function loadOptionalModule(candidatePaths, fallbackFactory, label) {
  for (const candidate of candidatePaths) {
    try {
      return require(candidate);
    } catch (err) {
      if (err.code !== 'MODULE_NOT_FOUND' || !String(err.message || '').includes(candidate.replace('./', '').replace('../', ''))) {
        console.warn(`[${label}] Failed to load ${candidate}:`, err.message);
        return fallbackFactory();
      }
    }
  }
  console.warn(`[${label}] Optional modules unavailable. Using degraded mode.`);
  return fallbackFactory();
}

