// MCPB-HARDEN-1a: validate body-supplied org_id/user_id belongs to the tenant
// before stamping audit envelopes. Service-key auth alone is not sufficient —
// any holder of INTERNAL_SERVICE_KEY could otherwise impersonate any user.
const _membershipCache = new Map(); // key = `${orgId}|${userId}` → { ok, expires }
const _MEMBERSHIP_TTL_MS = 60_000;
// STABILITY-AUDITS #6: this cache only ever .set(), and an expired read fell
// through to the network re-verify WITHOUT evicting the stale entry —
// every distinct (orgId, userId) pair this process ever verified stayed
// parked in memory forever. Same unbounded-growth shape trackToolExecution's
// _sessionToolTracker (below, server.js:22249-ish) already had and fixed:
// delete on expired-read, plus a size-bound sweep on write so growth is
// capped even under a distinct-pair pattern that never re-reads.
const _MEMBERSHIP_CACHE_SWEEP_THRESHOLD = 500;

// Returns 'member' | 'not_member' | 'unavailable'. The three states are
// deliberately distinct: only an authoritative 2xx/4xx answer from auth may
// assert anything about membership. A 429, timeout or network error is
// 'unavailable' — callers must fail closed with a retryable 503, never a 403.
// (2026-09-21: auth's rate limiter 429'd identity/verify and every agent tool
// call was refused as "not an active member" of an org the user belonged to.)
async function verifyOrgUserMembership(orgId, userId) {
  if (!orgId || !userId) return 'not_member';
  const cacheKey = `${orgId}|${userId}`;
  const cached = _membershipCache.get(cacheKey);
  if (cached) {
    if (cached.expires > Date.now()) return cached.ok ? 'member' : 'not_member';
    _membershipCache.delete(cacheKey); // expired — evict rather than leave it parked forever
  }

  const svcKey = process.env.INTERNAL_SERVICE_KEY || '';
  if (!svcKey) {
    console.error('[MCPB-HARDEN] INTERNAL_SERVICE_KEY not set — cannot verify membership');
    return 'unavailable';
  }
  try {
    const url = `${AUTH_SERVICE_URL}/api/internal/identity/verify?org_id=${encodeURIComponent(orgId)}&user_id=${encodeURIComponent(userId)}`;
    const resp = await fetch(url, {
      headers: { 'x-service-key': svcKey },
      signal: AbortSignal.timeout(3000),
    });
    if (resp.ok) {
      // Only cache positives; negatives stay un-cached so a fresh signup is picked up immediately
      _membershipCache.set(cacheKey, { ok: true, expires: Date.now() + _MEMBERSHIP_TTL_MS });
      // Bound growth — same shape as trackToolExecution's _sessionToolTracker sweep.
      if (_membershipCache.size > _MEMBERSHIP_CACHE_SWEEP_THRESHOLD) {
        const now = Date.now();
        for (const [key, val] of _membershipCache) {
          if (val.expires <= now) _membershipCache.delete(key);
        }
      }
      return 'member';
    }
    // 4xx = auth answered and said no; anything else (429/5xx) is not an answer
    if (resp.status >= 400 && resp.status < 500 && resp.status !== 429) return 'not_member';
    console.warn(`[MCPB-HARDEN] membership verify unavailable: auth returned ${resp.status}`);
    return 'unavailable';
  } catch (e) {
    console.warn('[MCPB-HARDEN] membership verify unavailable:', e.message);
    return 'unavailable';
  }
}

