// Credential caches (fetched from auth service via QuoxVault resolver), scoped per org
// getProviderKeys() delegates to lib/providerKeys.js (single implementation,
// shared with conversationRecall.js via configure() below) rather than
// keeping its own copy of the cache + legacy-fallback + merge orchestration.
const providerKeysLib = require('./lib/providerKeys');
const _claudeKeysCache = new Map();
const CLAUDE_KEYS_CACHE_TTL = 30 * 1000; // 30 seconds

const AUTH_BASE_URL = `http://${process.env.AUTH_HOST || 'auth'}:${process.env.AUTH_PORT || '3101'}`;

// COLLECTOR-ONCEOVER #181: circuit breaker for the vault-resolve call below.
// Under host load, the auth service's /internal/resolve can start timing out
// on every call; without a breaker each concurrent request stacks its own
// 5s-timeout fetch promise on the event loop, compounding the stall that
// makes the /health probe (and everything else) slow. After N consecutive
// failures we stop attempting the vault call for a cooldown window and go
// straight to the legacy fallback that callers already have.
const VAULT_BREAKER_FAILURE_THRESHOLD = 3;
const VAULT_BREAKER_COOLDOWN_MS = 30 * 1000;
let _vaultBreakerFailures = 0;
let _vaultBreakerOpenUntil = 0;

/**
 * Resolve credentials via QuoxVault waterfall: vault → instance_config → env
 * Falls back to legacy endpoints if the resolve endpoint is unavailable.
 */
async function resolveCredentials(orgId, providers, channels = []) {
  const now = Date.now();
  if (_vaultBreakerOpenUntil > now) {
    return null; // breaker open — skip the call, go straight to legacy fallback
  }
  try {
    const resp = await fetch(`${AUTH_BASE_URL}/api/setup/internal/resolve`, {
      method: 'POST',
      headers: buildInternalServiceHeaders({ 'Content-Type': 'application/json' }),
      body: JSON.stringify({ org_id: orgId || 'default', providers, channels }),
      signal: AbortSignal.timeout(5000)
    });
    if (resp.ok) {
      if (_vaultBreakerFailures > 0) {
        console.warn('[Vault] Resolve endpoint recovered — circuit breaker reset');
      }
      _vaultBreakerFailures = 0;
      return await resp.json();
    }
    console.warn('[Vault] Resolve endpoint returned', resp.status, '— falling back to legacy');
  } catch (err) {
    console.warn('[Vault] Resolve endpoint unavailable:', err.message, '— falling back to legacy');
  }
  _vaultBreakerFailures += 1;
  if (_vaultBreakerFailures >= VAULT_BREAKER_FAILURE_THRESHOLD) {
    _vaultBreakerOpenUntil = Date.now() + VAULT_BREAKER_COOLDOWN_MS;
    console.warn(`[Vault] Circuit breaker OPEN — ${_vaultBreakerFailures} consecutive failures, skipping vault resolve for ${VAULT_BREAKER_COOLDOWN_MS}ms`);
  }
  return null;
}

/**
 * Resolve a specific credential by vault ID.
 * VAULT-P6.D (closes P6-F1): org_id is now threaded through so the auth
 * side can verify the credential belongs to the caller's org before
 * releasing its decrypted fields — a bare credential_id is caller-controlled
 * (e.g. the chat request body) and must never be trusted alone.
 * Returns { provider, key, label } or null.
 */
async function resolveCredentialById(credentialId, orgId) {
  if (!credentialId) return null;
  try {
    const resp = await fetch(`${AUTH_BASE_URL}/api/setup/internal/resolve-by-id`, {
      method: 'POST',
      headers: buildInternalServiceHeaders({ 'Content-Type': 'application/json' }),
      body: JSON.stringify({ credential_id: credentialId, org_id: orgId || null }),
      signal: AbortSignal.timeout(5000)
    });
    if (resp.ok) return await resp.json();
    console.warn(`[Vault] resolve-by-id returned ${resp.status} for ${credentialId}`);
  } catch (err) {
    console.warn(`[Vault] resolve-by-id failed for ${credentialId}:`, err.message);
  }
  return null;
}

async function getClaudeKeys(orgId) {
  const now = Date.now();
  const cacheKey = orgId || 'default';
  const cached = _claudeKeysCache.get(cacheKey);
  if (cached && (now - cached.checkedAt) < CLAUDE_KEYS_CACHE_TTL) {
    return cached.value;
  }

  // Try QuoxVault resolver first
  const resolved = await resolveCredentials(orgId, ['claude', 'anthropic']);
  if (resolved?.providers) {
    const result = {};
    if (resolved.providers.claude?.claude_oauth_token) {
      result.claude_oauth_token = resolved.providers.claude.claude_oauth_token;
    }
    if (resolved.providers.claude?.anthropic_api_key) {
      result.anthropic_api_key = resolved.providers.claude.anthropic_api_key;
    } else if (resolved.providers.anthropic?.key) {
      result.anthropic_api_key = resolved.providers.anthropic.key;
    }
    // Only use vault result if it returned actual credentials — otherwise fall through to legacy
    if (result.claude_oauth_token || result.anthropic_api_key) {
      _claudeKeysCache.set(cacheKey, { value: result, checkedAt: now });
      return result;
    }
    console.warn('[Claude Keys] Vault resolver returned empty — falling through to legacy');
  }

  // Legacy fallback: direct endpoint
  // LLM-CHOICE 3.3: verified field mapping between the three auth endpoints
  // this function can hit, in case /internal/claude-keys is ever retired:
  //   /internal/claude-keys   -> { claude_oauth_token, anthropic_api_key }
  //   /internal/provider-keys -> { anthropic_api_key, openai_api_key,
  //                                 perplexity_api_key, gemini_api_key }
  //                              (NO oauth-token equivalent — provider-keys
  //                              has never carried the Claude subscription
  //                              OAuth token, only the API key)
  //   /internal/resolve (providers:['claude']) -> { providers: { claude: {
  //     claude_oauth_token, anthropic_api_key, source: { oauth, api_key } } } }
  //     — a superset of claude-keys (vault + org-aware), already tried above
  //     as the primary path.
  // Do NOT cut over the live path here — /internal/resolve above already
  // covers the common case. This is a defensive fallback so a future auth
  // deployment that drops /internal/claude-keys (404) doesn't silently zero
  // out the Anthropic API key; it degrades gracefully (oauth token still
  // absent — only claude-keys/resolve can supply that field) rather than
  // failing key fetch outright.
  try {
    const resp = await fetch(`${AUTH_BASE_URL}/api/setup/internal/claude-keys`, {
      headers: buildInternalServiceHeaders(),
      signal: AbortSignal.timeout(5000)
    });
    if (resp.ok) {
      const result = await resp.json();
      _claudeKeysCache.set(cacheKey, { value: result, checkedAt: now });
      return result;
    }
    if (resp.status === 404) {
      console.warn('[Claude Keys] /internal/claude-keys 404 — falling back to getProviderKeys (anthropic_api_key only; no OAuth token equivalent exists there)');
      const providerKeys = await getProviderKeys(orgId);
      if (providerKeys?.anthropic_api_key) {
        const result = { anthropic_api_key: providerKeys.anthropic_api_key };
        _claudeKeysCache.set(cacheKey, { value: result, checkedAt: now });
        return result;
      }
    }
  } catch (err) {
    console.error('[Claude Keys] Legacy fallback failed:', err.message);
  }
  return cached?.value || {};
}

// Thin delegate to lib/providerKeys.js — the single implementation of the
// cache + legacy-fallback + merge orchestration. resolveCredentials (with
// its circuit breaker) stays defined here and is passed in as a dependency,
// so the vault-fetch logic is never duplicated between this file and the
// lib. Cache semantics, TTL, warn/error lines, the cached-value fallback,
// and vault-wins merge precedence are all unchanged — they now live in
// lib/providerKeys.js, called with this file's real deps.
async function getProviderKeys(orgId) {
  return providerKeysLib.getProviderKeys(orgId, {
    resolveCredentials,
    fetchImpl: fetch,
    buildInternalServiceHeaders,
    authBaseUrl: AUTH_BASE_URL,
  });
}

function resolveRequestOrgId(req) {
  // SECURITY (AEE-ORG-1 tenant isolation, audit 2026-08-17). A JWT/MCP user is
  // LOCKED to their verified token's org. The pre-route default-deny gate
  // (utils/collectorAuthGate.js) populates req.user/req.service for EVERY
  // authenticated request, so this holds on every route regardless of its own
  // middleware. Honoring a client-supplied ?org_id / x-org-id / body org_id
  // for a logged-in user was a cross-tenant bypass: any user could set a
  // header and act on another org's slots, dev-sessions, quoxplan approvals,
  // etc. Tokens are single-org and `org switch` re-mints (auth.js), so a JWT
  // caller never legitimately names a different org. Only a trusted
  // service-key caller (req.service) may name an org explicitly.
  if (req.user?.org_id) return req.user.org_id;

  const explicitOrgId = req.query?.org_id || req.headers['x-org-id'] || req.body?.org_id;
  if (req.service && explicitOrgId) return explicitOrgId;

  // No middleware-populated identity (e.g. an unauthenticated request in the
  // gate's shadow mode). Verify a token/cookie directly for defense in depth,
  // then fall back to 'default' (which the gate 401s under enforce anyway).
  let token = null;
  const authHeader = req.headers.authorization;
  if (authHeader && authHeader.startsWith('Bearer ')) {
    token = authHeader.slice(7);
  }

  if (!token) {
    const cookies = req.cookies || parseCookieHeader(req.headers.cookie);
    if (cookies.access_token) {
      token = cookies.access_token;
    }
  }

  if (token) {
    const result = verifyToken(token);
    if (result.valid && result.payload?.org_id) {
      return result.payload.org_id;
    }
  }

  return 'default';
}

// DEVSUITE-SLOTS tenant isolation (AEE-ORG-1 pattern, mirrors the compliance
// posture route ~L15451). Unlike resolveRequestOrgId, a JWT/MCP user is LOCKED
// to their verified token's org; a client-supplied ?org_id / x-org-id / body
// org_id is IGNORED for them, closing the cross-tenant header-override hole
// (any logged-in user could otherwise read/checkout/say another org's slots
// and inject into its Matrix room). Only a trusted service-key caller
// (req.service, e.g. the tasks service or the appservice steer) may name an
// org explicitly. Returns null when a service caller names none — the inbound
// steer path then resolves the slot by globally-unique name. The audit that
// found this (2026-08-17) also flagged resolveRequestOrgId itself as a
// platform-wide P0 shared by dev-sessions/dev-servers; that is tracked
// separately, this guard fixes the slot surface which additionally writes to
// Matrix and the owner bridge.
function resolveSlotOrgId(req) {
  if (req.user?.org_id) return req.user.org_id;
  if (req.service) return req.query?.org_id || req.body?.org_id || req.headers['x-org-id'] || null;
  return null;
}

function defaultModelForProvider(provider) {
  if (provider === 'openai') return 'gpt-5.4';
  if (provider === 'perplexity') return 'llama-3.1-sonar-large-128k-online';
  if (provider === 'gemini') return 'gemini-2.5-flash';
  if (provider === 'local') return 'default';
  return 'claude-sonnet-4-5-20250929';
}

function inferProviderFromModel(model) {
  if (!model || typeof model !== 'string') return null;
  if (model.startsWith('gpt-') || model.startsWith('o1') || model.startsWith('o3') || model.startsWith('o4')) return 'openai';
  if (model.startsWith('claude-')) return 'anthropic';
  if (model.startsWith('gemini-')) return 'gemini';
  if (model.includes('sonar')) return 'perplexity';
  return null;
}

function resolveRequestedLlm({ requestedProvider, requestedModel, vaultCredential }) {
  const credentialProvider = vaultCredential?.provider || null;
  const effectiveProvider = credentialProvider || requestedProvider || inferProviderFromModel(requestedModel) || 'anthropic';
  const requestedModelProvider = inferProviderFromModel(requestedModel);
  const effectiveModel = requestedModel && (!credentialProvider || !requestedModelProvider || requestedModelProvider === effectiveProvider)
    ? requestedModel
    : defaultModelForProvider(effectiveProvider);

  return {
    provider: effectiveProvider,
    model: effectiveModel,
    credentialOverride: !!credentialProvider,
    credentialProvider
  };
}

function buildExecutionMeta({
  body,
  effectiveProvider,
  effectiveModel,
  requestedProvider,
  requestedModel,
  requestedCredentialId,
  vaultCredential,
  effectiveLlm,
  executionPlan = null,
  policyPayload = null
}) {
  const source = executionPlan?.source || (
    requestedCredentialId
      ? 'vault_credential_selection'
      : (requestedProvider || requestedModel)
        ? 'toolbar_selection'
        : 'agent_default'
  );

  return {
    provider: body?.provider || effectiveProvider || null,
    model: body?.model || effectiveModel || null,
    source,
    capability: executionPlan?.capability || null,
    capability_label: executionPlan?.capabilityLabel || null,
    policy_label: executionPlan?.policyLabel || null,
    policy_source: policyPayload?.source || null,
    credential_id: requestedCredentialId || null,
    credential_label: vaultCredential?.label || null,
    credential_provider: vaultCredential?.provider || null,
    provider_overridden_by_credential: !!(effectiveLlm?.credentialOverride && requestedProvider && requestedProvider !== effectiveProvider),
    model_overridden_by_credential: !!(effectiveLlm?.credentialOverride && requestedModel && requestedModel !== effectiveModel),
    fallback_chain: executionPlan?.fallbackChain || [],
    reasons: executionPlan?.reasons || [],
    coercions: executionPlan?.coercions || {}
  };
}

// Sanitize error messages before returning to users
// NEVER expose CLI commands, system prompts, internal paths, or tokens
function sanitizeErrorForUser(errorMsg) {
  if (!errorMsg) return 'An unknown error occurred.';
  // Claude CLI errors — generic message
  if (errorMsg.includes('--system-prompt') || errorMsg.includes('--dangerously-skip-permissions') || errorMsg.includes('claude --output-format')) {
    return 'Claude request failed. Please check your authentication in Settings \u2192 Core Integrations.';
  }
  // Internal paths, stack traces, module errors — hide from users
  if (errorMsg.includes('/home/') || errorMsg.includes('/app/') || errorMsg.includes('/opt/') ||
      errorMsg.includes('execFile') || errorMsg.includes('execSync') || errorMsg.includes('node_modules') ||
      errorMsg.includes('SQLITE_') || errorMsg.includes('ENOENT') || errorMsg.includes('at Object.') ||
      errorMsg.includes('Cannot find module')) {
    return 'An internal error occurred. Please try again.';
  }
  return errorMsg
    .replace(/sk-ant-[a-zA-Z0-9_-]+/g, '[REDACTED]')
    .replace(/sk-[a-zA-Z0-9_-]{20,}/g, '[REDACTED]')
    .replace(/CLAUDE_CODE_OAUTH_TOKEN=[^\s]+/g, '[REDACTED]')
    .replace(/Bearer\s+[a-zA-Z0-9_-]+/g, 'Bearer [REDACTED]')
    .replace(/\/home\/[^\s:]+/g, '[path]')
    .replace(/\/opt\/[^\s:]+/g, '[path]')
    .replace(/\/var\/[^\s:]+/g, '[path]')
    .substring(0, 200);
}

// CORS configuration - validate origin against allowlist (security fix for issue #48)
const ALLOWED_ORIGINS = parseAllowedOrigins(process.env);
const COLLECTOR_DASHBOARD_PORTS = parseDashboardPorts(process.env);

function getSecureCorsOrigin(req) {
  const origin = req.headers.origin;
  if (origin && isCollectorAllowedOrigin(origin, {
    allowedOrigins: ALLOWED_ORIGINS,
    dashboardPorts: COLLECTOR_DASHBOARD_PORTS,
  })) {
    return origin;
  }
  return null; // Don't set header if origin not in allowlist
}

// UUID validation regex - Claude CLI requires valid UUIDs for --resume
const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
function isValidUUID(str) {
  return str && UUID_REGEX.test(str);
}

/**
 * Escape SQL LIKE wildcard characters - Issue 1.11 fix
 * Prevents LIKE injection by escaping %, _, and \ characters
 * @param {string} str - String to escape
 * @returns {string} - Escaped string safe for LIKE queries
 */
function escapeLike(str) {
  if (!str) return str;
  return str.replace(/[%_\\]/g, '\\$&');
}

