// Backend config — starts from env vars but refreshes from vault on first request
let _backendConfigResolved = false;
const BACKEND_CONFIG = {
  // Perplexity for research/web queries
  perplexity: {
    url: 'https://api.perplexity.ai/chat/completions',
    apiKey: process.env.PERPLEXITY_API_KEY,
    model: 'llama-3.1-sonar-large-128k-online', // Web-connected model
    enabled: !!process.env.PERPLEXITY_API_KEY
  },
  // OpenAI for code-focused queries
  openai: {
    url: 'https://api.openai.com/v1/chat/completions',
    apiKey: process.env.OPENAI_API_KEY,
    model: 'gpt-5.4',
    enabled: !!process.env.OPENAI_API_KEY && process.env.OPENAI_API_KEY !== 'PLACEHOLDER_ROTATE_THIS_KEY'
  },
  // Claude (default) — routed via Claude CLI/MCP
  claude: {
    enabled: true
  }
};

/**
 * Refresh BACKEND_CONFIG from vault-resolved keys on first request.
 * Keeps env vars as last-resort fallback.
 */
async function ensureBackendConfig(orgId) {
  if (_backendConfigResolved) return;
  try {
    const keys = await getProviderKeys(orgId);
    if (keys.perplexity_api_key) {
      BACKEND_CONFIG.perplexity.apiKey = keys.perplexity_api_key;
      BACKEND_CONFIG.perplexity.enabled = true;
    }
    if (keys.openai_api_key && keys.openai_api_key !== 'PLACEHOLDER_ROTATE_THIS_KEY') {
      BACKEND_CONFIG.openai.apiKey = keys.openai_api_key;
      BACKEND_CONFIG.openai.enabled = true;
    }
    _backendConfigResolved = true;
  } catch {
    // Env var fallback remains active
  }
}

// Provider routing is now dynamic — each agent's llm.provider config is sent by the
// frontend as `provider` in the request body. See assistants.js llm field and
// ModelSelector component. Backend routes via requestedProvider (line ~4119).

/**
 * Verify user consent before calling third-party AI provider
 * Security Issue #72: Data must not be sent without explicit consent
 * @param {string} userId - User ID making the request
 * @param {string} provider - AI provider name
 * @returns {Promise<{consented: boolean, reason?: string}>}
 */
async function verifyAIConsent(userId, provider, options = {}) {
  // Check if this provider requires consent
  if (!requiresThirdPartyConsent(provider)) {
    return { consented: true, reason: 'provider_does_not_require_consent' };
  }

  // Call auth service to verify consent
  const authServiceUrl = process.env.AUTH_SERVICE_URL || 'http://auth:3101';
  const verificationRequest = buildConsentVerificationRequest({
    authServiceUrl,
    userId,
    orgId: options.orgId || null,
    provider,
    endpoint: options.endpoint || 'chat',
    accessToken: options.accessToken || '',
    serviceKey: options.serviceKey || process.env.INTERNAL_SERVICE_KEY || '',
  });

  if (!verificationRequest.url) {
    console.warn(`[Consent] Verification unavailable for ${provider}: no auth metadata available (${verificationRequest.authMode})`);
    return { consented: false, reason: 'verification_credentials_unavailable' };
  }

  try {
    const response = await fetchWithTimeout(verificationRequest.url, {
      method: 'POST',
      headers: verificationRequest.headers,
      body: JSON.stringify(verificationRequest.body)
    }, 10000); // 10 second timeout for internal service

    if (!response.ok) {
      console.warn(`[Consent] Verification request failed for ${provider} via ${verificationRequest.authMode} (${response.status})`);
      return { consented: false, reason: 'verification_failed' };
    }

    const data = await response.json();
    return {
      consented: data.consented,
      reason: data.blocked_reason || (data.consented ? 'consent_granted' : 'no_consent')
    };
  } catch (err) {
    console.error('[Consent] Verification error:', err.message);
    return { consented: false, reason: 'verification_unavailable' };
  }
}

function buildConsentDeniedResponse({ provider, reason, agentUsed }) {
  const normalizedProvider = String(provider || '').toLowerCase();
  const providerLabel = normalizedProvider ? normalizedProvider[0].toUpperCase() + normalizedProvider.slice(1) : 'AI';

  if (reason === 'verification_unavailable') {
    return {
      success: false,
      result: 'Consent verification is temporarily unavailable. Please try again shortly.',
      error: 'consent_required',
      hint: 'The privacy verification service could not be reached. Retry in a moment or check auth service health.',
      agent_used: agentUsed,
      can_continue: false,
    };
  }

  if (reason === 'verification_credentials_unavailable') {
    return {
      success: false,
      result: 'Consent could not be verified for this session. Refresh and sign in again if the problem persists.',
      error: 'consent_required',
      hint: 'Your session context was missing for consent verification. Refresh the app or sign in again before retrying.',
      agent_used: agentUsed,
      can_continue: false,
    };
  }

  return {
    success: false,
    result: `AI data sharing consent required (${reason}). Enable in Settings > Privacy.`,
    error: 'consent_required',
    hint: `Open [Settings > Privacy](/settings#privacy) and enable AI data sharing to use ${providerLabel}-backed chat.`,
    settings_path: '/settings#privacy',
    agent_used: agentUsed,
    can_continue: false,
  };
}

/**
 * Call Perplexity API directly
 * Security Issue #72: Requires user consent
 */
async function callPerplexity(prompt, systemPrompt = '', userId = null) {
  const config = BACKEND_CONFIG.perplexity;
  if (!config.enabled) {
    throw new Error('Perplexity API not configured - set PERPLEXITY_API_KEY');
  }

  // Security Issue #72: Verify consent before sending data
  if (userId) {
    const consent = await verifyAIConsent(userId, 'perplexity');
    if (!consent.consented) {
      throw new Error(`AI data sharing consent required (${consent.reason}). Please enable consent in Settings > Privacy.`);
    }
  }

  const response = await fetchWithTimeout(config.url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.apiKey}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      model: config.model,
      messages: [
        { role: 'system', content: systemPrompt || 'You are Scholar, a research specialist. Provide accurate, well-sourced information.' },
        { role: 'user', content: prompt }
      ]
    })
  }, 60000); // 60 second timeout for AI APIs

  if (!response.ok) {
    const error = await response.text();
    throw new Error(`Perplexity API error: ${response.status} - ${error}`);
  }

  const data = await response.json();
  return {
    result: data.choices?.[0]?.message?.content || '',
    backend: 'perplexity',
    model: config.model,
    citations: data.citations || []
  };
}

/**
 * Call OpenAI API directly
 * Security Issue #72: Requires user consent
 */
async function callOpenAI(prompt, systemPrompt = '', userId = null) {
  const config = BACKEND_CONFIG.openai;
  if (!config.enabled) {
    throw new Error('OpenAI API not configured - set OPENAI_API_KEY');
  }

  // Security Issue #72: Verify consent before sending data
  if (userId) {
    const consent = await verifyAIConsent(userId, 'openai');
    if (!consent.consented) {
      throw new Error(`AI data sharing consent required (${consent.reason}). Please enable consent in Settings > Privacy.`);
    }
  }

  const response = await fetchWithTimeout(config.url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.apiKey}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(buildOpenAIChatCompletionBody({
      model: config.model,
      systemPrompt: systemPrompt || 'You are Vulcan, a code specialist. Provide clean, efficient code solutions.',
      userMessage: prompt,
      maxTokens: 4096,
    }))
  }, 60000); // 60 second timeout for AI APIs

  if (!response.ok) {
    const error = await response.text();
    throw new Error(`OpenAI API error: ${response.status} - ${error}`);
  }

  const data = await response.json();
  return {
    result: data.choices?.[0]?.message?.content || '',
    backend: 'openai',
    model: config.model,
    usage: data.usage
  };
}

/**
 * Get backend status for logging
 */
function getBackendStatus() {
  return {
    perplexity: BACKEND_CONFIG.perplexity.enabled,
    openai: BACKEND_CONFIG.openai.enabled,
    claude: BACKEND_CONFIG.claude.enabled
  };
}

console.log('[Backends]', getBackendStatus());

// ============================================================================
// MULTI-PROVIDER CHAT HANDLERS
// Full chat handlers that return normalized responses for the collector chat endpoint
// ============================================================================

// flattenOpenAIMessageContent + buildOpenAIStyleConversationMessages now live
// in lib/openaiRequest.js (imported above) so the governed stack-mode failover
// path can reach them too — see attemptOpenAiInvoke.

function buildGeminiConversationContents(userMessage, conversation_history) {
  const contents = [];
  if (Array.isArray(conversation_history) && conversation_history.length > 0) {
    for (const turn of conversation_history) {
      if (!turn || (turn.role !== 'user' && turn.role !== 'assistant')) continue;
      const text = flattenOpenAIMessageContent(turn.content);
      if (!text) continue;
      contents.push({
        role: turn.role === 'assistant' ? 'model' : 'user',
        parts: [{ text }],
      });
    }
  }
  contents.push({ role: 'user', parts: [{ text: userMessage }] });
  return contents;
}

// LLM-CHOICE OpenAI tool parity: serializeToolResultForModel and
// executeOpenAICompatibleToolLoop moved to lib/openaiInvokeDispatcher.js
// (pure extraction, deps injected) so the governed stack-mode failover leg
// (attemptOpenAiInvoke below) can call the exact same proven loop that
// already powers handleOpenAIChat / handleLocalInferenceChat instead of a
// second implementation. A function (not a top-level const) — voltEmitter
// is declared later in this file, so an eager object literal here would hit
// the temporal dead zone at module load; resolving the refs lazily at call
// time (same timing the original in-file function body used) avoids that.
function openaiToolLoopDeps() {
  return {
    fetchFn: fetchWithTimeout,
    executeTool,
    voltEmitter,
    storeAuditEnvelope,
    emitToolEvidence,
  };
}

async function handleOpenAIChat(req, res, opts) {
  const {
    apiKey,
    model,
    systemPrompt,
    userMessage,
    session_id: requestedSessionId,
    selected_agent,
    userId,
    orgId,
    userAccessToken,
    agentTools = [],
    memory_context,
    quox_context,
    conversation_history,
    hatManifest, // QUOXHAT P2
    effectiveSessionId, // QUOXHAT P4
  } = opts;
  // BRAIN2-BRUTALOOP: mint the id BEFORE the tool loop. A first CLI turn sends
  // none, so the recall tool registered its retrieval and finalizeAnswer ran
  // under an empty key, and only the response got 'openai-<ts>': the citation
  // record for that id was always "not_searched". One id for all three now
  // (the route's effectiveSessionId when it minted one, which the tools use).
  const session_id = requestedSessionId || effectiveSessionId || 'openai-' + Date.now();

  if (userId) {
    const consent = await verifyAIConsent(userId, 'openai', {
      orgId,
      accessToken: userAccessToken,
      endpoint: 'chat',
    });
    if (!consent.consented) {
      storeAuditEnvelope({ type: 'error', from: `human.${userId}`, to: 'audit.system', intent: 'quox.consent.denied', corr: session_id || `DENIED_${Date.now()}`, payload: { provider: 'openai', reason: consent.reason, agent: selected_agent, user_id: userId } });
      return res.json(buildConsentDeniedResponse({
        provider: 'openai',
        reason: consent.reason,
        agentUsed: selected_agent,
      }));
    }
  }

  console.log(`[OpenAI] Chat request: model=${model}, agent=${selected_agent}`);

  // CRP-AU-4: Start VOLT run for OpenAI path
  const voltRunId = voltEmitter.startRun(session_id || `OPENAI_${Date.now()}`, {
    org_id: orgId, user_id: userId, agent_id: selected_agent, path: 'openai'
  });

  let loopResult;
  // Research turns (capability research): use the Responses API built-in web
  // search first; research needs no Quox tools. On failure fall through to the
  // tool loop with the honest "not available" line.
  let effectiveUserMessage = userMessage;
  if (opts.nativeWebSearch) {
    const rs = await require('./lib/openaiResponsesSearch.js').invokeOpenAiResponsesSearch({
      apiKey, model, systemPrompt, userMessage, conversation_history,
    });
    if (rs.ok) {
      loopResult = { content: rs.text, toolsUsed: rs.toolsUsed || [] };
    } else {
      console.warn(`[OpenAI-Responses] research turn fell back to chat completions (agent=${selected_agent})`);
      effectiveUserMessage = require('./lib/nativeWebSearch.js').withNoWebSearchNote(userMessage, true);
    }
  }
  // QUOXON-ENGINE class 2: the turn's tool results, for the grounding contract below.
  const openaiGroundingEv = require('./lib/groundingContract.js').createEvidenceCollector();
  if (!loopResult) try {
    loopResult = await executeOpenAICompatibleToolLoop(req, {
      onEvent: openaiGroundingEv.onEvent,
      apiUrl: 'https://api.openai.com/v1/chat/completions',
      headers: { 'Authorization': `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
      model,
      systemPrompt,
      userMessage: effectiveUserMessage,
      selected_agent,
      session_id,
      agentTools,
      providerLabel: 'OpenAI',
      userId,
      orgId,
      userAccessToken,
      memory_context,
      quox_context,
      conversation_history,
      voltRunId,
      hatManifest, // QUOXHAT P2
      effectiveSessionId, // QUOXHAT P4
    }, openaiToolLoopDeps());
  } catch (err) {
    voltEmitter.failRun(voltRunId, err);
    console.error(`[OpenAI] API error ${err.status || 'unknown'}:`, (err.body || err.message || '').substring(0, 200));
    if (err.status === 401 || err.status === 403) {
      const authHint = 'API key authentication failed. Check your OpenAI API Key in Settings → Core Integrations.';
      return res.json({
        success: false,
        result: authHint,
        voice_summary: 'Authentication failed.',
        error: 'auth_required',
        hint: authHint,
        settings_path: '/settings',
        agent_used: selected_agent,
        can_continue: false
      });
    }
    throw err;
  }

  // QUOXON-ENGINE classes 2 + 5: the grounding contract on the non-stream path too.
  const openaiGrounding = require('./lib/groundingContract.js').applyGroundingContract({ stripFakeActivity: true,
    answer: loopResult.content || '',
    evidence: [openaiGroundingEv.text(), userMessage, quox_context || '', memory_context || ''].join('\n'),
    toolResults: openaiGroundingEv.items(), userMessage, evidenceAvailable: !opts.nativeWebSearch || loopResult.toolsUsed.length > 0,
    tag: `path=openai-nonstream agent=${selected_agent}`,
  });
  const content = openaiGrounding.text;
  const toolSuffix = loopResult.toolsUsed.length > 0 ? `\n\n---\n*Tools used: ${loopResult.toolsUsed.join(', ')}*` : '';
  const voiceSummary = extractVoiceSummary(content);

  voltEmitter.completeRun(voltRunId);
  storeAuditEnvelope({
    type: 'event', from: `agent.${selected_agent}`, to: 'audit.system',
    intent: 'quox.chat.success', corr: session_id || `CHAT_${Date.now()}`,
    payload: { agent: selected_agent, path: 'openai', model, response_length: content.length, tools_used: loopResult.toolsUsed, ...(openaiGrounding.flagged ? { grounding_flags: openaiGrounding.flags } : {}) }
  });

  return res.json({
    success: true, result: content + toolSuffix, voice_summary: voiceSummary,
    session_id: session_id || 'openai-' + Date.now(),
    model, provider: 'openai', agent_used: selected_agent,
    tools_used: loopResult.toolsUsed, ...(Array.isArray(loopResult.toolOutcomes)&&loopResult.toolOutcomes.length?{tool_outcomes:loopResult.toolOutcomes}:{}), can_continue: true
  });
}

async function handlePerplexityChat(req, res, opts) {
  const { apiKey, model, systemPrompt, userMessage, session_id, selected_agent, userId, orgId, userAccessToken, conversation_history } = opts;

  if (userId) {
    const consent = await verifyAIConsent(userId, 'perplexity', {
      orgId,
      accessToken: userAccessToken,
      endpoint: 'chat',
    });
    if (!consent.consented) {
      storeAuditEnvelope({ type: 'error', from: `human.${userId}`, to: 'audit.system', intent: 'quox.consent.denied', corr: session_id || `DENIED_${Date.now()}`, payload: { provider: 'perplexity', reason: consent.reason, agent: selected_agent, user_id: userId } });
      return res.json(buildConsentDeniedResponse({
        provider: 'perplexity',
        reason: consent.reason,
        agentUsed: selected_agent,
      }));
    }
  }

  console.log(`[Perplexity] Chat request: model=${model}, agent=${selected_agent}`);

  // CRP-AU-4: Start VOLT run for Perplexity path
  const voltRunId = voltEmitter.startRun(session_id || `PPLX_${Date.now()}`, {
    org_id: orgId, user_id: userId, agent_id: selected_agent, path: 'perplexity'
  });
  voltEmitter.emit(voltRunId, 'model.requested', {
    actor: { actor_type: 'system', actor_id: 'collector' }, model, provider: 'perplexity'
  });

  const response = await fetchWithTimeout('https://api.perplexity.ai/chat/completions', {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model,
      messages: buildOpenAIStyleConversationMessages(systemPrompt, userMessage, conversation_history)
    })
  }, 120000);

  if (!response.ok) {
    const errText = await response.text();
    console.error(`[Perplexity] API error ${response.status}:`, errText.substring(0, 200));
    voltEmitter.failRun(voltRunId, new Error(`API ${response.status}`));
    throw new Error(`Perplexity API returned ${response.status}: ${errText.substring(0, 200)}`);
  }

  const data = await response.json();
  const content = data.choices?.[0]?.message?.content || '';
  const voiceSummary = extractVoiceSummary(content);

  voltEmitter.emit(voltRunId, 'model.responded', {
    actor: { actor_type: 'agent', actor_id: selected_agent }, model, provider: 'perplexity',
    input_tokens: data.usage?.prompt_tokens, output_tokens: data.usage?.completion_tokens,
  });
  voltEmitter.completeRun(voltRunId);
  storeAuditEnvelope({
    type: 'event', from: `agent.${selected_agent}`, to: 'audit.system',
    intent: 'quox.chat.success', corr: session_id || `CHAT_${Date.now()}`,
    payload: { agent: selected_agent, path: 'perplexity', model, response_length: content.length }
  });

  return res.json({
    success: true, result: content, voice_summary: voiceSummary,
    session_id: session_id || 'perplexity-' + Date.now(),
    model, provider: 'perplexity', agent_used: selected_agent,
    tools_used: [], can_continue: true,
    citations: data.citations || []
  });
}

/**
 * Infer aspect ratio from user's natural language message.
 * Maps common intent phrases to Gemini API aspect ratios.
 * Returns null if no clear intent is detected (Gemini defaults to square).
 */
function inferAspectRatio(text) {
  if (!text) return null;
  const lower = text.toLowerCase();

  // Explicit ratio mentioned (e.g. "16:9", "9:16")
  const explicitMatch = lower.match(/\b(\d{1,2}:\d{1,2})\b/);
  if (explicitMatch) {
    const valid = ['1:1','2:3','3:2','3:4','4:3','4:5','5:4','9:16','16:9','21:9','1:4','1:8','4:1','8:1'];
    if (valid.includes(explicitMatch[1])) return explicitMatch[1];
  }

  // Intent-based mapping — order: most specific first
  const patterns = [
    { regex: /\b(ultra.?wide|cinematic|film|movie)\b/, ratio: '21:9' },
    { regex: /\b(hero|banner|header|landscape|wide|desktop|blog.*hero|hero.*image|cover)\b/, ratio: '16:9' },
    { regex: /\b(portrait|vertical|mobile|story|stories|tall|phone)\b/, ratio: '9:16' },
    { regex: /\b(photo|photograph|standard)\b/, ratio: '3:2' },
    { regex: /\b(poster|pin|pinterest)\b/, ratio: '2:3' },
    { regex: /\b(square|avatar|icon|profile|social|instagram)\b/, ratio: '1:1' },
  ];

  for (const { regex, ratio } of patterns) {
    if (regex.test(lower)) return ratio;
  }

  return null;
}

async function handleGeminiChat(req, res, opts) {
  const { apiKey, model, systemPrompt, userMessage, session_id, effectiveSessionId, selected_agent, userId, orgId, userIdFromJwt, conversation_history, agentTools = [], hatManifest, userAccessToken, memory_context, quox_context } = opts;

  // Consent: user explicitly selected Gemini provider — that IS their consent.
  // The /verify endpoint requires CSRF+auth that internal calls can't provide.

  // Image-capable: model name contains 'image' OR agent is an image-generation specialist.
  // This ensures image output even when the user manually selects a non-image model
  // (e.g. gemini-2.5-pro) while talking to an image agent like ImagesQ.
  const IMAGE_AGENTS = ['imagesq'];
  const isImageModel = model.includes('image') || IMAGE_AGENTS.includes(selected_agent);
  console.log(`[Gemini] Chat request: model=${model}, agent=${selected_agent}, imageMode=${isImageModel}`);

  // CRP-AU-4: Start VOLT run for Gemini path
  const voltRunId = voltEmitter.startRun(session_id || `GEMINI_${Date.now()}`, {
    org_id: orgId, user_id: userId || userIdFromJwt, agent_id: selected_agent, path: 'gemini'
  });

  const generationConfig = { maxOutputTokens: 4096 };
  if (isImageModel) {
    generationConfig.responseModalities = ['TEXT', 'IMAGE'];

    // Extract aspect ratio from user message or request body.
    // The Gemini direct path has no tool_use — we must infer from text.
    const requestedRatio = req.body?.aspect_ratio || null;
    const inferredRatio = requestedRatio || inferAspectRatio(userMessage);
    if (inferredRatio) {
      generationConfig.imageConfig = { aspectRatio: inferredRatio };
      console.log(`[Gemini] Using aspect ratio: ${inferredRatio} (${requestedRatio ? 'explicit' : 'inferred'})`);
    }
  }

  // QUOXHAT P3: governed function-call loop for the ordinary (non-image)
  // Gemini path. Before this, the Gemini leg sent NO function declarations —
  // agents on Gemini could not call a single tool. The loop mirrors the
  // OpenAI-compatible one (same deps, same executeTool choke with the P2
  // hat gate, same round bound). Image mode keeps the single-shot request:
  // responseModalities + tools is a separately-certified combination.
  if (!isImageModel && Array.isArray(agentTools) && agentTools.length > 0) {
    try {
      const { executeGeminiToolLoop } = require('./lib/geminiInvokeDispatcher');
      const loopResult = await executeGeminiToolLoop(req, {
        apiKey,
        model,
        systemPrompt,
        userMessage,
        selected_agent,
        session_id,
        agentTools,
        userId,
        orgId,
        userAccessToken,
        memory_context,
        quox_context,
        conversation_history,
        voltRunId,
        hatManifest,
        effectiveSessionId, // QUOXHAT P4
        generationConfig,
        buildContents: buildGeminiConversationContents,
      }, openaiToolLoopDeps());
      const loopContent = loopResult.content || '';
      voltEmitter.emit(voltRunId, 'model.responded', {
        actor: { actor_type: 'agent', actor_id: selected_agent }, model, provider: 'gemini',
        response_length: loopContent.length, tools_used: loopResult.toolsUsed.length
      });
      voltEmitter.completeRun(voltRunId);
      storeAuditEnvelope({
        type: 'event', from: `agent.${selected_agent}`, to: 'audit.system',
        intent: 'quox.chat.success', corr: session_id || `CHAT_${Date.now()}`,
        payload: { agent: selected_agent, path: 'gemini', model, response_length: loopContent.length, tools_used: loopResult.toolsUsed }
      });
      return res.json({
        success: true, result: loopContent,
        voice_summary: extractVoiceSummary(loopContent),
        session_id: session_id || 'gemini-' + Date.now(),
        model, provider: 'gemini', agent_used: selected_agent,
        tools_used: loopResult.toolsUsed, ...(Array.isArray(loopResult.toolOutcomes)&&loopResult.toolOutcomes.length?{tool_outcomes:loopResult.toolOutcomes}:{}), can_continue: true
      });
    } catch (err) {
      voltEmitter.failRun(voltRunId, err);
      console.error(`[Gemini] tool loop error ${err.status || 'unknown'}:`, (err.body || err.message || '').substring(0, 200));
      throw err;
    }
  }

  voltEmitter.emit(voltRunId, 'model.requested', {
    actor: { actor_type: 'system', actor_id: 'collector' }, model, provider: 'gemini', imageMode: isImageModel
  });
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`;
  const response = await fetchWithTimeout(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      system_instruction: { parts: [{ text: systemPrompt }] },
      contents: buildGeminiConversationContents(userMessage, conversation_history),
      generationConfig
    })
  }, 120000);

  if (!response.ok) {
    const errText = await response.text();
    console.error(`[Gemini] API error ${response.status}:`, errText.substring(0, 200));
    voltEmitter.failRun(voltRunId, new Error(`API ${response.status}`));
    throw new Error(`Gemini API returned ${response.status}: ${errText.substring(0, 200)}`);
  }

  const data = await response.json();

  // Extract text and images from response parts
  let content = '';
  const rawImages = [];
  for (const candidate of data.candidates || []) {
    for (const part of candidate.content?.parts || []) {
      if (part.text) content += part.text;
      if (part.inlineData?.data) {
        rawImages.push({
          base64: part.inlineData.data,
          mime_type: part.inlineData.mimeType || 'image/png'
        });
      }
    }
  }

  // Save images to image store so they get persistent URLs
  const savedImages = [];
  for (const img of rawImages) {
    try {
      const saved = imageStore.saveImage(img.base64, img.mime_type, {
        prompt: userMessage,
        model,
        agent: selected_agent,
        org_id: orgId || null,
        user_id: userIdFromJwt || userId || null,
        aspect_ratio: generationConfig.aspectRatio || null,
      });
      savedImages.push({
        id: saved.id,
        url: saved.url,
        mime_type: img.mime_type,
        prompt: saved.sidecar.prompt,
        model: saved.sidecar.model,
        agent: selected_agent,
        created_at: saved.sidecar.created_at,
      });
      console.log(`[Gemini] Saved image: ${saved.id}`);
    } catch (err) {
      console.error('[Gemini] Failed to save image:', err.message);
    }
  }

  const voiceSummary = extractVoiceSummary(content);

  voltEmitter.emit(voltRunId, 'model.responded', {
    actor: { actor_type: 'agent', actor_id: selected_agent }, model, provider: 'gemini',
    response_length: content.length, images_generated: savedImages.length
  });
  voltEmitter.completeRun(voltRunId);
  storeAuditEnvelope({
    type: 'event', from: `agent.${selected_agent}`, to: 'audit.system',
    intent: 'quox.chat.success', corr: session_id || `CHAT_${Date.now()}`,
    payload: { agent: selected_agent, path: 'gemini', model, response_length: content.length, images_generated: savedImages.length }
  });

  const result = {
    success: true, result: content || (savedImages.length > 0 ? 'Image generated.' : ''),
    voice_summary: voiceSummary,
    session_id: session_id || 'gemini-' + Date.now(),
    model, provider: 'gemini', agent_used: selected_agent,
    tools_used: [], can_continue: true
  };

  if (savedImages.length > 0) {
    result.images = savedImages;
  }

  return res.json(result);
}

// ============================================================================
// Local Inference Handler (PATH 3)
// Connects to user-configured Ollama / vLLM / llama.cpp / NVIDIA NIM servers
// via OpenAI-compatible /v1/chat/completions endpoint.
// ============================================================================

// SEC-LOCAL-INF-ORG: org-scoped store (loaded from SQLite or request) — see
// lib/localInferenceSourcesStore.js header for why this is no longer a bare
// process-global Map with no org field.
const { createLocalInferenceSourcesStore } = require('./lib/localInferenceSourcesStore.js');
const localInferenceSourcesStore = createLocalInferenceSourcesStore();

/**
 * Resolve a local inference source configuration.
 * Sources can come from the request body or be pre-registered.
 *
 * SEC-LOCAL-INF-ORG-CHAT (quox#599): the pre-registered lookup is now org-
 * scoped via getForOrg(sourceId, orgId) — `orgId` MUST be the authenticated
 * caller's org (jwtOrgId / resolvedOrgId at the two chat-dispatch call
 * sites below), never a client-supplied value alone. Previously this called
 * getUnscoped(sourceId), so any authenticated org that knew/guessed another
 * org's registered source id could route its chat through that org's
 * inference endpoint + auth token. A missing orgId or a cross-org id both
 * resolve to null (same "not found" either way — no existence disclosure).
 */
function resolveLocalSource(sourceId, requestBody, orgId) {
  // If source config is passed inline in the request, use it directly
  if (requestBody?.local_source_url) {
    const ssrf = validateOutboundUrl(requestBody.local_source_url);
    if (!ssrf.valid) {
      throw new Error(`blocked_url: local_source_url is not allowed (${ssrf.error})`);
    }
    return {
      id: sourceId || 'inline',
      baseUrl: requestBody.local_source_url,
      authToken: requestBody.local_source_token || null,
      backendType: requestBody.local_backend_type || 'auto',
      dataResidencyTag: requestBody.local_residency_tag || 'local'
    };
  }
  // Otherwise look up from registered sources — org-scoped.
  if (!orgId) return null;
  return localInferenceSourcesStore.getForOrg(sourceId, orgId);
}

/**
 * Register a local inference source (called from settings API).
 * SEC-LOCAL-INF-ORG: orgId is now required — see the POST route below.
 */
function registerLocalSource(source, orgId) {
  localInferenceSourcesStore.register(source, orgId);
}

async function handleLocalInferenceChat(req, res, opts) {
  const {
    source,
    model,
    systemPrompt,
    userMessage,
    session_id,
    selected_agent,
    agentTools = [],
    userId,
    orgId,
    userAccessToken,
    memory_context,
    quox_context,
    conversation_history,
  } = opts;
  const start = Date.now();

  const baseUrl = source.baseUrl.replace(/\/$/, '');
  const chatUrl = `${baseUrl}/v1/chat/completions`;

  console.log(`[LocalInference] Chat request: source=${source.id}, backend=${source.backendType}, model=${model}, agent=${selected_agent}`);

  // CRP-AU-4: Start VOLT run for Local Inference path
  const voltRunId = voltEmitter.startRun(session_id || `LOCAL_${Date.now()}`, {
    org_id: orgId, user_id: userId, agent_id: selected_agent,
    path: 'local_inference', source_id: source.id, backend: source.backendType
  });

  const headers = { 'Content-Type': 'application/json' };
  if (source.authToken) {
    headers['Authorization'] = `Bearer ${source.authToken}`;
  }

  try {
    let loopResult;
    const localGroundingEv = require('./lib/groundingContract.js').createEvidenceCollector();
    try {
      loopResult = await executeOpenAICompatibleToolLoop(req, {
        onEvent: localGroundingEv.onEvent,
        apiUrl: chatUrl,
        headers,
        model,
        systemPrompt,
        userMessage,
        selected_agent,
        session_id,
        agentTools,
        providerLabel: `local inference (${source.id})`,
        userId,
        orgId,
        userAccessToken,
        memory_context,
        quox_context,
        conversation_history,
        voltRunId,
      }, openaiToolLoopDeps());
    } catch (err) {
      if (err.code === 'tool_calling_unsupported') {
        console.warn(`[LocalInference] ${source.id} does not support tools via chat completions — retrying without tool calls`);
        loopResult = await executeOpenAICompatibleToolLoop(req, {
          apiUrl: chatUrl,
          headers,
          model,
          systemPrompt,
          userMessage,
          selected_agent,
          session_id,
          agentTools: [],
          providerLabel: `local inference (${source.id})`,
          userId,
          orgId,
          userAccessToken,
          memory_context,
          quox_context,
          conversation_history,
          voltRunId,
        }, openaiToolLoopDeps());
      } else {
        console.error(`[LocalInference] API error ${err.status || 'unknown'}:`, (err.body || err.message || '').substring(0, 200));
        if (err.status === 404) {
          throw new Error(`Model '${model}' not found on ${source.id}. Check that the model is loaded.`);
        }
        throw new Error(`Local inference server returned ${err.status || 500}: ${(err.body || err.message || '').substring(0, 200)}`);
      }
    }

    // QUOXON-ENGINE classes 2 + 5: the grounding contract on the local-inference path.
    const localGrounding = require('./lib/groundingContract.js').applyGroundingContract({ stripFakeActivity: true,
      answer: loopResult.content || '', userMessage, toolResults: localGroundingEv.items(),
      evidence: [localGroundingEv.text(), userMessage, quox_context || '', memory_context || ''].join('\n'),
      tag: `path=local-inference agent=${selected_agent}`,
    });
    const content = localGrounding.text;
    const latencyMs = Date.now() - start;
    const tokensUsed = loopResult.data?.usage?.total_tokens || null;
    const voiceSummary = extractVoiceSummary(content);
    const toolSuffix = loopResult.toolsUsed.length > 0 ? `\n\n---\n*Tools used: ${loopResult.toolsUsed.join(', ')}*` : '';

    voltEmitter.completeRun(voltRunId);
    storeAuditEnvelope({
      type: 'event', from: `agent.${selected_agent}`, to: 'audit.system',
      intent: 'quox.chat.success', corr: session_id || `CHAT_${Date.now()}`,
      payload: {
        agent: selected_agent,
        path: 'local_inference',
        provider: 'local',
        host: source.id,
        model,
        inferenceBackend: source.backendType,
        privacyBoundary: source.dataResidencyTag || 'local',
        latencyMs,
        tokensUsed,
        response_length: content.length,
        tools_used: loopResult.toolsUsed
      }
    });

    return res.json({
      success: true, result: content + toolSuffix, voice_summary: voiceSummary,
      session_id: session_id || 'local-' + Date.now(),
      model, provider: 'local',
      local_source: source.id,
      inference_backend: source.backendType,
      privacy_boundary: source.dataResidencyTag || 'local',
      latency_ms: latencyMs,
      tokens_used: tokensUsed,
      agent_used: selected_agent,
      tools_used: loopResult.toolsUsed, ...(Array.isArray(loopResult.toolOutcomes)&&loopResult.toolOutcomes.length?{tool_outcomes:loopResult.toolOutcomes}:{}), can_continue: true
    });
  } catch (err) {
    voltEmitter.failRun(voltRunId, err);
    const latencyMs = Date.now() - start;
    console.error(`[LocalInference] Error:`, err.message);

    storeAuditEnvelope({
      type: 'error', from: `agent.${selected_agent}`, to: 'audit.system',
      intent: 'quox.chat.error', corr: session_id || `CHAT_${Date.now()}`,
      payload: {
        agent: selected_agent,
        path: 'local_inference',
        provider: 'local',
        host: source.id,
        model,
        error: err.message,
        latencyMs
      }
    });

    throw err;
  }
}

