// In-memory agent store
const agents = new Map();
// QUOXON first-text (2026-10-19): fleet host names, synchronously, for the pre-dispatch handoff gap (lib/fleetHostNames.js).
const _fleetHostNames = require('./lib/fleetHostNames.js').createFleetHostNames({
  load: (...a) => require('./lib/agentTools.js').getFleetRegistryLocal(...a),
  liveIds: () => [...agents.keys()],
});
const knownFleetHostNames = () => _fleetHostNames.get();
// QUOXTRUST D2 — per-host_id set of source IPs seen on heartbeats. >1 distinct
// IP for one host_id ⇒ TWO VMs POST under the same id (clone provisioned without
// a unique host_id), which makes the collector's keyed-status flap. Diagnostic
// for the belt-flip readiness (exposed on /api/internal/fleet/heartbeat-auth).
const heartbeatSrcAddrs = new Map();

// ============================================================================
// MR-7: Collector-side Mirror Cache
// Lightweight self-updating cache of system state for prompt injection.
// Runs independently of frontend — ensures system prompt has Mirror data
// even for API-only requests.
// ============================================================================
let _collectorMirrorCache = null;
let _collectorMirrorTimestamp = 0;
const MIRROR_CACHE_TTL = 30000; // 30s

async function refreshCollectorMirror() {
  try {
    const TASKS_URL = `http://${process.env.TASKS_HOST || 'tasks'}:${process.env.TASKS_PORT || '3104'}`;
    const SERVICE_KEY = process.env.INTERNAL_SERVICE_KEY || '';
    const headers = { 'X-Service-Key': SERVICE_KEY, 'X-Org-Id': 'default' };

    const [healthResp, fleetCount] = await Promise.allSettled([
      fetch(`${TASKS_URL}/api/engine/health`, { headers, signal: AbortSignal.timeout(5000) }).then(r => r.ok ? r.json() : null),
      Promise.resolve(agents.size), // connected agents from heartbeat map
    ]);

    const health = healthResp.status === 'fulfilled' ? healthResp.value : null;
    const connectedAgents = fleetCount.status === 'fulfilled' ? fleetCount.value : 0;

    _collectorMirrorCache = {
      timestamp: new Date().toISOString(),
      guardian: health ? {
        alive: health.guardian_alive,
        schedulerAlive: health.scheduler_alive,
        interventions24h: health.interventions_24h || 0,
        alertsActive: health.alerts_24h || 0,
      } : null,
      fleet: { connectedAgents },
    };
    _collectorMirrorTimestamp = Date.now();
  } catch (err) {
    console.warn('[Mirror] Collector cache refresh failed:', err.message);
  }
}

function getCollectorMirrorCompact() {
  // QUOXON-MIRROR (#1125): retired. This block was built once for the whole collector (every org's
  // CommanderQ saw the whole fleet count). The org-scoped Mirror (lib/orgMirror.js) now rides in
  // [SELF-KNOWLEDGE] on every path, so the global "## System Status" line is no longer injected.
  return '';
}

// The pre-#1125 whole-collector line, kept only for GET /api/internal/mirror (service key, ops view).
function getCollectorWideStatusLine() {
  if (!_collectorMirrorCache) return '';
  const m = _collectorMirrorCache;
  const guardian = m.guardian
    ? `Guardian: ${m.guardian.alive ? 'alive' : 'offline'}, ${m.guardian.interventions24h} interventions (24h)`
    : 'Guardian: unknown';
  return `Fleet: ${m.fleet.connectedAgents} agents connected | ${guardian}`;
}

// ============================================================================
// AEE (Agent Envelope Exchange) SQLite Storage
// ============================================================================

// Initialize SQLite database for AEE envelopes
const executionLedger = require('./lib/executionLedger.js');
// QUOXTRUST WP4.2 — armed in server.listen once the ward service resolves;
// /health reads its status (null-safe → 'disabled').
let _evidenceReconciler = null;
let aeeDb = null;
let lucidDb = null; // LUCID's own small SQLite file (lib/lucid/db.js)
try {
  const dbDir = require('path').dirname(AEE_DB_PATH);
  if (!require('fs').existsSync(dbDir)) {
    require('fs').mkdirSync(dbDir, { recursive: true });
  }
  aeeDb = new Database(AEE_DB_PATH);
  aeeDb.pragma('journal_mode = WAL');
  aeeDb.pragma('cache_size = -262144'); // 256 MB page cache (multi-GB db, random-key index inserts)
  aeeDb.pragma('mmap_size = 1073741824'); // 1 GB

  // Initialize NOC outcome recorder with the same database
  setNocDatabase(aeeDb);

  // Versioned migrations (schema_migrations tracking + append-only
  // migrations/aee/*.sql) — replaces the previous inline CREATE TABLE +
  // ad-hoc ALTER try/catch. Covers envelopes, noc_tool_outcomes, and
  // suggestion_dismissals (all three share aeeDb).
  runMigrations({ db: aeeDb, migrationsDir: migrationsDirFor('aee'), log: (m) => console.log(`[AEE] ${m}`) });

  // QUOXTRUST T3 (D3 durability) — execution ledger: idempotent safety-net table
  // (real schema in migrations/aee/034-execution-intents.sql), then reconcile any
  // crash-orphaned in-flight external effects left by a prior run: dispatched →
  // outcome_unknown (may have landed, NEVER auto-retried), claimed → aborted
  // (provably did not fire). This is the on-boot recovery the plan calls for.
  try {
    executionLedger.initExecutionLedger(aeeDb);
    const recon = executionLedger.reconcileOnBoot(aeeDb);
    if (recon.dispatched_unknown > 0 || recon.claimed_aborted > 0) {
      console.warn(`[AEE] T3 execution-ledger reconcile: ${recon.dispatched_unknown} dispatched→outcome_unknown, ${recon.claimed_aborted} claimed→aborted (crash orphans; NOT retried)`);
    } else {
      console.log('[AEE] T3 execution-ledger reconcile: no in-flight orphans');
    }
  } catch (ledgerErr) {
    console.warn('[AEE] T3 execution-ledger init/reconcile failed:', ledgerErr.message);
  }

  // QUOXTRUST T3 — give the agent tool layer (email_send) the durable ledger
  // handle so its consequential external effects fail closed without durable
  // intent, same as the connector bridge.
  try {
    require('./lib/agentTools').setExecutionLedger(aeeDb);
  } catch (e) {
    console.warn('[AEE] T3 agentTools ledger wiring failed:', e.message);
  }

  // Run initial WAL checkpoint to reclaim space
  try {
    aeeDb.pragma('wal_checkpoint(TRUNCATE)');
    console.log('[AEE] Initial WAL checkpoint completed');
  } catch (walErr) {
    console.warn('[AEE] Initial WAL checkpoint failed:', walErr.message);
  }

  // Periodic WAL checkpoint every 6 hours
  const walCheckpointTimer = setInterval(() => {
    try {
      aeeDb.pragma('wal_checkpoint(TRUNCATE)');
      console.log('[AEE] WAL checkpoint completed');
    } catch (err) {
      console.error('[AEE] WAL checkpoint failed:', err.message);
    }
  }, 6 * 60 * 60 * 1000);
  if (walCheckpointTimer.unref) walCheckpointTimer.unref();

  console.log(`[AEE] SQLite database initialized at ${AEE_DB_PATH}`);
} catch (err) {
  console.warn(`[AEE] SQLite initialization failed: ${err.message}`);
  console.warn('[AEE] Running without persistence (in-memory only)');
}

// Initialize SQLite database for VOLT execution traces
// NB: platformSettingsStore MUST be required before the init block below —
// it is used at initPlatformSettingsStore(voltDb) inside this try. It was
// previously declared ~370 lines later, so that reference hit the const's
// temporal dead zone and threw "Cannot access 'platformSettingsStore' before
// initialization", which the catch swallowed, silently skipping the
// org_platform_settings table creation AND every init after it (governance
// incidents, agent contracts, behaviour baselines, the AEE attach). Proven
// live 2026-08-08: settings_set failed with "no such table" and the logs
// flooded with MON-GOV "no such table: aee.envelopes".
const platformSettingsStore = require('./lib/platformSettingsStore');
const killSwitchStore = require('./lib/killSwitchStore');
const safetyDispatchGate = require('./lib/safetyDispatchGate');
const safetyGateRoutes = require('./routes/safetyGate');
const acceptanceStore = require('./lib/acceptanceStore');
const runAcceptanceRoutes = require('./routes/runAcceptance');
const { applyOpenAiToolCap, applySmartToolCap } = require('./lib/toolRetrievalCap');
// QUOXHAT P0 — per-turn tool manifest instrumentation (measurement only):
// origin decomposition + cap/fallback-leg status, org-scoped, feeding the
// read-only Settings + Mirror baseline surface. Never modifies the tool set.
const { summarizeToolOrigins, recordTurnToolStats, getTurnToolStats } = require('./lib/turnToolStats');
// QUOXHAT P2 — per-turn hat resolution + frozen manifest (see lib/hatManifest.js).
const { resolveHatForTurn, buildTurnManifest, buildFailClosedManifest, startEnforcementPrewarm } = require('./lib/hatManifest');
const { searchTools: toolIndexSearchTools } = require('./lib/toolIndex');
let voltDb = null;
try {
  const voltDbDir = require('path').dirname(VOLT_DB_PATH);
  if (!require('fs').existsSync(voltDbDir)) {
    require('fs').mkdirSync(voltDbDir, { recursive: true });
  }
  voltDb = new Database(VOLT_DB_PATH);
  voltDb.pragma('journal_mode = WAL');
  voltDb.pragma('cache_size = -262144'); // 256 MB page cache (multi-GB db, random-key index inserts)
  voltDb.pragma('mmap_size = 1073741824'); // 1 GB

  // Versioned migrations (schema_migrations tracking + append-only
  // migrations/volt/*.sql) — replaces the previous inline CREATE TABLE
  // blocks (main VOLT/compliance/audit tables + the separate TRV-1 trace
  // tables exec below). Covers all 22 tables that live in voltDb, including
  // ones owned by lib/policyStore.js, lib/governanceIncidents.js, etc.
  // (those modules' own init*(voltDb) calls further below still run, but
  // are now redundant idempotent no-ops against an already-migrated DB).
  runMigrations({ db: voltDb, migrationsDir: migrationsDirFor('volt'), log: (m) => console.log(`[VOLT] ${m}`) });
  console.log('[TRV] Trace persistence tables initialized');

  // GOV-1: Initialize policies table and seed defaults
  initPolicyStore(voltDb);
  const seededCount = seedDefaultPolicies(voltDb);
  if (seededCount > 0) console.log(`[GOV] Seeded ${seededCount} default policies`);

  // Phase 25: org-scoped platform settings (org_platform_settings + history)
  platformSettingsStore.initPlatformSettingsStore(voltDb);

  // quox#503: server-side kill switch / DEFCON state (agent_kill_switches,
  // org_defcon_state, safety_state_history). Same voltDb, same init-order
  // requirement as platformSettingsStore above.
  killSwitchStore.initKillSwitchStore(voltDb);

  // SEO-MOAT (owner ruling 2026-09-03): minimal witnessed acceptance
  // verdicts (run_acceptance_verdicts). Same voltDb, same init-order
  // requirement as the two stores above.
  acceptanceStore.initAcceptanceStore(voltDb);

  // COMMANDERQ P5: signed plan-artifact store (artifacts table). The queryable
  // server-side source of truth for retrieval; the quox.artifact.created AEE
  // envelope remains the WARD-witnessed evidence. Same voltDb, same init-order.
  initArtifactStore(voltDb);

  // COMMANDERQ P8: commitment ledger (promises as governed objects; mutable
  // lifecycle beside the immutable signed commitment artifact). Same voltDb.
  initCommitmentLedger(voltDb);

  // COMMANDERQ P11/B3: calibration self-audit ledger (per-turn P3 grounding counts).
  initCalibrationLedger(voltDb);

  // COMMANDERQ P9 (C1+C3): contactability policy + attempts + watch-brief store.
  contactabilityStore.initContactabilityStore(voltDb);

  // COMMANDERQ P10 (F1+F3): governed outbound-call objects (intent/lifecycle/summary).
  callStore.initCallStore(voltDb);

  // P7 CONTINUITY: the witnessed self-log (hash-chained self-deltas, one
  // substrate ready for QLoop lineage records too). Witness emission rides
  // storeAuditEnvelope like every other evidence event.
  {
    const selfLog = require('./lib/selfLogStore.js');
    selfLog.ensure(voltDb);
    selfLog.setDatabase(voltDb);
    selfLog.setEnvelopeEmitter((env) => storeAuditEnvelope(env));
  }

  // X-PLUGIN P2: durable, org-scoped X posting budget ledger (x_post_ledger).
  // Same voltDb, same wiring pattern as selfLog above — setDatabase() also
  // runs xPostingStore's CREATE TABLE IF NOT EXISTS.
  {
    const xTools = require('./lib/xTools.js');
    xTools.setDatabase(voltDb);
    // QUOXTRUST C2/WP2: cross-domain durable intent for executeXDecision (the
    // real X dispatch runs on the approval-decide path, outside the executeTool
    // choke) — same aeeDb execution_intents table the choke gate uses.
    xTools.setExecutionLedgerDb(aeeDb);
  }

  // MON-GOV-0: Governance incidents schema
  initGovernanceIncidents(voltDb);
  // MON-GOV-3: SIEM webhook configuration schema
  initGovernanceWebhookConfig(voltDb);
  // RSP-CONTRACT Phase 1a: Responsibility Contract schema (real schema owned
  // by migrations/volt/002-agent-contracts.sql; this is the same idempotent
  // redundant-safety-net pattern as the two lines above).
  initAgentContracts(voltDb);
  // MON-GOV-INT Phase 1: ticketing configuration schema (governance_ticket_config
  // + governance_incident_tickets are also owned by migrations/volt/001-governance-ticketing.sql;
  // this call is the same idempotent redundant-safety-net pattern as the two lines above).
  initGovernanceTicketConfig(voltDb);
  initGovernanceIncidentTickets(voltDb);
  // MON-GOV-4: Agent behavioural baselines schema + ATTACH the AEE db
  // so a single voltDb handle can read both tables in the detector.
  initAgentBehaviorBaselines(voltDb);
  // receipts honesty: the first boot running it anchors MON-GOV's "error counting changed" note (kept on later boots)
  anchorErrorCountingChange(voltDb);
  attachAeeDbForBehavior(voltDb, AEE_DB_PATH);

  // AUD-PDF: generated-PDF cache (cache-key hash of (format, input))
  const { initPdfCache } = require('./lib/pdf/pdfCache.js');
  initPdfCache(voltDb);

  // GOV-4: Wire policy store into approval gate and agent tools
  const { setDatabase: setApprovalGateDb, setReachEvaluator } = require('./lib/approvalGate.js');
  setApprovalGateDb(voltDb);
  const { setGovDatabase, setAuditEmitter } = require('./lib/agentTools.js');
  setGovDatabase(voltDb);
  // QUOXTRUST D6/T9: inject the same storeAuditEnvelope the gold /api/v1/tools/
  // execute path uses so the executeTool CHOKE emits a witnessed per-tool receipt
  // for every native tool run through ANY of the 20+ direct callers. The 5 caller
  // sites that emit their own richer per-tool evidence set
  // ctx._callerEmitsToolEvidence to opt out (no double-emit).
  setAuditEmitter(storeAuditEnvelope);

  // BLAST-RADIUS-P1/P2: wire the real blast-radius evaluator into the
  // approval gate (lib/reach/actionRadius.js over the P0 static resolver),
  // and set up the shared reach runtime (lib/reach/runtime.js) every other
  // reach entry point (the GET route, the reach_agent agent tool) consumes.
  // Built as a closure rather than invoked here — qlarityAllowlist (below,
  // line ~7196) isn't assigned yet at this point in module load order, but
  // this function only runs later, per approval, once the whole module has
  // finished loading. getToolsWithConnectors is already destructured at
  // the top of this file.
  const { createReachResolver } = require('./lib/reach/reachResolver.js');
  const { computeActionRadius } = require('./lib/reach/actionRadius.js');
  const { setReachRuntime, auditReachEvaluation } = require('./lib/reach/runtime.js');
  // qlarityAllowlist is a const declared ~5000 lines below; naming it eagerly
  // here is a TDZ ReferenceError that aborts this whole try block at boot
  // (2026-09-20: took reach AND the actions/brain audit wiring down with it).
  // The lazy wrapper defers the read to first evaluation, after module load.
  const reachResolverForRuntime = createReachResolver({
    getToolsWithConnectors,
    qlarityAllowlist: { originsFor: (args) => qlarityAllowlist.originsFor(args) },
  });
  const resolveStaticReachForRuntime = (aId, oId) => reachResolverForRuntime.resolveReach({ agentId: aId, orgId: oId });

  // BLAST-RADIUS-P2: one runtime instance, three consumers. audit =
  // storeAuditEnvelope (hoisted function declaration further down this
  // file — already the established pattern here, see selfLog wiring above).
  setReachRuntime({
    resolveStaticReach: resolveStaticReachForRuntime,
    computeActionRadius,
    audit: storeAuditEnvelope,
  });

  setReachEvaluator(async ({ toolName, input, agentId, orgId, correlationId }) => {
    const result = await computeActionRadius(
      { toolName, input, agentId, orgId },
      { resolveStaticReach: resolveStaticReachForRuntime },
    );
    auditReachEvaluation({ trigger: 'approval_gate', orgId, agentId, corr: correlationId, result });
    return result;
  });

  // ACTIONS: wire collector's audit-envelope writer into action tool handlers
  // so AEE envelopes from action_add/move/update/delete/analyse/delegate persist.
  setActionsAuditFn(storeAuditEnvelope);

  // BRAIN2-PRODUCT P3a: same DI pattern, wires quoxbrain_search's per-invocation
  // 'quox.brain.search' envelope into the real AEE store. BRAIN2-V2-5: the same
  // injection also carries 'quox.brain.unavailable' (brain never answered, with
  // a reason), which is what separates a down brain from an empty one.
  setQuoxbrainAuditFn(storeAuditEnvelope);

  // BRAIN2-V2-1: same DI pattern again, for the end-of-turn
  // 'quox.brain.cited' envelope (which retrieved notes the answer used).
  setBrainCitationAuditFn(storeAuditEnvelope);

  console.log(`[VOLT] SQLite database initialized at ${VOLT_DB_PATH}`);
} catch (err) {
  console.warn(`[VOLT] SQLite initialization failed: ${err.message}`);
}

// Initialize SQLite database for Feedback & Error Reports
let feedbackDb = null;
try {
  const fbDbDir = require('path').dirname(FEEDBACK_DB_PATH);
  if (!require('fs').existsSync(fbDbDir)) {
    require('fs').mkdirSync(fbDbDir, { recursive: true });
  }
  feedbackDb = new Database(FEEDBACK_DB_PATH);
  feedbackDb.pragma('journal_mode = WAL');

  // Versioned migrations (schema_migrations tracking + append-only
  // migrations/feedback/*.sql) — replaces the previous inline CREATE TABLE
  // block. Covers feedback + error_reports.
  runMigrations({ db: feedbackDb, migrationsDir: migrationsDirFor('feedback'), log: (m) => console.log(`[Feedback] ${m}`) });

  console.log(`[Feedback] SQLite database initialized at ${FEEDBACK_DB_PATH}`);
} catch (err) {
  console.warn(`[Feedback] SQLite initialization failed: ${err.message}`);
}

// QUOX-SECURITY Phase 0: engagement/scope database (security.db). Mirrors
// the wazuhDb init pattern below (own SQLite file, own migrations/security/
// dir, non-fatal on failure). Wired into approvalGate.js so the
// engagement-scope pre-check (checkApproval's ctx._securityEngagement
// branch) can run its policy query.
const SECURITY_DB_PATH = process.env.SECURITY_DB_PATH || '/var/lib/quox/security.db';
let securityDb = null;
try {
  securityDb = new Database(SECURITY_DB_PATH);
  securityDb.pragma('journal_mode = WAL');
  runMigrations({ db: securityDb, migrationsDir: migrationsDirFor('security'), log: (m) => console.log(`[Security DB] ${m}`) });
  const { setSecurityDb } = require('./lib/approvalGate.js');
  setSecurityDb(securityDb);
  const { configure: configureSecurityEngagementTools } = require('./lib/securityEngagementTools.js');
  const { checkFleetMembership: checkFleetMembershipImpl } = require('./lib/securityFleetVerification.js');
  configureSecurityEngagementTools({ db: securityDb, checkFleetMembership: checkFleetMembershipImpl });
  const { configure: configureSecurityCapabilityTools, executeSecurityCapabilityToolAsync } = require('./lib/securityCapabilityTools.js');
  configureSecurityCapabilityTools({ db: securityDb });
  const { configure: configureSecurityFindingsTools } = require('./lib/securityFindingsTools.js');
  configureSecurityFindingsTools({ db: securityDb });

  // QUOX-SECURITY-SCHED Phase 2: server-side cadence loop in front of the
  // EXISTING async execution path. No new executor — the adapter below just
  // maps the scheduler's clean call shape onto executeSecurityCapabilityToolAsync's
  // real (name, input, ctx) signature, the same one the
  // .../capability/:tool/start route already calls. Schedules store the
  // bare tool suffix (e.g. "vuln_scan", see securityEngagementSchedules
  // tests), matching that route's own `sectest_${req.params.tool}`
  // convention, so the adapter applies the same prefix.
  const { createSecurityScanScheduler } = require('./lib/securityScanScheduler.js');
  const securityScanScheduler = createSecurityScanScheduler({
    db: securityDb,
    executeAsync: async ({ engagementId, orgId, toolName, targetValue, scheduleId, createdBy }) => {
      const fullToolName = toolName.startsWith('sectest_') ? toolName : `sectest_${toolName}`;
      return executeSecurityCapabilityToolAsync(
        fullToolName,
        { engagement_id: engagementId, target: targetValue, schedule_id: scheduleId, created_by: createdBy },
        { orgId }
      );
    },
  });
  if (process.env.NODE_ENV !== 'test') {
    securityScanScheduler.start();
  }

  console.log(`[Security DB] Initialized at ${SECURITY_DB_PATH}`);
} catch (err) {
  console.error('[Security DB] Failed to initialize:', err.message);
}

// ============================================================================
// STUDY-REV K1/R1: Tool Definitions Store (DB-resolved metadata)
// ============================================================================
// Runs after entity tool loading (agentTools.js is already fully required above
// at line 74, which triggers entity tool + MCP merges). Seeding here captures
// all native + entity + MCP tools in one pass.
const TOOLS_DB_PATH = process.env.TOOLS_DB_PATH || '/var/lib/quox/tools.db';
try {
  const toolDefStore = require('./lib/toolDefinitionsStore.js');
  toolDefStore.init(TOOLS_DB_PATH);
  const seeded = toolDefStore.seedFromHardcoded(TOOL_DEFS);
  console.log(`[Tools] Seeded ${seeded.inserted} new tool definitions, ${seeded.skipped} already present, ${seeded.refreshed} refreshed from code.`);

  // POWERS-P2.C-fix-3: Boot-reseed from auth (CLAUDE.md ZERO TOLERANCE — Data Persistence).
  // The in-memory toolDefinitionsStore is a CACHE; auth's tool_definitions table is
  // the SOURCE OF TRUTH. Every collector restart silently vaporises the store. This
  // loop keeps retrying in background until auth is reachable so MCP tools survive restarts.
  let _reseedAttempt = 0;
  const _reseedMax = 20; // ~10 minutes of retries at 30s intervals
  const _doReseed = () => {
    toolDefStore.reseedFromAuth().then(({ reseeded, errors }) => {
      console.log(`[Tools] Boot-reseed from auth complete: ${reseeded} tools, ${errors} errors`);
    }).catch((err) => {
      _reseedAttempt++;
      if (_reseedAttempt < _reseedMax) {
        console.warn(`[Tools] Boot-reseed attempt ${_reseedAttempt}/${_reseedMax} failed (will retry in 30s): ${err.message}`);
        setTimeout(_doReseed, 30_000);
      } else {
        console.error(`[Tools] Boot-reseed gave up after ${_reseedMax} attempts. MCP tools will not dispatch until next restart.`);
      }
    });
  };
  // Defer first attempt 5s to let auth finish starting
  setTimeout(_doReseed, 5_000);
} catch (err) {
  console.warn(`[Tools] Tool definitions store init failed (non-fatal): ${err.message}`);
}

// Boot-reseed plugin backend gateway registrations. The in-memory PLUGIN_BACKENDS
// map is a CACHE wiped on every collector restart; auth's plugin_installs is the
// source of truth. Without this, plugin API calls 404 ('backend not registered')
// after any restart until a user happens to re-activate the plugin — the ~10s
// "wait and it loads" window. startPluginBackend is idempotent (returns the
// already-running container), so this is cheap for live backends. Retries in the
// background until auth is reachable. (Sibling of the tool-definitions reseed.)
async function _reseedPluginBackends() {
  // SEC-PLUGIN-TRUST P5: official and eligible community backends start; an
  // ineligible one (e.g. revoked while the collector was down) is stopped.
  return require('./lib/pluginBackendAdmin.js').reseedPluginBackends({
    lifecycle: pluginBackendLifecycle,
    registerPluginBackend,
    unregisterPluginBackend,
  });
}
let _pbReseedAttempt = 0;
const _pbReseedMax = 20; // ~10 minutes of 30s retries
const _doPbReseed = () => {
  _reseedPluginBackends().then(({ ok, fail, total }) => {
    console.log(`[PluginGateway] Boot-reseed complete: ${ok}/${total} backend(s) registered, ${fail} failed`);
  }).catch((err) => {
    _pbReseedAttempt++;
    if (_pbReseedAttempt < _pbReseedMax) {
      console.warn(`[PluginGateway] Boot-reseed attempt ${_pbReseedAttempt}/${_pbReseedMax} failed (retry 30s): ${err.message}`);
      setTimeout(_doPbReseed, 30_000);
    } else {
      console.error(`[PluginGateway] Boot-reseed gave up after ${_pbReseedMax} attempts — plugins re-register on next activation.`);
    }
  });
};
if (process.env.NODE_ENV !== 'test') {
  setTimeout(_doPbReseed, 7_000); // shortly after the tool reseed, once auth is up
}

// Prepared statements for feedback & error reports
