const voltStatements = voltDb ? {
  insertRun: voltDb.prepare(`
    INSERT OR REPLACE INTO volt_runs (run_id, corr, status, started_at, completed_at, seq, head_hash, org_id, stored_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
  `),
  insertEvent: voltDb.prepare(`
    INSERT OR IGNORE INTO volt_events (event_id, run_id, event_type, ts, seq, data, stored_at)
    VALUES (?, ?, ?, ?, ?, ?, datetime('now'))
  `),
  insertBundle: voltDb.prepare(`
    INSERT OR REPLACE INTO volt_bundles (bundle_id, run_id, created_ts, data, stored_at)
    VALUES (?, ?, ?, ?, datetime('now'))
  `),
  insertContent: voltDb.prepare(`
    INSERT OR IGNORE INTO volt_content (event_id, run_id, event_type, created_at, content, content_hash, redacted)
    VALUES (?, ?, ?, datetime('now'), ?, ?, ?)
  `),
  // quox#510 (lib/aeeVoltBridge.js): durable idempotency check before calling
  // voltEmitter.emit() — see that file's appendEvent() for why an in-memory
  // dedup set isn't enough (emit() advances chain state before insertEvent's
  // INSERT OR IGNORE tells you whether a row was actually written).
  hasEvent: voltDb.prepare('SELECT 1 FROM volt_events WHERE event_id = ?'),
  // quox#510: surfaces the AEE-ingest bridge's per-run event cap on the run
  // row itself (migrations/volt/006-volt-runs-event-cap-column.sql).
  markRunCapped: voltDb.prepare('UPDATE volt_runs SET event_cap_hit = 1 WHERE run_id = ?'),
  getRun: voltDb.prepare('SELECT * FROM volt_runs WHERE run_id = ?'),
  // quox#745: voltEmitter resumes a run's chain from its last persisted event
  // (last seq + hash) instead of forking a second chain at seq 1.
  getLastEvent: voltDb.prepare('SELECT seq, data FROM volt_events WHERE run_id = ? ORDER BY seq DESC, rowid DESC LIMIT 1'),
  // quox#745: /volt/sync refuses an event that would fork a run's chain.
  getEventAtSeq: voltDb.prepare('SELECT event_id, data FROM volt_events WHERE run_id = ? AND seq = ? LIMIT 1'),
  getRunByCorr: voltDb.prepare('SELECT * FROM volt_runs WHERE corr = ? ORDER BY started_at DESC LIMIT 1'),
  getRuns: voltDb.prepare('SELECT * FROM volt_runs ORDER BY started_at DESC LIMIT ?'),
  getRunsPaged: voltDb.prepare('SELECT * FROM volt_runs ORDER BY started_at DESC LIMIT ? OFFSET ?'),
  // WP-B: org-scoped runs for per-org VOLT integrity (monComputeVoltIntegrity).
  // Runs with no org_id (background/system) are never returned for a caller org.
  getRunsByOrg: voltDb.prepare("SELECT * FROM volt_runs WHERE status = 'completed' AND (org_id = ? OR org_id IS NULL) ORDER BY started_at DESC LIMIT ?"),
  // TRUST-PROOF (FND_01M2Y2GXRF): org-scoped paged listing + count for GET
  // /volt/runs, which previously served getRunsPaged (ALL orgs). Same
  // (org_id = ? OR org_id IS NULL) shared-system convention as getRunsByOrg;
  // includes all statuses (the listing showed active+completed) unlike the
  // integrity query which is completed-only.
  getRunsByOrgPaged: voltDb.prepare('SELECT * FROM volt_runs WHERE (org_id = ? OR org_id IS NULL) ORDER BY started_at DESC LIMIT ? OFFSET ?'),
  countRunsByOrg: voltDb.prepare('SELECT COUNT(*) as n FROM volt_runs WHERE (org_id = ? OR org_id IS NULL)'),
  getRunEvents: voltDb.prepare('SELECT * FROM volt_events WHERE run_id = ? ORDER BY seq ASC'),
  getRunBundle: voltDb.prepare('SELECT * FROM volt_bundles WHERE run_id = ? LIMIT 1'),
  // AUD-WS-5: list bundles in a time window for assurance-pack export
  listBundlesInPeriod: voltDb.prepare('SELECT * FROM volt_bundles WHERE created_ts >= ? AND created_ts <= ? ORDER BY created_ts'),
  getRunContent: voltDb.prepare('SELECT * FROM volt_content WHERE run_id = ? ORDER BY created_at ASC'),
  stats: voltDb.prepare(`
    SELECT
      (SELECT COUNT(*) FROM volt_runs) as runs,
      (SELECT COUNT(*) FROM volt_events) as events,
      (SELECT COUNT(*) FROM volt_bundles) as bundles
  `),
  // WP-B (compliance surface): org-scoped VOLT stats for GET /volt/stats.
  // Events/bundles have no org_id of their own — scoped via their owning
  // run's org_id (volt_runs.org_id, migration 003). Same shape as `stats`
  // above (runs/events/bundles keys) so callers (sidebar, useComplianceData)
  // don't need to change. No org -> zeros, never global.
  // quox#700: each (org_id = ? OR org_id IS NULL) was rewritten as two
  // summed index branches (idx_volt_runs_org serves both = and IS NULL), and
  // events/bundles are counted per branch through idx_volt_events_run /
  // idx_volt_bundles_run. One bound org (?1); guarded by
  // test/statusProbeQueryPlans.test.js (no full-table SCAN).
  statsByOrg: voltDb.prepare(statusProbeSql.voltStatsByOrg),
} : null;

