// AEE-ORG-1: envelope org_id derivation — see lib/aeeOrgScoping.js for the
// priority order (explicit org_id > payload.orgId > org.<id> address > null).
const { deriveEnvelopeOrgId, parseOrgFromAddress, resolveAeeOrgId } = require('./lib/aeeOrgScoping.js');
const { buildIntentFilter } = require('./lib/aeeIntentFilter.js');

// Prepared statements for AEE operations
// EVD-1b: INSERT OR IGNORE (was OR REPLACE) — envelopes are append-only audit
//         records. Duplicate IDs (ULID — practically impossible) are dropped,
//         not overwritten. Matches the immutability expected of an audit log.
// EVD-1c: priority column added per AEE spec.
// fleet #393/#409: 60s throttle for /aee/query's `total` computation — the
// route's intent filter is a CONTAINS pattern, which no index can serve, so
// each fresh total walks ~1.6M intent values. Pollers re-use the cached
// value; see the route for details.
const aeeCountCache = new Map();
const AEE_COUNT_CACHE_TTL_MS = 60000;

const aeeStatements = aeeDb ? {
  // AEE-ORG-1: org_id added (nullable — see migrations/aee/002-envelopes-org-id-column.sql).
  insert: aeeDb.prepare(`
    INSERT OR IGNORE INTO envelopes (id, v, ts, type, "from", "to", intent, corr, reply_to, payload, raw, priority, org_id)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `),
  getById: aeeDb.prepare('SELECT * FROM envelopes WHERE id = ?'),
  getByCorr: aeeDb.prepare('SELECT * FROM envelopes WHERE corr = ? ORDER BY ts ASC'),
  // BRAIN2-W5 022: org-scoped corr read for Feed / reflection mining.
  getByCorrForOrg: aeeDb.prepare('SELECT * FROM envelopes WHERE corr = ? AND org_id = ? ORDER BY ts ASC'),
  getRecentByCorrForOrg: aeeDb.prepare('SELECT * FROM envelopes WHERE corr = ? AND org_id = ? ORDER BY ts DESC LIMIT ?'),
  // AEE-CORE-2.3: intent+type histogram for list-row rollup badges.
  // Only plain-text columns — no decryption needed.
  groupedByCorr: aeeDb.prepare('SELECT intent, type, COUNT(*) as n FROM envelopes WHERE corr = ? GROUP BY intent, type'),
  // Issue 1.11: Added ESCAPE clause for LIKE query
  query: aeeDb.prepare(`
    SELECT * FROM envelopes
    WHERE (? IS NULL OR type = ?)
      AND (? IS NULL OR intent LIKE ? ESCAPE '\\')
      AND (? IS NULL OR "from" = ?)
      AND (? IS NULL OR "to" = ?)
      AND (? IS NULL OR ts >= ?)
      AND (? IS NULL OR ts < ?)
    ORDER BY ts DESC
    LIMIT ?
  `),
  // AEE-ORG-1 (READ-SCOPE): org-scoped variant of `query`, used ONLY by the
  // caller-facing GET /aee/query HTTP route. `query` above is intentionally
  // left unscoped — it is shared by internal global-scan consumers
  // (reflectionMiningQueryRecentEnvelopes, the assurance-pack audit-events
  // puller) that legitimately need cross-org data for platform-wide
  // background jobs. This variant adds a strict `AND org_id = ?` at the end.
  // fleet #393/#409 history: the original OR-NULL single query forced a temp
  // b-tree sort of nearly the whole table per call (94.5% of collector CPU);
  // it was rewritten as a two-branch UNION ALL, and P2 below then removed the
  // NULL branch outright.
  // AEE-ORG-BACKFILL P2: the second UNION branch (org_id IS NULL) is gone.
  // It filtered on nothing, so every tenant received the whole untagged
  // bucket — 94% of the table. New writes are org-stamped at the quoxflow
  // sink (AEE-ORG-BACKFILL P1) and the recoverable backlog is backfilled by
  // scripts/backfill-aee-org.js; the residue is platform envelopes with no
  // tenant, which internal consumers read via the unscoped `query` above,
  // never via a tenant call. Single branch also keeps the fleet #393/#409
  // perf property: one idx_envelopes_org_ts walk, stops at LIMIT.
  queryOrgScoped: aeeDb.prepare(`
    SELECT * FROM envelopes
    WHERE ($type IS NULL OR type = $type)
      AND ($intent IS NULL OR intent LIKE $intent ESCAPE '\\')
      AND ($from IS NULL OR "from" = $from)
      AND ($to IS NULL OR "to" = $to)
      AND ($after IS NULL OR ts >= $after)
      AND ($before IS NULL OR ts < $before)
      AND ($corr IS NULL OR corr = $corr)
      AND org_id = $orgId
    ORDER BY ts DESC
    LIMIT $limit
  `),
  // quox#700: prefix-intent variants (see lib/aeeIntentFilter.js). The intent
  // predicate is an unconditional range, so the planner can use
  // idx_envelopes_org_intent (org_id = ? AND intent >= ? AND intent < ?).
  queryOrgScopedPrefix: aeeDb.prepare(statusProbeSql.queryOrgScopedPrefix),
  queryAgentEnvelopesSince: aeeDb.prepare(statusProbeSql.queryAgentEnvelopesSince),
  queryOrgIntentPrefixLatest: aeeDb.prepare(statusProbeSql.queryOrgIntentPrefixLatest),
  countOrgScopedPrefix: aeeDb.prepare(statusProbeSql.countOrgScopedPrefix),
  // Covering-index variant for the footer badge shape (org + intent prefix
  // only): answered from idx_envelopes_org_intent alone, no table lookups.
  countOrgIntentPrefix: aeeDb.prepare(statusProbeSql.countOrgIntentPrefix),
  // GOV-TRUTH tail (#3): true org-scoped total matching queryOrgScoped's
  // filters, independent of the caller's `limit`. Used by GET /aee/query so
  // the response's `count` reflects the real number of matching rows, not
  // just how many were capped/returned (e.g. sidebar AOCL count was reading
  // `count` as if it were a total when it was really min(total, limit)).
  // fleet #393/#409: same OR-shape rewrite as queryOrgScoped above — two
  // summed branches so the org_id=? branch and the org_id IS NULL branch
  // each use a composite index (idx_envelopes_org_intent makes the footer
  // badge's intent-prefix count an index range scan instead of a 1.6M-row
  // table walk per poll).
  // AEE-ORG-BACKFILL P2: NULL-bucket addend removed, matching queryOrgScoped.
  countOrgScoped: aeeDb.prepare(`
    SELECT COUNT(*) as total FROM envelopes
    WHERE ($type IS NULL OR type = $type)
      AND ($intent IS NULL OR intent LIKE $intent ESCAPE '\\')
      AND ($from IS NULL OR "from" = $from)
      AND ($to IS NULL OR "to" = $to)
      AND ($after IS NULL OR ts >= $after)
      AND ($before IS NULL OR ts < $before)
      AND ($corr IS NULL OR corr = $corr)
      AND org_id = $orgId
  `),
  // fleet #388: envelopes recorded since a given ISO timestamp. The
  // aggregate-health block used to guard on `typeof getAeeStats ===
  // 'function'` for a function that exists nowhere in this service, so the
  // guard could never pass and envelopes_today shipped a hardcoded 0 while
  // `quox aee stats` showed real traffic. A dead typeof guard reads like a
  // working integration, which is worse than an explicit TODO.
  countSince: aeeDb.prepare(`
    SELECT COUNT(*) as total FROM envelopes WHERE ts >= ?
  `),
  getConversations: aeeDb.prepare(`
    SELECT corr, MIN(ts) as first_ts, MAX(ts) as last_ts, COUNT(*) as count
    FROM envelopes
    WHERE corr NOT LIKE 'FLEET_%'
      AND corr NOT LIKE 'AUDIT_%'
      AND corr NOT LIKE 'MEM_%'
      AND corr NOT LIKE 'ERR_%'
      AND corr NOT LIKE 'ACTION_%'
      -- AEE-CORE-2.1: suppress legacy fragmented sibling corrs from list view.
      -- Post-AEE-CORE-1 these no longer generate new data, but historical
      -- records exist and would duplicate a single user action across multiple
      -- rows. Detail pane can still pull them via direct corr query.
      AND corr NOT LIKE 'mcp-%'
      AND corr NOT LIKE 'term-%'
      AND corr NOT LIKE 'TOOL_%'
      AND corr NOT LIKE 'STREAM_%'
      AND corr NOT LIKE 'OPS_%'
      -- ACTIVITY-TABS: standalone AOCL_ governance events get their own
      -- "Governance" tab (getConversationsGovernance below) so the default
      -- Conversations tab isn't mixed with policy/layer chatter.
      AND corr NOT LIKE 'AOCL_%'
      -- AEE-ORG-1 (READ-SCOPE): org isolation for new tagged data, while
      -- still surfacing legacy pre-org_id history (NULL org_id) shared
      -- across the instance — see /aee/stats + posture.
      AND org_id = ?
    GROUP BY corr
    HAVING count > 1 OR corr LIKE 'OBJ_%'
    ORDER BY last_ts DESC
    LIMIT ? OFFSET ?
  `),
  // ACTIVITY-TABS-2 (taxonomy fix): owner feedback — "Conversations should
  // be USER CHATS with agents ONLY, not core-agent objectives/workflows."
  // The Activity Centre now splits into six server-scoped families, each
  // backed by REAL corr-prefix families confirmed against the live aee.db
  // (see docs — CONV_ actual user<->agent chat envelopes with task/result
  // types; OBJ_ objectives; WORKFLOW_BUILDER_/WF_/wf-<slug>-<suffix>
  // workflow runs; AOCL_/ANOM_ governance+anomaly events; TOOL_ orphan tool
  // executions). Precedence is fixed and non-overlapping — Chats > Objectives
  // > Workflows > Governance > Tools > System, where System is defined as
  // the catch-all "everything not claimed by a specific tab" so no corr is
  // ever double-counted or silently dropped between tabs.
  //
  // SESSION_ decision: inspected live envelopes under SESSION_ENV_* corrs —
  // every one routes from agent/system actors to audit.agent_stream /
  // audit.system / system.aocl / system.tools with intents
  // quox.session.started, quox.agent.message, aocl.layer.*.complete,
  // aocl.run.*, ops.tool.executed. These are the system's own audit
  // recording of a run (no human-authored chat text lives here — contrast
  // with CONV_ envelopes, which carry human.user -> agent.* quox.chat.query
  // /quox.chat.response with real payload text). Several SESSION_ corrs even
  // fire from human.anonymous at identical times daily, indicating a
  // scheduled/system-initiated run, not a live user chat. Classified as
  // System (the infra catch-all), not Chats.
  // AEE-ORG-1 (READ-SCOPE): every getConversations*/countConversations*
  // statement below adds `AND org_id = ?` — legacy NULL org_id rows are
  // intentionally excluded (forward-looking, consistent with /aee/stats and
  // the posture endpoint). Only reachable via /aee/conversations/enriched
  // (getConversationRowsCached), which is now gated by requireAeeAuth().
  getConversationsChats: aeeDb.prepare(`
    SELECT corr, MIN(ts) as first_ts, MAX(ts) as last_ts, COUNT(*) as count
    FROM envelopes
    WHERE corr LIKE 'CONV_%'
      AND org_id = ?
    GROUP BY corr
    HAVING count > 1
    ORDER BY last_ts DESC
    LIMIT ? OFFSET ?
  `),
  countConversationsChats: aeeDb.prepare(`
    SELECT COUNT(*) as total FROM (
      SELECT corr FROM envelopes WHERE corr LIKE 'CONV_%' AND org_id = ? GROUP BY corr HAVING COUNT(*) > 1
    )
  `),
  // Noise-included variant (Chats tab "include infrastructure events" toggle)
  // — same CONV_ scope, without the count > 1 noise filter.
  getConversationsChatsAll: aeeDb.prepare(`
    SELECT corr, MIN(ts) as first_ts, MAX(ts) as last_ts, COUNT(*) as count
    FROM envelopes
    WHERE corr LIKE 'CONV_%'
      AND org_id = ?
    GROUP BY corr
    ORDER BY last_ts DESC
    LIMIT ? OFFSET ?
  `),
  countConversationsChatsAll: aeeDb.prepare(`
    SELECT COUNT(*) as total FROM (
      SELECT corr FROM envelopes WHERE corr LIKE 'CONV_%' AND org_id = ? GROUP BY corr
    )
  `),
  getConversationsObjectives: aeeDb.prepare(`
    SELECT corr, MIN(ts) as first_ts, MAX(ts) as last_ts, COUNT(*) as count
    FROM envelopes
    WHERE corr LIKE 'OBJ_%'
      AND org_id = ?
    GROUP BY corr
    ORDER BY last_ts DESC
    LIMIT ? OFFSET ?
  `),
  countConversationsObjectives: aeeDb.prepare(`
    SELECT COUNT(*) as total FROM (
      SELECT corr FROM envelopes WHERE corr LIKE 'OBJ_%' AND org_id = ? GROUP BY corr
    )
  `),
  // Workflows: WORKFLOW_BUILDER_* (Workflow Builder UI sessions) plus every
  // WF-shaped execution id — 'WF%' also matches lowercase wf-<slug>-<suffix>
  // (case-insensitive LIKE) and legacy static ids (WF_ai-news-9000-daily,
  // WFRUN_<ulid>) that don't carry the dynamic dash-suffix.
  getConversationsWorkflows: aeeDb.prepare(`
    SELECT corr, MIN(ts) as first_ts, MAX(ts) as last_ts, COUNT(*) as count
    FROM envelopes
    WHERE (corr LIKE 'WORKFLOW%' OR corr LIKE 'WF%')
      AND org_id = ?
    GROUP BY corr
    ORDER BY last_ts DESC
    LIMIT ? OFFSET ?
  `),
  countConversationsWorkflows: aeeDb.prepare(`
    SELECT COUNT(*) as total FROM (
      SELECT corr FROM envelopes WHERE (corr LIKE 'WORKFLOW%' OR corr LIKE 'WF%') AND org_id = ? GROUP BY corr
    )
  `),
  // Governance: AOCL_ (policy/layer trace events) + ANOM_ (behavioral
  // anomaly detections) — both are system-emitted compliance signal, not
  // user-authored content.
  getConversationsGovernance: aeeDb.prepare(`
    SELECT corr, MIN(ts) as first_ts, MAX(ts) as last_ts, COUNT(*) as count
    FROM envelopes
    WHERE (corr LIKE 'AOCL_%' OR corr LIKE 'ANOM_%')
      AND org_id = ?
    GROUP BY corr
    ORDER BY last_ts DESC
    LIMIT ? OFFSET ?
  `),
  countConversationsGovernance: aeeDb.prepare(`
    SELECT COUNT(*) as total FROM (
      SELECT corr FROM envelopes WHERE (corr LIKE 'AOCL_%' OR corr LIKE 'ANOM_%') AND org_id = ? GROUP BY corr
    )
  `),
  getConversationsTools: aeeDb.prepare(`
    SELECT corr, MIN(ts) as first_ts, MAX(ts) as last_ts, COUNT(*) as count
    FROM envelopes
    WHERE corr LIKE 'TOOL_%'
      AND org_id = ?
    GROUP BY corr
    ORDER BY last_ts DESC
    LIMIT ? OFFSET ?
  `),
  countConversationsTools: aeeDb.prepare(`
    SELECT COUNT(*) as total FROM (
      SELECT corr FROM envelopes WHERE corr LIKE 'TOOL_%' AND org_id = ? GROUP BY corr
    )
  `),
  // Rooms: Matrix room-DAG activity — `!<roomId>:quox` corrs are the
  // room-DAG receipts witnessed via the thin appservice bridge, and
  // `matrix_<roomId>` corrs are agent turns inside a bridged room. Both were
  // previously swallowed by the System catch-all with no way to find them.
  getConversationsRooms: aeeDb.prepare(`
    SELECT corr, MIN(ts) as first_ts, MAX(ts) as last_ts, COUNT(*) as count
    FROM envelopes
    WHERE (corr LIKE '!%' OR corr LIKE 'matrix\\_%' ESCAPE '\\')
      AND org_id = ?
    GROUP BY corr
    ORDER BY last_ts DESC
    LIMIT ? OFFSET ?
  `),
  countConversationsRooms: aeeDb.prepare(`
    SELECT COUNT(*) as total FROM (
      SELECT corr FROM envelopes WHERE (corr LIKE '!%' OR corr LIKE 'matrix\\_%' ESCAPE '\\') AND org_id = ? GROUP BY corr
    )
  `),
  // System: the catch-all — everything NOT claimed by Chats/Objectives/
  // Workflows/Governance/Tools/Rooms. This is the precedence rule that
  // guarantees no corr is ever double-counted across tabs or silently
  // dropped: every envelope's corr matches exactly one of the six specific
  // WHERE clauses above, or lands here (AUTH_/MEM_/SESSION_/WAZ_/SHELL_/
  // OPS_/PROF_/FLEET_/AUDIT_/TERM_/ACTION_/STREAM_/mcp-/term-/INBOX_/BQ_/etc
  // — plus any corr shape not yet seen).
  getConversationsSystem: aeeDb.prepare(`
    SELECT corr, MIN(ts) as first_ts, MAX(ts) as last_ts, COUNT(*) as count
    FROM envelopes
    WHERE corr NOT LIKE 'CONV_%'
      AND corr NOT LIKE 'OBJ_%'
      AND corr NOT LIKE 'WORKFLOW%'
      AND corr NOT LIKE 'WF%'
      AND corr NOT LIKE 'AOCL_%'
      AND corr NOT LIKE 'ANOM_%'
      AND corr NOT LIKE 'TOOL_%'
      AND corr NOT LIKE '!%'
      AND corr NOT LIKE 'matrix\\_%' ESCAPE '\\'
      AND org_id = ?
    GROUP BY corr
    ORDER BY last_ts DESC
    LIMIT ? OFFSET ?
  `),
  countConversationsSystem: aeeDb.prepare(`
    SELECT COUNT(*) as total FROM (
      SELECT corr FROM envelopes
      WHERE corr NOT LIKE 'CONV_%'
        AND corr NOT LIKE 'OBJ_%'
        AND corr NOT LIKE 'WORKFLOW%'
        AND corr NOT LIKE 'WF%'
        AND corr NOT LIKE 'AOCL_%'
        AND corr NOT LIKE 'ANOM_%'
        AND corr NOT LIKE 'TOOL_%'
        AND corr NOT LIKE '!%'
        AND corr NOT LIKE 'matrix\\_%' ESCAPE '\\'
        AND org_id = ?
      GROUP BY corr
    )
  `),
  getConversationsAll: aeeDb.prepare(`
    SELECT corr, MIN(ts) as first_ts, MAX(ts) as last_ts, COUNT(*) as count
    FROM envelopes
    WHERE corr NOT LIKE 'FLEET_%'
      AND corr NOT LIKE 'AUDIT_%'
    GROUP BY corr
    ORDER BY last_ts DESC
    LIMIT ? OFFSET ?
  `),
  // TRUST-GATE-1.26 (2026-07-05): watermark-bounded variant for reflection
  // mining. getConversationsAll SCANS every envelope (4.1s at 906K rows /
  // 55K corrs) and the scheduler called it once PER ORG PER TICK — 25 orgs
  // × 4.1s saturated the event loop the moment org count + db size crossed
  // the line (this is reflection-bloat iceberg layer 3: the 1.25 watermark
  // filtered last_ts >= after in JS, AFTER the full scan). WHERE ts >= ?
  // rides idx_ts so each call touches only post-watermark envelopes.
  // The inner subquery + INDEXED BY is load-bearing: with a flat
  // WHERE ts >= ? GROUP BY corr, the optimizer picks idx_corr to satisfy the
  // GROUP BY and scans the WHOLE index (measured 4.2s); forcing idx_ts makes
  // it a range scan + temp b-tree group (measured 18ms on the same data).
  getActiveConversationsSince: aeeDb.prepare(`
    SELECT corr, MAX(ts) as last_ts, COUNT(*) as recent_count
    FROM (SELECT corr, ts FROM envelopes INDEXED BY idx_ts WHERE ts >= ?
          AND corr IN (SELECT corr FROM envelopes WHERE ts >= ? AND intent IN ${MINABLE_INTENTS_SQL}))
    WHERE corr NOT LIKE 'FLEET_%'
      AND corr NOT LIKE 'AUDIT_%'
    GROUP BY corr
  `),
  // quox#518: org-scoped variant for reflection mining. The scheduler
  // always passed orgId; this wiring used to drop it, so every org mined
  // the GLOBAL conversation list (Nx duplicate grind, and memories
  // extracted from other tenants' conversations posted under this org's
  // X-Org-Id). An org with no envelopes of its own is now a free no-op,
  // which is also quox#508's activity floor in its natural form.
  // 2026-10-17: pinned to the (org_id, ts) range. Left alone, SQLite picks the covering
  // idx_envelopes_org_corr_ts on org_id ONLY (it suits GROUP BY corr) and walks the org's whole history
  // whatever the watermark: an 8.5 s loop block after boot on dev. test/reflectionMiningIdlePlan.test.js
  // quox#1193: only corrs carrying an intent the miner learns from (see
  // MINABLE_INTENTS_SQL); slot logs and other agent traffic are never mined.
  getActiveConversationsSinceForOrg: aeeDb.prepare(`
    SELECT corr, MAX(ts) as last_ts, COUNT(*) as recent_count
    FROM (SELECT corr, ts FROM envelopes INDEXED BY idx_envelopes_org_ts WHERE ts >= ? AND org_id = ?
          AND corr IN (SELECT corr FROM envelopes WHERE ts >= ? AND org_id = ? AND intent IN ${MINABLE_INTENTS_SQL}))
    WHERE corr NOT LIKE 'FLEET_%'
      AND corr NOT LIKE 'AUDIT_%'
    GROUP BY corr
  `),
  countEnvelopesByCorr: aeeDb.prepare(`
    SELECT COUNT(*) as count FROM envelopes WHERE corr = ?
  `),
  countConversations: aeeDb.prepare(`
    SELECT COUNT(*) as total FROM (
      SELECT corr
      FROM envelopes
      WHERE corr NOT LIKE 'FLEET_%'
        AND corr NOT LIKE 'AUDIT_%'
        AND corr NOT LIKE 'MEM_%'
        AND corr NOT LIKE 'ERR_%'
        AND corr NOT LIKE 'ACTION_%'
        -- AEE-CORE-2.1: keep in sync with getConversations filter
        AND corr NOT LIKE 'mcp-%'
        AND corr NOT LIKE 'term-%'
        AND corr NOT LIKE 'TOOL_%'
        AND corr NOT LIKE 'STREAM_%'
        AND corr NOT LIKE 'OPS_%'
        AND corr NOT LIKE 'AOCL_%'
      GROUP BY corr
      HAVING COUNT(*) > 1 OR corr LIKE 'OBJ_%'
    )
  `),
  stats: aeeDb.prepare(`
    SELECT
      COUNT(*) as total,
      COUNT(DISTINCT corr) as conversations,
      MIN(ts) as oldest,
      MAX(ts) as newest
    FROM envelopes
    WHERE corr NOT LIKE 'FLEET_%' AND corr NOT LIKE 'AUDIT_%'
  `),
  // AEE-ORG-1 (READ-SCOPE): org-scoped variant of `stats`, used by GET
  // /aee/stats. `stats` above stays unscoped — it backs the dead-code
  // fallback branch in getConversationRowsCached (countStmt ?? stats.get())
  // and is not itself reachable via an unauthenticated HTTP route anymore.
  statsOrgScoped: aeeDb.prepare(`
    SELECT
      COUNT(*) as total,
      COUNT(DISTINCT corr) as conversations,
      MIN(ts) as oldest,
      MAX(ts) as newest
    FROM envelopes
    WHERE corr NOT LIKE 'FLEET_%' AND corr NOT LIKE 'AUDIT_%'
      AND org_id = ?
  `),
  // Dashboard summary (server-source, org-scoped, windowed). Replaces the
  // browser IndexedDB analytics for the /dashboard KPIs + activity feed so a
  // fresh device shows the real numbers. success_rate mirrors the client rule:
  // a conversation (corr) is a success iff it has NO type='error' envelope.
  dashboardConvOrgScoped: aeeDb.prepare(`
    SELECT COUNT(*) as conversations,
           SUM(CASE WHEN has_error = 0 THEN 1 ELSE 0 END) as success_conversations
    FROM (
      SELECT corr, MAX(CASE WHEN type='error' THEN 1 ELSE 0 END) as has_error
      FROM envelopes
      WHERE org_id = ? AND ts >= ?
        AND corr NOT LIKE 'FLEET_%' AND corr NOT LIKE 'AUDIT_%'
      GROUP BY corr
    )
  `),
  dashboardEnvCountOrgScoped: aeeDb.prepare(`
    SELECT COUNT(*) as total FROM envelopes WHERE org_id = ? AND ts >= ?
  `),
  dashboardRecentOrgScoped: aeeDb.prepare(`
    SELECT corr, intent, type, ts FROM envelopes
    WHERE org_id = ? AND ts >= ?
      AND corr NOT LIKE 'FLEET_%' AND corr NOT LIKE 'AUDIT_%'
    ORDER BY ts DESC LIMIT 15
  `),
  // AEE-CORE-4.2: retention GC support.
  // Distinct intents + oldest ts per intent — cheap O(N log N) aggregate on
  // the intent index. We ask the policy resolver what the TTL is, then
  // target-delete with a single range query per intent that has overflow.
  distinctIntents: aeeDb.prepare(`
    SELECT intent, MIN(ts) as oldest, COUNT(*) as n FROM envelopes GROUP BY intent
  `),
  deleteExpiredByIntent: aeeDb.prepare(`
    DELETE FROM envelopes WHERE intent = ? AND ts < ?
  `),
  // AEE-CORE-4.3: orphan detection — envelopes with a reply_to whose
  // parent id no longer exists (retention delete, manual purge, never-
  // synced-from-client, etc.). NOT EXISTS leverages the id primary key.
  findOrphans: aeeDb.prepare(`
    SELECT id, ts, type, intent, corr, reply_to
    FROM envelopes
    WHERE reply_to IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM envelopes p WHERE p.id = envelopes.reply_to)
    ORDER BY ts DESC
    LIMIT ?
  `),
  countOrphans: aeeDb.prepare(`
    SELECT COUNT(*) as n
    FROM envelopes
    WHERE reply_to IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM envelopes p WHERE p.id = envelopes.reply_to)
  `),
  // MCPB-HARDEN-3D: per-session tool-call history for session detail drawer.
  // Filters by session_id stored in the JSON payload, returning tool execution
  // envelopes in reverse-chronological order.
  getSessionCalls: aeeDb.prepare(`
    SELECT id, ts, type, intent, payload, "from"
    FROM envelopes
    WHERE json_extract(payload, '$.session_id') = ?
      AND intent IN ('aocl.tool.execute', 'ops.tool.executed')
    ORDER BY ts DESC
    LIMIT ?
  `),
} : null;

// TRUST-GATE-1.18f: production wiring for the reflection mining scheduler —
// queries the collector's own aeeDb directly (same process as the AEE
// store, unlike the memory service, so no HTTP round-trip is needed here).
function reflectionMiningRowToEnvelope(row) {
  let payload = {};
  try { payload = JSON.parse(row.payload); } catch { payload = {}; }
  return { id: row.id, ts: row.ts, type: row.type, from: row.from, to: row.to, intent: row.intent, corr: row.corr, reply_to: row.reply_to, payload };
}

function reflectionMiningListIdleConversations({ orgId, after }) {
  if (!aeeStatements) return [];
  // TRUST-GATE-1.26: watermark pushed into SQL (see getActiveConversationsSince
  // note). The original `count > 1` meant "the conversation has more than one
  // envelope IN TOTAL" — recent_count only counts post-watermark envelopes,
  // so conversations with exactly one NEW envelope get their total checked
  // via the cheap idx_corr count before being excluded.
  // quox#518: org-scoped when an orgId is supplied (the scheduler always
  // supplies one) — the unscoped path survives only as a defensive fallback.
  const rows = orgId
    ? aeeStatements.getActiveConversationsSinceForOrg.all(after, orgId, after, orgId)
    : aeeStatements.getActiveConversationsSince.all(after, after);
  return rows
    .filter(r => {
      if (r.recent_count > 1) return true;
      return aeeStatements.countEnvelopesByCorr.get(r.corr).count > 1;
    })
    .map(r => ({ corr: r.corr, lastTs: r.last_ts }));
}

const { getConversationEnvelopesForOrg } = require('./lib/aeeOrgReadScope');
function reflectionMiningGetConversationEnvelopes({ orgId, corr, limit }) {
  if (!aeeStatements) return [];
  // BRAIN2-W5 022: scope by org as well as corr (no org => no rows). limit: newest-window read (2026-10-16).
  return getConversationEnvelopesForOrg(aeeStatements, { orgId, corr, limit }).map(reflectionMiningRowToEnvelope);
}

function reflectionMiningQueryRecentEnvelopes({ orgId, after }) {
  if (!aeeStatements) return [];
  // quox#518: org-scoped when an orgId is supplied — pattern detection and
  // proactive alerts must read THIS tenant's envelopes, not the instance's.
  if (orgId) {
    return aeeStatements.queryOrgScoped.all({
      type: null, intent: null, from: null, to: null,
      after, before: null, corr: null, orgId, limit: 2000,
    }).map(reflectionMiningRowToEnvelope);
  }
  return aeeStatements.query.all(null, null, null, null, null, null, null, null, after, after, null, null, 2000)
    .map(reflectionMiningRowToEnvelope);
}

// WebSocket clients for real-time updates
const wsClients = new Set();

// ============================================================================
// AUDIT TRAIL INFRASTRUCTURE (Phase 3 - Memory Overhaul)
// ============================================================================

// Heartbeat buffer for batched AEE storage
const heartbeatBuffer = [];
const HEARTBEAT_FLUSH_SIZE = 10;
const HEARTBEAT_FLUSH_INTERVAL_MS = 30000;

/**
 * Generate ULID for envelope IDs
 */
function generateEnvelopeId() {
  const timestamp = Date.now().toString(36);
  const random = Math.random().toString(36).slice(2, 10);
  return `ENV_${timestamp}_${random}`.toUpperCase();
}

// GOV-E-6: Register the AOCL pipeline's per-layer envelope emitter so layer
// events (aocl.layer.L1.complete, aocl.layer.L3.reject, etc.) flow into the
// AEE audit trail. Registered once at module init — all chat requests share it.
//
// MON-GOV-1c: The same emitter also funnels governance rejections into the
// incident store. Failures here must never surface to the caller — audit
// storage always wins.
try {
  const { setLayerEnvelopeEmitter } = require('./lib/aoclPipeline.js');
  setLayerEnvelopeEmitter((envelope) => {
    try { storeAuditEnvelope(envelope); }
    catch (err) { console.warn('[AOCL] layer envelope emission failed:', err.message); }

    if (voltDb && isGovernanceRejection(envelope)) {
      try {
        const incident = createIncidentFromEnvelope(voltDb, envelope);
        if (incident) {
          // Emit governance.incident.created only on first-insert (new rows).
          // createIncident sets _inserted: true when the row was newly
          // created, false on an idempotent upsert from retry. Timestamp
          // comparison was the previous pattern but broke at millisecond
          // resolution under load.
          if (incident._inserted) {
            try {
              storeAuditEnvelope({
                type: 'event',
                from: 'system.governance',
                to: 'system.aee',
                intent: 'governance.incident.created',
                corr: incident.corr,
                payload: {
                  incident_id: incident.id,
                  org_id: incident.org_id,
                  incident_type: incident.incident_type,
                  severity: incident.severity,
                  layer: incident.layer,
                  policy_id: incident.policy_id,
                  policy_name: incident.policy_name,
                  framework_mapping: incident.framework_mapping,
                  agent_id: incident.agent_id,
                },
              });
            } catch (selfErr) {
              console.warn('[MON-GOV] self-envelope emit failed (non-fatal):', selfErr.message);
            }
            // MON-GOV-3: fan out to configured SIEM webhooks. Fully fire-and-forget —
            // the dispatcher catches its own errors and never returns a rejected promise.
            Promise.resolve(dispatchGovernanceIncident(voltDb, incident))
              .catch((err) => console.warn('[MON-GOV] webhook dispatch failed:', err?.message || err));
            // MON-GOV-INT Phase 1: fan out to configured ticketing targets (Jira first).
            // Same fire-and-forget contract as the SIEM dispatcher above — never
            // throws, never blocks the chat pipeline on a Jira outage.
            Promise.resolve(dispatchGovernanceIncidentTickets({ voltDb, aeeDb }, incident))
              .catch((err) => console.warn('[MON-GOV-INT] ticket dispatch failed:', err?.message || err));
          }
        }
      } catch (incErr) {
        console.warn('[MON-GOV] incident creation failed (non-fatal):', incErr.message);
      }
    }
  });
} catch (err) {
  console.warn('[AOCL] pipeline emitter registration failed (non-fatal):', err.message);
}

/**
 * Store an AEE envelope for audit trail (non-blocking)
 * @param {object} envelope - Envelope data (type, from, to, intent, corr, payload)
 */
// QUOXTRUST T3 (D3 durability): audit-write failure ACCOUNTING. For an
// evidence-first product, an audit envelope that fails to persist is a
// durability breach, not a nuisance to console.warn and forget. Pre-fix the two
// silent paths in storeAuditEnvelope (storage-unavailable-after-config, and a
// throwing INSERT) dropped the receipt with zero durable trace — the exact
// shape of the 30-hour silent-audit outage (a "0 failed" that was a lie because
// the dependency was down). We now COUNT every drop, keep the last error, and
// surface it on /health (which flips to degraded) and /metrics, so an outage is
// detectable instead of invisible. We do NOT fail the action on an audit drop:
// once an external effect (SMTP accept) has happened, returning failure cannot
// undo it and invites a duplicate — that belongs to the T3 execution state
// machine (deferred), not here. This step makes the loss VISIBLE; the state
// machine will make it RECOVERABLE.
//
// Storage that was never configured at init (aeeDb null from the start) is an
// intentional no-AEE deployment, not an outage — those skips are not counted.
// The accounting singleton lives in lib/auditWriteFailures.js so it is unit
// tested against the real code /health + /metrics read.
const AEE_STORAGE_CONFIGURED = !!aeeDb;
const { recordAuditWriteFailure, getAuditWriteFailures } = require('./lib/auditWriteFailures.js');

function storeAuditEnvelope(envelope) {
  if (!aeeDb || !aeeStatements) {
    // Storage was configured at boot but is now unavailable = a real durability
    // event (account it). Never-configured = intentional no-AEE (silent skip).
    if (AEE_STORAGE_CONFIGURED) recordAuditWriteFailure('storage_unavailable');
    return { stored: false, reason: 'storage_unavailable' };
  }

  // QUOXIFY pass 4 (DEVSUITE phase 17): stamp the AOCL classification on slot
  // envelopes. The audit found Slots had AEE + WARD but no AOCL, while QLoop
  // (the reference) carries the full quartet.
  //
  // Stamped HERE, at the choke point, rather than at each of the nine slot
  // emit sites: a classification that a future route forgets to add is a gap
  // that looks exactly like a deliberate omission when someone reads the
  // trail later. One place cannot be forgotten. Scoped to quox.slot.* and
  // additive, so no other envelope type is touched, and an explicit
  // payload.aocl always wins.
  try {
    if (typeof envelope?.intent === 'string' && envelope.intent.startsWith('quox.slot.') && !envelope.payload?.aocl) {
      const { classifySlotAocl } = require('./lib/devSlotEvidence.js');
      envelope = { ...envelope, payload: { ...(envelope.payload || {}), aocl: classifySlotAocl(envelope.intent) } };
    }
  } catch (aoclErr) {
    // Classification is additive evidence; failing to add it must never drop
    // the envelope itself.
    console.warn('[Slots] AOCL classification failed (non-fatal):', aoclErr.message);
  }

  // AEE-ORG-1: derive org_id at the choke point (explicit envelope.org_id >
  // payload.orgId (AOCL envelopes) > org.<id> from/to address > null).
  // Never fabricated — null means genuinely unknown (background/fleet writes).
  // Phase 25: derived before the transcript-storage check so an org's
  // DISABLE_TRANSCRIPT_STORAGE setting override (Settings > Privacy) applies
  // here even though this choke point is used by every envelope type, not
  // just chat transcripts. No org context (null) falls back to the env
  // default, same as before this flag was settable per org.
  const orgId = deriveEnvelopeOrgId(envelope);
  if (platformSettingsStore.getEffectiveFlag(voltDb, orgId, 'DISABLE_TRANSCRIPT_STORAGE').on) {
    // QUOXTRUST WP4.1a (D6): the privacy toggle governs TRANSCRIPT retention,
    // never the fact-of-execution. Content-free execution receipts (the
    // system.tools / system.aocl channels) are MANDATORY and store+witness
    // regardless — a settings flip must not erase "what ran" (codex B5; the
    // 2026-09-28 gauge run scored this exact silent-skip as the binding
    // claim-honesty defect). See lib/mandatoryEvidence.js for the contract.
    const { isMandatoryExecutionEvidence } = require('./lib/mandatoryEvidence.js');
    if (!isMandatoryExecutionEvidence(envelope)) {
      // Transcript-class envelope — storage disabled for this org (or by env
      // default). A deliberate skip, not a delivery: callers holding an
      // evidence OBLIGATION never take this branch (mandatory channel).
      return { stored: false, reason: 'transcript_storage_disabled' };
    }
  }

  try {
    const id = envelope.id || generateEnvelopeId();
    const ts = envelope.ts || new Date().toISOString();
    const raw = JSON.stringify(envelope);

    // Encrypt sensitive fields
    const { payload: encryptedPayload, raw: encryptedRaw } = encryptEnvelopeFields({
      ...envelope,
      id,
      ts,
      payload: envelope.payload
    });

    aeeStatements.insert.run(
      id,
      envelope.v || '1',
      ts,
      envelope.type,
      envelope.from,
      envelope.to,
      envelope.intent,
      envelope.corr || `AUDIT_${Date.now()}`,
      envelope.reply_to || null,
      encryptedPayload,
      encryptedRaw,
      envelope.priority || 'normal',  // EVD-1c: AEE spec requires priority
      orgId
    );

    // WARD: witness this envelope (fire-and-forget, SPEC §10.3)
    // ORG-VIEW-SCOPE: pass the already-derived orgId (AEE-ORG-1 choke point
    // above) through as a row attribute/tag on the ward_entries row — never
    // affects chain/seq/hash selection.
    const intent = envelope.intent || '';
    if (intent.startsWith('aocl.')) {
      wardHookAOCL({ ...envelope, id, ts, org_id: orgId });
    } else {
      wardHookAEE({ ...envelope, id, ts, org_id: orgId });
    }

    // CLI-2d: Broadcast to unified event stream (fire-and-forget)
    eventStreamHub.broadcast({ ...envelope, id, ts });

    // WP4.1b: confirmed delivery signal — the evidence outbox settles a
    // receipt debt ONLY on this. Additive; every pre-4.1b caller ignores it.
    return { stored: true, id };
  } catch (err) {
    // QUOXTRUST T3: account the dropped receipt (see recordAuditWriteFailure
    // above) so a persistent audit-store failure is visible on /health +
    // /metrics rather than a warn nobody reads.
    recordAuditWriteFailure('insert_failed', err);
    console.warn('[Audit] Failed to store envelope:', err.message);
    return { stored: false, reason: 'insert_failed' };
  }
}

// QUOXTRUST WP4.1b — flush owed evidence obligations (emit-only recovery; the
// callback can reach emitToolEvidence and nothing capable of dispatch, so a
// receipt is recovered but an effect is NEVER replayed). Shared by the boot
// recovery pass and the WP4.2 reconciler tick.
function reEmitOwedReceiptsNow(limit = 200) {
  if (!aeeDb) return { reEmitted: 0, delivered: 0, stillOwed: 0 };
  const { emitToolEvidence } = require('./lib/toolEvidence.js');
  return executionLedger.reEmitOwedObligations(aeeDb, (ob) => emitToolEvidence({
    toolName: ob.tool,
    ctx: ob.ctx || { orgId: ob.org_id },
    actionCommitment: ob.actionCommit,
    recovery: { intent_state: ob.intent_state },
    corrId: ob.corr || undefined,
    durationMs: 0,
    success: ob.intent_state === 'confirmed',
    error: ob.intent_state === 'confirmed' ? undefined
      : (ob.intent_error || `intent settled ${ob.intent_state}`),
    source: 'outbox-recovery',
    storeAuditEnvelope,
  }), { limit });
}

// ============================================================================
// QuoxAgent Event Bridge — push local activity to Agent Stream
// Fire-and-forget POSTs to the local QuoxAgent API so chat + terminal sessions
// appear in the real-time Agent Stream WebSocket feed.
// ============================================================================
const QUOXAGENT_API = process.env.QUOXAGENT_API_URL || 'http://172.18.0.1:9847/api/v1';

// quox#439 (AEE-ORG-BACKFILL P6): envelope construction extracted to
// lib/agentEventEnvelope.js so it is unit-tested against the real code.
// Events/sessions may now carry org_id; callers pass the org they resolved
// (jwtOrgId, authResult.user.org_id) so agent-stream rows stop landing in
// the untagged bucket the P2 read-scope close hid from tenants.
const { buildAgentEventEnvelope, buildAgentSessionEnvelope } = require('./lib/agentEventEnvelope.js');

function emitAgentSession(session) {
  // 1. Push to QuoxAgent WebSocket stream
  fetch(`${QUOXAGENT_API}/agents/sessions`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(session),
    signal: AbortSignal.timeout(3000),
  }).catch(() => {});

  // 2. Store AEE envelope for session lifecycle
  storeAuditEnvelope(buildAgentSessionEnvelope(session));
}

function emitAgentEvent(event) {
  // 1. Push to QuoxAgent WebSocket stream (fire-and-forget)
  fetch(`${QUOXAGENT_API}/agents/events`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(event),
    signal: AbortSignal.timeout(3000),
  }).catch(() => {});

  // 2. Store as AEE envelope for audit trail + WARD witness
  storeAuditEnvelope(buildAgentEventEnvelope(event));
}

/**
 * auditOp — lightweight AEE envelope for any state-changing operation.
 * Use for config writes, container actions, plugin management, etc.
 * @param {string} intent - e.g. 'ops.docker.container.action'
 * @param {object} payload - operation details
 * @param {object} [opts] - optional: from, to, corr
 */
function auditOp(intent, payload, opts = {}) {
  storeAuditEnvelope({
    type: 'event',
    from: opts.from || 'system.collector',
    to: opts.to || 'audit.ops',
    intent,
    corr: opts.corr || `OPS_${Date.now()}`,
    payload,
  });
}

// quox#503: kill switch / DEFCON collector chokepoint backstop — logic
// lives in lib/safetyDispatchGate.js (unit-tested there); this wrapper just
// binds this process's voltDb/storeAuditEnvelope so call sites read cleanly.
function checkAgentInvokeSafetyGate(ctx) {
  return safetyDispatchGate.checkAgentInvokeSafetyGate({ db: voltDb, storeAuditEnvelope }, ctx);
}

/**
 * Flush heartbeat buffer to AEE storage
 */
function flushHeartbeatBuffer() {
  if (heartbeatBuffer.length === 0 || !aeeDb) return;

  const toFlush = heartbeatBuffer.splice(0, heartbeatBuffer.length);
  const today = new Date().toISOString().slice(0, 10);

  try {
    const insertMany = aeeDb.transaction((envelopes) => {
      for (const data of envelopes) {
        const envelope = {
          id: generateEnvelopeId(),
          v: '1',
          ts: data.received_at || new Date().toISOString(),
          type: 'event',
          from: `quoxagent.${data.host_id}`,
          to: 'system.collector',
          intent: 'quoxagent.heartbeat',
          corr: `FLEET_${today}`,
          payload: {
            host_id: data.host_id,
            status: data.status,
            resources: data.resources,
            agent_version: data.agent?.version
          }
        };
        const { payload: encryptedPayload, raw: encryptedRaw } = encryptEnvelopeFields(envelope);
        aeeStatements.insert.run(
          envelope.id, envelope.v, envelope.ts, envelope.type,
          envelope.from, envelope.to, envelope.intent, envelope.corr,
          null, encryptedPayload, encryptedRaw,
          envelope.priority || 'normal',  // EVD-1c
          null  // AEE-ORG-1: fleet heartbeats carry no tenant context — honest null, not fabricated
        );
      }
    });
    insertMany(toFlush);
    console.log(`[Audit] Flushed ${toFlush.length} heartbeats to AEE`);
  } catch (err) {
    console.warn('[Audit] Heartbeat flush failed:', err.message);
  }
}

// Flush heartbeat buffer periodically
const heartbeatFlushTimer = setInterval(flushHeartbeatBuffer, HEARTBEAT_FLUSH_INTERVAL_MS);
if (heartbeatFlushTimer.unref) heartbeatFlushTimer.unref();

/**
 * Store fleet snapshot (called every 5 minutes)
 */
function storeFleetSnapshot() {
  if (!aeeDb || agents.size === 0) return;

  const now = Date.now();
  let connected = 0, stale = 0, dead = 0;

  const agentSnapshots = [];
  for (const [hostId, agent] of agents) {
    const age = now - agent.received_at;
    let status = 'connected';
    if (age > AGENT_DEAD_MS) { status = 'dead'; dead++; }
    else if (age > AGENT_TIMEOUT_MS) { status = 'stale'; stale++; }
    else { connected++; }

    agentSnapshots.push({
      host_id: hostId,
      status: status,
      cpu_percent: agent.resources?.cpu?.usage_percent,
      memory_percent: agent.resources?.memory?.usage_percent,
      agent_version: agent.agent?.version
    });
  }

  storeAuditEnvelope({
    type: 'event',
    from: 'system.collector',
    to: 'audit',
    intent: 'fleet.snapshot',
    corr: `FLEET_${new Date().toISOString().slice(0, 10)}`,
    payload: {
      snapshot_type: 'periodic',
      total: agents.size,
      connected,
      stale,
      dead,
      agents: agentSnapshots
    }
  });

  console.log(`[Audit] Fleet snapshot: ${agents.size} agents (${connected} connected, ${stale} stale, ${dead} dead)`);
}

// Fleet snapshot every hour (was 5min — caused DB bloat with 288 snapshots/day)
const fleetSnapshotTimer = setInterval(storeFleetSnapshot, 60 * 60 * 1000);
if (fleetSnapshotTimer.unref) fleetSnapshotTimer.unref();

// QUOXTRUST D3 (2026-09-29): witnessed-source retention exemption. Both AEE
// prune paths (this blanket prune and runRetentionGc) must NOT delete an
// envelope that has been WITNESSED into the append-only WARD chain — a witness
// is a promise the source can be reproduced (retention is a floor, not a
// ceiling). We ATTACH ward.db to the aee connection ONCE as `warddb` and delete
// only rows absent from ward_entries. FAIL-SAFE: if ward.db cannot be attached
// the prune SKIPS entirely (over-retain rather than delete evidence blind).
let _wardAttachedForPrune = false;
function ensureWardAttachedForPrune() {
  if (_wardAttachedForPrune) return true;
  try {
    if (!aeeDb) return false;
    const wardPath = process.env.WARD_DB_PATH || '/var/lib/quox/ward.db';
    if (!require('fs').existsSync(wardPath)) return false;
    aeeDb.exec(`ATTACH DATABASE '${wardPath.replace(/'/g, "''")}' AS warddb`);
    aeeDb.prepare('SELECT 1 FROM warddb.ward_entries LIMIT 1').get();
    _wardAttachedForPrune = true;
    console.log('[AEE GC] ward.db attached for witnessed-source retention exemption');
    return true;
  } catch (e) {
    if (/already in use|already.*attach/i.test(e.message || '')) { _wardAttachedForPrune = true; return true; }
    console.warn('[AEE GC] ward attach failed — prune will SKIP (fail-safe, evidence protection):', e.message);
    return false; // not cached: retried next cycle
  }
}

/**
 * AEE retention policy — prune old envelopes daily.
 * Keeps chat/audit envelopes for 90 days, fleet snapshots for 7 days.
 * WITNESSED envelopes are exempt (QUOXTRUST D3) and this prune SKIPS if ward.db
 * cannot be attached (fail-safe).
 */
let _aeePruneRunning = false;
async function pruneAEEDatabase() {
  if (!aeeDb) return;
  if (!ensureWardAttachedForPrune()) {
    console.warn('[Audit] Retention prune SKIPPED — ward.db not attached (fail-safe, evidence protection)');
    return;
  }
  if (_aeePruneRunning) return;
  _aeePruneRunning = true;
  const t0 = Date.now();
  try {
    const { fleetDeleted, oldDeleted } = await pruneAeeBatched(aeeDb);
    if (fleetDeleted + oldDeleted > 0) {
      console.log(`[Audit] Retention prune (witnessed-exempt): ${fleetDeleted} fleet snapshots, ${oldDeleted} old envelopes deleted (${Date.now() - t0}ms)`);
    }
  } catch (err) {
    console.warn('[Audit] Retention prune failed:', err.message);
  } finally {
    _aeePruneRunning = false;
  }
}

// Run retention on startup and then daily
// First run delayed 5 min (was 10 s): a boot-triggered prune must not re-arm a wedge on every restart.
const pruneStartupTimer = setTimeout(pruneAEEDatabase, 300000);
if (pruneStartupTimer.unref) pruneStartupTimer.unref();
const pruneDailyTimer = setInterval(pruneAEEDatabase, 24 * 60 * 60 * 1000);
if (pruneDailyTimer.unref) pruneDailyTimer.unref();

/**
 * MON-GOV retention — purge resolved/closed/false_positive incidents
 * after 730 days so the operational-response table stays bounded.
 * Open + investigating incidents are never auto-purged.
 */
function pruneGovernanceIncidents() {
  if (!voltDb) return;
  try {
    const cutoff = new Date(Date.now() - 730 * 24 * 60 * 60 * 1000).toISOString();
    const deleted = voltDb.prepare(`
      DELETE FROM governance_incidents
      WHERE status IN ('resolved', 'closed', 'false_positive')
        AND COALESCE(resolved_at, updated_at) < ?
    `).run(cutoff).changes;
    if (deleted > 0) {
      console.log(`[MON-GOV] retention prune: ${deleted} closed incidents older than 730 days deleted`);
    }
  } catch (err) {
    console.warn('[MON-GOV] retention prune failed:', err.message);
  }
}

const govPruneStartupTimer = setTimeout(pruneGovernanceIncidents, 15000);
if (govPruneStartupTimer.unref) govPruneStartupTimer.unref();
const govPruneDailyTimer = setInterval(pruneGovernanceIncidents, 24 * 60 * 60 * 1000);
if (govPruneDailyTimer.unref) govPruneDailyTimer.unref();

// ============================================================================
// SSE Streaming Infrastructure for Chat
// ============================================================================

// Active SSE connections by query_id
const sseClients = new Map();

/**
 * Broadcast to a specific query's SSE client
 * @param {string} queryId - The query ID to broadcast to
 * @param {object} data - The data to send
 */
function broadcastToQuery(queryId, data) {
  const client = sseClients.get(queryId);
  if (client && !client.finished) {
    client.write(`data: ${JSON.stringify(data)}\n\n`);
  }
}

/**
 * Broadcast thinking/progress update to a query
 * @param {string} queryId - The query ID
 * @param {string} agent - The agent name
 * @param {string} message - The thinking message
 * @param {string} stage - The stage (routing, processing, generating, etc.)
 * @param {object} extra - Additional data (routing info, tool calls, etc.)
 */
function sendThinking(queryId, agent, message, stage = 'processing', extra = {}) {
  const ts = new Date().toISOString();

  // Broadcast to SSE client
  broadcastToQuery(queryId, {
    type: 'thinking',
    agent,
    message,
    stage,
    ts,
    ...extra
  });

  // Persist to AEE audit trail (Phase 3)
  storeAuditEnvelope({
    type: 'stream',
    from: `agent.${agent || 'system'}`,
    to: 'audit',
    intent: 'agent.thinking',
    corr: queryId,
    payload: {
      stage,
      message,
      ...extra
    }
  });
}

/**
 * Send a response chunk to a query
 * @param {string} queryId - The query ID
 * @param {string} content - The text chunk
 */
function sendChunk(queryId, content) {
  broadcastToQuery(queryId, {
    type: 'chunk',
    content,
    ts: new Date().toISOString()
  });
}

/**
 * End the stream for a query
 * @param {string} queryId - The query ID
 * @param {object} metadata - Optional metadata (token count, etc.)
 */
function endStream(queryId, metadata = {}) {
  broadcastToQuery(queryId, {
    type: 'done',
    ...metadata,
    ts: new Date().toISOString()
  });

  // Clean up
  const client = sseClients.get(queryId);
  if (client) {
    client.end();
    sseClients.delete(queryId);
  }
}

/**
 * Send an error to a query
 * @param {string} queryId - The query ID
 * @param {string} error - Error message
 */
function sendError(queryId, error) {
  broadcastToQuery(queryId, {
    type: 'error',
    error,
    ts: new Date().toISOString()
  });
  endStream(queryId);
}

// FIX-11 boot guard: test-only env flags must not appear in production
// per feedback_test_env_flags_in_prod.md
const { guardTestEnvFlags } = require('./lib/bootGuard.js');
const _bootGuardResult = guardTestEnvFlags(process.env);
if (_bootGuardResult.shouldAbort) {
  console.error(`[boot] Refusing to start with test-only env flags set: ${_bootGuardResult.presentFlags.join(',')}. Set ALLOW_TEST_FLAGS=true to bypass (test contexts only).`);
  process.exit(2);
}
if (_bootGuardResult.presentFlags.length > 0) {
  console.warn(`[boot] WARNING: test-only env flags active under ALLOW_TEST_FLAGS=true: ${_bootGuardResult.presentFlags.join(',')}`);
}

const app = express();
app.set('trust proxy', 1); // Behind nginx reverse proxy
// SECURITY FIX: Replace wildcard CORS with validated origin allowlist.
// QCL-2 EXEMPTION: the public /quoxchat/* widget subtree must accept arbitrary
// customer origins (a widget embeds on any site) — those routes are secured
// per-widget by domainGuard (widget_id + allowed_domains) on the POST, NOT by
// this dashboard-origin allowlist. Without this, the browser CORS preflight to
// /quoxchat/message from a customer domain (e.g. https://quox.ai) is 403'd
// ("cors_rejected") and the widget can never send a message cross-origin.
const corsDashboardOptions = {
  origin: function(origin, callback) {
    // Allow requests with no origin (same-origin, server-to-server, curl)
    if (!origin) return callback(null, true);
    if (isCollectorAllowedOrigin(origin, {
      allowedOrigins: ALLOWED_ORIGINS,
      dashboardPorts: COLLECTOR_DASHBOARD_PORTS,
    })) {
      return callback(null, true);
    }
    callback(new Error('Not allowed by CORS'));
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS']
};
const corsWidgetOptions = {
  origin: true,          // reflect any origin — public widget subtree
  credentials: false,    // widgets are cookieless; domainGuard is the real gate
  methods: ['GET', 'POST', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Accept'],
};
app.use(cors(function corsDelegate(req, callback) {
  const p = req.path || '';
  const isWidgetPublic = p === '/quoxchat' || p.startsWith('/quoxchat/');
  callback(null, isWidgetPublic ? corsWidgetOptions : corsDashboardOptions);
}));
app.use(helmet({ contentSecurityPolicy: false })); // CSP off — API service, not serving HTML

// Qluster Phase 4 — capture the RAW body of the one signed operational POST
// route (backups/trigger) BEFORE the blanket express.json() below parses it.
// body-parser's json middleware no-ops once req._body is already set (see
// node_modules/body-parser/lib/types/json.js:102), so a route-local
// verify:() parser registered AFTER the global one (as /webhook/slack etc.
// do further down this file) never actually fires its verify callback once
// a preceding blanket app.use(express.json()) has already consumed the
// stream — it must run FIRST instead. requireQlusterScope's signed-envelope
// check hashes req.rawBody (see lib/qlusterEnroll.js buildSignedMessage);
// the GET download route carries no body so needs no capture (req.rawBody
// stays undefined → hashes as sha256('')).
app.use('/api/v1/qluster/backups/trigger', express.json({
  limit: '1mb',
  verify: (req, res, buf) => { req.rawBody = buf.toString(); }
}));

// Qluster Phase 5b — the governed-delegation POST is likewise a signed
// operational route (agent.delegate → isOperationalScope → requires an
// Ed25519-signed envelope). requireQlusterScope hashes req.rawBody, so capture
// it here BEFORE the blanket express.json() consumes the stream (same reason
// as backups/trigger above).
app.use('/api/v1/qluster/delegate', express.json({
  limit: '1mb',
  verify: (req, res, buf) => { req.rawBody = buf.toString(); }
}));

app.use(express.json({ limit: '1mb' }));

// INCIDENT-700: names the blocking route in our own log (see lib/eventLoopWatchdog.js).
const loopWatchdog = require('./lib/eventLoopWatchdog').create();
loopWatchdog.start();
app.use(loopWatchdog.middleware);
app.get('/api/internal/loop-watchdog', loopWatchdog.handler);

// COLLECTOR-AUTH #52 — default-deny auth gate, registered before every route
// so allowlist completeness is provable by construction (docs/STREAM_COLLECTOR_AUTH_PLAN.md §3).
// Defaults to SHADOW mode (log-only, never rejects) until COLLECTOR_AUTH_ENFORCE=enforce.
const collectorAuthGate = require('./utils/collectorAuthGate');
app.use(collectorAuthGate);
console.log(`[collector-auth] gate registered mode=${process.env.COLLECTOR_AUTH_ENFORCE === 'enforce' ? 'enforce' : 'shadow'}`);

// ============================================================================
// GLOBAL RATE LIMIT (quox#598) — backstop, not a throttle on real use.
// ============================================================================
// Before this, rate limiting was a handful of narrow per-route buckets
// (chatLimiter/toolLimiter/etc. below) across ~460+ routes, so almost every
// route had NO ceiling at all. This adds two generous, always-on buckets
// mounted right after the auth gate (so req.user/req.service are already
// populated — collectorAuthGate's userGate sets them even in shadow mode):
//   - per-IP:  blunts a single unauthenticated source flooding the box.
//   - per-org: blunts a single compromised/misbehaving authenticated org
//     hammering across many IPs. Only applied when a verified org exists
//     (from the JWT/service auth already run by the gate above, never a
//     client-supplied org_id body field — that would let an attacker pick
//     their own bucket).
// Defaults are set well above the sum of the existing per-route buckets
// (chat 30/min + tool 60/min + task 100/min + ... per IP) so legitimate
// dashboard/agent traffic never trips this; it exists to catch abuse the
// narrow buckets don't cover. Exempt: health/readiness, CORS preflight,
// INTERNAL_SERVICE_KEY-authenticated service-to-service calls (fleet
// agents, internal service mesh), and long-lived SSE/streaming connections
// (throttling those mid-stream would drop a legitimate open dashboard tab
// rather than blunt abuse — a stream is one held connection, not a request
// burst). Configurable via env; see .env.example.
const GLOBAL_RATE_LIMIT_WINDOW_MS = parseInt(process.env.COLLECTOR_GLOBAL_RATE_LIMIT_WINDOW_MS || '60000', 10);
const GLOBAL_RATE_LIMIT_MAX_PER_IP = parseInt(process.env.COLLECTOR_GLOBAL_RATE_LIMIT_MAX_PER_IP || '1200', 10);
const GLOBAL_RATE_LIMIT_MAX_PER_ORG = parseInt(process.env.COLLECTOR_GLOBAL_RATE_LIMIT_MAX_PER_ORG || '3000', 10);
const GLOBAL_RATE_LIMIT_ENABLED = process.env.COLLECTOR_GLOBAL_RATE_LIMIT_DISABLED !== 'true';

// Long-lived SSE endpoints (GET, one held connection per client — not a
// request burst). POST-based streaming (quoxchat widget, quoxchat/message
// with { stream: true }) is exempted below via a body check instead, since
// it shares a path with non-streaming requests.
const GLOBAL_RATE_LIMIT_STREAM_PATHS = new Set(['/chat/stream', '/chat/stream-mock', '/voice/speak/stream']);

function isGlobalRateLimitExempt(req) {
  if (req.method === 'OPTIONS') return true; // CORS preflight carries no auth/body
  if (req.service) return true; // INTERNAL_SERVICE_KEY-authenticated service-to-service call
  if (req.path === '/health' || req.path === '/version' || req.path.startsWith('/api/v1/health')) return true;
  if (GLOBAL_RATE_LIMIT_STREAM_PATHS.has(req.path)) return true;
  if (req.body && req.body.stream === true) return true; // POST SSE (quoxchat widget/message)
  return false;
}

const globalIpRateLimiter = rateLimit({
  windowMs: GLOBAL_RATE_LIMIT_WINDOW_MS,
  max: GLOBAL_RATE_LIMIT_MAX_PER_IP,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'rate_limited', scope: 'ip' },
  skip: (req) => !GLOBAL_RATE_LIMIT_ENABLED || isGlobalRateLimitExempt(req),
});

const globalOrgRateLimiter = rateLimit({
  windowMs: GLOBAL_RATE_LIMIT_WINDOW_MS,
  max: GLOBAL_RATE_LIMIT_MAX_PER_ORG,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'rate_limited', scope: 'org' },
  // Only ever keyed by an auth-derived org (req.user.org_id, set by
  // collectorAuthGate's userGate above from a verified JWT/MCP token) — a
  // request with no verified org is skipped below rather than falling back
  // to a client-suppliable key, so a caller can't choose its own bucket.
  keyGenerator: (req) => req.user?.org_id || 'unscoped',
  skip: (req) => !GLOBAL_RATE_LIMIT_ENABLED || isGlobalRateLimitExempt(req) || !req.user?.org_id,
});

app.use(globalIpRateLimiter);
app.use(globalOrgRateLimiter);
console.log(`[rate-limit] global backstop registered ip=${GLOBAL_RATE_LIMIT_MAX_PER_IP}/${GLOBAL_RATE_LIMIT_WINDOW_MS}ms org=${GLOBAL_RATE_LIMIT_MAX_PER_ORG}/${GLOBAL_RATE_LIMIT_WINDOW_MS}ms enabled=${GLOBAL_RATE_LIMIT_ENABLED}`);

// Rate limiting for sensitive endpoints
const chatLimiter = rateLimit({ windowMs: 60_000, max: 30, message: { error: 'Too many requests' } });
const terminalLimiter = rateLimit({ windowMs: 60_000, max: 20, message: { error: 'Too many terminal sessions' } });
const toolLimiter = rateLimit({ windowMs: 60_000, max: 60, message: { error: 'Too many tool calls' } });
// BRAIN2-W11: internal model routes (/internal/embed, /internal/rerank). User callers keep the
// 60/min cap; trusted service-key callers (quoxbrain backfill + live query embeds) are exempt so
// a backfill can never 429 an interactive search into a silent keyword-only fallback.
const internalModelLimiter = rateLimit({ windowMs: 60_000, max: 60, skip: (req) => !!req.service, message: { error: 'Too many model calls' } });
const feedbackLimiter = rateLimit({ windowMs: 3600_000, max: 10, message: { error: 'Too many submissions, please try again later' } });
const errorReportLimiter = rateLimit({ windowMs: 60_000, max: 20, message: { error: 'Too many error reports' } });
const taskLimiter = rateLimit({ windowMs: 60_000, max: 100, message: { error: 'Task service rate limit exceeded' } });

const scanLimiter = rateLimit({ windowMs: 60_000, max: 5, message: { error: 'Too many scans, please wait' } });

// Public VOX share-link lookups are unauthenticated — anyone with a link can
// hit them. Cap per-IP to blunt bulk enumeration/scraping of published
// waypoints (only 'public'-tier ones are ever revealed, but even that set
// shouldn't be cheaply harvestable).
const spatialPublicLimiter = rateLimit({ windowMs: 60_000, max: 60, message: { error: 'rate_limited' } });

// Calendar-Q's GET /oauth/callback is unauthenticated by necessity (Google's
// redirect carries no bearer token — see lib/calendarq/api.js's oauth
// section). Per-IP cap blunts state-token guessing against that one route;
// the state token itself (single-use, expiring) is the real guard.
const calendarqOauthCallbackLimiter = rateLimit({ windowMs: 60_000, max: 30, message: { error: 'rate_limited' } });

// Adaptive limiter: task-service background requests get a higher ceiling
const adaptiveChatLimiter = (req, res, next) => {
  const limiter = req.headers['x-quox-source'] === 'task-service' ? taskLimiter : chatLimiter;
  limiter(req, res, next);
};

// Health check
// Roadmap Viewer plugin — serve STRATEGIC_ROADMAP.json + plan docs
app.get('/api/v1/roadmap', (req, res) => {
  try {
    const roadmapPath = hostPath('STRATEGIC_ROADMAP.json');
    const data = JSON.parse(require('fs').readFileSync(roadmapPath, 'utf8'));
    res.json(data);
  } catch (err) {
    res.status(404).json({ error: 'Roadmap not found', message: err.message });
  }
});

// QUOXIDENTITY P3 (territory F): the slot-binding store + a SEPARATE
// devSlotsStore instance bound to the same aeeDb accessor as the one
// created later (Phase 3, ~L6692) — createDevSlotsStore is a pure factory
// (no side effects, no module state beyond closures over aeeDb), so a
// second instance here is safe and avoids reordering the existing
// DEVSUITE-SLOTS block just to satisfy this route's earlier position.
const agentSlotBindings = require('./lib/agentSlotBindings.js').createAgentSlotBindingsStore({ getDb: () => aeeDb });
// quox#1171: a user-made agent may slot_say only into its admin-bound slot (lib/slotTools.js).
require('./lib/slotTools.js').configureSlotAgentScope({
  isOrgCustomAgent: (args) => require('./lib/agentIdResolver.js').isUserMadeOrgAgent(args),
  getBinding: (args) => agentSlotBindings.getBinding(args),
});
const devSlotsForIdentity = require('./lib/devSlotsStore.js').createDevSlotsStore({ getDb: () => aeeDb });

// QUOXIDENTITY P1 (territory B): the attach kit. Auth: requireServiceOrUserAuth()
// like siblings; the handler itself further requires actor_type 'agent' AND an
// attach_lease_id claim (see lib/agentAttachKit.js, docs/QUOXIDENTITY_P1_CONTRACT.md).
// QUOXIDENTITY P3 (territory F): kit.slot hydration deps (getSlotBinding/getSlot/
