const { createAgentAttachKitHandler } = require('./lib/agentAttachKit.js');
app.get('/api/v1/agent-attach/kit', requireServiceOrUserAuth(), createAgentAttachKitHandler({
  audit: storeAuditEnvelope,
  getSlotBinding: (args) => agentSlotBindings.getBinding(args),
  getSlot: (args) => devSlotsForIdentity.getSlot(args),
  isPluginLicensed: isPluginLicensedForOrg,
}));

// QUOXIDENTITY P2 (territory D): the handoff endpoint. Same gate shape as
// the kit route above (requireServiceOrUserAuth() + the handler's own
// attach-lease requirement) — see lib/agentAttachHandoff.js,
// docs/QUOXIDENTITY_P2_CONTRACT.md.
const { createAgentAttachHandoffHandler } = require('./lib/agentAttachHandoff.js');
app.post('/api/v1/agent-attach/handoff', requireServiceOrUserAuth(), createAgentAttachHandoffHandler({ audit: storeAuditEnvelope }));

// QUOXIDENTITY P4 (territory H): detach witnessing symmetry — see
// docs/QUOXIDENTITY_P4_CONTRACT.md §5, lib/agentAttachDetach.js. Same gate
// shape as the kit/handoff routes above. Witness-only: auth (territory A)
// owns lease state; this endpoint never mutates a lease, it just makes the
// CLI's detach notice visible in the collector's own AEE stream, closing the
// loop kit-fetch and handoff witnessing already opened (P1/P2).
const { createAgentAttachDetachHandler } = require('./lib/agentAttachDetach.js');
app.post('/api/v1/agent-attach/detach', requireServiceOrUserAuth(), createAgentAttachDetachHandler({ audit: storeAuditEnvelope }));

// INBOXQ-1: governed email-management surface (/api/v1/inboxq/*). Native
// collector routes (not a proxy) — the IMAP/SMTP plumbing, the email_account
// vault kind and the strong approval gate already live here. Gate stack:
// requireServiceOrUserAuth -> resolve caller org -> per-org licence('inboxq')
// -> handler -> AEE witness (quox.inbox.*). P1 (custom folders + safe IMAP
// move): an APPROVED 'file' proposal now executes a real, safe UID MOVE
// (never COPY+EXPUNGE); 'block'/'draft' remain decision-only. See
// lib/inboxq/api.js.
{
  const { registerInboxqRoutes } = require('./lib/inboxq/api.js');
  const { resolveOrgId: resolveInboxqOrgId } = require('./lib/feedApiHandlers.js');
  const inboxqStoreForLlm = require('./lib/inboxq/store.js');
  const { buildClassifierLlm } = require('./lib/inboxq/classifierLlm.js');

  // Selectable classifier model (cost control): an OPT-IN, budget-capped LLM
  // tie-break for classify.js's genuinely-ambiguous mail (AMBIGUOUS_THRESHOLD).
  // buildClassifierLlm (lib/inboxq/classifierLlm.js) is pure DI so it is unit
  // testable in isolation; server.js's job here is just wiring in the REAL
  // deps — the same model invocation helper the /api/internal/agents/invoke
  // fast path uses (attemptAnthropicApiInvoke), and the same key resolvers
  // (getClaudeKeys/getProviderKeys) already used elsewhere in this file —
  // rather than a new HTTP round trip or a hand-rolled provider client.
  // buildInboxqClassifierLlm(orgId) builds a fresh org-scoped llm(msg) fn per
  // call, so each org's own inboxq_settings.classifier_model (see store.js's
  // AVAILABLE_CLASSIFIER_MODELS, curated cheap tiers only) is honoured.
  const buildInboxqClassifierLlm = buildClassifierLlm({
    store: inboxqStoreForLlm,
    getClaudeKeys,
    getProviderKeys,
    invokeAnthropic: attemptAnthropicApiInvoke,
    fetchImpl: fetch,
  });

  registerInboxqRoutes(app, {
    requireAuth: requireServiceOrUserAuth(),
    resolveOrgId: (req) => resolveInboxqOrgId(req),
    isPluginLicensed: isPluginLicensedForOrg,
    // codex F04: approving/denying a filing proposal is a human decision.
    // requireHumanAdmin rejects agent tokens + service keys and sends its own
    // response; adapt it to (req,res,next) for the resolve route.
    requireHuman: (req, res, next) => { if (requireHumanAdmin(req, res)) next(); },
    audit: (e) => storeAuditEnvelope({ from: 'agent.inboxq', to: 'audit.system', ...e }),
    llmForOrg: buildInboxqClassifierLlm,
  });
  console.log('[inboxq] governed routes registered at /api/v1/inboxq/*');

  // INBOXQ-AGENT (P2b): the agent tool satellite (lib/inboxqTools.js) calls
  // inboxq/api.js's pure handlers in-process and needs the SAME
  // storeAuditEnvelope closure this route registration just wired above —
  // same DI pattern as actionToolHandlers.js's setAuditFn, since the module
  // has no other way to reach a server.js-local function.
  const { setInboxqToolsAuditFn } = require('./lib/inboxqTools.js');
  setInboxqToolsAuditFn((e) => storeAuditEnvelope({ from: 'agent.inboxq', to: 'audit.system', ...e }));
  // QUOXON-ASK lane J: quox_cli / quox_cli_write evidence (content-free receipt on
  // system.tools + argv on audit.system), WARD-witnessed through the same choke.
  require('./lib/quoxCliTools.js').setQuoxCliAuditFn((e) => storeAuditEnvelope(e));
  // QUOXON-ASK P2: build the quox_cli leaf index (SITE-CLI asks per leaf) once at boot, off
  // the request path, so no turn pays for it. A failure leaves the lazy build in place.
  setImmediate(() => {
    try {
      const t0 = Date.now();
      const r = require('./lib/quoxCli/candidates.js').rankCandidateLeaves('list', { k: 1 });
      console.log(`[quox_cli] leaf index ready (source=${r.source}) in ${Date.now() - t0}ms`);
    } catch (err) { console.warn('[quox_cli] leaf index build failed (lazy build on first ask):', err && err.message); }
  });

  // INBOXQ background sync scheduler. DARK unless INBOXQ_SYNC_ENABLED=1 (env
  // master, registered in envRegistry); then only orgs whose inboxq_settings
  // opt in are synced at their own cadence. The triad lives in syncAccount.
  const { createInboxqScheduler } = require('./lib/inboxq/scheduler.js');
  const { fetchSince: inboxqFetchSince } = require('./lib/inboxq/imap.js');
  const { classify: inboxqClassify } = require('./lib/inboxq/classify.js');
  const { resolveEmailCredential } = require('./lib/inboxq/credential.js');
  const inboxqScheduler = createInboxqScheduler({
    resolveCredential: (account) => resolveEmailCredential(account.orgId, account.credentialId),
    fetchSince: inboxqFetchSince,
    classify: inboxqClassify,
    llmForOrg: buildInboxqClassifierLlm,
  });
  inboxqScheduler.start();
}

// CALENDAR-Q L2-C0: governed read-only status surface (/api/v1/calendarq/*).
// Phase C0 ships the data contracts + store + this status/layers skeleton
// only — no provider sync, no write path yet. registerCalendarQRoutes is
// deliberately fail-closed (see lib/calendarq/api.js's module doc comment):
// a missing auth/org-resolver/licence dep refuses to register these routes
// at all, with a clear log here, rather than silently skipping them.
try {
  const { registerCalendarQRoutes } = require('./lib/calendarq/api.js');
  const { resolveOrgId: resolveCalendarqOrgId } = require('./lib/feedApiHandlers.js');
  registerCalendarQRoutes(app, {
    requireAuth: requireServiceOrUserAuth(),
    resolveOrgId: (req) => resolveCalendarqOrgId(req),
    isPluginLicensed: isPluginLicensedForOrg,
    audit: (e) => storeAuditEnvelope({ from: 'agent.calendarq', to: 'audit.system', ...e }),
    oauthCallbackRateLimiter: calendarqOauthCallbackLimiter,
  });
  console.log('[calendarq] governed routes registered at /api/v1/calendarq/*');

  // L2-C1 U4: the agent tool satellite (lib/calendarqTools.js) calls
  // lib/calendarq/agenda.js's reads in-process and needs the SAME
  // storeAuditEnvelope closure the route registration just wired above —
  // same DI pattern as lib/inboxqTools.js's setInboxqToolsAuditFn.
  const { setCalendarqToolsAuditFn } = require('./lib/calendarqTools.js');
  setCalendarqToolsAuditFn((e) => storeAuditEnvelope({ from: 'agent.calendarq', to: 'audit.system', ...e }));

  // L2-C1 U2: background sync scheduler. DARK unless CALENDARQ_SYNC_ENABLED=1
  // (env master, registered in envRegistry) — see lib/calendarq/scheduler.js
  // for the full triad.
  const { createCalendarqScheduler } = require('./lib/calendarq/scheduler.js');
  const calendarqScheduler = createCalendarqScheduler({ fetchImpl: fetch });
  calendarqScheduler.start();
} catch (e) {
  console.error('[calendarq] routes NOT registered — refusing to start this surface open:', e?.message);
}

// NOTESQ: governed notes surface (/api/v1/notesq/*). The single entry point:
// requireServiceOrUserAuth -> resolve caller org -> per-org licence('notesq',
// awaited, fail closed) -> proxy to quoxbrain's service-key-only /notesq/*
// routes -> AEE witness (quox.notes.*, never note content). See lib/notesq/api.js.
{
  const { registerNotesqRoutes } = require('./lib/notesq/api.js');
  const { resolveOrgId: resolveNotesqOrgId } = require('./lib/feedApiHandlers.js');
  const notesqCall = registerNotesqRoutes(app, {
    requireAuth: requireServiceOrUserAuth(),
    resolveOrgId: (req) => resolveNotesqOrgId(req),
    isPluginLicensed: isPluginLicensedForOrg,
    audit: (e) => storeAuditEnvelope({ from: 'service.notesq', to: 'audit.system', ...e }),
    deriveActorType,
    isHumanAdmin,
    // quox#1015: import/batch job summaries persist in aeeDb (lazy: aeeDb opens after routes register)
    importJobStore: require('./lib/notesq/import/jobStore.js').createImportJobStore(() => aeeDb),
  });
  // NOTESQ agent tools consume the SAME notesqCall the routes use (no second path).
  require('./lib/notesqTools.js').setNotesqToolsCall(notesqCall);
  // AQ-9D P5: record agent-edit accept/reject outcomes to the wisdom store.
  require('./lib/toolApprovalStore.js').onFinalized(require('./lib/notesqWisdom.js').recordOutcome);
  // NOTESQ scheduled notes (AQ-9D P4): server-side loop, claims per period in quoxbrain.
  try {
    const { createNotesqScheduler } = require('./lib/notesq/scheduler.js');
    createNotesqScheduler({
      notesqCall,
      isPluginLicensed: isPluginLicensedForOrg,
      audit: (e) => storeAuditEnvelope({ to: 'audit.system', ...e }),
      fetchImpl: fetch,
    }).start();
  } catch (e) {
    console.error('[notesq] scheduler NOT started:', e?.message);
  }
  // Cortex's brain_save/update/delete write NotesQ notes directly; same evidence shape.
  require('./lib/notesq/evidence.js').setNotesAudit((e) => storeAuditEnvelope({ to: 'audit.system', ...e }));
  console.log('[notesq] governed routes registered at /api/v1/notesq/*');
}

// CONTACTSQ: governed contacts layer (/api/v1/contactsq/*), P0. Encrypted at
// rest (per-contact DEK under a master-derived KEK), blind-index lookup, WARD
// evidence without PII (quox.contacts.*). Substrate is FREE in Core: no
// licence gate. Fail closed: a missing dep refuses to register the surface.
try {
  const { registerContactsqRoutes } = require('./lib/contactsq/api.js');
  const { resolveOrgId: resolveContactsqOrgId } = require('./lib/feedApiHandlers.js');
  const contactsqService = registerContactsqRoutes(app, {
    requireAuth: requireServiceOrUserAuth(),
    resolveOrgId: (req) => resolveContactsqOrgId(req),
    audit: (e) => storeAuditEnvelope({ from: 'service.contactsq', to: 'audit.system', ...e }),
    // History tab log trail: this org's quox.contacts.* envelopes, read through the collector's own AEE statement
    // and decryptEnvelopeRow (payloads are encrypted at rest; never raw SQL on ciphertext).
    readEnvelopes: aeeStatements
      ? require('./lib/contactsq/history.js').createEnvelopeReader({ run: (p) => aeeStatements.queryOrgScopedPrefix.all(p), decryptRow: decryptEnvelopeRow })
      : undefined,
    deriveActorType,
    isHumanAdmin,
  });
  // Raw-number outbound boundary (quox-voice): ONE policy engine decides, no parallel DNC list.
  require('./lib/contactsq/policyCheck.js').registerPolicyCheckRoute(app, {
    requireAuth: requireServiceOrUserAuth(),
    audit: (e) => storeAuditEnvelope({ from: 'service.contactsq', to: 'audit.system', ...e }),
    deriveActorType,
  });
  // CONTACTSQ agent tools consume the SAME service the routes use (no second path).
  require('./lib/contactsqTools.js').setContactsqToolsService(contactsqService);
  // P3b: InboxQ/CalendarQ identity helper writes touchpoints through the SAME service (fail-soft, optional).
  require('./lib/contactsq/identity.js').setService(contactsqService);
  // P4 retention reaper: wall-clock armed (default 03:15 UTC), NEVER run at boot; per-org kill switch is the
  // retention_reaper_enabled setting (Settings tab / `quox contacts settings`). See lib/contactsq/retention.js.
  require('./lib/contactsq/scheduler.js').createContactsqScheduler({ service: contactsqService }).start();
  console.log('[contactsq] governed routes registered at /api/v1/contactsq/*');
} catch (e) {
  console.error('[contactsq] routes NOT registered — refusing to start this surface open:', e?.message);
}

// QUOXIDENTITY P3 (territory F): slot binding CRUD — see
// docs/QUOXIDENTITY_P3_CONTRACT.md, lib/agentAttachSlotBinding.js. Same
// requireLicence('quoxslots') gate shape as the existing /api/v1/slots
// routes (~L6722 onward): binding an address is a slot-touching act. PUT/
// DELETE additionally require a human org admin (requireHumanAdmin, inside
// the handler — NOT an attach token, binding is an admin act); GET is open
// to any authenticated org member or attach token.
const {
  createSetSlotBindingHandler,
  createDeleteSlotBindingHandler,
  createGetSlotBindingHandler,
} = require('./lib/agentAttachSlotBinding.js');
app.put('/api/v1/agent-attach/:agentId/slot-binding', requireServiceOrUserAuth(), requireLicence('quoxslots', 'QuoxSlots'), createSetSlotBindingHandler({
  agentSlotBindings, devSlots: devSlotsForIdentity, audit: storeAuditEnvelope,
}));
app.delete('/api/v1/agent-attach/:agentId/slot-binding', requireServiceOrUserAuth(), requireLicence('quoxslots', 'QuoxSlots'), createDeleteSlotBindingHandler({
  agentSlotBindings, audit: storeAuditEnvelope,
}));
app.get('/api/v1/agent-attach/:agentId/slot-binding', requireServiceOrUserAuth(), requireLicence('quoxslots', 'QuoxSlots'), createGetSlotBindingHandler({
  agentSlotBindings,
}));

// VULCAN-DASH S2/S3: agent activity read (stats overview + history timeline).
// Reads the agent's shared (org_id, agent_id) memory namespace SERVER-SIDE
// with the internal service key + agent_scope=1, so the dashboard can see the
// durable facts an attach-bound CLI session left under user_id='service'
// (invisible to a browser user JWT, which is role=user). Org is the caller's
// resolved org (resolveRequestOrgId — never a client-supplied one), so there
// is no cross-tenant read. Named agents only (the default personal assistant
// has no shared namespace). Degrades to an ok:false empty body, never throws.
app.get('/api/v1/agents/:agentId/activity', requireAuth(), async (req, res) => {
  try {
    const { fetchAgentActivity } = require('./lib/agentActivity.js');
    const { isAgentScopedIdentity } = require('./lib/memoryImplant.js');
    const agentId = String(req.params.agentId || '').toLowerCase();
    if (!isAgentScopedIdentity(agentId)) {
      return res.status(400).json({ error: 'not_a_scoped_agent', message: 'This agent has no shared (org, agent) memory namespace.' });
    }
    const orgId = resolveRequestOrgId(req);
    const memoryServiceUrl = process.env.MEMORY_SERVICE_URL || 'http://memory:3103';
    const result = await fetchAgentActivity({ orgId, agentId, limit: req.query.limit, memoryServiceUrl });
    const { latestAgentEnvelopeAt, withLastSeen } = require('./lib/agentActivity.js');
    result.stats = withLastSeen(result.stats, latestAgentEnvelopeAt(aeeDb, { orgId, agentId }));
    return res.status(200).json({ agent_id: agentId, org_id: orgId, ...result });
  } catch (err) {
    console.error(`[AgentActivity] route error: ${err.message}`);
    return res.status(200).json({ ok: false, memories: [], stats: { total: 0 }, error: 'internal' });
  }
});

// QUOXHAT P3 — read-only provider certification matrix: per-provider
