// claim. Static data, auth-gated for consistency with its sibling panels.
app.get('/api/v1/observability/provider-compat', requireAuth(), (req, res) => {
  const { PROVIDER_COMPAT } = require('./lib/providerCompat');
  res.json({ ok: true, providers: PROVIDER_COMPAT });
});

// QUOXHAT P0 — read-only per-turn tool manifest baseline (counts, origin
// decomposition, cap/fallback-leg status). Org-scoped via the verified JWT
// org (resolveRequestOrgId); feeds the Settings + Mirror baseline panels.
// Measurement only: no hat behaviour exists yet.
app.get('/api/v1/observability/tool-turns', requireAuth(), (req, res) => {
  try {
    const orgId = resolveRequestOrgId(req);
    if (!orgId) return res.status(403).json({ error: 'org_id_required' });
    const limit = Math.min(parseInt(req.query.limit, 10) || 100, 500);
    const stats = getTurnToolStats({ orgId, limit });
    return res.json({ ok: true, org_id: orgId, ...stats });
  } catch (err) {
    console.error('[QUOXHAT-P0] tool-turns route error:', err.message);
    return res.status(500).json({ ok: false, error: 'internal' });
  }
});

// AGH-CHAIN-4: per-agent honesty leaderboard endpoints.
const { aghChainOrgId } = require('./lib/aghChainOrg.js');
app.get('/api/v1/agh-chain/leaderboard', requireServiceOrUserAuth(), (req, res) => {
  try {
    const orgId = aghChainOrgId(req);
    if (!orgId) return res.status(403).json({ error: 'org_id required' });
    const window = req.query.window || '24h';
    if (!['24h', '7d', '30d'].includes(window)) {
      return res.status(400).json({ error: 'window must be 24h, 7d, or 30d' });
    }
    const result = honestyRollup.getOrgLeaderboard(orgId, window);
    return res.json(result);
  } catch (e) {
    return res.status(500).json({ error: String(e?.message || e) });
  }
});

