// AGH-CHAIN-5: public opt-in honesty stats endpoint.
// Gated by AGH_CHAIN_FEDERATE_STATS env flag. No auth (intentionally public).
// Payload is integer counts only — text/IDs/envelopes are excluded by schema.
app.get('/api/public/honesty-stats', (req, res) => {
  if (process.env.AGH_CHAIN_FEDERATE_STATS !== 'true') {
    return res.status(503).json({ error: 'opted_out', message: 'AGH_CHAIN_FEDERATE_STATS is not enabled on this install' });
  }
  try {
    const window = req.query.window || '30d';
    if (!['24h', '7d', '30d'].includes(window)) {
      return res.status(400).json({ error: 'window must be 24h, 7d, or 30d' });
    }
    const stats = federatedStatsAggregator.computeStats(window);
    // Self-validate before responding (defense in depth)
    const v = validateFederatedStatsPayload(stats);
    if (!v.valid) {
      console.error('[AGH-CHAIN-5] internal schema validation failed:', v.errors);
      return res.status(500).json({ error: 'internal_schema_violation' });
    }
    return res.json(stats);
  } catch (e) {
    return res.status(500).json({ error: String(e?.message || e) });
  }
});

