// AUD-WS-5: Assurance pack export. Auditor-accessible (compliance.export_pack).
// Returns a single signed JSON document for the requested period.
//
// POST /api/v1/governance/assurance-pack
// Body: { from, to, org_id?, include?: { ward, volt, audit } }
// ===== COMMANDERQ P5: Plan-as-Artifact (signed, WARD-witnessed, approve-once,
// deviation-gated). Routes are auth-gated (service key for the loopback tool
// self-fetch, or a user JWT). The agent PROPOSES approval; a human resolves it.
app.post('/api/v1/artifacts/plan', requireServiceOrUserAuth(), async (req, res) => {
  try {
    const body = req.body || {};
    const orgId = resolveRequestOrgId(req);
    const createdBy = req.user?.id ? `human.${req.user.id}` : 'agent.quox';
    const corr = resolveCorrelationId(req, body);
    const deviation_policy = body.deviation_policy || 'gated';
    const planBody = {
      title: body.title,
      intent: body.intent,
      steps: Array.isArray(body.steps) ? body.steps : [],
      deviation_policy,
      approval: (body.approval && typeof body.approval === 'object')
        ? body.approval
        : { required: deviation_policy === 'gated' },
    };
    const result = await createSignedArtifact('plan', planBody, {
      orgId, createdBy, corr,
      getHookKeypair,
      storeAuditEnvelope,
      toolsUsed: Array.isArray(body.tools_used) ? body.tools_used : [],
      evidenceRefs: Array.isArray(body.evidence_refs) ? body.evidence_refs : [],
      sourceTurn: body.session_id || corr || null,
    });
    if (result.error) return res.status(400).json({ error: result.error, errors: result.errors });
    const artifact = result.artifact;
    // Queryable server-side source of truth (the AEE envelope is the witnessed evidence).
    try { insertArtifact(voltDb, artifact); }
    catch (e) { console.warn('[Artifact] persist failed (non-fatal):', e.message); }
    // Approve-once: ONE HITL card per plan, only when gated + approval required.
    // Never auto-approves — a human resolves the card.
    let approval_filed = false;
    if (planBody.deviation_policy === 'gated' && planBody.approval.required) {
      try {
        const { fileInboxCard } = require('./lib/commanderqWriteTools.js');
        const card = await fileInboxCard({
          orgId,
          kind: 'approval',
          title: `Plan approval — ${planBody.title || 'untitled'}`.slice(0, 120),
          bodyMd: `**${planBody.title || 'Plan'}**\n\n${planBody.intent || ''}\n\n${planBody.steps.length} step(s). Approve to authorise execution; deviation from this plan will require re-approval.`,
          payload: { artifact_id: artifact.artifact_id, artifact_type: 'plan', kind_detail: 'plan_approval', what: { action: 'authorise plan', target: `plan ${artifact.artifact_id}`, summary: `authorise execution of plan "${String(planBody.title || 'untitled').slice(0, 100)}" (${planBody.steps.length} step(s))` } },
        });
        approval_filed = !!(card && card.ok);
      } catch (e) { console.warn('[Artifact] approval card failed (non-fatal):', e.message); }
    }
    const verify = verifySignedArtifact(artifact, { getHookKeypair });
    return res.json({
      artifact_id: artifact.artifact_id,
      artifact_type: artifact.artifact_type,
      created_at: artifact.created_at,
      signature: {
        sig_type: artifact.signature.sig_type,
        key_id: artifact.signature.key_id,
        ...(artifact.signature.warning ? { warning: artifact.signature.warning } : {}),
      },
      approval_filed,
      verify,
    });
  } catch (err) {
    console.error('[Artifact/plan] error:', err.message);
    return res.status(500).json({ error: 'artifact_create_failed', message: err.message });
  }
});

