app.post('/api/v1/artifacts/plan/:id/diff', requireServiceOrUserAuth(), async (req, res) => {
  try {
    const body = req.body || {};
    const orgId = resolveRequestOrgId(req);
    const artifact = getStoredArtifact(voltDb, req.params.id, orgId);
    if (!artifact) return res.status(404).json({ error: 'artifact_not_found' });
    if (artifact.artifact_type !== 'plan') return res.status(400).json({ error: 'not_a_plan_artifact' });
    const diff = computePlanDiff(artifact, Array.isArray(body.actual_steps) ? body.actual_steps : []);
    // Deviation gate: a gated plan that deviated re-files ONE approval card.
    let reapproval_filed = false;
    if (diff.reapproval_required) {
      try {
        const { fileInboxCard } = require('./lib/commanderqWriteTools.js');
        const card = await fileInboxCard({
          orgId,
          kind: 'approval',
          title: 'Plan deviation — re-approval needed',
          bodyMd: `Plan **${artifact.body?.title || artifact.artifact_id}** deviated from its approved steps (missing: ${diff.missing.length}, extra: ${diff.extra.length}, changed: ${diff.changed.length}). Re-approval required before continuing.`,
          payload: { artifact_id: artifact.artifact_id, artifact_type: 'plan', kind_detail: 'plan_deviation', what: { action: 're-authorise deviated plan', target: `plan ${artifact.artifact_id}`, summary: `let plan "${String(artifact.body?.title || artifact.artifact_id).slice(0, 100)}" continue after deviating (missing ${diff.missing.length}, extra ${diff.extra.length}, changed ${diff.changed.length})` } },
        });
        reapproval_filed = !!(card && card.ok);
      } catch (e) { console.warn('[Artifact] reapproval card failed (non-fatal):', e.message); }
    }
    return res.json({ artifact_id: artifact.artifact_id, ...diff, reapproval_filed });
  } catch (err) {
    return res.status(500).json({ error: 'artifact_diff_failed', message: err.message });
  }
});

// ===== COMMANDERQ P8: commitment ledger. A promise = a signed `commitment`
// artifact (immutable evidence) + a mutable ledger row (open → fulfilled |
// escalated | cancelled) so Q can find overdue promises and chase/escalate.
app.post('/api/v1/commitments', requireServiceOrUserAuth(), async (req, res) => {
  try {
    const body = req.body || {};
    const orgId = resolveRequestOrgId(req);
    const createdBy = req.user?.id ? `human.${req.user.id}` : 'agent.quox';
    const corr = resolveCorrelationId(req, body);
    const cbody = (body.body && typeof body.body === 'object') ? body.body : body;
    const result = await createSignedArtifact('commitment', { status: 'open', ...cbody }, {
      orgId, createdBy, corr, getHookKeypair, storeAuditEnvelope,
      toolsUsed: Array.isArray(body.tools_used) ? body.tools_used : [],
      evidenceRefs: Array.isArray(body.evidence_refs) ? body.evidence_refs : [],
      sourceTurn: body.session_id || corr || null,
    });
    if (result.error) return res.status(400).json({ error: result.error, errors: result.errors });
    try { insertArtifact(voltDb, result.artifact); insertCommitment(voltDb, result.artifact); }
    catch (e) { console.warn('[Commitment] persist failed (non-fatal):', e.message); }
    return res.json({
      commitment_id: result.artifact.artifact_id,
      status: 'open',
      signature: { sig_type: result.artifact.signature.sig_type, key_id: result.artifact.signature.key_id },
      verify: verifySignedArtifact(result.artifact, { getHookKeypair }),
    });
  } catch (err) {
    console.error('[Commitment/create] error:', err.message);
    return res.status(500).json({ error: 'commitment_create_failed', message: err.message });
  }
});

