app.post('/api/v1/commitments/:id/resolve', requireServiceOrUserAuth(), async (req, res) => {
  try {
    const body = req.body || {};
    const orgId = resolveRequestOrgId(req);
    const r = resolveLedgerCommitment(voltDb, req.params.id, orgId, body.status, body.note);
    if (!r.ok) return res.status(r.error === 'not_found' ? 404 : 400).json(r);
    // Evidence the resolution (WARD-witnessed; counts/status only, no note text).
    try {
      storeAuditEnvelope({
        type: 'event',
        from: req.user?.id ? `human.${req.user.id}` : 'agent.quox',
        to: 'system.collector',
        intent: 'quox.commitment.resolved',
        corr: resolveCorrelationId(req, body),
        reply_to: null,
        org_id: orgId,
        payload: { commitment_id: req.params.id, status: body.status, note_len: (body.note || '').length },
      });
    } catch (_) { /* evidence best-effort */ }
    // Escalation surfaces to a human via the inbox.
    let escalation_filed = false;
    if (body.status === 'escalated') {
      try {
        const { fileInboxCard } = require('./lib/commanderqWriteTools.js');
        const card = await fileInboxCard({
          orgId, kind: 'approval', title: 'Commitment escalated',
          bodyMd: `A commitment was escalated${body.note ? `: ${body.note}` : '.'}`,
          payload: { commitment_id: req.params.id, kind_detail: 'commitment_escalation', what: { action: 'decide escalated commitment', target: `commitment ${req.params.id}`, summary: `decide on escalated commitment ${req.params.id}${body.note ? `: ${String(body.note).slice(0, 140)}` : ''}` } },
        });
        escalation_filed = !!(card && card.ok);
      } catch (e) { console.warn('[Commitment] escalation card failed (non-fatal):', e.message); }
    }
    return res.json({ ...r, escalation_filed });
  } catch (err) {
    return res.status(500).json({ error: 'commitment_resolve_failed', message: err.message });
  }
});

