// ── COMMANDERQ P9 (C1+C3): contactability + tripwire policy engine ────────────
// Governed proactivity, TCPA/PECR-shaped: DENY-BY-DEFAULT, opt-in only, quiet
// hours + frequency caps. This is the RULES ENGINE ONLY — nothing here sends a
// message or places a call ("minus audio"). Deciding and doing are separate so
// the engine carries zero outbound risk.

// Check whether a proposed outbound contact is permitted RIGHT NOW. Read-only.
app.post('/api/v1/commanderq/contactability/check', requireServiceOrUserAuth(), async (req, res) => {
  try {
    const body = req.body || {};
    const orgId = resolveRequestOrgId(req);
    const recipient = String(body.recipient || '').trim();
    const channel = String(body.channel || '').trim();
    if (!recipient || !channel) return res.status(400).json({ error: 'recipient_and_channel_required' });
    const nowIso = typeof body.now === 'string' && body.now ? body.now : new Date().toISOString();
    const policy = contactabilityStore.getPolicy(voltDb, orgId, recipient, channel);
    const recent = contactabilityStore.recentAttempts(voltDb, orgId, recipient, channel, {});
    const decision = evaluateContactability({ policy, nowIso, recentAttempts: recent });
    return res.json({ recipient, channel, ...decision, has_policy: !!policy });
  } catch (err) {
    return res.status(500).json({ error: 'contactability_check_failed', message: err.message });
  }
});

// PROPOSE a contactability policy (opt-in / quiet hours / frequency). AGENTS
// PROPOSE, THEY NEVER GRANT: this files a human approval card and changes NO
// state. Actual opt-in is a human act via the grant route below.
app.post('/api/v1/commanderq/contactability/policy/propose', requireServiceOrUserAuth(), async (req, res) => {
  try {
    const body = req.body || {};
    const orgId = resolveRequestOrgId(req);
    const recipient = String(body.recipient || '').trim();
    const channel = String(body.channel || '').trim();
    if (!recipient || !channel) return res.status(400).json({ error: 'recipient_and_channel_required' });
    let filed = false;
    try {
      const { fileInboxCard } = require('./lib/commanderqWriteTools.js');
      const card = await fileInboxCard({
        orgId,
        kind: 'approval',
        title: `Contactability opt-in — ${recipient} via ${channel}`.slice(0, 120),
        bodyMd: `An agent proposes recording contact consent for **${recipient}** on **${channel}**.\n\nPurpose: ${String(body.purpose || 'unspecified').slice(0, 300)}\nProposed quiet hours: ${body.quiet_start || '—'}–${body.quiet_end || '—'}, caps: min ${body.min_interval_minutes || 0}m / max ${body.max_per_day || 0}/day.\n\nApprove ONLY with a lawful basis and the recipient's actual opt-in. Approving grants consent; declining leaves contact denied-by-default.`,
        payload: { kind_detail: 'contactability_optin', recipient, channel, proposed: body, what: { action: 'record contact consent', target: `${recipient} via ${channel}`, summary: `record that ${recipient} opted in to contact on ${channel}` } },
      });
      filed = !!(card && card.ok);
    } catch (e) { console.warn('[Contactability] propose card failed (non-fatal):', e.message); }
    return res.json({ proposed: true, approval_filed: filed, note: 'No consent recorded. A human must grant opt-in; contact stays denied by default until then.' });
  } catch (err) {
    return res.status(500).json({ error: 'contactability_propose_failed', message: err.message });
  }
});

// GRANT a contactability opt-in. HUMAN-ONLY: rejects agent/service-key callers so
// an agent can never consent on a recipient's behalf (TCPA/PECR). On grant, sets
// the policy AND records a signed P4 `consent` artifact as immutable evidence.
app.post('/api/v1/commanderq/contactability/policy/grant', requireServiceOrUserAuth(), async (req, res) => {
  try {
    if (!req.user || !req.user.id) {
      return res.status(403).json({ error: 'human_grant_required', message: 'Contactability consent can only be granted by an authenticated user, never by an agent or service key.' });
    }
    const body = req.body || {};
    // QUOXTRUST T7 (FND_..SAGZ) — org MUST come from the authenticated identity, never a
    // caller-supplied org header/body first. The old derivation put the x-org-id header
    // ahead of the identity, so any logged-in user could write a consent artifact +
    // contactability policy into ANOTHER org by naming it in the header (and the tripwire
    // path reads these to decide who to auto-dial). resolveRequestOrgId returns the user's
    // own org and only honours an explicit org for a trusted service caller — and this
    // route is human-only anyway (the check above rejects service/agent callers).
    const orgId = resolveRequestOrgId(req);
    if (!orgId) return res.status(400).json({ error: 'org_context_required', message: 'No authenticated org context.' });
    const recipient = String(body.recipient || '').trim();
    const channel = String(body.channel || '').trim();
    const basis = String(body.basis || '').trim();
    if (!recipient || !channel || !basis) return res.status(400).json({ error: 'recipient_channel_basis_required' });
    const grantedAt = new Date().toISOString();
    // Immutable signed consent evidence (P4 consent body: subject/scope/channel/granted_at/basis).
    const result = await createSignedArtifact('consent', {
      subject: recipient, scope: `contactability:${String(body.purpose || 'general')}`.slice(0, 120),
      channel, granted_at: grantedAt, basis,
    }, { orgId, createdBy: `human.${req.user.id}`, corr: resolveCorrelationId(req, body), getHookKeypair, storeAuditEnvelope });
    if (result.error) return res.status(400).json({ error: result.error, errors: result.errors });
    try { insertArtifact(voltDb, result.artifact); } catch (e) { console.warn('[Contactability] consent persist failed (non-fatal):', e.message); }
    contactabilityStore.setPolicy(voltDb, {
      orgId, recipient, channel, opt_in: true, basis,
      quiet_start: body.quiet_start, quiet_end: body.quiet_end,
      tz_offset_minutes: body.tz_offset_minutes,
      min_interval_minutes: body.min_interval_minutes, max_per_day: body.max_per_day,
      consent_artifact_id: result.artifact.artifact_id, updated_by: `human.${req.user.id}`, updated_at: grantedAt,
    });
    return res.json({ granted: true, recipient, channel, consent_artifact_id: result.artifact.artifact_id, verify: verifySignedArtifact(result.artifact, { getHookKeypair }) });
  } catch (err) {
    return res.status(500).json({ error: 'contactability_grant_failed', message: err.message });
  }
});

