// Register a standing-watch tripwire (C1). PROPOSE-ONLY: stored as 'proposed';
// when a brief would fire it must still clear the contactability check before any
// contact. Files a human card for activation.
app.post('/api/v1/commanderq/contactability/watch', requireServiceOrUserAuth(), async (req, res) => {
  try {
    const body = req.body || {};
    const orgId = resolveRequestOrgId(req);
    const name = String(body.name || '').trim();
    const condition = String(body.condition || '').trim();
    if (!name || !condition) return res.status(400).json({ error: 'name_and_condition_required' });
    const id = `WATCH_${Date.now().toString(36).toUpperCase()}_${require('crypto').randomBytes(5).toString('hex').toUpperCase()}`;
    const createdBy = req.user?.id ? `human.${req.user.id}` : 'agent.quox';
    contactabilityStore.registerWatch(voltDb, {
      orgId, id, name, condition, channel: body.channel, recipient: body.recipient,
      status: 'proposed', created_by: createdBy, created_at: new Date().toISOString(),
    });
    let filed = false;
    try {
      const { fileInboxCard } = require('./lib/commanderqWriteTools.js');
      const card = await fileInboxCard({
        orgId, kind: 'approval',
        title: `Standing watch — ${name}`.slice(0, 120),
        bodyMd: `An agent proposes a standing watch:\n\n**${name}**\nCondition: ${condition}\n\nWhen it fires it will PROPOSE a contact; any outbound still passes the deny-by-default contactability engine first. Approve to activate the watch.`,
        payload: { kind_detail: 'standing_watch', watch_id: id, what: { action: 'activate standing watch', target: `watch ${id}`, summary: `activate standing watch "${String(name).slice(0, 80)}" (condition: ${condition.slice(0, 100)})` } },
      });
      filed = !!(card && card.ok);
    } catch (e) { console.warn('[Contactability] watch card failed (non-fatal):', e.message); }
    return res.json({ watch_id: id, status: 'proposed', approval_filed: filed });
  } catch (err) {
    return res.status(500).json({ error: 'watch_register_failed', message: err.message });
  }
});

// ── COMMANDERQ P10 (F1+F3): governed outbound calls ("CommanderQ calls you") ──
// The decide-and-call spine. DENY-BY-DEFAULT: a call intent only becomes
// 'intended' when the P9 contactability engine ALLOWS it; otherwise it is
// recorded 'blocked' (evidence of restraint). The actual audio bridge (Discord
// voice) is NOT wired here — this governs, evidences, and state-manages the call
// so the audio is the last wire, not the governance.

// Raise an outbound call intent (e.g. a tripwire wants to warn the owner). Runs
// the contactability check and records the outcome. Does NOT place audio.
app.post('/api/v1/commanderq/calls/intent', requireServiceOrUserAuth(), async (req, res) => {
  try {
    const body = req.body || {};
    const orgId = resolveRequestOrgId(req);
    const recipient = String(body.recipient || '').trim();
    const channel = String(body.channel || '').trim();
    if (!recipient || !channel) return res.status(400).json({ error: 'recipient_and_channel_required' });
    const nowIso = new Date().toISOString();
    const policy = contactabilityStore.getPolicy(voltDb, orgId, recipient, channel);
    const recent = contactabilityStore.recentAttempts(voltDb, orgId, recipient, channel, {});
    const decision = evaluateContactability({ policy, nowIso, recentAttempts: recent });
    const allowed = decision.decision === 'allow';
    const callRef = `CALL_${Date.now().toString(36).toUpperCase()}_${require('crypto').randomBytes(4).toString('hex').toUpperCase()}`;
    const createdBy = req.user?.id ? `human.${req.user.id}` : 'agent.quox';
    callStore.createCall(voltDb, {
      orgId, callRef, channel, recipient, purpose: body.purpose, trigger: body.trigger,
      state: allowed ? 'intended' : 'blocked',
      blockReason: allowed ? null : ((decision.reasons || []).join(',') || decision.decision),
      createdBy,
    });
    try {
      storeAuditEnvelope({
        type: 'event', from: createdBy, to: 'audit.system',
        intent: 'quox.call.intent', corr: resolveCorrelationId(req, body),
        payload: { call_ref: callRef, recipient, channel, decision: decision.decision, reasons: decision.reasons, purpose: body.purpose || null, trigger: body.trigger || null },
      });
    } catch (_) { /* evidence best-effort */ }
    // Attempt the actual dial via the provider bridge. Un-credentialed today, so
    // this returns a clean needs_credentials / needs_hookup status — the honest
    // "one step from live" signal, recorded, never a fake success.
    let provider = null;
    if (allowed) {
      provider = await callProviders.placeOutboundCall({ channel, recipient, message: body.purpose || 'CommanderQ has an update for you.' });
    }
    return res.json({
      call_ref: callRef,
      state: allowed ? 'intended' : 'blocked',
      contactability: decision,
      next_allowed_at: decision.next_allowed_at || null,
      provider,
      note: allowed
        ? `Call intent raised. Dial status: ${provider ? provider.status : 'n/a'} (providers are one cred/hookup from live — see /calls/providers).`
        : `Not calling: ${(decision.reasons || []).join(', ') || decision.decision}. Deny-by-default holds until consent + quiet-hours/frequency allow.`,
    });
  } catch (err) {
    return res.status(500).json({ error: 'call_intent_failed', message: err.message });
  }
});

// End a call with a receipted, signed P4 call_summary artifact (F3).
app.post('/api/v1/commanderq/calls/:ref/end', requireServiceOrUserAuth(), async (req, res) => {
  try {
    const body = req.body || {};
    const orgId = resolveRequestOrgId(req);
    const ref = req.params.ref;
    const summary = String(body.summary || '').trim();
    if (!summary) return res.status(400).json({ error: 'summary_required' });
    const call = callStore.getCall(voltDb, ref, orgId);
    if (!call) return res.status(404).json({ error: 'call_not_found' });
    const createdBy = req.user?.id ? `human.${req.user.id}` : 'agent.quox';
    const result = await createSignedArtifact('call_summary', {
      call_ref: ref, started_at: call.created_at, summary,
      participants: Array.isArray(body.participants) ? body.participants : [call.recipient, 'agent.quox'],
    }, { orgId, createdBy, corr: resolveCorrelationId(req, body), getHookKeypair, storeAuditEnvelope });
    if (result.error) return res.status(400).json({ error: result.error, errors: result.errors });
    try { insertArtifact(voltDb, result.artifact); } catch (e) { console.warn('[Call] summary persist failed (non-fatal):', e.message); }
    const r = callStore.endCallWithSummary(voltDb, ref, orgId, { summary, summaryArtifactId: result.artifact.artifact_id });
    if (!r.ok) return res.status(409).json({ error: r.error });
    return res.json({ call_ref: ref, state: 'ended', summary_artifact_id: result.artifact.artifact_id, verify: verifySignedArtifact(result.artifact, { getHookKeypair }) });
  } catch (err) {
    return res.status(500).json({ error: 'call_end_failed', message: err.message });
  }
});

