// ── Auto-detect -> call: the tripwire brain ───────────────────────────────────
// Event-driven (called per incident, no polling). DENY-BY-DEFAULT: raises a call
// intent ONLY to contacts who have opted in (P9), so it cannot call anyone who
// hasn't consented. Cooldown per source prevents storm-spam. Never throws.
async function handleTripwireIncident(incident, orgId, { actor = 'agent.quox', corr } = {}) {
  const nowIso = new Date().toISOString();
  const decision = _tripwireShouldRaise(incident || {});
  if (!decision.warrants) return { raised: false, reason: decision.reason };
  const source = String((incident && incident.source) || 'unknown');
  const ckey = `${orgId}|${source}`;
  if (_tripwireCooldown(_tripwireLastRaise.get(ckey), nowIso, _TRIPWIRE_COOLDOWN_MIN)) {
    return { raised: false, reason: 'cooldown', source };
  }
  // Claim the cooldown BEFORE any async work: a burst of same-source incidents can
  // arrive before the dial/notify chain resolves, and reading-then-writing after
  // the awaits would let them all pass the gate and storm-dial (the exact spam the
  // cooldown exists to stop). Set now; the sweep below just bounds the map.
  _tripwireLastRaise.set(ckey, nowIso);
  // QUOXTRUST FND_..S8Q8 (T6/T9) — bring outbound telephony + notification under the org
  // GOV-4 policy store (the SAME store the reference monitor uses), so an org can DENY /
  // egress-bound them. Additive: consent + cooldown + deny-by-default stay primary; an
  // explicit DENY blocks, but an incident alert is never SUPPRESSED by require_approval or
  // a store outage (see lib/outboundEffectGovernance.js).
  const { checkStorePolicies: _govCheckStorePolicies } = require('./lib/approvalGate.js');
  const { evaluateOutboundEffectPolicy: _govOutbound } = require('./lib/outboundEffectGovernance.js');
  const policies = (contactabilityStore.listPolicies(voltDb, orgId) || []).filter((p) => p.opt_in);
  // NOTE: 'sms' deliberately NOT a call channel — an sms-consented contact must
  // not be voice-dialled (channel-scoped consent). SMS is a future distinct provider.
  const CALL_CHANNELS = new Set(['discord', 'twilio', 'voice', 'phone']);
  const callContacts = policies.filter((p) => CALL_CHANNELS.has(String(p.channel).toLowerCase()));
  const purpose = `Incident: ${incident.summary || incident.category || 'critical event'}`.slice(0, 180);
  const trigger = `${source}: ${incident.severity}`.slice(0, 120);
  const crypto = require('crypto');
  const results = [];
  for (const c of callContacts) {
    const recent = contactabilityStore.recentAttempts(voltDb, orgId, c.recipient, c.channel, {});
    const dec = evaluateContactability({ policy: c, nowIso, recentAttempts: recent });
    let allowed = dec.decision === 'allow';
    let blockReason = allowed ? null : ((dec.reasons || []).join(',') || dec.decision);
    // GOV-4 governance layer: an explicit org DENY policy blocks the dial.
    const govCall = allowed
      ? await _govOutbound(_govCheckStorePolicies, 'commanderq_outbound_call', { channel: c.channel, recipient: c.recipient }, orgId)
      : { allowed: true, governance: null };
    if (allowed && !govCall.allowed) { allowed = false; blockReason = `governance:${govCall.reason}`; }
    const callRef = `CALL_${Date.now().toString(36).toUpperCase()}_${crypto.randomBytes(4).toString('hex').toUpperCase()}`;
    callStore.createCall(voltDb, {
      orgId, callRef, channel: c.channel, recipient: c.recipient, purpose, trigger,
      state: allowed ? 'intended' : 'blocked',
      blockReason, createdBy: actor,
    });
    let providerStatus = null;
    if (allowed) {
      const pr = await callProviders.placeOutboundCall({ channel: c.channel, recipient: c.recipient, message: purpose });
      providerStatus = pr && pr.status;
    }
    results.push({ recipient: c.recipient, channel: c.channel, call_ref: callRef, state: allowed ? 'intended' : 'blocked', decision: dec.decision, governance: govCall.governance || (allowed ? null : govCall.reason), provider: providerStatus });
  }
  // Telegram fallback (best-effort) to an opted-in telegram contact until audio lands.
  let telegram = 'no_telegram_contact';
  const tg = policies.find((p) => String(p.channel).toLowerCase() === 'telegram');
  if (tg) {
    const govNotify = await _govOutbound(_govCheckStorePolicies, 'commanderq_outbound_notify', { channel: 'telegram', recipient: tg.recipient }, orgId);
    if (!govNotify.allowed) {
      telegram = `blocked:governance:${govNotify.reason}`;
    } else {
      try {
        const { sendNotification } = require('./lib/notificationService');
        const rr = await sendNotification({ channel: 'telegram', recipient: tg.recipient, title: 'CommanderQ alert', message: `${purpose} (${trigger})`, priority: 'high', orgId });
        telegram = rr && rr.success ? 'sent' : `unavailable:${(rr && rr.error) || 'unknown'}`;
      } catch (e) { telegram = `error:${e.message}`; }
    }
  }
  // cooldown already claimed above (before the async work); just bound the map.
  if (_tripwireLastRaise.size > 500) {
    for (const [k, v] of _tripwireLastRaise) { if (!_tripwireCooldown(v, nowIso, _TRIPWIRE_COOLDOWN_MIN)) _tripwireLastRaise.delete(k); }
  }
  try {
    storeAuditEnvelope({
      type: 'event', from: actor, to: 'audit.system', intent: 'quox.tripwire.fired',
      corr: corr || `TRIP_${Date.now()}`,
      payload: { source, severity: incident.severity, category: incident.category || null, contacts: results.length, results, telegram },
    });
  } catch (_) { /* evidence best-effort */ }
  return { raised: true, source, severity: incident.severity, contacts: results, telegram, note: callContacts.length ? undefined : 'No opted-in call contact — deny-by-default: nobody was called. Grant contactability consent to enable.' };
}
// Exposed so an in-process incident emitter can fire it best-effort (see governanceIncidents hook).
global.__quoxHandleTripwireIncident = handleTripwireIncident;

// Governed endpoint: an incident source (quox-sentry, the collector's own incident
// path, an external monitor) posts a signal here to trigger the tripwire brain.
app.post('/api/v1/commanderq/tripwire/signal', requireServiceOrUserAuth(), async (req, res) => {
  try {
    const body = req.body || {};
    const orgId = resolveRequestOrgId(req);
    const incident = { severity: body.severity, category: body.category, source: body.source, summary: body.summary };
    if (!incident.severity) return res.status(400).json({ error: 'severity_required' });
    const result = await handleTripwireIncident(incident, orgId, { actor: 'agent.quox', corr: resolveCorrelationId(req, body) });
    return res.json(result);
  } catch (err) {
    return res.status(500).json({ error: 'tripwire_signal_failed', message: err.message });
  }
});

// Generic signed-artifact create for the non-plan types (routing_verdict,
// commitment, consent, call_summary). Plans keep their dedicated route (HITL
// approval-card handling). First emitter of routing_verdict is COMMANDERQ P6.
app.post('/api/v1/artifacts/:type', requireServiceOrUserAuth(), async (req, res) => {
  try {
    const type = req.params.type;
    if (type === 'plan') return res.status(400).json({ error: 'use_plan_route', message: 'Use POST /api/v1/artifacts/plan for plans.' });
    const body = req.body || {};
    const orgId = resolveRequestOrgId(req);
    const createdBy = req.user?.id ? `human.${req.user.id}` : 'agent.quox';
    const corr = resolveCorrelationId(req, body);
    const artifactBody = (body.body && typeof body.body === 'object') ? body.body : body;
    const result = await createSignedArtifact(type, artifactBody, {
      orgId, createdBy, corr, getHookKeypair, storeAuditEnvelope,
      toolsUsed: Array.isArray(body.tools_used) ? body.tools_used : [],
      evidenceRefs: Array.isArray(body.evidence_refs) ? body.evidence_refs : [],
      sourceTurn: body.session_id || corr || null,
    });
    if (result.error) return res.status(400).json({ error: result.error, errors: result.errors });
    try { insertArtifact(voltDb, result.artifact); }
    catch (e) { console.warn('[Artifact] persist failed (non-fatal):', e.message); }
    const verify = verifySignedArtifact(result.artifact, { getHookKeypair });
    return res.json({
      artifact_id: result.artifact.artifact_id,
      artifact_type: type,
      signature: {
        sig_type: result.artifact.signature.sig_type,
        key_id: result.artifact.signature.key_id,
        ...(result.artifact.signature.warning ? { warning: result.artifact.signature.warning } : {}),
      },
      verify,
    });
  } catch (err) {
    console.error('[Artifact/:type] error:', err.message);
    return res.status(500).json({ error: 'artifact_create_failed', message: err.message });
  }
});

app.post('/api/v1/governance/assurance-pack', requireServiceOrUserAuth(), async (req, res) => {
  try {
    const { buildAssurancePack } = require('./lib/assurancePack.js');
    const body = req.body || {};
    const { org_id: orgIdBody, include } = body;
    // Accept top-level from/to and the nested { period: { from, to } } shape
    // older frontends send; default to the last 30 days when neither is given.
    let from = body.from || body.period?.from;
    let to = body.to || body.period?.to;
    if (!from && !to) {
      const now = new Date();
      to = now.toISOString();
      from = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000).toISOString();
    }
    if (!from || !to) {
      return res.status(400).json({ error: 'period_required', message: 'from and to (ISO dates) are both required' });
    }

    const orgId = orgIdBody || req.user?.org_id || '__default__';

    // wardData: read current chain state via the WARD verify route's data shape
    const wardData = async () => {
      try {
        const verifierPath = hostPath('quox-dashboard', 'services', 'ward', 'lib', 'verify.js');
        // WARD is ESM — just return a summary from the public stats endpoint shape
        // via a direct read of the DB if available. Otherwise return a minimal stub.
        const wardDb = voltDb; // WARD lives in its own DB; but we'll read from ward.db if path env says so
        // Pragmatic: attempt via the /ward/stats fetcher
        return { chain_id: 'ward:org/quox/env/production', entries_count: null, tips: [], note: 'live stats via /collector/ward/stats' };
      } catch (e) {
        return { error: e.message };
      }
    };

    // auditEvents: pull AEE envelopes for the window
    const auditEvents = async (period) => {
      try {
        if (!aeeStatements || !aeeStatements.query) return [];
        const rows = aeeStatements.query.all(
          null, null, null, null, null, null,
          period.from, period.to,
          null, null,
          1000, 0
        ) || [];
        return rows.map(r => ({
          id: r.id, ts: r.ts, type: r.type, from: r.from, to: r.to,
          intent: r.intent, corr: r.corr, priority: r.priority,
        }));
      } catch (e) {
        console.warn('[assurance-pack] audit query failed:', e.message);
        return [];
      }
    };

    // Public key PEM from the WARD keypair
    let publicKeyPem = null;
    try {
      const fs = require('fs');
      publicKeyPem = fs.readFileSync('/var/lib/quox/ward-keys/ward-pub.pem', 'utf-8');
    } catch (e) {
      publicKeyPem = null;
    }

    const pack = await buildAssurancePack({
      voltStatements,
      signer: signBundleManifest,
      wardData,
      auditEvents,
      publicKeyPem,
      orgId,
      period: { from, to },
      generatedBy: req.user?.id || (req.service ? 'service:internal' : 'anonymous'),
      include,
    });

    // Emit an audit envelope so the export itself is governed
    try {
      storeAuditEnvelope({
        type: 'event',
        from: req.user?.id ? `human.${req.user.id}` : 'service',
        to: 'system.compliance',
        intent: 'compliance.assurance_pack.exported',
        corr: pack.pack_id,
        payload: {
          pack_id: pack.pack_id, org_id: orgId, period: { from, to },
          stats: pack.stats,
        },
      });
    } catch (_) { /* non-fatal */ }

    res.setHeader('Content-Type', 'application/json');
    res.setHeader('Content-Disposition', `attachment; filename="${pack.pack_id}.json"`);
    res.json(pack);
  } catch (err) {
    console.error('[assurance-pack] failed:', err.message);
    res.status(500).json({ error: 'assurance_pack_failed', message: err.message });
  }
});

// Serve stream plan docs (markdown files)
app.get('/api/v1/roadmap/plan-doc', (req, res) => {
  const { path: docPath } = req.query;
  if (!docPath || docPath.includes('..') || !docPath.endsWith('.md')) {
    return res.status(400).json({ error: 'Invalid plan doc path' });
  }
  // Handle both "docs/STREAM_X.md" and "quox-dashboard/docs/STREAM_X.md"
  const cleanPath = docPath.replace(/^quox-dashboard\//, '');
  try {
    const fullPath = require('path').join(hostPath('quox-dashboard'), cleanPath);
    const content = require('fs').readFileSync(fullPath, 'utf8');
    res.json({ path: docPath, content });
  } catch (err) {
    // Try as absolute path under ~
    try {
      const altPath = require('path').join(hostHome(), docPath);
      const content = require('fs').readFileSync(altPath, 'utf8');
      res.json({ path: docPath, content });
    } catch {
      res.status(404).json({ error: 'Plan doc not found', path: docPath });
    }
  }
});

// ============================================================================
// PSDK-5: Plugin Storage — server-side key-value store per plugin per org
// ============================================================================
// Schema now owned by migrations/volt/000-baseline.sql (runMigrations() at
// voltDb init above already created plugin_storage on a fresh DB / no-ops
// on an existing one).

const pluginStorageStatements = voltDb ? {
  get: voltDb.prepare('SELECT value FROM plugin_storage WHERE plugin_id = ? AND org_id = ? AND key = ?'),
  set: voltDb.prepare('INSERT OR REPLACE INTO plugin_storage (plugin_id, org_id, key, value, updated_at) VALUES (?, ?, ?, ?, datetime(\'now\'))'),
  del: voltDb.prepare('DELETE FROM plugin_storage WHERE plugin_id = ? AND org_id = ? AND key = ?'),
  keys: voltDb.prepare('SELECT key FROM plugin_storage WHERE plugin_id = ? AND org_id = ?'),
  all: voltDb.prepare('SELECT key, value FROM plugin_storage WHERE plugin_id = ? AND org_id = ?'),
} : null;

// LICENSE-LAUNCH LL-1b: these four routes had NO route-level auth and keyed
// their rows by a client-supplied org_id defaulting to 'default'. They are
// registered BEFORE the entitlement-gated plugin backend proxy
// (app.all('/api/v1/plugins/:pluginId/*'), LE-3f, ~L24900) so they match first
// and never reached its gate. They now self-defend: requireServiceOrUserAuth()
// (so the default SHADOW mode of collectorAuthGate cannot leave them open to
// the network) plus requirePluginStorageOrg(), which derives the org from the
// CALLER (never the client-supplied org_id, for users) and applies the same
// entitlement check as the proxy. See lib/pluginStorageAuth.js.
const { requirePluginStorageOrg } = require('./lib/pluginStorageAuth.js');

app.get('/api/v1/plugins/:pluginId/storage/:key', requireServiceOrUserAuth(), requirePluginStorageOrg({ isPluginLicensed: isPluginLicensedForOrg }), (req, res) => {
  if (!pluginStorageStatements) return res.status(503).json({ error: 'Storage not available' });
  const row = pluginStorageStatements.get.get(req.params.pluginId, req.pluginStorageOrgId, req.params.key);
  if (!row) return res.json({ value: null });
  try { res.json({ value: JSON.parse(row.value) }); } catch { res.json({ value: row.value }); }
});

app.put('/api/v1/plugins/:pluginId/storage/:key', requireServiceOrUserAuth(), requirePluginStorageOrg({ isPluginLicensed: isPluginLicensedForOrg }), (req, res) => {
  if (!pluginStorageStatements) return res.status(503).json({ error: 'Storage not available' });
  pluginStorageStatements.set.run(req.params.pluginId, req.pluginStorageOrgId, req.params.key, JSON.stringify(req.body.value));
  res.json({ ok: true });
});

app.delete('/api/v1/plugins/:pluginId/storage/:key', requireServiceOrUserAuth(), requirePluginStorageOrg({ isPluginLicensed: isPluginLicensedForOrg }), (req, res) => {
  if (!pluginStorageStatements) return res.status(503).json({ error: 'Storage not available' });
  pluginStorageStatements.del.run(req.params.pluginId, req.pluginStorageOrgId, req.params.key);
  res.json({ ok: true });
});

// ApprovalsQ (QVOICE-OUTBOUND #521): escalation ledger routes. Escalations are
// recorded in voltDb.approvalsq_escalations (migrations/volt/009). The routes
// never touch an approval item; the watcher (started below, OFF unless
// QUOX_APPROVALSQ_WATCHER is set) only places calls so a human decides.
const approvalsqStore = voltDb ? createApprovalsqStore(voltDb) : null;
registerApprovalsqRoutes(app, { getStore: () => approvalsqStore, auth: requireServiceOrUserAuth });
app.get('/api/v1/plugins/:pluginId/storage', requireServiceOrUserAuth(), requirePluginStorageOrg({ isPluginLicensed: isPluginLicensedForOrg }), (req, res) => {
  if (!pluginStorageStatements) return res.status(503).json({ error: 'Storage not available' });
  const rows = pluginStorageStatements.all.all(req.params.pluginId, req.pluginStorageOrgId);
  const data = {};
  for (const row of rows) { try { data[row.key] = JSON.parse(row.value); } catch { data[row.key] = row.value; } }
  res.json({ data });
});

// Fleet standing grants (owner decision 2026-10-13): org-admin pre-approved ssh_exec lanes.
registerFleetStandingGrantRoutes(app, { auth: requireServiceOrUserAuth, requireHumanAdmin });
// Proxmox disposable VM pool (DEVFLEET-P10): org from the verified caller only; host commands ride the governed ssh_exec boundary.
registerProxmoxPoolRoutes(app, { auth: requireServiceOrUserAuth, requireHumanAdmin, requireHumanActor });
// HYPERION activity (DEVFLEET-P15): read-only VMs, holders, node load and recent ops. Org from the verified caller only.
require('./lib/proxmoxActivity.js').registerProxmoxActivityRoutes(app, { auth: requireServiceOrUserAuth, getAeeDb: () => aeeDb, callBastion: devServerHeartbeatCallBastion });
// Proxmox onboarding (DEVFLEET-ONBOARD): cert fetch, token test, vault save. Human org admin only; org from the verified caller only.
proxmoxOnboard.registerProxmoxOnboardRoutes(app, {
  auth: requireServiceOrUserAuth,
  requireHumanAdmin,
  limiter: rateLimit({ windowMs: 60_000, max: 20, message: { error: 'Too many Proxmox onboarding requests' } }),
  vault: proxmoxOnboard.createVaultClient({ authBaseUrl: `${AUTH_BASE_URL}/api` }),
  emit: (intent, orgId, payload, actor) => storeAuditEnvelope({
    type: 'event',
    from: `human.${actor || 'unknown'}`,
    to: 'system.proxmox_onboard',
    intent,
    corr: `proxmox-onboard:${orgId}`,
    payload: { orgId, org_id: orgId, ...payload },
  }),
});

/**
 * Can this collector still WRITE?
 *
 * /health hardcoded status:'healthy' and never looked at storage, so on
 * 2026-08-19 it answered healthy while the log filled with
 * "[WARD] witness error: database or disk is full" and the root filesystem sat
 * at 100% of 524GB. A collector that cannot record evidence is not healthy;
 * the process merely being able to answer an HTTP request is a much weaker
 * claim than the word implies, and it is the claim the docker healthcheck, the
 * build daemon's post-build probe, `quox status` and the dashboard all read.
 *
 * statfs on the database's own directory is cheap (no write, no query) and
 * answers exactly the question that failed. A probe that itself errors returns
 * null, which is UNKNOWN and deliberately does NOT downgrade the status:
 * asserting "degraded" because a check broke is the same overconfidence in the
 * other direction.
 */
function storageHealth() {
  try {
    const dir = path.dirname(AEE_DB_PATH);
    const st = fs.statfsSync(dir);
    const freeBytes = st.bavail * st.bsize;
    const totalBytes = st.blocks * st.bsize;
    return {
      ok: freeBytes > MIN_FREE_BYTES,
      free_bytes: freeBytes,
      free_pct: totalBytes > 0 ? Math.round((freeBytes / totalBytes) * 100) : null,
    };
  } catch (err) {
    return { ok: null, reason: err.message };
  }
}

// A gigabyte of headroom. Below this, writes are close enough to failing that
// calling the service healthy is a coin flip, and tonight's outage went from
// "slow" to "nothing can be written" inside a single build.
const MIN_FREE_BYTES = 1024 * 1024 * 1024;

app.get('/health', (req, res) => {
  const storage = storageHealth();
  // QUOXTRUST T3 (D3): a non-zero audit-write failure count means receipts are
  // being dropped — a durability breach for an evidence product. Surface it and
  // downgrade to degraded so a silent audit outage is caught by health probes,
  // quox status/doctor and sentry, instead of living only in a console.warn.
  const auditWrites = getAuditWriteFailures();
  const auditDropping = auditWrites.count > 0;
  // QUOXTRUST T3 — a crash left an external effect whose outcome we cannot know
  // (outcome_unknown) is a durability breach that a human must reconcile; surface
  // it and downgrade, same as a dropped audit receipt.
  const execLedger = executionLedger.getExecutionLedgerStatus(aeeDb);
  const execUnknown = execLedger.outcome_unknown > 0;
  // QUOXTRUST WP4.2 — the reconciliation tripwire: a failed reconciliation
  // (broken chain window, unprovable receipt, source divergence — open
  // qtrust incidents — or a failing tick) downgrades health. 'incomplete'
  // (checked:0) and 'stale' report honestly but do not page.
  let evidenceReconciliation = { state: 'disabled' };
  try { if (_evidenceReconciler) evidenceReconciliation = _evidenceReconciler.getStatus(); } catch (e) { evidenceReconciliation = { state: 'failed', error: e.message }; }
  const reconFailed = evidenceReconciliation.state === 'failed';
  // QUOXTRUST T1/D1 (FND_..SB5J) — WARD witness hooks readiness. A permanent load
  // failure (loadError) means every witness receipt is silently dropping (the primary
  // AEE row still writes, but the tamper-evidence layer is off) — a durability/evidence
  // breach that must page, not live in a console.warn. The transient boot window
  // (ready:false, no loadError) reports honestly but does NOT downgrade.
  let wardHooks = null;
  try { wardHooks = (typeof wardHooksStatus === 'function') ? wardHooksStatus() : null; } catch (e) { wardHooks = { ready: false, loadError: e.message, dropped: {}, droppedTotal: 0 }; }
  const wardWitnessOutage = !!(wardHooks && wardHooks.loadError);
  res.json({
    // A KNOWN-bad storage probe OR any dropped audit receipt OR any unreconciled
    // ambiguous effect OR a failed evidence reconciliation downgrades this.
    // Unknown storage stays healthy rather than inventing an outage.
    status: (storage.ok === false || auditDropping || execUnknown || reconFailed || wardWitnessOutage) ? 'degraded' : 'healthy',
    service: 'quox-collector',
    version: RESOLVED_VERSION,
    agents_connected: agents.size,
    ward_api: getWardApiMountStatus() ? 'mounted' : 'degraded',
    ward_hooks: wardHooks,
    storage,
    audit_writes: auditWrites,
    execution_ledger: execLedger,
    evidence_reconciliation: evidenceReconciliation,
    // QUOXTRUST WP3.1 (D4 posture ratchet): expose the default-deny gate's
    // EFFECTIVE posture so any monitor / deploy check can alert on a collector
    // that booted in shadow mode (would-deny logging without denying). Pure
    // read of the fail-closed resolver (lib/enforcementPosture.js) — an auth
    // outage reads as 'enforce' there by design, never looser.
    auth_gate_posture: (() => {
      try {
        const { isEnforced } = require('./lib/enforcementPosture.js');
        return isEnforced('COLLECTOR_AUTH_ENFORCE') ? 'enforce' : 'shadow';
      } catch { return 'unknown'; }
    })(),
    // QUOXTRUST D2 — heartbeat-auth coverage, the gate for flipping
    // HEARTBEAT_REQUIRE_AGENT_KEY. COUNTS ONLY (no host names — this endpoint is
    // public; naming which hosts are unauthenticated would advertise the blackout
    // set). would_blackout = hosts presenting neither key = the ones the flip
    // would 401. The per-host names are on the internal route
    // /api/internal/fleet/heartbeat-auth (INTERNAL_SERVICE_KEY-gated).
    heartbeat_auth_coverage: (() => {
      const c = { scoped: 0, internal: 0, other: 0, none: 0, total: agents.size };
      for (const a of agents.values()) {
        const k = ['scoped', 'internal', 'other', 'none'].includes(a && a.heartbeat_auth) ? a.heartbeat_auth : 'none';
        c[k] += 1;
      }
      c.would_blackout = c.other + c.none;
      c.enforced = process.env.HEARTBEAT_REQUIRE_AGENT_KEY === 'true';
      c.agent_service_key_set = !!process.env.AGENT_SERVICE_KEY;
      return c;
    })(),
    uptime_seconds: Math.floor(process.uptime())
  });
});

// QUOXTRUST D2 — per-host heartbeat-auth (the actionable blackout set, WITH host
// names). INTERNAL ONLY: it is NOT allowlisted, so the default-deny gate
// (collectorAuthGate) requires INTERNAL_SERVICE_KEY (or a user JWT) — a public
// list of which fleet hosts lack a valid key would itself be a finding. Read-only.
app.get('/api/internal/fleet/heartbeat-auth', (req, res) => {
  const hosts = [];
  for (const [host, a] of agents.entries()) {
    const k = ['scoped', 'internal', 'other', 'none'].includes(a && a.heartbeat_auth) ? a.heartbeat_auth : 'none';
    const addrs = heartbeatSrcAddrs.has(host) ? Array.from(heartbeatSrcAddrs.get(host)) : [];
    hosts.push({ host_id: host, heartbeat_auth: k, last_seen_ms_ago: a && a.received_at ? Date.now() - a.received_at : null, src_addrs: addrs, dup_host_id: addrs.length > 1 });
  }
  hosts.sort((x, y) => x.heartbeat_auth.localeCompare(y.heartbeat_auth) || x.host_id.localeCompare(y.host_id));
  res.json({
    enforced: process.env.HEARTBEAT_REQUIRE_AGENT_KEY === 'true',
    agent_service_key_set: !!process.env.AGENT_SERVICE_KEY,
    total: hosts.length,
    would_blackout: hosts.filter(h => h.heartbeat_auth === 'other' || h.heartbeat_auth === 'none').map(h => h.host_id),
    dup_host_ids: hosts.filter(h => h.dup_host_id).map(h => ({ host_id: h.host_id, src_addrs: h.src_addrs })),
    hosts,
  });
});

// #610 Part 2: dedicated version/commit probe so a DEPLOYED collector can be
// checked against a known commit the way `quox --version` / `quox doctor` check
// the CLI. Unauthenticated like /health (no secrets), so `quox status`/doctor
// and a plain curl can read it. `stamped` is false when the build never
// injected a commit (RESOLVED_VERSION fell back to 0.0.0), so an unstamped
// deploy is loud rather than silently reading as "version zero".
app.get('/version', (req, res) => {
  res.json({
    service: 'quox-collector',
    version: RESOLVED_VERSION,
    commit: RESOLVED_COMMIT,
    release: RESOLVED_RELEASE,
    stamped: VERSION_SOURCE.startsWith('env') || VERSION_SOURCE.startsWith('file'),
    source: VERSION_SOURCE,
    node: process.version,
    uptime_seconds: Math.floor(process.uptime()),
  });
});

// CLI-2a: Aggregate health — full platform health in one response
// Consumed by: quox status (CLI), quox doctor (CLI), DashboardView (frontend)
let _healthCache = null;
let _healthCacheTime = 0;
const HEALTH_CACHE_TTL = 5000; // 5 seconds

// #914: the Qluster read token, or the caller's own user/service auth (a signed-in owner's `quox status`).
app.get('/api/v1/health/aggregate', require('./lib/resourceStats.js').readTokenOr(requireServiceOrUserAuth()), async (req, res) => {
  const now = Date.now();
  if (_healthCache && (now - _healthCacheTime) < HEALTH_CACHE_TTL) {
    return res.json(_healthCache);
  }

  try {
    const AUTH_URL = process.env.AUTH_SERVICE_URL || 'http://auth:3101';
    const MEMORY_URL = process.env.MEMORY_SERVICE_URL || 'http://memory:3103';
    const FILES_URL = process.env.FILES_SERVICE_URL || 'http://files:3102';
    const QUOXFLOW_URL = process.env.QUOXFLOW_URL || 'http://quoxflow:3200';
    // Z2H run-6: an explicit empty REPOBRAIN_URL (public install, setup.sh) means not installed; unset = the default.
    const REPOBRAIN_HEALTH_URL = process.env.REPOBRAIN_URL === '' ? '' : (process.env.REPOBRAIN_URL || 'http://repobrain:3105');
    const TIMEOUT = 3000;

    // Parallel fan-out to all services
    const [authHealth, memoryHealth, filesHealth, quoxflowHealth, repobrainHealth] = await Promise.all([
      checkServiceHealth(AUTH_URL, '/health', TIMEOUT),
      // Use the PUBLIC /health (unauthenticated, like the other services) for the
      // aggregate liveness check. The deeper /api/memory/health requires an auth
      // header this fan-out doesn't send, so it always 401'd → checkServiceHealth
      // reported memory as "degraded" even when it was fine (false alarm surfaced
      // in Qluster). /health returns {status:'ok'} for a healthy memory service.
      checkServiceHealth(MEMORY_URL, '/health', TIMEOUT),
      checkServiceHealth(FILES_URL, '/health', TIMEOUT),
      checkServiceHealth(QUOXFLOW_URL, '/health', TIMEOUT),
      checkOptionalServiceHealth(REPOBRAIN_HEALTH_URL, '/healthz', TIMEOUT),
    ]);

    const serviceChecks = {
      auth: authHealth,
      memory: memoryHealth,
      collector: { status: 'ok', latency_ms: 0 }, // We are the collector
      quoxflow: quoxflowHealth,
      files: filesHealth,
      repobrain: repobrainHealth,
    };

    // Fleet data from in-memory agents map
    let fleetHealthy = 0, fleetDegraded = 0, fleetDown = 0;
    for (const [, agent] of agents) {
      const health = agent.status?.health || 'unknown';
      if (health === 'healthy') fleetHealthy++;
      else if (health === 'warning' || health === 'degraded') fleetDegraded++;
      else fleetDown++;
    }

    // Session data from agent sessions (if quoxagent is reachable)
    let sessionData = { active: 0, providers: {}, cost_today_usd: 0 };
    try {
      const sessResp = await fetch('http://localhost:9847/api/v1/agents/summary', {
        signal: AbortSignal.timeout(2000)
      });
      if (sessResp.ok) {
        const data = await sessResp.json();
        sessionData = {
          active: data.active_sessions || 0,
          providers: data.by_provider || {},
          cost_today_usd: data.total_cost_usd || 0,
        };
      }
    } catch { /* quoxagent may not be local */ }

    // AEE stats — fleet #388. This used to guard on `typeof getAeeStats ===
    // 'function'` for a function defined nowhere in this service, so the
    // branch was unreachable and envelopes_today was a hardcoded 0 that
    // looked like a live counter. Now counts real rows via the AEE db, and
    // reports null (not 0) when that db isn't available, so "unknown" is
    // distinguishable from "genuinely none today".
    let aeeData = { envelopes_today: null, chain_ok: true };
    try {
      if (aeeStatements?.countSince) {
        const todayStart = new Date();
        todayStart.setHours(0, 0, 0, 0);
        aeeData = {
          envelopes_today: aeeStatements.countSince.get(todayStart.toISOString()).total,
          chain_ok: true,
        };
      }
    } catch (err) {
      console.warn('[Health] AEE envelope count unavailable:', err.message);
    }

    // Vault health from auth's internal credential-health endpoint.
    // Scoped to the 'default' org — matches the single-tenant convention
    // already used for the other internal cross-service calls in this file
    // (e.g. refreshCollectorMirror's tasks call). null on failure/timeout.
    let vaultData = null;
    try {
      const SERVICE_KEY = process.env.INTERNAL_SERVICE_KEY || '';
      const vaultResp = await fetch(`${AUTH_URL}/api/internal/vault-health`, {
        headers: { 'X-Service-Key': SERVICE_KEY, 'X-Org-Id': 'default' },
        signal: AbortSignal.timeout(3000)
      });
      if (vaultResp.ok) {
        const data = await vaultResp.json();
        vaultData = {
          total: data.total || 0,
          healthy: data.healthy || 0,
          expiring_soon: data.expiring_soon || 0,
        };
      }
    } catch { /* auth vault-health unreachable — leave null */ }

    // Memory stats from the memory service's per-scope stats endpoint.
    // Scoped to the 'default' org/user bucket (same convention as vault
    // above) — this is not yet a true platform-wide total across orgs.
    let memoryData = null;
    try {
      const SERVICE_KEY = process.env.INTERNAL_SERVICE_KEY || '';
      const memResp = await fetch(`${MEMORY_URL}/api/memory/stats`, {
        headers: { 'X-Service-Key': SERVICE_KEY, 'X-Org-Id': 'default', 'X-User-Id': 'service' },
        signal: AbortSignal.timeout(3000)
      });
      if (memResp.ok) {
        const data = await memResp.json();
        memoryData = {
          entries: (data.memories?.total || 0) + (data.entities?.total || 0),
          vector_size_gb: 0, // Qdrant vector size is not exposed via any API yet
          // fleet #367: this is the 'default' org/user bucket only (this
          // endpoint has no caller org context — see the X-Org-Id header
          // above), not the caller's own org. Without this, `entries: 0`
          // for a real org reads as "your memory is empty" right after a
          // successful `memory create` in that org, when it actually means
          // "the default bucket, which isn't yours, is empty."
          scope: 'default_org',
        };
      }
    } catch { /* memory service unreachable — leave null */ }

    const result = await buildAggregateHealth({
      serviceChecks,
      fleetData: {
        total: agents.size,
        healthy: fleetHealthy,
        degraded: fleetDegraded,
        down: fleetDown,
      },
      sessionData,
      vaultData,
      memoryData,
      aeeData,
      // No clean endpoint exists yet for a running-workflow count (quoxflow
      // exposes no workflow-run API; the "tasks" self-improvement engine at
      // QUOXFLOW_URL's sibling service is a different subsystem). Left null
      // rather than invented — wire when quoxflow ships a runs/status API.
      workflowData: null,
    });

    _healthCache = result;
    _healthCacheTime = now;
    res.json(result);
  } catch (err) {
    res.status(500).json({ error: 'Failed to aggregate health', detail: err.message });
  }
});

// Qluster Phase 2 — box-side machine resources (CPU/memory/disk) for the
// external Qluster fleet controller, which today only sees health+services.
// Gated by requireReadToken: no-op unless QUOXCORE_READ_TOKEN is set (opt-in).
let _resourcesCache = null;
let _resourcesCacheTime = 0;
const RESOURCES_CACHE_TTL = 5000; // 5 seconds — mirrors health/aggregate's cache

app.get('/api/v1/health/resources', requireReadToken, async (req, res) => {
  const now = Date.now();
  if (_resourcesCache && (now - _resourcesCacheTime) < RESOURCES_CACHE_TTL) {
    return res.json(_resourcesCache);
  }

  try {
    const result = await getResourceStats();
    _resourcesCache = result;
    _resourcesCacheTime = now;
    res.json(result);
  } catch (err) {
    res.status(500).json({ error: 'Failed to read resource stats', detail: err.message });
  }
});

// Qluster Phase 3 — box-side config-fingerprint / ward-chain / backups-summary
// for the external Qluster fleet controller. Unlike health/resources and
// health/aggregate above, these expose audit/config surface: fail CLOSED
// (403 read_token_required) when QUOXCORE_READ_TOKEN is unset, in addition
// to the existing requireReadToken bearer check. See lib/qlusterReadApi.js.
app.get(
  '/api/v1/qluster/config-fingerprint',
  requireReadTokenConfigured,
  requireReadToken,
  createConfigFingerprintHandler({ getWardApiMountStatus })
);

app.get(
  '/api/v1/qluster/ward-chain',
  requireReadTokenConfigured,
  requireReadToken,
  createWardChainHandler({ getWardService })
);

app.get(
  '/api/v1/qluster/backups-summary',
  requireReadTokenConfigured,
  requireReadToken,
  createBackupsSummaryHandler()
);

// Qluster Phase 5c — cross-box EVIDENCE display. Read-only, read-token-gated
// (fail-closed like the other Phase 3 read routes). Returns a single corr's
// AEE evidence as { corr, envelopes:[metadata...], ward, manifest } for
// display in the Qluster controller — envelope METADATA + WARD hashes only,
// never raw payloads. Derived from the same AEE/VOLT source as the
// ground-truth GET /aee/conversation/:corr/bundle endpoint. Unknown/empty
// corr → { corr, envelopes: [] } (not a 404). See lib/qlusterReadApi.js.
app.get(
  '/api/v1/qluster/evidence/:corr',
  requireReadTokenConfigured,
  requireReadToken,
  createEvidenceHandler({
    getBundle: async (corr) => {
      if (!aeeDb || !corr) return null;
      const rows = aeeStatements.getByCorr.all(corr);
      const envelopes = rows.map((r) => decryptEnvelopeRow(r)).filter(Boolean);
      if (envelopes.length === 0) return null;
      envelopes.sort((a, b) => (a.ts || '').localeCompare(b.ts || ''));

      // Cross-box display carries envelope METADATA only (the same canonical
      // fields the bundle's manifest hashes) — never the decrypted payload.
      const metadata = envelopes.map((e) => ({
        // quox#516: ?? null on every field — see the bundle export route's
        // canonicalization comment; the two sites must serialize identically.
        id: e.id ?? null,
        ts: e.ts ?? null,
        intent: e.intent ?? null,
        corr: e.corr ?? null,
        reply_to: e.reply_to ?? null,
        from: e.from ?? null,
        to: e.to ?? null,
      }));

      const envelopesHash = require('crypto')
        .createHash('sha256')
        .update(JSON.stringify(metadata))
        .digest('hex');

      // WARD witness receipt + VOLT head hash, same source as the bundle route.
      let wardReceipt = null;
      let headHash = null;
      if (voltStatements) {
        const voltRun = voltStatements.getRunByCorr.get(corr) || null;
        if (voltRun && voltRun.run_id) {
          headHash = voltRun.head_hash || null;
          const bundleRow = voltStatements.getRunBundle.get(voltRun.run_id);
          if (bundleRow) {
            /* Resolve the receipt from the WARD chain rather than trusting an
               embedded ward_receipt field. Nothing writes that field, so this
               handler reported every genuinely witnessed bundle as unwitnessed.
               Reusing the resolver rather than copying its logic is deliberate:
               a second implementation of a verification check is how the two
               drift and one quietly stops verifying. Fails closed. */
            try {
              const manifest = (JSON.parse(bundleRow.data) || {}).manifest || null;
              if (manifest?.bundle_id && typeof getWardService === 'function') {
                const ward = await getWardService();
                const resolved = resolveWardReceiptForBundle(
                  {
                    getEntryBySource: ward.getEntryBySource,
                    payloadHash: ward.payloadHash,
                    chainId: ward.getHookChainId ? ward.getHookChainId() : null,
                    getCoveringTip: ward.getCoveringTip, // quox#515: signed-tip context on the receipt
                  },
                  manifest
                );
                wardReceipt = resolved.receipt;
              }
            } catch { /* best-effort: stays unwitnessed rather than optimistic */ }
          }
        }
      }

      return {
        envelopes: metadata,
        ward: { witnessed: !!wardReceipt, receipt: wardReceipt },
        manifest: {
          envelope_count: metadata.length,
          envelopes_sha256: envelopesHash,
          head_hash: headHash,
          first_ts: metadata[0] ? metadata[0].ts : null,
          last_ts: metadata[metadata.length - 1] ? metadata[metadata.length - 1].ts : null,
        },
      };
    },
  })
);

// ============================================================================
// Qluster Phase 4 — enrollment + scoped-token security + backup access.
// See lib/qlusterEnroll.js and lib/qlusterBackupProxy.js.
//   - enroll/issue, controllers list/revoke: box-admin (service key or admin JWT).
//   - enroll/exchange: UNauthed (the enrollment token IS the auth), rate-limited.
//   - backups/*: gated by requireQlusterScope; operational scopes are signed.
// ============================================================================
if (aeeDb) {
  try {
    ensureQlusterSchema(aeeDb);
    console.log('[Qluster] enrollment schema ensured on aee.db');
  } catch (qErr) {
    console.warn('[Qluster] schema init failed:', qErr.message);
  }
  try {
    ensureQlusterDelegationStore(aeeDb);
    console.log('[Qluster] delegation-result store ensured on aee.db');
  } catch (dErr) {
    console.warn('[Qluster] delegation-result store init failed:', dErr.message);
  }
  // HITL approve→execute bridge (native tool approvals) — SAME db handle as
  // the qluster delegation store above. See lib/toolApprovalStore.js.
  try {
    require('./lib/toolApprovalStore.js').ensure(aeeDb);
    console.log('[HITL] tool-approval store ensured on aee.db');
    // Fleet standing grants share aee.db; every create/use/revoke is an AEE envelope.
    require('./lib/fleetStandingGrants.js').ensure(aeeDb);
    require('./lib/fleetStandingGrants.js').setEmitter((envelope) => storeAuditEnvelope(envelope));
    // Proxmox VM pool (DEVFLEET-P10) shares aee.db; every pool op is an AEE envelope.
    require('./lib/proxmoxPoolStore.js').ensure(aeeDb);
    require('./lib/proxmoxPool.js').setEmitter((envelope) => storeAuditEnvelope(envelope));
    // Rehearsal twins (DEVFLEET-P15): org-scoped rehearsal records an approval card can reference by id.
    require('./lib/proxmoxRehearseStore.js').ensure(aeeDb);
    // VM Doctor (DEVFLEET-DOCTOR): org-scoped diagnosis reports + the quox.proxmox.doctor evidence envelope.
    require('./lib/proxmoxDoctorStore.js').ensure(aeeDb);
    require('./lib/proxmoxDoctor.js').setEmitter((envelope) => storeAuditEnvelope(envelope));
    // One-shot (no timer): rehearsals left 'running' by a previous process get their twin and snapshot cleaned up and are marked error.
    require('./lib/proxmoxRehearse.js').getRehearser().recoverAtBoot().catch((e) => console.warn('[ProxmoxRehearse] boot recovery failed:', e && e.message));
    // Reap expired leases + warm to target every 5 min for enabled orgs. Interval only, no boot-time tick (loop hygiene).
    require('./lib/proxmoxPoolScheduler.js').createProxmoxPoolScheduler({ pool: require('./lib/proxmoxPool.js').getPool(), store: require('./lib/proxmoxPoolStore.js') }).start();
  } catch (tErr) {
    console.warn('[HITL] tool-approval store init failed:', tErr.message);
  }
  // quox#695: per-number telephony org binding (replaces QUOX_TELEPHONY_ORG_ID).
  try {
    require('./lib/telephony/numbersStore.js').ensure(aeeDb);
  } catch (nErr) {
    console.warn('[Telephony] numbers store init failed:', nErr.message);
  }
  try {
    require('./lib/telephony/configuredLinesStore.js').ensure(aeeDb);
  } catch (cErr) {
    console.warn('[Telephony] configured lines store init failed:', cErr.message);
  }
  try {
    require('./lib/telephony/telephonyIdentityStore.js').ensure(aeeDb);
  } catch (iErr) {
    console.warn('[Telephony] identity store init failed:', iErr.message);
  }
  try {
    require('./lib/telephony/voiceCallStore.js').ensure(aeeDb);
  } catch (vErr) {
    console.warn('[Telephony] voice call store init failed:', vErr.message);
  }
  try {
    require('./lib/awareness/awarenessStore.js').ensure(aeeDb);
  } catch (awErr) {
    console.warn('[Awareness] store init failed:', awErr.message);
  }
  try {
    lucidDb = require('./lib/lucid/db.js').openLucidDb(Database, AEE_DB_PATH, require('./lib/lucid/journal.js'));
  } catch (lucidErr) {
    console.warn('[LUCID] journal init failed:', lucidErr.message);
  }
  try {
    // Heartbeat the in-process LUCID feeds (calls, security findings, agent runs) for orgs LUCID knows.
    require('./lib/lucid/emit.js').startHeartbeats(() =>
      lucidDb.prepare('SELECT DISTINCT org_id FROM aware_feeds').all().map((r) => r.org_id));
  } catch (hbErr) {
    console.warn('[LUCID] heartbeats not started:', hbErr.message);
  }
  try {
    // The Herald: LUCID speaks first (approvals inbox first; slot and call are host-side steps).
    require('./lib/lucid/herald.js').startHerald(() => lucidDb.prepare('SELECT DISTINCT org_id FROM aware_feeds').all().map((r) => r.org_id), {});
  } catch (heraldErr) {
    console.warn('[LUCID] herald not started:', heraldErr.message);
  }
  try {
    // P2: witness what LUCID knew and told into WARD (selective, async), and check for contradictions.
    // wardHookVOLT is fire-and-forget and silently drops when WARD is not ready, so the sink checks
    // readiness first: an unready chain is a witness failure (surfaced), never a false "witnessed".
    require('./lib/lucid/witness.js').start({ sink: (ev) => {
      const st = typeof wardHooksStatus === 'function' ? wardHooksStatus() : null;
      if (!st || !st.ready) throw new Error(`WARD not ready${st && st.loadError ? `: ${st.loadError}` : ''}`);
      wardHookVOLT(ev);
    } });
    require('./lib/lucid/epistemic.js').startEpistemic(() => lucidDb.prepare('SELECT DISTINCT org_id FROM aware_feeds').all().map((r) => r.org_id), { expectedFeeds: ['hitl'] });
  } catch (p2Err) {
    console.warn('[LUCID] witness/epistemic not started:', p2Err.message);
  }
  try {
    // P4: plain-language summaries for raw text (e.g. roadmap notes), only for orgs that switched synth on
    // (quox lucid herald set synth=true), through the same per-org model path Brain2 rerank uses.
    const lucidOrgs = () => lucidDb.prepare('SELECT DISTINCT org_id FROM aware_feeds').all().map((r) => r.org_id);
    const heraldMod = require('./lib/lucid/herald.js');
    require('./lib/lucid/synth.js').startSynth(lucidOrgs, {
      // Resolved at call time: _rerankComplete is defined further down this file (a TDZ const at boot).
      complete: (...args) => _rerankComplete(...args),
      allowOrg: (orgId) => { try { return heraldMod.getSettings(orgId).synth === true; } catch { return false; } },
    });
  } catch (synthErr) {
    console.warn('[LUCID] synth not started:', synthErr.message);
  }
  try {
    ensureQlusterDelegationSettings(aeeDb);
    console.log('[Qluster] delegation settings store ensured on aee.db');
  } catch (sErr) {
    console.warn('[Qluster] delegation settings store init failed:', sErr.message);
  }
}

