// ============================================================================
// TOOLSMITH Slice 3a — Validate + Analyse endpoints
// Mounted BEFORE requireAuth wrappers. Service-internal only (no nginx proxy block).
// ============================================================================

{
  const { validate: toolsmithValidate } = require('./lib/toolsmithValidator.js');
  const { analyse: toolsmithAnalyse } = require('./lib/toolsmithAnalyser.js');

  /**
   * POST /api/internal/toolsmith/validate
   * Body: { files: { 'tool.json': '...', 'script.py': '...', ... } }
   * Response: { valid: boolean, errors: [...], warnings: [...] }
   */
  app.post('/api/internal/toolsmith/validate', (req, res) => {
    try {
      const { files } = req.body || {};
      const result = toolsmithValidate(files);
      res.json(result);
    } catch (err) {
      console.error('[toolsmith/validate] error:', err.message);
      res.status(500).json({ valid: false, errors: [{ file: 'server', severity: 'error', code: 'INTERNAL_ERROR', message: err.message }], warnings: [] });
    }
  });

  /**
   * POST /api/internal/toolsmith/analyse
   * Body: { scriptPy: string }
   * Response: { flags: [...], suggestedPermissions: {...} }
   */
  app.post('/api/internal/toolsmith/analyse', (req, res) => {
    try {
      const { scriptPy } = req.body || {};
      if (typeof scriptPy !== 'string') {
        return res.status(400).json({ error: 'scriptPy is required and must be a string', flags: [], suggestedPermissions: null });
      }
      const result = toolsmithAnalyse(scriptPy);
      res.json(result);
    } catch (err) {
      console.error('[toolsmith/analyse] error:', err.message);
      res.status(500).json({ error: err.message, flags: [], suggestedPermissions: null });
    }
  });

  /**
   * POST /api/internal/toolsmith/sandbox/run
   * TOOLSMITH Slice E — single HTTP endpoint for sandbox execution.
   *
   * Both the UI surface (ScriptForgeView Test button → authFetch) and the
   * chat-side surface (toolsmith.runScript tool executor) ultimately call
   * scriptExecutor.runScript through this shared code path.
   *
   * Body: {
   *   scriptHash?,      — sha256 hex; computed from scriptContent if omitted
   *   scriptContent,    — Python script text (required)
   *   inputsJson?,      — JSON object for /inputs/input.json (default {})
   *   permissions,      — { network, filesystem, secrets, subprocess, approval_required }
   *   profile?,         — 'restricted' | 'standard' (default 'restricted')
   *   walltimeMs?,      — walltime in ms (default 30000)
   *   voltSessionId?,   — VOLT correlation ID; minted as ULID if omitted
   * }
   *
   * Auth: requireServiceOrUserAuth() — accepts service key (chat path) or user JWT (UI path).
   */
  app.post('/api/internal/toolsmith/sandbox/run', requireServiceOrUserAuth(), async (req, res) => {
    try {
      const {
        scriptContent,
        inputsJson = {},
        permissions,
        profile = 'restricted',
        walltimeMs = 30000,
      } = req.body || {};

      let { scriptHash, voltSessionId } = req.body || {};

      // --- org_id extraction + validation (TOOLSMITH-FIX-4) ---
      // Priority 1: JWT auth path — req.user.org_id is set by requireServiceOrUserAuth()
      // Priority 2: service-key auth path — caller must supply X-Quox-Org-Id header
      let orgId = resolveCallerOrgId(req);
      if (orgId) orgId = String(orgId).trim();

      if (!orgId) {
        return res.status(400).json({
          error: 'org_id is required: either authenticate with a JWT carrying org_id, or pass X-Quox-Org-Id with the service key',
          code: 'missing_org_id',
        });
      }

      // Validate orgId shape: non-empty, ≤128 chars, safe identifier characters only
      const ORG_ID_RE = /^[\w\-:.]+$/;
      if (orgId.length > 128 || !ORG_ID_RE.test(orgId)) {
        return res.status(400).json({
          error: 'org_id has an invalid format (max 128 chars, allowed: word chars, hyphen, colon, dot)',
          code: 'invalid_org_id',
        });
      }

      if (!scriptContent || typeof scriptContent !== 'string') {
        return res.status(400).json({ error: 'scriptContent is required and must be a string' });
      }

      if (!permissions || typeof permissions !== 'object') {
        return res.status(400).json({ error: 'permissions is required and must be an object' });
      }

      // Compute scriptHash if not provided
      if (!scriptHash) {
        const crypto = require('crypto');
        scriptHash = crypto.createHash('sha256').update(scriptContent).digest('hex');
      }

      // Mint a voltSessionId if not provided
      if (!voltSessionId) {
        const { monotonicUlid } = (() => {
          try { return require('ulidx'); } catch { return { monotonicUlid: () => `VS_${Date.now().toString(36).toUpperCase()}_${Math.random().toString(36).slice(2, 8).toUpperCase()}` }; }
        })();
        voltSessionId = monotonicUlid();
      }

      console.log('[toolsmith/sandbox/run]', { orgId, scriptHash, voltSessionId });

      const { runScript } = require('./lib/scriptExecutor.js');

      const referenceMonitor = require('./lib/referenceMonitor.js');
      const { checkStorePolicies, isSafeUnderPolicyOutage, createApprovalRequest } = require('./lib/approvalGate.js');
      const gov = await referenceMonitor.mediateGovernancePolicy('toolsmith.runScript', { scriptContent, permissions }, { orgId },
        { checkStorePolicies, isSafeUnderPolicyOutage, createApprovalRequest });
      if (gov.outcome !== referenceMonitor.OUTCOME.ALLOW) {
        return res.status(403).json({ success: false, ...gov.response });
      }

      const runResult = await runScript({
        scriptHash,
        scriptContent,
        inputsJson,
        permissions,
        profile,
        voltSessionId,
        walltimeMs,
        voltEmitter,
        orgId,
      });

      return res.json(runResult);
    } catch (err) {
      console.error('[toolsmith/sandbox/run] error:', err.message);
      return res.status(500).json({ error: err.message });
    }
  });
}

// ============================================================================
// TOOLSMITH-E-fix Patch 1 — Collector mirror for installed Toolsmith tools
//
// POST /api/internal/tool-definitions/install
// Called by auth service after writing a tool_definitions row, so the
// collector process registers the tool in toolDefinitionsStore and
// invalidates the toolsmith agent's tool cache.
//
// Auth: X-Service-Key header matching INTERNAL_SERVICE_KEY (timing-safe).
// Idempotent: re-POSTing same (toolId, orgId) returns 200 with existing row.
// ============================================================================
app.post('/api/internal/tool-definitions/install', requireInternalServiceKey, (req, res) => {

  const {
    toolId, orgId, toolName, toolJson, files,
    source = 'toolsmith', edition = 'experimental',
    executor_type: executorType = 'toolsmith',
    executor_config_payload: executorConfigPayload,
    agent_id: agentId,
  } = req.body || {};

  if (!toolId || typeof toolId !== 'string') {
    return res.status(400).json({ error: 'toolId is required' });
  }
  if (!orgId || typeof orgId !== 'string') {
    return res.status(400).json({ error: 'orgId is required' });
  }
  if (!toolName || typeof toolName !== 'string') {
    return res.status(400).json({ error: 'toolName is required' });
  }
  if (executorType !== 'toolsmith' && executorType !== 'mcp_endpoint' && executorType !== 'mcp_hosted') {
    return res.status(400).json({ error: 'unsupported_executor_type', message: `executor_type must be 'toolsmith', 'mcp_endpoint', or 'mcp_hosted'` });
  }

  const toolDefStore = require('./lib/toolDefinitionsStore.js');
  if (!toolDefStore.isReady()) {
    return res.status(503).json({ error: 'store_not_ready', message: 'Tool definitions store not initialised' });
  }

  // Idempotent: check for existing registration
  const existing = toolDefStore.getToolMeta(toolId, orgId);
  if (existing) {
    return res.status(200).json({
      ok: true,
      toolId,
      registeredAt: existing.installed_at || new Date().toISOString(),
      idempotent: true,
    });
  }

  const MCP_WRAPPER_INPUT_SCHEMA = {
    type: 'object',
    properties: {
      tool_name: { type: 'string', description: "Name of the MCP tool to invoke (must be one of the server's available tools)" },
      arguments: { type: 'object', description: 'Arguments to pass to the MCP tool', additionalProperties: true },
    },
    required: ['tool_name', 'arguments'],
  };

  // Build description and input_schema from toolJson if provided
  let description;
  let inputSchema;
  if (executorType === 'mcp_endpoint') {
    const availableTools = (executorConfigPayload && executorConfigPayload.available_tools) || [];
    const toolList = availableTools.map(t => t.name).join(', ');
    description = toolList ? `MCP endpoint: ${toolList}` : `MCP tool: ${toolName}`;
    inputSchema = MCP_WRAPPER_INPUT_SCHEMA;
  } else {
    description = `Toolsmith tool: ${toolName}`;
    inputSchema = { type: 'object', properties: {}, required: [] };
    if (toolJson && typeof toolJson === 'object') {
      if (toolJson.description) description = toolJson.description;
      if (toolJson.inputs_schema) inputSchema = toolJson.inputs_schema;
    }
  }

  let executorConfig;
  if (executorType === 'mcp_endpoint' || executorType === 'mcp_hosted') {
    // POWERS-P2.C-fix-6b: mcp_hosted MUST also pass through executor_config_payload.
    // Previously fell into the toolsmith else-branch which overwrote with
    // {source, edition, files, toolId, orgId} — dropping agent_id, tool_def_id,
    // repo_url that auth's /finalize sends. That broke hasAgent() (R3 fix) and
    // _buildMcpHostedExecute's tool_def_id lookup.
    executorConfig = JSON.stringify(executorConfigPayload || {});
  } else {
    executorConfig = JSON.stringify({
      source,
      edition,
      files: files || {},
      toolId,
      orgId,
      runtime: toolJson?.runtime || 'python3.11',
      permissions: toolJson?.permissions || {},
    });
  }

  const { normalizeToolName } = require('./lib/normalizeToolName.js');

  const baseRegistration = {
    description,
    input_schema: inputSchema,
    executor_type: executorType,
    executor_config: executorConfig,
    category: executorType === 'mcp_endpoint' ? 'mcp_endpoint' : (executorType === 'mcp_hosted' ? 'mcp_hosted' : 'toolsmith'),
    orgId,
    installedBy: `auth-service:${orgId}`,
  };

  try {
    // Always register under the canonical name (preserves dots for audit/log)
    toolDefStore.registerToolDef({ ...baseRegistration, name: toolId });

    // If the canonical contains dots, ALSO register under the LLM-normalized name
    // so getToolDef(normalizedName, orgId) finds the row when LLMs emit tool_use.
    const normalizedId = normalizeToolName(toolId);
    if (normalizedId !== toolId) {
      toolDefStore.registerToolDef({ ...baseRegistration, name: normalizedId });
      console.log(`[tool-definitions/install] dual-registered alias: ${normalizedId}`);
    }
  } catch (err) {
    console.error('[tool-definitions/install] registerToolDef failed:', err.message);
    return res.status(500).json({ error: 'registration_failed', message: err.message });
  }

  if (executorType === 'toolsmith') {
    invalidateAgentToolCache('toolsmith');
  } else if ((executorType === 'mcp_endpoint' || executorType === 'mcp_hosted') && agentId && typeof agentId === 'string') {
    invalidateAgentToolCache(agentId);
  }

  const registeredAt = new Date().toISOString();
  console.log(`[tool-definitions/install] org=${orgId} toolId=${toolId} executor_type=${executorType} registeredAt=${registeredAt}`);

  return res.status(200).json({ ok: true, toolId, registeredAt });
});

// ============================================================================
// B2: Collector mirror for uninstalled tools
//
// POST /api/internal/tool-definitions/uninstall
// Called by auth service DELETE /orgs/:orgId/powers/deploy/repo/:toolDefId
// to remove the tool from the collector's in-memory store.
//
// Auth: X-Service-Key header matching INTERNAL_SERVICE_KEY (timing-safe).
// Idempotent: returns 200 even if the tool was not registered.
// ============================================================================
app.post('/api/internal/tool-definitions/uninstall', requireInternalServiceKey, (req, res) => {

  const { toolId, orgId } = req.body || {};
  if (!toolId || typeof toolId !== 'string') {
    return res.status(400).json({ error: 'toolId is required' });
  }
  if (!orgId || typeof orgId !== 'string') {
    return res.status(400).json({ error: 'orgId is required' });
  }

  const toolDefStore = require('./lib/toolDefinitionsStore.js');
  if (!toolDefStore.isReady()) {
    // Non-fatal: store may not be ready on early boot; log and return 200
    console.warn('[tool-definitions/uninstall] store not ready — skipping removal for toolId=%s org=%s', toolId, orgId);
    return res.status(200).json({ ok: true, toolId, removed: 0, storeReady: false });
  }

  const { normalizeToolName } = require('./lib/normalizeToolName.js');
  let removed = 0;

  // Remove canonical name
  if (toolDefStore.removeToolDef(toolId, orgId)) removed++;

  // Also remove LLM-normalized alias if it differs
  const normalizedId = normalizeToolName(toolId);
  if (normalizedId !== toolId) {
    if (toolDefStore.removeToolDef(normalizedId, orgId)) removed++;
  }

  console.log(`[tool-definitions/uninstall] org=${orgId} toolId=${toolId} removed=${removed}`);
  return res.status(200).json({ ok: true, toolId, removed });
});

// ============================================================================
// LIFECYCLE-P3-D2: Internal VOLT emit endpoint
// Auth side calls this fire-and-forget to emit power.deploy.* events into
// the VOLT ledger (which is owned by the collector). This keeps VOLT DB
// ownership in collector, single emitter instance, consistent hash-chain.
//
// POST /api/internal/volt/emit
// Body: { corr, event_type, context?: { org_id, user_id }, payload?: {} }
// Auth: X-Service-Key header
// Returns: { ok: true, event_id? }
// ============================================================================
app.post('/api/internal/volt/emit', requireInternalServiceKey, (req, res) => {

  const { corr, event_type: eventType, context = {}, payload = {} } = req.body || {};

  if (!corr || typeof corr !== 'string') {
    return res.status(400).json({ error: 'corr is required' });
  }
  if (!eventType || typeof eventType !== 'string') {
    return res.status(400).json({ error: 'event_type is required' });
  }

  // VOLT emitter is available as `voltEmitter` at module scope (set up at boot).
  // If VOLT DB is unavailable (no-op emitter), isAvailable() returns false.
  if (!voltEmitter.isAvailable()) {
    // Non-fatal: VOLT unavailable is a known degraded mode
    console.warn('[LIFECYCLE-P3-D2] VOLT emit %s skipped — VOLT DB unavailable corr=%s', eventType, corr);
    return res.status(200).json({ ok: true, skipped: true, reason: 'volt_unavailable' });
  }

  try {
    // Find existing run for this corr, or start a new one.
    // startRun is idempotent-like: each power.deploy lifecycle gets a run keyed by toolDefId (corr).
    let runId;
    const existingRun = voltStatements && voltStatements.getRunByCorr
      ? voltStatements.getRunByCorr.get(corr)
      : null;

    if (existingRun && existingRun.status === 'active') {
      runId = existingRun.run_id;
    } else {
      runId = voltEmitter.startRun(corr, {
        org_id: context.org_id || null,
        user_id: context.user_id || null,
        agent_id: 'auth-service',
      });
    }

    if (!runId) {
      return res.status(200).json({ ok: true, skipped: true, reason: 'startRun_returned_null' });
    }

    const eventObj = voltEmitter.emit(runId, eventType, {
      ...payload,
      context: { corr, ...context },
    });

    // For terminal events, complete or fail the run
    if (eventType === 'power.deploy.finalized') {
      voltEmitter.completeRun(runId);
    } else if (eventType === 'power.deploy.failed') {
      voltEmitter.failRun(runId, new Error(payload.reason || 'deploy_failed'));
    }

    return res.status(200).json({ ok: true, event_id: eventObj?.event_id || null, run_id: runId });
  } catch (err) {
    console.error('[LIFECYCLE-P3-D2] VOLT emit %s failed: %s', eventType, err.message);
    // Non-fatal: don't return 5xx — the caller is fire-and-forget
    return res.status(200).json({ ok: true, skipped: true, reason: err.message });
  }
});

// DEVSUITE-SKILLS Phase 2: minimal callBastion for the heartbeat-triggered
// skill pack installer below. Same logic as callBastion in agentTools.js /
// bastionSshExecutor.js / securityCapabilityTools.js's defaultCallBastion,
// duplicated to avoid circular deps (established pattern in this codebase).
async function devServerHeartbeatCallBastion(hostId, command, grantOrTimeout = 30000) {
  const bastionUrl = process.env.BASTION_URL || '';
  const bastionToken = process.env.BASTION_API_TOKEN || '';
  if (!bastionUrl || !bastionToken) {
    return { success: false, error: require('./lib/bastionUnavailable').BASTION_UNAVAILABLE_MESSAGE };
  }
  // DEVSUITE B′ (quox#608): the 3rd arg is polymorphic for backward compat — a
  // number is a timeout (legacy callers), a string is a collector-signed
  // X-Bastion-Approval-Grant (the pack-install approval path passes this so the
  // install's execs clear Bastion's "risky" approval gate). Without forwarding
  // it, every install exec 403s "present a collector-signed grant".
  const grant = typeof grantOrTimeout === 'string' ? grantOrTimeout : null;
  const timeoutMs = typeof grantOrTimeout === 'number' ? grantOrTimeout : 30000;
  try {
    const resp = await fetch(`${bastionUrl}/api/v1/exec`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${bastionToken}`,
        ...(grant ? { 'X-Bastion-Approval-Grant': grant } : {}),
      },
      body: JSON.stringify({ targets: [hostId], command }),
      signal: AbortSignal.timeout(timeoutMs),
    });
    if (!resp.ok) {
      const text = await resp.text();
      return { success: false, error: `Bastion returned ${resp.status}: ${text}` };
    }
    const data = await resp.json();
    const r = data.results && data.results[0];
    if (!r) return data;
    return {
      success: r.exit_code === 0,
      exit_code: r.exit_code,
      stdout: r.stdout,
      stderr: r.stderr,
      error: r.error || (r.exit_code !== 0 ? r.stderr : undefined),
      duration_ms: r.duration_ms,
    };
  } catch (err) {
    return { success: false, error: err.message };
  }
}

// Receive heartbeat from QuoxAgent agent
// QUOXTRUST D2 — classify a heartbeat's presented X-Service-Key against the two
// keys the auth gate honours. Byte-safe (constant-time) equality. Pure read of
// process.env; does not mutate anything.
function classifyHeartbeatAuth(req) {
  const provided = req && req.headers && req.headers['x-service-key'];
  if (!provided) return 'none';
  const { timingSafeEqual } = require('crypto');
  const eq = (a, b) => {
    if (!a || !b) return false;
    const ba = Buffer.from(String(a));
    const bb = Buffer.from(String(b));
    return ba.length === bb.length && timingSafeEqual(ba, bb);
  };
  if (eq(provided, process.env.AGENT_SERVICE_KEY)) return 'scoped';
  if (eq(provided, process.env.INTERNAL_SERVICE_KEY)) return 'internal';
  return 'other';
}

app.post('/api/v1/heartbeat', (req, res) => {
  const heartbeat = req.body;

  if (!heartbeat.host_id) {
    return res.status(400).json({ error: 'Missing host_id' });
  }


  const now = Date.now();
  const isNew = !agents.has(heartbeat.host_id);

  // Store agent state
  const agentData = {
    ...heartbeat,
    received_at: now,
    remote_addr: req.ip || req.connection.remoteAddress,
    // QUOXTRUST D2 — classify the presented heartbeat key AT the enforcement
    // point (ground truth for the HEARTBEAT_REQUIRE_AGENT_KEY flip, NOT a
    // host-config proxy): 'scoped' = the dedicated AGENT_SERVICE_KEY
    // (collectorAuthGate.agentKeyValid path); 'internal' = INTERNAL_SERVICE_KEY
    // (survives enforce via the userGate fall-through, but is the shared god-key
    // — weaker posture); 'other'/'none' = neither, so this host WOULD BLACK OUT
    // when the belt closes. Observability only — never changes the ack below.
    heartbeat_auth: classifyHeartbeatAuth(req),
    status: {
      ...heartbeat.status,
      connection: 'connected'
    }
  };
  agents.set(heartbeat.host_id, agentData);

  // QUOXTRUST D2 — record the source IP per host_id (clone-collision diagnostic).
  try {
    const addr = (req.ip || (req.connection && req.connection.remoteAddress) || '').replace(/^::ffff:/, '');
    if (addr) {
      let s = heartbeatSrcAddrs.get(heartbeat.host_id);
      if (!s) { s = new Set(); heartbeatSrcAddrs.set(heartbeat.host_id, s); }
      s.add(addr);
      if (s.size > 8) { const first = s.values().next().value; s.delete(first); } // bound
    }
  } catch { /* diagnostic only, never block the ack */ }

  // B1 (QUOXGPU #149): GPU heartbeats also UPSERT into the durable gpu_nodes
  // table (aeeDb) — server-side source of truth, so a collector restart no
  // longer drops the GPU fleet (the Map above is a cache over this). Only
  // agents carrying gpu_devices are persisted; best-effort, never blocks the
  // heartbeat ack.
  if (aeeDb) {
    try { recordGpuHeartbeat(aeeDb, heartbeat, { now: () => now }); } catch (gErr) { console.warn('[GPU] gpu_nodes upsert failed:', gErr.message); }
  }

  // DEVSUITE-DEVMODE Phase 3: dev_capabilities heartbeats UPSERT into the
  // durable dev_servers table — mirrors gpu_nodes above (devServersStore.js).
  // DEVSUITE-SKILLS Phase 2: first-ever registration auto-installs the core
  // dev skill pack. P6: EVERY dev heartbeat also runs the trigger's drift
  // check (cheap local hash compare; Bastion exec only on drift, throttled),
  // so a pack version bump reaches the fleet without anyone hand-driving the
  // installer. Non-blocking either way: the heartbeat ack below must not
  // wait on a remote Bastion exec call.
  if (aeeDb) {
    try {
      const devResult = recordDevServerHeartbeat(aeeDb, heartbeat, { now: () => now });
      if (devResult) {
        maybeTriggerSkillPackInstall(
          {
            installSkillPack,
            callBastion: devServerHeartbeatCallBastion,
            db: aeeDb,
            // SKILLRIGHTS-11: the background installer respects the org's
            // distribution policy exactly like the sync route (same resolver).
            resolveDistributionPolicy: async (orgId) => configResolver.getSetting(orgId, 'DEV_SKILLPACK_DISTRIBUTION_POLICY').value,
            // quox#642: fallback for hosts with no attributed org.
            resolveFleetOperatorOrgId,
          },
          { isNewRegistration: !!devResult.isNewRegistration, heartbeat }
        );
      }
    } catch (dErr) { console.warn('[DEV] dev_servers upsert failed:', dErr.message); }
  }

  // QMD-B: Record heartbeat in signal aggregation layer (threshold + cascade detection)
  // QUOXMIND #1110: a concern is attributed to the heartbeat's org only when the heartbeat
  // presented the agent or internal key, so QuoxSense never shows an org a spoofed host.
  try {
    const hbOrg = (agentData.heartbeat_auth === 'scoped' || agentData.heartbeat_auth === 'internal') && typeof heartbeat.org_id === 'string' ? heartbeat.org_id : null;
    recordSignalHeartbeat(heartbeat.host_id, heartbeat.resources, { orgId: hbOrg });
  } catch { /* non-blocking */ }

  // Heartbeats are fleet telemetry — do NOT store in AEE audit trail.
  // 30 hosts × 2/min = 86,400/day = 7GB/month of noise that kills query perf.

  // Broadcast to WebSocket clients
  const update = {
    type: isNew ? 'agent_joined' : 'heartbeat',
    host_id: heartbeat.host_id,
    data: agentData
  };
  broadcastToClients(update);

  // CLARITY-2: per-heartbeat lines are ~994/1000 of collector log volume at
  // fleet scale (30 hosts x 2/min). Demoted to debug-gated — set
  // LOG_VERBOSE=true to restore per-beat logging. New-host joins still log
  // unconditionally since they're rare and operationally useful.
  if (isNew) {
    console.log(`[${new Date().toISOString()}] Heartbeat from ${heartbeat.host_id} (NEW)`);
  } else if (process.env.LOG_VERBOSE === 'true') {
    console.log(`[${new Date().toISOString()}] Heartbeat from ${heartbeat.host_id} (update)`);
  }

  res.json({
    status: 'accepted',
    host_id: heartbeat.host_id,
    server_time: new Date().toISOString()
  });
});

// DEVSUITE-HUB Phase 2 — "register as dev server" trigger (`quox dev
// enable`). NOT self-service from a fleet host — this is what turns a plain
// quoxagent host into a dev server, by constructing + signing + delivering
// a CapabilityProfile it can load at next startup (or via a future
// live-reload, not built in this pass). See lib/devCapabilityProfileIssuer.js.
//
// SEC-DEV-PROFILES-1 (2026-08-11 audit): requireServiceOrUserAuth() only
// authenticates (JWT or the shared INTERNAL_SERVICE_KEY) — the actual
// authorization for this privileged route lives in
// resolveDevProfileEnableAuth() (see its header comment in
// devCapabilityProfileIssuer.js), which requires a real JWT user (rejects
// req.service) and derives orgId EXCLUSIVELY from that user's own verified
// session, never from a caller-supplied body.org_id or a silent 'default'
// fallback.
app.post('/api/internal/dev-profiles/enable', requireServiceOrUserAuth(), async (req, res) => {
  const authResult = resolveDevProfileEnableAuth(req);
  if (!authResult.ok) {
    return res.status(authResult.status).json(authResult.body);
  }
  const orgId = authResult.orgId;

  const body = req.body || {};
  const hostId = body.host_id;
  const { capabilities, max_concurrent_sessions: maxConcurrentSessions, ttl_seconds: ttlSeconds } = body;

  if (!hostId) {
    return res.status(400).json({ error: 'bad_request', message: 'host_id is required' });
  }

  try {
    const result = await issueDevCapabilityProfile(
      { callBastion: devServerHeartbeatCallBastion },
      { hostId, orgId, capabilities, maxConcurrentSessions, ttlSeconds }
    );
    if (!result.delivered) {
      return res.status(502).json(result);
    }
    // RESIDENT IDENTITY (quox#453 phase 15): enabling dev mode also gives
    // the host its own Ed25519 resident keypair, generated on the host and
    // registered with auth. Best-effort, same as the org binding stamp
    // below — the capability profile already delivered, so a resident-
    // identity hiccup is reported on the response, never a failed enable.
    try {
      result.resident = await provisionResidentIdentity(
        {
          callBastion: devServerHeartbeatCallBastion,
          // Item 1b (2026-08-23): the real host-to-slot link is
          // dev_servers.supervisor_slot, set by a human via `quox dev
          // supervisor enable --slot`. Best-effort, same posture as the
          // rest of this dependency object — a lookup failure just means
          // no slot ships in the bootstrap, never a thrown error here.
          getHostSlot: (residentHostId) => {
            try {
              return getSupervisorSettings(aeeDb, residentHostId).slot || null;
            } catch (_err) {
              return null;
            }
          },
        },
        { hostId, orgId, instanceUrl: body.instance_url }
      );
    } catch (residentErr) {
      console.warn('[DEV] resident identity provisioning failed:', residentErr.message);
      result.resident = { provisioned: false, reason: 'error', error: residentErr.message };
    }
    // quox#453 phase 15 — mirror the resident outcome onto the durable
    // registry row so it survives past this one response (dashboard chip,
    // `quox dev doctor`). Best-effort, same discipline as the org binding
    // stamp below: the enable itself already succeeded, a write failure
    // here is only ever logged.
    if (aeeDb) {
      try {
        const residentState = result.resident && result.resident.provisioned ? 'provisioned' : 'failed';
        const residentDetail = result.resident && result.resident.provisioned
          ? (result.resident.keyState || null)
          : (result.resident && (result.resident.reason || result.resident.error)) || null;
        setResidentState(aeeDb, hostId, residentState, residentDetail);
      } catch (residentStateErr) {
        console.warn('[DEV] resident state stamp failed:', residentStateErr.message);
      }
    }
    // ORG-SCOPE (2026-08-15): the signed profile is the org truth — stamp it
    // onto the registry row so the org-filtered list (and the loop spawner's
    // host resolution) bind hosts to the org that enabled them. Best-effort:
    // profile delivery already succeeded.
    if (aeeDb) {
      try { setDevServerOrgBinding(aeeDb, hostId, orgId); }
      catch (bindErr) { console.warn('[DEV] org binding stamp failed:', bindErr.message); }
    }
    // ENABLE PROVISIONS EVERYTHING (2026-08-15): enabling dev mode also
    // delivers the dev skill pack, fire-and-forget through the same governed
    // installer the first-registration trigger uses (synthetic heartbeat
    // shape, isNewRegistration forced — the trigger's contract, see its
    // test 'the enable route reuses the trigger'). Pack install failures are
    // loud in the log, never fail the enable.
    maybeTriggerSkillPackInstall(
      { installSkillPack, callBastion: devServerHeartbeatCallBastion, db: aeeDb, resolveFleetOperatorOrgId },
      {
        isNewRegistration: true,
        heartbeat: {
          host_id: hostId,
          org_id: orgId,
          dev_capabilities: { enabled_capabilities: result.capabilities || capabilities || [] },
        },
      }
    );
    // ENABLE PROVISIONS EVERYTHING, agent-refresh slice (phase 7,
    // 2026-08-20): deliver the CURRENT agent binary and restart the agent so
    // the profile just signed is actually adopted — quoxagent reads it at
    // startup only, and the old flow ended with the CLI telling a human to
    // restart. Awaited so the response can report what happened, but a
    // refresh failure never fails the enable (the profile is already
    // delivered). Live sessions defer the restart: structured (QLoop)
    // children die with the agent; only tmux sessions survive it.
    {
      const { refreshDevServerAgent } = require('./lib/devServerRefresh.js');
      const devSessionsProxyForRefresh = require('./lib/devSessionsProxy.js');
      const collectorBase = (resolveCollectorEventUrl({ required: false }) || 'http://192.0.2.126:9848').replace(/\/+$/, '');
      // Phase 8 (CLI-FIRST): enable also keeps /opt/quoxcli current with the
      // served bundle, hash-gated. No bundle on disk -> no CLI leg, honestly
      // absent rather than a guaranteed remote failure.
      let cliLeg;
      try {
        const bundlePath = path.join(__dirname, 'cli/deploy/quoxcli-bundle.tar.gz');
        const bundleSha = crypto.createHash('sha256').update(fs.readFileSync(bundlePath)).digest('hex');
        cliLeg = {
          bundleUrl: `${collectorBase}/download/quoxcli-bundle.tar.gz`,
          bundleSha,
          collectorHost: new URL(collectorBase).hostname,
        };
      } catch (bundleErr) {
        console.warn('[DEV] quoxcli bundle unavailable, enable skips the CLI leg:', bundleErr.message);
        cliLeg = undefined;
      }
      // #456: same hash-gated pattern for DoneEngine. No bundle on disk ->
      // no gauge leg, honestly absent (`quox done` then names the missing
      // engine and how it is delivered, never a bare path error).
      let gaugeLeg;
      try {
        const gaugeBundlePath = path.join(__dirname, 'cli/deploy/quoxgauge-bundle.tar.gz');
        const gaugeBundleSha = crypto.createHash('sha256').update(fs.readFileSync(gaugeBundlePath)).digest('hex');
        gaugeLeg = {
          bundleUrl: `${collectorBase}/download/quoxgauge-bundle.tar.gz`,
          bundleSha: gaugeBundleSha,
        };
      } catch (bundleErr) {
        console.warn('[DEV] quoxgauge bundle unavailable, enable skips the DoneEngine leg:', bundleErr.message);
        gaugeLeg = undefined;
      }
      // DEVSUITE-DEVMODE phase 14: same hash-gated pattern delivering
      // Precompacticus (context-limit alerts + pre-compaction snapshots),
      // today only ever installed by hand via scripts/install-precompacticus.sh.
      // No bundle on disk -> no precompacticus leg, honestly absent.
      let precompacticusLeg;
      try {
        const pcBundlePath = path.join(__dirname, 'cli/deploy/precompacticus-bundle.tar.gz');
        const pcBundleSha = crypto.createHash('sha256').update(fs.readFileSync(pcBundlePath)).digest('hex');
        precompacticusLeg = {
          bundleUrl: `${collectorBase}/download/precompacticus-bundle.tar.gz`,
          bundleSha: pcBundleSha,
        };
      } catch (bundleErr) {
        console.warn('[DEV] precompacticus bundle unavailable, enable skips the precompacticus leg:', bundleErr.message);
        precompacticusLeg = undefined;
      }
      result.agent_refresh = await refreshDevServerAgent({
        hostId,
        cli: cliLeg,
        gauge: gaugeLeg,
        precompacticus: precompacticusLeg,
        // #462 (footgun 4): stamp the signing-key-fetch env into the agent
        // unit BEFORE the restart below, so the just-signed profile can
        // actually be VERIFIED, not just delivered. The seam service key
        // itself is never sent this way (it would land in the witnessed
        // exec log); the leg only reports whether the key file exists.
        verifierEnv: { orgId, collectorUrl: collectorBase },
        downloadUrl: `${collectorBase}/download/quoxagent-linux-amd64`,
        callBastion: devServerHeartbeatCallBastion,
        countLiveSessions: async () => {
          const out = await devSessionsProxyForRefresh.deliverDevSessionsInvoke({
            orgId, hostId, method: 'list-sessions', input: {},
            signFn: async (org, canonicalBytesHex) => {
              const authUrl = process.env.AUTH_SERVICE_URL || 'http://auth:3101';
              const resp = await fetch(`${authUrl}/api/internal/dev-profiles/sign`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'X-Service-Key': process.env.INTERNAL_SERVICE_KEY || '' },
                body: JSON.stringify({ org_id: org, kind: 'invoke', canonical_bytes_hex: canonicalBytesHex }),
                signal: AbortSignal.timeout(10000),
              });
              if (!resp.ok) throw new Error(`signing oracle returned ${resp.status}`);
              return resp.json();
            },
            deliverFn: (targetHost, command) => devServerHeartbeatCallBastion(targetHost, command, 30000),
          });
          return Number(out && out.count) || 0;
        },
      });
      if (!result.agent_refresh.ok) {
        console.warn(`[DEV] agent refresh for ${hostId} failed (non-fatal): ${result.agent_refresh.error}`);
      }
    }
    return res.json(result);
  } catch (err) {
    console.error('[DEV] dev-profiles/enable failed:', err.message);
    return res.status(500).json({ error: 'dev_profile_issue_failed', message: err.message });
  }
});

// Thin proxy for quoxagent's own startup fetch
// (internal/agent/devprofile.go's FetchDevTrustedPublicKey) to auth's real
// GET /api/internal/dev-profiles/public-key/:orgId
// (services/auth/routes/internal-dev-profile-signing.js). quoxagent never
// talks to the auth service directly — every fleet-host call goes through
// the collector, same as dev.gripe/dev.sessions' witness emits — so this
// is a pass-through, not a new capability of its own.
//
// TODO(SEC-FLEET-CRED): same known gap already flagged on GripeClient
// (quoxagent's gripe.go) and the signing oracle itself
// (internal-dev-profile-signing.js) — requireServiceOrUserAuth() here only
// accepts an X-Service-Key that exactly matches INTERNAL_SERVICE_KEY, so a
// quoxagent host calling this (per devprofile.go's doc comment) must be
// configured with QUOXAGENT_SERVICE_KEY === INTERNAL_SERVICE_KEY. Handing a
// remote fleet host that shared master key is the same known posture
// GripeClient already has; not migrated to a scoped per-host token in this
// pass (mirrors the existing gap exactly rather than inventing a new
// mechanism — see gripe.go's TODO for the intended fix shape).
app.get('/api/internal/dev-profiles/public-key/:orgId', requireServiceOrUserAuth(), async (req, res) => {
  try {
    const body = await fetchPublicKeyFromAuth({}, { orgId: req.params.orgId });
    return res.json(body);
  } catch (err) {
    console.error('[DEV] dev-profiles public-key proxy failed:', err.message);
    return res.status(502).json({ error: 'public_key_lookup_failed', message: err.message });
  }
});

// Get all agents
app.get('/api/v1/agents', (req, res) => {
  const now = Date.now();
  const agentList = [];

  for (const [hostId, agent] of agents) {
    const age = now - agent.received_at;
    let connectionStatus = 'connected';
    if (age > AGENT_DEAD_MS) {
      connectionStatus = 'dead';
    } else if (age > AGENT_TIMEOUT_MS) {
      connectionStatus = 'stale';
    }

    agentList.push({
      ...agent,
      status: {
        ...agent.status,
        connection: connectionStatus,
        last_seen_seconds: Math.floor(age / 1000)
      }
    });
  }

  // Sort by host_id
  agentList.sort((a, b) => a.host_id.localeCompare(b.host_id));

  res.json({
    count: agentList.length,
    agents: agentList
  });
});

// Get single agent
app.get('/api/v1/agents/:hostId', (req, res) => {
  const agent = agents.get(req.params.hostId);
  if (!agent) {
    return res.status(404).json({ error: 'Agent not found' });
  }

  const age = Date.now() - agent.received_at;
  let connectionStatus = 'connected';
  if (age > AGENT_DEAD_MS) connectionStatus = 'dead';
  else if (age > AGENT_TIMEOUT_MS) connectionStatus = 'stale';

  res.json({
    ...agent,
    status: {
      ...agent.status,
      connection: connectionStatus,
      last_seen_seconds: Math.floor(age / 1000)
    }
  });
});

// B1 (QUOXGPU #149) — durable GPU nodes, read from the gpu_nodes table
// (aeeDb) directly, so the fleet is visible even before the first post-boot
// heartbeat lands. Same auth posture as the sibling GET /api/v1/agents*
// routes above: not in the collectorAuthGate allowlist — same-origin cookie
// (dashboard) or a valid service/user auth is required once
// COLLECTOR_AUTH_ENFORCE=enforce. Optional ?org_id= filter (agents.js has no
// org filtering today either — heartbeats don't currently carry a verified
// org_id, so this mirrors that until GPU enrollment is org-scoped).
app.get('/api/v1/gpu/nodes', createGpuNodesListHandler({ getDb: () => aeeDb }));

// DEVSUITE-DEVMODE Phase 3 — durable dev-server registry, read from the
// dev_servers table (aeeDb) directly. Same auth posture as the sibling GET
// /api/v1/gpu/nodes immediately above (not in the collectorAuthGate
// allowlist; same-origin cookie or valid service/user auth once
// COLLECTOR_AUTH_ENFORCE=enforce). Consumed today by this endpoint only —
// the hub-plugin UI panel that will read it is a future pass, not this one.
// Optional ?org_id= filter, same convention as gpu/nodes.
// ORG-SCOPE (DEVSUITE phase 5): this route was ungated. The handler now
// fails closed without an org, but it needs the auth middleware to populate
// req.user / req.service in the first place, or every caller looks anonymous
// and gets the 403 regardless of who they are.
app.get('/api/v1/dev-servers', requireServiceOrUserAuth(), requireLicence('dev-servers', 'Dev Servers'), createDevServersListHandler({ getDb: () => aeeDb }));

// DEVSUITE-SKILLS Phase 3 — durable skill-pack status + on-demand sync.
// GET reads the durable dev_server_skill_packs record for the common case
// (no remote call); it only falls back to a live Bastion status check when
// no durable record exists yet (e.g. a host whose pack was installed before
// this table existed). POST re-runs installSkillPack() unconditionally and
// updates the durable record from the outcome — the on-demand sync
// trigger. A periodic auto-sync-on-drift scheduler is explicitly out of
// scope for this pass (see devServerSkillPacksStore.js header comment).
//
// SEC-DEV-SKILLPACK-2 (2026-08-11 audit): these routes had NO route-level
// auth — the global collectorAuthGate only confirms authentication, never
// that the caller's own org matches the target host's org. Both routes now
// carry requireServiceOrUserAuth() explicitly (defense in depth, matching
// the pattern other explicitly-gated routes in this file use) AND a real
// per-request ownership check inside the handlers themselves (getDevServer
// passed to both, so callerCanAccessOrg() can compare the resolved host's
// org_id against req.user.org_id — see devServerSkillPacksStore.js).
app.get('/api/v1/dev-servers/:hostId/skill-pack-status', requireServiceOrUserAuth(), requireLicence('dev-servers', 'Dev Servers'), createSkillPackStatusHandler({
  getDb: () => aeeDb,
  callBastion: devServerHeartbeatCallBastion,
  getDevServer,
}));
app.post('/api/v1/dev-servers/:hostId/skill-pack-sync', requireServiceOrUserAuth(), requireLicence('dev-servers', 'Dev Servers'), createSkillPackSyncHandler({
  getDb: () => aeeDb,
  callBastion: devServerHeartbeatCallBastion,
  installSkillPack,
  getDevServer,
  // SKILLRIGHTS #478 Phase 9: the org's registered distribution policy
  // (DEV_SKILLPACK_DISTRIBUTION_POLICY, settable in Settings — never
  // env-only), resolved fresh per sync through THE shared precedence
  // resolver.
  resolveDistributionPolicy: async (orgId) => configResolver.getSetting(orgId, 'DEV_SKILLPACK_DISTRIBUTION_POLICY').value,
  // Same in-process emitter the sibling build-receipts route uses (see its
  // header comment on why an in-process caller uses storeAuditEnvelope
  // directly rather than self-POSTing /aee/store).
  emitEnvelope: (envelope) => storeAuditEnvelope(envelope),
}));

// SKILLRIGHTS #478 Phase 10 — `quox skills protect` (moat 1). The CLI hashes
// the skill locally and sends only the SkillRights manifest; this route has
// the org sign a domain-separated digest via the auth signing oracle,
// registers the hash in the OPEN registry (env-pinned URL, never
// request-derived), verifies the returned receipt before accepting it,
// persists the protection (full receipt included) and witnesses it into the
// org's evidence chain (AEE envelope -> WARD, the storeAuditEnvelope path).
// See lib/skillProtect.js for the full contract and honesty text.
//
// Deliberately NOT behind requireLicence() yet, unlike the skill-pack routes
// above: protection is the free-to-drive half of the moat (the open registry
// it consumes is free by ruling), and entitlement gating belongs with the
// marketplace surfaces in phase 11, where the tiers are actually decided.
// Stated here so the absence reads as a decision, not an oversight.
const skillProtect = require('./lib/skillProtect.js');
app.post('/api/v1/skills/protect', requireServiceOrUserAuth(), async (req, res) => {
  const orgId = req.user?.org_id;
  if (!orgId) return res.status(403).json({ error: 'org_id required' });
  try {
    const result = await skillProtect.protectSkill({ orgId, body: req.body }, {
      db: aeeDb,
      authBaseUrl: process.env.AUTH_SERVICE_URL || 'http://auth:3101',
      internalServiceKey: process.env.INTERNAL_SERVICE_KEY,
    });
    if (result.created) {
      // Mint the id here so the protection row can point at the envelope.
      // storeAuditEnvelope() returns nothing and CAN silently skip (an org
      // with DISABLE_TRANSCRIPT_STORAGE), so the id is only recorded after
      // confirming the row actually landed — a protection must never claim
      // an evidence envelope that does not exist.
      const envelopeId = generateEnvelopeId();
      const envelope = {
        id: envelopeId,
        type: 'evidence',
        from: `human.${req.user?.id || 'unknown'}`,
        to: 'skills.registry',
        intent: 'quox.skills.protect',
        corr: result.protection.srid,
        payload: {
          org_id: orgId,
          srid: result.protection.srid,
          manifest_sha256: result.protection.manifestSha256,
          license: result.protection.license,
          mode: result.protection.mode,
          org_key_id: result.protection.orgKeyId,
          protect_digest: result.protection.protectDigest,
          registry_url: result.protection.registryUrl,
          skill_name: result.protection.skillName,
        },
      };
      storeAuditEnvelope(envelope);
      const landed = aeeStatements?.getById?.get(envelopeId);
      if (landed) {
        skillProtect.recordEnvelopeId(aeeDb, result.protection.id, envelopeId);
        result.protection.aeeEnvelopeId = envelopeId;
      } else {
        console.warn('[skills-protect] evidence envelope did not land (transcript storage disabled?); protection stored without an AEE reference');
      }
    }
    return res.status(result.created ? 201 : 200).json(result);
  } catch (err) {
    if (err.code === 'invalid_protect_request') {
      return res.status(400).json({ error: err.code, errors: err.errors });
    }
    if (err.code === 'org_signing_failed' || err.code === 'registry_registration_failed' || err.code === 'receipt_verification_failed') {
      console.error('[skills-protect]', err.code, err.message);
      return res.status(502).json({ error: err.code, message: err.message });
    }
    console.error('[skills-protect] unexpected:', err);
    return res.status(500).json({ error: 'protect_failed' });
  }
});
app.get('/api/v1/skills/protections', requireServiceOrUserAuth(), (req, res) => {
  const orgId = req.user?.org_id;
  if (!orgId) return res.status(403).json({ error: 'org_id required' });
  try {
    return res.json({ protections: skillProtect.listProtections(aeeDb, orgId) });
  } catch (err) {
    console.error('[skills-protect] list failed:', err);
    return res.status(500).json({ error: 'list_failed' });
  }
});

// SKILLRIGHTS #478 Phase 11 — AFFIRMATIVE ACCEPTANCE RECORDING (external
// audit finding 11). Two routes, both USER-ONLY: the offer presents the exact
// artefact hash, the exact declared rights, the exact terms bytes and a
// single-use challenge; the POST records assent to exactly that, BEFORE any
// download under the 'require-acceptance' distribution policy is authorized.
//
// A service key is refused by name (user_assent_required, inside the
// handlers): a shared machine credential proves a process ran, never that a
// person agreed, so it cannot manufacture assent. That refusal is the point
// of the phase, not an ergonomics oversight.
//
// Same confirm-before-record shape as /api/v1/skills/protect above: the
// envelope is minted after the acceptance validates, and its id is stored on
// the row only once the envelope is confirmed landed. The envelope carries
// HASHES ONLY — the preserved terms bytes live in the acceptance row, and the
// evidence chain is not a document store.
const skillPackAcceptance = require('./lib/skillPackAcceptance.js');
app.get('/api/v1/skills/acceptance/offer', requireServiceOrUserAuth(), skillPackAcceptance.createAcceptanceOfferHandler({
  getDb: () => aeeDb,
}));
app.post('/api/v1/skills/acceptance', requireServiceOrUserAuth(), skillPackAcceptance.createAcceptanceRecordHandler({
  getDb: () => aeeDb,
  emitEnvelope: (envelope) => storeAuditEnvelope(envelope),
  generateEnvelopeId,
  envelopeLanded: (id) => !!aeeStatements?.getById?.get(id),
}));

// SKILLRIGHTS #478 Phase 12 (pricing-free core) — the org rights disclosure
// ledger: distributions + protections + policy-in-force + evidence counts,
// assembled per request from the durable records (read-model only, writes
// nothing). What it deliberately does NOT contain: execution/usage events
// (workstream 10, not built) and the full protection receipts (those stay on
// /skills/protections). See lib/skillRightsLedger.js.
const { buildRightsLedger } = require('./lib/skillRightsLedger.js');
app.get('/api/v1/skills/rights-ledger', requireServiceOrUserAuth(), async (req, res) => {
  const orgId = req.user?.org_id;
  if (!orgId) return res.status(403).json({ error: 'org_id required' });
  try {
    const ledger = await buildRightsLedger(aeeDb, orgId, {
      getPolicy: async (id) => configResolver.getSetting(id, 'DEV_SKILLPACK_DISTRIBUTION_POLICY').value,
    });
    return res.json(ledger);
  } catch (err) {
    console.error('[skills-rights-ledger] failed:', err);
    return res.status(500).json({ error: 'rights_ledger_failed' });
  }
});

// SKILLRIGHTS #478 Phase 14: the SEALED EXECUTION PILOT
// (docs/SEALED_EXECUTION_PILOT_DESIGN.md). Sealed is the third tier: the
// caller invokes a capability, the methodology executes here, and only inputs
// and outputs cross the boundary. The methodology text never enters the
// calling model's context, so no route below may return it, directly or
// indirectly: create/list/get return MANIFESTS ONLY, invoke returns the work
// product, and every evidence envelope carries HASHES ONLY.
//
// The one sentence every surface prints, verbatim and binding on all of them
// (docs, CLI, STATUS row, and the create response below): "Sealed execution
// keeps the text of your methodology out of the calling model's context; the
// executing model and its provider do see it, under that provider's data
// terms, and nothing here prevents someone who can call the capability from
// learning what it does." Anything stronger is a false promise about
// protection, sold to enterprises.
//
// SUPERSEDED 2026-09-11 (external audit): the original wording claimed the
// text stays out of "every model's context and every provider's training
// pipeline". The execution path contradicts it — lib/sealedExecutor.js puts
// the plaintext into the prompt it sends to the executing model — and nothing
// here establishes any provider-training exclusion.
//
// SEALED_CONTENT_KEY is the content-encryption key and has its OWN purpose:
// the design doc forbids reusing the org crystal signing key or any other
// existing secret for it. No key, no sealed tier (503), never a fallback to
// storing the methodology in the clear.
//
// Like /api/v1/skills/protect above, these are deliberately NOT behind
// requireLicence() yet: entitlement gating for the sealed tier belongs with
// the marketplace surfaces, where the tiers are decided. Stated so the
// absence reads as a decision.
const sealedSkills = require('./lib/sealedSkills.js');
const sealedExecutor = require('./lib/sealedExecutor.js');
const SEALED_SENTENCE = 'Sealed execution keeps the text of your methodology out of the calling model\'s context; the executing model and its provider do see it, under that provider\'s data terms, and nothing here prevents someone who can call the capability from learning what it does.';

function sealedContentKey() {
  const key = process.env.SEALED_CONTENT_KEY;
  return sealedSkills.isValidContentKey(key) ? key : null;
}

// One-shot at module load: rewrite any legacy v1 sealed blob (AES-GCM with no
// additional authenticated data) as a v2 blob bound to org|sealedId|contentHash
// (ASTRA audit round 3, finding 13). Idempotent, and conservative by design: a
// row it cannot read is left exactly as it is and counted, never replaced.
// Invoke upgrades a straggler in place anyway, so a failure here costs nothing
// but a log line.
try {
  const sealedKeyAtBoot = sealedContentKey();
  if (sealedKeyAtBoot && aeeDb) {
    const migrated = sealedSkills.migrateSealedBlobs(aeeDb, sealedKeyAtBoot);
    if (migrated.upgraded) console.log(`[skills-sealed] upgraded ${migrated.upgraded} sealed blob(s) to v2 (identity-bound)`);
    if (migrated.failed) console.warn(`[skills-sealed] ${migrated.failed} legacy sealed blob(s) could not be upgraded and were left untouched`);
  }
} catch (err) {
  console.warn('[skills-sealed] sealed blob migration skipped:', err.code || err.message);
}

app.post('/api/v1/skills/sealed', requireServiceOrUserAuth(), (req, res) => {
  const orgId = req.user?.org_id;
  if (!orgId) return res.status(403).json({ error: 'org_id required' });
  // The design doc puts sealed UPLOADS with the org admin, and this route used
  // to require nothing beyond an authenticated org member, so any member could
  // create executable methodology and occupy org-wide sealed names (ASTRA
  // audit round 3, finding 14). Invoking a sealed skill stays a member act:
  // only creation moves behind the admin role.
  if (!requireAdminRole(req, res, 'sealed_admin_required')) return;
  const key = sealedContentKey();
  if (!key) return res.status(503).json({ error: 'sealed_unavailable' });
  try {
    const { name, description, input_contract: inputContract, content } = req.body || {};
    const manifest = sealedSkills.createSealedSkill(aeeDb, {
      orgId,
      name,
      description,
      inputContract: inputContract ?? (req.body || {}).inputContract,
      content,
      createdBy: req.user?.id || null,
      key,
    });

    // Confirm-before-record, same discipline as /api/v1/skills/protect: mint
    // the id, store, then check the row actually landed (storeAuditEnvelope
    // returns nothing and CAN silently skip) before telling the caller the
    // envelope exists. The payload carries the content HASH, never the
    // methodology.
    const envelopeId = generateEnvelopeId();
    storeAuditEnvelope({
      id: envelopeId,
      type: 'evidence',
      from: `human.${req.user?.id || 'unknown'}`,
      to: 'skills.sealed',
      intent: 'quox.skills.sealed.create',
      corr: manifest.sealedId,
      payload: {
        org_id: orgId,
        sealed_id: manifest.sealedId,
        name: manifest.name,
        content_sha256: manifest.contentSha256,
      },
    });
    const landed = aeeStatements?.getById?.get(envelopeId);
    if (!landed) {
      console.warn('[skills-sealed] evidence envelope did not land (transcript storage disabled?); sealed skill stored without an AEE reference');
    }

    return res.status(201).json({
      sealed: manifest,
      evidence: { envelopeId: landed ? envelopeId : null },
      notice: SEALED_SENTENCE,
    });
  } catch (err) {
    if (err.code === 'invalid_sealed_skill') return res.status(400).json({ error: err.code, errors: err.errors });
    if (err.code === 'sealed_name_taken') return res.status(409).json({ error: err.code });
    console.error('[skills-sealed] create failed:', err.code || err.message);
    return res.status(500).json({ error: 'sealed_create_failed' });
  }
});

app.get('/api/v1/skills/sealed', requireServiceOrUserAuth(), (req, res) => {
  const orgId = req.user?.org_id;
  if (!orgId) return res.status(403).json({ error: 'org_id required' });
  try {
    return res.json({ sealed: sealedSkills.listSealedSkills(aeeDb, orgId) });
  } catch (err) {
    console.error('[skills-sealed] list failed:', err.message);
    return res.status(500).json({ error: 'sealed_list_failed' });
  }
});

app.get('/api/v1/skills/sealed/:sealedId', requireServiceOrUserAuth(), (req, res) => {
  const orgId = req.user?.org_id;
  if (!orgId) return res.status(403).json({ error: 'org_id required' });
  try {
    const manifest = sealedSkills.getManifest(aeeDb, orgId, req.params.sealedId);
    if (!manifest) return res.status(404).json({ error: 'sealed_not_found' });
    return res.json({ sealed: manifest });
  } catch (err) {
    console.error('[skills-sealed] get failed:', err.message);
    return res.status(500).json({ error: 'sealed_get_failed' });
  }
});

app.post('/api/v1/skills/sealed/:sealedId/invoke', requireServiceOrUserAuth(), async (req, res) => {
  const orgId = req.user?.org_id;
  if (!orgId) return res.status(403).json({ error: 'org_id required' });
  const key = sealedContentKey();
  if (!key) return res.status(503).json({ error: 'sealed_unavailable' });

  const input = (req.body || {}).input;
  const valid = sealedSkills.validateInvokeInput(input);
  if (!valid.ok) return res.status(400).json({ error: 'invalid_sealed_input', message: valid.error });

  // Rate limits are a cloning MITIGATION, not a prevention (design doc,
  // leakage table), resolved fresh per call through the shared precedence
  // resolver, so the org's Settings override beats the env default.
  // Two ceilings, both resolved here: per sealed skill, and across the org.
  // The per-skill limit alone handed every NEW skill a fresh quota, so an org
  // could multiply its budget by creating skills (ASTRA audit round 3,
  // finding 9). Whichever bites first refuses the call.
  const configured = Number(configResolver.getSetting(orgId, 'SEALED_INVOKE_RATE_PER_HOUR').value);
  const ratePerHour = Number.isFinite(configured) && configured > 0 ? configured : 30;
  const configuredOrg = Number(configResolver.getSetting(orgId, 'SEALED_INVOKE_ORG_RATE_PER_HOUR').value);
  const orgRatePerHour = Number.isFinite(configuredOrg) && configuredOrg > 0
    ? configuredOrg
    : sealedSkills.DEFAULT_ORG_RATE_PER_HOUR;

  try {
    const result = await sealedSkills.invokeSealed({
      orgId,
      sealedId: req.params.sealedId,
      input,
      userId: req.user?.id || null,
    }, {
      db: aeeDb,
      key,
      ratePerHour,
      orgRatePerHour,
      runInvocation: ({ content, input: callerInput }) => sealedExecutor.runSealedInvocation({
        content,
        input: callerInput,
        spawnFn: require('node:child_process').spawn,
        timeoutMs: sealedExecutor.DEFAULT_TIMEOUT_MS,
        homeDir: RUNTIME_HOME_DIR,
        user: RUNTIME_USER,
      }),
      generateEnvelopeId,
      emitEnvelope: (envelope) => storeAuditEnvelope(envelope),
      confirmEnvelope: (id) => !!aeeStatements?.getById?.get(id),
    });

    if (result.outcome === 'not_found') return res.status(404).json({ error: 'sealed_not_found' });
    if (result.outcome === 'rate_limited') {
      // `scope` names WHICH ceiling refused ('skill' or 'org'), so the caller
      // is not left guessing why a quiet skill was rate limited.
      return res.status(429).json({ error: 'sealed_rate_limited', limit: result.limit, scope: result.scope });
    }
    if (result.outcome === 'refused') {
      // 200, not an error: the invocation ran and was witnessed. The work
      // product is withheld because it quoted the methodology back. Honest
      // limit, stated in lib/sealedExecutor.js: this check is partial at best.
      return res.status(200).json({ refused: true, error: 'sealed_output_withheld', evidence: result.evidence });
    }
    if (result.outcome === 'error') {
      return res.status(502).json({ error: result.code, evidence: result.evidence });
    }
    return res.json({ output: result.output, evidence: result.evidence });
  } catch (err) {
    // Never echo err.message here: the sealed paths raise generic codes, and
    // anything else could carry content.
    console.error('[skills-sealed] invoke failed:', err.code || 'unexpected');
    if (err.code === 'sealed_decrypt_failed') return res.status(500).json({ error: 'sealed_decrypt_failed' });
    return res.status(500).json({ error: 'sealed_invoke_failed' });
  }
});

// DEVSUITE-DEVMODE headless supervisor (quox#453 phase 15 follow-on). A
// resident's Ed25519 identity (lib/devResidentProvisioner.js) can now answer
// its slot channel with no interactive session open, driven by a headless
// runner loop on the host (`quox dev supervisor`, a separate CLI build).
// That runner polls GET .../supervisor every cycle and stops itself the
// instant `enabled` reads false — this pair of routes is the entire
// server-side switch it depends on. See lib/devServersStore.js's
// getSupervisorSettings/setSupervisorSettings header comments for the full
// validation contract (poll_seconds/turn_timeout_seconds/max_turns_per_hour
// ranges, the slot pattern, the stub-row-on-write behaviour).
//
// HARD INVARIANT, do not weaken: enabling autonomy is a HUMAN decision. The
// PUT write is gated by requireHumanAdmin() (utils/httpAuth.js), which
// rejects a service-key caller (req.service === true) AND any JWT carrying
// agent_id or agent_ops — a resident's own token always carries agent_id, so
// a resident can never switch itself on, only a real human admin/owner JWT
// can. GET stays on requireServiceOrUserAuth(): the resident (to poll) and
// the dashboard (to render the toggle) both need to read the current state,
// and reading the switch is not the governance-sensitive half of this.
//
// Org-scoping mirrors the skill-pack-status/sync routes immediately above
// (callerCanAccessOrg, SEC-DEV-SKILLPACK-2): when the host has a registered
// row, the caller's own org must match it or the request 403s. GET diverges
// from the skill-pack routes' 404-on-no-row in ONE deliberate way — a host
// with no row yet still returns 200 with the documented defaults
// (enabled:false) rather than 404, so the runner's poll contract is stable
// across "never enabled" and "host not registered yet" alike; there is no
// org to scope against when there is no row, and no data is being exposed by
// a default. PUT does NOT get that allowance: a governance-critical write
// must land against a real, org-owned host, so it still 404s on no row.
app.get('/api/v1/dev-servers/:hostId/supervisor', requireServiceOrUserAuth(), requireLicence('dev-servers', 'Dev Servers'), (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  try {
    const devServer = getDevServer(aeeDb, req.params.hostId);
    if (devServer && !callerCanAccessOrg(req, devServer.org_id)) {
      return res.status(403).json({ error: 'org_scope_mismatch' });
    }
    return res.json(getSupervisorSettings(aeeDb, req.params.hostId));
  } catch (err) {
    return res.status(500).json({ error: 'dev_supervisor_read_failed', detail: err.message });
  }
});

app.put('/api/v1/dev-servers/:hostId/supervisor', requireServiceOrUserAuth(), requireLicence('dev-servers', 'Dev Servers'), (req, res) => {
  // HARD INVARIANT — see the header comment above the GET route. Do not
  // relax this to requireAdminRole(): that gate treats a service-key caller
  // as admin ("inside the trust boundary"), which is exactly the hole this
  // route must not have.
  if (!requireHumanAdmin(req, res)) return;
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });

  try {
    const devServer = getDevServer(aeeDb, req.params.hostId);
    if (!devServer) return res.status(404).json({ error: 'dev_server_not_found' });
    if (!callerCanAccessOrg(req, devServer.org_id)) {
      return res.status(403).json({ error: 'org_scope_mismatch' });
    }

    const { enabled, slot, poll_seconds, turn_timeout_seconds, max_turns_per_hour } = req.body || {};
    const result = setSupervisorSettings(aeeDb, req.params.hostId, {
      enabled,
      slot,
      config: { poll_seconds, turn_timeout_seconds, max_turns_per_hour },
      updatedBy: req.user?.email || req.user?.id || null,
    });
    if (!result.ok) return res.status(400).json({ error: result.error, field: result.field });

    storeAuditEnvelope({
      type: 'event',
      from: `human.${req.user?.id || req.user?.email || 'unknown'}`,
      to: 'audit.system',
      intent: 'quox.dev.supervisor.set',
      corr: req.params.hostId,
      payload: { host_id: req.params.hostId, org_id: devServer.org_id, enabled: result.settings.enabled, slot: result.settings.slot },
    });

    return res.json(result.settings);
  } catch (err) {
    return res.status(500).json({ error: 'dev_supervisor_write_failed', detail: err.message });
  }
});

// QP-DASH P1 (DEVSUITE-DEVMODE phase 16): per-turn receipts for the headless
// supervisor. POST is the runner reporting its own attempted turn (agent JWT
// allowed: a resident reporting what it spent is member-level work, not a
// switch flip); GET feeds the dashboard health panel and `quox dev
// supervisor turns`. No AEE envelope per receipt, same rationale as the
// heartbeat route: per-turn cadence would flood WARD, and the receipts table
// IS the durable record. Born from the 2026-08-23 invisible-churn incident.
const devSupervisorTurns = require('./lib/devSupervisorTurnsStore.js').createDevSupervisorTurnsStore({ getDb: () => aeeDb });

app.post('/api/v1/dev-servers/:hostId/supervisor/turns', requireServiceOrUserAuth(), requireLicence('dev-servers', 'Dev Servers'), (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  try {
    const devServer = getDevServer(aeeDb, req.params.hostId);
    if (!devServer) return res.status(404).json({ error: 'dev_server_not_found' });
    if (!callerCanAccessOrg(req, devServer.org_id)) {
      return res.status(403).json({ error: 'org_scope_mismatch' });
    }
    const b = req.body || {};
    const row = devSupervisorTurns.recordTurn({
      orgId: devServer.org_id,
      hostId: req.params.hostId,
      slotName: b.slot_name || null,
      messageId: b.message_id || null,
      messageFrom: b.message_from || null,
      outcome: b.outcome,
      replyChars: Number.isFinite(b.reply_chars) ? b.reply_chars : undefined,
      costUsd: Number.isFinite(b.cost_usd) ? b.cost_usd : undefined,
      durationMs: Number.isFinite(b.duration_ms) ? b.duration_ms : undefined,
      errorNote: b.error_note || null,
      sessionId: b.session_id || null,
    });
    return res.status(201).json({ turn: row });
  } catch (err) {
    if (/outcome|orgId|hostId/.test(err.message)) return res.status(400).json({ error: err.message });
    return res.status(500).json({ error: 'turn_record_failed', detail: err.message });
  }
});

app.get('/api/v1/dev-servers/:hostId/supervisor/turns', requireServiceOrUserAuth(), requireLicence('dev-servers', 'Dev Servers'), (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  try {
    const devServer = getDevServer(aeeDb, req.params.hostId);
    if (!devServer) return res.status(404).json({ error: 'dev_server_not_found' });
    if (!callerCanAccessOrg(req, devServer.org_id)) {
      return res.status(403).json({ error: 'org_scope_mismatch' });
    }
    const limit = req.query.limit ? parseInt(req.query.limit, 10) : undefined;
    const turns = devSupervisorTurns.listTurns({
      orgId: devServer.org_id, hostId: req.params.hostId, since: req.query.since || null, limit,
    });
    const summary = devSupervisorTurns.summarize({
      orgId: devServer.org_id, hostId: req.params.hostId, since: req.query.since || null,
    });
    return res.json({ turns, summary });
  } catch (err) {
    return res.status(500).json({ error: 'turn_list_failed', detail: err.message });
  }
});

// DEVSUITE-BUILD Phase 1 ("receipts wedge") — durable build-queue receipts.
// POST is the daemon-side quox-build-daemon's record_action() equivalent
// (fire-and-forget from the daemon; that call site is a separate task), GET
// is the read side. Same auth posture as the sibling GET /api/v1/dev-servers
// / GET /api/v1/gpu/nodes immediately above (not in the collectorAuthGate
// allowlist — same-origin cookie or valid service/user auth once
// COLLECTOR_AUTH_ENFORCE=enforce). emitEnvelope is the in-process
// storeAuditEnvelope (defined further below) — NOT a self-POST to
// /aee/store (see lib/qlusterBackupProxy.js's header comment on why an
// in-process caller uses storeAuditEnvelope directly), wired via a getter so
// it resolves storeAuditEnvelope after its declaration further down this file.
app.post('/api/v1/build-receipts', requireLicence('quoxbuild', 'QuoxBuild'), createBuildReceiptCreateHandler({
  getDb: () => aeeDb,
  emitEnvelope: (envelope) => storeAuditEnvelope(envelope),
  host: os.hostname(),
}));
app.get('/api/v1/build-receipts', requireLicence('quoxbuild', 'QuoxBuild'), createBuildReceiptsListHandler({ getDb: () => aeeDb }));
app.get('/api/v1/build-status', requireLicence('quoxbuild', 'QuoxBuild'), createBuildStatusHandler({ getDb: () => aeeDb }));

// G2d slice 2 — durable backup/restore receipts. POST is the engine-side
// call (quoxagent's dev.backup / dev.restore executor posts the outcome of a
// scripts/backup-quox.sh or scripts/restore-quox.sh run), GET is the read
// side. Auth posture mirrors the build-receipts trio immediately above EXACTLY
// (the default-deny collector gate; the agent authenticates the same way it
// does for a build receipt today) with ONE deliberate difference: no
// requireLicence(). Backup and restore are core data-safety capabilities, not
// a paid plugin — an unlicensed instance losing the ability to record that it
// backed itself up would be a safety regression dressed as monetisation.
app.post('/api/v1/backup-receipts', createBackupReceiptCreateHandler({
  getDb: () => aeeDb,
  emitEnvelope: (envelope) => storeAuditEnvelope(envelope),
  host: os.hostname(),
}));
app.get('/api/v1/backup-receipts', createBackupReceiptsListHandler({ getDb: () => aeeDb }));
app.get('/api/v1/backup-status', createBackupStatusHandler({ getDb: () => aeeDb }));

// QUOXPERTICUS-REVISIT P3 — the dev.sessions list-sessions invoke, hoisted
// out of the bare block below (var, not const/let: this file runs as plain
// CommonJS with no 'use strict', so var declared inside a bare block still
// hoists to module scope) so the slot checkout route further down can gate
// an interactive checkout's holder_session against the host's real tmux
// plane without duplicating the signing/delivery closures. null until the
// block below assigns it; stays null (gate stays permissive) if it never
// runs, e.g. in a stripped-down test boot.
var devSessionsListInvoke = null;

// DEVSUITE-BUILD step 3 — dev.build control plane. Proxies dispatch/status/
// targets to the host-side executor (quoxagent internal/plugins/dev/build)
// as oracle-signed envelopes over Bastion, same signing contract and
// delivery path as the dev-loop spawn seam below. The envelope input only
// ever NAMES a pre-registered target; the target list lives host-side.
// Auth posture: same as the build-receipts routes above (default-deny gate,
// service/user auth). Host gate: must be a registered dev server whose
// verified profile enables dev.build.
{
  const devBuildProxy = require('./lib/devBuildProxy.js');
  const { resolveOrgId: resolveCallerOrgId } = require('./lib/feedApiHandlers.js');
  const devBuildSignFn = async (org, canonicalBytesHex) => {
    const authUrl = process.env.AUTH_SERVICE_URL || 'http://auth:3101';
    const resp = await fetch(`${authUrl}/api/internal/dev-profiles/sign`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-Service-Key': process.env.INTERNAL_SERVICE_KEY || '' },
      body: JSON.stringify({ org_id: org, kind: 'invoke', canonical_bytes_hex: canonicalBytesHex }),
      signal: AbortSignal.timeout(10000),
    });
    if (!resp.ok) throw new Error(`signing oracle returned ${resp.status}`);
    return resp.json();
  };
  const devBuildDeliverFn = async (hostId, command) => {
    const bastionUrl = process.env.BASTION_URL || '';
    const bastionToken = process.env.BASTION_API_TOKEN || '';
    if (!bastionUrl || !bastionToken) return { success: false, error: 'Bastion not configured' };
    const resp = await fetch(`${bastionUrl}/api/v1/exec`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${bastionToken}` },
      body: JSON.stringify({ targets: [hostId], command }),
      signal: AbortSignal.timeout(45000),
    });
    if (!resp.ok) return { success: false, error: `Bastion returned ${resp.status}: ${await resp.text().catch(() => '')}` };
    const data = await resp.json();
    const r = data.results && data.results[0];
    return r ? { success: r.exit_code === 0, stdout: r.stdout, stderr: r.stderr, error: r.error } : { success: false, error: 'no bastion result' };
  };
  const devBuildDeps = {
    getServer: (hostId) => getDevServer(aeeDb, hostId),
    resolveOrgId: (req) => resolveCallerOrgId(req) || 'default',
    invoke: ({ orgId, hostId, method, input }) => devBuildProxy.deliverDevBuildInvoke({
      orgId, hostId, method, input,
      signFn: devBuildSignFn,
      deliverFn: devBuildDeliverFn,
    }),
    emitEnvelope: (envelope) => storeAuditEnvelope(envelope),
  };
  app.post('/api/v1/dev-build/:hostId/dispatch', requireServiceOrUserAuth(), devBuildProxy.createDevBuildDispatchHandler(devBuildDeps));
  app.get('/api/v1/dev-build/:hostId/status', requireServiceOrUserAuth(), devBuildProxy.createDevBuildStatusHandler(devBuildDeps));
  app.get('/api/v1/dev-build/:hostId/targets', requireServiceOrUserAuth(), devBuildProxy.createDevBuildTargetsHandler(devBuildDeps));

  // G2d slice 2 — dev.backup / dev.restore control plane. Proxies the five
  // methods to the host-side executors (quoxagent internal/plugins/dev/backup
  // and .../restore, wrapping scripts/backup-quox.sh and
  // scripts/restore-quox.sh) as oracle-signed envelopes over Bastion, reusing
  // the SAME signing oracle and Bastion delivery closures as dev.build above —
  // there is one signing contract in this file and duplicating it is how two
  // callers drift a byte apart. Host gate: a registered dev server whose
  // verified profile enables dev.backup, plus dev.restore for the two restore
  // routes (see requireBackupHost in lib/devBackupProxy.js).
  //
  // AUTH: every route here also carries an explicit requireServiceOrUserAuth(),
  // the same guard the /api/v1/dev-servers routes use (the dev-build trio
  // above carries it too, as of the cross-org host-gate fix). A backup reads
  // the whole box's data and a restore writes it back over a live stack —
  // server-wide data movement must never ride on the global collector gate
  // alone, whose enforcement posture is an env setting (COLLECTOR_AUTH_ENFORCE).
  //
  // NO requireLicence() here, unlike the build routes: backup and restore are
  // core data-safety capabilities, not a paid plugin.
  const devBackupProxy = require('./lib/devBackupProxy.js');
  const devBackupDeps = {
    getServer: (hostId) => getDevServer(aeeDb, hostId),
    resolveOrgId: (req) => resolveCallerOrgId(req) || 'default',
    invoke: ({ orgId, hostId, capability, method, input }) => devBackupProxy.deliverDevBackupInvoke({
      orgId, hostId, capability, method, input,
      signFn: devBuildSignFn,
      deliverFn: devBuildDeliverFn,
    }),
    emitEnvelope: (envelope) => storeAuditEnvelope(envelope),
  };
  app.post('/api/v1/dev-backup/:hostId/dispatch', requireServiceOrUserAuth(), devBackupProxy.createDevBackupDispatchHandler(devBackupDeps));
  app.get('/api/v1/dev-backup/:hostId/status', requireServiceOrUserAuth(), devBackupProxy.createDevBackupStatusHandler(devBackupDeps));
  app.get('/api/v1/dev-backup/:hostId/archives', requireServiceOrUserAuth(), devBackupProxy.createDevBackupArchivesHandler(devBackupDeps));
  app.post('/api/v1/dev-backup/:hostId/restore', requireServiceOrUserAuth(), devBackupProxy.createDevRestoreDispatchHandler(devBackupDeps));
  app.get('/api/v1/dev-backup/:hostId/restore-status', requireServiceOrUserAuth(), devBackupProxy.createDevRestoreStatusHandler(devBackupDeps));

  // SLOTS-TMUX step B — dev.sessions tmux (interactive) control plane. The
  // five agent methods (new/send-keys/pane/kill/list, quoxagent
  // internal/plugins/dev/sessions) were declared and tested but had NO
  // caller (note #2877); these routes are the caller. Same signing oracle +
  // Bastion delivery as dev.build above; each route is one short envelope
  // delivery, the session itself lives on the host's tmux server, so
  // Bastion's 60s exec ceiling never binds a session's lifetime. Auth:
  // service/user, same posture as /api/v1/dev-sessions/spawn below.
  const devSessionsProxy = require('./lib/devSessionsProxy.js');
  const devSessionsDeps = {
    getServer: (hostId) => getDevServer(aeeDb, hostId),
    resolveOrgId: (req) => resolveCallerOrgId(req) || 'default',
    invoke: ({ orgId, hostId, method, input }) => devSessionsProxy.deliverDevSessionsInvoke({
      orgId, hostId, method, input,
      signFn: devBuildSignFn,
      deliverFn: devBuildDeliverFn,
    }),
    emitEnvelope: (envelope) => storeAuditEnvelope(envelope),
  };
  // QUOXPERTICUS-REVISIT P3: expose list-sessions (host-scoped, org
  // resolved by the caller) to the slot checkout route's resident gate.
  devSessionsListInvoke = ({ orgId, hostId }) => devSessionsDeps.invoke({ orgId, hostId, method: 'list-sessions', input: {} });
  app.get('/api/v1/dev-sessions/tmux/:hostId', requireServiceOrUserAuth(), devSessionsProxy.createTmuxListHandler(devSessionsDeps));
  app.post('/api/v1/dev-sessions/tmux/:hostId', requireServiceOrUserAuth(), devSessionsProxy.createTmuxNewHandler(devSessionsDeps));
  app.post('/api/v1/dev-sessions/tmux/:hostId/:sessionId/keys', requireServiceOrUserAuth(), devSessionsProxy.createTmuxSendKeysHandler(devSessionsDeps));
  app.get('/api/v1/dev-sessions/tmux/:hostId/:sessionId/pane', requireServiceOrUserAuth(), devSessionsProxy.createTmuxPaneHandler(devSessionsDeps));
  app.delete('/api/v1/dev-sessions/tmux/:hostId/:sessionId', requireServiceOrUserAuth(), devSessionsProxy.createTmuxKillHandler(devSessionsDeps));

  // SLOTS-TMUX step D — idle-and-unheld tmux reap (note #2876, task #26).
  // sweepStale (further below) frees the SLOT row and never touches the
  // host; this sweep is the host half. A session dies only when NO
  // held/stale slot points at it AND its pane has been inactive past the
  // threshold — release never auto-kills, surviving detach is the point of
  // tmux. Server-side interval (never a browser timer). The idle env var is
  // a startup DEFAULT only, same posture as SLOT_HELD_TTL_MS below.
  const { reapIdleTmuxSessions } = require('./lib/devSessionsReaper.js');
  const TMUX_REAP_IDLE_MS = Number(process.env.QUOX_TMUX_REAP_IDLE_MS) || 60 * 60 * 1000;
  const tmuxReapTimer = setInterval(async () => {
    if (!aeeDb) return;
    try {
      // Signing is per org: the agent only trusts envelopes signed by the
      // org key that signed its capability profile, so every invoke here
      // signs as the HOST's registered org, never a fixed default.
      const orgForHost = (hostId) => {
        const row = getDevServer(aeeDb, hostId);
        return (row && row.org_id) || 'default';
      };
      const result = await reapIdleTmuxSessions({
        listDevServers: () => listDevServers(aeeDb),
        listHeldSlots: () => devSlots.listHeldSlots(),
        listSessions: ({ hostId }) => devSessionsDeps.invoke({ orgId: orgForHost(hostId), hostId, method: 'list-sessions', input: {} }),
        invoke: ({ hostId, method, input }) => devSessionsDeps.invoke({ orgId: orgForHost(hostId), hostId, method, input }),
        idleMs: TMUX_REAP_IDLE_MS,
        emitEnvelope: (envelope) => storeAuditEnvelope(envelope),
        log: (line) => console.log(line),
      });
      if (result.reaped > 0) {
        console.log(`[DevSessionsReap] sweep: ${result.reaped} reaped, ${result.protectedHeld} held, ${result.hostErrors} errors`);
      }
    } catch (err) {
      console.error('[DevSessionsReap] sweep failed:', err.message);
    }
  }, 5 * 60 * 1000);
  if (tmuxReapTimer.unref) tmuxReapTimer.unref();
}

// ============================================================================
// DEVSUITE-DEVMODE fleet spawn seam — dev loop sessions (design: QuoxPlan
// DEVSUITE-DEVMODE note #2665; agent half: quoxagent f49a18f..aa83429).
//
// POST /spawn        (service/user auth) mint session + ingest token, build
//                    an oracle-signed job envelope, deliver via Bastion ssh
//                    to the agent's loopback /api/v1/dev/invoke.
// POST /:id/events   (AGENT PUSH — collectorAuthGate-ALLOWLISTED; the
//                    per-session ingest token minted at spawn is the auth,
//                    verified by hash in the store; bad token → 401,
//                    unknown session → 404. Fleet hosts have no JWT.)
// GET  /:id/events   (service/user auth) since_seq resumable read; the
//                    tasks service's realLoopSpawner polls this.
// ============================================================================
const devLoopSessions = require('./lib/devLoopSessionsStore.js');
const devLoopSpawner = require('./lib/devLoopSpawner.js');
const { makeLoopSpawnGrantFn } = require('./lib/loopSpawnGrant.js');
const { classifyLoopAocl, buildLoopVoltEntry } = require('./lib/devLoopEvidence.js');
// FLEET #431 — the collector base URL stamped into the agent envelope is
// consumed on ANOTHER machine, so it has no safe default. Single resolver,
// fails loud when neither COLLECTOR_LAN_URL nor COLLECTOR_PUBLIC_URL is set.
const { resolveCollectorEventUrl, checkStartupConfig: checkCollectorUrlConfig, templateInstallScript } = require('./lib/collectorUrls.js');
// EVIDENCED: session_id -> VOLT run_id, so a run started at spawn can be
// emitted-to on each ingest turn and completed on done/interrupt. In-memory,
// same lifetime as voltEmitter's own activeRuns (a collector restart loses
// both together, which is consistent).
const devLoopVoltRuns = new Map();

app.post('/api/v1/dev-sessions/spawn', requireServiceOrUserAuth(), async (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  // capability_scope + tool_access arrive snake_case from the tasks service
  // (pinned contract). capability_scope is audit-only here: enforcement lives
  // in args plus the tasks side. tool_access is what the agent needs, so it
  // must not be dropped.
  const { host_id, backend, payload, args, max_duration_ms, max_turns, capability_scope, tool_access, objective_id, approval_item_id } = req.body || {};
  const orgId = resolveRequestOrgId(req);
  // CORE-LOCAL (QuoxPlan #2873, 2026-08-20): host_id is OPTIONAL now. With a
  // host, the loop runs on that governed fleet host exactly as before; with
  // none, it runs INSIDE the collector (authenticated claude/codex CLIs live
  // here), replacing the interim "core-local execution is not built" error.
  // Everything downstream of delivery (session row, ingest, witnessing,
  // VOLT/AOCL, interrupt) is the same code path for both.
  if (!orgId || !backend) {
    return res.status(400).json({ error: 'org_id (or authed org) and backend are required' });
  }
  const isApiBackend = backend === 'openai' && require('./lib/openaiLoopRunner.js').isAvailable();
  if (backend !== 'claude' && backend !== 'codex' && !isApiBackend) {
    return res.status(400).json({ error: "backend must be 'claude' or 'codex'" });
  }
  if (isApiBackend && host_id) {
    return res.status(400).json({ error: "api-kind backend 'openai' runs in the collector, not on a fleet host" });
  }
  const hostId = host_id || 'core-local';

  const { id, ingestToken } = devLoopSessions.createLoopSession(aeeDb, { orgId, hostId, backend });
  // The collector stamps the session id it just minted onto tool_access, so
  // the agent's tool calls are attributable to this exact loop session.
  const toolAccessResult = devLoopSpawner.normalizeToolAccess(tool_access, id);
  if (!toolAccessResult.ok) {
    devLoopSessions.markLoopSessionError(aeeDb, id, toolAccessResult.error);
    return res.status(400).json({ error: toolAccessResult.error, session_id: id });
  }
  try {
    let agentSessionId;
    if (isApiBackend) {
      // API-kind delivery: the model loop runs in-process; its tools go ONLY
      // through the governed chokepoint (openaiToolLoopDeps), its turns self-ingest
      // through the same /:id/events route, and /interrupt reaches it below.
      const openaiRunner = require('./lib/openaiLoopRunner.js');
      // Resolve the full governed tool catalogue for the loop's agent; the
      // runner offers ONLY the subset the capability_scope names (deny by
      // default, argument-patterned entries never offered). Loops run as
      // CommanderQ ('quox'). A resolver failure is caught by the outer try and
      // marks the session errored rather than silently running tool-less.
      const loopAgentId = 'quox';
      const loopTools = await getToolsWithConnectors(loopAgentId, orgId);
      ({ agentSessionId } = openaiRunner.startOpenAILoop({
        sessionRef: id,
        ingestToken,
        orgId,
        agentId: loopAgentId,
        payload: payload || '',
        capabilityScope: Array.isArray(capability_scope) ? capability_scope : [],
        tools: Array.isArray(loopTools) ? loopTools : [],
        maxDurationMs: Number(max_duration_ms) || 0,
        maxTurns: Number(max_turns) || 0,
        collectorUrl: `http://127.0.0.1:${PORT}`,
        deps: openaiToolLoopDeps(),
      }));
    } else if (!host_id) {
      // Core-local delivery: spawn in-process, events self-ingest through
      // the SAME /:id/events route the fleet agent posts to, so evidence
      // behaves identically. tool_access is not wired for core-local in
      // this pass (the MCP config seam is host-side); asking for it is
      // refused loudly rather than silently granting nothing.
      const coreLocal = require('./lib/coreLocalLoopRunner.js');
      if (toolAccessResult.value && toolAccessResult.value.enabled) {
        devLoopSessions.markLoopSessionError(aeeDb, id, 'tool_access is not supported for core-local loops yet');
        return res.status(400).json({ error: 'tool_access is not supported for core-local loops yet (spawn on a dev server for tool-enabled loops)', session_id: id });
      }
      ({ agentSessionId } = coreLocal.startCoreLocalLoop({
        sessionRef: id,
        ingestToken,
        backend,
        payload: payload || '',
        args: Array.isArray(args) ? args : [],
        maxDurationMs: Number(max_duration_ms) || 0,
        maxTurns: Number(max_turns) || 0,
        collectorUrl: `http://127.0.0.1:${PORT}`,
      }));
    } else {
    ({ agentSessionId } = await devLoopSpawner.deliverLoopSpawn({
      orgId,
      hostId: host_id,
      sessionRef: id,
      ingestToken,
      // FLEET #431: required — a spawn with no configured collector URL must
      // fail visibly (session marked errored, 502 carrying the actionable
      // message) rather than tell the agent to push its turns somewhere else.
      collectorLanUrl: resolveCollectorEventUrl({
        required: true,
        purpose: 'dev-loop event forwarding (the spawned agent POSTs its turn batches back to this URL)',
      }),
      backend,
      payload: payload || '',
      args: Array.isArray(args) ? args : undefined,
      maxDurationMs: Number(max_duration_ms) || 0,
      maxTurns: Number(max_turns) || 0,
      toolAccess: toolAccessResult.value,
      signFn: async (org, canonicalBytesHex) => {
        const authUrl = process.env.AUTH_SERVICE_URL || 'http://auth:3101';
        const resp = await fetch(`${authUrl}/api/internal/dev-profiles/sign`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'X-Service-Key': process.env.INTERNAL_SERVICE_KEY || '' },
          body: JSON.stringify({ org_id: org, kind: 'invoke', canonical_bytes_hex: canonicalBytesHex }),
          signal: AbortSignal.timeout(10000),
        });
        if (!resp.ok) throw new Error(`signing oracle returned ${resp.status}`);
        return resp.json();
      },
      // Throws (never returns null) when an approval item exists but cannot be
      // proven this objective's human before_start approval: fails closed.
      grantFn: makeLoopSpawnGrantFn({ orgId, objectiveId: objective_id, approvalItemId: approval_item_id }),
      deliverFn: async (hostId, command, grant) => {
        const bastionUrl = process.env.BASTION_URL || '';
        const bastionToken = process.env.BASTION_API_TOKEN || '';
        if (!bastionUrl || !bastionToken) return { success: false, error: 'Bastion not configured' };
        const resp = await fetch(`${bastionUrl}/api/v1/exec`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${bastionToken}`, ...(grant ? { 'X-Bastion-Approval-Grant': grant } : {}) },
          body: JSON.stringify({ targets: [hostId], command }),
          signal: AbortSignal.timeout(45000),
        });
        if (!resp.ok) return { success: false, error: `Bastion returned ${resp.status}: ${await resp.text().catch(() => '')}` };
        const data = await resp.json();
        const r = data.results && data.results[0];
        return r ? { success: r.exit_code === 0, stdout: r.stdout, stderr: r.stderr, error: r.error } : { success: false, error: 'no bastion result' };
      },
    }));
    }

    devLoopSessions.setAgentSessionId(aeeDb, id, agentSessionId);
    storeAuditEnvelope({
      type: 'event',
      from: req.user ? `human.${req.user.id || req.user.sub || 'unknown'}` : 'system.tasks',
      to: `host.${hostId}`,
      intent: 'quox.dev.loop.spawned',
      corr: id,
      payload: {
        session_id: id,
        agent_session_id: agentSessionId,
        host_id: hostId,
        backend,
        org_id: orgId,
        // Audit-only: what the loop was scoped to, and whether it was given a
        // tool identity at all. No secret is recorded here.
        capability_scope: capability_scope || null,
        tool_access: toolAccessResult.value || null,
      },
    });
    // EVIDENCED: start a VOLT run keyed to this loop session, and emit the
    // AOCL layer classification for a governed autonomous loop. Both are
    // best-effort — evidence emission must never turn a successful spawn into
    // a failed one, so each is individually guarded (an escape here would be
    // caught by the route's catch and wrongly mark the session errored).
    try {
      const voltRunId = voltEmitter.startRun(id, {
        org_id: orgId, agent_id: backend, host_id: hostId, source: 'dev_loop',
      });
      if (voltRunId) devLoopVoltRuns.set(id, voltRunId);
    } catch (voltErr) {
      console.error(`[DevLoop] VOLT startRun failed for ${id}:`, voltErr.message);
    }
    try {
      storeAuditEnvelope({
        type: 'event',
        from: req.user ? `human.${req.user.id || req.user.sub || 'unknown'}` : 'system.tasks',
        to: 'system.aocl',
        intent: 'aocl.run.start',
        corr: id,
        payload: {
          session_id: id, host_id: hostId, backend, org_id: orgId,
          source: 'dev_loop', aocl: classifyLoopAocl(),
        },
      });
    } catch (aoclErr) {
      console.error(`[DevLoop] AOCL spawn envelope failed for ${id}:`, aoclErr.message);
    }
    res.status(201).json({ session_id: id, agent_session_id: agentSessionId, status: 'streaming' });
  } catch (err) {
    // A spawn that didn't spawn must be a visibly failed session, never a
    // phantom streaming row.
    devLoopSessions.markLoopSessionError(aeeDb, id, err.message);
    console.error('[DevLoop] Spawn failed:', err.message);
    res.status(502).json({ error: 'spawn failed', detail: err.message, session_id: id });
  }
});

app.post('/api/v1/dev-sessions/:id/events', (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  try {
    const { ingest_token, events, done } = req.body || {};
    const result = devLoopSessions.ingestEventBatch(aeeDb, req.params.id, {
      ingestToken: ingest_token,
      events: Array.isArray(events) ? events : [],
      done: !!done,
    });
    // WARD-witness each genuinely-new turn on the real hash chain, so the
    // durable dev_loop_session_events table becomes tamper-evident: the chain
    // binds seq -> content hash, and tampering with a stored turn breaks
    // verification. Only newEvents are witnessed (dedup: an at-least-once
    // redelivery returns an empty list, so no (session, seq) is witnessed
    // twice). Best-effort: a witness failure must never break ingest
    // durability, but it must be visible in the logs.
    for (const ev of result.newEvents || []) {
      try {
        storeAuditEnvelope({
          type: 'event',
          from: `host.${result.session.host_id}`,
          to: `host.${result.session.host_id}`,
          intent: 'quox.dev.loop.turn',
          corr: req.params.id,
          payload: {
            session_id: req.params.id,
            seq: ev.seq,
            event_type: ev.type,
            raw_sha256: ev.rawSha256,
            org_id: result.session.org_id || null,
          },
        });
      } catch (witnessErr) {
        console.error(`[DevLoop] Turn witness failed for ${req.params.id} seq ${ev.seq}:`, witnessErr.message);
      }
      // EVIDENCED: emit a lightweight VOLT entry for this turn on the run
      // started at spawn. References seq + the same raw_sha256 the WARD turn
      // envelope carries; no raw turn body, no secret. Best-effort.
      try {
        const voltRunId = devLoopVoltRuns.get(req.params.id);
        const entry = buildLoopVoltEntry(result.session, ev);
        if (voltRunId && entry) voltEmitter.emit(voltRunId, entry.eventType, entry.payload);
      } catch (voltErr) {
        console.error(`[DevLoop] VOLT turn emit failed for ${req.params.id} seq ${ev.seq}:`, voltErr.message);
      }
    }
    // EVIDENCED: on session done, complete the VOLT run and emit the AOCL
    // run.complete layer event. Best-effort; the wire response below is
    // unchanged.
    if (result.done) {
      const voltRunId = devLoopVoltRuns.get(req.params.id);
      if (voltRunId) {
        try { voltEmitter.completeRun(voltRunId); }
        catch (voltErr) { console.error(`[DevLoop] VOLT completeRun failed for ${req.params.id}:`, voltErr.message); }
        devLoopVoltRuns.delete(req.params.id);
      }
      try {
        storeAuditEnvelope({
          type: 'event',
          from: `host.${result.session.host_id}`,
          to: 'system.aocl',
          intent: 'aocl.run.complete',
          corr: req.params.id,
          payload: {
            session_id: req.params.id, org_id: result.session.org_id || null,
            source: 'dev_loop', success: true, aocl: classifyLoopAocl(),
          },
        });
      } catch (aoclErr) {
        console.error(`[DevLoop] AOCL complete envelope failed for ${req.params.id}:`, aoclErr.message);
      }
    }
    // Keep the wire response the forwarder expects; session/newEvents stay
    // server-internal (they carry the token-hash-adjacent row and would bloat
    // the response).
    res.json({ ok: result.ok, inserted: result.inserted, done: result.done });
  } catch (err) {
    if (err.code === 'unknown_session') return res.status(404).json({ error: 'unknown session' });
    if (err.code === 'bad_token') return res.status(401).json({ error: 'bad ingest token' });
    console.error('[DevLoop] Event ingest failed:', err.message);
    res.status(500).json({ error: 'ingest failed' });
  }
});

app.get('/api/v1/dev-sessions/:id/events', requireServiceOrUserAuth(), (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  const session = devLoopSessions.getLoopSession(aeeDb, req.params.id);
  if (!session) return res.status(404).json({ error: 'unknown session' });
  // Tenancy: this route resolved the org from the SESSION, so anyone who knew
  // (or guessed) a session id could read another org's loop events. Pin JWT
  // users to their own token org, the same posture resolveSlotOrgId uses and
  // identical to the interrupt route's fix below. Internal service callers
  // are unchanged: they legitimately act across orgs and carry no user org
  // of their own.
  if (req.user) {
    const callerOrg = resolveRequestOrgId(req);
    if (!callerOrg || (session.org_id && callerOrg !== session.org_id)) {
      return res.status(404).json({ error: 'unknown session' });
    }
  }
  try {
    const sinceSeq = parseInt(req.query.since_seq, 10) || 0;
    const limit = parseInt(req.query.limit, 10) || 200;
    res.json(devLoopSessions.listEventsSince(aeeDb, req.params.id, sinceSeq, limit));
  } catch (err) {
    if (err.code === 'unknown_session') return res.status(404).json({ error: 'unknown session' });
    console.error('[DevLoop] Event read failed:', err.message);
    res.status(500).json({ error: 'read failed' });
  }
});

// DEVSUITE-HUB dev.sessions window: org-scoped session listing, optionally
