// ============================================================================
// QUOXON J1: one org-scoped index of live sessions (GET /api/v1/sessions) +
// the `quox claude` wrapper heartbeat/end. Same auth and org resolution as the
// live-sessions routes above (authenticated only, resolveSlotOrgId, fails
// closed). Objectives/executions are read from tasks/quoxflow with the
// CALLER'S OWN bearer token (both lists are org-scoped by that token), so the
// index never sees more than the caller could list directly. Handlers live in
// lib/sessionsIndexRoutes.js; deps are closures so later-declared module
// state (devSlots) is read at request time.
// ============================================================================
{
  const forwardJson = async (url, req) => {
    const authz = req.headers.authorization;
    if (!authz) throw new Error('no user token to forward');
    const r = await fetch(url, { headers: { Authorization: authz, Accept: 'application/json' }, signal: AbortSignal.timeout(2500) });
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    return r.json();
  };
  const listOf = (d, ...keys) => { for (const k of keys) if (Array.isArray(d?.[k])) return d[k]; return Array.isArray(d) ? d : null; };
  require('./lib/sessionsIndexRoutes.js').registerSessionsIndexRoutes(app, {
    db: () => aeeDb,
    auth: requireServiceOrUserAuth,
    resolveOrgId: resolveSlotOrgId,
    listConversations: ({ orgId, userId, limit }) => require('./lib/chatSessionHistory.js').listSessions({ orgId, userId, limit }),
    listSlots: ({ orgId }) => devSlots.listSlots({ orgId }),
    // Declared later in this file; read at request time. Running turns only (finished = resting).
    runningConversations: ({ orgId, userId }) => conversationTurnRegistry.runningConversations({ orgId, userId }),
    fetchObjectives: async ({ req }) => {
      const base = `http://${process.env.TASKS_HOST || 'tasks'}:${process.env.TASKS_PORT || '3104'}`;
      return listOf(await forwardJson(`${base}/api/objectives?limit=100`, req), 'objectives');
    },
    fetchExecutions: async ({ req }) => {
      const base = process.env.QUOXFLOW_URL || 'http://quoxflow:3200';
      return listOf(await forwardJson(`${base}/api/executions`, req), 'data', 'items', 'executions');
    },
    // No server host label: the collector runs in a container (os.hostname() is a container id).
    hostname: () => null,
  });
}

// ============================================================================
// QUOXON E5: "What happened while I was away?" GET /api/v1/away?since=<iso>.
// Read-only digest from real sources (lib/awayDigest.js). Remote services are
// read with the CALLER'S OWN bearer (each list is org- and member-scoped by that
// token, as in the sessions index above); a service caller without a bearer
// uses the service key with its resolved org. A source that cannot be read is
// reported as blind, never as empty.
// ============================================================================
{
  const away = require('./lib/awayDigest.js');
  const listOf = (d, ...keys) => { for (const k of keys) if (Array.isArray(d?.[k])) return d[k]; return Array.isArray(d) ? d : []; };
  const getJson = async (url, req, ctx) => {
    const headers = { Accept: 'application/json' };
    if (req.headers.authorization) headers.Authorization = req.headers.authorization;
    else if (req.service && process.env.INTERNAL_SERVICE_KEY) {
      headers['X-Service-Key'] = process.env.INTERNAL_SERVICE_KEY;
      headers['X-Org-Id'] = ctx.orgId;
      if (ctx.userId) headers['X-User-Id'] = ctx.userId;
    } else throw new Error('no credential to forward');
    const r = await fetch(url, { headers, signal: AbortSignal.timeout(4000) });
    if (!r.ok) throw new Error(away.httpReason(r.status, await r.text().catch(() => '')));
    return r.json();
  };
  const aee = () => { if (!aeeDb) throw new Error('evidence store unavailable'); return aeeDb; };
  require('./lib/awayRoutes.js').registerAwayRoutes(app, {
    auth: requireServiceOrUserAuth,
    resolveOrgId: resolveSlotOrgId,
    readersFor: (req, ctx) => ({
      approvals: async () => {
        const base = `${AUTH_SERVICE_URL}/api/orgs/${encodeURIComponent(ctx.orgId)}/inbox?kind=approval&limit=100`;
        const [waiting, resolved] = await Promise.all([getJson(base, req, ctx), getJson(`${base}&status=resolved`, req, ctx)]);
        return { items: away.mapApprovals(listOf(waiting, 'items'), listOf(resolved, 'items'), ctx.sinceMs) };
      },
      objectives: async () => {
        const base = `http://${process.env.TASKS_HOST || 'tasks'}:${process.env.TASKS_PORT || '3104'}`;
        return { items: away.mapObjectives(listOf(await getJson(`${base}/api/objectives?limit=100`, req, ctx), 'objectives'), ctx.sinceMs) };
      },
      workflows: async () => {
        const base = process.env.QUOXFLOW_URL || 'http://quoxflow:3200';
        return { items: away.mapExecutions(listOf(await getJson(`${base}/api/executions?limit=100`, req, ctx), 'data', 'items', 'executions'), ctx.sinceMs, ctx.userId) };
      },
      lucid: async () => {
        const journal = require('./lib/lucid/journal.js');
        if (!lucidDb || !journal.isReady()) throw new Error('LUCID storage unavailable');
        const viewer = ctx.userId ? `user:${ctx.userId}` : 'owner';
        const v = require('./lib/lucid/routes.js').situationFor(ctx.orgId, { since: String(journal.latestSeq(ctx.orgId)), viewer, surface: 'away', advance: false });
        return away.mapSituation(v.situation, ctx.sinceMs);
      },
      decisions: async () => {
        const base = (process.env.QUOXBRAIN_URL || 'http://quoxbrain:3106').replace(/\/$/, '');
        const d = await getJson(`${base}/brain/decisions?since=${encodeURIComponent(new Date(ctx.sinceMs).toISOString())}`, req, ctx);
        return { items: away.mapDecisions(listOf(d, 'decisions')) };
      },
      turns: async () => ({ items: away.failedTurns(aee(), ctx) }),
      activity: async () => ({ activity: away.agentActivity(aee(), ctx) }),
    }),
  });
}

// ============================================================================
// DEVSUITE-SLOTS Phase 3 — server-side slot registry (design in QuoxPlan
// DEVSUITE-SLOTS plan v2 section 2a). A slot is a fixed, org-curated
// address (T1..T8, or named: `triage`, `builder`) that a session checks
// out and releases; checkout is compare-and-swap so two sessions racing
// the same slot cannot both win. Same auth posture as the dev-sessions
// routes above (requireServiceOrUserAuth, org resolved via
// resolveRequestOrgId). Checkout/release/create/retire are witnessed
// AEE envelopes (quox.slot.*); heartbeat is not (too noisy at 15s-60s
// cadence to be worth a WARD entry per beat).
// ============================================================================
const devSlots = require('./lib/devSlotsStore.js').createDevSlotsStore({ getDb: () => aeeDb });
const { readThroughOf } = require('./lib/devSlotsStore.js');
// PRESENCE (owner 2026-10-16): /afk, /sleep, /back. Per (org, user) in aee.db; read by slot responses,
// slot list, quox presence, the presence_get tool, turn context and approval-request responses.
// Approvals still queue exactly as before: presence never approves, denies or skips anything.
const userPresenceLib = require('./lib/userPresence.js');
const userPresence = userPresenceLib.createUserPresenceStore({ getDb: () => aeeDb });
userPresenceLib.setDefaultStore(userPresence);
require('./lib/userPresenceRoutes.js').registerUserPresenceRoutes(app, {
  getStore: () => (aeeDb ? userPresence : null), auth: requireServiceOrUserAuth, resolveOrgId: resolveSlotOrgId,
  audit: (e) => storeAuditEnvelope(e),
});
// PRESENCE clears ONLY through the explicit POST /api/v1/presence/activity, called by the interactive TUI or a PIN step-up.
// Never implicitly on chat or approval routes: proof runs and agents drive `quox -p moo chat` with the owner's JWT all day.
/** human_presence for a response about one slot: set only when that slot's human is away. Never throws. */
function humanPresenceForSlot(orgId, slotName) {
  try { return aeeDb ? userPresenceLib.slotPresenceField(userPresence.forSlot({ orgId, slot: slotName })) : null; } catch { return null; }
}
/** [OWNER PRESENCE] for a chat turn in this org; '' when nobody is away. Never throws. */
function presenceContextBlock(orgId) {
  try { return aeeDb && orgId ? userPresenceLib.contextBlock(userPresence.awayHumans({ orgId })) : ''; } catch { return ''; }
}
// QUOXON-PROOF (quox#824): the slot_list agent tool reads this store in-process (same
// licence gate as GET /api/v1/slots) instead of a loopback fetch that queued behind busy turns.
require('./lib/slotTools.js').configureSlotStore({
  listSlots: (args) => devSlots.listSlots(args),
  isLicensed: (orgId) => isPluginLicensedForOrg(orgId, 'quoxslots'),
});
// QUOXON lane S: slot_create / slot_checkout run in-process with the caller from the turn
// identity (the Claude CLI's per-turn token cannot reach the slot routes). Same licence gate.
require('./lib/slotTools.js').configureSlotActions({
  create: async ({ orgId, name, notes, actor }) => {
    if (!aeeDb) return { ok: false, code: 'storage_unavailable' };
    if (!(await isPluginLicensedForOrg(orgId, 'quoxslots'))) return { ok: false, code: 'unlicensed' };
    return withSlotRoom(createSlotWithEffects({ orgId, name, notes, actor }));
  },
  checkout: async ({ orgId, name, holderSession, holderKind, holderIdentity, create, actor }) => {
    if (!aeeDb) return { ok: false, code: 'storage_unavailable' };
    if (!(await isPluginLicensedForOrg(orgId, 'quoxslots'))) return { ok: false, code: 'unlicensed' };
    const result = devSlots.checkoutSlot({ orgId, name, holderSession, holderKind, holderIdentity, create: create === true, createdBy: actor });
    if (result.ok) {
      runCheckoutSideEffects({
        result, orgId, name, actor, holder_session: holderSession, holder_kind: holderKind, host_id: null,
        storeAuditEnvelope, provisionSlotRoom, devSlots, devSlotDiscord,
      });
    }
    return withSlotRoom(result);
  },
});
const {
  callerFromReq, evaluateMemberJoin, createClaimHandler: createSlotClaimHandler,
} = require('./lib/slotSplinter.js');
// QUOXPERTICUS-REVISIT P3: the interactive-checkout tmux-session gate (see
// devSlotsResidentGate.js's doc comment).
const devSlotsResidentGate = require('./lib/devSlotsResidentGate.js');
const { runCheckoutSideEffects } = require('./lib/devSlotCheckoutEffects.js');
// DEVSUITE-SLOTS phase 4: derive a Matrix room per slot through the existing
// M-ROOMS provisioning path (auth's /api/internal/matrix/provision-node,
// node_type 'dev_slot'). Fail-soft by contract, see devSlotMatrixProvision.js.
const { provisionSlotRoom: provisionSlotRoomRaw, deprovisionSlotRoom, relaySlotMessage, renderSlotLineToBridge, probeBridgeRoom, isDiscordWebhook, isSlotsOwnPuppetSender } = require('./lib/devSlotMatrixProvision.js');
// QUOXON-MESH: every room provision goes through one tracker (deduped per slot, waitable, and the delivery
// point for a say that landed before the room existed; lib/devSlotRoomTracker.js).
const slotRoomTracker = require('./lib/devSlotRoomTracker.js').createSlotRoomTracker({
  provision: provisionSlotRoomRaw, relay: relaySlotMessage,
});
const provisionSlotRoom = (args) => slotRoomTracker.provision(args);
const SLOT_ROOM_WAIT_MS = 10 * 1000;
// create/checkout return with a room when one lands within the bound, so the next say finds it.
async function withSlotRoom(result) {
  if (!result || !result.ok || !result.slot || result.slot.matrix_room_id) return result;
  const roomId = await slotRoomTracker.waitForRoom(result.slot.id, SLOT_ROOM_WAIT_MS);
  if (roomId) return { ...result, slot: { ...result.slot, matrix_room_id: roomId } };
  return { ...result, room_pending: true };
}
// DEVSUITE-SLOTS item 5: the per-slot Discord channel. Lifecycle mirrors the
// Matrix room at the same call sites, EXCEPT retire keeps the channel (owner
// decision; see the module header). All calls fail-soft.
const devSlotDiscord = require('./lib/devSlotDiscordProvision.js');
// DEVSUITE-SLOTS phase 5: the say/read message cache (see the migration
// file + devSlotMessagesStore.js header — a CACHE of the room, not the
// truth; no server-side Matrix timeline-read precedent exists yet).
const devSlotMessages = require('./lib/devSlotMessagesStore.js').createDevSlotMessagesStore({ getDb: () => aeeDb });
const { deriveSlotAuthor, deriveCallerIdentity, deriveSayIdentity, deriveOnBehalfOf, validateSlotLabel, checkSlotSayAuthor, checkFromSlot, resolveFromSlot, validateRunCommand } = require('./lib/devSlotMessagesStore.js');
// QUOXIDENTITY DEFECT #2: CommanderQ must defer to a held slot's own voice
// rather than front-run it. See lib/commanderQHeldSlotDefer.js.
const { checkHeldMatrixSlotDefer } = require('./lib/commanderQHeldSlotDefer.js');
// QUOXIDENTITY DEFECT #1: Matrix inbound was never ingested. See
// lib/devSlotInboundByRoom.js.
const { handleInboundByRoom } = require('./lib/devSlotInboundByRoom.js');
// DEVSUITE-SLOTS wait verb: long-poll seam so a holding session can block on
// inbound messages instead of hand-rolling a poll loop (see devSlotWait.js
// header for the 2026-08-22 deaf-resident incident that mandated this).
const devSlotRoomMembers = require('./lib/devSlotRoomMembers.js').createDevSlotRoomMembers({ getDb: () => aeeDb });
const devSlotWait = require('./lib/devSlotWait.js').createDevSlotWait({ devSlots, devSlotMessages });
// DEVSUITE-SLOTS phase 9: governed, org-scoped bridge-room config, replacing
// QUOX_SLOT_BRIDGE_ROOM / QUOX_SLOT_DISCORD_ROOM as the primary source (env
// vars kept as a fallback only — see no-env-only-config in CLAUDE.md).
const devSlotBridges = require('./lib/devSlotBridgesStore.js').createDevSlotBridgesStore({ getDb: () => aeeDb });
// NO-ENV-ONLY-CONFIG: the per-org QLarity origin allowlist, replacing the
// install-wide QLARITY_ALLOWLIST env var as the thing a CUSTOMER can manage.
// See migrations/aee/016-qlarity-org-allowlist.sql for the scope boundary.
const qlarityAllowlist = require('./lib/qlarityAllowlistStore.js').createQlarityAllowlistStore({ getDb: () => aeeDb });
// quox#1171: per-org URL-prefix allowlist behind the governed agent fetch tool
// (web_fetch_allowlisted). Routes are mounted next to the qlarity-allowlist ones.
const agentFetchAllowlist = require('./lib/agentFetchAllowlistStore.js').createAgentFetchAllowlistStore({ getDb: () => aeeDb });
require('./lib/allowlistedFetchTool.js').configureAllowlistedFetch({
  store: agentFetchAllowlist,
  audit: (e) => storeAuditEnvelope(e),
});
// SDK-TEAM #5002: web_search reads the same allowlist for an admin-named private SearXNG origin.
require('./lib/webResearch.js').configureWebResearch({ store: agentFetchAllowlist, audit: (e) => storeAuditEnvelope(e) });

// quox#665: no slot route may send the per-channel Discord webhook URL (it
// embeds its own posting token). Registered BEFORE every /api/v1/slots route,
// so records returned by any route, present or future, are redacted to
// discord_webhook_set. The store keeps the URL for the server-side say/heal paths.
app.use('/api/v1/slots', require('./lib/devSlotPublic.js').slotResponseGuard);

app.get('/api/v1/slots', requireServiceOrUserAuth(), requireLicence('quoxslots', 'QuoxSlots'), (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  const orgId = resolveSlotOrgId(req);
  if (!orgId) return res.status(400).json({ error: 'org could not be resolved' });
  try {
    // PRESENCE: which humans are away, and on each human slot (hitl, triage-q, a window's own) who is.
    let humans = [];
    try { humans = userPresence.list({ orgId }).map((p) => ({ who: p.who, state: p.state, away: p.away, since: p.since, note: p.note, slots: p.slots })); } catch { humans = []; }
    const slots = devSlots.listSlots({ orgId }).map((sl) => { const hp = humanPresenceForSlot(orgId, sl.name); return hp ? { ...sl, human_presence: hp } : sl; });
    res.json({ slots, humans });
  } catch (err) {
    console.error('[DevSlots] list failed:', err.message);
    res.status(500).json({ error: 'list failed' });
  }
});

// Retire a slot and (optionally) delete its Discord channel. Shared by the
// retire route (delete_channel:true) and /prune. Returns { ok, slot, channel? }.
async function retireSlotAndMaybeDeleteChannel({ orgId, name, actor, deleteChannel }) {
  const result = devSlots.retireSlot({ orgId, name });
  if (!result.ok) return { ok: false };
  storeAuditEnvelope({
    type: 'event', from: actor, to: 'audit.system', intent: 'quox.slot.retire',
    corr: result.slot.id, payload: { org_id: orgId, name },
  });
  deprovisionSlotRoom({ orgId, slotId: result.slot.id })
    .catch((err) => console.warn(`[DevSlots] room deprovision for ${name} failed (non-fatal): ${err.message}`));
  const channelId = result.slot.discord_channel_id;
  let channel;
  if (channelId && deleteChannel) {
    const del = await devSlotDiscord.deleteSlotDiscordChannel({ channelId });
    channel = { deleted: !!del.deleted, error: del.error || null };
    storeAuditEnvelope({
      type: 'event', from: actor, to: 'audit.system', intent: 'quox.slot.channel_deleted',
      corr: result.slot.id, payload: { org_id: orgId, name, channel_id: channelId, deleted: !!del.deleted, error: del.error || null },
    });
    // The slot row is already gone after retire, so there is nothing left to
    // clear; setSlotDiscord is a harmless no-op that keeps this honest if
    // retire ever becomes a soft delete.
    if (del.deleted) {
      try { devSlots.setSlotDiscord({ orgId, name, channelId: null, webhookUrl: null }); } catch { /* row gone */ }
    }
  } else if (channelId) {
    // Default: channel kept for its history, marked disconnected.
    devSlotDiscord.updateSlotDiscordStatus({ channelId, slotName: name, state: 'retired' })
      .then(() => devSlotDiscord.postSlotDiscordMessage({
        channelId,
        content: `slot **${name}** has been retired: this channel is disconnected and kept only for its history.`,
      }))
      .catch((err) => console.warn(`[DevSlots] discord retire status for ${name} failed (non-fatal): ${err.message}`));
  }
  return { ok: true, slot: result.slot, channel };
}

// QUOXON-BROADCAST: /broadcast fan-out. One call delivers to the caller's org's held slots (or --slots),
// returns per-slot status (delivered / queued / failed / unknown), stores the broadcast and its acks.
// Registered before the :name routes. Recipients come only from the caller's org (lib/devSlotBroadcast.js).
const devSlotBroadcast = require('./lib/devSlotBroadcast.js').createDevSlotBroadcast({
  getDb: () => aeeDb,
  devSlots,
  devSlotMessages: { appendMessage: (a) => devSlotMessages.appendMessage(a) },
  relay: ({ slot, text, from }) => relaySlotMessage({ roomId: slot.matrix_room_id, slotId: slot.id, slotName: slot.name, text, from }),
});
app.post('/api/v1/slots/broadcast', requireServiceOrUserAuth(), requireLicence('quoxslots', 'QuoxSlots'), async (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  const orgId = resolveSlotOrgId(req);
  if (!orgId) return res.status(400).json({ error: 'org could not be resolved' });
  const { text, from, slots, priority, ack } = req.body || {};
  const labelCheck = validateSlotLabel(from);
  if (!labelCheck.ok) return res.status(400).json({ error: labelCheck.error });
  if (slots !== undefined && slots !== null && !Array.isArray(slots)) return res.status(400).json({ error: 'slots must be an array of names' });
  try {
    const identity = deriveCallerIdentity(req);
    const sender = deriveSlotAuthor(req, labelCheck.value);
    const r = await devSlotBroadcast.broadcast({ orgId, text, from: sender, identity, slots, priority: priority || 'normal', ack: ack === true });
    if (!r.ok) return res.status(r.status || 400).json({ error: r.error });
    storeAuditEnvelope({
      type: 'event', from: `session.${sender}`, to: 'audit.system', intent: 'quox.slot.broadcast', corr: r.id,
      payload: { org_id: orgId, broadcast_id: r.id, from: sender, author_identity: identity, priority: r.priority, ack: r.ack, recipients: r.deliveries.map((d) => d.slot), text_length: String(text).length },
    });
    // PRESENCE: a broadcast or page that reaches a human slot while its human is away says so.
    const hp = (r.deliveries || []).map((d) => humanPresenceForSlot(orgId, d.slot)).find(Boolean) || null;
    res.json(hp ? { ...r, human_presence: hp } : r);
  } catch (err) {
    console.error('[DevSlots] broadcast failed:', err.message);
    res.status(500).json({ error: 'broadcast failed' });
  }
});
app.get('/api/v1/slots/broadcast/:id', requireServiceOrUserAuth(), requireLicence('quoxslots', 'QuoxSlots'), (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  const orgId = resolveSlotOrgId(req);
  if (!orgId) return res.status(400).json({ error: 'org could not be resolved' });
  try {
    const st = devSlotBroadcast.status({ orgId, id: req.params.id });
    if (!st) return res.status(404).json({ error: 'unknown broadcast' });
    res.json(st);
  } catch (err) { res.status(500).json({ error: 'broadcast status failed' }); }
});
app.post('/api/v1/slots/broadcast/:id/ack', requireServiceOrUserAuth(), requireLicence('quoxslots', 'QuoxSlots'), (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  const orgId = resolveSlotOrgId(req);
  if (!orgId) return res.status(400).json({ error: 'org could not be resolved' });
  try {
    const r = devSlotBroadcast.ack({ orgId, id: req.params.id, slot: (req.body || {}).slot, by: deriveCallerIdentity(req) });
    if (!r.ok) return res.status(r.status || 400).json({ error: r.error });
    storeAuditEnvelope({
      type: 'event', from: `session.${deriveCallerIdentity(req)}`, to: 'audit.system', intent: 'quox.slot.broadcast_ack', corr: req.params.id,
      payload: { org_id: orgId, broadcast_id: req.params.id, slot: String((req.body || {}).slot) },
    });
    res.json(r.broadcast);
  } catch (err) { res.status(500).json({ error: 'broadcast ack failed' }); }
});

app.post('/api/v1/slots/prune', requireServiceOrUserAuth(), requireLicence('quoxslots', 'QuoxSlots'), async (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  const orgId = resolveSlotOrgId(req);
  if (!orgId) return res.status(400).json({ error: 'org could not be resolved' });
  if (!requireAdminRole(req, res, 'Pruning slots requires an org admin')) return;
  const body = req.body || {};
  const days = body.older_than_days === undefined ? 14 : Number(body.older_than_days);
  if (!Number.isFinite(days) || days < 0) return res.status(400).json({ error: 'older_than_days must be a non-negative number' });
  const dryRun = body.dry_run !== false;
  const deleteChannels = body.delete_channels !== false;
  const actor = req.user ? `human.${req.user.id || req.user.sub || 'unknown'}` : 'system.tasks';
  try {
    const candidates = require('./lib/devSlotPrune.js').selectPruneCandidates(devSlots.listSlots({ orgId }), { olderThanDays: days });
    // Orphan sweep (SLOTS-TIDY): daemon slot channels whose slot name is live
    // in NO org. Deletion is instance-wide, so it is gated (see
    // canDeleteInstanceOrphans); other callers get the count only.
    const pruneLib = require('./lib/devSlotPrune.js');
    let orphans = [];
    let orphanError = null;
    const includeOrphans = body.include_orphans !== false;
    const mayDeleteOrphans = pruneLib.canDeleteInstanceOrphans(req);
    if (includeOrphans) {
      const bindings = await devSlotDiscord.getSlotDiscordBindings();
      if (bindings === null) { orphans = null; orphanError = 'discord daemon unreachable; orphan channels unknown'; }
      else orphans = pruneLib.selectOrphanChannels(bindings, devSlots.listAllSlotNames());
    } else { orphans = undefined; }
    const orphanFields = () => (orphans === undefined ? {} : {
      orphans: mayDeleteOrphans || orphans === null ? orphans : undefined,
      ...(orphans && !mayDeleteOrphans ? { orphan_count: orphans.length, orphans_note: 'listing and deleting instance-wide orphan channels requires the instance owner org admin or a system admin' } : {}),
      ...(orphanError ? { orphans_error: orphanError } : {}),
    });
    if (dryRun) return res.json({ dry_run: true, older_than_days: days, candidates, ...orphanFields() });
    const results = [];
    for (const c of candidates) {
      try {
        const r = await retireSlotAndMaybeDeleteChannel({ orgId, name: c.name, actor, deleteChannel: deleteChannels });
        results.push({ name: c.name, retired: !!r.ok, ...(r.channel ? { channel: r.channel } : {}) });
      } catch (err) {
        results.push({ name: c.name, retired: false, error: err.message });
      }
    }
    storeAuditEnvelope({
      type: 'event', from: actor, to: 'audit.system', intent: 'quox.slot.prune',
      corr: orgId, payload: { org_id: orgId, older_than_days: days, delete_channels: deleteChannels, count: results.length },
    });
    let orphanResults;
    if (Array.isArray(orphans) && mayDeleteOrphans) {
      orphanResults = [];
      for (const o of orphans) {
        const r = await devSlotDiscord.deleteSlotDiscordChannel({ channelId: o.channel_id });
        orphanResults.push({ slot_name: o.slot_name, channel_id: o.channel_id, deleted: !!r.deleted, ...(r.error ? { error: r.error } : {}) });
        if (r.deleted) {
          storeAuditEnvelope({
            type: 'event', from: actor, to: 'audit.system', intent: 'quox.slot.orphan_channel_deleted',
            corr: o.channel_id, payload: { requesting_org_id: orgId, slot_name: o.slot_name, channel_id: o.channel_id },
          });
        }
      }
    }
    res.json({ dry_run: false, older_than_days: days, results, ...orphanFields(), ...(orphanResults ? { orphan_results: orphanResults } : {}) });
  } catch (err) {
    console.error('[DevSlots] prune failed:', err.message);
    res.status(500).json({ error: 'prune failed' });
  }
});

// QUOXON lane S: the create core, shared by POST /api/v1/slots and the slot_create agent
// tool (lib/slotTools.js configureSlotActions). The caller's admin gate stays at each entry.
function createSlotWithEffects({ orgId, name, notes, actor }) {
  const result = devSlots.createSlot({ orgId, name, createdBy: actor, notes });
  if (!result.ok) return result;
  storeAuditEnvelope({
    type: 'event', from: actor, to: 'audit.system', intent: 'quox.slot.create',
    corr: result.slot.id, payload: { org_id: orgId, name, notes: notes || null },
  });
  // Fire-and-forget room derivation (M-ROOMS #416 path): a Matrix/auth
  // outage must never fail the create response. Success writes the room
  // id back onto the slot row (denorm cache; auth's ledger is the truth).
  provisionSlotRoom({ orgId, slotId: result.slot.id, label: `Slots > ${name}` })
    .then((roomId) => {
      if (roomId) {
        devSlots.setSlotRoomId({ orgId, name, roomId });
        // #574: announce the write-back. Success was previously silent,
        // so an empty matrix_room_id right after create (fire-and-forget
        // had not finished) read as "provisioning never ran".
        console.log(`[DevSlotMatrix] slot ${name} room provisioned and written back: ${roomId}`);
      }
    })
    .catch((err) => console.warn(`[DevSlots] room provision for ${name} failed (non-fatal): ${err.message}`));
  // Item 5: the channel follows the SLOT, so it is born here. Same
  // fail-soft contract as the room; a later checkout heals a miss.
  devSlotDiscord.provisionSlotDiscordChannel({ slotName: name })
    .then((ch) => {
      if (!ch) return;
      devSlots.setSlotDiscord({ orgId, name, channelId: ch.channelId, webhookUrl: ch.webhookUrl });
      // #574: announce the write-back (was silent on success).
      console.log(`[DevSlotDiscord] slot ${name} channel provisioned and written back: ${ch.channelId}`);
      return devSlotDiscord.updateSlotDiscordStatus({ channelId: ch.channelId, slotName: name, state: 'free' });
    })
    .catch((err) => console.warn(`[DevSlots] discord provision for ${name} failed (non-fatal): ${err.message}`));
  return result;
}

app.post('/api/v1/slots', requireServiceOrUserAuth(), requireLicence('quoxslots', 'QuoxSlots'), async (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  const orgId = resolveSlotOrgId(req);
  if (!orgId) return res.status(400).json({ error: 'org could not be resolved' });
  const { name, notes, retire, delete_channel: deleteChannel } = req.body || {};
  if (!name) return res.status(400).json({ error: 'name is required' });
  // Curating the slot POOL (create/retire the named addresses) is an admin
  // action; USING slots (checkout/release/say) stays open to any org member.
  // requireAdminRole allows a real org admin/owner JWT and service-key callers
  // (the CLI, internal), and 403s a plain member/viewer.
  if (!requireAdminRole(req, res, retire ? 'Retiring a slot requires an org admin' : 'Creating a slot requires an org admin')) return;
  const actor = req.user ? `human.${req.user.id || req.user.sub || 'unknown'}` : 'system.tasks';

  try {
    if (retire) {
      const r = await retireSlotAndMaybeDeleteChannel({ orgId, name, actor, deleteChannel: deleteChannel === true });
      if (!r.ok) return res.status(404).json({ error: 'unknown slot' });
      return res.json({ slot: r.slot, ...(r.channel ? { channel: r.channel } : {}) });
    }

    const result = createSlotWithEffects({ orgId, name, notes, actor });
    if (!result.ok) {
      if (result.code === 'bad_name') return res.status(400).json({ error: 'name must match /^[a-z0-9-]{1,32}$/' });
      if (result.code === 'duplicate') return res.status(409).json({ error: 'slot already exists' });
      return res.status(500).json({ error: 'create failed' });
    }
    res.status(201).json({ slot: result.slot });
  } catch (err) {
    console.error('[DevSlots] create/retire failed:', err.message);
    res.status(500).json({ error: 'create/retire failed' });
  }
});

app.post('/api/v1/slots/:name/checkout', requireServiceOrUserAuth(), requireLicence('quoxslots', 'QuoxSlots'), async (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  const orgId = resolveSlotOrgId(req);
  if (!orgId) return res.status(400).json({ error: 'org could not be resolved' });
  const { holder_session, holder_kind, host_id, force, create, take } = req.body || {};
  if (!holder_session) return res.status(400).json({ error: 'holder_session is required' });

  // QUOXPERTICUS-REVISIT P3: an interactive checkout naming a dev host must
  // name a REAL tmux session on that host, not just any string. Untouched
  // for every other checkout (no host, human free-text sessions, loop/
  // resident kind) — see devSlotsResidentGate.js's own doc comment.
  try {
    const gate = await devSlotsResidentGate.checkResidentSessionGate(
      { getServer: (hostId) => getDevServer(aeeDb, hostId), listSessions: devSessionsListInvoke },
      { orgId, hostId: host_id, holderKind: holder_kind, holderSession: holder_session }
    );
    if (!gate.ok) {
      return res.status(409).json({
        error: 'session not found',
        message: gate.message,
        detail: { code: gate.code, host_id, holder_session },
      });
    }
  } catch (err) {
    // A gate that cannot even run must never silently become a refusal —
    // that would turn an internal bug into every interactive checkout on
    // every dev host failing. Log and proceed, same fail-open posture as a
    // transport error inside the gate itself.
    console.warn(`[DevSlots] resident session gate failed (non-fatal): ${err.message}`);
  }

  try {
    const actor = req.user ? `human.${req.user.id || req.user.sub || 'unknown'}` : `session.${holder_session}`;
    const result = devSlots.checkoutSlot({
      orgId, name: req.params.name,
      holderSession: holder_session, holderKind: holder_kind, hostId: host_id,
      // quox#584: bind the hold to the AUTHENTICATED identity server-side so
      // a resident that checked out under a display --session name can still
      // pass the say double-voice gate as itself.
      holderIdentity: deriveCallerIdentity(req),
      force: force === true, create: create === true, take: take === true, createdBy: actor,
    });
    if (!result.ok) {
      if (result.code === 'bad_name') return res.status(400).json({ error: 'name must match /^[a-z0-9-]{1,32}$/' });
      if (result.code === 'not_found') return res.status(404).json({ error: 'unknown slot' });
      // An assignment now actually protects the slot. Name the assignee and
      // the override, so this reads as a decision rather than a mystery.
      if (result.code === 'assigned_to_other') {
        return res.status(409).json({
          error: 'slot assigned',
          message: `slot ${req.params.name} is assigned to ${result.slot?.assigned_to || 'another session'}; pass --force to take it anyway`,
          detail: { assigned_to: result.slot?.assigned_to || null },
          slot: result.slot,
        });
      }
      // QUOXIDENTITY P10: an attach caller of the agent this slot is bound to,
      // while another session of that same agent holds it, JOINS as a member
      // instead of being refused. Everything else falls through to the 409.
      if (result.code === 'conflict') {
        const joinResult = evaluateMemberJoin({
          req, orgId, slot: result.slot, holderSession: holder_session, identity: deriveCallerIdentity(req),
          getBindingBySlot: (a) => agentSlotBindings.getBindingBySlot(a), devSlots,
        });
        if (joinResult.joined) {
          storeAuditEnvelope({
            type: 'event', from: `session.${holder_session}`, to: 'audit.system', intent: 'quox.slot.member_join',
            corr: result.slot.id,
            payload: {
              org_id: orgId, name: req.params.name, member_key: joinResult.member.member_key,
              splinter: joinResult.member.splinter || null, member_session: holder_session,
              agent_id: req.user.agent_id, attach_lease_id: req.user.attach_lease_id,
            },
          });
          return res.json({ slot: joinResult.slot, joined: true, member: joinResult.member });
        }
      }
      // CLI phase 5: `message` + `detail.holder_session` so `quox slot
      // checkout` can render "slot <name> is held by <holder>" — the CLI
      // http client (cli/lib/core/client.js) only forwards data.message and
      // data.detail onto the thrown error, so a bare `slot` field here would
      // be silently dropped before the command ever sees the holder.
      return res.status(409).json({
        error: 'slot held',
        message: `slot ${req.params.name} is held by ${result.slot?.holder_session || 'unknown'}`,
        detail: {
          holder_session: result.slot?.holder_session || null,
          state: result.slot?.state || null,
          same_user: result.sameUser === true,
          checked_out_at: result.slot?.checked_out_at || null,
          last_heartbeat_at: result.slot?.last_heartbeat_at || null,
        },
        slot: result.slot,
      });
    }
    runCheckoutSideEffects({
      result, orgId, name: req.params.name, actor, holder_session, holder_kind, host_id,
      storeAuditEnvelope, provisionSlotRoom, devSlots, devSlotDiscord,
    });
    res.json(result.refreshed ? { slot: result.slot, refreshed: true } : result.tookOver ? { slot: result.slot, took_over: result.tookOver } : { slot: result.slot });
  } catch (err) {
    console.error('[DevSlots] checkout failed:', err.message);
    res.status(500).json({ error: 'checkout failed' });
  }
});

app.post('/api/v1/slots/:name/release', requireServiceOrUserAuth(), requireLicence('quoxslots', 'QuoxSlots'), (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  const orgId = resolveSlotOrgId(req);
  if (!orgId) return res.status(400).json({ error: 'org could not be resolved' });
  const { holder_session, force } = req.body || {};

  try {
    const result = devSlots.releaseSlot({
      orgId, name: req.params.name, holderSession: holder_session, force: !!force,
      holderIdentity: deriveCallerIdentity(req),
      memberKey: callerFromReq(req).memberKey,
    });
    if (!result.ok) {
      if (result.code === 'not_found') return res.status(404).json({ error: 'unknown slot' });
      if (result.code === 'forbidden') return res.status(403).json({ error: 'only the holder (or force) can release this slot' });
      return res.status(500).json({ error: 'release failed' });
    }
    storeAuditEnvelope({
      type: 'event', from: `session.${holder_session || 'unknown'}`, to: 'audit.system', intent: 'quox.slot.release',
      corr: result.slot.id,
      payload: { org_id: orgId, name: req.params.name, holder_session: holder_session || null, force: !!force },
    });
    // Item 5: the card flips back to free. Release never touches the tmux
    // session or the channel itself; only the status changes.
    if (result.slot.discord_channel_id) {
      devSlotDiscord.updateSlotDiscordStatus({
        channelId: result.slot.discord_channel_id, slotName: req.params.name, state: 'free',
      }).catch((err) => console.warn(`[DevSlots] discord status for ${req.params.name} failed (non-fatal): ${err.message}`));
    }
    res.json({ slot: result.slot });
  } catch (err) {
    console.error('[DevSlots] release failed:', err.message);
    res.status(500).json({ error: 'release failed' });
  }
});

app.post('/api/v1/slots/:name/heartbeat', requireServiceOrUserAuth(), requireLicence('quoxslots', 'QuoxSlots'), (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  const orgId = resolveSlotOrgId(req);
  if (!orgId) return res.status(400).json({ error: 'org could not be resolved' });
  const { holder_session } = req.body || {};
  if (!holder_session) return res.status(400).json({ error: 'holder_session is required' });

  try {
    const result = devSlots.heartbeatSlot({
      orgId, name: req.params.name, holderSession: holder_session, memberKey: callerFromReq(req).memberKey,
    });
    if (!result.ok) {
      if (result.code === 'not_found') return res.status(404).json({ error: 'unknown slot' });
      return res.status(409).json({ error: 'slot not held by this session' });
    }
    // No AEE envelope here by design — heartbeat cadence (15s-60s) would
    // flood WARD with no evidentiary value beyond what checkout/release
    // already carry.
    res.json({ slot: result.slot });
  } catch (err) {
    console.error('[DevSlots] heartbeat failed:', err.message);
    res.status(500).json({ error: 'heartbeat failed' });
  }
});

// DEVSUITE-SLOTS "Option B" assign model (plan v2 note #2831): the owner
// ASSIGNS a slot to an expected holder (session name); the slot stays FREE
// until that session CLAIMS it at startup. Additive to the existing
// checkout/release flow above, not a replacement for it.
app.post('/api/v1/slots/:name/assign', requireServiceOrUserAuth(), requireLicence('quoxslots', 'QuoxSlots'), (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  const orgId = resolveSlotOrgId(req);
  if (!orgId) return res.status(400).json({ error: 'org could not be resolved' });
  // Curating who a slot is EARMARKED for is an admin action, same posture as
  // create/retire above; claiming it (below) stays open to any org member.
  if (!requireAdminRole(req, res, 'Assigning a slot requires an org admin')) return;
  const { assigned_to } = req.body || {};
  const actor = req.user ? `human.${req.user.id || req.user.sub || 'unknown'}` : 'system.tasks';

  try {
    const result = devSlots.assignSlot({ orgId, name: req.params.name, assignedTo: assigned_to || null });
    if (!result.ok) return res.status(404).json({ error: 'unknown slot' });
    storeAuditEnvelope({
      type: 'event', from: actor, to: 'audit.system', intent: 'quox.slot.assign',
      corr: result.slot.id,
      payload: { org_id: orgId, name: req.params.name, assigned_to: assigned_to || null },
    });
    res.json({ slot: result.slot });
  } catch (err) {
    console.error('[DevSlots] assign failed:', err.message);
    res.status(500).json({ error: 'assign failed' });
  }
});

app.post('/api/v1/slots/claim', requireServiceOrUserAuth(), requireLicence('quoxslots', 'QuoxSlots'), (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  const orgId = resolveSlotOrgId(req);
  if (!orgId) return res.status(400).json({ error: 'org could not be resolved' });
  // A session claims its OWN assigned slots, so this is open to any org
  // member (not admin-gated). Session identity is a free-text label in v1
  // (same known limitation as holder_session elsewhere on this surface) —
  // there is no per-session auth binding it to a specific caller yet.
  const { session, holder_kind, host_id } = req.body || {};
  if (!session) return res.status(400).json({ error: 'session is required' });

  try {
    const claimed = devSlots.claimForSession({ orgId, session, holderKind: holder_kind, hostId: host_id });
    for (const slot of claimed) {
      storeAuditEnvelope({
        type: 'event', from: `session.${session}`, to: 'audit.system', intent: 'quox.slot.checkout',
        corr: slot.id,
        payload: { org_id: orgId, name: slot.name, holder_session: session, holder_kind: holder_kind || null, host_id: host_id || null, via: 'claim' },
      });
      if (!slot.matrix_room_id) {
        provisionSlotRoom({ orgId, slotId: slot.id, label: `Slots > ${slot.name}` })
          .then((roomId) => {
            if (roomId) devSlots.setSlotRoomId({ orgId, name: slot.name, roomId });
          })
          .catch((err) => console.warn(`[DevSlots] room provision re-attempt for ${slot.name} failed (non-fatal): ${err.message}`));
      }
    }
    res.json({ claimed: claimed.map((s) => s.name) });
  } catch (err) {
    console.error('[DevSlots] claim failed:', err.message);
    res.status(500).json({ error: 'claim failed' });
  }
});

// DEVSUITE-SLOTS Phase 9 — the org-scoped bridge-room config that `say`
// renders into (Telegram/Discord). Reading is open to any org member (same
// posture as the rest of this surface's non-curation routes); setting a
// room is admin-gated, same posture as create/retire/assign above.
/**
 * A display-safe form of a bridge target.
 *
 * A Matrix room id is an identifier and passes through. A Discord webhook URL
 * is a CREDENTIAL: `https://discord.com/api/webhooks/<id>/<token>`, where the
 * token is the whole authority to post. The id alone identifies the channel,
 * which is all a listing needs.
 *
 * Fails closed on an unrecognised https URL. If a future platform's target is
 * also a secret-bearing URL, the safe default is to redact it and have someone
 * notice the listing is unhelpful, rather than to publish a token because the
 * shape was not on a list somebody remembered to update. This is the same
 * allowlist-not-denylist rule that the VOLT payload bounds landed on.
 */
function redactBridgeTarget(target) {
  const t = String(target || '').trim();
  if (!t) return t;
  const webhook = t.match(/^https:\/\/(?:discord|discordapp)\.com\/api\/webhooks\/(\d+)\//i);
  if (webhook) return `discord webhook ${webhook[1]}`;
  if (/^https?:\/\//i.test(t)) return 'url (redacted)';
  return t;
}

function redactBridgeMap(bridges) {
  const out = {};
  for (const [platform, target] of Object.entries(bridges || {})) {
    out[platform] = target ? redactBridgeTarget(target) : target;
  }
  return out;
}

// A bridge `entry` row carries the same secret-bearing target as the map and
// details do, so it needs the same treatment on any response that includes it.
function redactBridgeEntry(entry) {
  if (!entry) return null;
  const out = { ...entry };
  if (out.room_id) out.room_id = redactBridgeTarget(out.room_id);
  if (out.webhook_url) out.webhook_url = 'url (redacted)';
  return out;
}

function redactBridgeDetails(details) {
  const out = {};
  for (const [platform, row] of Object.entries(details || {})) {
    out[platform] = row ? { ...row, room_id: redactBridgeTarget(row.room_id) } : row;
  }
  return out;
}

app.get('/api/v1/slots/bridges', requireServiceOrUserAuth(), requireLicence('quoxslots', 'QuoxSlots'), (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  const orgId = resolveSlotOrgId(req);
  if (!orgId) return res.status(400).json({ error: 'org could not be resolved' });
  try {
    // `bridges` stays the flat platform->room_id shape the say path and older
    // callers expect; `details` carries the phase-10 verification verdict so
    // the deck and the CLI can show trusted vs unverified rather than just
    // echoing a room id back at the user.
    //
    // A DISCORD BRIDGE TARGET IS A CREDENTIAL. The webhook URL carries a token
    // in its path, and anyone holding it can post to that channel. This
    // endpoint returned it verbatim, so every curl, log line, screenshot and
    // transcript of a bridge listing published it. It leaked into a session
    // transcript on 2026-08-19 exactly that way, by someone who had written
    // the redaction helper for the delivery report a few hours earlier and
    // then called the raw endpoint anyway.
    //
    // The listing's job is to say WHICH channel is bridged and whether it is
    // verified. Neither needs the secret, so the secret does not leave the
    // server. The say path reads the store directly and is unaffected.
    res.json({
      bridges: redactBridgeMap(devSlotBridges.getBridgeRooms({ orgId })),
      details: redactBridgeDetails(devSlotBridges.getBridgeDetails({ orgId })),
    });
  } catch (err) {
    console.error('[DevSlots] bridges list failed:', err.message);
    res.status(500).json({ error: 'list failed' });
  }
});

app.put('/api/v1/slots/bridges/:platform', requireServiceOrUserAuth(), requireLicence('quoxslots', 'QuoxSlots'), async (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  const orgId = resolveSlotOrgId(req);
  if (!orgId) return res.status(400).json({ error: 'org could not be resolved' });
  // requireHumanAdmin, not requireAdminRole: a bridge decides WHERE a slot's
  // messages are broadcast, so an agent or a shared service key must not be
  // able to point a resident's channel at somewhere new. requireAdminRole
  // treats any service-key caller as admin (see utils/httpAuth.js
  // isAdminUser), which is the wrong posture for this specific write and is
  // inconsistent with the supervisor switch, which is already human-only for
  // the same reason. Verified before tightening: the only callers of this
  // route are the CLI and its tests, so nothing automated depended on the
  // looser gate.
  if (!requireHumanAdmin(req, res, 'Setting a slot bridge requires a human org admin')) return;
  const { platform } = req.params;
  const { room_id, force } = req.body || {};
  const actor = req.user ? `human.${req.user.id || req.user.sub || 'unknown'}` : 'system.tasks';

  try {
    // DEVSUITE-SLOTS phase 10 (POLISH P0, trust). This route used to accept
    // ANY string and answer 200, so pointing Slots at a room that was not a
    // bridge portal looked exactly like success and then rendered to nobody
    // (bundle audit note #2840, theme S5: silent success). Now a set is
    // PROVED before it is stored: the appservice joins the same relay puppet
    // `say` uses and reads the room's m.bridge state.
    //
    // Fail closed on a bad verdict AND on an unknown one. `force: true` is the
    // deliberate escape hatch (an operator bridging a room the probe cannot
    // see yet), and it is recorded as unverified rather than quietly blessed,
    // so the deck and the CLI can keep telling the truth about it later.
    const clearing = room_id == null || String(room_id).trim() === '';
    let verification = null;

    // A Discord target may be a WEBHOOK URL rather than a Matrix portal room.
    // Verifying one is better than verifying a portal: Discord's API returns
    // the webhook's own channel and name on a GET, so a pass here proves the
    // exact URL we will post to is live and names the channel it posts into.
    // No gateway connection is involved, which is the entire point (see
    // lib/devSlotMatrixProvision.js for why the bridge path was abandoned).
    if (!clearing && isDiscordWebhook(String(room_id))) {
      const url = String(room_id).trim();
      let hook = null;
      try {
        const r = await fetch(url, { signal: AbortSignal.timeout(10000) });
        if (r.ok) hook = await r.json().catch(() => null);
      } catch { /* unreachable is a verdict, handled below */ }

      if (!hook || !hook.id) {
        if (!force) {
          return res.status(422).json({
            error: 'bridge_not_verified',
            message: 'That Discord webhook URL did not respond. Check it was copied whole, and that it has not been deleted in Discord.',
            detail: { probe: null, hint: 'Fix the URL, or pass force to store it anyway, where it will be shown as unverified.' },
          });
        }
      } else {
        verification = {
          ok: true,
          reason: `Verified: live Discord webhook "${hook.name || 'unnamed'}" posting into channel ${hook.channel_id}.`,
          channel_label: hook.name ? `#${hook.name}` : (hook.channel_id ? `channel ${hook.channel_id}` : null),
        };
      }

      const whResult = devSlotBridges.setBridge({ orgId, platform, roomId: room_id, updatedBy: actor, verification });
      if (!whResult.ok) return res.status(500).json({ error: 'set failed' });
      storeAuditEnvelope({
        type: 'event', from: actor, to: 'audit.system', intent: 'quox.slot.bridge_set',
        corr: `${orgId}:${platform}`,
        // NEVER the URL: it carries a token.
        payload: { org_id: orgId, platform, kind: 'webhook', verified: verification ? verification.ok : null },
      });
      // Redact on the WRITE response too, not just the read. GET has always
      // redacted; these PUT responses returned the raw target, so a Discord
      // webhook URL (a credential: whoever holds it can post as that channel)
      // round-tripped to the browser on every set and clear. Found while
      // building the dashboard surface against this API, 2026-08-23.
      return res.json({
        bridges: redactBridgeMap(devSlotBridges.getBridgeRooms({ orgId })),
        details: redactBridgeDetails(devSlotBridges.getBridgeDetails({ orgId })),
        entry: redactBridgeEntry(whResult.entry),
      });
    }

    if (!clearing) {
      const probe = await probeBridgeRoom({ roomId: String(room_id).trim(), platform });
      const verified = !!(probe && probe.bridged && probe.deliverable);

      if (!verified && !force) {
        // `detail` is the shape the quox CLI client lifts onto QuoxApiError
        // (cli/lib/core/client.js reads data.detail || data.details), so the
        // probe verdict has to live there to reach the terminal.
        return res.status(422).json({
          error: 'bridge_not_verified',
          message: probe
            ? probe.reason
            : 'Could not reach the Matrix appservice to verify this room, so the bridge was not stored.',
          detail: {
            probe: probe || null,
            hint: 'Fix the room, or pass force to store it anyway, where it will be shown as unverified.',
          },
        });
      }
      if (probe) {
        verification = {
          ok: verified,
          reason: probe.reason,
          channel_label: probe.channel?.displayname || null,
        };
      }
    }

    const result = devSlotBridges.setBridge({ orgId, platform, roomId: room_id, updatedBy: actor, verification });
    if (!result.ok) {
      if (result.code === 'bad_platform') return res.status(400).json({ error: "platform must be 'telegram' or 'discord'" });
      return res.status(500).json({ error: 'set failed' });
    }
    storeAuditEnvelope({
      type: 'event', from: actor, to: 'audit.system', intent: 'quox.slot.bridge_set',
      corr: `${orgId}:${platform}`,
      payload: {
        org_id: orgId, platform, cleared: !!result.cleared,
        room_id: result.cleared ? null : (result.entry?.room_id || null),
        verified: verification ? verification.ok : null,
        forced: !!force && !(verification && verification.ok),
      },
    });
    res.json({
      bridges: redactBridgeMap(devSlotBridges.getBridgeRooms({ orgId })),
      details: redactBridgeDetails(devSlotBridges.getBridgeDetails({ orgId })),
      entry: redactBridgeEntry(result.entry),
    });
  } catch (err) {
    console.error('[DevSlots] bridge set failed:', err.message);
    res.status(500).json({ error: 'set failed' });
  }
});

// DEVSUITE-SLOTS Phase 5 — the say/read message seam through a slot's
// Matrix room (design in QuoxPlan DEVSUITE-SLOTS plan v2 sections 1b/1c/2c).
// Same auth posture as the routes above. `say` relays into the live room as
// a slot_ puppet AND writes the local cache row (so a read right after a
// say never races the appservice); `inbound` (service-key bridge callers,
// wired up in a later phase) only writes the cache row — the text already
// landed in the room some other way. `messages` reads the cache.
app.post('/api/v1/slots/:name/say', requireServiceOrUserAuth(), requireLicence('quoxslots', 'QuoxSlots'), async (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  const orgId = resolveSlotOrgId(req);
  if (!orgId) return res.status(400).json({ error: 'org could not be resolved' });
  const { text, from } = req.body || {};
  if (!text || !String(text).trim()) return res.status(400).json({ error: 'text is required' });

  // Label validation (migrations/aee/022): from_label is caller-chosen free
  // text and stays that way, but unbounded/unfiltered text lands on every
  // rendered surface (CLI tables, bridge lines, the dashboard). Reject
  // rather than silently mangle it.
  const labelCheck = validateSlotLabel(from);
  if (!labelCheck.ok) return res.status(400).json({ error: labelCheck.error });
  // SLOT-RUN: an optional command for the human to run in their own terminal. Validated and stored
  // verbatim; the collector NEVER executes it (the quox TUI shows it in full and asks first).
  const runCheck = validateRunCommand(req.body && req.body.run);
  if (!runCheck.ok) return res.status(400).json({ error: runCheck.error });

  try {
    const slot = devSlots.getSlot({ orgId, name: req.params.name });
    if (!slot) return res.status(404).json({ error: 'unknown slot' });
    // QUOXON-MESH: a slot whose room is still provisioning (just created) no longer refuses the say. The
    // line is stored and pushed to listeners now; only its Matrix room copy waits for the room.
    const roomPending = !slot.matrix_room_id;
    // PRESENCE: saying into a human's slot while they are away says so (approvals will queue).
    const humanPresenceFields = () => { const hp = humanPresenceForSlot(orgId, slot.name); return hp ? { human_presence: hp } : {}; };
    const sayPresence = () => require("./lib/devSlotPresence.js").slotPresence({ slot: devSlots.getSlot({ orgId, name: req.params.name }) || slot, listeners: devSlotMessages.listeners({ orgId, slotId: slot.id, excludeSession: (req.body && (req.body.room_session || req.body.holder_session)) || null }) });

    // Durable, synchronous work FIRST (cache + witness), THEN the network
    // sends fire-and-forget. Audit 2026-08-17: the old order relayed to the
    // room first and appended the cache after, so a cache-insert failure
    // returned 500 even though the room already had the message, making the
    // caller retry and DOUBLE-post. Now a cache failure fails before any send,
    // and a relay/bridge outage never fails the say.
    //
    // Unforgeable authorship (migrations/aee/022): identity is resolved from
    // the AUTHENTICATED caller ONLY, never from the request body — a caller
    // cannot claim to be another session's identity no matter what `from`
    // says. `author` stays the DISPLAY LABEL (the caller's chosen name,
    // falling back to the identity when none is supplied), which is why
    // slots stay addressable by session name even though many sessions
    // share one authenticated account.
    const identity = deriveSayIdentity(req, req.body);
    if (identity === null) return res.status(400).json({ error: 'acting_agent must be an agent id' });
    const onBehalfOf = deriveOnBehalfOf(req, req.body);
    if (onBehalfOf === null) return res.status(400).json({ error: 'on_behalf_of must be a user id or a system actor' });

    // P1-TRUST slice 2, the double-voice kill: a resident's identity IS the
    // slot's voice (checkoutSlot for a resident sets holder_session to
    // exactly this identity), so two resident processes cannot both speak
    // as the same slot. Enforced at THIS derivation point, not earlier —
    // ordinary human/session say (steer) is never subject to it, see
    // checkSlotSayAuthor's module comment for why identity alone can only
    // gate a resident, not a human. Fail closed, name the actual holder.
    // QUOXON-ROOMS: a room member (joined, not holding) posts as its membership says
    // (session + person, server-derived), never under a caller-chosen human label.
    const roomSession = (req.body && typeof req.body.room_session === 'string') ? req.body.room_session : '';
    const roomMember = roomSession ? devSlotRoomMembers.getMember({ orgId, slotId: slot.id, session: roomSession }) : null;
    if (roomSession && !roomMember) {
      return res.status(403).json({ error: 'not a room member', message: `${roomSession} has not joined ${req.params.name}; quox slot join ${req.params.name} --session ${roomSession}` });
    }
    const authCheck = roomMember ? { ok: true } : checkSlotSayAuthor({
      slot, identity, caller: callerFromReq(req, { session: (req.body && req.body.holder_session) || null, identity }),
    });
    if (!authCheck.ok) {
      return res.status(403).json({
        error: 'not slot holder',
        message: `${identity} is not the current holder of slot ${req.params.name}; held by ${authCheck.holderSession || 'nobody'}`,
        detail: { holder_session: authCheck.holderSession },
      });
    }

    const author = roomMember ? devSlotRoomMembers.senderFor(roomMember) : deriveSlotAuthor(req, labelCheck.value);

    // SLOTS-REPLY: the sender's own slot (its reply address), kept only when this
    // org's slot is held by the same authenticated identity; otherwise dropped.
    const fromSlot = resolveFromSlot({
      fromSlot: req.body && req.body.from_slot, identity,
      holderSession: roomMember ? null : (req.body && req.body.holder_session),
      getSlot: (n) => devSlots.getSlot({ orgId, name: n }),
      listSlots: () => devSlots.listSlots({ orgId }),
    });
    const fromSlotFields = { from_slot: fromSlot.value, ...(fromSlot.dropped ? { from_slot_dropped: fromSlot.dropped } : {}) };

    const stored = devSlotMessages.appendMessage({
      orgId, slotId: slot.id, slotName: slot.name, from: author, authorIdentity: identity, text, source: 'say', fromSlot: fromSlot.value, run: runCheck.value,
    });

    storeAuditEnvelope({
      type: 'event', from: `session.${author}`, to: 'audit.system', intent: 'quox.slot.say',
      corr: slot.id,
      payload: {
        org_id: orgId, name: req.params.name, from: author, author_identity: identity, from_slot: fromSlot.value, text_length: String(text).length,
        ...(onBehalfOf ? { on_behalf_of: onBehalfOf } : {}),
        ...(runCheck.value ? { run_request: true, run_length: runCheck.value.length } : {}),
      },
    });

    // Relay into the slot room and fan to the owner's bridge (set-relay), both
    // fire-and-forget: the witnessed record is the cache row + envelope above.
    if (roomPending) {
      const q = slotRoomTracker.enqueue(slot.id, { slotId: slot.id, slotName: slot.name, text, from: labelCheck.value });
      if (!q.queued) console.warn(`[DevSlots] say for ${slot.name} not queued for its room (${q.reason}); stored and pushed only`);
      // Kick (or join) provisioning so the queue drains; deduped per slot, fail-soft.
      provisionSlotRoom({ orgId, slotId: slot.id, label: `Slots > ${slot.name}` })
        .then((roomId) => { if (roomId) devSlots.setSlotRoomId({ orgId, name: slot.name, roomId }); })
        .catch((err) => console.warn(`[DevSlots] room provision on say for ${slot.name} failed (non-fatal): ${err.message}`));
    } else {
      relaySlotMessage({ roomId: slot.matrix_room_id, slotId: slot.id, slotName: slot.name, text, from: labelCheck.value })
        .catch((err) => console.warn(`[DevSlots] say relay for ${slot.name} failed (non-fatal): ${err.message}`));
    }
    // Phase 9: resolve bridge rooms from the governed org-scoped store first,
    // env vars only as a fallback when no row exists for that org/platform.
    const bridgeCfg = devSlotBridges.getBridgeRooms({ orgId });
    const bridgeRooms = [
      bridgeCfg.telegram || process.env.QUOX_SLOT_BRIDGE_ROOM,
      // Item 5: a slot with its OWN channel posts there, not into the shared
      // org bridge channel; the design is per-slot exactly so multiple
      // sessions never chime into one channel at once. Org bridge and env
      // stay as fallbacks for slots that predate their channel.
      slot.discord_webhook_url || bridgeCfg.discord || process.env.QUOX_SLOT_DISCORD_ROOM,
    ].filter(Boolean);
    // Report per-bridge delivery, WITHOUT letting a slow bridge hold up the say.
    //
    // 2026-08-18: this was fire-and-forget with `.catch(() => {})`, so the CLI
    // printed "Said into demo." in the same second the collector logged
    // `bridge render returned 502` for Telegram. Not failing on a bridge outage
    // is correct (the witnessed record is the cache row + envelope above);
    // saying nothing about it is not.
    //
    // The wait is bounded so the response time stays the room write, not the
    // slowest external service. Anything unresolved inside the budget reports
    // as `pending` rather than as success, because we genuinely do not know yet.
    const BRIDGE_REPORT_BUDGET_MS = 4000;
    const bridgeRender = renderSlotLineToBridge({
      slotId: slot.id, slotName: slot.name, text, from: labelCheck.value, rooms: bridgeRooms,
    }).catch((err) => ({ eventId: null, results: [], error: err.message }));

    // quox#679: the Telegram relay is reached through a Matrix room, so the
    // renderer reported it as platform 'matrix'. Every slot's say therefore
    // printed "rendered to matrix (<the shared Telegram bridge room>)", which
    // read as two slots writing into the SAME room. Name it for what it is.
    const telegramBridgeRoom = bridgeCfg.telegram || process.env.QUOX_SLOT_BRIDGE_ROOM || null;
    const labelBridge = (b) => (b && telegramBridgeRoom && b.target === telegramBridgeRoom
      ? { ...b, platform: 'telegram' } : b);
    // QUOXON-MESH: a chat window's say (@slot, /say) wants "delivered" the moment the line is
    // in the slot (cache row + notify bus, above), not after the slowest bridge. It opts out of
    // the bridge report; the render still runs, unreported.
    if (req.body && req.body.bridge_report === false) {
      bridgeRender.catch(() => {});
      return res.json({ ok: true, message: stored, ...fromSlotFields, bridges: bridgeRooms.map(() => ({ ok: null, reason: 'not awaited' })), presence: sayPresence(), ...humanPresenceFields(), ...(roomPending ? { room_pending: true } : {}) });
    }
    const bridges = await Promise.race([
      bridgeRender.then((r) => (r.results || []).map(labelBridge)),
      new Promise((resolve) => setTimeout(
        () => resolve(bridgeRooms.map(() => ({ ok: null, reason: 'still sending' }))),
        BRIDGE_REPORT_BUDGET_MS,
      )),
    ]);
    // The render keeps running past the budget; make sure a late rejection
    // cannot surface as an unhandled promise.
    bridgeRender.catch(() => {});

    res.json({ ok: true, message: stored, ...fromSlotFields, bridges, presence: sayPresence(), ...humanPresenceFields(), ...(roomPending ? { room_pending: true } : {}) });
  } catch (err) {
    console.error('[DevSlots] say failed:', err.message);
    res.status(500).json({ error: 'say failed' });
  }
});

app.post('/api/v1/slots/:name/inbound', requireServiceOrUserAuth(), requireLicence('quoxslots', 'QuoxSlots'), (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  const orgId = resolveSlotOrgId(req);
  const { text, from, source } = req.body || {};
  if (!text || !String(text).trim()) return res.status(400).json({ error: 'text is required' });

  try {
    let slot = null;
    if (orgId) {
      slot = devSlots.getSlot({ orgId, name: req.params.name });
    } else if (req.service) {
      // Org-less service caller (the appservice slotSteer hook): a [name]
      // prefix typed on the owner's phone is inherently org-less. Resolve by
      // globally-unique name; refuse ambiguity rather than guess. A JWT user
      // never reaches here (resolveSlotOrgId always yields their token org).
      const matches = devSlots.findSlotsByName({ name: req.params.name });
      if (matches.length === 1) slot = matches[0];
      else if (matches.length > 1) return res.status(409).json({ error: 'slot name ambiguous across orgs; steer requires an org-scoped caller' });
    } else {
      return res.status(400).json({ error: 'org could not be resolved' });
    }
    if (!slot) return res.status(404).json({ error: 'unknown slot' });

    const stored = devSlotMessages.appendMessage({
      orgId: slot.org_id, slotId: slot.id, slotName: slot.name, from: from || null, text, source: source || 'inbound',
    });

    // Governance (audit 2026-08-17): steer is a HITL-adjacent act and was
    // previously unwitnessed. Witness it on the same spine as say.
    storeAuditEnvelope({
      type: 'event', from: from ? `human.${from}` : 'system.bridge', to: 'audit.system', intent: 'quox.slot.steer',
      corr: slot.id,
      payload: { org_id: slot.org_id, name: slot.name, from: from || null, source: source || 'inbound', text_length: String(text).length },
    });

    // Make "the room is the truth" honest for steer too: mirror it into the
    // slot's own Matrix room (not the bridge room, so no phone echo/loop) so
    // the holding session sees it there and it joins the witnessed room DAG,
    // not only the cache table. Fail-soft.
    if (slot.matrix_room_id) {
      relaySlotMessage({ roomId: slot.matrix_room_id, slotId: slot.id, slotName: slot.name, text: `(steer) ${text}`, from: from || null })
        .catch(() => {});
    }

    res.status(201).json({ ok: true, message: stored });
  } catch (err) {
    console.error('[DevSlots] inbound failed:', err.message);
    res.status(500).json({ error: 'inbound failed' });
  }
});

