app.get('/api/v1/slots/:name/messages', requireServiceOrUserAuth(), requireLicence('quoxslots', 'QuoxSlots'), (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  const orgId = resolveSlotOrgId(req);
  if (!orgId) return res.status(400).json({ error: 'org could not be resolved' });

  try {
    const slot = devSlots.getSlot({ orgId, name: req.params.name });
    if (!slot) return res.status(404).json({ error: 'unknown slot' });
    const limit = req.query.limit ? parseInt(req.query.limit, 10) : undefined;
    const messages = devSlotMessages.listMessages({
      orgId, slotId: slot.id, since: req.query.since || null, limit,
    });
    // This route is genuinely reading the channel, so it marks the read
    // watermark — but only when the caller identifies itself as the current
    // holder. touchSlotRead's own CAS (state='held' AND holder_session=?)
    // refuses a bystander or a lapsed holder, so passing an arbitrary
    // holder_session can never mark someone else's hold as caught up.
    if (req.query.holder_session) {
      try {
        devSlots.touchSlotRead({ orgId, name: req.params.name, holderSession: req.query.holder_session, memberKey: callerFromReq(req).memberKey, readThrough: readThroughOf(messages) });
      } catch (err) {
        console.warn(`[DevSlots] touchSlotRead for ${req.params.name} failed (non-fatal): ${err.message}`);
      }
    }
    res.json({ messages });
  } catch (err) {
    console.error('[DevSlots] messages failed:', err.message);
    res.status(500).json({ error: 'messages failed' });
  }
});

// QUOXIDENTITY P10: atomic message claim (CAS), voice-gated through the one
