// Server-side sweep (never a browser timer, per the collector-owned-
// scheduling rule): ages a held slot whose heartbeat lapsed past
// SLOT_HELD_TTL_MS to 'stale', then frees a stale slot past
// SLOT_STALE_TTL_MS. Env vars are a startup DEFAULT only, not the only
// switch — NO ENV-ONLY CONFIG applies: TTLs are slated to surface as an
// editable dashboard setting in DEVSUITE-SLOTS phase 7; until then this is
// a server-side default with no per-request override.
const SLOT_HELD_TTL_MS = Number(process.env.QUOX_SLOT_HELD_TTL_MS) || 15 * 60 * 1000;
const SLOT_STALE_TTL_MS = Number(process.env.QUOX_SLOT_STALE_TTL_MS) || 30 * 60 * 1000;
// Boot grace: after a collector outage holders could not heartbeat, so the
// sweep must not judge heartbeats older than process start (floorMs).
const COLLECTOR_BOOT_AT_MS = Date.now();
let slotGraceLogged = false;
let slotGraceEndLogged = false;
const slotSweepTimer = setInterval(() => {
  if (!aeeDb) return;
  try {
    const upMs = Date.now() - COLLECTOR_BOOT_AT_MS;
    if (upMs < SLOT_STALE_TTL_MS && !slotGraceLogged) {
      slotGraceLogged = true;
      console.log(`[DevSlots] boot grace active: no held->stale for ${Math.round(SLOT_HELD_TTL_MS / 60000)}m, no stale->free for ${Math.round(SLOT_STALE_TTL_MS / 60000)}m after collector start`);
    } else if (upMs >= SLOT_STALE_TTL_MS && slotGraceLogged && !slotGraceEndLogged) {
      slotGraceEndLogged = true;
      console.log('[DevSlots] boot grace ended: sweep transitions fully active');
    }
    const result = devSlots.sweepStale({ heldTtlMs: SLOT_HELD_TTL_MS, staleTtlMs: SLOT_STALE_TTL_MS, floorMs: COLLECTOR_BOOT_AT_MS });
    if (result.heldToStale + result.staleToFree > 0) {
      console.log(`[DevSlots] sweep: ${result.heldToStale} held->stale, ${result.staleToFree} stale->free`);
      // Item 5: the pinned card is rewritten on stale/free transitions too,
      // fail-soft, so a channel never claims a holder the sweep removed.
      const devSlotDiscord = require('./lib/devSlotDiscordProvision.js');
      for (const s of result.wentStale || []) {
        if (!s.discord_channel_id) continue;
        devSlotDiscord.updateSlotDiscordStatus({
          channelId: s.discord_channel_id, slotName: s.name, state: 'stale',
          holderSession: s.holder_session, hostId: s.host_id,
        }).catch(() => {});
      }
      for (const s of result.wentFree || []) {
        if (!s.discord_channel_id) continue;
        devSlotDiscord.updateSlotDiscordStatus({
          channelId: s.discord_channel_id, slotName: s.name, state: 'free',
        }).catch(() => {});
      }
    }
  } catch (err) {
    console.error('[DevSlots] sweep failed:', err.message);
  }
}, 60 * 1000);
if (slotSweepTimer.unref) slotSweepTimer.unref();

// ONE-BRAIN CX6 — topic subscriptions: "tell my slot when new notes about X
// land". Server-side tick (never a browser timer); first tick at +interval,
// no work at boot. Triad (failure accounting, capped backoff, durable
// retirement) lives in lib/brainSubscriptionScheduler.js. Interval:
// QUOX_BRAIN_SUBSCRIPTION_INTERVAL_MS (default 30 min, floor 60 s).
{
  const brainSubs = require('./lib/brainSubscriptionScheduler.js');
  const brainSubScheduler = brainSubs.createBrainSubscriptionScheduler({
    brainUrl: `http://${process.env.QUOXBRAIN_HOST || 'quoxbrain'}:${process.env.QUOXBRAIN_PORT || '3106'}`,
    collectorUrl: `http://127.0.0.1:${process.env.COLLECTOR_PORT || 9848}`,
    serviceKey: process.env.INTERNAL_SERVICE_KEY || '',
    intervalMs: brainSubs.resolveIntervalMs(process.env.QUOX_BRAIN_SUBSCRIPTION_INTERVAL_MS),
  });
  brainSubScheduler.start();
}

// ONE-BRAIN CX6 gardener: daily, per opted-in org and user, the brain proposes
// archiving duplicate / stale private notes; each proposal is an always-propose
// brain_garden_apply approval, applied only when a human approves. Opt-in is the
// org setting BRAIN_GARDENER_ENABLED (stored override of 'true'); the scheduler
// is inert for every other org. First tick at +interval, never at boot.
// Kill switch: QUOX_BRAIN_GARDENER_DISABLED=true. Triad in lib/brainGardenerScheduler.js.
if (voltDb && process.env.QUOX_BRAIN_GARDENER_DISABLED !== 'true') {
  const gardener = require('./lib/brainGardenerScheduler.js');
  const brainGardener = gardener.createBrainGardenerScheduler({
    db: voltDb,
    brainUrl: `http://${process.env.QUOXBRAIN_HOST || 'quoxbrain'}:${process.env.QUOXBRAIN_PORT || '3106'}`,
    serviceKey: process.env.INTERNAL_SERVICE_KEY || '',
    listOptedInOrgs: () => voltDb
      .prepare("SELECT org_id FROM org_platform_settings WHERE key = 'BRAIN_GARDENER_ENABLED' AND value = 'true'")
      .all().map((r) => r.org_id),
    executeTool,
    intervalMs: gardener.resolveIntervalMs(process.env.QUOX_BRAIN_GARDENER_INTERVAL_MS),
  });
  brainGardener.start();
}

