// POST /api/v1/wazuh/proxy — Generic proxy to Wazuh REST API
app.post('/api/v1/wazuh/proxy', requireServiceOrUserAuth(), async (req, res) => {
  const { endpoint, method = 'GET', body: reqBody } = req.body;

  if (!endpoint) {
    return res.status(400).json({ success: false, error: 'endpoint is required' });
  }

  // STREAM WAZ v2 GAP 2 (see lib/wazuhProxyGuard.js): endpoint + method come
  // straight from the caller — constrain to the read-only allowlist before
  // any stored Wazuh credentials are attached to an outbound request.
  // Destructive operations (deploy/remove/active-response) have their own
  // dedicated, HITL-gated routes and never reach this generic proxy.
  if (!isAllowedWazuhRequest(method, endpoint)) {
    return res.status(403).json({ success: false, error: 'method_not_allowed', detail: `${String(method).toUpperCase()} ${endpoint} is not on the Wazuh proxy allowlist` });
  }

  try {
    const orgId = (req.user && req.user.org_id) || 'system';
    const { token, host, port } = await getWazuhToken(orgId);
    const payload = reqBody ? JSON.stringify(reqBody) : null;

    const result = await new Promise((resolve, reject) => {
      const options = {
        hostname: host,
        port,
        path: endpoint.startsWith('/') ? endpoint : `/${endpoint}`,
        method: method.toUpperCase(),
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        rejectUnauthorized: false,
        timeout: 30000,
      };
      if (payload) options.headers['Content-Length'] = Buffer.byteLength(payload);

      const request = https.request(options, (resp) => {
        let data = '';
        resp.on('data', chunk => { data += chunk; });
        resp.on('end', () => {
          try {
            const parsed = JSON.parse(data);
            resolve({ success: resp.statusCode >= 200 && resp.statusCode < 300, data: parsed, status: resp.statusCode });
          } catch {
            resolve({ success: false, data, status: resp.statusCode });
          }
        });
      });

      request.on('error', (err) => {
        resolve({ success: false, error: err.message, status: 500 });
      });
      request.on('timeout', () => {
        request.destroy();
        resolve({ success: false, error: 'Wazuh API timeout', status: 500 });
      });

      if (payload) request.write(payload);
      request.end();
    });

    emitWazuhAEE(req, { intent: 'quox.wazuh.proxy.call', payload: { endpoint, method } });
    res.json(result);
  } catch (err) {
    console.error('[Wazuh Proxy] Error:', err.message);
    emitWazuhAEE(req, { type: 'error', intent: 'quox.wazuh.proxy.failed', payload: { error: err.message } });
    res.status(500).json({ success: false, error: err.message, status: 500 });
  }
});

