// POST /api/v1/wazuh/deploy-agent — HITL-gated: queue deploy via HITL Inbox approval
app.post('/api/v1/wazuh/deploy-agent', requireServiceOrUserAuth(), async (req, res) => {
  const {
    hostname,
    hostIp,
    wazuhServer = process.env.WAZUH_HOST || '',
    bastionHost = resolveBastionHost(),
    sshUser = 'control',
    sshPort = 22,
  } = req.body;

  if (!hostname || !hostIp) {
    return res.status(400).json({ success: false, error: 'hostname and hostIp are required' });
  }
  if (!wazuhServer) {
    return res.status(400).json({ success: false, error: 'Wazuh server IP is not configured. Open Settings → Plugins → Wazuh → Configure and fill in the Wazuh Server IP.' });
  }

  // Validate shell-interpolated inputs (defence-in-depth: also validated at execution time).
  // bastionHost is optional — empty means direct (one-hop) SSH from collector to host.
  const portStr = String(sshPort);
  try {
    validateWazuhInput(hostname, 'hostname', 'hostname');
    validateWazuhInput(hostIp, 'ip', 'hostIp');
    validateWazuhInput(wazuhServer, 'ip', 'wazuhServer');
    if (bastionHost) validateWazuhInput(bastionHost, 'ip', 'bastionHost');
    validateWazuhInput(sshUser, 'sshUser', 'sshUser');
    validateWazuhInput(portStr, 'port', 'sshPort');
  } catch (valErr) {
    return res.status(400).json({ success: false, error: valErr.message });
  }

  const orgId = (req.user && req.user.org_id) ? req.user.org_id : 'system';
  const requestedBy = req.service ? 'service' : (req.user && req.user.id ? req.user.id : 'unknown');
  const corrId = `WAZ_DEPLOY_${Date.now()}`;

  // Emit AEE: intent = task (destructive, awaiting approval)
  emitWazuhAEE(req, {
    type: 'task',
    intent: 'quox.wazuh.agents.deploy.requested',
    corr: corrId,
    payload: { hostname, hostIp, wazuhServer, bastionHost, sshUser, sshPort: portStr, requested_by: requestedBy },
  });

  // Push HITL Inbox approval card
  const bodyMd = [
    `**Wazuh Agent Deploy Request**`,
    ``,
    `| Field | Value |`,
    `|-------|-------|`,
    `| Host | \`${hostname}\` |`,
    `| IP | \`${hostIp}\` |`,
    `| SSH User | \`${sshUser}\` |`,
    `| SSH Port | \`${portStr}\` |`,
    `| Wazuh Manager | \`${wazuhServer}\` |`,
    `| Bastion | \`${bastionHost}\` |`,
    `| Requested by | \`${requestedBy}\` |`,
    ``,
    `Approving will install and start the Wazuh agent on this host via SSH.`,
  ].join('\n');

  const approval = await pushWazuhApproval({
    orgId,
    action: 'wazuh.agents.deploy',
    title: `Wazuh: Deploy agent to ${hostname}`,
    bodyMd,
    priority: 'high',
    actionParams: { action: 'wazuh.agents.deploy', hostname, hostIp, wazuhServer, bastionHost, sshUser, sshPort: portStr, org_id: orgId, corr: corrId },
    callbackUrl: '/api/internal/wazuh/approvals/decide',
  });

  if (!approval.ok) {
    emitWazuhAEE(req, { type: 'error', intent: 'quox.wazuh.agents.deploy.failed', corr: corrId, payload: { error: approval.error, phase: 'inbox_push' } });
    return res.status(503).json({ success: false, error: `Failed to queue approval: ${approval.error}`, hostname, hostIp });
  }

  console.log(`[Wazuh HITL] Deploy to ${hostname} queued — inbox item ${approval.itemId}`);
  res.status(202).json({ success: true, status: 'awaiting_approval', inbox_item_id: approval.itemId, message: 'Deploy queued — awaiting approval', hostname, hostIp });
});

// POST /api/v1/wazuh/deploy-bulk — HITL-gated: queue bulk deploy via HITL Inbox approval
app.post('/api/v1/wazuh/deploy-bulk', requireServiceOrUserAuth(), async (req, res) => {
  const { hosts } = req.body;

  if (!hosts || !Array.isArray(hosts) || hosts.length === 0) {
    return res.status(400).json({ success: false, error: 'hosts array is required (each with hostname and ip)' });
  }

  const wazuhServer = req.body.wazuhServer || process.env.WAZUH_HOST || '';
  const bastionHost = req.body.bastionHost || resolveBastionHost();

  if (!wazuhServer) {
    return res.status(400).json({ success: false, error: 'Wazuh server IP is not configured. Open Settings → Plugins → Wazuh → Configure and fill in the Wazuh Server IP.' });
  }

  // Validate shared inputs (defence-in-depth: also validated at execution time).
  // bastionHost is optional — empty means direct (one-hop) SSH.
  try {
    validateWazuhInput(wazuhServer, 'ip', 'wazuhServer');
    if (bastionHost) validateWazuhInput(bastionHost, 'ip', 'bastionHost');
  } catch (valErr) {
    return res.status(400).json({ success: false, error: valErr.message });
  }

  const orgId = (req.user && req.user.org_id) ? req.user.org_id : 'system';
  const requestedBy = req.service ? 'service' : (req.user && req.user.id ? req.user.id : 'unknown');
  const corrId = `WAZ_BULK_${Date.now()}`;
  const hostNames = hosts.map(h => h.hostname || h.ip).slice(0, 5).join(', ') + (hosts.length > 5 ? ` +${hosts.length - 5} more` : '');

  // Emit AEE: type=task, bulk deploy requested
  emitWazuhAEE(req, {
    type: 'task',
    intent: 'quox.wazuh.agents.deploy.bulk.requested',
    corr: corrId,
    payload: { host_count: hosts.length, host_names: hostNames, wazuhServer, bastionHost, requested_by: requestedBy },
  });

  const bodyMd = [
    `**Wazuh Bulk Agent Deploy Request**`,
    ``,
    `| Field | Value |`,
    `|-------|-------|`,
    `| Host count | ${hosts.length} |`,
    `| Hosts | \`${hostNames}\` |`,
    `| Wazuh Manager | \`${wazuhServer}\` |`,
    `| Bastion | \`${bastionHost}\` |`,
    `| Requested by | \`${requestedBy}\` |`,
    ``,
    `Approving will install and start the Wazuh agent on all ${hosts.length} hosts sequentially via SSH.`,
  ].join('\n');

  const approval = await pushWazuhApproval({
    orgId,
    action: 'wazuh.agents.deploy.bulk',
    title: `Wazuh: Deploy agent to ${hosts.length} hosts`,
    bodyMd,
    priority: 'high',
    actionParams: { action: 'wazuh.agents.deploy.bulk', hosts, wazuhServer, bastionHost, org_id: orgId, corr: corrId },
    callbackUrl: '/api/internal/wazuh/approvals/decide',
  });

  if (!approval.ok) {
    emitWazuhAEE(req, { type: 'error', intent: 'quox.wazuh.agents.deploy.bulk.failed', corr: corrId, payload: { error: approval.error, phase: 'inbox_push' } });
    return res.status(503).json({ success: false, error: `Failed to queue approval: ${approval.error}` });
  }

  console.log(`[Wazuh HITL] Bulk deploy to ${hosts.length} hosts queued — inbox item ${approval.itemId}`);
  res.status(202).json({ success: true, status: 'awaiting_approval', inbox_item_id: approval.itemId, message: 'Bulk deploy queued — awaiting approval', host_count: hosts.length });
});

