// POST /api/v1/wazuh/agent-status — Check if Wazuh agent is installed and running on a host
app.post('/api/v1/wazuh/agent-status', requireServiceOrUserAuth(), async (req, res) => {
  const { exec } = require('child_process');
  const {
    hostIp,
    bastionHost = process.env.BASTION_HOST || '',
    sshUser = 'control',
  } = req.body;

  if (!hostIp) {
    return res.status(400).json({ success: false, error: 'hostIp is required' });
  }

  // Validate shell-interpolated inputs
  try {
    validateWazuhInput(hostIp, 'ip', 'hostIp');
    validateWazuhInput(bastionHost, 'ip', 'bastionHost');
    validateWazuhInput(sshUser, 'sshUser', 'sshUser');
  } catch (valErr) {
    return res.status(400).json({ success: false, error: valErr.message });
  }

  const checkScript = [
    'INSTALLED=false; RUNNING=false; VERSION=unknown',
    'if dpkg -l wazuh-agent 2>/dev/null | grep -q ^ii; then INSTALLED=true; VERSION=$(dpkg -l wazuh-agent 2>/dev/null | grep ^ii | awk "{print \\$3}"); fi',
    'if systemctl is-active --quiet wazuh-agent 2>/dev/null; then RUNNING=true; fi',
    'echo "INSTALLED=$INSTALLED RUNNING=$RUNNING VERSION=$VERSION"',
  ].join('; ');

  const cmd = `ssh -o StrictHostKeyChecking=no -o ConnectTimeout=10 ubuntu@${bastionHost} "ssh -o StrictHostKeyChecking=no -o ConnectTimeout=10 ${sshUser}@${hostIp} '${checkScript}'"`;

  exec(cmd, { timeout: 30000 }, (err, stdout, stderr) => {
    if (err) {
      console.error(`[Wazuh Agent Status] Error for ${hostIp}:`, err.message);
      emitWazuhAEE(req, { type: 'error', intent: 'quox.wazuh.agent.status.failed', payload: { hostIp, error: err.message } });
      return res.status(500).json({ success: false, error: err.message });
    }

    const installed = stdout.includes('INSTALLED=true');
    const running = stdout.includes('RUNNING=true');
    const versionMatch = stdout.match(/VERSION=(\S+)/);
    const version = versionMatch ? versionMatch[1] : 'unknown';

    emitWazuhAEE(req, { intent: 'quox.wazuh.agent.status', payload: { hostIp, installed, running, version } });
    res.json({ success: true, installed, running, version, hostIp });
  });
});

// POST /api/v1/wazuh/active-response — HITL-gated: trigger Wazuh active response
// Allowlisted commands only. Always requires approval before execution.
const ACTIVE_RESPONSE_ALLOWLIST = ['firewall-block', 'host-isolate', 'restart-wazuh-agent'];

app.post('/api/v1/wazuh/active-response', requireServiceOrUserAuth(), async (req, res) => {
  const { command, agentList, args = [], reason } = req.body;

  // Validate inputs
  if (!command || !ACTIVE_RESPONSE_ALLOWLIST.includes(command)) {
    return res.status(400).json({ success: false, error: `command must be one of: ${ACTIVE_RESPONSE_ALLOWLIST.join(', ')}` });
  }
  if (!agentList || !Array.isArray(agentList) || agentList.length === 0) {
    return res.status(400).json({ success: false, error: 'agentList must be a non-empty array of agent IDs' });
  }
  if (!reason || typeof reason !== 'string' || reason.trim().length < 10) {
    return res.status(400).json({ success: false, error: 'reason must be at least 10 characters' });
  }

  const orgId = (req.user && req.user.org_id) ? req.user.org_id : 'system';
  const requestedBy = req.service ? 'service' : (req.user && req.user.id ? req.user.id : 'unknown');
  const corrId = `WAZ_AR_${Date.now()}`;

  // Sanitise agentList: alphanumeric only
  const sanitisedAgentList = agentList.map(id => String(id).replace(/[^a-zA-Z0-9]/g, '')).filter(Boolean);
  if (sanitisedAgentList.length === 0) {
    return res.status(400).json({ success: false, error: 'No valid agent IDs after sanitisation' });
  }

  // quox#1004: an install with no Wazuh connection must refuse here, the way deploy-agent does, rather than
  // file a high-priority approval card for an action that can only fail after approval.
  const wazuhReady = await checkWazuhConfigured(orgId, { resolveCredentialForAgent, resolveWazuhConnection });
  if (!wazuhReady.ok) {
    return res.status(400).json({ success: false, error: wazuhReady.error, code: 'WAZUH_NOT_CONFIGURED' });
  }

  emitWazuhAEE(req, {
    type: 'task',
    intent: 'quox.wazuh.active-response.trigger',
    corr: corrId,
    payload: { command, agent_count: sanitisedAgentList.length, reason: reason.trim(), requested_by: requestedBy },
  });

  const bodyMd = [
    `**Wazuh Active Response Request**`,
    ``,
    `| Field | Value |`,
    `|-------|-------|`,
    `| Command | \`${command}\` |`,
    `| Agents | \`${sanitisedAgentList.join(', ')}\` |`,
    `| Arguments | \`${args.join(', ') || '(none)'}\` |`,
    `| Requested by | \`${requestedBy}\` |`,
    ``,
    `**Justification:** ${reason.trim()}`,
    ``,
    `> This action will execute the command on the listed agents immediately upon approval.`,
  ].join('\n');

  const approval = await pushWazuhApproval({
    orgId,
    action: 'wazuh.active-response',
    title: `Wazuh: Active response — ${command} on ${sanitisedAgentList.length} agent(s)`,
    bodyMd,
    priority: 'high',
    actionParams: { action: 'wazuh.active-response', command, agentList: sanitisedAgentList, args, reason: reason.trim(), org_id: orgId, corr: corrId },
    callbackUrl: '/api/internal/wazuh/approvals/decide',
  });

  if (!approval.ok) {
    emitWazuhAEE(req, { type: 'error', intent: 'quox.wazuh.active-response.trigger.failed', corr: corrId, payload: { error: approval.error, phase: 'inbox_push' } });
    return res.status(503).json({ success: false, error: `Failed to queue approval: ${approval.error}` });
  }

  console.log(`[Wazuh HITL] Active response ${command} queued — inbox item ${approval.itemId}`);
  res.status(202).json({ success: true, status: 'awaiting_approval', inbox_item_id: approval.itemId, message: 'Active response queued — awaiting approval' });
});

// DELETE /api/v1/wazuh/agents/:agentId — HITL-gated: remove a Wazuh agent
