// Server-side cache for Docker fleet data (persists across page reloads)
const DOCKER_CACHE_PATH = require('path').join(
  process.env.AEE_DB_PATH ? require('path').dirname(process.env.AEE_DB_PATH) : '/var/lib/quox',
  'docker-fleet-cache.json'
);

function loadDockerCache() {
  try {
    if (require('fs').existsSync(DOCKER_CACHE_PATH)) {
      return JSON.parse(require('fs').readFileSync(DOCKER_CACHE_PATH, 'utf8'));
    }
  } catch { /* ignore */ }
  return {};
}

function saveDockerCache(cache) {
  try {
    require('fs').writeFileSync(DOCKER_CACHE_PATH, JSON.stringify(cache, null, 2));
  } catch (err) {
    console.error('[Docker Fleet] Failed to save cache:', err.message);
  }
}

// ============================================================================
// QUOX-SECURITY Phase 0: engagement/scope REST API
// ============================================================================
// The engagement/scope object and policy pre-check every future security
// capability call must pass. No agent capability exists yet (Phase 1's
// job) — these routes are pure CRUD + the domain-verification challenge.
// Auth pattern mirrors the wazuh routes above (requireServiceOrUserAuth,
// req.user.org_id, a per-domain emitXAEE helper) rather than the
// governed-proxy shape quoxplan's routes use, since this is a
// collector-native resource (own DB), not a proxy to an external server.

// FND_..SM0Q (cross-tenant fix): caller-supplied org_id (body/query) is honored ONLY for a
// trusted service-key caller (req.service). A JWT/cookie user is always scoped to their own
// authenticated org, and a null org_id stays null rather than falling through to
// attacker-controlled input. Extracted to lib/callerOrgScope.js so the security property is
// unit-tested at the real function (w-sm0q-caller-org-scope.test.js), mirroring the safe
// pattern at server.js ~9529 and lib/complianceOrgScope.js. (NOTE: a DIFFERENT, block-scoped
// `resolveCallerOrgId` alias for feedApiHandlers.resolveOrgId exists ~7385 inside its own
// route block and shadows this module binding only there — unrelated.)
const { resolveCallerOrgId } = require('./lib/callerOrgScope.js');

function emitSecurityAEE(req, opts) {
  const { type = 'event', intent, corr, payload = {}, from } = opts;
  if (!intent) return;
  const userId = req.service ? 'service' : (req.user && req.user.id ? `human.${req.user.id}` : 'system');
  const orgId = req.user && req.user.org_id ? req.user.org_id : 'system';
  storeAuditEnvelope({
    type,
    from: from || userId,
    to: 'agent.security-lead',
    intent,
    corr: corr || `SEC_${Date.now()}`,
    payload: { org_id: orgId, ...payload },
  });
}

function securityDb_() {
  if (!securityDb) throw new Error('Security database not initialized');
  return securityDb;
}

// QUOX-SECURITY-SCHED Phase 4: the schedule routes below are used across
// several handlers, so (unlike most of this block's inline per-route
// requires) it's pulled in once here.
const securityEngagementSchedules = require('./lib/securityEngagementSchedules.js');

// UI/agent-discovery catalog: what capability tools exist, their risk tier
