    const { securityEngagement } = requireSecurityEngagement();
    const eng = securityEngagement.getEngagement(req.params.id, orgId, { db: securityDb_() });
    if (!eng) return res.status(404).json({ success: false, error: `Engagement "${req.params.id}" not found` });
    const targets = securityDb_().prepare('SELECT * FROM security_targets WHERE engagement_id = ? AND org_id = ?').all(req.params.id, orgId);
    res.json({ success: true, engagement: eng, targets });
