// Prometheus metrics endpoint
app.get('/metrics', (req, res) => {
  const now = Date.now();
  let lines = [];

  // Collector metrics
  lines.push('# HELP quox_collector_agents_total Total number of registered agents');
  lines.push('# TYPE quox_collector_agents_total gauge');
  lines.push(`quox_collector_agents_total ${agents.size}`);

  let connected = 0, stale = 0, dead = 0;
  for (const [, agent] of agents) {
    const age = now - agent.received_at;
    if (age > AGENT_DEAD_MS) dead++;
    else if (age > AGENT_TIMEOUT_MS) stale++;
    else connected++;
  }

  lines.push('# HELP quox_collector_agents_connected Agents with recent heartbeat');
  lines.push('# TYPE quox_collector_agents_connected gauge');
  lines.push(`quox_collector_agents_connected ${connected}`);

  lines.push('# HELP quox_collector_agents_stale Agents with stale heartbeat');
  lines.push('# TYPE quox_collector_agents_stale gauge');
  lines.push(`quox_collector_agents_stale ${stale}`);

  lines.push('# HELP quox_collector_agents_dead Agents considered dead');
  lines.push('# TYPE quox_collector_agents_dead gauge');
  lines.push(`quox_collector_agents_dead ${dead}`);

  // QUOXTRUST T3 (D3 durability): dropped audit-envelope writes. A rising
  // counter here means evidence is being lost — alert on it.
  const auditWrites = getAuditWriteFailures();
  lines.push('# HELP quox_collector_audit_write_failures_total Audit envelopes that failed to persist (dropped receipts)');
  lines.push('# TYPE quox_collector_audit_write_failures_total counter');
  lines.push(`quox_collector_audit_write_failures_total ${auditWrites.count}`);
  lines.push(`quox_collector_audit_write_failures_total{reason="storage_unavailable"} ${auditWrites.by_reason.storage_unavailable}`);
  lines.push(`quox_collector_audit_write_failures_total{reason="insert_failed"} ${auditWrites.by_reason.insert_failed}`);
  // QUOXTRUST T3 — durable execution ledger: crash-orphaned ambiguous effects and
  // current in-flight count (read from the durable table, survives restart).
  const execLedgerMetrics = executionLedger.getExecutionLedgerStatus(aeeDb);
  lines.push('# HELP quox_collector_execution_outcome_unknown Consequential external effects left ambiguous by a crash (never auto-retried)');
  lines.push('# TYPE quox_collector_execution_outcome_unknown gauge');
  lines.push(`quox_collector_execution_outcome_unknown ${execLedgerMetrics.outcome_unknown}`);
  lines.push('# HELP quox_collector_execution_in_flight External effects currently mid-dispatch (durable intent claimed, not yet resolved)');
  lines.push('# TYPE quox_collector_execution_in_flight gauge');
  lines.push(`quox_collector_execution_in_flight ${execLedgerMetrics.in_flight}`);

  // Per-agent metrics
  lines.push('# HELP quox_agent_cpu_percent Agent CPU usage percentage');
  lines.push('# TYPE quox_agent_cpu_percent gauge');
  lines.push('# HELP quox_agent_memory_percent Agent memory usage percentage');
  lines.push('# TYPE quox_agent_memory_percent gauge');
  lines.push('# HELP quox_agent_last_seen_seconds Seconds since last heartbeat');
  lines.push('# TYPE quox_agent_last_seen_seconds gauge');

  for (const [hostId, agent] of agents) {
    const age = Math.floor((now - agent.received_at) / 1000);
    const cpu = agent.resources?.cpu?.usage_percent || 0;
    const mem = agent.resources?.memory?.usage_percent || 0;

    lines.push(`quox_agent_cpu_percent{host_id="${hostId}"} ${cpu.toFixed(2)}`);
    lines.push(`quox_agent_memory_percent{host_id="${hostId}"} ${mem.toFixed(2)}`);
    lines.push(`quox_agent_last_seen_seconds{host_id="${hostId}"} ${age}`);
  }

  res.set('Content-Type', 'text/plain');
  res.send(lines.join('\n') + '\n');
});

// Broadcast to all WebSocket clients
// STABILITY-AUDITS #1: this runs per fleet heartbeat (every agent, every
// beat). A single client erroring on send() (closed socket race, backpressure,
// broken pipe) used to throw synchronously out of this loop and abort every
// remaining client's delivery for that heartbeat — with no process-level
// handler either, that could take the whole collector down. Isolate each
// client's send so one bad client can't affect the others.
function broadcastToClients(message) {
  const data = JSON.stringify(message);
  for (const client of wsClients) {
    if (client.readyState === 1) { // OPEN
      try {
        client.send(data);
      } catch (err) {
        console.warn('[WS] broadcastToClients: send failed, dropping dead client:', err.message);
        try { client.terminate(); } catch { /* already dead */ }
        wsClients.delete(client);
      }
    }
  }
}

// Cleanup stale agents periodically
const staleAgentCleanupTimer = setInterval(() => {
  const now = Date.now();
  for (const [hostId, agent] of agents) {
    const age = now - agent.received_at;
    if (age > AGENT_DEAD_MS) {
      console.log(`[${new Date().toISOString()}] Removing dead agent: ${hostId}`);
      agents.delete(hostId);
      broadcastToClients({
        type: 'agent_removed',
        host_id: hostId
      });
    }
  }
}, 60000); // Check every minute
if (staleAgentCleanupTimer.unref) staleAgentCleanupTimer.unref();

// ============================================================================
// RepoBrain proxy: /api/v1/nucleus/* -> repobrain:3105/api/*
// ============================================================================
const REPOBRAIN_URL = process.env.REPOBRAIN_URL || 'http://repobrain:3105'; // QN Phase 1: bundled fallback only, zero-config orgs
// QN Phase 0 (govern the seam): resolve the caller's org for the RepoBrain
// proxy, same trust boundary the Feed uses (JWT org_id wins; a service caller
// may pass org via query/body). Aliased to avoid any redeclaration on this
// large, multi-session file.
const { resolveOrgId: resolveNucleusOrgId } = require('./lib/feedApiHandlers');
// QN Phase 1: per-org backend resolver (lib/repobrainRegistry.js) replaces
// the single hardcoded REPOBRAIN_URL below with a licenseGate-shaped cache
// over the auth service's repobrain-resolve endpoint.
const { resolveRepoBrainBackend } = require('./lib/repobrainRegistry');

// GOVERNED. RepoBrain is a licensed plugin. Before QN Phase 0 this
// proxy was an unauthenticated passthrough (requireAuth required:false, no org,
// no licence, no audit). Now it requires auth, resolves the org, gates on the
// quox-nucleus entitlement (fail closed), passes org context downstream for
// future engine tenancy, and audits. The CodeSearch.jsx health honesty gate stays.
app.all('/api/v1/nucleus/*', requireServiceOrUserAuth(), async (req, res) => {
  const orgId = resolveNucleusOrgId(req);
  if (!orgId) {
    return res.status(401).json({ error: 'Organisation context required for RepoBrain' });
  }
  let nucleusLicensed = false;
  try {
    nucleusLicensed = await isPluginLicensedForOrg(orgId, 'quox-nucleus');
  } catch (e) {
    nucleusLicensed = false; // fail closed
  }
  if (!nucleusLicensed) {
    return res.status(403).json({ error: 'RepoBrain is not licensed for this organisation' });
  }

  const targetPath = req.originalUrl.replace('/collector/api/v1/nucleus', '/api').replace('/api/v1/nucleus', '/api');

  // QN Phase 1: resolve the org's RepoBrain backend (its own connection, or
  // the bundled default for zero-config orgs). Fail closed: a resolver
  // error with no usable cache never falls back to the shared bundle for
  // an org that may hold its own connection.
  const requestedConn = req.headers['x-repobrain-connection'] || null;
  let backend;
  try {
    backend = await resolveRepoBrainBackend(orgId, requestedConn);
  } catch (e) {
    return res.status(502).json({ error: 'RepoBrain backend resolution failed' });
  }

  const targetUrl = `${backend.baseUrl}${targetPath}`;
  // Audit: who queried RepoBrain, which backend, and what path (query string
  // stripped). Emits a real audit event (not just a log line); a full VOLT run
  // bundle for query provenance is a follow-up.
  const auditPath = targetPath.split('?')[0];
  console.log(`[Nucleus] org=${orgId} backend=${backend.source}:${backend.connectionId || 'bundled'} ${req.method} ${auditPath}`);
  try {
    auditOp('ops.nucleus.query', {
      org_id: orgId,
      backend: backend.source,
      connection_id: backend.connectionId || null,
      method: req.method,
      path: auditPath,
    });
  } catch (_e) { /* audit is best-effort, never blocks the query */ }

  try {
    const fetchOpts = {
      method: req.method,
      headers: {
        'Accept': 'application/json',
        'Content-Type': req.headers['content-type'] || 'application/json',
        'X-Org-Id': orgId,
        ...(backend.sharedSecret ? { 'X-RepoBrain-Key': backend.sharedSecret } : {}),
      },
      signal: AbortSignal.timeout(30000),
    };

    if (['POST', 'PUT', 'PATCH'].includes(req.method) && req.body) {
      // RepoBrain private repos (2026-10-05): the org whose GitHub credential a
      // target may borrow is stamped HERE from the authenticated caller, always
      // overwriting the body, so a caller can never point a target at another
      // org's credential.
      let outBody = req.body;
      if (outBody && typeof outBody === 'object' && outBody.source_config && typeof outBody.source_config === 'object') {
        const sc = { ...outBody.source_config };
        if (sc.auth === 'org_github') sc.org_id = orgId; else delete sc.org_id;
        outBody = { ...outBody, source_config: sc };
      }
      fetchOpts.body = JSON.stringify(outBody);
    }

    const resp = await fetch(targetUrl, fetchOpts);
    const contentType = resp.headers.get('content-type') || '';

    res.status(resp.status);

    if (contentType.includes('text/event-stream')) {
      res.setHeader('Content-Type', 'text/event-stream');
      res.setHeader('Cache-Control', 'no-cache');
      res.setHeader('Connection', 'keep-alive');
      const text = await resp.text();
      res.end(text);
    } else if (contentType.includes('json')) {
      const data = await resp.json();
      res.json(data);
    } else {
      const text = await resp.text();
      res.send(text);
    }
  } catch (err) {
    if (err.name === 'TimeoutError' || err.name === 'AbortError') {
      return res.status(504).json({ error: 'RepoBrain request timed out' });
    }
    if (err.cause?.code !== 'ECONNREFUSED') {
      console.error('[Nucleus proxy]', err.message);
    }
    res.status(502).json({ error: 'RepoBrain service unavailable', detail: err.message });
  }
});

// ============================================================================
// QuoxPlan proxy: /api/v1/quoxplan/* -> QUOXPLAN_URL/api/v1/* (QUOXPLAN-P4)
// ============================================================================
// Simpler than the RepoBrain proxy above by design: QuoxPlan is still a
// dummy-data dev product (STREAM_QUOXPLAN_PLAN.md, no real-roadmap migration
// until P7), so there is no per-org backend resolution or license gate yet —
// same auth posture as the collector default-deny gate (requireServiceOrUserAuth,
// shadow by default). Add org/license gating alongside RepoBrain's when
// QuoxPlan reaches multi-tenant phase 5.
// PLUGIN-IMG #1012: env first (compose and the plugins overlay set it), dev default otherwise.
const QUOXPLAN_URL = require('./lib/quoxplanUrl.js').resolveQuoxplanUrl();

// QUOXPLAN-P7: intent mapping for AEE emission at the governed boundary
// (the proxy, below — the ONLY place these mutations are witnessed, since
// quoxplanTools.js's write tools call the QuoxPlan server directly). relPath
// is the quoxplan-relative path (targetPath with the leading /api/v1 dropped),
// e.g. '/streams/CL-SUPPORT-KB/notes'. Falls back to a generic
// 'quoxplan.mutation' intent for any unlisted-but-real write rather than
// silently dropping evidence for it.
function resolveQuoxplanAeeIntent(method, relPath, body) {
  let m;
  if (method === 'PATCH' && (m = relPath.match(/^\/streams\/([^/]+)$/))) {
    return {
      intent: (body && body.status !== undefined) ? 'quoxplan.stream.status_changed' : 'quoxplan.stream.updated',
      ids: { stream_id: decodeURIComponent(m[1]) },
    };
  }
  if (method === 'POST' && (m = relPath.match(/^\/streams\/([^/]+)\/notes$/))) {
    return { intent: 'quoxplan.note.added', ids: { stream_id: decodeURIComponent(m[1]) } };
  }
  if (method === 'POST' && (m = relPath.match(/^\/streams\/([^/]+)\/phases$/))) {
    return { intent: 'quoxplan.phase.updated', ids: { stream_id: decodeURIComponent(m[1]) } };
  }
  if ((method === 'PATCH' || method === 'DELETE') && (m = relPath.match(/^\/phases\/([^/]+)$/))) {
    return { intent: 'quoxplan.phase.updated', ids: { phase_id: decodeURIComponent(m[1]) } };
  }
  if (method === 'PUT' && (m = relPath.match(/^\/streams\/([^/]+)\/plan$/))) {
    return { intent: 'quoxplan.plan.updated', ids: { stream_id: decodeURIComponent(m[1]) } };
  }
  if (method === 'POST' && (m = relPath.match(/^\/roadmaps\/([^/]+)\/reprioritise$/))) {
    return { intent: 'quoxplan.reprioritised', ids: { roadmap_id: decodeURIComponent(m[1]) } };
  }
  if (method === 'POST' && (m = relPath.match(/^\/roadmaps\/([^/]+)\/streams$/))) {
    return { intent: 'quoxplan.stream.created', ids: { roadmap_id: decodeURIComponent(m[1]) } };
  }
  if (method === 'POST' && (m = relPath.match(/^\/streams\/([^/]+)\/action-items$/))) {
    return { intent: 'quoxplan.action_item.updated', ids: { stream_id: decodeURIComponent(m[1]) } };
  }
  if (method === 'PATCH' && (m = relPath.match(/^\/action-items\/([^/]+)$/))) {
    return { intent: 'quoxplan.action_item.updated', ids: { action_item_id: decodeURIComponent(m[1]) } };
  }
  if (['PATCH', 'POST', 'PUT', 'DELETE'].includes(method)) {
    return { intent: 'quoxplan.mutation', ids: {} };
  }
  return null;
}

/** Emit a quoxplan.* AEE envelope for a successful governed mutation through
 * the proxy. Fire-and-forget: any failure here must NEVER fail the proxied
 * request — caught and logged only. Mirrors emitWazuhAEE's from-resolution. */
// QUOXIFY pass 4 (DEVSUITE phase 17): this used to hardcode
// `to: 'agent.roady'` and `corr: QUOXPLAN_<ts>`, and the QLarity proxy reused
// it verbatim. So every governed browser inspection was witnessed as if the
// ROADMAP agent had done it, under a QuoxPlan correlation id (bundle audit
// note #2842, S-Q4: "QLarity reuses the QuoxPlan emitter so its envelopes are
// mislabeled"). Evidence that names the wrong actor is worse than thin
// evidence: it is confidently wrong, and an audit trail is the one place that
// cannot be. Parameterised, with the QuoxPlan values as defaults so its own
// two call sites are unchanged.
function emitProxyAEE(req, orgId, mapped, { to = 'agent.roady', corrPrefix = 'QUOXPLAN', onBehalfOfOrg = null } = {}) {
  try {
    const from = req.service ? 'service.collector' : (req.user && req.user.id ? `human.${req.user.id}` : 'system');
    storeAuditEnvelope({
      type: 'event',
      from,
      to,
      intent: mapped.intent,
      corr: `${corrPrefix}_${Date.now()}`,
      org_id: orgId || null,
      payload: {
        ...mapped.ids,
        method: req.method,
        fields: Object.keys(req.body || {}).filter((k) => k !== 'actor' && k !== 'confirm_owner'),
        // Cross-org create: record that this roadmap was made FOR another org,
        // so the evidence trail shows the on-behalf-of, not just the caller.
        ...(onBehalfOfOrg ? { on_behalf_of_org: onBehalfOfOrg } : {}),
      },
    });
  } catch (err) {
    console.warn('[QuoxPlan proxy] AEE emission failed (non-fatal):', err.message);
  }
}

/**
 * Verify the CALLER's role in a target org by asking the auth service, with the
 * caller's own credentials. Used only for the roadmap-create-on-behalf-of path
 * in the QuoxPlan proxy. Token forwarding mirrors quoxflowUserAuthHeader (bearer
 * header first, then the browser access_token cookie); the /api/orgs read
 * mirrors the chat handler's org-resolution fetch. Fail-closed: any error or
 * non-2xx returns null so an unauthorized create can never land in a foreign
 * org. Caches nothing.
 */
async function verifyQuoxplanOrgRole(req, targetOrgId) {
  try {
    const authBase = process.env.AUTH_SERVICE_URL || 'http://auth:3101';
    const auth = req.headers.authorization;
    const headers = { Accept: 'application/json' };
    if (auth && /^Bearer /i.test(auth)) {
      headers.Authorization = auth;
    } else {
      const cookies = parseCookieHeader(req.headers.cookie);
      if (cookies.access_token) headers.Authorization = `Bearer ${cookies.access_token}`;
    }
    if (!headers.Authorization) return null;

    const resp = await fetch(`${authBase}/api/orgs`, {
      headers,
      signal: AbortSignal.timeout(5000),
    });
    if (!resp.ok) return null;

    const data = await resp.json();
    const list = data.organizations || data.orgs || [];
    const match = Array.isArray(list) ? list.find((o) => o && o.id === targetOrgId) : null;
    return match ? (match.role || null) : null;
  } catch (err) {
    return null;
  }
}

// LL-7 D3: server-enforced entitlement gate. The page gate looked
// authoritative for QuoxPlan while this proxy checked auth + org scoping
// only — any authenticated org reached the data plane. Same middleware as
// the lens/discord-pro/github mounts: 402 LICENSE_REQUIRED for an
// unlicensed user org, pure INTERNAL_SERVICE_KEY calls (no req.user)
// bypass, fail closed on lookup error.
app.all('/api/v1/quoxplan/*', requireServiceOrUserAuth(), requirePluginEntitlement('quoxplan'), async (req, res) => {
  // DEVSUITE phase 6 (2026-08-20): PER-ORG QuoxPlan. The 2026-08-15
  // owner-org-only 403 existed because the server was effectively
  // single-tenant (the live roadmap sat in UNSCOPED_ORG_IDS, visible to any
  // org that reached it). Both halves of that are gone: the live roadmap is
  // org-scoped to the instance owner's real org id (reassignOrg cutover)
  // and the QuoxPlan server enforces per-route org visibility (orgGuard,
  // 404-not-403). So the proxy now lets any AUTHENTICATED user through and
  // forwards their verified org (X-Quoxplan-Org below); each org sees its
  // own roadmaps plus the deliberate demo corpus, and a foreign org's ids
  // answer 404. A JWT with no org still gets nothing sensitive: it forwards
  // no org header only for service callers; org-less USERS are refused so
  // the unrestricted no-header mode stays a loopback/CLI privilege.
  if (!req.service && !(req.user && req.user.org_id)) {
    return res.status(403).json({
      error: 'quoxplan_org_gate',
      message: 'QuoxPlan needs an organisation-scoped session; log in to an organisation first.',
    });
  }
  // The QuoxPlan server mounts its health probe at bare /health (not under
  // /api/v1 like its data routes) — special-cased so the sidebar/header
  // health poll (api.health() -> `${API_BASE}/health`) doesn't 404 through
  // the generic /api/v1/quoxplan -> /api/v1 rewrite below.
  const isHealthCheck = req.method === 'GET' && req.path.endsWith('/quoxplan/health');
  // Defense in depth: refuse traversal segments before building the target
  // path; the rewrite below must never be escapable even if the backend
  // grows file-serving routes later.
  if (/(^|[\\/])\.\.([\\/]|$)/.test(decodeURIComponent(req.path))) {
    return res.status(400).json({ error: 'invalid path' });
  }
  const targetPath = isHealthCheck
    ? '/health'
    : req.originalUrl.replace('/collector/api/v1/quoxplan', '/api/v1').replace('/api/v1/quoxplan', '/api/v1');
  const targetUrl = `${QUOXPLAN_URL}${targetPath}`;

  try {
    const fetchOpts = {
      method: req.method,
      headers: {
        'Accept': 'application/json',
        'Content-Type': req.headers['content-type'] || 'application/json',
      },
      signal: AbortSignal.timeout(30000),
    };

    // QuoxPlan's /api/v1 serviceKeyGate requires the house-standard internal
    // service key when QUOXPLAN_SERVICE_KEY is armed on that server. This is a
    // governed, authenticated boundary (requireServiceOrUserAuth + quoxplan
    // entitlement above), so it presents the key on the caller's behalf. Without
    // it, every `quox plan` call 401s the moment the gate is enabled.
    if (process.env.INTERNAL_SERVICE_KEY) {
      fetchOpts.headers['X-Service-Key'] = process.env.INTERNAL_SERVICE_KEY;
    }

    // QUOXPLAN-P5: org separation. Resolve the caller's active org the same
    // way the action-tracker proxies do (verified JWT org_id first, then the
    // client-supplied X-Org-Id header) and forward it so the QuoxPlan server
    // can filter roadmaps to that org (plus its legacy/demo unscoped ones).
    // Cross-org roadmap placement fix: an authorized roadmap-create can target
    // a DIFFERENT org than the caller's active one (an operator onboarding a
    // customer tenant). resolveQuoxplanForwardOrg returns the target org only
    // when a real owner/admin of that org asks; every other request keeps the
    // caller's own org. callerOrgId is still the caller's org, kept for the AEE
    // envelope's org_id below.
    const callerOrgId = resolveCallerOrgId(req);
    const { forwardOrg, onBehalfOf } = await resolveQuoxplanForwardOrg(req, {
      verifyOrgRole: verifyQuoxplanOrgRole,
    });
    if (forwardOrg) {
      fetchOpts.headers['X-Quoxplan-Org'] = forwardOrg;
    }

    if (['POST', 'PUT', 'PATCH', 'DELETE'].includes(req.method) && req.body && Object.keys(req.body).length > 0) {
      // Governance/first-run F6.3: stamp the SERVER-AUTHORITATIVE actor so QuoxPlan's activity feed
      // attributes each mutation to the real authenticated user, not the spoofable client-supplied
      // actor:'owner' the dashboard sends (which made every action in a multi-user org read "by owner").
      // The authoritative AEE/WARD trail already binds the real identity (emitProxyAEE `from:human.<id>`);
      // this aligns the QuoxPlan-internal feed with it. Overridden here, never trusted from the body.
      const actorLabel = req.user?.email || req.user?.id || (req.service ? 'service' : null);
      const forwardBody = actorLabel ? { ...req.body, actor: actorLabel } : req.body;
      fetchOpts.body = JSON.stringify(forwardBody);
    }

    const resp = await fetch(targetUrl, fetchOpts);
    const contentType = resp.headers.get('content-type') || '';

    // QUOXPLAN-P7: evidence layer — a SUCCESSFUL (2xx) mutating request gets
    // an AEE envelope at this governed boundary. Fire-and-forget, never
    // blocks or fails the proxied response.
    if (!isHealthCheck && resp.status >= 200 && resp.status < 300
      && ['PATCH', 'POST', 'PUT', 'DELETE'].includes(req.method)) {
      const relPath = targetPath.replace(/^\/api\/v1/, '').split('?')[0];
      const mapped = resolveQuoxplanAeeIntent(req.method, relPath, req.body);
      if (mapped) emitProxyAEE(req, callerOrgId, mapped, onBehalfOf ? { onBehalfOfOrg: forwardOrg } : {});
    }

    res.status(resp.status);

    if (contentType.includes('json')) {
      const data = await resp.json();
      res.json(data);
    } else {
      const text = await resp.text();
      res.send(text);
    }
  } catch (err) {
    if (err.name === 'TimeoutError' || err.name === 'AbortError') {
      return res.status(504).json({ error: 'QuoxPlan request timed out' });
    }
    if (err.cause?.code !== 'ECONNREFUSED') {
      console.error('[QuoxPlan proxy]', err.message);
    }
    // No err.message to the client: it can carry internal topology
    // (host.docker.internal:3107) on connection failures.
    res.status(502).json({ error: 'QuoxPlan service unavailable' });
  }
});

// ============================================================================
// Quox Voice proxy: /api/v1/quox-voice/* -> QUOX_VOICE_URL/v1/* (QUOX-VOICE P2)
// ============================================================================
// The governed bridge for realtime voice sessions (quox-voice repo, :3111).
// The voice control API does its own caller resolution against the auth
// service, so unlike the QuoxPlan proxy this one FORWARDS the caller's bearer
// token: the backend re-derives org scope from the token, and the collector
// adds the witness layer (quox.voice.* AEE) that the backend cannot emit for
// itself. Entitlement gating deliberately absent for now: the quox-voice /
// advanced-voice entitlement relationship is unresolved (STORE-CANON #3842)
// and adding a wrong paywall is the known failure class. Wire
// requirePluginEntitlement here in P4 when that decision lands.
const QUOX_VOICE_URL = process.env.QUOX_VOICE_URL || 'http://host.docker.internal:3111';

function resolveQuoxVoiceAeeIntent(method, relPath) {
  let m;
  if (method === 'POST' && relPath === '/sessions') {
    return { intent: 'quox.voice.session_created', ids: {} };
  }
  if (method === 'POST' && (m = relPath.match(/^\/sessions\/([^/]+)\/end$/))) {
    return { intent: 'quox.voice.session_ended', ids: { voice_session_id: decodeURIComponent(m[1]) } };
  }
  if (['PATCH', 'POST', 'PUT', 'DELETE'].includes(method)) {
    return { intent: 'quox.voice.mutation', ids: {} };
  }
  return null;
}

app.all('/api/v1/quox-voice/*', requireServiceOrUserAuth(), async (req, res) => {
  // Same org posture as the QuoxPlan proxy: org-less USER sessions are
  // refused; the backend additionally re-verifies org from the token.
  if (!req.service && !(req.user && req.user.org_id)) {
    return res.status(403).json({
      error: 'quox_voice_org_gate',
      message: 'Quox Voice needs an organisation-scoped session; log in to an organisation first.',
    });
  }
  if (/(^|[\\/])\.\.([\\/]|$)/.test(decodeURIComponent(req.path))) {
    return res.status(400).json({ error: 'invalid path' });
  }
  // Health probe is /healthz on the voice service, not under /v1.
  const isHealthCheck = req.method === 'GET' && req.path.endsWith('/quox-voice/health');
  const targetPath = isHealthCheck
    ? '/healthz'
    : req.originalUrl.replace('/collector/api/v1/quox-voice', '/v1').replace('/api/v1/quox-voice', '/v1');
  const targetUrl = `${QUOX_VOICE_URL}${targetPath}`;

  try {
    const fetchOpts = {
      method: req.method,
      headers: {
        'Accept': 'application/json',
        'Content-Type': req.headers['content-type'] || 'application/json',
      },
      signal: AbortSignal.timeout(30000),
    };
    // Forward the caller's own bearer: the voice API resolves caller + org
    // from it (never from a client-supplied header alone). Cookie-session
    // browsers get their access_token converted to a bearer, same as the
    // quoxflow proxy (quoxflowUserAuthHeader below; function declarations
    // hoist across this module).
    const userAuth = quoxflowUserAuthHeader(req);
    if (userAuth) {
      Object.assign(fetchOpts.headers, userAuth);
    }
    const callerOrgId = resolveCallerOrgId(req);
    if (callerOrgId) {
      fetchOpts.headers['X-Quox-Org'] = callerOrgId;
    }
    if (['POST', 'PUT', 'PATCH', 'DELETE'].includes(req.method) && req.body && Object.keys(req.body).length > 0) {
      fetchOpts.body = JSON.stringify(req.body);
    }

    const resp = await fetch(targetUrl, fetchOpts);
    const contentType = resp.headers.get('content-type') || '';

    if (!isHealthCheck && resp.status >= 200 && resp.status < 300
      && ['PATCH', 'POST', 'PUT', 'DELETE'].includes(req.method)) {
      const relPath = targetPath.replace(/^\/v1/, '').split('?')[0];
      const mapped = resolveQuoxVoiceAeeIntent(req.method, relPath);
      if (mapped) {
        emitProxyAEE(req, callerOrgId, mapped, { to: 'agent.quox', corrPrefix: 'QUOXVOICE' });
      }
    }

    res.status(resp.status);
    if (contentType.includes('json')) {
      const data = await resp.json();
      res.json(data);
    } else {
      const text = await resp.text();
      res.send(text);
    }
  } catch (err) {
    if (err.name === 'TimeoutError' || err.name === 'AbortError') {
      return res.status(504).json({ error: 'Quox Voice request timed out' });
    }
    if (err.cause?.code !== 'ECONNREFUSED') {
      console.error('[QuoxVoice proxy]', err.message);
    }
    // No err.message to the client: it can carry internal topology on
    // connection failures.
    res.status(502).json({ error: 'Quox Voice service unavailable' });
  }
});

// ============================================================================
// OutboundQ schedule proxy: /api/v1/telephony-schedules/* -> bridge :3112 (#521 P5)
// ============================================================================
// The browser cannot reach the loopback telephony bridge and must NEVER hold the
// bridge's X-Quox-Trigger secret. This is the one authed, org-gated hop: it injects
// the secret SERVER-SIDE (the Bastion-proxy pattern, not the bearer-forwarding the
// quox-voice realtime proxy uses) and forwards the authed user's org. SINGLE-ORG POC
// HONESTY: the bridge resolves its org from the configured Twilio number today and
// does not yet honour the forwarded X-Quox-Org, so this surface is owner single-org
// until the bridge does (tracked #521). The collector still refuses org-less users.
const QUOX_TELEPHONY_BRIDGE_URL = process.env.QUOX_TELEPHONY_BRIDGE_URL || 'http://host.docker.internal:3112';

function resolveScheduleAeeIntent(method, relPath) {
  if (method === 'POST' && relPath === '') return { intent: 'quox.voice.schedule.created', ids: {} };
  const m = relPath.match(/^\/([^/]+)$/);
  if (m) {
    const id = decodeURIComponent(m[1]);
    if (method === 'PATCH') return { intent: 'quox.voice.schedule.updated', ids: { schedule_id: id } };
    if (method === 'DELETE') return { intent: 'quox.voice.schedule.deleted', ids: { schedule_id: id } };
  }
  if (['POST', 'PATCH', 'PUT', 'DELETE'].includes(method)) return { intent: 'quox.voice.schedule.mutation', ids: {} };
  return null;
}

async function telephonyScheduleProxy(req, res) {
  const callerOrgId = resolveCallerOrgId(req);
  if (!req.service && !callerOrgId) {
    return res.status(403).json({
      error: 'telephony_schedule_org_gate',
      message: 'Scheduled calls need an organisation-scoped session; log in to an organisation first.',
    });
  }
  const secret = process.env.TELEPHONY_TRIGGER_SECRET || '';
  if (!secret) {
    return res.status(503).json({
      error: 'telephony_scheduling_unconfigured',
      message: 'Scheduled calling is not configured on this instance.',
    });
  }
  if (/(^|[\\/])\.\.([\\/]|$)/.test(decodeURIComponent(req.path))) {
    return res.status(400).json({ error: 'invalid path' });
  }
  const targetPath = req.originalUrl
    .replace('/collector/api/v1/telephony-schedules', '/telephony/schedules')
    .replace('/api/v1/telephony-schedules', '/telephony/schedules');
  const targetUrl = `${QUOX_TELEPHONY_BRIDGE_URL}${targetPath}`;
  try {
    const fetchOpts = {
      method: req.method,
      headers: { 'Accept': 'application/json', 'Content-Type': 'application/json', 'X-Quox-Trigger': secret },
      signal: AbortSignal.timeout(10000),
    };
    if (callerOrgId) fetchOpts.headers['X-Quox-Org'] = callerOrgId;  // forward-compatible; bridge single-org today
    if (['POST', 'PUT', 'PATCH'].includes(req.method) && req.body && Object.keys(req.body).length > 0) {
      fetchOpts.body = JSON.stringify(req.body);
    }
    const resp = await fetch(targetUrl, fetchOpts);
    const contentType = resp.headers.get('content-type') || '';
    if (resp.status >= 200 && resp.status < 300 && ['POST', 'PATCH', 'PUT', 'DELETE'].includes(req.method)) {
      const relPath = targetPath.replace(/^\/telephony\/schedules/, '').split('?')[0];
      const mapped = resolveScheduleAeeIntent(req.method, relPath);
      if (mapped) emitProxyAEE(req, callerOrgId, mapped, { to: 'agent.outboundq', corrPrefix: 'OUTBOUNDQ' });
    }
    res.status(resp.status);
    if (contentType.includes('json')) res.json(await resp.json());
    else res.send(await resp.text());
  } catch (err) {
    if (err.name === 'TimeoutError' || err.name === 'AbortError') {
      return res.status(504).json({ error: 'telephony schedule request timed out' });
    }
    if (err.cause?.code !== 'ECONNREFUSED') console.error('[OutboundQ schedule proxy]', err.message);
    res.status(502).json({ error: 'telephony scheduling service unavailable' });
  }
}

app.all('/api/v1/telephony-schedules', requireServiceOrUserAuth(), telephonyScheduleProxy);
app.all('/api/v1/telephony-schedules/*', requireServiceOrUserAuth(), telephonyScheduleProxy);

// ============================================================================
// QuoxSEO proxy: /api/v1/quoxseo/* -> QUOXSEO_URL/api/v1/* (QUOXSEO S2)
// ============================================================================
// GOVERNED FROM DAY ONE (the QLarity lesson, not the quoxplan/quoxsignal
// "gate later" path): entitlement-checked and org-forwarded on the first
// commit. The backend (repo quoxai/quox-seo, host loopback :3110) is
// READ-ONLY over the org-scoped URL warehouse + WARD-witnessed change log;
// ingest/witness run on a systemd timer, never through HTTP, so this proxy
// forwards GET plus exactly ONE governed mutation: site registration
// (POST /sites, quox#583), which gets AEE emission here at the boundary like
// the QuoxPlan proxy above. The witnessed WARD chain remains the evidence
// trail for ingest itself; every other write is refused (see
// lib/quoxseoProxyPolicy.js).
const QUOXSEO_URL = process.env.QUOXSEO_URL || 'http://quoxseo:3110';

app.all('/api/v1/quoxseo/*', requireServiceOrUserAuth(), requirePluginEntitlement('quoxseo'), async (req, res, next) => {
  // The report-deliver endpoint is a dedicated governed WRITE with its own
  // route registered below; fall through to it rather than let this
  // read-only proxy 405 it (Express matches app.all first by registration
  // order). This is the ONE non-proxied POST under /api/v1/quoxseo/*.
  if (req.method === 'POST' && req.path.endsWith('/quoxseo/report/deliver')) return next();
  // Report SCHEDULING is collector-native too (durable weekly delivery with the
  // triad), not a quox-seo proxy read. Fall through for its CRUD routes below.
  if (req.path.includes('/quoxseo/report/schedule') && ['POST', 'GET', 'PATCH'].includes(req.method)) return next();
  // quox#583: site registration is the ONE governed mutation on this
  // otherwise read-only surface. The backend enforces request shape, SSRF
  // guard and the per-org property cap; THIS boundary owns the entitlement
  // check (middleware above) and the AEE envelope (below), exactly as the
  // day-one comment demanded.
  const seoPolicy = require('./lib/quoxseoProxyPolicy').evaluateQuoxseoRequest(req.method, req.path);
  if (!seoPolicy.allowed) {
    return res.status(405).json({ error: 'read_only', message: 'QuoxSEO API is read-only apart from site registration and removal (POST /sites, DELETE /sites/:id); ingest runs server-side on a schedule.' });
  }
  // Same org posture as the QuoxPlan proxy: authenticated users need an org;
  // org-less USERS are refused so no-org access stays a loopback privilege.
  const callerOrgId = resolveCallerOrgId(req);
  if (!req.service && !callerOrgId) {
    return res.status(403).json({
      error: 'quoxseo_org_gate',
      message: 'QuoxSEO needs an organisation-scoped session; log in to an organisation first.',
    });
  }
  if (/(^|[\\/])\.\.([\\/]|$)/.test(decodeURIComponent(req.path))) {
    return res.status(400).json({ error: 'invalid path' });
  }
  const isHealthCheck = req.path.endsWith('/quoxseo/health');
  const targetPath = isHealthCheck
    ? '/health'
    : req.originalUrl.replace('/collector/api/v1/quoxseo', '/api/v1').replace('/api/v1/quoxseo', '/api/v1');
  try {
    const resp = await fetch(`${QUOXSEO_URL}${targetPath}`, {
      method: req.method,
      headers: {
        'Accept': 'application/json',
        ...(seoPolicy.mutation && req.method === 'POST' ? { 'Content-Type': 'application/json' } : {}),
        ...(callerOrgId ? { 'X-Quoxseo-Org': callerOrgId } : {}),
      },
      ...(seoPolicy.mutation && req.method === 'POST' ? { body: JSON.stringify(req.body ?? {}) } : {}),
      signal: AbortSignal.timeout(30000),
    });
    if (seoPolicy.mutation && resp.ok) {
      // Witness the governed write. emitProxyAEE records field NAMES plus the
      // ids we pass; origin is the identity of what was registered, not a
      // secret, so it belongs in the trail.
      const removing = seoPolicy.intent === 'quox.seo.site_remove';
      emitProxyAEE(req, callerOrgId, removing
        ? { intent: 'quox.seo.site_remove', ids: { site_id: req.path.split('/').filter(Boolean).pop() } }
        : { intent: 'quox.seo.site_register', ids: { origin: req.body?.origin } }, { to: 'service.quoxseo', corrPrefix: 'QUOXSEO' });
    }
    res.status(resp.status);
    const contentType = resp.headers.get('content-type') || '';
    if (contentType.includes('json')) {
      res.json(await resp.json());
    } else {
      res.send(await resp.text());
    }
  } catch (err) {
    if (err.name === 'TimeoutError' || err.name === 'AbortError') {
      return res.status(504).json({ error: 'QuoxSEO request timed out' });
    }
    if (err.cause?.code !== 'ECONNREFUSED') {
      console.error('[QuoxSEO proxy]', err.message);
    }
    // No err.message to the client: it can carry internal topology.
    res.status(502).json({ error: 'QuoxSEO service unavailable' });
  }
});

// ----------------------------------------------------------------------------
// QuoxSEO report delivery: on-demand governed send (email + HITL inbox).
// Additive to the proxy above; NOT a scheduler (a recurring/cron delivery is
// a separate, deliberately deferred follow-up). Same auth + entitlement gate
// as the proxy, mirrored exactly, so this never becomes an ungated side door
// into an otherwise governed plugin.
// ----------------------------------------------------------------------------
const { deliverQuoxseoReport } = require('./lib/quoxseoReport.js');

app.post('/api/v1/quoxseo/report/deliver', requireServiceOrUserAuth(), requirePluginEntitlement('quoxseo'), async (req, res) => {
  const callerOrgId = resolveCallerOrgId(req);
  if (!req.service && !callerOrgId) {
    return res.status(403).json({
      error: 'quoxseo_org_gate',
      message: 'QuoxSEO needs an organisation-scoped session; log in to an organisation first.',
    });
  }
  // Service-key callers (no req.user) must supply the target org explicitly;
  // there is no session org_id to fall back to for them.
  const orgId = callerOrgId || req.body?.org_id;
  if (!orgId) {
    return res.status(400).json({ error: 'org_id_required', message: 'A target org_id is required for a service-key caller.' });
  }

  const channels = Array.isArray(req.body?.channels) && req.body.channels.length > 0
    ? req.body.channels
    : ['email', 'inbox'];
  // No dedicated "org notification email" field exists in this codebase
  // today; the authenticated caller's own email is the only resolvable
  // default. Flagged as a gap, not invented: pass { recipient } explicitly
  // for anything other than "email the caller".
  const recipient = req.body?.recipient || req.user?.email || null;
  if (channels.includes('email') && !recipient) {
    return res.status(400).json({
      error: 'recipient_required',
      message: 'No recipient email resolvable for this caller; pass { recipient } explicitly.',
    });
  }

  try {
    const summary = await deliverQuoxseoReport({
      orgId,
      recipientEmail: recipient,
      channels,
      authServiceUrl: process.env.AUTH_SERVICE_URL || 'http://auth:3101',
      internalServiceKey: process.env.INTERNAL_SERVICE_KEY || '',
      quoxseoUrl: QUOXSEO_URL,
    });

    // Fire-and-forget evidence, same posture as emitProxyAEE/emitWazuhAEE
    // above: never let an audit-trail write fail the actual response.
    try {
      const from = req.service ? 'service.collector' : (req.user && req.user.id ? `human.${req.user.id}` : 'system');
      storeAuditEnvelope({
        type: 'event',
        from,
        to: 'audit.ops',
        intent: 'quox.quoxseo.report.deliver',
        corr: `QUOXSEO_${Date.now()}`,
        org_id: orgId,
        payload: {
          channels,
          csvIncluded: summary.csvIncluded,
          emailOk: summary.email ? summary.email.success !== false : null,
          inboxOk: summary.inbox ? !summary.inbox.error : null,
        },
      });
    } catch (aeeErr) {
      console.warn('[QuoxSEO report deliver] AEE emission failed (non-fatal):', aeeErr.message);
    }

    res.json(summary);
  } catch (err) {
    console.error('[QuoxSEO report deliver]', err.message);
    res.status(502).json({ error: 'quoxseo_report_unavailable', message: err.message });
  }
});

// ============================================================================
// QuoxSEO weekly report SCHEDULER (QUOXSEO P-H): durable, server-side, triad.
// ============================================================================
const quoxseoScheduler = require('./lib/quoxseoScheduler.js');
// One deliver closure the runner and any manual "run now" share; binds the
// collector-only deps (SMTP via notificationService, inbox service key).
function quoxseoScheduledDeliver(args) {
  return deliverQuoxseoReport({
    ...args,
    authServiceUrl: process.env.AUTH_SERVICE_URL || 'http://auth:3101',
    internalServiceKey: process.env.INTERNAL_SERVICE_KEY || '',
    quoxseoUrl: QUOXSEO_URL,
  });
}
function quoxseoSchedOrg(req) {
  return resolveCallerOrgId(req);
}

// Create a schedule.
app.post('/api/v1/quoxseo/report/schedule', requireServiceOrUserAuth(), requirePluginEntitlement('quoxseo'), (req, res) => {
  const orgId = quoxseoSchedOrg(req);
  if (!orgId) return res.status(400).json({ error: 'org_id_required', message: 'A target org_id is required.' });
  const b = req.body || {};
  const channels = Array.isArray(b.channels) && b.channels.length ? b.channels : ['email', 'inbox'];
  const recipient = b.recipient || req.user?.email || null;
  if (channels.includes('email') && !recipient) {
    return res.status(400).json({ error: 'recipient_required', message: 'No recipient email resolvable; pass { recipient }.' });
  }
  if (b.interval && !['weekly', 'daily', 'monthly'].includes(b.interval)) {
    return res.status(400).json({ error: 'bad_interval', message: 'interval must be weekly | daily | monthly' });
  }
  try {
    const sched = quoxseoScheduler.createSchedule(voltDb, {
      orgId, siteId: b.site_id ?? null, recipientEmail: recipient, channels,
      interval: b.interval || 'weekly', dayOfWeek: b.day_of_week, hour: b.hour,
      timezone: b.timezone || 'UTC', reportType: b.report_type || 'full',
    }, Date.now());
    try {
      storeAuditEnvelope({ type: 'event', from: req.service ? 'service.collector' : `human.${req.user?.id || 'unknown'}`, to: 'audit.ops', intent: 'quox.quoxseo.report.schedule.create', corr: `QUOXSEO_SCHED_${Date.now()}`, org_id: orgId, payload: { id: sched.id, interval: sched.interval, channels } });
    } catch { /* evidence best-effort */ }
    res.status(201).json({ schedule: sched });
  } catch (err) {
    console.error('[QuoxSEO schedule create]', err.message);
    res.status(500).json({ error: 'schedule_create_failed', message: err.message });
  }
});

// List this org's schedules.
app.get('/api/v1/quoxseo/report/schedule', requireServiceOrUserAuth(), requirePluginEntitlement('quoxseo'), (req, res) => {
  const orgId = quoxseoSchedOrg(req);
  if (!orgId) return res.status(400).json({ error: 'org_id_required' });
  try {
    res.json({ schedules: quoxseoScheduler.listSchedules(voltDb, orgId) });
  } catch (err) {
    res.status(500).json({ error: 'schedule_list_failed', message: err.message });
  }
});

// Pause / resume / retire a schedule (status is the only mutation).
app.patch('/api/v1/quoxseo/report/schedule/:id', requireServiceOrUserAuth(), requirePluginEntitlement('quoxseo'), (req, res) => {
  const orgId = quoxseoSchedOrg(req);
  if (!orgId) return res.status(400).json({ error: 'org_id_required' });
  const status = req.body?.status;
  if (!['active', 'paused', 'retired'].includes(status)) {
    return res.status(400).json({ error: 'bad_status', message: 'status must be active | paused | retired' });
  }
  try {
    const updated = quoxseoScheduler.setStatus(voltDb, req.params.id, orgId, status, req.body?.reason || null, Date.now());
    if (!updated) return res.status(404).json({ error: 'no_such_schedule' });
    res.json({ schedule: updated });
  } catch (err) {
    res.status(500).json({ error: 'schedule_update_failed', message: err.message });
  }
});

// The runner. Server-side (never a browser timer), reads due schedules from the
// durable store every 60s, applies the triad. Restart-safe: paused/retired
// schedules are persisted and never resurrected; it is not a boot-triggered
// one-shot, so a restart simply resumes checking due times.
let quoxseoSchedulerRunner = null;
function startQuoxseoScheduler() {
  if (quoxseoSchedulerRunner || !voltDb) return;
  try { quoxseoScheduler.initSchema(voltDb); } catch (e) { console.error('[QuoxSEO sched] schema init failed:', e.message); return; }
  quoxseoSchedulerRunner = setInterval(async () => {
    try {
      await quoxseoScheduler.runDueSchedules({ db: voltDb, nowMs: Date.now(), deliver: quoxseoScheduledDeliver, log: (m) => console.log(m) });
    } catch (err) {
      console.error('[QuoxSEO sched] runner tick error:', err.message);
    }
  }, 60000);
  quoxseoSchedulerRunner.unref?.();
  console.log('[QuoxSEO sched] server-side report scheduler started (60s interval)');
}
if (voltDb) startQuoxseoScheduler();

// ============================================================================
// QLarity proxy: /api/v1/qlarity/* -> QLARITY_URL/api/v1/* (DEVSUITE-CLARIFY)
// ============================================================================
// GOVERNED FROM DAY ONE, modelled on the nucleus proxy above rather than on
// its immediate neighbours. QuoxPlan and QuoxSignal both shipped ungoverned
// "until the multi-tenant phase", and DEVSUITE-BLUEPRINT records that as
// defect 5.2: retro-governing a live plugin is an owner-gated cutover with a
// lockout risk, and "add gating later" is how a paid plugin ships free. So the
// org resolution and the licence gate are here on the first commit.
//
// QLarity drives a headless browser. Its blast radius on a missing gate is not
// "someone reads a roadmap they did not pay for", it is "someone points a
// browser inside the Docker network". The service enforces its own default-deny
// egress allowlist; this boundary is what decides WHO may ask.
const QLARITY_URL = process.env.QLARITY_URL || 'http://qlarity:3109';

function resolveQlarityAeeIntent(method, relPath) {
  if (method === 'POST' && /^\/sessions$/.test(relPath)) return { intent: 'qlarity.session.opened' };
  if (method === 'DELETE' && /^\/sessions\//.test(relPath)) return { intent: 'qlarity.session.closed' };
  if (method === 'POST' && /\/open$/.test(relPath)) return { intent: 'qlarity.page.opened' };
  if (method === 'POST' && /\/login$/.test(relPath)) return { intent: 'qlarity.session.login' };
  if (method === 'POST' && /\/inspect$/.test(relPath)) return { intent: 'qlarity.inspected' };
  if (method === 'POST' && /\/eval$/.test(relPath)) return { intent: 'qlarity.eval.requested' };
  // Generic fallback rather than dropping evidence for an unlisted write —
  // the QuoxPlan pattern (server.js resolveQuoxplanAeeIntent). A coarse
  // receipt beats a gap.
  return { intent: 'qlarity.mutation' };
}

/**
 * QLARITY-LOGIN (issue #15): resolve a `browser_login` vault credential
 * server-side and hand back the FIELDS a qlarity /sessions/:id/login call
 * needs — never the credential id's contents to the caller, and never a
 * value logged. Reuses the exact internal endpoint
 * (`/api/setup/internal/credential-decrypt/:id`) agentTools.js's
 * `browser_login` tool already calls for the same integration type, rather
 * than inventing a parallel vault type or a parallel resolve path — the
 * SAME `browser_login` credential (domain, username, password, optional
 * login_url) now serves both ScreenCap's act-as-user flow and qlarity's
 * read-only inspection flow.
 *
 * Throws an Error carrying `.status` on any failure; the caller maps that
 * straight to the HTTP response instead of ever forwarding raw
 * username/password from a failed resolve.
 */
async function resolveQlarityLoginCredential({ orgId, credentialId }) {
  let resp;
  try {
    resp = await fetch(
      `${AUTH_BASE_URL}/api/setup/internal/credential-decrypt/${encodeURIComponent(credentialId)}?org_id=${encodeURIComponent(orgId)}`,
      { headers: buildInternalServiceHeaders(), signal: AbortSignal.timeout(10000) },
    );
  } catch (err) {
    const wrapped = new Error('credential_resolve_unavailable');
    wrapped.status = 502;
    throw wrapped;
  }
  if (!resp.ok) {
    const wrapped = new Error(resp.status === 403 ? 'lease_required' : 'credential_not_found');
    wrapped.status = resp.status === 403 ? 403 : 404;
    throw wrapped;
  }
  const data = await resp.json();
  if (data?.integration_type !== 'browser_login') {
    const wrapped = new Error('credential_type_mismatch: expected a browser_login credential');
    wrapped.status = 400;
    throw wrapped;
  }
  const creds = data.credentials || {};
  if (!creds.domain || !creds.username || !creds.password) {
    const wrapped = new Error('credential_incomplete');
    wrapped.status = 422;
    throw wrapped;
  }
  let loginPath = '/login';
  if (creds.login_url) {
    try { loginPath = new URL(creds.login_url, creds.domain).pathname || '/login'; } catch { /* keep default */ }
  }
  return { origin: creds.domain, login_path: loginPath, username: creds.username, password: creds.password };
}

// NO-ENV-ONLY-CONFIG (2026-08-18): the customer-facing allowlist management
// surface. Reading is open to any org member so the UI can show what is
// declared; CHANGING it is admin-gated, the same posture as slot curation,
// because it decides what the org's browser sessions may reach.
//
// Mounted BEFORE the catch-all /api/v1/qlarity/* proxy: these paths are ours,
// not QLarity's, and the proxy would otherwise forward them to a service that
// has never heard of them.
app.get('/api/v1/qlarity-allowlist', requireServiceOrUserAuth(), requireLicence('qlarity', 'QLarity'), (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  const orgId = resolveNucleusOrgId(req);
  if (!orgId) return res.status(401).json({ error: 'Organisation context required' });
  try {
    res.json({
      origins: qlarityAllowlist.listOrigins({ orgId }),
      // Surfaced so the UI can explain WHY something is inspectable when the
      // org itself declared nothing: the operator's install-wide entries.
      install_wide: (process.env.QLARITY_ALLOWLIST || '').split(',').map((x) => x.trim()).filter(Boolean),
      policy: 'default-deny',
    });
  } catch (err) {
    console.error('[QLarity] allowlist list failed:', err.message);
    res.status(500).json({ error: 'list failed' });
  }
});

app.post('/api/v1/qlarity-allowlist', requireServiceOrUserAuth(), requireLicence('qlarity', 'QLarity'), (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  const orgId = resolveNucleusOrgId(req);
  if (!orgId) return res.status(401).json({ error: 'Organisation context required' });
  if (!requireAdminRole(req, res, 'Changing the QLarity allowlist requires an org admin')) return;
  const actor = req.user ? `human.${req.user.id || req.user.sub || 'unknown'}` : 'system.tasks';
  const { origin, note } = req.body || {};
  try {
    const result = qlarityAllowlist.addOrigin({ orgId, origin, addedBy: actor, note });
    if (!result.ok) {
      // Hand back the REASON. "Invalid origin" with no explanation is how a
      // customer concludes the product is broken rather than that they typed
      // a wildcard.
      return res.status(400).json({ error: 'bad_origin', message: result.reason });
    }
    storeAuditEnvelope({
      type: 'event', from: actor, to: 'audit.qlarity', intent: 'qlarity.allowlist.added',
      corr: `QLARITY_ALLOWLIST_${orgId}`,
      payload: { org_id: orgId, origin: result.entry.origin },
    });
    res.status(201).json({ entry: result.entry, origins: qlarityAllowlist.listOrigins({ orgId }) });
  } catch (err) {
    console.error('[QLarity] allowlist add failed:', err.message);
    res.status(500).json({ error: 'add failed' });
  }
});

app.delete('/api/v1/qlarity-allowlist', requireServiceOrUserAuth(), requireLicence('qlarity', 'QLarity'), (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'storage unavailable' });
  const orgId = resolveNucleusOrgId(req);
  if (!orgId) return res.status(401).json({ error: 'Organisation context required' });
  if (!requireAdminRole(req, res, 'Changing the QLarity allowlist requires an org admin')) return;
  const actor = req.user ? `human.${req.user.id || req.user.sub || 'unknown'}` : 'system.tasks';
  const origin = req.query.origin || (req.body || {}).origin;
  try {
    const result = qlarityAllowlist.removeOrigin({ orgId, origin });
    storeAuditEnvelope({
      type: 'event', from: actor, to: 'audit.qlarity', intent: 'qlarity.allowlist.removed',
      corr: `QLARITY_ALLOWLIST_${orgId}`,
      payload: { org_id: orgId, origin: result.origin, removed: result.removed },
    });
    res.json({ removed: result.removed, origins: qlarityAllowlist.listOrigins({ orgId }) });
  } catch (err) {
    console.error('[QLarity] allowlist remove failed:', err.message);
    res.status(500).json({ error: 'remove failed' });
  }
});

// quox#1171: agent fetch allowlist admin routes. Authenticated (default-deny
// gate admits any valid user); writes are human-org-admin only inside the module.
require('./lib/agentFetchAllowlistRoutes.js').registerAgentFetchAllowlistRoutes(app, {
  auth: requireServiceOrUserAuth,
  requireHumanAdmin,
  store: agentFetchAllowlist,
  audit: (e) => storeAuditEnvelope(e),
  // HYPERION NO-GO fix: only an INSTANCE admin may allowlist a private range
  checkInstanceAdmin: (req) => require('./lib/pluginBackendAdmin.js').checkInstanceAdmin(req, { isHumanAdmin }),
});

app.all('/api/v1/qlarity/*', requireServiceOrUserAuth(), async (req, res) => {
  const isHealthCheck = req.method === 'GET' && req.path.endsWith('/qlarity/health');

  if (/(^|[\\/])\.\.([\\/]|$)/.test(decodeURIComponent(req.path))) {
    return res.status(400).json({ error: 'invalid path' });
  }

  const orgId = resolveNucleusOrgId(req);
  if (!orgId) {
    return res.status(401).json({ error: 'Organisation context required for QLarity' });
  }

  // Health is gated too. An ungated health probe is a free existence oracle
  // and, more practically, the one route everybody forgets to gate.
  let licensed = false;
  try {
    licensed = await isPluginLicensedForOrg(orgId, 'qlarity');
  } catch (e) {
    licensed = false; // fail closed
  }
  if (!licensed) {
    return res.status(403).json({ error: 'QLarity is not licensed for this organisation' });
  }

  const targetPath = isHealthCheck
    ? '/health'
    : req.originalUrl.replace('/collector/api/v1/qlarity', '/api/v1').replace('/api/v1/qlarity', '/api/v1');
  const targetUrl = `${QLARITY_URL}${targetPath}`;

  try {
    const fetchOpts = {
      method: req.method,
      headers: {
        'Content-Type': 'application/json',
        // The service has no user auth of its own; org context is asserted
        // HERE, at the governed boundary, and the service trusts nothing else.
        'X-Org-Id': orgId,
        ...(req.user?.id ? { 'X-Actor-Id': String(req.user.id) } : {}),
      },
      signal: AbortSignal.timeout(30000),
    };
    if (!['GET', 'HEAD'].includes(req.method) && req.body) {
      fetchOpts.body = JSON.stringify(req.body);
    }

    // NO-ENV-ONLY-CONFIG: inject the org's OWN declared origins when it opens a
    // session. QLarity's install-wide QLARITY_ALLOWLIST stays in force and is
    // unioned service-side; this is what a customer can actually manage
    // themselves, which the env var made impossible (they buy QLarity, are
    // told nothing can be inspected, and cannot declare an origin without
    // shell access to the host).
    //
    // The allowlist is taken from the SERVER-SIDE store keyed by the org we
    // just resolved, never from the request body, so a caller cannot widen its
    // own egress by asking. It also cannot reach internal targets at all: the
    // service resolves DNS and refuses private/metadata addresses regardless
    // of this list.
    const isSessionCreate = req.method === 'POST' && /\/sessions\/?$/.test(targetPath.split('?')[0]);
    if (isSessionCreate) {
      try {
        const origins = qlarityAllowlist.originsFor({ orgId });
        if (origins.length) {
          const body = (req.body && typeof req.body === 'object') ? { ...req.body } : {};
          body.allowlist = origins;
          fetchOpts.body = JSON.stringify(body);
        }
      } catch (alErr) {
        // A failure here must not block opening a session: the customer just
        // falls back to the install-wide list, which is the pre-fix behaviour.
        console.warn('[QLarity] per-org allowlist lookup failed (non-fatal):', alErr.message);
      }
    }

    // QLARITY-LOGIN (issue #15): a login call arrives from the CLI/agent
    // carrying a `credential_id`, never a raw username/password — the vault
    // credential is resolved HERE, server-side, and its fields REPLACE
    // credential_id in the forwarded body. qlarity itself never sees a
    // credential id and this response is never returned to the caller, so
    // the secret exists only inside this one fetch to qlarity on the
    // internal network. Unlike the allowlist injection above, a resolve
    // failure here is NOT swallowed: forwarding credential_id unresolved
    // would make qlarity 400 with 'credentials_required' anyway, so failing
    // fast with the real reason (lease_required, credential_not_found, ...)
    // is strictly more useful and no less safe.
    const isLoginCall = req.method === 'POST' && /\/sessions\/[^/]+\/login\/?$/.test(targetPath.split('?')[0]);
    if (isLoginCall && req.body && typeof req.body === 'object' && req.body.credential_id) {
      try {
        const resolved = await resolveQlarityLoginCredential({ orgId, credentialId: req.body.credential_id });
        const body = { ...req.body };
        delete body.credential_id;
        body.origin = resolved.origin;
        if (!body.login_path) body.login_path = resolved.login_path;
        body.username = resolved.username;
        body.password = resolved.password;
        fetchOpts.body = JSON.stringify(body);
      } catch (credErr) {
        return res.status(credErr.status || 502).json({ error: credErr.message || 'credential_resolve_failed' });
      }
    }

    const resp = await fetch(targetUrl, fetchOpts);
    const contentType = resp.headers.get('content-type') || '';

    if (!isHealthCheck && resp.status >= 200 && resp.status < 300
      && ['PATCH', 'POST', 'PUT', 'DELETE'].includes(req.method)) {
      const relPath = targetPath.replace(/^\/api\/v1/, '').split('?')[0];
      const mapped = resolveQlarityAeeIntent(req.method, relPath);
      // Name QLarity as the actor, not the roadmap agent. 'audit.qlarity'
      // matches the codebase's own convention for a subsystem receipt
      // (audit.system, audit.build_queue) rather than falsely attributing a
      // browser inspection to an agent that never ran one.
      if (mapped) emitProxyAEE(req, orgId, mapped, { to: 'audit.qlarity', corrPrefix: 'QLARITY' });
    }

    res.status(resp.status);
    if (contentType.includes('json')) {
      res.json(await resp.json());
    } else {
      res.send(await resp.text());
    }
  } catch (err) {
    if (err.name === 'TimeoutError' || err.name === 'AbortError') {
      return res.status(504).json({ error: 'QLarity request timed out' });
    }
    if (err.cause?.code !== 'ECONNREFUSED') {
      console.error('[QLarity proxy]', err.message);
    }
    // No err.message to the client: it carries internal topology.
    res.status(502).json({ error: 'QLarity service unavailable' });
  }
});

// ============================================================================
// QuoxSignal proxy: /api/v1/signal/* -> QUOXSIGNAL_URL/api/v1/* (SIGNAL-EMBED)
// ============================================================================
// Same shape as the QuoxPlan proxy directly above — QuoxSignal is the second
// dev-bundle product to move from a standalone app into a governed dashboard
// surface. It has no org/license gating either (same posture as QuoxPlan pre
// multi-tenant phase 5), and no X-Quoxsignal-Org header forward: unlike
// QuoxPlan's server, quox-signal's server never reads an org header off the
// request (org_id comes from query/body only, defaulting 'default' — see
// quox-signal/server/src/api/*.js's orgIdOf()), so forwarding one here would
// be dead code pretending to do something it doesn't.
const QUOXSIGNAL_URL = process.env.QUOXSIGNAL_URL || 'http://host.docker.internal:3108';

// SIGNAL-P4: evidence bundles. See lib/signalEvidence.js for field
// provenance and the honesty rules around what can/can't be re-verified.
const { buildProposalBundle, proposalEvidenceCorr } = require('./lib/signalEvidence.js');

// SIGNAL-EMBED: intent mapping for AEE emission at the governed boundary (the
// proxy, below — the only place these mutations are witnessed since the web
// client talks to the QuoxSignal server only through this proxy). relPath is
// the signal-relative path (targetPath with the leading /api/v1 dropped),
// e.g. '/items/yt-123/stage'. Falls back to the generic 'signal.mutation'
// intent for any unlisted-but-real write rather than silently dropping
// evidence for it — never invent an intent for a route that doesn't exist.
function resolveSignalAeeIntent(method, relPath) {
  let m;
  if (method === 'POST' && relPath === '/sources') {
    return { intent: 'signal.source.followed', ids: {} };
  }
  if (method === 'POST' && relPath === '/items') {
    return { intent: 'signal.item.discovered', ids: {} };
  }
  if (method === 'POST' && (m = relPath.match(/^\/items\/([^/]+)\/stage$/))) {
    return { intent: 'signal.item.stage_requested', ids: { item_id: decodeURIComponent(m[1]) } };
  }
  if (method === 'POST' && relPath === '/proposals') {
    return { intent: 'signal.proposal.created', ids: {} };
  }
  if (method === 'POST' && (m = relPath.match(/^\/proposals\/([^/]+)\/decision$/))) {
    return { intent: 'signal.proposal.decided', ids: { proposal_id: decodeURIComponent(m[1]) } };
  }
  if (method === 'POST' && (m = relPath.match(/^\/proposals\/([^/]+)\/handoff$/))) {
    return { intent: 'signal.proposal.handed_off', ids: { proposal_id: decodeURIComponent(m[1]) } };
  }
  // Enrichment (the deepen-research next step) gets its own intent rather than falling
  // through to the generic signal.mutation: it SPENDS MONEY on a model call and appends a
  // second analysis alongside the original verdict, so "which enrichments were run against
  // this proposal, when, and by whom" has to be answerable from the evidence trail alone.
  if (method === 'POST' && (m = relPath.match(/^\/proposals\/([^/]+)\/enrichments$/))) {
    return { intent: 'signal.proposal.enriched', ids: { proposal_id: decodeURIComponent(m[1]) } };
  }
  if (['PATCH', 'POST', 'PUT', 'DELETE'].includes(method)) {
    return { intent: 'signal.mutation', ids: {} };
  }
  return null;
}

/** Emit a signal.* AEE envelope for a successful governed mutation through
 * the proxy. Fire-and-forget: any failure here must NEVER fail the proxied
 * request — caught and logged only. Mirrors emitProxyAEE.
 *
 * `corrOverride` lets proposal.created/handed_off use a DETERMINISTIC corr
 * (see lib/signalEvidence.js's proposalEvidenceCorr) instead of a
 * time-based one — that is what lets the frontend rediscover a proposal's
 * evidence thread on a fresh page load with no extra storage, since AEE
 * payloads are encrypted at rest and cannot cheaply be searched by
 * proposal_id. Every other signal.* mutation keeps the time-based corr.
 *
 * Returns the corr used, so a follow-up evidence-bundle envelope (see
 * persistSignalEvidenceBundle below) can be correlated to the exact same
 * mutation rather than starting a new, unlinked thread. */
function emitSignalAEE(req, orgId, mapped, corrOverride) {
  const corr = corrOverride || `SIGNAL_${Date.now()}`;
  try {
    const from = req.service ? 'service.collector' : (req.user && req.user.id ? `human.${req.user.id}` : 'system');
    storeAuditEnvelope({
      type: 'event',
      from,
      to: 'agent.scout',
      intent: mapped.intent,
      corr,
      org_id: orgId || null,
      payload: {
        ...mapped.ids,
        method: req.method,
        fields: Object.keys(req.body || {}).filter((k) => k !== 'actor'),
      },
    });
  } catch (err) {
    console.warn('[QuoxSignal proxy] AEE emission failed (non-fatal):', err.message);
  }
  return corr;
}

/** Fetch the item behind a proposal, for the evidence bundle's transcript
 * hash and ASR engine. Best-effort: any failure (timeout, 404, service
 * down) resolves to null rather than rejecting — buildProposalBundle
 * already degrades gracefully with no item. */
function fetchSignalItemForEvidence(itemId) {
  if (!itemId) return Promise.resolve(null);
  return fetch(`${QUOXSIGNAL_URL}/api/v1/items/${encodeURIComponent(itemId)}`, {
    headers: { Accept: 'application/json' },
    signal: AbortSignal.timeout(5000),
  })
    .then((r) => (r.ok ? r.json() : null))
    .catch(() => null);
}

/**
 * SIGNAL-P4: persist the evidence bundle for a proposal creation or
 * handoff. Fire-and-forget, always run AFTER the client response has
 * already been sent — a slow or failed item fetch must never add latency
 * or failure to the proposal request itself.
 *
 * Uses the SAME persistence mechanism as every other envelope in this file
 * (storeAuditEnvelope -> aeeDb -> WARD witness) rather than a second,
 * bundle-only store — the bundle lives in this envelope's payload. Its
 * own distinct intent (signal.evidence.bundled) and shared corr mean it is
 * a second, closely-related fact ("the evidence for this mutation was
 * captured and hashed"), not a duplicate of the mutation envelope itself —
 * mirrors how governance.incident.created is emitted as a follow-on
 * envelope off the back of another governed event elsewhere in this file.
 */
function persistSignalEvidenceBundle(orgId, corr, proposalId, itemId, proposalData) {
  fetchSignalItemForEvidence(itemId)
    .then((item) => {
      const bundle = buildProposalBundle(proposalData, item);
      storeAuditEnvelope({
        type: 'event',
        from: 'service.collector',
        to: 'agent.scout',
        intent: 'signal.evidence.bundled',
        corr,
        org_id: orgId || null,
        payload: { proposal_id: proposalId, item_id: itemId, bundle },
      });
    })
    .catch((err) => console.warn('[QuoxSignal proxy] evidence bundle failed (non-fatal):', err.message));
}

// LICENSE-ENFORCE LE-5: server-enforced entitlement gate. This proxy had none
// (see the "no org/license gating either" note above — accurate when
// written, no longer the intent once 'quoxsignal' is governed). Health is
// gated too, same reasoning as the QLarity/RepoBrain proxies in this file: an
// ungated health probe is a free existence oracle and the route everyone
// forgets to gate. Mirrors the QLarity proxy's shape exactly.
app.all('/api/v1/signal/*', requireServiceOrUserAuth(), async (req, res) => {
  // The QuoxSignal server mounts its health probe at bare /health (not under
  // /api/v1 like its data routes) — special-cased so the client's health
  // poll doesn't 404 through the generic /api/v1/signal -> /api/v1 rewrite
  // below. Mirrors the QuoxPlan proxy's own isHealthCheck special-case.
  const isHealthCheck = req.method === 'GET' && req.path.endsWith('/signal/health');
  // Defense in depth: refuse traversal segments before building the target
  // path, same as the QuoxPlan proxy.
  if (/(^|[\\/])\.\.([\\/]|$)/.test(decodeURIComponent(req.path))) {
    return res.status(400).json({ error: 'invalid path' });
  }

  const callerOrgId = resolveCallerOrgId(req);
  if (!callerOrgId) {
    return res.status(401).json({ error: 'Organisation context required for QuoxSignal' });
  }
  let signalLicensed = false;
  try {
    signalLicensed = await isPluginLicensedForOrg(callerOrgId, 'quoxsignal');
  } catch (e) {
    signalLicensed = false; // fail closed
  }
  if (!signalLicensed) {
    return res.status(403).json({ error: 'QuoxSignal is not licensed for this organisation' });
  }

  const targetPath = isHealthCheck
    ? '/health'
    : req.originalUrl.replace('/collector/api/v1/signal', '/api/v1').replace('/api/v1/signal', '/api/v1');
  // F07 fix: never forward a caller-supplied org_id upstream — force it to
  // the verified callerOrgId that was just license-checked above. Upstream
  // quox-signal's orgIdOf(req) trusts req.query.org_id || req.body.org_id,
  // so without this a licensed caller for org A could pass org_id=orgB on
  // the query string and read/write org B's data.
  const scopedTargetPath = isHealthCheck
    ? targetPath
    : scopeSignalTargetToOrg(targetPath, callerOrgId);
  const targetUrl = `${QUOXSIGNAL_URL}${scopedTargetPath}`;

  try {
    const fetchOpts = {
      method: req.method,
      headers: {
        'Accept': 'application/json',
        'Content-Type': req.headers['content-type'] || 'application/json',
      },
      signal: AbortSignal.timeout(30000),
    };

    if (['POST', 'PUT', 'PATCH', 'DELETE'].includes(req.method) && req.body && Object.keys(req.body).length > 0) {
      fetchOpts.body = JSON.stringify(scopeSignalBodyToOrg(req.body, callerOrgId));
    }

    const resp = await fetch(targetUrl, fetchOpts);
    const contentType = resp.headers.get('content-type') || '';
    const isJson = contentType.includes('json');
    /* BINARY responses must not go through resp.text(). Item thumbnails and source
     * avatars are served as image/jpeg, and decoding those bytes as UTF-8 corrupted
     * them and then handed Express a string, which it sent as text/html. The browser
     * refused to render it, the <img> onError fired, and every thumbnail in the feed
     * fell back to its placeholder while the images existed and were fine upstream.
     * A 200 was being returned throughout, so nothing looked broken from the server
     * side. Read binary as a Buffer and forward the upstream content-type verbatim. */
    const isBinary = !isJson && !contentType.startsWith('text/') && contentType !== '';
    // Parse the body once, here — both the AEE/evidence block below and the
    // response write need it, and a fetch Response body can only be read once.
    const data = isJson
      ? await resp.json()
      : isBinary
        ? Buffer.from(await resp.arrayBuffer())
        : await resp.text();

    // SIGNAL-EMBED: evidence layer — a SUCCESSFUL (2xx) mutating request gets
    // an AEE envelope at this governed boundary. Fire-and-forget, never
    // blocks or fails the proxied response.
    if (!isHealthCheck && resp.status >= 200 && resp.status < 300
      && ['PATCH', 'POST', 'PUT', 'DELETE'].includes(req.method)) {
      const relPath = targetPath.replace(/^\/api\/v1/, '').split('?')[0];
      const mapped = resolveSignalAeeIntent(req.method, relPath);
      if (mapped) {
        const isEvidenceIntent = mapped.intent === 'signal.proposal.created' || mapped.intent === 'signal.proposal.handed_off';
        const proposalId = isEvidenceIntent ? (mapped.ids.proposal_id || data?.id || null) : null;
        // SIGNAL-P4: proposal creation and handoff are the two points where
        // a roadmap-bound claim is born from evidence — only these use a
        // deterministic corr (see proposalEvidenceCorr) so the frontend can
        // rediscover the same evidence thread on a later, fresh page load
        // purely from the proposal id, without any extra field on the
        // proxied response body.
        const corrOverride = isEvidenceIntent && proposalId ? proposalEvidenceCorr(proposalId) : undefined;
        const corr = emitSignalAEE(req, callerOrgId, mapped, corrOverride);
        // Fire-and-forget, not awaited: runs after the response below has
        // already gone out.
        if (isJson && data && isEvidenceIntent && proposalId) {
          const itemId = data.item_id || null;
          persistSignalEvidenceBundle(callerOrgId, corr, proposalId, itemId, data);
        }
      }
    }

    res.status(resp.status);

    if (isJson) {
      res.json(data);
    } else {
      /* Forward the upstream content-type verbatim. Without this Express infers one from
         the payload, which turned image/jpeg into text/html and broke every thumbnail. */
      if (contentType) res.type(contentType);
      // Cache headers are the whole point of the thumbnail route (it sets an ETag off the
      // content hash so a client revalidates instead of refetching); dropping them here
      // would silently undo that.
      for (const h of ['cache-control', 'etag', 'last-modified']) {
        const v = resp.headers.get(h);
        if (v) res.set(h, v);
      }
      res.send(data);
    }
  } catch (err) {
    if (err.name === 'TimeoutError' || err.name === 'AbortError') {
      return res.status(504).json({ error: 'QuoxSignal request timed out' });
    }
    if (err.cause?.code !== 'ECONNREFUSED') {
      console.error('[QuoxSignal proxy]', err.message);
    }
    // No err.message to the client: it can carry internal topology
    // (host.docker.internal:3108) on connection failures.
    res.status(502).json({ error: 'QuoxSignal service unavailable' });
  }
});

// QUOXPLAN-P5: division/department scope options for the QuoxPlan scope
// selector. Thin passthrough to the auth service's own org-scopes list
// (services/auth/routes/scopes.js GET /orgs/:orgId/scopes), called with the
// CALLER's own auth context (Authorization/cookie forwarded), not a service
// key — this is a per-user read exactly like the /api/v1/actions proxies
// above, not an internal service-to-service call. Degrades to an empty list
// (never an error) when the caller has no org context or the org has no
// scopes configured yet, so the UI can hide the selector cleanly.
app.get('/api/v1/quoxplan-meta/scopes', requireServiceOrUserAuth(), requirePluginEntitlement('quoxplan'), async (req, res) => {
  const orgId = resolveCallerOrgId(req);
  if (!orgId) return res.json({ scopes: [] });

  try {
    const headers = { 'Content-Type': 'application/json' };
    if (req.headers.authorization) headers['Authorization'] = req.headers.authorization;
    else if (req.headers.cookie) headers['Cookie'] = req.headers.cookie;

    const authRes = await fetch(`${AUTH_SERVICE_URL}/api/orgs/${orgId}/scopes?flat=true`, {
      headers,
      signal: AbortSignal.timeout(5000),
    });
    if (!authRes.ok) {
      // Org has no membership record, no scopes table rows, or auth 404s —
      // all degrade to "no scopes" rather than surfacing an auth-service
      // error into the QuoxPlan UI.
      return res.json({ scopes: [] });
    }
    const data = await authRes.json();
    res.json({ scopes: data.scopes || [] });
  } catch (err) {
    console.error('[QuoxPlan scopes proxy]', err.message);
    res.json({ scopes: [] });
  }
});

// QUOXPLAN-HITLFIX: best-effort, idempotent auth-inbox card resolution for
// the decide handler below. The normal path (auth's POST .../respond) already
// marks the card resolved before it ever calls this decide endpoint, so this
// is a no-op there — it only matters if decide is ever called directly
// (bypassing /respond), in which case the card would otherwise stay 'open'
// forever even though the stream itself completed. Never throws — logs and
// swallows errors so it can never affect the decide response.
async function resolveQuoxplanInboxCard({ inboxItemId, orgId, action, approver, reason }) {
  if (!inboxItemId || !orgId) return;
  try {
    // P0b 6b: auth's /resolve no longer trusts a body-supplied approver; the
    // ORIGINAL decision-maker travels as x-actor-type/x-actor-id. The decide
    // callback only ever fires off a human decision relayed by the auth
    // service's /respond flow (or a keyed operator call), so the actor type
    // here is 'human'. An agent-driven resolve must not come through this
    // relay at all — agents propose, and auth 403s an agent actor at the
    // sink except under a leased disposable sandbox.
    const resp = await fetch(`${AUTH_SERVICE_URL}/api/internal/orgs/${encodeURIComponent(orgId)}/inbox/${encodeURIComponent(inboxItemId)}/resolve`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-service-key': process.env.INTERNAL_SERVICE_KEY || '',
        'x-actor-type': 'human',
        'x-actor-id': approver || 'owner',
      },
      body: JSON.stringify({ action, reason }),
      signal: AbortSignal.timeout(10000),
    });
    if (!resp.ok) {
      const text = await resp.text().catch(() => '');
      console.error(`[QuoxPlan HITL] Inbox card resolve failed (${resp.status}): ${text.slice(0, 200)}`);
    }
  } catch (err) {
    console.error('[QuoxPlan HITL] Inbox card resolve error:', err.message);
  }
}

// P7 CONTINUITY: recall for the tasks dispatcher (mandatory pre-start stage
// for resident-agent loops). Service-to-service only.
app.get('/api/internal/continuity/recall', requireServiceOrUserAuth(), (req, res) => {
  if (!req.service) {
    return res.status(403).json({ error: 'internal service auth required' });
  }
  try {
    const selfLog = require('./lib/selfLogStore.js');
    const db = selfLog.getDatabase();
    if (!db) return res.status(503).json({ error: 'continuity store not initialised' });
    const orgId = req.query.org_id;
    const agentId = String(req.query.agent_id || '').trim().toLowerCase();
    if (!orgId || !agentId) return res.status(400).json({ error: 'org_id and agent_id are required' });
    return res.json(selfLog.recall(db, { orgId, agentId }));
  } catch (err) {
    return res.status(500).json({ error: err.message });
  }
});

// P7 CONTINUITY: system-authored fallback commit (the loop consumer calls
// this when a resident loop ends without the agent having committed, so the
// chain never gaps). Service-to-service only.
app.post('/api/internal/continuity/commit', requireServiceOrUserAuth(), (req, res) => {
  if (!req.service) {
    return res.status(403).json({ error: 'internal service auth required' });
  }
  try {
    const selfLog = require('./lib/selfLogStore.js');
    const db = selfLog.getDatabase();
    if (!db) return res.status(503).json({ error: 'continuity store not initialised' });
    const { org_id, agent_id, delta_md, open_loops, message_to_next, objective_id } = req.body || {};
    const entry = selfLog.appendSelfDelta(db, {
      orgId: org_id,
      agentId: String(agent_id || '').trim().toLowerCase(),
      deltaMd: delta_md,
      openLoops: open_loops,
      messageToNext: message_to_next ?? null,
      objectiveId: objective_id ?? null,
    });
    return res.status(201).json(entry);
  } catch (err) {
    return res.status(400).json({ error: err.message });
  }
});

// POST /api/internal/quoxplan/approvals/decide — Service-to-service callback
// from HITL Inbox. Called when the owner approves or denies a QuoxPlan stream
// completion request queued by the quoxplan_request_complete tool
// (lib/quoxplanTools.js). Mirrors the Wazuh HITL decide handler's shape
// verbatim (server.js /api/internal/wazuh/approvals/decide, ~:7825): audit
// the decision unconditionally, short-circuit on deny, execute the deferred
// action (here: PATCH the stream to COMPLETE) on approve.
app.post('/api/internal/quoxplan/approvals/decide', requireServiceOrUserAuth(), async (req, res) => {
  // Must be called from an internal service (inbox service key), not a user JWT
  if (!req.service) {
    return res.status(401).json({ error: 'This endpoint requires internal service authentication' });
  }

  const { inbox_item_id, action, approver, reason, action_params } = req.body;

  if (!action || !['approve', 'deny'].includes(action)) {
    return res.status(400).json({ error: 'action must be "approve" or "deny"' });
  }
  if (!action_params || !action_params.stream_id) {
    return res.status(400).json({ error: 'action_params.stream_id is required' });
  }

  const { stream_id } = action_params;
  const orgId = action_params.org_id || null;
  const corrId = `QUOXPLAN_COMPLETE_${Date.now()}`;

  console.log(`[QuoxPlan HITL] Decide: inbox=${inbox_item_id} action=${action} stream=${stream_id} approver=${approver}`);

  // Emit AEE: decision recorded (both approve and deny land here — matches
  // the Wazuh precedent's unconditional decision envelope).
  storeAuditEnvelope({
    type: 'event',
    from: approver ? `human.${approver}` : 'system.inbox',
    to: 'agent.roady',
    intent: action === 'approve' ? 'quoxplan.stream.complete.approved' : 'quoxplan.stream.complete.denied',
    corr: corrId,
    org_id: orgId,
    payload: { stream_id, inbox_item_id, approver, reason: reason || action_params.reason, org_id: orgId },
  });

  if (action === 'deny') {
    resolveQuoxplanInboxCard({ inboxItemId: inbox_item_id, orgId, action: 'denied', approver, reason });
    return res.json({ denied: true, inbox_item_id, stream_id });
  }

  // Approved — issue the owner-gated completion PATCH against the QuoxPlan
  // server directly (same URL the proxy above targets), then store the
  // quoxplan.stream.completed evidence envelope.
  try {
    const actor = `hitl:${approver || 'owner'}`;
    const resp = await fetch(`${QUOXPLAN_URL}/api/v1/streams/${encodeURIComponent(stream_id)}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ status: 'COMPLETE', confirm_owner: true, actor }),
      signal: AbortSignal.timeout(10000),
    });
    let data = null;
    try { data = await resp.json(); } catch { /* body may be empty/non-JSON */ }

    if (!resp.ok) {
      storeAuditEnvelope({
        type: 'error',
        from: 'system.collector',
        to: 'agent.roady',
        intent: 'quoxplan.stream.complete.failed',
        corr: corrId,
        org_id: orgId,
        payload: { stream_id, status: resp.status, detail: data && data.error, org_id: orgId },
      });
      return res.status(502).json({ error: 'QuoxPlan server rejected completion', detail: data && data.error });
    }

    storeAuditEnvelope({
      type: 'event',
      from: 'system.collector',
      to: 'agent.roady',
      intent: 'quoxplan.stream.completed',
      corr: corrId,
      org_id: orgId,
      payload: {
        stream_id,
        roadmap_id: data && data.stream ? data.stream.roadmap_id : undefined,
        approver,
        org_id: orgId,
      },
    });

    resolveQuoxplanInboxCard({ inboxItemId: inbox_item_id, orgId, action: 'approved', approver, reason });
    return res.json({ executed: true, stream_id, status: 'COMPLETE' });
  } catch (err) {
    console.error('[QuoxPlan HITL] Deferred completion failed:', err.message);
    storeAuditEnvelope({
      type: 'error',
      from: 'system.collector',
      to: 'agent.roady',
      intent: 'quoxplan.stream.complete.failed',
      corr: corrId,
      org_id: orgId,
      payload: { stream_id, error: err.message, org_id: orgId },
    });
    return res.status(500).json({ error: err.message });
  }
});

// POST /api/internal/x/approvals/decide — Service-to-service callback from
// HITL Inbox. Called when the owner approves or discards an x_post/x_thread/
// x_delete request filed by lib/xTools.js. Same shape as the Wazuh/QuoxPlan
// decide handlers above (service-auth only, AEE decision envelope
// unconditionally, deny short-circuits, approve executes), but the actual
// logic lives in lib/xTools.js's handleApprovalDecide (unit-testable without
// the full collector app — see that function's doc comment for why).
app.post('/api/internal/x/approvals/decide', requireServiceOrUserAuth(), async (req, res) => {
  if (!req.service) {
    return res.status(401).json({ error: 'This endpoint requires internal service authentication' });
  }
  const xTools = require('./lib/xTools.js');
  const { status, body } = await xTools.handleApprovalDecide(req.body, { emitEnvelope: storeAuditEnvelope });
  return res.status(status).json(body);
});

