// Brain2 P4-WP1 — embedding seam (STREAM_QUOXBRAIN2_OVERNIGHT_BUILD.md
// Phase F). Thin service-key-only wrapper around quoxchat's embedText()
// so quoxbrain (and any other internal caller) can batch-embed text
// without duplicating the Gemini/OpenAI provider logic. Handler logic
// lives in lib/internalEmbedHandler.js (dependency-injected, unit-tested);
// this just wires auth + the real embedText/getProviderKeys deps.
// getProviderKeys is org-scoped via resolveRequestOrgId(req) — without it,
// org-scoped BYOK keys could never resolve for internal embed callers and
// only instance-wide/legacy keys would ever be found.
const { createEmbedHandler, createEmbedProviderHandler } = require('./lib/internalEmbedHandler');
app.post('/internal/embed', internalModelLimiter, requireServiceOrUserAuth(), createEmbedHandler({
  embedText: quoxchatRoutes.embedText,
  getProviderKeys: (req) => getProviderKeys(resolveRequestOrgId(req)),
  // VAULT-INTEG P17: org-scopes embedText()'s QUOXCHAT_EMBED_PROVIDER
  // resolution so a stored per-org override reaches this internal call
  // path too, not just the widget message/knowledge routes.
  getOrgId: (req) => resolveRequestOrgId(req),
}));
// BRAIN2-W11 B: opt-in LLM reranker seam (service-key only). Reuses the
// governed /chat/complete path over loopback so the org's provider policy,
// keys, failover and audit envelope apply. quoxbrain gates it per org.
const { createRerankHandler } = require('./lib/internalRerankHandler');
const { createOpenAIRerankComplete } = require('./lib/rerankCompletion');
// BRAIN2-W12 D: direct small-model call (OpenAI chat completions with the org's key), NOT the
// agent endpoint /chat/complete (agent prompt + pipeline, 8 s median). No key = 502
