app.get('/internal/embed/provider', requireServiceOrUserAuth(), createEmbedProviderHandler({
  getProviderKeys: (req) => getProviderKeys(resolveRequestOrgId(req)),
  getOrgId: (req) => resolveRequestOrgId(req),
}));

