// ═══════════════════════════════════════════════════════════════════
// BRAIN2-CORTEX P1a — GET /api/brain/citations/:sessionId: per-turn honest
// citation status (hits/empty/unavailable) + structured citations for a
// future dock UI, reusing the existing registerRetrieval/finalizeAnswer
// tracing in lib/brainCitationTrace.js. Same auth posture as the overview
// route directly above (requireServiceOrUserAuth() IS the gate). Prefers the
// finalized record; falls back to the pre-finalize live entry (the race
// fix — a caller may poll before finalizeAnswer has run for this turn).
// Cross-org: 404 (never 403) on mismatch, so the response never confirms
// another org's session exists — same org accessor as
// /api/v1/platform/settings/flags above (req.user?.org_id, or the caller's
// own X-Org-Id header for a trusted service-key caller).
app.get('/api/brain/citations/:sessionId', requireServiceOrUserAuth(), (req, res) => {
  try {
    const key = req.params.sessionId;
    const callerOrg = req.user?.org_id || (req.service ? req.headers['x-org-id'] : undefined);

    // BRAIN2-W3 B (112): scope every read to the caller's org AND user. A
    // user caller sees only their own turn; a service-key caller must name
    // the org (x-org-id) and may read any user in it. No org => nothing.
    const scope = callerScope({ user: req.user, service: req.service, headerOrgId: req.headers['x-org-id'] });
    if (!scope) return res.status(404).json({ status: 'not_searched' });

    // BRAIN2-W5 114: the newer turn wins (a live entry registered after the
    // previous finalize is the current turn; never serve the old evidence).
    const picked = pickBrainCitationRecord(getBrainCitationFinalized(key, scope), getBrainCitationLive(key, scope));
    if (picked && picked.kind === 'finalized') {
      const fin = picked.record;
      if (fin.orgId && callerOrg && fin.orgId !== callerOrg) return res.status(404).json({ status: 'not_searched' });
      return res.json({ ...fin, finalized: true });
    }

    const live = picked && picked.record;
    if (live) {
      if (live.orgId && callerOrg && live.orgId !== callerOrg) return res.status(404).json({ status: 'not_searched' });
      return res.json({
        corr: key,
        status: live.status,
        reason: live.reason,
        retrieved: (live.refs || []).length,
        cited: 0,
        rate: 0,
        citations: (live.refs || []).map((r) => ({
          noteId: r.noteId, title: r.title, relPath: r.relPath, snippet: r.snippet, score: r.score, index: null, cited: false,
        })),
        finalized: false,
      });
    }

    return res.status(404).json({ status: 'not_searched' });
  } catch (e) {
    return res.status(500).json({ error: String(e?.message || e) });
  }
});

// ═══════════════════════════════════════════════════════════════════
// GET /api/brain/activity — collector-side proxy to quoxbrain's real
// GET /brain/activity (recent autonomic activity feed for the BRAIN2
// visualiser). Same org-resolution + service-key forwarding pattern as
// lib/toolExecutors/quoxbrain.js's BRAIN_URL/SERVICE_KEY calls and the
// /api/brain/citations/:sessionId route directly above (requireServiceOrUserAuth()
// IS the gate; caller org resolved the same way, never trusted from a body).
// The collector never invents brain data itself — on any non-2xx or network
// failure this still returns 200 with honestly-zeroed sections (+ `error`)
// so a polling visualiser never breaks on a transient quoxbrain hiccup.
const BRAIN_ACTIVITY_URL = `http://${process.env.QUOXBRAIN_HOST || 'quoxbrain'}:${process.env.QUOXBRAIN_PORT || '3106'}`;
app.get('/api/brain/activity', requireServiceOrUserAuth(), async (req, res) => {
  const callerOrg = req.user?.org_id || (req.service ? req.headers['x-org-id'] : undefined);
  const zeroed = (extra = {}) => ({
    ingest: { count: 0, noteIds: [] },
    dream: { active: false, lastRunAt: null, notesReadRecent: 0, recentRuns: [] },
    embedding: { recentlyEmbeddedChunks: 0, note: 'recency proxy from chunk_embeddings.updated_at, not a run event' },
    ...extra,
  });

  if (!callerOrg) {
    return res.status(200).json(zeroed({ error: 'no organization resolved for caller' }));
  }

  try {
    const windowParam = req.query.window ? `?window=${encodeURIComponent(req.query.window)}` : '';
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 8000);
    let brainRes;
    try {
      brainRes = await fetch(`${BRAIN_ACTIVITY_URL}/brain/activity${windowParam}`, {
        headers: {
          'X-Service-Key': process.env.INTERNAL_SERVICE_KEY || '',
          'X-Org-Id': callerOrg,
          ...(req.user?.id ? { 'X-User-Id': req.user.id } : {}),
        },
        signal: controller.signal,
      });
    } finally {
      clearTimeout(timer);
    }

    if (!brainRes.ok) {
      return res.status(200).json(zeroed({ error: `quoxbrain returned ${brainRes.status}` }));
    }
    const data = await brainRes.json();
    return res.status(200).json(data);
  } catch (e) {
    return res.status(200).json(zeroed({ error: String(e?.message || e) }));
  }
});

// Create HTTP server
const server = http.createServer(app);

// Disable Node's default 300s requestTimeout — policy-driven timeouts handle this
// Without this, long-running internal invoke calls (CEO delegating to 9 agents) get killed
server.requestTimeout = 0;

// WebSocket servers — using noServer mode with manual upgrade routing
// (multiple WebSocketServer instances on the same HTTP server with `path`
//  can destroy sockets before other handlers get a chance to match)
const wss = new WebSocketServer({ noServer: true });

wss.on('connection', (ws, req) => {
  const clientId = Math.random().toString(36).slice(2, 8);
  const clientIp = req.socket.remoteAddress;

  // Security fix for issue #65: Authenticate WebSocket connections
  const authResult = authenticateWebSocket(req);

  if (!authResult.authenticated) {
    console.warn(`[${new Date().toISOString()}] [${clientId}] WebSocket auth REJECTED from ${clientIp}: ${authResult.error}`);

    // Send error message before closing
    try {
      ws.send(JSON.stringify({
        type: 'error',
        error: 'authentication_failed',
        message: authResult.error
      }));
    } catch (e) {
      // Ignore send errors during rejection
    }

    // Close with 4001 (unauthorized) code
    ws.close(4001, authResult.error);
    return;
  }

  // Store auth info on socket
  ws.user = authResult.user;
  ws.clientId = clientId;
  ws.authenticatedAt = Date.now();

  const userInfo = authResult.user ? ` (user: ${authResult.user.id})` : ' (dev-mode)';
  console.log(`[${new Date().toISOString()}] [${clientId}] WebSocket authenticated from ${clientIp}${userInfo}`);

  wsClients.add(ws);

  // Send current state to new client
  const agentList = [];
  for (const [, agent] of agents) {
    agentList.push(agent);
  }
  const initMsg = JSON.stringify({
    type: 'init',
    agents: agentList
  });
  console.log(`[${new Date().toISOString()}] [${clientId}] Sending init (${initMsg.length} bytes)`);
  ws.send(initMsg);
  console.log(`[${new Date().toISOString()}] [${clientId}] Init sent successfully`);

  ws.on('close', (code, reason) => {
    wsClients.delete(ws);
    console.log(`[${new Date().toISOString()}] [${clientId}] WebSocket closed - code: ${code}, reason: ${reason || 'none'}`);
  });

  ws.on('error', (err) => {
    console.error(`[${new Date().toISOString()}] [${clientId}] WebSocket error:`, err.message);
    wsClients.delete(ws);
  });
});

// ============================================================================
// Terminal WebSocket Endpoint — /terminal/ws
// Spawns a PTY shell for browser-based terminal access (Phase 1: auth via CLI)
// ============================================================================

// CLI credential file path — created by `claude /login` via web terminal
const RUNTIME_HOME_DIR = resolveRuntimeHomeDir();
const RUNTIME_USER = resolveRuntimeUser(RUNTIME_HOME_DIR);
// D2: where spawned Claude CLIs (HOME = RUNTIME_HOME_DIR) write session files, so GDPR
// purge and the TTL prune can delete the ones an org / user owns.
require('./lib/chatSessionHistory.js').setCliProjectsDir(path.join(RUNTIME_HOME_DIR, '.claude', 'projects'));
const CLI_CREDS_PATH = path.join(RUNTIME_HOME_DIR, '.claude', '.credentials.json');

// DEVSUITE-DEVMODE 5c: codex is the second loop backend and gets the same
// Settings web-terminal auth treatment as Claude (owner decision 2026-08-11:
// "treat them the same and support both"). Its device-auth flow
// (`codex login --device-auth`, verified codex-cli 0.118.0) prints a URL +
// one-time code — no localhost callback, so it works from the web terminal
// on a headless deployment.
const CODEX_AUTH_PATH = path.join(RUNTIME_HOME_DIR, '.codex', 'auth.json');

// The ONLY commands /terminal/ws will ever spawn, keyed by the ?app= query
// value. A strict allowlist — the client picks a key, never a command.
// (Extracted to lib/terminalApps.cjs so tests exercise the real module.)
const { resolveTerminalApp } = require('./lib/terminalApps.cjs');

let _codexCliCache = { result: null, checkedAt: 0 };
const CODEX_CLI_CACHE_MS = 120000;

/** Is the codex CLI installed in this runtime, and is it authenticated? */
async function getCodexCliStatus() {
  const now = Date.now();
  if (_codexCliCache.result && now - _codexCliCache.checkedAt < CODEX_CLI_CACHE_MS) {
    return { ..._codexCliCache.result, authenticated: fs.existsSync(CODEX_AUTH_PATH) };
  }
  const { execFile } = require('child_process');
  const installed = await new Promise((resolve) => {
    execFile('codex', ['--version'], { timeout: 5000, env: { ...process.env, HOME: RUNTIME_HOME_DIR } }, (err) => resolve(!err));
  });
  _codexCliCache = { result: { installed }, checkedAt: now };
  return { installed, authenticated: fs.existsSync(CODEX_AUTH_PATH) };
}

function validateQuoxCliRuntime(cliPath) {
  const cliRoot = path.dirname(path.dirname(cliPath));
  const packagePath = path.join(cliRoot, 'package.json');
  if (!fs.existsSync(packagePath)) {
    return { cliRoot, validationError: 'package.json missing' };
  }

  try {
    const pkg = JSON.parse(fs.readFileSync(packagePath, 'utf8'));
    for (const dependency of Object.keys(pkg.dependencies || {})) {
      try {
        require.resolve(dependency, { paths: [cliRoot] });
      } catch (err) {
        // ERR_PACKAGE_PATH_NOT_EXPORTED means the package IS installed but its
        // `exports` map doesn't expose a bare-specifier CJS entry — common for
        // ESM-only deps like `fullscreen-ink` (the CLI reaches them via dynamic
        // import(), not require). That is NOT a missing dependency. Only treat
        // it as missing when the package directory truly isn't on disk.
        if (err && err.code === 'ERR_PACKAGE_PATH_NOT_EXPORTED') continue;
        if (fs.existsSync(path.join(cliRoot, 'node_modules', dependency, 'package.json'))) continue;
        return { cliRoot, missingDependency: dependency };
      }
    }
    return { cliRoot };
  } catch (err) {
    return { cliRoot, validationError: err.message };
  }
}

function hasCliCredentials() {
  return fs.existsSync(CLI_CREDS_PATH);
}

/**
 * Check if CLI OAuth token is actually valid (not just file exists).
 * Returns { valid, reason, expiresIn } for diagnostics.
 */
function validateCliCredentials() {
  if (!hasCliCredentials()) {
    return { valid: false, reason: 'no_file' };
  }
  try {
    const creds = JSON.parse(fs.readFileSync(CLI_CREDS_PATH, 'utf8'));
    const oauth = creds.claudeAiOauth;
    if (!oauth?.accessToken) {
      return { valid: false, reason: 'no_token' };
    }
    if (oauth.expiresAt && oauth.expiresAt <= Date.now()) {
      return { valid: false, reason: 'expired', expiredAgo: Math.round((Date.now() - oauth.expiresAt) / 60000), hasRefreshToken: !!oauth.refreshToken };
    }
    const expiresIn = oauth.expiresAt ? Math.round((oauth.expiresAt - Date.now()) / 60000) : null;
    return { valid: true, expiresIn };
  } catch (e) {
    return { valid: false, reason: 'parse_error', detail: e.message };
  }
}

/** Deps for lib/cliHopShape.js (the /chat auth resolution and the hint-time dry run of a delegate hop). Late-bound. */
function hopWarmDeps() {
  return {
    getProviderKeys,
    getClaudeKeys,
    resolveCliOAuthToken,
    resolveCollectorPolicyPlan,
    applyOllamaSelection: require('./lib/ollamaProvider.js').applyOllamaSelection,
    isNativeWebSearch: require('./lib/nativeWebSearch.js').isNativeWebSearch,
    aliasAgentId,
    runtimeHomeDir: RUNTIME_HOME_DIR,
    runtimeUser: RUNTIME_USER,
    collectorPort: process.env.COLLECTOR_PORT || 9848,
  };
}

/**
 * Resolve the Claude CLI / OAuth subscription token — same precedence used by
 * both chat entry points: vault/instance_config `claude_oauth_token` first,
 * then the CLI's own ~/.claude/.credentials.json (with expiry/refresh checks).
 *
 * GAP-1 (collector chat-stream OAuth parity): extracted from
 * handleCollectorChat so /chat/stream can reuse the EXACT same resolution
 * instead of gating solely on anthropic_api_key.
 */
function resolveCliOAuthToken(claudeKeys) {
  let cliOAuthToken = claudeKeys?.claude_oauth_token || '';
  if (cliOAuthToken) {
    console.log('[Claude] Using OAuth token from vault/instance_config');
    return cliOAuthToken;
  }
  if (hasCliCredentials()) {
    try {
      const creds = JSON.parse(fs.readFileSync(CLI_CREDS_PATH, 'utf8'));
      const oauth = creds.claudeAiOauth;
      if (oauth?.accessToken && oauth.expiresAt > Date.now()) {
        cliOAuthToken = oauth.accessToken;
        console.log('[Claude] Using OAuth token from CLI credentials file');
      } else if (oauth?.accessToken && oauth?.refreshToken) {
        // Token expired but refresh token exists — CLI handles refresh internally
        cliOAuthToken = oauth.accessToken;
        console.log('[Claude] CLI OAuth token expired but refresh token available — CLI will auto-refresh');
      } else if (oauth?.accessToken) {
        console.warn('[Claude] CLI OAuth token expired with no refresh token');
      }
    } catch (e) {
      console.warn('[Claude] Failed to read CLI credentials:', e.message);
    }
  }
  return cliOAuthToken;
}

/**
 * Cached CLI refresh probe — tests if expired token can actually refresh.
 * Caches result for 2 min to avoid hammering the CLI on every /chat/status poll.
 */
let _cliRefreshCache = { result: null, checkedAt: 0 };
const CLI_REFRESH_CACHE_MS = 120000; // 2 min
const CLI_HEALTH_CACHE_MS = 60000; // 1 min

// QUOXON-PARITY: retry a transient probe failure once; cache a failure for seconds, not a minute (lib/claudeCliHealth.js).
const _claudeCliHealth = require('./lib/claudeCliHealth.js').createClaudeCliHealth({
  execFile,
  env: () => ({ ...process.env, HOME: RUNTIME_HOME_DIR, USER: RUNTIME_USER }),
});
async function getClaudeCliHealth({ timeoutMs = 15000, cacheMs = CLI_HEALTH_CACHE_MS, force = false } = {}) {
  const r = await _claudeCliHealth.get({ timeoutMs, cacheMs, force });
  global._cliHealthCache = r;
  return r;
}

async function getTerminalCapabilityStatus() {
  const nodePty = getNodePty();
  if (!nodePty) {
    return buildTerminalCapabilityStatus({
      ptyAvailable: false,
      ptyError: _nodePtyLoadError?.message || null,
    });
  }

  const cliHealth = await getClaudeCliHealth({ timeoutMs: 5000, cacheMs: 120000 });
  return buildTerminalCapabilityStatus({
    ptyAvailable: true,
    cliHealth,
  });
}

function getQuoxCliCapabilityStatus() {
  const nodePty = getNodePty();
  if (!nodePty) {
    return buildQuoxCliCapabilityStatus({
      ptyAvailable: false,
      ptyError: _nodePtyLoadError?.message || null,
    });
  }

  const cliPath = resolveQuoxCliEntryPath();
  if (!cliPath) {
    return buildQuoxCliCapabilityStatus({
      ptyAvailable: true,
      cliPath: null,
    });
  }

  const { missingDependency, validationError } = validateQuoxCliRuntime(cliPath);
  return buildQuoxCliCapabilityStatus({
    ptyAvailable: true,
    cliPath,
    validationError: validationError || null,
    missingDependency: missingDependency || null,
  });
}

async function checkCliRefreshable() {
  const now = Date.now();
  if (now - _cliRefreshCache.checkedAt < CLI_REFRESH_CACHE_MS) {
    return _cliRefreshCache.result;
  }
  try {
    const { execFile } = require('child_process');
    const cliEnv = { ...process.env, HOME: RUNTIME_HOME_DIR, USER: RUNTIME_USER };
    const ok = await new Promise((resolve) => {
      execFile('claude', ['-p', 'say OK'], { encoding: 'utf8', timeout: 15000, env: cliEnv }, (err, stdout) => {
        resolve(!err && stdout.trim().length > 0);
      });
    });
    _cliRefreshCache = { result: ok, checkedAt: now };
    return ok;
  } catch {
    _cliRefreshCache = { result: false, checkedAt: now };
    return false;
  }
}

const MAX_TERMINAL_SESSIONS = 3;
const terminalSessions = new Map();
const terminalWss = new WebSocketServer({ noServer: true });

// Shell WebSocket — real shell (bash/SSH) for premium Web Terminal plugin
const crypto = require('crypto');
const RingBuffer = require('./lib/RingBuffer');

const MAX_SHELL_SESSIONS = 5;
const shellSessions = new Map();      // sessionId → active session
const detachedSessions = new Map();   // sessionId → detached session (PTY alive, no WS)
const shellWss = new WebSocketServer({ noServer: true });
const ALLOWED_SHELL_MODES = ['local', 'ssh'];
const HOST_ID_PATTERN = /^[a-zA-Z0-9][a-zA-Z0-9._-]{0,62}$/;

const DETACH_GRACE_PERIOD_MS = 30 * 60 * 1000;  // 30 min before killing orphaned PTY
const DETACH_BUFFER_CAPACITY = 102400;            // 100KB ring buffer for scrollback replay
const SESSION_CLEANUP_INTERVAL_MS = 30 * 1000;   // Check for expired detached sessions

// Observer limits
const MAX_OBSERVERS_PER_SESSION = 5;
const MAX_OBSERVERS_PER_USER = 10;
const observerWss = new WebSocketServer({ noServer: true });
const quoxCliWss = new WebSocketServer({ noServer: true });

// CLI-2d: Unified event stream WebSocket server
const eventStreamWss = new WebSocketServer({ noServer: true });
eventStreamWss.on('connection', (ws, req) => {
  const url = new URL(req.url, 'http://localhost');
  const layersParam = url.searchParams.get('layers');
  const entityParam = url.searchParams.get('entity');

  const filters = {};
  if (layersParam) filters.layers = layersParam.split(',').map(s => s.trim());
  if (entityParam) filters.entity = entityParam.trim();

  eventStreamHub.addClient(ws, filters);

  ws.on('close', () => eventStreamHub.removeClient(ws));
  ws.on('error', () => eventStreamHub.removeClient(ws));

  // Send welcome message with current stats
  try {
    ws.send(JSON.stringify({
      type: 'connected',
      filters,
      stats: eventStreamHub.stats(),
    }));
  } catch { /* ignore */ }
});

// ── Output redaction patterns for observer streams ──────────────────────
// Denylist approach: scrub known secret formats before broadcasting.
// Owner stream is NEVER filtered — only observer broadcasts.
const REDACTION_PATTERNS = [
  { pattern: /sk-ant-[a-zA-Z0-9_-]{20,}/g, label: 'anthropic_key' },
  { pattern: /sk-[a-zA-Z0-9_-]{40,}/g, label: 'openai_key' },
  { pattern: /Bearer\s+[a-zA-Z0-9._-]{20,}/g, label: 'bearer_token' },
  { pattern: /Authorization:\s*Bearer\s+[^\s'"]+/gi, label: 'auth_header' },
  { pattern: /(?:password|passwd|pwd)\s*[=:]\s*[^\s;'"]+/gi, label: 'password' },
  { pattern: /(?:secret|token|api[_-]?key)\s*[=:]\s*[^\s;'"]+/gi, label: 'secret_assignment' },
  { pattern: /(?:postgres|mysql|mongodb|redis):\/\/[^\s'"]+/gi, label: 'connection_string' },
  { pattern: /-----BEGIN\s+(?:RSA\s+)?PRIVATE\s+KEY-----[\s\S]*?-----END\s+(?:RSA\s+)?PRIVATE\s+KEY-----/g, label: 'private_key' },
  { pattern: /ghp_[a-zA-Z0-9]{36,}/g, label: 'github_token' },
  { pattern: /glpat-[a-zA-Z0-9_-]{20,}/g, label: 'gitlab_token' },
  { pattern: /xox[bpas]-[a-zA-Z0-9-]+/g, label: 'slack_token' },
  { pattern: /AKIA[A-Z0-9]{16}/g, label: 'aws_access_key' },
];

/**
 * Scrub known secret patterns from terminal output before sending to observers.
 * Returns the scrubbed string. Original data is never modified.
 */
function scrubForObservers(data) {
  let scrubbed = data;
  for (const { pattern } of REDACTION_PATTERNS) {
    // Reset lastIndex for global regexes
    pattern.lastIndex = 0;
    scrubbed = scrubbed.replace(pattern, '[REDACTED]');
  }
  return scrubbed;
}

/**
 * Notify the session owner of the current observer count.
 * Sends { type: 'observer_count', count } to the owner's WebSocket.
 */
function notifyOwnerObserverCount(sessionInfo) {
  const count = sessionInfo.observers ? sessionInfo.observers.size : 0;
  if (sessionInfo.ws && sessionInfo.ws.readyState === 1) {
    try {
      sessionInfo.ws.send(JSON.stringify({ type: 'observer_count', count }));
    } catch { /* ignore */ }
  }
}

/**
 * Broadcast a message to all observers of a session (non-blocking).
 * Cleans up dead connections automatically.
 * Data messages are scrubbed for secrets before sending.
 */
function broadcastToObservers(sessionInfo, message) {
  if (!sessionInfo.observers || sessionInfo.observers.size === 0) return;
  // Scrub data messages for secrets before broadcasting to observers
  const scrubbed = (message.type === 'data' && message.data)
    ? { ...message, data: scrubForObservers(message.data) }
    : message;
  const payload = JSON.stringify(scrubbed);
  const dead = [];
  for (const [id, obs] of sessionInfo.observers) {
    if (obs.ws.readyState === 1) {
      obs.ws.send(payload, (err) => {
        if (err) console.warn(`[Observer] [${id}] Send failed:`, err.message);
      });
      if (obs.ws.bufferedAmount > 1048576) {
        console.warn(`[Observer] [${id}] Backpressure: ${obs.ws.bufferedAmount} bytes buffered`);
      }
    } else if (obs.ws.readyState === 3) {
      dead.push(id);
    }
  }
  for (const id of dead) sessionInfo.observers.delete(id);
}

/**
 * Close all observer connections for a session with a given code/reason.
 */
function closeAllObservers(sessionInfo, code, reason) {
  if (!sessionInfo.observers) return;
  for (const [id, obs] of sessionInfo.observers) {
    try { obs.ws.close(code, reason); } catch { /* ignore */ }
  }
  sessionInfo.observers.clear();
}

/** Generate cryptographically random session ID (24-char hex) */
function generateSessionId() {
  return crypto.randomBytes(12).toString('hex');
}

// Periodic cleanup of expired detached sessions
const detachedCleanupTimer = setInterval(() => {
  const now = Date.now();
  for (const [sessionId, session] of detachedSessions) {
    if (now - session.detachedAt > DETACH_GRACE_PERIOD_MS) {
      console.log(`[Shell] [${sessionId.slice(0, 8)}] Grace period expired, killing detached PTY`);
      closeAllObservers(session, 1000, 'Session expired');
      try { session.shell.kill(); } catch (e) { /* already dead */ }
      detachedSessions.delete(sessionId);
      storeAuditEnvelope({
        type: 'event',
        from: session.user ? `human.${session.user.id}` : 'human.anonymous',
        to: 'audit.system',
        intent: 'quox.shell.timeout',
        corr: `SHELL_${sessionId}`,
        payload: { sessionId, mode: session.mode, hostId: session.hostId, detachedDurationMs: now - session.detachedAt }
      });
    }
  }
}, SESSION_CLEANUP_INTERVAL_MS);
if (detachedCleanupTimer.unref) detachedCleanupTimer.unref(); // Don't prevent process exit

// Route HTTP upgrade requests to the correct WebSocket server by path
server.on('upgrade', (req, socket, head) => {
  const { pathname } = new URL(req.url, `http://${req.headers.host}`);
  if (pathname === '/terminal/shell/ws') {
    shellWss.handleUpgrade(req, socket, head, (ws) => {
      shellWss.emit('connection', ws, req);
    });
  } else if (pathname === '/terminal/shell/observe') {
    observerWss.handleUpgrade(req, socket, head, (ws) => {
      observerWss.emit('connection', ws, req);
    });
  } else if (pathname === '/terminal/quox-cli/ws') {
    quoxCliWss.handleUpgrade(req, socket, head, (ws) => {
      quoxCliWss.emit('connection', ws, req);
    });
  } else if (pathname === '/terminal/ws') {
    terminalWss.handleUpgrade(req, socket, head, (ws) => {
      terminalWss.emit('connection', ws, req);
    });
  } else if (pathname === '/ws') {
    wss.handleUpgrade(req, socket, head, (ws) => {
      wss.emit('connection', ws, req);
    });
  } else if (pathname === '/api/v1/stream/events') {
    // CLI-2d: Unified event stream — broadcasts AEE envelopes in real-time
    eventStreamWss.handleUpgrade(req, socket, head, (ws) => {
      eventStreamWss.emit('connection', ws, req);
    });
  } else {
    socket.destroy();
  }
});

terminalWss.on('connection', (ws, req) => {
  const clientId = Math.random().toString(36).slice(2, 8);
  const clientIp = req.socket.remoteAddress;

  // Authenticate via JWT (same pattern as fleet WebSocket)
  const authResult = authenticateWebSocket(req);
  if (!authResult.authenticated) {
    console.warn(`[Terminal] [${clientId}] Auth rejected from ${clientIp}: ${authResult.error}`);
    try {
      ws.send(JSON.stringify({ type: 'error', error: 'authentication_failed', message: authResult.error }));
    } catch (e) { /* ignore send errors during rejection */ }
    ws.close(4001, authResult.error);
    return;
  }

  // Enforce concurrent session limit
  if (terminalSessions.size >= MAX_TERMINAL_SESSIONS) {
    console.warn(`[Terminal] [${clientId}] Session limit reached (${MAX_TERMINAL_SESSIONS})`);
    try {
      ws.send(JSON.stringify({ type: 'error', error: 'session_limit', message: `Maximum ${MAX_TERMINAL_SESSIONS} terminal sessions allowed` }));
    } catch (e) { /* ignore */ }
    ws.close(4003, 'Session limit reached');
    return;
  }

  const userInfo = authResult.user ? ` (user: ${authResult.user.id})` : ' (dev-mode)';
  console.log(`[Terminal] [${clientId}] Connected from ${clientIp}${userInfo}`);

  // DEVSUITE-DEVMODE 5c: which allowlisted app this terminal runs. The query
  // value is ONLY ever used as a key into the allowlist — never spawned raw.
  const { app: requestedApp, spec: terminalApp } = resolveTerminalApp(req.url);
  if (!terminalApp) {
    console.warn(`[Terminal] [${clientId}] Rejected unknown app '${requestedApp}'`);
    try {
      ws.send(JSON.stringify({ type: 'error', error: 'unknown_app', message: `Unknown terminal app '${requestedApp}'` }));
    } catch (e) { /* ignore */ }
    ws.close(4004, 'Unknown terminal app');
    return;
  }

  const capabilityPromise = requestedApp === 'codex'
    // Codex needs the PTY plus its own binary; claude-CLI health is irrelevant.
    ? Promise.resolve(getNodePty()).then(async (pty) => {
        if (!pty) return { available: false, reason: 'pty_unavailable', recommendation: 'Terminal is unavailable on this deployment (no PTY support).' };
        const codex = await getCodexCliStatus();
        if (!codex.installed) return { available: false, reason: 'codex_not_installed', recommendation: 'The codex CLI is not installed in this deployment, so Codex terminal login is unavailable.' };
        return { available: true };
      })
    : getTerminalCapabilityStatus();

  capabilityPromise.then((terminalCapability) => {
    if (!terminalCapability.available) {
      console.warn(`[Terminal] [${clientId}] Terminal unavailable: ${terminalCapability.reason}`);
      try {
        ws.send(JSON.stringify({
          type: 'error',
          error: 'terminal_unavailable',
          reason: terminalCapability.reason,
          message: terminalCapability.recommendation,
          detail: terminalCapability.detail,
        }));
      } catch (e) { /* ignore send errors during rejection */ }
      ws.close(4005, 'Terminal unavailable');
      return;
    }

    const nodePty = getNodePty();
    const shell = nodePty.spawn(terminalApp.cmd, terminalApp.args, {
    name: 'xterm-256color',
    cols: 80,
    rows: 24,
    cwd: resolveTerminalCwd(RUNTIME_HOME_DIR),
    env: {
      ...process.env,
      HOME: RUNTIME_HOME_DIR,
      USER: RUNTIME_USER,
      TERM: 'xterm-256color',
      COLORTERM: 'truecolor'
    }
  });

    // The bootstrap types `/login` into claude's REPL — claude-specific.
    // codex login --device-auth needs no input, so it gets a no-op with the
    // same interface (handleData/dispose are called later in this handler).
    const claudeTerminalBootstrap = requestedApp === 'claude'
      ? createClaudeTerminalBootstrap({
          write: (data) => {
            try { shell.write(data); } catch (e) { /* PTY may have exited */ }
          },
        })
      : { start() {}, handleData() {}, dispose() {} };
    claudeTerminalBootstrap.start();

    const sessionInfo = { ws, shell, user: authResult.user, startedAt: Date.now() };
    terminalSessions.set(clientId, sessionInfo);

    // AEE audit: terminal session opened
    storeAuditEnvelope({
      type: 'event',
      from: authResult.user ? `human.${authResult.user.id}` : 'human.anonymous',
      to: 'audit.system',
      intent: 'quox.terminal.open',
      corr: `TERM_${clientId}`,
      payload: { clientId, ip: clientIp }
    });

    // AEE-CORE-3: per-session command-line capture. Every line submitted
    // (Enter) becomes one `quox.terminal.exec` envelope with the accumulated
    // command text, under the same TERM_<clientId> corr as the session open.
    const { createShellCapture } = require('./lib/shellCommandCapture.js');
    const shellCapture = createShellCapture({
      onCommand: (cmd, meta) => {
        storeAuditEnvelope({
          type: 'event',
          from: authResult.user ? `human.${authResult.user.id}` : 'human.anonymous',
          to: 'audit.system',
          intent: 'quox.terminal.exec',
          corr: `TERM_${clientId}`,
          payload: {
            clientId,
            command: cmd,
            length: cmd.length,
            truncated: !!meta?.truncated,
          },
        });
      },
    });

    // PTY output → WebSocket
    shell.onData((data) => {
      claudeTerminalBootstrap.handleData(data);
      if (ws.readyState === 1) {
        ws.send(JSON.stringify({ type: 'data', data }));
      }
    });

    // PTY exit → notify client
    shell.onExit(({ exitCode, signal }) => {
      console.log(`[Terminal] [${clientId}] PTY exited (code: ${exitCode}, signal: ${signal})`);
      terminalSessions.delete(clientId);
      claudeTerminalBootstrap.dispose();
      if (ws.readyState === 1) {
        ws.send(JSON.stringify({ type: 'exit', exitCode, signal }));
        ws.close(1000, 'PTY exited');
      }
    });

    // WebSocket messages → PTY
    ws.on('message', (msg) => {
      try {
        const parsed = JSON.parse(msg.toString());
        switch (parsed.type) {
          case 'data':
            shell.write(parsed.data);
            try { shellCapture.feed(parsed.data); } catch { /* never block I/O on audit */ }
            break;
          case 'resize':
            if (parsed.cols > 0 && parsed.rows > 0 && parsed.cols <= 500 && parsed.rows <= 200) {
              shell.resize(parsed.cols, parsed.rows);
            }
            break;
        }
      } catch (e) {
        // Not JSON — treat as raw terminal input
        const raw = msg.toString();
        shell.write(raw);
        try { shellCapture.feed(raw); } catch { /* never block I/O on audit */ }
      }
    });

    // WebSocket close → clean up PTY and refresh auth cache
    ws.on('close', (code, reason) => {
      const duration = Date.now() - sessionInfo.startedAt;
      console.log(`[Terminal] [${clientId}] Disconnected (code: ${code}, duration: ${Math.round(duration / 1000)}s)`);
      terminalSessions.delete(clientId);
      claudeTerminalBootstrap.dispose();
      try { shell.kill(); } catch (e) { /* already dead */ }

      // Log credential status after terminal close — user may have just completed /login
      console.log(`[Terminal] CLI credentials after session close: ${hasCliCredentials() ? 'found' : 'not found'}`);

      storeAuditEnvelope({
        type: 'event',
        from: authResult.user ? `human.${authResult.user.id}` : 'human.anonymous',
        to: 'audit.system',
        intent: 'quox.terminal.close',
        corr: `TERM_${clientId}`,
        payload: { clientId, durationMs: duration }
      });
    });

    ws.on('error', (err) => {
      console.error(`[Terminal] [${clientId}] WebSocket error:`, err.message);
      terminalSessions.delete(clientId);
      try { shell.kill(); } catch (e) { /* already dead */ }
    });
  }).catch((err) => {
    console.error(`[Terminal] [${clientId}] Capability check failed:`, err.message);
    try {
      ws.send(JSON.stringify({
        type: 'error',
        error: 'terminal_unavailable',
        reason: 'capability_check_failed',
        message: 'Claude terminal login is unavailable right now. Use an OpenAI or Anthropic API key instead.',
      }));
    } catch (e) { /* ignore */ }
    ws.close(4005, 'Terminal unavailable');
  });
});

// REST endpoint for terminal session info
app.get('/terminal/sessions', requireAuth(), (req, res) => {
  const sessions = [];
  for (const [id, session] of terminalSessions) {
    sessions.push({
      id,
      user: session.user?.id || 'anonymous',
      startedAt: session.startedAt,
      durationMs: Date.now() - session.startedAt
    });
  }
  res.json({ sessions, count: sessions.length, limit: MAX_TERMINAL_SESSIONS });
});

// ============================================================================
// Shell WebSocket Endpoint — /terminal/shell/ws
// Spawns real shells (bash, SSH) for premium Web Terminal plugin
// ============================================================================

/**
 * Resolve host info from QuoxBastion registry
 */
async function resolveHostForShell(hostId) {
  const bastionUrl = process.env.BASTION_URL;
  const bastionToken = process.env.BASTION_API_TOKEN;
  if (!bastionUrl) throw new Error('Bastion shell access is unavailable on this installation.');

  const resp = await fetchWithTimeout(
    `${bastionUrl}/api/v1/hosts/${encodeURIComponent(hostId)}`,
    {
      headers: {
        'Authorization': `Bearer ${bastionToken}`,
        'Content-Type': 'application/json'
      }
    },
    10000
  );

  if (!resp.ok) {
    const text = await resp.text().catch(() => '');
    throw new Error(`Host "${hostId}" not found in bastion registry (${resp.status}): ${text}`);
  }

  return await resp.json();
}

/**
 * Spawn a PTY for the requested shell mode
 */
function spawnShellPty(mode, hostInfo) {
  const nodePty = getNodePty();
  if (!nodePty) {
    throw new Error('Terminal shell support is unavailable because PTY support is not installed in the collector runtime.');
  }

  const env = {
    ...process.env,
    TERM: 'xterm-256color',
    COLORTERM: 'truecolor',
    HOME: RUNTIME_HOME_DIR,
    USER: RUNTIME_USER,
    SHELL: '/bin/bash',
  };
  const cwd = resolveTerminalCwd(RUNTIME_HOME_DIR);
  const ptyOpts = { name: 'xterm-256color', cols: 80, rows: 24, cwd, env };

  switch (mode) {
    case 'local':
      return nodePty.spawn('/bin/bash', ['--login'], ptyOpts);

    case 'ssh': {
      const sshUser = hostInfo.ssh?.user || 'control';
      const sshPort = String(hostInfo.ssh?.port || 22);
      const sshHost = hostInfo.ip;
      // Bastion uses key auth; all other hosts use password only
      const bastionIp = process.env.BASTION_HOST || '';
      const isBastion = bastionIp && sshHost === bastionIp;
      const args = [
        '-o', 'StrictHostKeyChecking=accept-new',
        '-o', 'ServerAliveInterval=30',
        ...(isBastion
          ? ['-i', resolveBastionSshKeyPath(RUNTIME_HOME_DIR)]
          : ['-o', 'PubkeyAuthentication=no', '-o', 'PreferredAuthentications=password']),
        '-p', sshPort,
        `${sshUser}@${sshHost}`
      ];
      return nodePty.spawn('ssh', args, ptyOpts);
    }

    default:
      throw new Error(`Unknown shell mode: ${mode}`);
  }
}

// Quox brand PS1 (blue user, lilac host, white path)
const QUOX_PS1 = "\\[\\e[38;5;75m\\]\\u\\[\\e[0m\\]@\\[\\e[38;5;141m\\]\\h\\[\\e[0m\\]:\\[\\e[1;37m\\]\\w\\[\\e[0m\\]\\$ ";

/**
 * Wire WebSocket message/close/error handlers for a shell session.
 * Used by both new-session and reconnect paths to avoid duplication.
 */
function wireShellWsHandlers(ws, sessionInfo, authResult, clientIp) {
  const { sessionId, shell } = sessionInfo;
  const shortId = sessionId.slice(0, 8);

  // WebSocket messages → PTY
  ws.on('message', (msg) => {
    try {
      const parsed = JSON.parse(msg.toString());
      switch (parsed.type) {
        case 'data':
          shell.write(parsed.data);
          break;
        case 'resize':
          if (parsed.cols > 0 && parsed.rows > 0 && parsed.cols <= 500 && parsed.rows <= 200) {
            shell.resize(parsed.cols, parsed.rows);
          }
          break;
      }
    } catch (e) {
      // Not JSON — treat as raw terminal input
      shell.write(msg.toString());
    }
  });

  // WebSocket close → detach PTY (keep alive for reconnect) or final cleanup
  ws.on('close', (code, reason) => {
    const duration = Date.now() - sessionInfo.startedAt;
    console.log(`[Shell] [${shortId}] WebSocket closed (code: ${code}, duration: ${Math.round(duration / 1000)}s)`);
    shellSessions.delete(sessionId);

    // If PTY still alive, detach instead of killing
    try {
      if (shell.pid) {
        console.log(`[Shell] [${shortId}] Detaching PTY (pid: ${shell.pid}), grace: ${DETACH_GRACE_PERIOD_MS / 1000}s`);

        // Notify observers that owner detached (they stay connected during grace period)
        broadcastToObservers(sessionInfo, { type: 'owner_detached' });

        // Rewire PTY output to buffer + observers (no owner WebSocket)
        shell.removeAllListeners('data');
        shell.onData((data) => {
          sessionInfo.buffer.write(data);
          broadcastToObservers(sessionInfo, { type: 'data', data });
        });

        // Rewire PTY exit to clean up from detached map + close observers
        shell.removeAllListeners('exit');
        shell.onExit(({ exitCode, signal }) => {
          console.log(`[Shell] [${shortId}] Detached PTY exited (code: ${exitCode}, signal: ${signal})`);
          broadcastToObservers(sessionInfo, { type: 'exit', exitCode, signal });
          closeAllObservers(sessionInfo, 1000, 'Session ended');
          detachedSessions.delete(sessionId);
        });

        detachedSessions.set(sessionId, {
          sessionId,
          shell,
          user: sessionInfo.user,
          mode: sessionInfo.mode,
          hostId: sessionInfo.hostId,
          hostInfo: sessionInfo.hostInfo,
          startedAt: sessionInfo.startedAt,
          detachedAt: Date.now(),
          buffer: sessionInfo.buffer,
          ps1Injected: sessionInfo.ps1Injected,
          observers: sessionInfo.observers,
        });

        storeAuditEnvelope({
          type: 'event',
          from: authResult.user ? `human.${authResult.user.id}` : 'human.anonymous',
          to: 'audit.system',
          intent: 'quox.shell.detach',
          corr: `SHELL_${sessionId}`,
          payload: { sessionId, mode: sessionInfo.mode, hostId: sessionInfo.hostId, durationMs: duration }
        });
        emitAgentEvent({
          session_id: `SHELL_${sessionId}`,
          type: 'session.status',
          agent_name: 'terminal',
          org_id: authResult.user?.org_id,
          data: { status: 'detached', duration_ms: duration },
          summary: `Session detached (grace period active)`,
        });
        return;
      }
    } catch (e) { /* PTY already dead, proceed to final cleanup */ }

    // PTY already dead — final close
    storeAuditEnvelope({
      type: 'event',
      from: authResult.user ? `human.${authResult.user.id}` : 'human.anonymous',
      to: 'audit.system',
      intent: 'quox.shell.close',
      corr: `SHELL_${sessionId}`,
      payload: { sessionId, mode: sessionInfo.mode, hostId: sessionInfo.hostId, durationMs: duration }
    });
    emitAgentEvent({
      session_id: `SHELL_${sessionId}`,
      type: 'session.end',
      agent_name: 'terminal',
      org_id: authResult.user?.org_id,
      data: { status: 'finished', duration_ms: duration },
      summary: `Terminal closed (${Math.round(duration / 1000)}s)`,
    });
  });

  ws.on('error', (err) => {
    console.error(`[Shell] [${shortId}] WebSocket error:`, err.message);
    // Let the close handler deal with cleanup/detach
  });
}

shellWss.on('connection', async (ws, req) => {
  const clientId = Math.random().toString(36).slice(2, 8);
  const clientIp = req.socket.remoteAddress;

  // Authenticate via JWT
  const authResult = authenticateWebSocket(req);
  if (!authResult.authenticated) {
    console.warn(`[Shell] [${clientId}] Auth rejected from ${clientIp}: ${authResult.error}`);
    try {
      ws.send(JSON.stringify({ type: 'error', error: 'authentication_failed', message: authResult.error }));
    } catch (e) { /* ignore */ }
    ws.close(4001, authResult.error);
    return;
  }

  // Parse query params
  const url = new URL(req.url, `http://${req.headers.host}`);
  const sessionParam = url.searchParams.get('session');
  const mode = url.searchParams.get('mode') || 'local';
  const hostParam = url.searchParams.get('host');

  // ── Reconnection path ──────────────────────────────────────────────
  if (sessionParam) {
    const detached = detachedSessions.get(sessionParam);
    if (!detached) {
      try {
        ws.send(JSON.stringify({ type: 'error', error: 'session_not_found', message: 'Session not found or expired' }));
      } catch (e) { /* ignore */ }
      ws.close(4006, 'Session not found');
      return;
    }

    // Validate user ownership (prevent session hijacking)
    const originalUserId = detached.user?.id || null;
    const reconnectUserId = authResult.user?.id || null;
    if (originalUserId !== reconnectUserId) {
      try {
        ws.send(JSON.stringify({ type: 'error', error: 'session_owner_mismatch', message: 'Session belongs to a different user' }));
      } catch (e) { /* ignore */ }
      ws.close(4007, 'Session owner mismatch');
      return;
    }

    // Reattach: move from detached → active
    detachedSessions.delete(sessionParam);
    const shortId = sessionParam.slice(0, 8);

    const sessionInfo = {
      sessionId: sessionParam,
      ws,
      shell: detached.shell,
      user: detached.user,
      mode: detached.mode,
      hostId: detached.hostId,
      hostInfo: detached.hostInfo,
      startedAt: detached.startedAt,
      buffer: detached.buffer,
      ps1Injected: detached.ps1Injected,
      observers: detached.observers || new Map(),
    };
    shellSessions.set(sessionParam, sessionInfo);

    // Read buffered output for replay
    const bufferedOutput = detached.buffer.read();

    // Send reconnected message with scrollback
    try {
      ws.send(JSON.stringify({
        type: 'reconnected',
        sessionId: sessionParam,
        mode: detached.mode,
        hostId: detached.hostId,
        hostIp: detached.hostInfo?.ip || 'localhost',
        bufferedOutput,
      }));
    } catch (e) { /* ignore */ }

    // Rewire PTY output to new WebSocket + buffer + observers
    detached.shell.removeAllListeners('data');
    detached.shell.onData((data) => {
      sessionInfo.buffer.write(data);
      if (ws.readyState === 1) {
        ws.send(JSON.stringify({ type: 'data', data }));
      }
      broadcastToObservers(sessionInfo, { type: 'data', data });
    });

    // Notify observers that owner reconnected
    broadcastToObservers(sessionInfo, { type: 'owner_reconnected' });

    // Rewire PTY exit
    detached.shell.removeAllListeners('exit');
    detached.shell.onExit(({ exitCode, signal }) => {
      console.log(`[Shell] [${shortId}] PTY exited (code: ${exitCode}, signal: ${signal})`);
      broadcastToObservers(sessionInfo, { type: 'exit', exitCode, signal });
      closeAllObservers(sessionInfo, 1000, 'Session ended');
      shellSessions.delete(sessionParam);
      detachedSessions.delete(sessionParam);
      if (ws.readyState === 1) {
        ws.send(JSON.stringify({ type: 'exit', exitCode, signal }));
        ws.close(1000, 'PTY exited');
      }
    });

    // Wire WS handlers (message, close, error)
    wireShellWsHandlers(ws, sessionInfo, authResult, clientIp);

    const detachedDuration = Date.now() - detached.detachedAt;
    console.log(`[Shell] [${shortId}] Reconnected from ${clientIp} (was detached ${Math.round(detachedDuration / 1000)}s)`);

    storeAuditEnvelope({
      type: 'event',
      from: authResult.user ? `human.${authResult.user.id}` : 'human.anonymous',
      to: 'audit.system',
      intent: 'quox.shell.reconnect',
      corr: `SHELL_${sessionParam}`,
      payload: { sessionId: sessionParam, mode: detached.mode, hostId: detached.hostId, ip: clientIp, detachedDurationMs: detachedDuration }
    });
    return;
  }

  // ── New session path ───────────────────────────────────────────────

  // Validate mode
  if (!ALLOWED_SHELL_MODES.includes(mode)) {
    try {
      ws.send(JSON.stringify({ type: 'error', error: 'invalid_mode', message: `Invalid mode: ${mode}. Allowed: ${ALLOWED_SHELL_MODES.join(', ')}` }));
    } catch (e) { /* ignore */ }
    ws.close(4002, 'Invalid mode');
    return;
  }

  // Validate host param for SSH mode
  if (mode === 'ssh') {
    if (!hostParam) {
      try {
        ws.send(JSON.stringify({ type: 'error', error: 'missing_host', message: 'SSH mode requires a host parameter' }));
      } catch (e) { /* ignore */ }
      ws.close(4002, 'Missing host');
      return;
    }
    if (!HOST_ID_PATTERN.test(hostParam)) {
      try {
        ws.send(JSON.stringify({ type: 'error', error: 'invalid_host', message: 'Invalid host ID format' }));
      } catch (e) { /* ignore */ }
      ws.close(4002, 'Invalid host ID');
      return;
    }
  }

  // Enforce session limit — evict user's detached sessions first before rejecting
  const totalSessions = shellSessions.size + detachedSessions.size;
  if (totalSessions >= MAX_SHELL_SESSIONS) {
    // Try to reclaim by killing the requesting user's oldest detached sessions
    const userId = authResult.user?.id || null;
    const userDetached = [];
    for (const [sid, sess] of detachedSessions) {
      if ((sess.user?.id || null) === userId) {
        userDetached.push({ sid, detachedAt: sess.detachedAt, session: sess });
      }
    }
    // Sort oldest first
    userDetached.sort((a, b) => a.detachedAt - b.detachedAt);

    if (userDetached.length > 0) {
      // Evict oldest detached session to make room
      const evict = userDetached[0];
      console.log(`[Shell] [${evict.sid.slice(0, 8)}] Evicting oldest detached session to make room`);
      try { evict.session.shell.kill(); } catch (e) { /* already dead */ }
      detachedSessions.delete(evict.sid);
    } else {
      // No detached sessions to evict — hard limit
      console.warn(`[Shell] [${clientId}] Session limit reached (${totalSessions}/${MAX_SHELL_SESSIONS}), no detached to evict`);
      try {
        ws.send(JSON.stringify({ type: 'error', error: 'session_limit', message: `Maximum ${MAX_SHELL_SESSIONS} shell sessions allowed` }));
      } catch (e) { /* ignore */ }
      ws.close(4003, 'Session limit reached');
      return;
    }
  }

  // Resolve host for SSH mode
  let hostInfo = null;
  if (mode === 'ssh') {
    try {
      hostInfo = await resolveHostForShell(hostParam);
    } catch (err) {
      console.error(`[Shell] [${clientId}] Host resolution failed for "${hostParam}":`, err.message);
      try {
        ws.send(JSON.stringify({ type: 'error', error: 'host_resolution_failed', message: err.message }));
      } catch (e) { /* ignore */ }
      ws.close(4004, 'Host not found');
      return;
    }
  }

  // Generate persistent session ID
  const sessionId = generateSessionId();
  const shortId = sessionId.slice(0, 8);

  const userInfo = authResult.user ? ` (user: ${authResult.user.id})` : ' (dev-mode)';
  const targetInfo = mode === 'ssh' ? ` -> ${hostParam} (${hostInfo.ip})` : ' (local)';
  console.log(`[Shell] [${shortId}] ${mode} session from ${clientIp}${userInfo}${targetInfo}`);

  // Spawn PTY
  let shell;
  try {
    shell = spawnShellPty(mode, hostInfo);
  } catch (err) {
    console.error(`[Shell] [${shortId}] Failed to spawn PTY:`, err.message);
    try {
      ws.send(JSON.stringify({ type: 'error', error: 'spawn_failed', message: err.message }));
    } catch (e) { /* ignore */ }
    ws.close(4005, 'Spawn failed');
    return;
  }

  const buffer = new RingBuffer(DETACH_BUFFER_CAPACITY);
  const sessionInfo = {
    sessionId, ws, shell, user: authResult.user, mode, hostId: hostParam,
    hostInfo, startedAt: Date.now(), buffer, ps1Injected: false,
    observers: new Map(),
  };
  shellSessions.set(sessionId, sessionInfo);

  // AEE audit: shell session opened
  storeAuditEnvelope({
    type: 'event',
    from: authResult.user ? `human.${authResult.user.id}` : 'human.anonymous',
    to: 'audit.system',
    intent: 'quox.shell.open',
    corr: `SHELL_${sessionId}`,
    payload: { sessionId, mode, hostId: hostParam, ip: clientIp }
  });

  // Emit to Agent Stream
  emitAgentSession({
    id: `SHELL_${sessionId}`,
    host_id: hostParam || 'localhost',
    agent_type: 'terminal',
    agent_name: mode === 'ssh' ? `SSH → ${hostParam}` : 'Local shell',
    provider: 'quox',
    status: 'running',
    user: authResult.user?.id || 'anonymous',
    org_id: authResult.user?.org_id,
    project: 'quox-terminal',
  });

  // Notify client of successful connection (includes sessionId for reconnect)
  try {
    ws.send(JSON.stringify({
      type: 'connected',
      sessionId,
      mode,
      hostId: hostParam,
      hostIp: hostInfo?.ip || 'localhost'
    }));
  } catch (e) { /* ignore */ }

  // PTY output → WebSocket + buffer + observers
  shell.onData((data) => {
    if (!sessionInfo.ps1Injected && sessionInfo.mode !== 'ssh') {
      sessionInfo.ps1Injected = true;
      setTimeout(() => {
        shell.write(`export PS1='${QUOX_PS1}'\rclear\r`);
      }, 300);
    }
    sessionInfo.buffer.write(data);
    if (ws.readyState === 1) {
      ws.send(JSON.stringify({ type: 'data', data }));
    }
    broadcastToObservers(sessionInfo, { type: 'data', data });
  });

  // PTY exit → notify client + observers
  shell.onExit(({ exitCode, signal }) => {
    console.log(`[Shell] [${shortId}] PTY exited (code: ${exitCode}, signal: ${signal})`);
    broadcastToObservers(sessionInfo, { type: 'exit', exitCode, signal });
    closeAllObservers(sessionInfo, 1000, 'Session ended');
    shellSessions.delete(sessionId);
    detachedSessions.delete(sessionId);
    if (ws.readyState === 1) {
      ws.send(JSON.stringify({ type: 'exit', exitCode, signal }));
      ws.close(1000, 'PTY exited');
    }
  });

  // Wire WS handlers (message, close, error)
  wireShellWsHandlers(ws, sessionInfo, authResult, clientIp);
});

// ── Observer WebSocket ─────────────────────────────────────────────
// Read-only observers connect here. They receive PTY output but cannot send input.
// Separate WebSocketServer ensures observer close never triggers owner detach.
observerWss.on('connection', async (ws, req) => {
  const clientId = Math.random().toString(36).slice(2, 8);
  const clientIp = req.socket.remoteAddress;

  // Authenticate
  const authResult = authenticateWebSocket(req);
  if (!authResult.authenticated) {
    console.warn(`[Observer] [${clientId}] Auth rejected from ${clientIp}: ${authResult.error}`);
    try { ws.send(JSON.stringify({ type: 'error', error: 'authentication_failed', message: authResult.error })); } catch { /* ignore */ }
    ws.close(4001, authResult.error);
    return;
  }

  // Extract session ID from query params
  const url = new URL(req.url, `http://${req.headers.host}`);
  const sessionId = url.searchParams.get('session');
  if (!sessionId) {
    try { ws.send(JSON.stringify({ type: 'error', error: 'missing_session', message: 'session parameter required' })); } catch { /* ignore */ }
    ws.close(4002, 'Missing session ID');
    return;
  }

  // Look up session (active or detached)
  const session = shellSessions.get(sessionId) || detachedSessions.get(sessionId);
  if (!session) {
    console.warn(`[Observer] [${clientId}] Session not found: ${sessionId.slice(0, 8)}`);
    try { ws.send(JSON.stringify({ type: 'error', error: 'session_not_found', message: 'No active or detached session with that ID' })); } catch { /* ignore */ }
    ws.close(4006, 'Session not found');
    return;
  }

  // Org boundary check
  const sessionOrgId = session.user?.org_id || session.user?.orgId || null;
  const observerOrgId = authResult.user?.org_id || authResult.user?.orgId || null;
  if (sessionOrgId && observerOrgId && sessionOrgId !== observerOrgId) {
    console.warn(`[Observer] [${clientId}] Org mismatch: observer=${observerOrgId}, session=${sessionOrgId}`);
    try { ws.send(JSON.stringify({ type: 'error', error: 'org_mismatch', message: 'Observer not in same organization' })); } catch { /* ignore */ }
    ws.close(4009, 'Organization mismatch');
    return;
  }

  // Enforce per-session observer limit
  if (!session.observers) session.observers = new Map();
  if (session.observers.size >= MAX_OBSERVERS_PER_SESSION) {
    console.warn(`[Observer] [${clientId}] Session ${sessionId.slice(0, 8)} at observer limit (${MAX_OBSERVERS_PER_SESSION})`);
    try { ws.send(JSON.stringify({ type: 'error', error: 'observer_limit', message: `Maximum ${MAX_OBSERVERS_PER_SESSION} observers per session` })); } catch { /* ignore */ }
    ws.close(4003, 'Observer limit reached');
    return;
  }

  // Enforce per-user observer limit (count across all sessions)
  const observerUserId = authResult.user?.id || null;
  let userObserverCount = 0;
  for (const [, s] of shellSessions) {
    if (s.observers) {
      for (const [, obs] of s.observers) {
        if ((obs.user?.id || null) === observerUserId) userObserverCount++;
      }
    }
  }
  for (const [, s] of detachedSessions) {
    if (s.observers) {
      for (const [, obs] of s.observers) {
        if ((obs.user?.id || null) === observerUserId) userObserverCount++;
      }
    }
  }
  if (userObserverCount >= MAX_OBSERVERS_PER_USER) {
    console.warn(`[Observer] [${clientId}] User ${observerUserId} at observer limit (${MAX_OBSERVERS_PER_USER})`);
    try { ws.send(JSON.stringify({ type: 'error', error: 'user_observer_limit', message: `Maximum ${MAX_OBSERVERS_PER_USER} observer connections` })); } catch { /* ignore */ }
    ws.close(4003, 'User observer limit reached');
    return;
  }

  // Register observer
  const observerId = `obs_${clientId}`;
  session.observers.set(observerId, {
    ws,
    user: authResult.user,
    joinedAt: Date.now(),
  });

  const shortSession = sessionId.slice(0, 8);
  const userInfo = authResult.user ? ` (user: ${authResult.user.id})` : ' (dev-mode)';
  console.log(`[Observer] [${observerId}] Subscribed to session ${shortSession} from ${clientIp}${userInfo}`);

  // Notify owner of updated observer count
  notifyOwnerObserverCount(session);

  // Send init message with buffered output
  try {
    const bufferedOutput = session.buffer ? session.buffer.read() : '';
    ws.send(JSON.stringify({
      type: 'observer_init',
      sessionId,
      bufferedOutput,
      mode: session.mode,
      hostId: session.hostId,
      startedAt: session.startedAt,
      isDetached: detachedSessions.has(sessionId),
    }));
  } catch (e) {
    console.error(`[Observer] [${observerId}] Failed to send init:`, e.message);
  }

  // AEE audit
  storeAuditEnvelope({
    type: 'event',
    from: authResult.user ? `human.${authResult.user.id}` : 'human.observer',
    to: 'audit.system',
    intent: 'quox.shell.observer.connected',
    corr: `SHELL_${sessionId}`,
    payload: { observerId, sessionId, clientIp, userId: authResult.user?.id || 'anonymous' }
  });

  // Observers cannot send input — reject all messages
  ws.on('message', () => {
    try {
      ws.send(JSON.stringify({ type: 'error', error: 'observer_read_only', message: 'Observers cannot send input' }));
    } catch { /* ignore */ }
  });

  // Cleanup on disconnect
  ws.on('close', () => {
    const duration = Date.now() - (session.observers?.get(observerId)?.joinedAt || Date.now());
    session.observers?.delete(observerId);
    console.log(`[Observer] [${observerId}] Unsubscribed from session ${shortSession} (${Math.round(duration / 1000)}s)`);
    notifyOwnerObserverCount(session);

    storeAuditEnvelope({
      type: 'event',
      from: authResult.user ? `human.${authResult.user.id}` : 'human.observer',
      to: 'audit.system',
      intent: 'quox.shell.observer.disconnected',
      corr: `SHELL_${sessionId}`,
      payload: { observerId, sessionId, durationMs: duration }
    });
  });

  ws.on('error', (err) => {
    console.error(`[Observer] [${observerId}] WebSocket error:`, err.message);
    session.observers?.delete(observerId);
    notifyOwnerObserverCount(session);
  });
});

// ============================================================================
// Quox CLI TUI WebSocket — /terminal/quox-cli/ws
// Spawns `quox tui` in a PTY for the web-based CLI interface
// ============================================================================

quoxCliWss.on('connection', (ws, req) => {
  const clientId = Math.random().toString(36).slice(2, 8);
  console.log(`[QuoxCLI] [${clientId}] WebSocket connected`);

  // Auth: use the same JWT auth as the main terminal
  const authResult = authenticateWebSocket(req);
  if (!authResult.authenticated) {
    console.log(`[QuoxCLI] [${clientId}] Auth failed: ${authResult.error || 'no token'}`);
    ws.send(JSON.stringify({ type: 'error', error: 'auth_required', message: 'Authentication required' }));
    ws.close(4001, 'Auth required');
    return;
  }
  const token = authResult.token || '';

  let pty = null;
  try {
    const nodePty = getNodePty();
    if (!nodePty) {
      throw new Error('QuoxCLI terminal mode is unavailable because PTY support is not installed in the collector runtime.');
    }
    // CLI is volume-mounted at /app/cli in the container
    const cliPath = resolveQuoxCliEntryPath();
    if (!cliPath) {
      throw new Error('QuoxCLI files are unavailable in this deployment.');
    }
    const { cliRoot, missingDependency, validationError } = validateQuoxCliRuntime(cliPath);
    if (validationError) {
      console.error(`[QuoxCLI] [${clientId}] Runtime validation failed: ${validationError}`);
      throw new Error('QuoxCLI runtime is unavailable on this deployment.');
    }
    if (missingDependency) {
      console.error(`[QuoxCLI] [${clientId}] Missing CLI dependency: ${missingDependency}`);
      throw new Error('QuoxCLI runtime is not fully installed on this deployment. Ask an admin to finish the CLI setup.');
    }

    // Optional deep-link: ?screen=<view> opens the TUI directly on that view
    // (CLI-4.0). Allowlisted so nothing but a known screen name is ever passed
    // as a process argument — no arbitrary-arg injection into the spawn.
    const QUOX_TUI_SCREENS = new Set([
      'fleet', 'agents', 'tools', 'orgs', 'memory', 'workflows', 'chat',
      'admin', 'files', 'backups', 'objectives', 'inbox', 'vault', 'governance', 'health',
    ]);
    let tuiScreen = null;
    try {
      const reqUrl = new URL(req.url, 'http://localhost');
      const s = reqUrl.searchParams.get('screen');
      if (s && QUOX_TUI_SCREENS.has(s)) tuiScreen = s;
    } catch { /* no/invalid screen param — open on the menu */ }
    const tuiArgs = tuiScreen ? ['tui', tuiScreen] : ['tui'];

    pty = nodePty.spawn('node', [cliPath, ...tuiArgs], {
      name: 'xterm-256color',
      cols: 120,
      rows: 40,
      cwd: resolveTerminalCwd(cliRoot),
      env: {
        ...process.env,
        HOME: RUNTIME_HOME_DIR,
        USER: RUNTIME_USER,
        TERM: 'xterm-256color',
        FORCE_COLOR: '3',
        QUOX_TOKEN: token,
        QUOX_AUTH_URL: resolveServiceUrl(process.env.AUTH_SERVICE_URL, 'http://auth:3101', 'http://127.0.0.1:3101'),
        QUOX_COLLECTOR_URL: `http://127.0.0.1:${process.env.COLLECTOR_PORT || 9848}`,
        QUOX_FILES_URL: resolveServiceUrl(process.env.FILES_SERVICE_URL, 'http://files:3102', 'http://127.0.0.1:3102'),
        QUOX_MEMORY_URL: resolveServiceUrl(process.env.MEMORY_SERVICE_URL, 'http://memory:3103', 'http://127.0.0.1:3103'),
      },
    });

    console.log(`[QuoxCLI] [${clientId}] PTY spawned (pid: ${pty.pid})`);

    // PTY output → WebSocket
    pty.onData((data) => {
      if (ws.readyState === 1) {
        ws.send(JSON.stringify({ type: 'data', data }));
      }
    });

    pty.onExit(({ exitCode }) => {
      console.log(`[QuoxCLI] [${clientId}] PTY exited (code: ${exitCode})`);
      if (ws.readyState === 1) {
        ws.send(JSON.stringify({ type: 'exit', code: exitCode }));
        ws.close(1000, 'Process exited');
      }
    });

    // WebSocket messages → PTY
    ws.on('message', (raw) => {
      try {
        const msg = JSON.parse(raw);
        if (msg.type === 'data' && pty) {
          pty.write(msg.data);
        } else if (msg.type === 'resize' && pty) {
          pty.resize(msg.cols || 120, msg.rows || 40);
        }
      } catch {
        // Raw data fallback
        if (pty) pty.write(String(raw));
      }
    });

    ws.on('close', () => {
      console.log(`[QuoxCLI] [${clientId}] WebSocket closed`);
      if (pty) {
        try { pty.kill(); } catch {}
      }
    });

    ws.on('error', (err) => {
      console.error(`[QuoxCLI] [${clientId}] WebSocket error:`, err.message);
      if (pty) {
        try { pty.kill(); } catch {}
      }
    });
  } catch (err) {
    console.error(`[QuoxCLI] [${clientId}] Failed to spawn PTY:`, err.message);
    ws.send(JSON.stringify({ type: 'error', error: 'spawn_failed', message: `Failed to start Quox CLI: ${err.message}` }));
    ws.close(4002, 'Spawn failed');
  }
});

// REST: Create observer URL for a session (owner only)
app.post('/terminal/shell/sessions/:sessionId/observe', requireAuth(), (req, res) => {
  const { sessionId } = req.params;
  const userId = req.user?.id || null;

  const session = shellSessions.get(sessionId) || detachedSessions.get(sessionId);
  if (!session) {
    return res.status(404).json({ error: 'session_not_found', message: 'No active or detached session with that ID' });
  }

  // Only session owner can create observer links
  const sessionUserId = session.user?.id || null;
  if (sessionUserId !== userId) {
    return res.status(403).json({ error: 'forbidden', message: 'Only session owner can create observer links' });
  }

  // Build observer URL (frontend will open this in a new tab or share)
  const observeUrl = `/terminal?observe=${sessionId}`;

  res.json({
    observeUrl,
    sessionId,
    mode: session.mode,
    hostId: session.hostId,
    observerCount: session.observers ? session.observers.size : 0,
    maxObservers: MAX_OBSERVERS_PER_SESSION,
  });
});

// REST endpoint for shell session info (active + detached)
app.get('/terminal/shell/sessions', requireAuth(), (req, res) => {
  const sessions = [];
  for (const [sessionId, session] of shellSessions) {
    sessions.push({
      sessionId,
      mode: session.mode,
      hostId: session.hostId,
      user: session.user?.id || 'anonymous',
      startedAt: session.startedAt,
      durationMs: Date.now() - session.startedAt,
      status: 'active',
    });
  }
  for (const [sessionId, session] of detachedSessions) {
    sessions.push({
      sessionId,
      mode: session.mode,
      hostId: session.hostId,
      user: session.user?.id || 'anonymous',
      startedAt: session.startedAt,
      durationMs: Date.now() - session.startedAt,
      status: 'detached',
      detachedAt: session.detachedAt,
      gracePeriodRemainingMs: Math.max(0, DETACH_GRACE_PERIOD_MS - (Date.now() - session.detachedAt)),
    });
  }
  res.json({ sessions, count: sessions.length, limit: MAX_SHELL_SESSIONS, active: shellSessions.size, detached: detachedSessions.size });
});

// REST endpoint for terminal output buffer (for AI context)
app.get('/terminal/shell/output/:sessionId', requireAuth(), (req, res) => {
  const { sessionId } = req.params;
  const userId = req.user?.id || null;

  // Look up session in both active and detached maps
  const session = shellSessions.get(sessionId) || detachedSessions.get(sessionId);

  if (!session) {
    return res.status(404).json({
      error: 'session_not_found',
      message: 'No active or detached session with that ID'
    });
  }

  // Ownership check: session user must match requesting user
  const sessionUserId = session.user?.id || null;
  if (sessionUserId !== userId) {
    return res.status(403).json({
      error: 'forbidden',
      message: 'You do not own this session'
    });
  }

  // Read buffer
  const rawOutput = session.buffer.read();

  // Apply length limit from query params (default 4000, hard cap 8000)
  const maxChars = Math.min(
    parseInt(req.query.chars, 10) || 4000,
    8000
  );

  // Trim to last N chars if over limit
  const output = rawOutput.length > maxChars
    ? rawOutput.slice(-maxChars)
    : rawOutput;

  res.json({
    sessionId,
    mode: session.mode,
    hostId: session.hostId || null,
    outputLength: output.length,
    totalBuffered: rawOutput.length,
    output
  });
});

// REST endpoint to execute a command in user's active terminal session
app.post('/terminal/shell/exec', terminalLimiter, requireAuth(), (req, res) => {
  const { sessionId, command } = req.body;
  const userId = req.user?.id || null;

  // Validate input
  if (!sessionId || typeof sessionId !== 'string') {
    return res.status(400).json({ error: 'missing_session_id', message: 'sessionId is required' });
  }
  if (!command || typeof command !== 'string' || !command.trim()) {
    return res.status(400).json({ error: 'missing_command', message: 'command is required' });
  }

  // Look up active sessions only (not detached — can't write to disconnected PTYs)
  const session = shellSessions.get(sessionId);
  if (!session) {
    return res.status(404).json({ error: 'session_not_found', message: 'No active session with that ID' });
  }

  // Ownership check
  const sessionUserId = session.user?.id || null;
  if (sessionUserId !== userId) {
    return res.status(403).json({ error: 'forbidden', message: 'You do not own this session' });
  }

  // Server-side command validation
  const { validateMultiLineCommand } = require('./utils/commandValidator');
  const validation = validateMultiLineCommand(command.trim());

  if (validation.action === 'BLOCK') {
    return res.status(403).json({
      error: 'command_blocked',
      message: validation.description || 'Command is blocked by security policy',
      action: 'BLOCK',
      validation
    });
  }

  // Write command to PTY
  try {
    session.shell.write(command.trim() + '\r');
  } catch (err) {
    console.error(`[terminal-exec] Failed to write to PTY ${sessionId}:`, err.message);
    return res.status(500).json({ error: 'exec_failed', message: 'Failed to write to terminal' });
  }

  // AEE audit envelope
  const execEnvelope = {
    v: '1',
    id: generateSessionId(),
    ts: new Date().toISOString(),
    type: 'event',
    from: `human.${userId || 'anonymous'}`,
    to: 'terminal.exec',
    intent: 'terminal.exec.command',
    payload: {
      sessionId,
      command: command.trim(),
      action: validation.action,
      severity: validation.severity || 'GREEN',
      mode: session.mode,
      hostId: session.hostId || null
    }
  };
  storeAuditEnvelope(execEnvelope);

  res.json({
    ok: true,
    action: validation.action,
    validation: {
      severity: validation.severity || null,
      description: validation.description || null,
      action: validation.action
    }
  });
});

// REST endpoint to write/edit/restore a file in user's terminal via PTY heredoc
// Phase 4a: file:create — Phase 4b: file:edit with backup, file:restore for undo
app.post('/terminal/shell/write-file', terminalLimiter, requireAuth(), async (req, res) => {
  const { sessionId, filePath, content, action, backupPath, targetPath } = req.body;
  const userId = req.user?.id || null;
  const VALID_ACTIONS = ['create', 'edit', 'restore', 'delete', 'rename'];

  // Input validation
  if (!sessionId || typeof sessionId !== 'string') {
    return res.status(400).json({ error: 'missing_session_id', message: 'sessionId is required' });
  }
  if (!filePath || typeof filePath !== 'string') {
    return res.status(400).json({ error: 'missing_file_path', message: 'filePath is required' });
  }
  if (!VALID_ACTIONS.includes(action)) {
    return res.status(400).json({ error: 'invalid_action', message: `action must be one of: ${VALID_ACTIONS.join(', ')}` });
  }
  // Content required for create/edit, optional for restore/delete/rename
  if ((action === 'create' || action === 'edit') && (content == null || typeof content !== 'string')) {
    return res.status(400).json({ error: 'missing_content', message: 'content is required for create/edit' });
  }
  // Restore requires backupPath
  if (action === 'restore') {
    if (!backupPath || typeof backupPath !== 'string' || !backupPath.endsWith('.quox-backup')) {
      return res.status(400).json({ error: 'invalid_backup_path', message: 'Valid backupPath ending in .quox-backup is required for restore' });
    }
  }
  // Rename requires targetPath
  if (action === 'rename') {
    if (!targetPath || typeof targetPath !== 'string' || !targetPath.startsWith('/')) {
      return res.status(400).json({ error: 'invalid_target_path', message: 'Absolute targetPath is required for rename' });
    }
    if (/\.\./.test(targetPath) || /\x00/.test(targetPath)) {
      return res.status(400).json({ error: 'invalid_target_path', message: 'Invalid characters in targetPath' });
    }
  }

  // Path validation — server-side defense-in-depth
  if (!filePath.startsWith('/')) {
    return res.status(400).json({ error: 'invalid_path', message: 'filePath must be absolute' });
  }
  if (/\.\./.test(filePath)) {
    return res.status(400).json({ error: 'invalid_path', message: 'Directory traversal not allowed' });
  }
  if (/\x00/.test(filePath)) {
    return res.status(400).json({ error: 'invalid_path', message: 'Null bytes not allowed in path' });
  }

  // Session lookup (active only)
  const session = shellSessions.get(sessionId);
  if (!session) {
    return res.status(404).json({ error: 'session_not_found', message: 'No active session with that ID' });
  }

  // Ownership check
  const sessionUserId = session.user?.id || null;
  if (sessionUserId !== userId) {
    return res.status(403).json({ error: 'forbidden', message: 'You do not own this session' });
  }

  const escapedPath = filePath.replace(/'/g, "'\\''");

  try {
    if (action === 'restore') {
      // Restore from backup: cp backup → original, rm backup
      const escapedBackup = backupPath.replace(/'/g, "'\\''");
      session.shell.write(`cp '${escapedBackup}' '${escapedPath}' && rm -f '${escapedBackup}'\n`);
    } else if (action === 'delete') {
      // Delete: backup first, then rm
      const escapedBackup = escapedPath + '.quox-backup';
      session.shell.write(`cp '${escapedPath}' '${escapedBackup}' 2>/dev/null\n`);
      await new Promise(r => setTimeout(r, 150));
      session.shell.write(`rm -f '${escapedPath}'\n`);
    } else if (action === 'rename') {
      // Rename: backup first, then mv (create target dir if needed)
      const escapedBackup = escapedPath + '.quox-backup';
      const escapedTarget = targetPath.replace(/'/g, "'\\''");
      session.shell.write(`cp '${escapedPath}' '${escapedBackup}' 2>/dev/null\n`);
      await new Promise(r => setTimeout(r, 150));
      session.shell.write(`mkdir -p "$(dirname '${escapedTarget}')" && mv '${escapedPath}' '${escapedTarget}'\n`);
    } else {
      // For edit action, create backup first
      if (action === 'edit') {
        const escapedBackup = escapedPath + '.quox-backup';
        session.shell.write(`cp '${escapedPath}' '${escapedBackup}' 2>/dev/null\n`);
        // Small delay to let cp finish before heredoc
        await new Promise(r => setTimeout(r, 150));
      }

      // Build and write heredoc (same for create and edit)
      const timestamp = Date.now();
      const delimiter = `QUOX_FILE_EOF_${timestamp}`;
      const heredocCmd = `cat > '${escapedPath}' << '${delimiter}'\n${content}\n${delimiter}\n`;
      session.shell.write(heredocCmd);
    }
  } catch (err) {
    console.error(`[terminal-file-write] Failed to write to PTY ${sessionId}:`, err.message);
    return res.status(500).json({ error: 'write_failed', message: 'Failed to write to terminal' });
  }

  // AEE audit envelope
  const intentMap = {
    create: 'terminal.file.write', edit: 'terminal.file.edit',
    restore: 'terminal.file.restore', delete: 'terminal.file.delete',
    rename: 'terminal.file.rename'
  };
  const fileWriteEnvelope = {
    v: '1',
    id: generateSessionId(),
    ts: new Date().toISOString(),
    type: 'event',
    from: `human.${userId || 'anonymous'}`,
    to: 'terminal.file',
    intent: intentMap[action] || 'terminal.file.write',
    payload: {
      sessionId,
      action,
      filePath,
      ...(targetPath ? { targetPath } : {}),
      contentLength: (content || '').length,
      mode: session.mode,
      hostId: session.hostId || null
    }
  };
  storeAuditEnvelope(fileWriteEnvelope);

  const response = { ok: true, action, filePath };
  if (action === 'edit' || action === 'delete' || action === 'rename') {
    response.backupPath = filePath + '.quox-backup';
  }
  if (action === 'rename') {
    response.targetPath = targetPath;
  }
  res.json(response);
});

// REST endpoint to read a file for diff computation (Phase 4b)
// Local sessions: fs.readFileSync. SSH sessions: graceful fallback.
app.get('/terminal/shell/read-file', requireAuth(), (req, res) => {
  const { sessionId, filePath } = req.query;
  const userId = req.user?.id || null;

  // Input validation
  if (!sessionId || typeof sessionId !== 'string') {
    return res.status(400).json({ error: 'missing_session_id', message: 'sessionId is required' });
  }
  if (!filePath || typeof filePath !== 'string') {
    return res.status(400).json({ error: 'missing_file_path', message: 'filePath is required' });
  }
  if (!filePath.startsWith('/')) {
    return res.status(400).json({ error: 'invalid_path', message: 'filePath must be absolute' });
  }
  if (/\.\./.test(filePath)) {
    return res.status(400).json({ error: 'invalid_path', message: 'Directory traversal not allowed' });
  }
  if (/\x00/.test(filePath)) {
    return res.status(400).json({ error: 'invalid_path', message: 'Null bytes not allowed in path' });
  }

  // Session lookup + ownership
  const session = shellSessions.get(sessionId);
  if (!session) {
    return res.status(404).json({ error: 'session_not_found', message: 'No active session with that ID' });
  }
  const sessionUserId = session.user?.id || null;
  if (sessionUserId !== userId) {
    return res.status(403).json({ error: 'forbidden', message: 'You do not own this session' });
  }

  // SSH sessions: file is on remote host, not accessible via fs
  if (session.mode === 'ssh') {
    return res.status(501).json({ error: 'not_supported', message: 'Remote file reading not yet supported for SSH sessions' });
  }

  // Local sessions: read via filesystem
  const fs = require('fs');
  try {
    const content = fs.readFileSync(filePath, 'utf-8');
    // AEE audit (read-only, lower severity)
    const readEnvelope = {
      v: '1',
      id: generateSessionId(),
      ts: new Date().toISOString(),
      type: 'event',
      from: `human.${userId || 'anonymous'}`,
      to: 'terminal.file',
      intent: 'terminal.file.read',
      payload: { sessionId, filePath, contentLength: content.length, mode: session.mode }
    };
    console.log('[terminal-file-read] AEE:', JSON.stringify(readEnvelope));

    res.json({ ok: true, content });
  } catch (err) {
    if (err.code === 'ENOENT') {
      return res.status(404).json({ error: 'file_not_found', message: 'File not found' });
    }
    if (err.code === 'EACCES') {
      return res.status(403).json({ error: 'permission_denied', message: 'Permission denied' });
    }
    console.error(`[terminal-file-read] Failed to read ${filePath}:`, err.message);
    return res.status(500).json({ error: 'read_failed', message: 'Failed to read file' });
  }
});

// REST endpoint for user's own reconnectable sessions
app.get('/terminal/shell/my-sessions', requireAuth(), (req, res) => {
  const userId = req.user?.id || null;
  const reconnectable = [];
  for (const [sessionId, session] of detachedSessions) {
    if ((session.user?.id || null) === userId) {
      reconnectable.push({
        sessionId,
        mode: session.mode,
        hostId: session.hostId,
        detachedAt: session.detachedAt,
        gracePeriodRemainingMs: Math.max(0, DETACH_GRACE_PERIOD_MS - (Date.now() - session.detachedAt)),
      });
    }
  }
  res.json({ sessions: reconnectable });
});

// Z2H-AGENTINST: public images carry the signed quoxagent release baked at
// /app/quoxagent-release (scripts/release/quoxagent/fetch-quoxagent-release.mjs,
// run by the release build); the dev box keeps serving its live checkout.
const { resolveQuoxAgentRoot } = require('./lib/quoxagentBinary.js');
const QuoxAgent_ROOT = resolveQuoxAgentRoot({ env: process.env, hostRoot: hostPath('quoxagent'), bakedRoot: path.join(__dirname, 'quoxagent-release') });

// Install script endpoint
app.get('/install', (req, res) => {
  const scriptPath = path.join(QuoxAgent_ROOT, 'deploy/install.sh');
  // NOTE (AGENT-AUTH #126): do NOT embed INTERNAL_SERVICE_KEY here — /install
  // is public/unauthenticated, so serving the master service key would let any
  // caller bypass the collector auth gate. Agent credentials must be
  // provisioned over the AUTHENTICATED deploy path (deploy/deploy-to-host.sh
  // over SSH passes SERVICE_KEY) or via a scoped enrollment token — never here.
  if (fs.existsSync(scriptPath)) {
    // #431 follow-up: the script ships a client-side COLLECTOR_URL default
    // pointing at one dev box; serve it templated to THIS collector's
    // configured address so `curl /install | bash` enrolls to the box that
    // answered. Explicit --collector / COLLECTOR_URL on the client still wins.
    const servingUrl = resolveCollectorEventUrl();
    res.type('text/plain');
    if (servingUrl) {
      res.send(templateInstallScript(fs.readFileSync(scriptPath, 'utf8'), servingUrl));
    } else {
      res.sendFile(scriptPath);
    }
  } else {
    // FLEET #421: this used to answer with a bare "not found", which told an
    // operator nothing when the container simply could not resolve the path.
    // Name the resolved path and the knob that controls it.
    console.error(`[install] install script missing at ${scriptPath} (QuoxAgent_ROOT=${QuoxAgent_ROOT})`);
    res.status(503).type('text/plain').send(
      // Z2H-3c: this body is piped into `sudo bash` by the documented one-liner, so it is a shell stub that
      // only explains and fails; the operator detail rides along as comments.
      `#!/bin/sh\n` +
      `# QuoxAgent install script not available: ${scriptPath} does not exist on the collector.\n` +
      `# This is a deployment misconfiguration: set QuoxAgent_ROOT (currently "${QuoxAgent_ROOT}") ` +
      `to the quoxagent checkout and make sure it is mounted into the collector container.\n` +
      `echo "Quox: this server cannot enrol hosts yet: its QuoxAgent installer is not available (HTTP 503). Nothing was installed." >&2\n` +
      `exit 1\n`
    );
  }
});

// Install QuoxAgent on hosts via bastion
app.post('/api/v1/quoxagent/install', requireServiceOrUserAuth(), async (req, res) => {
  const { hosts } = req.body;
  if (!hosts || !Array.isArray(hosts) || hosts.length === 0) {
    return res.status(400).json({ error: 'hosts array is required' });
  }
  // TRUST-PROOF installer integrity: host ids are templated into a bastion
  // shell command below — refuse anything not hostname-shaped.
  const { resolveQuoxagentBinary: _resolveQaBin, sha256OfFile: _sha256File, isSafeHostId: _isSafeHostId } = require('./lib/quoxagentBinary.js');
  const badHost = hosts.find((h) => !_isSafeHostId(h));
  if (badHost !== undefined) {
    return res.status(400).json({ error: `invalid host id: ${JSON.stringify(String(badHost)).slice(0, 140)}` });
  }

  const collectorUrl = process.env.COLLECTOR_URL || `http://${req.hostname}:${PORT}`;
  const results = [];

  // TRUST-PROOF installer integrity (audit cycle 1 high): compute the staged
  // linux-amd64 binary's SHA-256 here and deliver it INSIDE the install
  // command over the authenticated bastion SSH channel. The binary itself
  // still travels over plain LAN HTTP, but install.sh fails closed on hash
  // mismatch, so the download is tamper-evident. Absent binary → no hash →
  // install.sh's own fail-closed default takes over.
  const _qaBinPath = _resolveQaBin(QuoxAgent_ROOT, 'linux', 'amd64');
  const _qaSha = _qaBinPath ? _sha256File(_qaBinPath) : null;
  const _shaPrefix = _qaSha ? `env BINARY_SHA256=${_qaSha} ` : '';

  for (const host of hosts) {
    try {
      const cmd = require('./lib/failLoudInstallCommand.js').buildFailLoudInstallCommand({ installerUrl: `${collectorUrl}/install`, envPrefix: _shaPrefix, args: `--host-id ${host}` }); // quox#1223: no curl|bash
      // 55s, not the helper's 30s default: an install curls a 16KB script, pulls
      // a ~25MB binary over the LAN and runs setup. Must stay under QuoxBastion's
      // hardcoded 60s /api/v1/exec cap (known, unfixed, exec.go).
      const result = await devServerHeartbeatCallBastion(host, cmd, 55000);
      results.push({ hostname: host, success: result.success, error: result.error });
    } catch (err) {
      results.push({ hostname: host, success: false, error: err.message });
    }
  }

  res.json({ results });
});

// Download QuoxAgent binary
// TRUST-PROOF installer integrity: publish the SHA-256 of exactly the file
// the download route below would serve, sha256sum -c compatible. Registered
// BEFORE the generic route so the .sha256 suffix is never swallowed by
// :arch. Same-channel verification only catches corruption; the MITM-proof
// path is BINARY_SHA256 delivered out-of-band (bastion install does this).
app.get('/download/quoxagent-:os-:arch.sha256', (req, res) => {
  const { os, arch } = req.params;
  const { resolveQuoxagentBinary, sha256OfFile } = require('./lib/quoxagentBinary.js');
  const binPath = resolveQuoxagentBinary(QuoxAgent_ROOT, os, arch);
  if (!binPath) {
    return res.status(404).json({ error: 'unsupported_platform', message: `No quoxagent binary staged for ${os}/${arch}` });
  }
  const sha = sha256OfFile(binPath);
  if (!sha) {
    return res.status(503).json({ error: 'checksum_unavailable', message: `Binary at ${binPath} could not be hashed` });
  }
  res.type('text/plain').send(`${sha}  quoxagent-${os}-${arch}\n`);
});

app.get('/download/quoxagent-:os-:arch', (req, res) => {
  const { os, arch } = req.params;
  // fleet #424: this route used to parse :os/:arch only to name the download
  // and always served the single staged linux binary, so a darwin or arm64
  // host got a wrong-architecture file that looked right and died at exec
  // time with nothing naming the cause. Honest contract now: serve a staged
  // per-platform binary (bin/quoxagent-<os>-<arch>) when one exists, fall
  // back to the plain bin/quoxagent only for linux-amd64 (the platform that
  // binary actually is), and reject anything else naming what IS staged.
  if (!/^[a-z0-9]+$/.test(os) || !/^[a-z0-9_]+$/.test(arch)) {
    return res.status(400).json({
      error: 'bad_platform',
      message: 'os and arch must be lowercase alphanumeric',
    });
  }
  const binDir = path.join(QuoxAgent_ROOT, 'bin');
  const platformPath = path.join(binDir, `quoxagent-${os}-${arch}`);
  const binaryPath = path.join(QuoxAgent_ROOT, 'bin/quoxagent');
  // Order matters: the plain bin/quoxagent is the canonical, actively rebuilt
  // linux-amd64 binary, so it wins for that pair even when a (possibly stale)
  // bin/quoxagent-linux-amd64 also exists beside it. Per-platform files serve
  // every other platform.
  if (os === 'linux' && arch === 'amd64' && fs.existsSync(binaryPath)) {
    return res.download(binaryPath, `quoxagent-${os}-${arch}`);
  }
  if (fs.existsSync(platformPath)) {
    return res.download(platformPath, `quoxagent-${os}-${arch}`);
  }
  // Distinguish "this platform is not staged" (404, the caller's platform is
  // the gap) from "nothing is staged at all" (503, the deployment is broken,
  // same treatment as fleet #423).
  let staged = [];
  try {
    staged = [...new Set(
      fs.readdirSync(binDir)
        .filter((f) => f === 'quoxagent' || f.startsWith('quoxagent-'))
        .map((f) => (f === 'quoxagent' ? 'linux-amd64' : f.slice('quoxagent-'.length)))
    )];
  } catch { /* bin dir missing: staged stays empty, fall through to 503 */ }
  if (staged.length > 0) {
    return res.status(404).json({
      error: 'unsupported_platform',
      message:
        `No quoxagent binary is staged for ${os}/${arch}. Staged platforms: ${staged.join(', ')}. ` +
        `To enable this platform, build quoxagent for it and stage the binary at ` +
        `${platformPath} on the collector.`,
      requested: `${os}-${arch}`,
      available: staged,
    });
  }
  // FLEET #423: same treatment as GET /install. A bare "Binary not found"
  // told an operator nothing when the collector simply could not resolve the
  // path. Name the resolved path and the knob that controls it.
  console.error(`[download] quoxagent binary missing at ${binaryPath} (QuoxAgent_ROOT=${QuoxAgent_ROOT})`);
  res.status(503).json({
    error: 'binary_unavailable',
    message:
      `QuoxAgent binary not available: ${binaryPath} does not exist on the collector. ` +
      `This is a deployment misconfiguration: set QuoxAgent_ROOT (currently "${QuoxAgent_ROOT}") ` +
      `to the quoxagent checkout and make sure it is mounted into the collector container.`,
    path: binaryPath,
    QuoxAgent_ROOT,
  });
});

