// Quick check endpoint to see if QuoxAgent is installed on a host
app.get('/api/v1/check/:hostId', (req, res) => {
  const agent = agents.get(req.params.hostId);
  if (agent) {
    const age = Date.now() - agent.received_at;
    res.json({
      installed: true,
      running: age < AGENT_TIMEOUT_MS,
      version: agent.agent?.version,
      last_seen_seconds: Math.floor(age / 1000)
    });
  } else {
    res.json({
      installed: false,
      running: false
    });
  }
});

// ============================================================================
// AEE Envelope Storage API
// ============================================================================

/**
 * AEE DATA RETENTION POLICY
 * ─────────────────────────
 * Envelopes are APPEND-ONLY. There is no DELETE endpoint.
 * Never add a bulk-delete or purge route without explicit user confirmation.
 * The /aee/conversations endpoint must never filter by correlation ID prefix.
 * All conversation types (CONV_, UUID, wf-, SHELL_, TERM_, etc.) must be returned.
 *
 * If you need to reduce DB size, use archival (move to cold storage), not deletion.
 */

// Store a single envelope
// SEC-PLUGIN-TRUST H2: gated by requireAeeAuth() — see utils/httpAuth.js.
// Enforcement is OFF by default (AEE_ENDPOINT_AUTH_ENFORCE=true to enforce);
// until flipped, unauthenticated requests are logged, not rejected, and
// `from` is never rewritten, so no legitimate caller silently breaks.
app.post('/aee/store', requireAeeAuth(), (req, res) => {
  // Phase 25: org derived up front (same precedence as the AEE-ORG-1 write
  // below) so DISABLE_TRANSCRIPT_STORAGE's org setting override applies
  // here too, not just the env default. No org context falls back to env.
  // QUOXTRUST cross-tenant fix: a body-supplied org_id is only trustworthy from
  // a service-key caller (req.service) — an orgless/mismatched JWT user could
  // otherwise set body.org_id to any victim org. Mirrors resolveCallerOrgId's
  // rule (lib/callerOrgScope.js).
  const preOrgId = resolveAeeOrgId(req, req.body || {});
  if (platformSettingsStore.getEffectiveFlag(voltDb, preOrgId, 'DISABLE_TRANSCRIPT_STORAGE').on) {
    return res.json({ stored: false, id: req.body?.id, reason: 'storage_disabled' });
  }

  if (!aeeDb) {
    return res.status(503).json({ error: 'AEE storage not available' });
  }

  const envelope = req.body;
  if (!envelope.id || !envelope.v || !envelope.type) {
    return res.status(400).json({ error: 'Invalid envelope format' });
  }

  // Server-side `from` derivation (only once enforcement is on — see
  // deriveAeeFrom jsdoc). A human/JWT caller can no longer forge
  // `from:"human.adam"` or a fake `volt.witness.approved`; a trusted
  // internal service caller (auth/screencap/tasks) keeps its own `from`.
  //
  // QUOXIDENTITY P4 §1: for attach-lease callers (req.user.attach_lease_id),
  // the rewrite is UNCONDITIONAL — attach tokens are new, nothing depends on
  // their prior behavior, and enforcement being off by default must never
  // leave an attach-token AEE envelope carrying an unrewritten/forgeable
  // `from`. Every other caller's behavior is unchanged (still gated behind
  // AEE_ENDPOINT_AUTH_ENFORCE).
  if (req.pluginAuth || req.user?.attach_lease_id || (isAeeAuthEnforced() && req.aeeAuthenticated)) {
    envelope.from = deriveAeeFrom(req, envelope.from);
  }

  try {
    // Encrypt sensitive fields (payload and raw envelope) before storage
    const { payload: encryptedPayload, raw: encryptedRaw } = encryptEnvelopeFields(envelope);

    // AEE-ORG-1: authenticated caller's org wins over a body-supplied org_id
    // (JWT/service auth is the trust boundary); fall back to the envelope's
    // own signals (payload.orgId for AOCL envelopes, then the org.<id>
    // address convention); null if genuinely unknown — never fabricated.
    // Service-key callers with no org and no body org_id legitimately get null.
    // QUOXTRUST cross-tenant fix: body org_id honored only for req.service.
    const orgId = resolveAeeOrgId(req, envelope);

    aeeStatements.insert.run(
      envelope.id,
      envelope.v,
      envelope.ts,
      envelope.type,
      envelope.from,
      envelope.to,
      envelope.intent,
      envelope.corr,
      envelope.reply_to || null,
      encryptedPayload,
      encryptedRaw,
      envelope.priority || 'normal',  // EVD-1c
      orgId
    );

    // WARD: witness this externally-stored envelope, exactly as
    // storeAuditEnvelope does for internal writes (server.js:2787-2792).
    // Previously /aee/store stored-but-never-witnessed, so external AEE POSTs
    // (Matrix room DAG, plugins, other services) never reached the WARD chain.
    // Fail-soft — a witness error must not fail the store (envelope is persisted).
    witnessStoredEnvelope(envelope, orgId, { wardHookAEE, wardHookAOCL });

    // quox#510: materialize VOLT server-side for workflow-run corrs. Self-
    // protecting (see lib/aeeVoltBridge.js) — never throws, never blocks
    // the store response.
    aeeVoltBridge.ingestEnvelope(envelope, orgId);

    res.json({ stored: true, id: envelope.id });
  } catch (err) {
    console.error('[AEE] Store error:', err);
    res.status(500).json({ error: 'Failed to store envelope' });
  }
});

// Batch sync envelopes from browser
// SEC-PLUGIN-TRUST H2: gated by requireAeeAuth() — sibling of /aee/store.
// Leaving /aee/sync open would trivially bypass the /aee/store gate (plan
// §OQ-2). Same log-only-by-default posture as /aee/store.
app.post('/aee/sync', requireAeeAuth(), async (req, res) => {
  // Phase 25: same org-aware check as /aee/store above.
  // QUOXTRUST cross-tenant fix: body org_id honored only for req.service.
  const preOrgId = resolveAeeOrgId(req, null);
  if (platformSettingsStore.getEffectiveFlag(voltDb, preOrgId, 'DISABLE_TRANSCRIPT_STORAGE').on) {
    return res.json({ synced: 0, reason: 'storage_disabled' });
  }

  if (!aeeDb) {
    return res.status(503).json({ error: 'AEE storage not available' });
  }

  const { envelopes } = req.body;
  if (!Array.isArray(envelopes)) {
    return res.status(400).json({ error: 'Expected envelopes array' });
  }

  // QUOXIDENTITY P4 §1: unconditional for attach-lease callers, mirroring
  // /aee/store above; every other caller's behavior is unchanged.
  const enforceAeeAuth = !!req.pluginAuth || !!req.user?.attach_lease_id || (isAeeAuthEnforced() && req.aeeAuthenticated);

  // QUOXTRUST D3 (2026-09-29): ONE storability predicate governs insert, witness
  // AND VOLT-ingest. Previously the witness loop re-checked only `id`, so a
  // malformed-but-id'd envelope was witnessed into WARD without being stored —
  // an orphan the evidence reconciler flags as an unreadable source. Never
  // witness what you did not store.
  const { isStorableAeeEnvelope } = require('./lib/aeeEnvelopeShape.cjs');

  try {
    const insertOne = (envelope) => {
      {
        // AOCL-DISPATCH-5 fix: the stack path emits L0-L10 envelopes via
        // emitLayerEnvelope which may reach the browser cache without a full
        // AEE shape. Skip any envelope missing required fields so better-
        // sqlite3's "too few parameter values" error cannot fire.
        if (!isStorableAeeEnvelope(envelope)) return;
        // SEC-PLUGIN-TRUST H2: server-side `from` derivation (see
        // deriveAeeFrom jsdoc) — only rewrites once enforcement is on, and
        // only after the shape check above (a batch with a missing `from`
        // is still skipped for the unrelated shape-safety reason).
        if (enforceAeeAuth) {
          envelope.from = deriveAeeFrom(req, envelope.from);
        }
        // Encrypt sensitive fields before storage
        const { payload: encryptedPayload, raw: encryptedRaw } = encryptEnvelopeFields(envelope);
        // AEE-ORG-1: authenticated caller's org wins (trust boundary); then a
        // batch-level org_id on the request body; then the envelope's own
        // signals (payload.orgId / org.<id> address); null if unknown — never
        // fabricated. Per-envelope so a mixed batch is scoped correctly.
        // QUOXTRUST cross-tenant fix: body org_id honored only for req.service.
        const orgId = resolveAeeOrgId(req, envelope);
        // ORG-VIEW-SCOPE: stash the resolved orgId back onto the envelope
        // object so the WARD witness loop below (which re-iterates the same
        // `envelopes` array references after this transaction commits) can
        // tag the ward_entries row without recomputing org resolution.
        envelope.org_id = orgId;
        // AOCL-DISPATCH-A1 fix: aeeStatements.insert expects 13 params (EVD-1c
        // added `priority`; AEE-ORG-1 added `org_id`). Sync path was only
        // passing 11 originally, which only showed up after Phase 5 pushed
        // 10x more envelopes through this code path.
        aeeStatements.insert.run(
          envelope.id,
          envelope.v,
          envelope.ts,
          envelope.type,
          envelope.from,
          envelope.to,
          envelope.intent,
          envelope.corr,
          envelope.reply_to || null,
          encryptedPayload || null,
          encryptedRaw || null,
          envelope.priority || 'normal',
          orgId
        );
      }
    };

    // quox#777: chunked + yielding so a big batch cannot block the event loop.
    await require('./lib/aeeSyncChunks.js').runChunked(aeeDb, envelopes, insertOne);
    res.json({ synced: envelopes.length });
  } catch (err) {
    console.error('[AEE] Sync error:', err);
    if (!res.headersSent) res.status(500).json({ error: 'Failed to sync envelopes' });
    return;
  }

  // WARD: witness synced envelopes (fire-and-forget, SPEC §10.3)
  // Runs AFTER the response is sent and OUTSIDE the sync try/catch.
  try {
    wardBatch(() => {
      for (const envelope of envelopes.filter(isStorableAeeEnvelope)) {
        const intent = envelope.intent || '';
        if (intent.startsWith('aocl.')) {
          wardHookAOCL(envelope);
        } else {
          wardHookAEE(envelope);
        }
      }
    });
  } catch (err) {
    console.warn('[AEE/WARD] Witness error (non-fatal):', err.message);
  }

  // quox#510: materialize VOLT server-side for workflow-run corrs. Same
  // fire-and-forget posture as the WARD witness loop above — a bridge
  // failure must never fail the (already-sent) sync response or drop the
  // (already-persisted) AEE envelopes. envelope.org_id was stashed per-
  // envelope inside the insertMany transaction above.
  try {
    aeeVoltBridge.ingestEnvelopes(envelopes.filter(isStorableAeeEnvelope));
  } catch (err) {
    console.warn('[VOLT/AeeBridge] /aee/sync ingest failed (non-fatal):', err.message);
  }
});

// Query envelopes with filters
// SEC-PLUGIN-TRUST H2: gated by requireAeeAuth() — this endpoint decrypts
// and returns envelope payloads, previously to ANY caller with no auth.
// CORTEX-BENCH 2026-10-08: each miss of these dashboard probes runs a synchronous
// aggregate over the AEE/VOLT tables (1.5-3s of event-loop block per miss in a
// live CPU profile), stalling every other collector request. Overview stats do
// not need sub-minute freshness; longer TTLs cut the block rate ~4-5x.
const aeeStatusProbeCache = require('./lib/statusProbeCache.js').createTtlCache({ ttlMs: 60000 });
const AEE_QUERY_TIMEOUT_MS = parseInt(process.env.AEE_QUERY_TIMEOUT_MS, 10) || 10000;
const aeeQueryAsyncCache = require('./lib/sqliteProbeWorker.js').createAsyncProbeCache({ ttlMs: 60000 });
app.get('/aee/query', requireAeeAuth(), async (req, res) => {
  if (!aeeDb) {
    return res.status(503).json({ error: 'AEE storage not available' });
  }

  // fleet #386: `corr` filter. `aee conversations` lists correlation IDs but
  // there was no way to then read one, so the natural list -> pick -> read
  // workflow dead-ended. corr is the causality key of the AEE protocol, so
  // filtering on it is the obvious drill-down.
  const { type, intent, from, to, after, before, corr, limit = 100 } = req.query;

  try {
    // AEE-ORG-1 (READ-SCOPE): canonical org source (matches the posture
    // endpoint). No resolvable org -> honest empty result, never every
    // tenant's envelopes (previously the case for ANY authed caller, since
    // the envelopes table had no org_id column at all).
    // GOV-TRUTH tail: trusted service-key callers (complianceTools.js, AUDITUS
    // AEE/AOCL tools) authenticate via X-Service-Key and pass ?org_id=<org> —
    // req.user is unset for them, so they previously always got orgId=null
    // (empty results). JWT users still short-circuit on req.user.org_id and
    // can never target another org's data via query string.
    const orgId = req.user?.org_id || (req.service ? req.query.org_id : null) || null;

    const intentFilter = buildIntentFilter(intent);
    const queryParams = {
      type: type || null,
      intent: intentFilter.like,
      from: from || null,
      to: to || null,
      after: after || null,
      before: before || null,
      corr: corr || null,
      orgId,
      limit: parseInt(limit, 10),
    };
    // Incident 2026-10-06: the status bar polls ?intent=aocl.&limit=1 every
    // ~10s per client and each call full-scans envelopes (leading-wildcard
    // LIKE). Probe-shaped reads (limit <= 5) come from a 15s per-org cache.
    const prefixParams = intentFilter.mode === 'prefix'
      ? (() => { const { intent: _i, ...rest } = queryParams; return { ...rest, intentLo: intentFilter.lo, intentHi: intentFilter.hi }; })()
      : null;
    const intentOnly = !type && !from && !to && !after && !before && !corr;
    // QUOXON-AEE 2026-10-14: ?corr= (and any non-intent filter) ran on the main
    // thread over a planner-hostile OR-NULL statement and blocked the collector
    // 781 s. Every read now runs in the read-only probe worker with a hard
    // timeout (AEE_QUERY_TIMEOUT_MS, default 10 s -> 503), and the non-prefix
    // SQL carries only the active filters so the planner can use the corr/ts
    // indexes (lib/statusProbeSql.js buildQueryOrgScoped).
    const probeSpec = () => {
      if (!prefixParams) { const q = statusProbeSql.buildQueryOrgScoped(queryParams); return [q.sql, q.params]; }
      if (intentOnly) return [statusProbeSql.queryOrgIntentPrefixLatest, { orgId, intentLo: prefixParams.intentLo, intentHi: prefixParams.intentHi, limit: prefixParams.limit }];
      // quox#1047: prefix + other filters splice only the active predicates (the OR-NULL
      // queryOrgScopedPrefix shape timed out to 503 on ?intent=aocl.&after=...).
      const q = statusProbeSql.buildQueryOrgPrefix(prefixParams); return [q.sql, q.params];
    };
    const runBounded = () => { const [sqlText, params] = probeSpec(); return runProbe(AEE_DB_PATH, sqlText, params, { mode: 'all', timeoutMs: AEE_QUERY_TIMEOUT_MS }); };
    const rows = !orgId
      ? []
      : (queryParams.limit <= 5
        ? await aeeQueryAsyncCache.get(JSON.stringify(queryParams), runBounded)
        : await runBounded());

    // Decrypt each envelope, filter out any that failed decryption
    let envelopes = rows
      .map(row => decryptEnvelopeRow(row))
      .filter(env => env !== null);

    // SEC-PLUGIN-TRUST H2 (org-filter gap — CLOSED by AEE-ORG-1): the
    // envelopes table now has an org_id column (migrations/aee/
    // 002-envelopes-org-id-column.sql), tagged at the storeAuditEnvelope
    // choke-point (lib/aeeOrgScoping.js), and every row above has already
    // been filtered to `org_id = req.user.org_id` via queryOrgScoped — real
    // per-row multi-tenant isolation, not the partial from/to-address
    // mitigation this comment used to describe.
    //
    // The block below is now a SECOND, narrower filter kept for federated
    // cross-org chain reads: envelopes using the `org.<org_id>` address
    // convention (lib/chainGuards/crossOrgVerifier.js) can legitimately carry
    // a `from`/`to` address for a DIFFERENT org than the row's own org_id
    // (e.g. an inbound federated envelope stored under the receiving org).
    // This existing address-based check still applies on top of the new
    // row-level filter so a caller can't use an org.<other> address to read
    // a federated envelope meant for a counterpart org. Only applies to
    // req.user (JWT) callers, matching the trust-boundary convention used
    // elsewhere in this file.
    if (isAeeAuthEnforced() && req.aeeAuthenticated && req.user?.org_id) {
      const callerOrg = req.user.org_id;
      const orgOf = (addr) => (typeof addr === 'string' && addr.startsWith('org.')) ? addr.slice(4) : null;
      envelopes = envelopes.filter(env => {
        const fromOrg = orgOf(env.from);
        const toOrg = orgOf(env.to);
        if (fromOrg && fromOrg !== callerOrg) return false;
        if (toOrg && toOrg !== callerOrg) return false;
        return true;
      });
    }

    // GOV-TRUTH tail (#3): `count` above was `envelopes.length` — capped by
    // `limit` (e.g. the sidebar's aoclCount used ?limit=500 and read `.count`
    // as if it were the true total, so any org with >500 matching envelopes
    // showed a flat "500" artifact, not its real count). `total` is the real
    // org-scoped row count via countOrgScoped, independent of `limit`.
    //
    // fleet #393/#409 second profile pass: after the UNION rewrite the .all
    // query left the profile but this COUNT was still 87.6% of collector CPU
    // — the route's intent filter is a CONTAINS pattern (`%aocl.%`), which no
    // index can serve, so every count walks ~1.6M intent values. Pollers
    // (footer AOCLStatusBadge, 30s per open tab — which reads only `count`
    // and ignores `total` entirely) re-paid that scan every time. A total
    // for status pills does not need per-request freshness: cache per
    // filter-set for 60s. Bounded size, cleared wholesale — this is a
    // throttle, not a datastore.
    const countKey = JSON.stringify([orgId, type || null, intent || null, from || null, to || null, after || null, before || null, corr || null]);
    const cachedTotal = aeeCountCache.get(countKey);
    let total;
    if (cachedTotal && (Date.now() - cachedTotal.at) < AEE_COUNT_CACHE_TTL_MS) {
      total = cachedTotal.total;
    } else {
      const countParams = {
        type: type || null,
        intent: intentFilter.like,
        from: from || null,
        to: to || null,
        after: after || null,
        before: before || null,
        corr: corr || null,
        orgId,
      };
      if (!orgId) {
        total = 0;
      } else {
        let countSql; let countArgs;
        if (intentFilter.mode === 'prefix') {
          const onlyIntent = !type && !from && !to && !after && !before && !corr;
          if (onlyIntent) {
            countSql = statusProbeSql.countOrgIntentPrefix;
            countArgs = { orgId, intentLo: intentFilter.lo, intentHi: intentFilter.hi };
          } else {
            // quox#1047: spliced, index-served count (see buildCountOrgPrefix).
            const q = statusProbeSql.buildCountOrgPrefix({ ...countParams, intentLo: intentFilter.lo, intentHi: intentFilter.hi });
            countSql = q.sql; countArgs = q.params;
          }
        } else {
          const q = statusProbeSql.buildCountOrgScoped(countParams);
          countSql = q.sql; countArgs = q.params;
        }
        total = (await runProbe(AEE_DB_PATH, countSql, countArgs, { mode: 'get', timeoutMs: AEE_QUERY_TIMEOUT_MS })).total;
      }
      if (aeeCountCache.size >= 500) aeeCountCache.clear();
      aeeCountCache.set(countKey, { total, at: Date.now() });
    }

    res.json({ count: envelopes.length, total, envelopes });
  } catch (err) {
    if (/probe timeout|probe worker restarted/.test(err && err.message)) {
      console.error('[AEE] Query timed out (narrow the filters, e.g. add corr/after/before):', err.message);
      return res.status(503).json({ error: 'AEE query timed out; narrow the filters (corr, after, before, intent)' });
    }
    console.error('[AEE] Query error:', err);
    res.status(500).json({ error: 'Failed to query envelopes' });
  }
});

// Get recent conversations
// AEE-ORG-1 (READ-SCOPE): was unauthenticated + unscoped — any caller saw
// every org's conversations. Gated behind requireAeeAuth() (same as
// /aee/query) and org-scoped to req.user.org_id; no resolvable org -> honest
// empty list, never global.
app.get('/aee/conversations', requireAeeAuth(), (req, res) => {
  if (!aeeDb) {
    return res.status(503).json({ error: 'AEE storage not available' });
  }

  const { limit = 50, offset = 0 } = req.query;
  const orgId = req.user?.org_id || null;

  try {
    // NB: getConversations also fixes a pre-existing `LIMIT ? OFFSET ?`
    // param-count bug (this route previously passed only 1 of 2 required
    // bind values and would throw if ever invoked) — necessary to make the
    // org-scoped statement callable at all.
    const rows = orgId
      ? aeeStatements.getConversations.all(orgId, parseInt(limit, 10) || 50, parseInt(offset, 10) || 0)
      : [];
    res.json({ count: rows.length, conversations: rows });
  } catch (err) {
    console.error('[AEE] Conversations error:', err);
    res.status(500).json({ error: 'Failed to get conversations' });
  }
});

// Get recent conversations with first-message preview (for cross-device ActivityView)
// Supports pagination via ?limit=30&offset=0 and ?includeNoise=true for unfiltered view
// TRUST-GATE-1.27 (2026-07-05): the conversation GROUP BY scans all 906K+
// envelopes (~4s) and this endpoint is POLLED by the dashboard — an open tab
// alone pinned a full core (found via inspector hot-stack after the 1.26 fix
// exposed it as the remaining burner). Single-flight + short TTL: polls hit
// the cache; at most one scan per TTL window runs, and concurrent requests
// during a scan reuse the in-flight result instead of piling on.
const _convListCache = new Map(); // key → { at, rows, total }
const CONV_LIST_CACHE_TTL_MS = 30000;

// ACTIVITY-TABS-2: valid log-type families for the Activity Centre tabs.
// 'chats' (real user<->agent CONV_ conversations) is the default and
// replaces the old combined 'conversations' family, which used to lump
// chats + objectives + workflows together — see the taxonomy note on the
// aeeStatements block above for the full precedence rule and SESSION_
// classification evidence. Legacy callers still sending
// ?family=conversations fall through to the 'chats' default below.
const CONV_FAMILIES = ['chats', 'objectives', 'workflows', 'governance', 'tools', 'rooms', 'system'];

// AEE-ORG-1 (READ-SCOPE): orgId is now part of both the cache key AND the
// bound query params — a shared in-process cache keyed without orgId would
// leak orgA's row set to orgB on a cache hit (a cross-tenant leak worse than
// the unscoped query itself). No resolvable org -> honest empty/zero, cached
// like any other result (never falls back to global data).
function getConversationRowsCached(family, includeNoise, limit, offset, orgId) {
  const key = `${orgId || 'none'}:${family}:${includeNoise}:${limit}:${offset}`;
  const hit = _convListCache.get(key);
  if (hit && Date.now() - hit.at < CONV_LIST_CACHE_TTL_MS) return hit;

  if (!orgId) {
    const entry = { at: Date.now(), rows: [], total: 0 };
    _convListCache.set(key, entry);
    return entry;
  }

  let listStmt;
  let countStmt = null;
  switch (family) {
    case 'objectives':
      listStmt = aeeStatements.getConversationsObjectives;
      countStmt = aeeStatements.countConversationsObjectives;
      break;
    case 'workflows':
      listStmt = aeeStatements.getConversationsWorkflows;
      countStmt = aeeStatements.countConversationsWorkflows;
      break;
    case 'governance':
      listStmt = aeeStatements.getConversationsGovernance;
      countStmt = aeeStatements.countConversationsGovernance;
      break;
    case 'tools':
      listStmt = aeeStatements.getConversationsTools;
      countStmt = aeeStatements.countConversationsTools;
      break;
    case 'rooms':
      listStmt = aeeStatements.getConversationsRooms;
      countStmt = aeeStatements.countConversationsRooms;
      break;
    case 'system':
      listStmt = aeeStatements.getConversationsSystem;
      countStmt = aeeStatements.countConversationsSystem;
      break;
    case 'chats':
    default:
      listStmt = includeNoise ? aeeStatements.getConversationsChatsAll : aeeStatements.getConversationsChats;
      countStmt = includeNoise ? aeeStatements.countConversationsChatsAll : aeeStatements.countConversationsChats;
  }

  const rows = listStmt.all(orgId, limit, offset);
  let total = 0;
  try {
    total = countStmt ? countStmt.get(orgId).total : aeeStatements.statsOrgScoped.get(orgId).conversations;
  } catch { /* non-critical */ }
  const entry = { at: Date.now(), rows, total };
  _convListCache.set(key, entry);
  // Bound the cache — distinct offsets from pagination could grow it.
  if (_convListCache.size > 50) {
    const oldest = [..._convListCache.entries()].sort((a, b) => a[1].at - b[1].at)[0];
    _convListCache.delete(oldest[0]);
  }
  return entry;
}

// AEE-ORG-1 (READ-SCOPE): was unauthenticated + unscoped — any caller saw
// every org's conversations (with first-message preview text, decrypted).
// Gated behind requireAeeAuth() and org-scoped to req.user.org_id.
app.get('/aee/conversations/enriched', requireAeeAuth(), (req, res) => {
  if (!aeeDb) {
    return res.status(503).json({ error: 'AEE storage not available' });
  }

  const limit = parseInt(req.query.limit, 10) || 30;
  const offset = parseInt(req.query.offset, 10) || 0;
  const includeNoise = req.query.includeNoise === 'true';
  const family = CONV_FAMILIES.includes(req.query.family) ? req.query.family : 'chats';
  const orgId = req.user?.org_id || null;

  try {
    const { rows, total } = getConversationRowsCached(family, includeNoise, limit, offset, orgId);

    const enriched = rows
      .filter(row => row.corr)
      .map(row => {
        // Get first few envelopes to find a chat message (not AOCL event)
        const allEnvs = aeeStatements.getByCorr.all(row.corr);
        let firstChatEnvelope = null;
        let aoclStartEnvelope = null; // fallback for AOCL-only conversations (CHAT_*)

        // For OBJ_ conversations, find the 'created' envelope to extract title
        const isObjective = row.corr && row.corr.startsWith('OBJ_');
        const isBrowserQ = row.corr && row.corr.startsWith('BQ_');

        // Search first 20 envelopes for a displayable message, while keeping
        // a reference to aocl.run.start for the AOCL-only fallback path.
        // AEE-CORE fix: prefer envelopes whose payload has real text. A
        // `quox.session.started` with empty payload is a marker, not content.
        for (let i = 0; i < Math.min(allEnvs.length, 20); i++) {
          const decrypted = decryptEnvelopeRow(allEnvs[i]);
          if (!decrypted || !decrypted.intent) continue;

          if (decrypted.intent === 'aocl.run.start' && !aoclStartEnvelope) {
            aoclStartEnvelope = decrypted;
          }

          if (!decrypted.intent.startsWith('aocl.')) {
            // For objectives, prefer the 'created' envelope (has title)
            if (isObjective && decrypted.intent === 'quox.objective.created') {
              firstChatEnvelope = decrypted;
              break;
            }
            // For BQ conversations, prefer the created or completed envelope (has text)
            if (isBrowserQ && (decrypted.intent === 'quox.browser.objective.created' || decrypted.intent === 'quox.browser.objective.completed')) {
              firstChatEnvelope = decrypted;
              break;
            }
            // Has real text → this is the best candidate; take it immediately
            // over any earlier empty-payload marker.
            const txt = decrypted.payload?.text || decrypted.payload?.query_preview || decrypted.payload?.queryPreview;
            if (txt && String(txt).trim().length > 0) {
              firstChatEnvelope = decrypted;
              break;
            }
            // No text yet, but keep the first non-AOCL envelope as a fallback
            if (!firstChatEnvelope) {
              firstChatEnvelope = decrypted;
            }
          }
        }

        // AEE-CORE: if firstChatEnvelope ended up being an empty-payload
        // session marker AND we have a richer aocl.run.start (with the real
        // prompt), promote the aocl.run.start to firstMessage instead.
        if (firstChatEnvelope && aoclStartEnvelope) {
          const currentText = firstChatEnvelope.payload?.text || firstChatEnvelope.payload?.query_preview;
          const startText = aoclStartEnvelope.payload?.text || aoclStartEnvelope.payload?.queryPreview;
          if ((!currentText || !String(currentText).trim()) && startText && String(startText).trim()) {
            firstChatEnvelope = aoclStartEnvelope;
          }
        }

        // For OBJ_ conversations, inject the title into payload.text for summary display
        if (isObjective && firstChatEnvelope) {
          const title = firstChatEnvelope.payload?.title;
          if (title && !firstChatEnvelope.payload?.text) {
            firstChatEnvelope = {
              ...firstChatEnvelope,
              payload: { ...firstChatEnvelope.payload, text: title }
            };
          }
        }

        // For BQ_ conversations, ensure text is present from intent field
        if (isBrowserQ && firstChatEnvelope && !firstChatEnvelope.payload?.text) {
          const intent = firstChatEnvelope.payload?.intent;
          if (intent) {
            firstChatEnvelope = {
              ...firstChatEnvelope,
              payload: { ...firstChatEnvelope.payload, text: `Browser-Q: ${intent}` }
            };
          }
        }

        // Fallback: synthesise a firstMessage from aocl.run.start for AOCL-only
        // conversations so the UI shows something descriptive rather than "undefined".
        //
        // Prefer the envelope's real payload.text / queryPreview (set by
        // aoclContext.js after the AEE-CORE-1 fix) over the synthesised
        // "N char query" label — the real prompt is always more useful.
        if (!firstChatEnvelope && aoclStartEnvelope) {
          const p = aoclStartEnvelope.payload || {};
          const realText = (p.text || p.queryPreview || '').trim();
          let labelText = realText;
          if (!labelText) {
            const agent = p.agentId || 'agent';
            const model = [p.provider, p.model].filter(Boolean).join('/');
            const qlen = p.queryLength ? `${p.queryLength} char query` : 'query';
            labelText = model ? `${agent} · ${qlen} · ${model}` : `${agent} · ${qlen}`;
          }
          firstChatEnvelope = {
            ...aoclStartEnvelope,
            payload: { ...p, text: labelText }
          };
        }

        // AEE-CORE-2.3: rollup breakdown so the list row can show
        // "chat · 2 tools · 3 AOCL layers · 1 policy" without the frontend
        // having to fetch every conversation's envelopes.
        //
        // QOBS-1d: severity rollup — counts by critical/warn/info/debug —
        // computed from the SAME already-fetched groupedByCorr rows (no
        // extra query). Cheaper-honest-path note: grouped rows carry only
        // {intent, type, n}, so the payload-dependent nuances in the
        // frontend's per-envelope deriveSeverity (policy-denial payload
        // inspection, ERR_ corr-prefix override, explicit priority
        // override) aren't available here — see
        // services/collector/lib/envelopeSeverity.js for the documented
        // trade-off. This rollup is a best-effort aggregate for the
        // conversation list row; the frontend's per-envelope
        // deriveSeverity remains authoritative for the detail chain.
        let breakdown = null;
        let severity = null;
        try {
          const { computeBreakdownFromGrouped } = require('./lib/envelopeBreakdown.js');
          const { computeSeverityFromGrouped } = require('./lib/envelopeSeverity.js');
          const groupedRows = aeeStatements.groupedByCorr.all(row.corr);
          breakdown = computeBreakdownFromGrouped(groupedRows);
          severity = computeSeverityFromGrouped(groupedRows);
        } catch (brkErr) {
          console.warn('[AEE] breakdown/severity skipped for', row.corr, '—', brkErr.message);
        }

        return {
          corr: row.corr,
          first_ts: row.first_ts,
          last_ts: row.last_ts,
          count: row.count,
          firstMessage: firstChatEnvelope || null,
          breakdown,
          severity,
        };
      });

    res.json({ count: enriched.length, total, offset, limit, family, conversations: enriched });
  } catch (err) {
    console.error('[AEE] Enriched conversations error:', err);
    res.status(500).json({ error: 'Failed to get enriched conversations' });
  }
});

// Get AEE stats
// AEE-ORG-1 (READ-SCOPE): previously unauthenticated and returned GLOBAL
// counts (aeeStatements.stats — no WHERE org_id) to ANY caller, feeding the
// dashboard's sidebar/status badges from every tenant's data. Now gated
// behind requireAeeAuth() (same middleware as /aee/query) and scoped to
// req.user.org_id via a dedicated statsOrgScoped statement; no resolvable
// org -> honest zeros, never the old global count. Response shape is
// unchanged so useComplianceData / status badges keep working.
// PERF (2026-07-19): statsOrgScoped is a COUNT(DISTINCT corr)+MIN/MAX aggregate
// over the whole envelopes table (~1.2M rows) — a synchronous ~6s better-sqlite3
// query that BLOCKS the event loop. The dashboard status badges poll this, so
// under multiple sessions the 6s blocks backlogged and wedged the whole
// collector (event loop never free -> /health 000). It's a status badge, not a
// realtime figure, so cache the result per-org for AEE_STATS_CACHE_TTL_MS and
// serve subsequent polls from cache (at most one cold query per org per window).
const AEE_STATS_CACHE_TTL_MS = Number(process.env.AEE_STATS_CACHE_TTL_MS) || 300000;
const aeeStatsCache = new Map(); // cacheKey -> { value, expiresAt }
app.get('/aee/stats', requireAeeAuth(), async (req, res) => {
  if (!aeeDb) {
    return res.status(503).json({ error: 'AEE storage not available' });
  }

  try {
    // Trusted service-key callers (the aee_get_stats tool) carry the org as ?org_id=; JWT users never can.
    const orgId = req.user?.org_id || (req.service ? req.query.org_id : null) || null;
    const cacheKey = orgId || '__no_org__';
    const now = Date.now();
    const cached = aeeStatsCache.get(cacheKey);
    if (cached && cached.expiresAt > now) {
      return res.json(cached.value);
    }
    const stats = orgId
      ? await aeeStatsAsyncCache.get(`aee:${orgId}`, () => runProbe(AEE_DB_PATH, aeeStatements.statsOrgScoped.source, [orgId]))
      : { total: 0, conversations: 0, oldest: null, newest: null };
    const payload = {
      total_envelopes: stats.total || 0,
      conversations: stats.conversations || 0,
      oldest_ts: stats.oldest || null,
      newest_ts: stats.newest || null
    };
    aeeStatsCache.set(cacheKey, { value: payload, expiresAt: now + AEE_STATS_CACHE_TTL_MS });
    res.json(payload);
  } catch (err) {
    console.error('[AEE] Stats error:', err);
    res.status(500).json({ error: 'Failed to get stats' });
  }
});

// Dashboard summary — server-source 24h analytics for /dashboard (KPIs +
// activity feed). Org-scoped; honest zeros when the org has no envelopes.
app.get('/aee/dashboard-summary', requireAeeAuth(), (req, res) => {
  if (!aeeDb) {
    return res.status(503).json({ error: 'AEE storage not available' });
  }
  try {
    const orgId = req.user?.org_id || null;
    const windowHours = Math.min(Math.max(parseInt(req.query.window_hours, 10) || 24, 1), 168);
    if (!orgId) {
      return res.json({ window_hours: windowHours, total_conversations: 0, success_rate: 0, total_envelopes: 0, recent_events: [] });
    }
    const since = new Date(Date.now() - windowHours * 3600 * 1000).toISOString();
    const conv = aeeStatements.dashboardConvOrgScoped.get(orgId, since) || {};
    const conversations = conv.conversations || 0;
    const success = conv.success_conversations || 0;
    const successRate = conversations > 0 ? Math.round((success / conversations) * 100) : 0;
    const envCount = aeeStatements.dashboardEnvCountOrgScoped.get(orgId, since)?.total || 0;
    const recent = aeeStatements.dashboardRecentOrgScoped.all(orgId, since) || [];
    res.json({
      window_hours: windowHours,
      total_conversations: conversations,
      success_rate: successRate,
      total_envelopes: envCount,
      recent_events: recent.map(r => ({ corr: r.corr, intent: r.intent, type: r.type, ts: r.ts })),
    });
  } catch (err) {
    console.error('[AEE] dashboard-summary error:', err);
    res.status(500).json({ error: 'Failed to get dashboard summary' });
  }
});

// ============================================================================
// NQ-5b: NOC tool outcomes — read side.
// Every NOC tool call (docker/proxmox/ssh/network/etc.) is recorded to
// noc_tool_outcomes by lib/nocOutcomeRecorder.js. These endpoints are the
// consumer — turns the previously write-only table into queryable ops
// signal (which tools are failing / slow / flaky). Follows the /aee/stats
// convention (no auth — internal ops read, same trust boundary as the AEE
// query endpoints above).
// ============================================================================

// List recent NOC tool outcomes, optionally filtered by tool/agent/org/success/since.
app.get('/noc/tool-outcomes', (req, res) => {
  try {
    const { tool, agent, orgId, since } = req.query;
    let success;
    if (req.query.success === 'true') success = true;
    else if (req.query.success === 'false') success = false;

    const result = listNocOutcomes({
      tool: tool || null,
      agent: agent || null,
      orgId: orgId || null,
      success,
      since: since || null,
      limit: req.query.limit,
      offset: req.query.offset,
    });
    res.json(result);
  } catch (err) {
    console.error('[NOC Outcomes] List error:', err);
    res.status(500).json({ error: 'Failed to list tool outcomes' });
  }
});

// Per-tool success rate / avg duration / error counts over a rolling window.
app.get('/noc/tool-outcomes/stats', (req, res) => {
  const window = req.query.window || '24h';
  if (!['1h', '24h', '7d', '30d'].includes(window)) {
    return res.status(400).json({ error: 'window must be 1h, 24h, 7d, or 30d' });
  }
  try {
    const result = getNocOutcomeStats({
      window,
      tool: req.query.tool || null,
      agent: req.query.agent || null,
      orgId: req.query.orgId || null,
    });
    res.json(result);
  } catch (err) {
    console.error('[NOC Outcomes] Stats error:', err);
    res.status(500).json({ error: 'Failed to get tool outcome stats' });
  }
});

// ============================================================================
// AEE-CORE-4.2: retention GC
// ============================================================================

/**
 * Run one pass of retention garbage collection.
 * Iterates over distinct intents, resolves TTL for each, deletes any
 * envelopes with ts older than (now - TTL). Intents with Infinity TTL are
 * skipped. Returns a per-intent summary.
 *
 * This function is pure enough to be called from a schedule, an admin
 * endpoint, or a one-shot script — it doesn't touch HTTP state.
 */
let retentionGcRunning = false;
async function runRetentionGc() {
  if (!aeeDb) return { error: 'AEE storage not available' };
  // QUOXTRUST D3 (2026-09-29): witnessed envelopes are EXEMPT from prune and the
  // pass is FAIL-SAFE (skips if ward.db can't be attached). The per-intent
  // TTL/delete logic lives in lib/aeeRetentionGc.cjs so it is unit-testable.
  // INCIDENT-700 (2026-10-06): the helper is incremental + cooperative (yields).
  if (retentionGcRunning) return { skipped: 'already_running' };
  if (!ensureWardAttachedForPrune()) {
    console.warn('[AEE GC] SKIPPED — witnessed-source exemption unavailable (ward.db not attached); refusing to prune blind (evidence protection)');
    return { skipped: 'ward_unavailable' };
  }
  const { resolveRetention } = require('./lib/retentionPolicy.js');
  const { runWitnessedExemptGc, setLastCompletedMs } = require('./lib/aeeRetentionGc.cjs');
  retentionGcRunning = true;
  try {
    const res = await runWitnessedExemptGc({ aeeDb, resolveRetention, wardAttached: true });
    if (res.completed) {
      try { setLastCompletedMs(aeeDb, Date.now()); } catch (e) { console.warn('[AEE GC] could not persist last-run:', e.message); }
    }
    console.log(`[AEE GC] run: deleted=${res.total_deleted || 0} batches=${res.batches || 0} wall_ms=${res.wall_ms || 0} max_slice_ms=${res.max_slice_ms || 0} capped=${!!res.capped} intents=${(res.by_intent || []).length} (witnessed-exempt)`);
    return res;
  } finally {
    retentionGcRunning = false;
  }
}

/**
 * Admin endpoint — surface the active retention policy.
 */
app.get('/aee/admin/retention/policy', requireServiceOrUserAuth(), (req, res) => {
  const { describePolicy } = require('./lib/retentionPolicy.js');
  res.json({ rules: describePolicy() });
});

/**
 * Admin endpoint — run one GC pass on demand. Protected by service key
 * so accidental browser fetches can't fire it.
 */
app.post('/aee/admin/retention/run', requireServiceOrUserAuth(), async (req, res) => {
  try {
    const result = await runRetentionGc();
    res.json(result);
  } catch (err) {
    console.error('[AEE GC] run error:', err);
    res.status(500).json({ error: 'GC run failed' });
  }
});

const { envelopeRowVisibleToOrg } = require('./lib/aeeOrgReadScope');
// quox#1013: the VOLT run routes accept the workflow engine execution id a user holds (or a corr),
// not only a VR_ id. The execution's corr comes from QuoxFlow (indexed lookup); see lib/voltRunResolve.js.
const { createVoltRunResolver, notFoundMessage: voltRunNotFoundMessage } = require('./lib/voltRunResolve');
const voltRunResolver = voltDb ? createVoltRunResolver(voltDb) : null;
async function fetchQuoxflowExecutionForVolt(id, orgId) {
  const key = process.env.INTERNAL_SERVICE_KEY || '';
  const r = await fetch(`${process.env.QUOXFLOW_URL || 'http://quoxflow:3200'}/api/executions/${encodeURIComponent(id)}`, {
    headers: { ...(key ? { 'X-Service-Key': key } : {}), ...(orgId ? { 'X-Org-ID': orgId } : {}) },
    signal: AbortSignal.timeout(5000),
  });
  if (r.status === 404) return null; // QuoxFlow does not know it: not an execution id
  if (!r.ok) throw new Error(`QuoxFlow ${r.status}`); // could not ask: the resolver falls back
  const d = await r.json();
  return d && (d.data || d);
}
function resolveVoltRunForOrg(id, orgId) {
  return voltRunResolver.resolve(id, {
    visible: (row) => envelopeRowVisibleToOrg(row, orgId),
    fetchExecution: (execId) => fetchQuoxflowExecutionForVolt(execId, orgId),
  });
}

// AEE-ORG-1 (tenant isolation) for corr-addressed conversation reads. Returns
// the decrypted envelopes for a conversation, scoped to the caller's org:
//   - primary corr rows: included when they belong to `orgId` OR are untagged
//     (org_id NULL — the legacy pre-tagging bucket, matching /aee/query's
//     queryOrgScoped semantics). A corr is one conversation's causality key, so
//     it does not collide across orgs; the NULL branch only re-admits this same
//     conversation's own legacy rows.
//   - sibling-corr join rows: STRICT `org_id = orgId` only (no NULL branch).
//     The sibling match is a broad time-window + LIKE-prefix heuristic, so
//     admitting untagged rows there could pull a DIFFERENT tenant's legacy
//     activity into the view — that is the exact cross-tenant vector we close.
// orgId null (no resolvable org) -> [] (see nothing, never every tenant).
function getScopedCorrEnvelopes(orgId, primaryCorr, { includeSiblings = true } = {}) {
  if (!orgId || !aeeDb) return [];
  const primaryRows = aeeStatements.getByCorr.all(primaryCorr)
    .filter(r => envelopeRowVisibleToOrg(r, orgId));
  let envelopes = primaryRows.map(r => decryptEnvelopeRow(r)).filter(Boolean);
  if (includeSiblings) {
    try {
      const { getSiblingLikePatterns, getSiblingTimeWindow } = require('./lib/corrSiblings.js');
      const patterns = getSiblingLikePatterns(primaryCorr);
      const window = getSiblingTimeWindow(primaryCorr);
      if (patterns.length > 0 && window) {
        const sibStmt = aeeDb.prepare(`SELECT * FROM envelopes WHERE ts >= ? AND ts <= ? AND corr LIKE ? AND corr != ? AND org_id = ? ORDER BY ts ASC`);
        const tsMinIso = new Date(window.min).toISOString();
        const tsMaxIso = new Date(window.max).toISOString();
        for (const likePattern of patterns) {
          const sibRows = sibStmt.all(tsMinIso, tsMaxIso, likePattern, primaryCorr, orgId);
          for (const row of sibRows) {
            const e = decryptEnvelopeRow(row);
            if (e) envelopes.push(e);
          }
        }
      }
    } catch (sibErr) {
      console.warn('[AEE] sibling join skipped:', sibErr.message);
    }
  }
  envelopes.sort((a, b) => (a.ts || '').localeCompare(b.ts || ''));
  return envelopes;
}

/**
 * AEE-CORE-6.2: evidence bundle export.
 *
 * Returns a single self-contained JSON bundle for a conversation with
 * everything an auditor needs to verify the chain — envelopes, AOCL
 * policy events, VOLT run + events + canonical bundle, WARD receipt
 * (if witnessed), and a manifest with integrity claims. The companion
 * verify.sh script (served at /aee/tools/verify.sh) hashes the payload
 * and cross-checks against the claimed head_hash.
 */
app.get('/aee/conversation/:corr/bundle', requireServiceOrUserAuth(), async (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'AEE storage not available' });
  try {
    const primaryCorr = req.params.corr;
    // AEE-ORG-1 (tenant isolation): scope the bundle to the caller's org. An
    // empty result for a JWT/cookie caller means the conversation is not theirs
    // -> 404, which also prevents the VOLT/WARD lookups below from disclosing
    // another org's run metadata for that corr.
    const orgId = req.user?.org_id || (req.service ? req.query.org_id : null) || null;
    const envelopes = getScopedCorrEnvelopes(orgId, primaryCorr);
    if (!envelopes.length) return res.status(404).json({ error: 'Conversation not found' });

    // Policy decisions — any envelope whose intent indicates a policy step.
    const policies = envelopes.filter(e =>
      e.intent === 'aocl.layer.L3.complete' ||
      (e.intent || '').startsWith('aocl.policy.')
    );

    // VOLT — run + events + bundle (if present)
    let voltRun = null;
    let voltEvents = [];
    let voltBundle = null;
    if (voltStatements) {
      voltRun = voltStatements.getRunByCorr.get(primaryCorr) || null;
      if (voltRun?.run_id) {
        voltEvents = voltStatements.getRunEvents.all(voltRun.run_id) || [];
        const bundleRow = voltStatements.getRunBundle.get(voltRun.run_id);
        if (bundleRow) {
          try { voltBundle = { ...bundleRow, data: JSON.parse(bundleRow.data) }; }
          catch { voltBundle = bundleRow; }
        }
      }
    }
    // WARD-RECEIPT-GAP: look the receipt up on the WARD chain by the
    // bundle's own bundle_id instead of trusting an embedded `ward_receipt`
    // field — nothing writes that field (autoBundleOnComplete calls
    // wardHookVOLT() fire-and-forget and drops the return value). This also
    // makes bundles written BEFORE this fix report correctly, because the
    // ward_entries row was created at witness time regardless of whether
    // the bundle JSON ever recorded it — see lib/wardReceiptResolver.js.
    let wardResult = { witnessed: false, receipt: null };
    if (voltBundle?.data?.manifest?.bundle_id && typeof getWardService === 'function') {
      try {
        const ward = await getWardService();
        wardResult = resolveWardReceiptForBundle(
          {
            getEntryBySource: ward.getEntryBySource,
            payloadHash: ward.payloadHash,
            chainId: ward.getHookChainId ? ward.getHookChainId() : null,
            getCoveringTip: ward.getCoveringTip, // quox#515: signed-tip context on the receipt
          },
          voltBundle.data.manifest
        );
      } catch (err) {
        console.warn('[AEE] WARD receipt lookup failed (non-fatal, reports unwitnessed):', err.message);
      }
    }
    const wardReceipt = wardResult.receipt;

    // Integrity — SHA-256 of the canonical envelope list so verifiers can
    // recompute and compare. Fields are stable per envelope.
    const crypto = require('crypto');
    const envelopesCanonical = JSON.stringify(
      // quox#516: every field ?? null — JSON.stringify drops undefined-valued
      // keys while the served jq verifier emits null for absent keys, so an
      // envelope stored without reply_to broke outsider verification on an
      // intact bundle. Absent fields MUST serialize as null.
      envelopes.map(e => ({ id: e.id ?? null, ts: e.ts ?? null, intent: e.intent ?? null, corr: e.corr ?? null, reply_to: e.reply_to ?? null, from: e.from ?? null, to: e.to ?? null }))
    );
    const envelopesHash = crypto.createHash('sha256').update(envelopesCanonical).digest('hex');

    const bundle = {
      bundle_version: '1.0',
      corr: primaryCorr,
      exported_at: new Date().toISOString(),
      exported_by: req.user?.id || 'internal-service',
      envelopes,
      policies: policies.map(p => ({
        ts: p.ts,
        intent: p.intent,
        layer: p.payload?.layer,
        agent: p.payload?.agent,
        decision: p.payload?.proceed === false ? 'denied' : 'allowed',
        matched_policies: p.payload?.matchedPolicies || [],
        warnings: p.payload?.warnings || [],
        duration_ms: p.payload?.duration_ms,
      })),
      volt: voltRun ? {
        run: voltRun,
        events: voltEvents,
        bundle: voltBundle,
      } : null,
      ward: {
        witnessed: !!wardReceipt,
        receipt: wardReceipt,
      },
      manifest: {
        envelope_count: envelopes.length,
        policy_count: policies.length,
        volt_event_count: voltEvents.length,
        ward_witnessed: !!wardReceipt,
        first_ts: envelopes[0]?.ts || null,
        last_ts: envelopes[envelopes.length - 1]?.ts || null,
        envelopes_sha256: envelopesHash,
        head_hash: voltRun?.head_hash || null,
      },
      verify_instructions: 'Recompute sha256 over the canonical envelope list (id|ts|intent|corr|reply_to|from|to, JSON-stringified in array order; absent fields serialize as null) and compare to manifest.envelopes_sha256. If volt.bundle is present, verify head_hash against the VOLT bundle chain. See /aee/tools/verify.sh.',
    };

    res.setHeader('Content-Disposition', `attachment; filename="aee-bundle-${primaryCorr.slice(0, 24).replace(/[^a-zA-Z0-9_-]/g, '_')}.json"`);
    res.json(bundle);
  } catch (err) {
    console.error('[AEE] Bundle export error:', err);
    res.status(500).json({ error: 'Failed to build evidence bundle' });
  }
});

/**
 * AEE-CORE-6.2: companion verify script served as plain text so auditors
 * can save-as and run it against a downloaded bundle.
 */
app.get('/aee/tools/verify.sh', (req, res) => {
  res.type('text/x-shellscript').send(`#!/usr/bin/env bash
# AEE evidence bundle verifier
# Usage: verify.sh <path/to/aee-bundle-*.json>
set -euo pipefail
BUNDLE="\${1:?usage: $0 <bundle.json>}"
if ! command -v jq >/dev/null 2>&1; then
  echo "error: jq is required" >&2
  exit 2
fi
CLAIMED=$(jq -r '.manifest.envelopes_sha256' "$BUNDLE")
CORR=$(jq -r '.corr' "$BUNDLE")
COUNT=$(jq -r '.manifest.envelope_count' "$BUNDLE")
CANONICAL=$(jq -c '[.envelopes[] | {id, ts, intent, corr, reply_to, from, to}]' "$BUNDLE")
RECOMPUTED=$(printf '%s' "$CANONICAL" | sha256sum | cut -d' ' -f1)
echo "bundle corr   : $CORR"
echo "envelope count: $COUNT"
echo "claimed hash  : $CLAIMED"
echo "recomputed    : $RECOMPUTED"
if [ "$CLAIMED" = "$RECOMPUTED" ]; then
  echo "VERIFIED: envelope list integrity confirmed."
  exit 0
else
  echo "FAILED: envelope hash mismatch." >&2
  exit 1
fi
`);
});

/**
 * AEE-CORE-6.1: per-conversation witness summary.
 * Returns VOLT run (head hash + event count + status) for a given corr,
 * plus WARD witness info when available. UI shows this in the detail pane
 * so the user can copy hashes and verify the chain.
 */
app.get('/aee/conversation/:corr/witnesses', requireServiceOrUserAuth(), async (req, res) => {
  if (!voltStatements) return res.status(503).json({ error: 'VOLT not available' });
  try {
    const corr = req.params.corr;
    // AEE-ORG-1 (tenant isolation): a VOLT run for a corr owned by another org
    // must not disclose its head hash / witness metadata. Untagged legacy runs
    // (org_id NULL) stay visible, matching the VOLT read path.
    const orgId = req.user?.org_id || (req.service ? req.query.org_id : null) || null;
    const voltRun = voltStatements.getRunByCorr.get(corr);
    if (voltRun && voltRun.org_id && voltRun.org_id !== orgId) {
      return res.status(404).json({ error: 'Conversation not found' });
    }
    let bundle = null;
    let eventCount = 0;
    // WARD-RECEIPT-GAP sibling (flagged 2026-07-27, closed 2026-08-21): this
    // route used to trust a bundle-embedded `ward_receipt` field that nothing
    // writes, so auto-bundles always read witnessed:false here, and an edited
    // bundle blob could claim witnessed:true unchecked. Resolve from the WARD
    // chain with hash recompute instead, same as the bundle export route.
    let wardResult = { witnessed: false, receipt: null };
    if (voltRun?.run_id) {
      try {
        const events = voltStatements.getRunEvents.all(voltRun.run_id) || [];
        eventCount = events.length;
        const bundleRow = voltStatements.getRunBundle.get(voltRun.run_id);
        if (bundleRow) {
          let manifest = null;
          try {
            const parsed = JSON.parse(bundleRow.data);
            manifest = parsed?.manifest || null;
            bundle = {
              bundle_id: bundleRow.bundle_id,
              created_ts: bundleRow.created_ts,
              head_hash: parsed?.head_hash || voltRun.head_hash,
            };
          } catch { /* non-JSON bundle, surface raw */ }
          if (manifest?.bundle_id && typeof getWardService === 'function') {
            try {
              const ward = await getWardService();
              wardResult = resolveWardReceiptForBundle(
                {
                  getEntryBySource: ward.getEntryBySource,
                  payloadHash: ward.payloadHash,
                  chainId: ward.getHookChainId ? ward.getHookChainId() : null,
                  getCoveringTip: ward.getCoveringTip, // quox#515: signed-tip context on the receipt
                },
                manifest
              );
            } catch (err) {
              console.warn('[AEE] witnesses WARD lookup failed (non-fatal, reports unwitnessed):', err.message);
            }
          }
          if (bundle) {
            bundle.ward_receipt = wardResult.receipt;
            bundle.ward_witnessed = wardResult.witnessed;
          }
        }
      } catch (err) {
        console.warn('[AEE] witness lookup partial failure:', err.message);
      }
    }
    res.json({
      corr,
      volt: voltRun ? {
        run_id: voltRun.run_id,
        status: voltRun.status,
        started_at: voltRun.started_at,
        completed_at: voltRun.completed_at,
        seq: voltRun.seq,
        head_hash: voltRun.head_hash,
        event_count: eventCount,
      } : null,
      bundle,
      ward: {
        witnessed: wardResult.witnessed,
        receipt: wardResult.receipt,
      },
    });
  } catch (err) {
    console.error('[AEE] Witnesses error:', err);
    res.status(500).json({ error: 'Failed to get witnesses' });
  }
});

/**
 * AEE-CORE-4.3: orphan detection.
 * Lists envelopes whose reply_to points to a parent that no longer exists
 * (usually because the parent was pruned by retention or never synced from
 * the client). Useful diagnostic — also a signal for retention policy
 * tuning (if a short-TTL intent is a common parent, its child intents
 * end up orphaned).
 */
app.get('/aee/admin/orphans', requireServiceOrUserAuth(), (req, res) => {
  if (!aeeDb) return res.status(503).json({ error: 'AEE storage not available' });
  const limit = Math.min(parseInt(req.query.limit, 10) || 100, 500);
  try {
    const count = aeeStatements.countOrphans.get().n;
    const sample = aeeStatements.findOrphans.all(limit);
    res.json({ total: count, sample_size: sample.length, sample });
  } catch (err) {
    console.error('[AEE Orphans] error:', err);
    res.status(500).json({ error: 'Failed to list orphans' });
  }
});

// INCIDENT-700 (2026-10-06): the GC must NEVER be armed by a boot. A cheap tick
// every 30 min asks shouldRunGc(): >=24h since the last COMPLETED run (persisted
// in aee_gc_state) AND inside the quiet window (AEE_GC_WINDOW_UTC, default
// 03:00-05:00 UTC). AEE_GC_ENABLED=0 disables. No setTimeout-after-boot.
if (aeeDb && process.env.NODE_ENV !== 'test') {
  const gcTick = setInterval(() => {
    try {
      const { shouldRunGc } = require('./lib/aeeRetentionGc.cjs');
      const d = shouldRunGc({ db: aeeDb });
      if (!d.run) return;
      runRetentionGc().catch((err) => console.warn('[AEE GC] scheduled run failed:', err.message));
    } catch (err) { console.warn('[AEE GC] tick failed:', err.message); }
  }, 30 * 60 * 1000);
  if (gcTick.unref) gcTick.unref();
}

// Get all envelopes in a conversation
app.get('/aee/conversation/:corr', requireAeeAuth(), (req, res) => {
  if (!aeeDb) {
    return res.status(503).json({ error: 'AEE storage not available' });
  }

  try {
    const primaryCorr = req.params.corr;
    // AEE-ORG-1 (tenant isolation): scope to the caller's org (plus this corr's
    // own untagged legacy rows) — see getScopedCorrEnvelopes. No resolvable org
    // -> empty, never every tenant's conversation.
    //
    // AEE-CORE-2.2: the helper also merges legacy sibling corrs (pre-Phase-1
    // data fragmented one user action across CHAT_/SHELL_/orphan TOOL_ corrs).
    // Opt out with ?siblings=false for raw-data callers (export/debug).
    const orgId = req.user?.org_id || (req.service ? req.query.org_id : null) || null;
    const includeSiblings = req.query.siblings !== 'false';
    const envelopes = getScopedCorrEnvelopes(orgId, primaryCorr, { includeSiblings });

    res.json({ corr: primaryCorr, count: envelopes.length, envelopes });
  } catch (err) {
    console.error('[AEE] Conversation error:', err);
    res.status(500).json({ error: 'Failed to get conversation' });
  }
});

// Get envelope by ID — MUST be after all specific /aee/* routes to avoid
// the :id wildcard swallowing /aee/conversations, /aee/stats, etc.
app.get('/aee/:id', requireAeeAuth(), (req, res) => {
  if (!aeeDb) {
    return res.status(503).json({ error: 'AEE storage not available' });
  }

  try {
    // AEE-ORG-1 (tenant isolation): a JWT/cookie caller may read only its own
    // org's envelopes (plus untagged legacy rows, matching the query path);
    // another org's tagged envelope reads as 404, never disclosed. No org ->
    // 404 (no anonymous point reads).
    const orgId = req.user?.org_id || (req.service ? req.query.org_id : null) || null;
    const row = aeeStatements.getById.get(req.params.id);
    if (!envelopeRowVisibleToOrg(row, orgId)) {
      return res.status(404).json({ error: 'Envelope not found' });
    }
    // Decrypt envelope data
    const envelope = decryptEnvelopeRow(row);
    if (!envelope) {
      return res.status(500).json({ error: 'Failed to decrypt envelope' });
    }
    res.json(envelope);
  } catch (err) {
    console.error('[AEE] Get error:', err);
    res.status(500).json({ error: 'Failed to get envelope' });
  }
});

// ============================================================================
// Local Inference Source Management
// ============================================================================

// SEC-LOCAL-INF-ORG: caller's org is ALWAYS derived from the verified
// token/service-key, never a client-supplied value. JWT/qmcp_ callers use
// req.user.org_id; a raw INTERNAL_SERVICE_KEY caller has no JWT org, so it
// must state which org it's acting for via org_id (body for POST, query for
// GET/DELETE) — mirrors the existing req.service ? req.query.org_id pattern
// used elsewhere in this file for the AEE envelope-by-id route.
function resolveLocalInferenceCallerOrgId(req) {
  if (req.user?.org_id) return req.user.org_id;
  if (req.service) return (req.body && req.body.org_id) || req.query.org_id || null;
  return null;
}

// Register a local inference source
app.post('/api/v1/local-inference/sources', requireServiceOrUserAuth(), (req, res) => {
  try {
    const orgId = resolveLocalInferenceCallerOrgId(req);
    if (!orgId) {
      return res.status(400).json({ error: 'org_id_required', message: 'Could not resolve caller org; service callers must pass org_id in the body' });
    }
    const { id, name, baseUrl, backendType, authToken, dataResidencyTag, maxConcurrency, defaultChatModel } = req.body;
    if (!id || !name || !baseUrl) {
      return res.status(400).json({ error: 'id, name, and baseUrl are required' });
    }
    const ssrf = validateOutboundUrl(baseUrl);
    if (!ssrf.valid) {
      return res.status(400).json({ error: 'blocked_url', message: ssrf.error });
    }
    const source = { id, name, baseUrl: baseUrl.replace(/\/$/, ''), backendType: backendType || 'auto', authToken: authToken || null, dataResidencyTag: dataResidencyTag || 'local', maxConcurrency: maxConcurrency || 1, defaultChatModel: defaultChatModel || null };
    registerLocalSource(source, orgId);
    console.log(`[LocalInference] Registered source: ${id} (${name}) at ${baseUrl} org=${orgId}`);
    auditOp('ops.inference.source.registered', { source_id: id, name, url: baseUrl, org_id: orgId });
    res.json({ success: true, source: { ...source, authToken: source.authToken ? '***' : null } });
  } catch (err) {
    console.error('[LocalInference] Register error:', err);
    res.status(500).json({ error: 'Failed to register source' });
  }
});

// List registered sources — org-scoped (SEC-LOCAL-INF-ORG)
app.get('/api/v1/local-inference/sources', requireServiceOrUserAuth(), (req, res) => {
  const orgId = resolveLocalInferenceCallerOrgId(req);
  if (!orgId) {
    return res.status(400).json({ error: 'org_id_required', message: 'Could not resolve caller org; service callers must pass ?org_id=' });
  }
  const sources = localInferenceSourcesStore.listForOrg(orgId).map(s => ({
    ...s, authToken: s.authToken ? '***' : null
  }));
  res.json({ sources });
});

// Delete a source — org-scoped (SEC-LOCAL-INF-ORG): an id belonging to
// another org reads as not-found, same as it does for a truly unknown id.
app.delete('/api/v1/local-inference/sources/:id', requireServiceOrUserAuth(), (req, res) => {
  const orgId = resolveLocalInferenceCallerOrgId(req);
  if (!orgId) {
    return res.status(400).json({ error: 'org_id_required', message: 'Could not resolve caller org; service callers must pass ?org_id=' });
  }
  const deleted = localInferenceSourcesStore.deleteForOrg(req.params.id, orgId);
  if (!deleted) {
    return res.status(404).json({ error: 'Source not found' });
  }
  console.log(`[LocalInference] Removed source: ${req.params.id} org=${orgId}`);
  auditOp('ops.inference.source.deleted', { source_id: req.params.id, org_id: orgId });
  res.json({ success: true });
});

// Test connection to a source — SEC-LOCAL-INF-ORG: this route doesn't touch
// the org-scoped store (it probes a caller-supplied baseUrl directly, gated
// by validateOutboundUrl's SSRF check below), but it was still callable with
// zero auth; require a verified caller like its siblings above.
app.post('/api/v1/local-inference/test', requireServiceOrUserAuth(), async (req, res) => {
  const { baseUrl, backendType, authToken } = req.body;
  if (!baseUrl) {
    return res.status(400).json({ error: 'baseUrl is required' });
  }
  const ssrf = validateOutboundUrl(baseUrl);
  if (!ssrf.valid) {
    return res.status(400).json({ error: 'blocked_url', message: ssrf.error });
  }

  const start = Date.now();
  const headers = {};
  if (authToken) {
    headers['Authorization'] = `Bearer ${authToken}`;
  }

  try {
    // Try Ollama first if auto or ollama
    let detectedType = backendType;
    let models = [];

    if (backendType === 'auto' || backendType === 'ollama') {
      try {
        const ollamaRes = await fetchWithTimeout(`${baseUrl}/api/tags`, { headers }, 10000);
        if (ollamaRes.ok) {
          detectedType = 'ollama';
          const data = await ollamaRes.json();
          models = (data.models || []).map(m => ({
            id: m.name || m.model,
            name: m.name || m.model,
            sizeBytes: m.size || null,
            parameterSize: m.details?.parameter_size || null,
            family: m.details?.family || null
          }));
        }
      } catch { /* not Ollama */ }
    }

    if (models.length === 0 && detectedType !== 'ollama') {
      // Try OpenAI-compatible /v1/models
      const openaiRes = await fetchWithTimeout(`${baseUrl}/v1/models`, { headers }, 10000);
      if (openaiRes.ok) {
        detectedType = backendType === 'auto' ? 'openai-compatible' : backendType;
        const data = await openaiRes.json();
        models = (data.data || []).map(m => ({
          id: m.id,
          name: m.id,
          ownedBy: m.owned_by || null
        }));
      }
    }

    const latencyMs = Date.now() - start;
    if (models.length === 0 && detectedType === 'auto') {
      return res.json({ success: false, error: `Cannot reach inference server at ${baseUrl}`, latencyMs });
    }

    res.json({ success: true, backendType: detectedType, models, modelCount: models.length, latencyMs });
  } catch (err) {
    res.json({ success: false, error: err.message, latencyMs: Date.now() - start });
  }
});

// ============================================================================
// VOLT Sync — Server-side execution trace persistence
// ============================================================================

// Batch sync VOLT runs + events from browser IndexedDB
app.post('/volt/sync', requireServiceOrUserAuth(), (req, res) => {
  if (!voltDb || !voltStatements) {
    return res.status(503).json({ error: 'VOLT storage not available' });
  }

  const { runs, events, bundles, content } = req.body;
  // AEE-ORG-1 (tenant isolation): a JWT/cookie caller's synced runs are FORCED
  // to their own org (the body's org_id is ignored — otherwise a browser could
  // write runs tagged as any tenant). Only trusted service-key callers, which
  // legitimately relay multi-org fleet data, keep the per-run org_id.
  const isService = !!req.service;
  const callerOrg = req.user?.org_id || null;
  let syncedRuns = 0, syncedEvents = 0, syncedBundles = 0, syncedContent = 0;
  // VOLT-RETENTION P1: browser events arrive hash-chained, so an oversized one
  // is REFUSED and counted, never trimmed (a trimmed copy fails verification).
  let rejectedOversize = 0;
  let rejectedFork = 0;

  try {
    // Witness only what committed, in one WARD transaction, after the VOLT commit (was: one WARD
    // commit per event, inside a VOLT transaction that could still roll back). 2026-10-10.
    const toWitness = [];
    const syncAll = voltDb.transaction(() => {
      if (Array.isArray(runs)) {
        for (const run of runs) {
          if (!run.run_id) continue;
          voltStatements.insertRun.run(
            run.run_id, run.corr || null, run.status || 'pending',
            run.started_at || null, run.completed_at || null,
            run.seq || 0, run.head_hash || null,
            isService ? (run.org_id || null) : callerOrg
          );
          syncedRuns++;
        }
      }
      if (Array.isArray(events)) {
        for (const evt of events) {
          if (!evt.event_id) continue;
          if (voltIsOversizedSyncEvent(evt)) { rejectedOversize++; continue; }
          // quox#745: a second chain inside one run fails verification for
          // the whole run, so a forking event is refused and counted.
          if (voltSyncForksChain(voltStatements, evt)) { rejectedFork++; continue; }
          voltStatements.insertEvent.run(
            evt.event_id, evt.run_id, evt.event_type || null,
            evt.ts || null, evt.seq || 0,
            typeof evt === 'object' ? JSON.stringify(evt) : String(evt)
          );
          syncedEvents++;
          // GOV-E-6 deferred item: witness frontend-synced VOLT events in WARD.
          // Previously these landed in volt_events without a WARD receipt,
          // giving only 0.38% VOLT witness coverage. Fire-and-forget.
          if (evt.hash) {
            toWitness.push(evt);
          }
        }
      }
      if (Array.isArray(bundles)) {
        for (const b of bundles) {
          if (!b.bundle_id) continue;
          voltStatements.insertBundle.run(
            b.bundle_id, b.run_id, b.created_ts || null,
            typeof b.data === 'object' ? JSON.stringify(b.data) : String(b.data || '')
          );
          syncedBundles++;
          // Witness bundle manifests in WARD too (bundle_id + hash chain anchors)
          toWitness.push(b);
        }
      }
      // CRP-BE-4: Sync VOLT content (v0.2 — full prompts, tool I/O, model responses)
      if (Array.isArray(content)) {
        for (const c of content) {
          if (!c.event_id) continue;
          voltStatements.insertContent.run(
            c.event_id, c.run_id || '', c.event_type || null,
            typeof c.content === 'object' ? JSON.stringify(c.content) : String(c.content || ''),
            c.content_hash || null,
            c.redacted ? 1 : 0
          );
          syncedContent++;
        }
      }
    });

    syncAll();
    try { wardBatch(() => { for (const w of toWitness) { try { wardHookVOLT(w); } catch (_) { /* non-fatal */ } } }); }
    catch (err) { console.warn('[VOLT/WARD] sync witness batch failed (non-fatal):', err.message); }
    auditOp('ops.volt.sync', { type: req.body.type });
    if (rejectedOversize) console.warn(`[VOLT/sync] refused ${rejectedOversize} oversized event(s) (hash-chained, never trimmed)`);
    if (rejectedFork) console.warn(`[VOLT/sync] refused ${rejectedFork} event(s) that would fork a run chain (quox#745)`);
    res.json({ synced: { runs: syncedRuns, events: syncedEvents, bundles: syncedBundles, content: syncedContent }, rejected_oversize: rejectedOversize, rejected_fork: rejectedFork });
  } catch (err) {
    console.error('[VOLT] Sync error:', err);
    res.status(500).json({ error: 'Failed to sync VOLT data' });
  }
});

// Get VOLT runs (for cross-device access)
// TRUST-PROOF (FND_01M2Y2GXRF): tenant-isolation fix. Was unauthenticated and
// served getRunsPaged.all() = every org's runs; its sibling /volt/stats was
// already scoped and this was missed. Now auth-gated and org-scoped IDENTICALLY
// to /volt/stats: JWT/cookie users are locked to their own org, req.query.org_id
// is honored ONLY for trusted service-key callers, and no resolvable org yields
// honest empty (never global). Response shape ({runs,total,offset,limit})
// unchanged for its compliance/certification consumers.
app.get('/volt/runs', requireServiceOrUserAuth(), (req, res) => {
  if (!voltDb || !voltStatements) {
    return res.status(503).json({ error: 'VOLT storage not available' });
  }
  try {
    const limit = Math.min(parseInt(req.query.limit) || 30, 200);
    const offset = parseInt(req.query.offset) || 0;
    const orgId = req.user?.org_id || (req.service ? req.query.org_id : null) || null;
    if (!orgId) {
      return res.json({ runs: [], total: 0, offset, limit });
    }
    const runs = voltStatements.getRunsByOrgPaged.all(orgId, limit, offset);
    const total = voltStatements.countRunsByOrg.get(orgId)?.n || 0;
    res.json({ runs, total, offset, limit });
  } catch (err) {
    console.error('[VOLT] Query runs error:', err);
    res.status(500).json({ error: 'Failed to query VOLT runs' });
  }
});

// VOLT stats
// AEE-ORG-1-style read scoping: previously global (every tenant's runs/
// events/bundles counted for every caller), which fed compliance_posture's
// VOLT.runs/events summary and the sidebar via useComplianceData with a
// blended/global number. Now gated behind requireServiceOrUserAuth() (same
// as /api/v1/compliance/monitor/posture) and scoped to the caller's org via
// volt_runs.org_id (migration 003). Response shape (runs/events/bundles
// keys) is unchanged. No resolvable org -> honest zeros, never global.
const voltStatusProbeCache = require('./lib/statusProbeCache.js').createTtlCache({ ttlMs: 300000 });
const { runProbe, createAsyncProbeCache } = require('./lib/sqliteProbeWorker.js');
const voltStatsAsyncCache = createAsyncProbeCache({ ttlMs: 300000 });
const aeeStatsAsyncCache = createAsyncProbeCache({ ttlMs: 300000 });
app.get('/volt/stats', requireServiceOrUserAuth(), async (req, res) => {
  if (!voltDb || !voltStatements) {
    return res.status(503).json({ error: 'VOLT storage not available' });
  }
  try {
    // AEE-ORG-1 (tenant isolation): JWT/cookie users are LOCKED to their own
    // org — req.query.org_id is honored ONLY for trusted service-key callers
    // (req.service), never as a user-supplied override, else orgA could read
    // orgB by passing ?org_id=orgB.
    const orgId = req.user?.org_id || (req.service ? req.query.org_id : null) || null;
    // quox#510: an org-less service call used to get LITERAL ZEROS without
    // touching the store, which read as "the capture pipeline produces
    // nothing" while the same org held 150k+ runs. A caller we cannot scope
    // gets a refusal that says why, never a fabricated empty.
    if (!orgId) {
      return res.status(400).json({ error: 'org_required', message: 'Pass ?org_id= (service callers) or authenticate with an org-scoped session; an unscoped stats read would fabricate zeros.' });
    }
    // Incident 2026-10-06: polled by every status-bar client; 60s per-org cache.
    // CORTEX-BENCH 2026-10-08: the aggregate runs in the probe worker (own
    // read-only connection), never on the main event loop; stale-while-revalidate.
    const stats = await voltStatsAsyncCache.get(`volt:${orgId}`, () => runProbe(VOLT_DB_PATH, voltStatements.statsByOrg.source, { 1: orgId }));
    // VOLT-RETENTION P1: instance-wide bound counters since process start
    // (counts only, no evidence content), so oversized evidence is visible.
    res.json({ ...stats, bounds: voltBoundCounters() });
  } catch (err) {
    console.error('[VOLT] Stats error:', err);
    res.status(500).json({ error: 'Failed to get VOLT stats' });
  }
});

// HITL-VOLT-WITNESS (QuoxPlan #2202) — VOLT-witnessed approval decision
// query surface. Deliberately NOT in utils/collectorAuthGate.js's
// ALLOWLIST — it relies on requireServiceOrUserAuth() here, same as
// /volt/stats above, so an unauthenticated caller always 401s regardless
// of the gate's shadow/enforce mode.
const { createGetHitlDecisionsHandler } = require('./lib/hitlDecisionsHandler');
app.get('/volt/hitl/decisions', requireServiceOrUserAuth(), createGetHitlDecisionsHandler({ voltStatements }));

const { getArchivedAnchor } = require('./lib/voltArchivedRun');
// Get VOLT events for a run
app.get('/volt/runs/:runId/events', requireServiceOrUserAuth(), async (req, res) => {
  if (!voltDb || !voltStatements) {
    return res.status(503).json({ error: 'VOLT storage not available' });
  }
  try {
    // AEE-ORG-1 (tenant isolation): a run's hash-chain events must not be
    // readable by another org. envelopeRowVisibleToOrg is a generic org-row
    // predicate (own org OR untagged-legacy NULL; never another org; never
    // anon) reused for the volt_runs row (inside resolveVoltRunForOrg).
    const orgId = req.user?.org_id || (req.service ? req.query.org_id : null) || null;
    // quox#1013: an engine execution id or a corr resolves to its VOLT run.
    const { run, resolvedFrom } = await resolveVoltRunForOrg(req.params.runId, orgId);
    if (!run) return res.status(404).json({ error: 'Run not found', hint: voltRunNotFoundMessage(req.params.runId) });
    const runId = run.run_id;
    const events = voltStatements.getRunEvents.all(runId);
    if (events.length === 0) {
      const anchor = getArchivedAnchor(voltDb, runId);
      if (anchor) return res.json({ archived: true, anchor, events: [] });
    }
    // Parse JSON data back to objects
    const parsed = events.map(e => {
      try { return { ...e, data: JSON.parse(e.data) }; } catch { return e; }
    });
    res.json({ run_id: runId, ...(resolvedFrom ? { resolved_from: resolvedFrom } : {}), events: parsed });
  } catch (err) {
    console.error('[VOLT] Query events error:', err);
    res.status(500).json({ error: 'Failed to query VOLT events' });
  }
});

// Get VOLT bundle for a run
app.get('/volt/runs/:runId/bundle', requireServiceOrUserAuth(), async (req, res) => {
  if (!voltDb || !voltStatements) {
    return res.status(503).json({ error: 'VOLT storage not available' });
  }
  try {
    // AEE-ORG-1 (tenant isolation): gate the bundle on the run's org.
    const orgId = req.user?.org_id || (req.service ? req.query.org_id : null) || null;
    // quox#1013: an engine execution id or a corr resolves to its VOLT run.
    const { run, resolvedFrom } = await resolveVoltRunForOrg(req.params.runId, orgId);
    if (!run) return res.status(404).json({ error: 'Bundle not found', hint: voltRunNotFoundMessage(req.params.runId) });
    const runId = run.run_id;
    const bundle = voltStatements.getRunBundle.get(runId);
    if (!bundle) {
      const anchor = getArchivedAnchor(voltDb, runId);
      if (anchor) return res.json({ archived: true, anchor });
      return res.status(404).json({ error: 'Bundle not found', run_id: runId });
    }
    try { bundle.data = JSON.parse(bundle.data); } catch { /* keep as string */ }
    res.json({ run_id: runId, ...(resolvedFrom ? { resolved_from: resolvedFrom } : {}), bundle });
  } catch (err) {
    console.error('[VOLT] Query bundle error:', err);
    res.status(500).json({ error: 'Failed to query VOLT bundle' });
  }
});

// CRP-BE-4: Server-side bundle creation — assembles evidence bundle from server data
app.post('/volt/bundles/create', requireServiceOrUserAuth(), async (req, res) => {
  if (!voltDb || !voltStatements) {
    return res.status(503).json({ error: 'VOLT storage not available' });
  }

  const requestedRunId = req.body.run_id;
  if (!requestedRunId) return res.status(400).json({ error: 'run_id required' });

  try {
    // AEE-ORG-1 (tenant isolation): only bundle a run the caller's org owns.
    const orgId = req.user?.org_id || (req.service ? req.query.org_id : null) || null;
    // quox#1013: an engine execution id resolves to its captured VOLT run.
    const { run, resolvedFrom } = await resolveVoltRunForOrg(requestedRunId, orgId);
    if (!run) return res.status(404).json({ error: voltRunNotFoundMessage(requestedRunId) });
    const run_id = run.run_id;

    const events = voltStatements.getRunEvents.all(run_id);
    if (events.length === 0) return res.status(404).json({ error: 'No events for this run' });

    // Manifest + events NDJSON (VOLT SPEC section 7): single shared implementation.
    const { manifest, eventsNdjson, eventCount } = buildBundleParts(events, { runId: run_id, status: run.status });
    const bundleId = manifest.bundle_id;

    // Store bundle in DB
    voltStatements.insertBundle.run(
      bundleId, run_id, manifest.created_ts,
      JSON.stringify({ manifest, events_ndjson: eventsNdjson })
    );

    res.json({
      ok: true,
      bundle_id: bundleId,
      run_id,
      ...(resolvedFrom ? { resolved_from: resolvedFrom } : {}),
      manifest,
      event_count: eventCount,
      download_url: `/volt/bundles/${bundleId}/download`
    });
  } catch (err) {
    console.error('[VOLT] Bundle creation error:', err);
    res.status(500).json({ error: 'Failed to create bundle' });
  }
});

// CRP-BE-4: Download evidence bundle as portable JSON
app.get('/volt/bundles/:bundleId/download', requireServiceOrUserAuth(), (req, res) => {
  if (!voltDb || !voltStatements) {
    return res.status(503).json({ error: 'VOLT storage not available' });
  }

  try {
    const row = voltDb.prepare('SELECT * FROM volt_bundles WHERE bundle_id = ?').get(req.params.bundleId);
    if (!row) return res.status(404).json({ error: 'Bundle not found' });
    // AEE-ORG-1 (tenant isolation): the portable evidence bundle carries the
    // full run — gate it on the owning run's org.
    const orgId = req.user?.org_id || (req.service ? req.query.org_id : null) || null;
    const dlRun = voltStatements.getRun.get(row.run_id);
    if (!envelopeRowVisibleToOrg(dlRun, orgId)) return res.status(404).json({ error: 'Bundle not found' });

    let bundleData;
    try { bundleData = JSON.parse(row.data); } catch { bundleData = { raw: row.data }; }

    res.setHeader('Content-Type', 'application/json');
    res.setHeader('Content-Disposition', `attachment; filename="${req.params.bundleId}.json"`);
    res.json(bundleData);
  } catch (err) {
    console.error('[VOLT] Bundle download error:', err);
    res.status(500).json({ error: 'Failed to download bundle' });
  }
});

// ============================================================================
// VOLT Certification — Trust seal API (Phase 5.B)
// ============================================================================

// Schema now owned by migrations/volt/000-baseline.sql (runMigrations() at
// voltDb init above already created volt_certifications on a fresh DB /
// no-ops on an existing one).

const certStatements = voltDb ? {
  insertCert: voltDb.prepare(`
    INSERT OR REPLACE INTO volt_certifications
    (cert_id, run_id, bundle_id, tier, tier_name, checks, summary, certified_at, expires_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
  `),
  getCert: voltDb.prepare('SELECT * FROM volt_certifications WHERE cert_id = ?'),
  getCertByRun: voltDb.prepare('SELECT * FROM volt_certifications WHERE run_id = ? ORDER BY certified_at DESC LIMIT 1'),
  getCerts: voltDb.prepare('SELECT cert_id, run_id, bundle_id, tier, tier_name, certified_at, expires_at, revoked_at FROM volt_certifications ORDER BY certified_at DESC LIMIT ? OFFSET ?'),
  countCerts: voltDb.prepare('SELECT COUNT(*) as total FROM volt_certifications'),
  certStats: voltDb.prepare(`
    SELECT
      COUNT(*) as total,
      COALESCE(SUM(CASE WHEN tier = 'bronze' THEN 1 ELSE 0 END), 0) as bronze,
      COALESCE(SUM(CASE WHEN tier = 'silver' THEN 1 ELSE 0 END), 0) as silver,
      COALESCE(SUM(CASE WHEN tier = 'gold' THEN 1 ELSE 0 END), 0) as gold,
      COALESCE(SUM(CASE WHEN tier = 'platinum' THEN 1 ELSE 0 END), 0) as platinum,
      COALESCE(SUM(CASE WHEN revoked_at IS NOT NULL THEN 1 ELSE 0 END), 0) as revoked,
      COALESCE(SUM(CASE WHEN expires_at < datetime('now') AND revoked_at IS NULL THEN 1 ELSE 0 END), 0) as expired
    FROM volt_certifications
  `),
  revokeCert: voltDb.prepare('UPDATE volt_certifications SET revoked_at = datetime(\'now\'), revoked_reason = ? WHERE cert_id = ?'),
  // AEE-ORG-1 (tenant isolation): volt_certifications has NO org_id column, so
  // list + stats are scoped by joining to the certified run's org. Enumeration
  // and aggregates are NOT per-token verification (unlike GET /volt/cert/:id,
  // which stays a public trust-seal lookup), so they must not span orgs. Untagged
  // runs (org_id NULL) stay visible, matching the rest of the VOLT read path.
  getCertsByOrg: voltDb.prepare(`
    SELECT c.cert_id, c.run_id, c.bundle_id, c.tier, c.tier_name, c.certified_at, c.expires_at, c.revoked_at
    FROM volt_certifications c LEFT JOIN volt_runs r ON c.run_id = r.run_id
    WHERE (r.org_id = ? OR r.org_id IS NULL)
    ORDER BY c.certified_at DESC LIMIT ? OFFSET ?
  `),
  countCertsByOrg: voltDb.prepare(`
    SELECT COUNT(*) as total
    FROM volt_certifications c LEFT JOIN volt_runs r ON c.run_id = r.run_id
    WHERE (r.org_id = ? OR r.org_id IS NULL)
  `),
  certStatsByOrg: voltDb.prepare(`
    SELECT
      COUNT(*) as total,
      COALESCE(SUM(CASE WHEN c.tier = 'bronze' THEN 1 ELSE 0 END), 0) as bronze,
      COALESCE(SUM(CASE WHEN c.tier = 'silver' THEN 1 ELSE 0 END), 0) as silver,
      COALESCE(SUM(CASE WHEN c.tier = 'gold' THEN 1 ELSE 0 END), 0) as gold,
      COALESCE(SUM(CASE WHEN c.tier = 'platinum' THEN 1 ELSE 0 END), 0) as platinum,
      COALESCE(SUM(CASE WHEN c.revoked_at IS NOT NULL THEN 1 ELSE 0 END), 0) as revoked,
      COALESCE(SUM(CASE WHEN c.expires_at < datetime('now') AND c.revoked_at IS NULL THEN 1 ELSE 0 END), 0) as expired
    FROM volt_certifications c LEFT JOIN volt_runs r ON c.run_id = r.run_id
    WHERE (r.org_id = ? OR r.org_id IS NULL)
  `),
} : null;

// POST /volt/certify — Run certification against a VOLT run
app.post('/volt/certify', requireServiceOrUserAuth(), async (req, res) => {
  if (!voltDb || !voltStatements || !certStatements) {
    return res.status(503).json({ error: 'VOLT storage not available' });
  }

  try {
    const { run_id: requestedRunId, retention_days, audit_info, compliance_info } = req.body;

    if (!requestedRunId) {
      return res.status(400).json({ error: 'run_id is required' });
    }

    // AEE-ORG-1 (tenant isolation): certifying is a mutation — only the org
    // that owns the run may certify it.
    const orgId = req.user?.org_id || (req.service ? req.query.org_id : null) || null;
    // quox#1013: `quox workflow run` prints the ENGINE execution id; resolve it to the VOLT run
    // that captured it (VR_wf-...) instead of a 404 for the only id the user holds.
    const { run: certRun, resolvedFrom } = await resolveVoltRunForOrg(requestedRunId, orgId);
    if (!certRun) return res.status(404).json({ error: voltRunNotFoundMessage(requestedRunId) });
    const run_id = certRun.run_id;

    // Fetch run events from VOLT DB
    const eventRows = voltStatements.getRunEvents.all(run_id);
    if (!eventRows || eventRows.length === 0) {
      return res.status(404).json({ error: `No events found for run ${run_id}` });
    }

    // Parse event data
    const events = eventRows.map(row => {
      try { return JSON.parse(row.data); } catch { return row; }
    });

    // Fetch bundle if available
    const bundleRow = voltStatements.getRunBundle.get(run_id);
    let bundle = null;
    if (bundleRow && bundleRow.data) {
      try {
        const parsed = JSON.parse(bundleRow.data);
        bundle = {
          manifest: parsed.manifest || parsed,
          eventsNDJSON: parsed.events_ndjson || events.map(e => JSON.stringify(e)).join('\n') + '\n',
          redactions: parsed.redactions || null,
          // AUDIT-REAL #2: real signed bundles carry a SINGULAR `signature`
          // object (bundleSigner.js/voltContentStore.js); `signatures` (plural)
          // is the legacy/spec array shape. Keep both so evaluateBundleSignatures
          // can detect/verify either.
          signature: parsed.signature || null,
          signatures: parsed.signatures || [],
          attachments: parsed.attachments || []
        };
      } catch { /* no bundle */ }
    }

    // Auto-enhance bundle for Gold tier: add TSA timestamp + Ed25519 signature if missing
    if (bundle && bundle.manifest) {
      // Auto-timestamp: request RFC 3161 from FreeTSA if no timestamps present
      if (!bundle.manifest.timestamps || bundle.manifest.timestamps.length === 0) {
        try {
          const manifestJson = JSON.stringify(bundle.manifest);
          const manifestHash = require('crypto').createHash('sha256').update(manifestJson).digest('hex');
          const tsRecord = await requestRFC3161Timestamp(manifestHash);
          if (tsRecord) {
            bundle.manifest.timestamps = [tsRecord];
            console.log(`[VOLT/Cert] Auto-timestamped run ${run_id} via ${tsRecord.tsa_url}`);
          }
        } catch (tsErr) {
          console.warn(`[VOLT/Cert] TSA timestamp failed (non-fatal): ${tsErr.message}`);
        }
      }

      // Auto-sign: add Ed25519/HMAC signature only if no VALID signature is
      // already present (checks both the real singular `signature` shape
      // and the legacy plural `signatures` array — AUDIT-REAL #2).
      // VOLT-CERT-BIND: verify against the collector's own PINNED signing key
      // so a bundle-embedded attacker key can never pass as "already signed".
      if (!evaluateBundleSignatures(bundle, { pinnedPublicKey: getHookKeypair()?.publicKey || null }).has_signatures) {
        try {
          const sigRecord = await signBundleManifest(bundle.manifest);
          if (sigRecord) {
            bundle.signatures = [sigRecord];
            console.log(`[VOLT/Cert] Auto-signed run ${run_id} (${sigRecord.sig_type})`);
          }
        } catch (sigErr) {
          console.warn(`[VOLT/Cert] Auto-sign failed (non-fatal): ${sigErr.message}`);
        }
      }

      // Persist enhanced bundle back to DB
      if ((bundle.manifest.timestamps?.length > 0 || bundle.signature || bundle.signatures?.length > 0) && bundleRow) {
        try {
          const enhancedData = JSON.stringify({
            manifest: bundle.manifest,
            events_ndjson: bundle.eventsNDJSON,
            signature: bundle.signature || undefined,
            signatures: bundle.signatures,
            redactions: bundle.redactions,
            attachments: bundle.attachments
          });
          voltDb.prepare('UPDATE volt_bundles SET data = ? WHERE run_id = ?').run(enhancedData, run_id);
        } catch (dbErr) {
          console.warn(`[VOLT/Cert] Bundle update failed (non-fatal): ${dbErr.message}`);
        }
      }
    }

    const input = {
      events,
      bundle,
      retentionInfo: retention_days ? { retention_days } : undefined,
      auditInfo: audit_info,
      complianceInfo: compliance_info
    };

    const certResult = await runCertification(input, events, bundle);

    certStatements.insertCert.run(
      certResult.cert_id,
      certResult.run_id,
      certResult.bundle_id,
      certResult.tier || 'none',
      certResult.tier_name,
      JSON.stringify(certResult.checks),
      JSON.stringify(certResult.summary),
      certResult.certified_at,
      certResult.expires_at
    );

    auditOp('ops.volt.cert.created', { cert_id: certResult.cert_id });
    res.json(resolvedFrom ? { ...certResult, resolved_from: resolvedFrom } : certResult);
  } catch (err) {
    console.error('[VOLT] Certification error:', err);
    res.status(500).json({ error: `Certification failed: ${err.message}` });
  }
});

