// ============================================================================
// CRP-BE-5: Compliance Jobs & Reports — Server-Side Scheduling
// ============================================================================

// Calculate next run time
function calculateComplianceNextRun(interval, dayOfWeek, dayOfMonth) {
  const now = new Date();
  const next = new Date(now);
  switch (interval) {
    case 'daily': next.setDate(next.getDate() + 1); next.setHours(2, 0, 0, 0); break;
    case 'weekly': {
      const d = ((dayOfWeek || 1) - now.getDay() + 7) % 7 || 7;
      next.setDate(next.getDate() + d); next.setHours(2, 0, 0, 0); break;
    }
    case 'monthly': next.setMonth(next.getMonth() + 1); next.setDate(dayOfMonth || 1); next.setHours(2, 0, 0, 0); break;
  }
  return next.toISOString();
}

// POST /compliance/jobs — Create a scheduled compliance job
// GOV-TRUTH tail: capture the creating caller's org (JWT user locked to their
// own org; trusted service-key callers may pass ?org_id=<org> — same SAFE
// pattern as GET /compliance/reports above) so the job runner can later tag
// the reports it generates with a real org instead of always null.
app.post('/compliance/jobs', requireServiceOrUserAuth(), (req, res) => {
  if (!complianceStatements) return res.status(503).json({ error: 'Compliance storage not available' });
  try {
    const { format, schedule, options } = req.body;
    if (!format || !schedule?.interval) return res.status(400).json({ error: 'format and schedule.interval required' });
    const orgId = req.user?.org_id || (req.service ? req.query.org_id : null) || null;
    const id = `JOB_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`;
    const nextRun = calculateComplianceNextRun(schedule.interval, schedule.dayOfWeek, schedule.dayOfMonth);
    complianceStatements.insertJob.run(id, format, schedule.interval, schedule.dayOfWeek || null, schedule.dayOfMonth || null, JSON.stringify(options || {}), nextRun, orgId);
    const job = complianceStatements.getJob.get(id);
    res.json({ ok: true, job });
  } catch (err) {
    console.error('[Compliance] Create job error:', err);
    res.status(500).json({ error: 'Failed to create job' });
  }
});

