// PATCH /compliance/jobs/:id — Update job (pause/resume/modify)
// CRP-AU-5: Accept status, schedule, next_run — not just status
app.patch('/compliance/jobs/:id', requireServiceOrUserAuth(), (req, res) => {
  if (!complianceStatements) return res.status(503).json({ error: 'Compliance storage not available' });
  try {
    const orgId = resolveComplianceOrgId(req);
    const job = complianceStatements.getJob.get(req.params.id);
    if (!orgOwns(job, orgId)) return res.status(404).json({ error: 'Job not found' });

    const { status, schedule, next_run } = req.body;
    if (status) complianceStatements.updateJobStatus.run(status, req.params.id);
    if (next_run) {
      complianceStatements.updateJob.run(job.last_run, next_run, job.last_error, req.params.id);
    }
    if (schedule) {
      const nextRun = next_run || calculateComplianceNextRun(schedule.interval, schedule.dayOfWeek, schedule.dayOfMonth);
      voltDb.prepare('UPDATE compliance_jobs SET schedule_interval = ?, schedule_day_of_week = ?, schedule_day_of_month = ?, next_run = ? WHERE id = ?')
        .run(schedule.interval, schedule.dayOfWeek || null, schedule.dayOfMonth || null, nextRun, req.params.id);
    }

    const updated = complianceStatements.getJob.get(req.params.id);
    res.json({ ok: true, job: updated });
  } catch (err) {
    console.error('[Compliance] Update job error:', err);
    res.status(500).json({ error: 'Failed to update job' });
  }
});

// POST /compliance/reports — Store a generated report
// AEE-ORG-1-style write tagging: org comes from the requesting user's JWT
// (req.user?.org_id) or an internal service caller passing org_id in the
// body/query (matches monitor/posture's req.query.org_id || req.user?.org_id
// fallback so internal tools with no browser session can still tag reports
// they generate on an org's behalf). Never fabricated — null when unknown.
app.post('/compliance/reports', requireServiceOrUserAuth(), (req, res) => {
  if (!complianceStatements) return res.status(503).json({ error: 'Compliance storage not available' });
  try {
    const { format, period, summary, report_data, job_id } = req.body;
    if (!format) return res.status(400).json({ error: 'format required' });
    const orgId = resolveCallerOrgId(req);
    const id = `RPT_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`;
    complianceStatements.insertReport.run(
      id, job_id || null, format,
      period?.start || null, period?.end || null, period?.days || null,
      typeof summary === 'object' ? JSON.stringify(summary) : (summary || null),
      typeof report_data === 'object' ? JSON.stringify(report_data) : (report_data || null),
      orgId
    );
    res.json({ ok: true, report_id: id });
  } catch (err) {
    console.error('[Compliance] Store report error:', err);
    res.status(500).json({ error: 'Failed to store report' });
  }
});

// GET /compliance/reports — List report history (metadata only, no report_data)
// AEE-ORG-1-style read scoping: previously unauthenticated and unscoped —
// every caller saw every org's report history, which is what made the
// PostureDashboard (reads this endpoint via useComplianceData) show a
// blended/global score while the already org-scoped Monitor tab
// (/api/v1/compliance/monitor/posture) showed the caller's real score.
// No resolvable org -> honest empty list, never global.
app.get('/compliance/reports', requireServiceOrUserAuth(), (req, res) => {
  if (!complianceStatements) return res.status(503).json({ error: 'Compliance storage not available' });
  try {
    const limit = parseInt(req.query.limit) || 50;
    // AEE-ORG-1 (tenant isolation): JWT/cookie users are LOCKED to their own
    // org — req.query.org_id is honored ONLY for trusted service-key callers
    // (req.service), never as a user-supplied override, else orgA could read
    // orgB by passing ?org_id=orgB.
    const orgId = req.user?.org_id || (req.service ? req.query.org_id : null) || null;
    const reports = orgId ? complianceStatements.getReports.all(orgId, limit) : [];
    // Parse summary JSON
    const parsed = reports.map(r => {
      try { r.summary = JSON.parse(r.summary); } catch { /* keep string */ }
      return r;
    });
    res.json({ reports: parsed });
  } catch (err) {
    console.error('[Compliance] List reports error:', err);
    res.status(500).json({ error: 'Failed to list reports' });
  }
});

