// PUT /api/v1/compliance/soa/:id — Update SoA assessment controls and/or status
app.put('/api/v1/compliance/soa/:id', requireServiceOrUserAuth(), (req, res) => {
  if (!soaStatements) return res.status(503).json({ error: 'SoA storage not available' });
  try {
    const orgId = resolveComplianceOrgId(req);
    const existing = soaStatements.getById.get(req.params.id);
    if (!orgOwns(existing, orgId)) return res.status(404).json({ error: 'Assessment not found' });
    const { controls, status } = req.body;
    const newStatus = status || existing.status;
    const soaTransitions = { draft: ['review'], review: ['approved', 'draft'], approved: ['draft'] };
    if (status && status !== existing.status) {
      const allowed = soaTransitions[existing.status] || [];
      if (!allowed.includes(status)) {
        return res.status(400).json({ error: `Invalid transition: ${existing.status} → ${status}. Allowed: ${allowed.join(', ')}` });
      }
    }
    const controlsJson = controls ? JSON.stringify(controls) : existing.controls_json;
    soaStatements.update.run(controlsJson, newStatus, req.params.id);
    const updated = soaStatements.getById.get(req.params.id);
    updated.controls_json = JSON.parse(updated.controls_json);
    res.json({ ok: true, assessment: updated });
  } catch (err) {
    console.error('[SoA] Update error:', err);
    res.status(500).json({ error: 'Failed to update assessment' });
  }
});

// GET /api/v1/compliance/soa/:id/export — Export SoA as JSON or CSV
app.get('/api/v1/compliance/soa/:id/export', requireServiceOrUserAuth(), (req, res) => {
  if (!soaStatements) return res.status(503).json({ error: 'SoA storage not available' });
  try {
    const orgId = resolveComplianceOrgId(req);
    const assessment = soaStatements.getById.get(req.params.id);
    if (!orgOwns(assessment, orgId)) return res.status(404).json({ error: 'Assessment not found' });
    const format = req.query.format || 'json';
    const controls = JSON.parse(assessment.controls_json);
    const allDefs = getSoAControls();

    if (format === 'csv') {
      const headers = ['Control ID', 'Group', 'Control Name', 'Applicable', 'Implementation Status', 'Justification', 'Owner', 'Auto-Detected'];
      const rows = [headers.join(',')];
      for (const ctrl of controls) {
        const def = allDefs.find(d => d.id === ctrl.control_id) || {};
        rows.push([
          ctrl.control_id,
          def.group || '',
          `"${(def.name || '').replace(/"/g, '""')}"`,
          ctrl.applicable || '',
          ctrl.implementation_status,
          `"${(ctrl.justification || '').replace(/"/g, '""')}"`,
          ctrl.owner || '',
          ctrl.auto_detected ? 'Yes' : 'No',
        ].join(','));
      }
      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', `attachment; filename="soa-${req.params.id}.csv"`);
      return res.send(rows.join('\n'));
    }

    res.json({
      id: assessment.id,
      org_id: assessment.org_id,
      framework: assessment.framework,
      version: assessment.version,
      status: assessment.status,
      controls,
      created_at: assessment.created_at,
      updated_at: assessment.updated_at,
    });
  } catch (err) {
    console.error('[SoA] Export error:', err);
    res.status(500).json({ error: 'Failed to export assessment' });
  }
});

// ============================================================
// AUD-PDF: Compliance PDF generation
// ============================================================

const {
  generateFrameworkPdf,
  generateSoAPdf,
  generateDpiaPdf,
  generateWardBundlePdf,
  isFrameworkFormat: isFrameworkPdfFormat,
} = require('./lib/pdf/compliancePdfGenerator.js');

// POST /api/v1/compliance/pdf — Generate a framework compliance PDF
// Body: { format, report?, period? } — report is the pre-computed JSON
// from the matching formatter; period is forwarded to generate if report
// is absent. Returns application/pdf bytes with WARD-signed metadata.
app.post('/api/v1/compliance/pdf', requireServiceOrUserAuth(), async (req, res) => {
  const { format, report, orgLabel } = req.body || {};
  if (!format) return res.status(400).json({ error: 'format is required' });
  if (!isFrameworkPdfFormat(format)) {
    return res.status(400).json({ error: `format "${format}" not supported for framework PDF. Use SoA endpoint for Statements of Applicability.` });
  }
  if (!report) return res.status(400).json({ error: 'report body is required (send the JSON from generateComplianceReport)' });

  try {
    const { bytes, manifest, pageCount } = await generateFrameworkPdf({
      report: { ...report, format },
      options: {
        orgLabel: orgLabel || report?.org_id || '—',
        getHookKeypair,
        cacheDb: voltDb,
      },
    });
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `attachment; filename="compliance-${format}-${Date.now()}.pdf"`);
    res.setHeader('X-Quox-Manifest-Hash', manifest.manifest_hash);
    res.setHeader('X-Quox-Page-Count', String(pageCount));
    if (manifest.warning) res.setHeader('X-Quox-Signing-Warning', manifest.warning);
    res.send(bytes);
  } catch (err) {
    console.error('[AUD-PDF] framework PDF error:', err);
    res.status(500).json({ error: err.message || 'Failed to generate PDF' });
  }
});

// GET /api/v1/compliance/soa/:id/pdf — SoA Statement of Applicability PDF
app.get('/api/v1/compliance/soa/:id/pdf', requireServiceOrUserAuth(), async (req, res) => {
  if (!soaStatements) return res.status(503).json({ error: 'SoA storage not available' });
  try {
    const orgId = resolveComplianceOrgId(req);
    const assessment = soaStatements.getById.get(req.params.id);
    if (!orgOwns(assessment, orgId)) return res.status(404).json({ error: 'Assessment not found' });

    const { bytes, manifest, pageCount } = await generateSoAPdf({
      soa: assessment,
      options: {
        orgLabel: assessment.org_id || '—',
        getHookKeypair,
        cacheDb: voltDb,
      },
    });
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `attachment; filename="soa-${req.params.id}.pdf"`);
    res.setHeader('X-Quox-Manifest-Hash', manifest.manifest_hash);
    res.setHeader('X-Quox-Page-Count', String(pageCount));
    if (manifest.warning) res.setHeader('X-Quox-Signing-Warning', manifest.warning);
    res.send(bytes);
  } catch (err) {
    console.error('[AUD-PDF] SoA PDF error:', err);
    res.status(500).json({ error: err.message || 'Failed to generate SoA PDF' });
  }
});

