app.put('/api/v1/compliance/dpia/:id', requireServiceOrUserAuth(), (req, res) => {
  if (!dpiaStatements) return res.status(503).json({ error: 'DPIA storage not available' });
  try {
    const orgId = resolveComplianceOrgId(req);
    const existing = dpiaStatements.getById.get(req.params.id);
    if (!orgOwns(existing, orgId)) return res.status(404).json({ error: 'DPIA not found' });
    const { sections, status } = req.body;
    if (status && status !== existing.status) {
      if (!isDpiaTransitionValid(existing.status, status)) {
        return res.status(400).json({ error: `Invalid status transition: ${existing.status} → ${status}` });
      }
    }
    const updateDpia = voltDb.transaction(() => {
      if (status && status !== existing.status) dpiaStatements.updateStatus.run(status, req.params.id);
      if (sections) dpiaStatements.update.run(JSON.stringify(sections), req.params.id);
    });
    updateDpia();
    const row = dpiaStatements.getById.get(req.params.id);
    row.sections_json = JSON.parse(row.sections_json);
    res.json({ ok: true, dpia: row });
  } catch (err) {
    console.error('[DPIA] Update error:', err);
    res.status(500).json({ error: 'Failed to update DPIA' });
  }
});

