app.post('/traces/correlations', (req, res) => {
  if (!trvStatements) return res.status(503).json({ error: 'Trace storage not available' });
  try {
    const { id, root_run_id, correlation_id, tree, stats, agent_count, handoff_count, org_id } = req.body;
    if (!id || !root_run_id || !correlation_id) return res.status(400).json({ error: 'id, root_run_id, and correlation_id required' });
    // Default 24h cache TTL
    const expires_at = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
    trvStatements.insertCorrelation.run(
      id, root_run_id, correlation_id,
      typeof tree === 'object' ? JSON.stringify(tree) : (tree || '{}'),
      typeof stats === 'object' ? JSON.stringify(stats) : (stats || null),
      agent_count || 0, handoff_count || 0,
      expires_at, org_id || null
    );
    res.json({ stored: true, id, expires_at });
  } catch (err) {
    console.error('[TRV] Store correlation error:', err);
    res.status(500).json({ error: 'Failed to store correlation' });
  }
});

