// POST /api/v1/policies — Create a new policy
// POL-HIST: build actor context from the request. All /api/v1/policies
// routes now carry requireServiceOrUserAuth() (cross-org auth gap closed),
// but a service-key caller sets req.service rather than req.user, so we
// still fall back to body fields when req.user is absent. enforce_4eyes is
// opt-in:
// caller passes { enforce_4eyes: true } in the body OR the mutation
// targets a policy the org has opted in via future policy-level settings.
function policyMutationCtx(req) {
  const user = req.user || {};
  const body = req.body || {};
  return {
    actor_id: user.id || body.actor_id || body.created_by || 'unknown',
    actor_email: user.email || body.actor_email || null,
    actor_label: user.email || body.actor_label || user.id || body.created_by || 'unknown',
    actor_source: req.service ? 'service_key' : 'api',
    reason: body.reason_for_change || null,
    request_id: req.headers?.['x-request-id'] || null,
    enforce_4eyes: body.enforce_4eyes === true,
  };
}

// POL-HIST: fire-and-forget AEE envelope so WARD witnesses + UI subscribes.
function emitPolicyChangedEnvelope(policy, operation, ctx) {
  try {
    storeAuditEnvelope({
      type: 'event',
      from: 'system.governance',
      to: 'system.aee',
      intent: 'governance.policy.changed',
      corr: `POLCHG_${policy?.id || 'unknown'}_${Date.now()}`,
      payload: {
        policy_id: policy?.id || null,
        org_id: policy?.org_id || null,
        operation,
        category: policy?.category || null,
        actor_id: ctx?.actor_id || 'unknown',
        actor_label: ctx?.actor_label || null,
        actor_source: ctx?.actor_source || 'api',
      },
    });
  } catch (err) {
    console.warn('[POL-HIST] governance.policy.changed emit failed:', err.message);
  }
}

app.post('/api/v1/policies', requireServiceOrUserAuth(), (req, res) => {
  if (!voltDb) return res.status(503).json({ error: 'Policy storage not available' });
  try {
    const { name, category, enabled, priority, scope, conditions, effect, reason, framework_mapping, audit_required, org_id, created_by } = req.body;
    if (!name || !category || !org_id) {
      return res.status(400).json({ error: 'name, category, and org_id are required' });
    }
    const validation = validatePolicyRecord({ name, category, enabled: enabled !== false, priority: priority ?? 100, scope: scope || { agents: ['*'] }, conditions, effect: effect || 'deny' });
    if (!validation.valid) {
      return res.status(400).json({ error: 'Validation failed', details: validation.errors });
    }
    const ctx = policyMutationCtx(req);
    const policy = createPolicyRecord(voltDb, {
      name, category, enabled: enabled !== false, priority: priority ?? 100,
      scope: scope || { agents: ['*'] }, conditions, effect: effect || 'deny',
      reason: reason || '', framework_mapping: framework_mapping || [],
      audit_required: audit_required || false, org_id, created_by: created_by || '',
    }, ctx);
    emitPolicyChangedEnvelope(policy, 'created', ctx);
    res.status(201).json({ ok: true, policy });
  } catch (err) {
    console.error('[GOV] Create policy error:', err);
    if (err.message.includes('already exists')) {
      return res.status(409).json({ error: err.message });
    }
    res.status(400).json({ error: err.message });
  }
});

// PATCH /api/v1/policies/:id — Update a policy
app.patch('/api/v1/policies/:id', requireServiceOrUserAuth(), (req, res) => {
  if (!voltDb) return res.status(503).json({ error: 'Policy storage not available' });
  try {
    const updates = req.body;
    const ctx = policyMutationCtx(req);
    const policy = updatePolicyRecord(voltDb, req.params.id, updates, ctx);
    if (policy && policy._pending_approval) {
      return res.status(202).json({
        ok: true,
        pending_approval: policy._pending_approval,
        message: 'Change staged; awaiting second-approver review.',
      });
    }
    emitPolicyChangedEnvelope(policy, 'updated', ctx);
    res.json({ ok: true, policy });
  } catch (err) {
    console.error('[GOV] Update policy error:', err);
    if (err.message.includes('not found')) {
      return res.status(404).json({ error: err.message });
    }
    if (err.message.includes('system')) {
      return res.status(403).json({ error: err.message });
    }
    res.status(400).json({ error: err.message });
  }
});

// DELETE /api/v1/policies/:id — Delete a policy
app.delete('/api/v1/policies/:id', requireServiceOrUserAuth(), (req, res) => {
  if (!voltDb) return res.status(503).json({ error: 'Policy storage not available' });
  try {
    const ctx = policyMutationCtx(req);
    const existing = getPolicyRecord(voltDb, req.params.id);
    const result = deletePolicyRecord(voltDb, req.params.id, ctx);
    if (result.pending_approval) {
      return res.status(202).json({
        ok: true,
        pending_approval: result.pending_approval,
        message: 'Delete staged; awaiting second-approver review.',
      });
    }
    if (!result.deleted) return res.status(404).json({ error: 'Policy not found' });
    emitPolicyChangedEnvelope(existing, 'deleted', ctx);
    res.json({ ok: true, deleted: req.params.id });
  } catch (err) {
    console.error('[GOV] Delete policy error:', err);
    if (err.message.includes('system')) {
      return res.status(403).json({ error: err.message });
    }
    res.status(500).json({ error: 'Failed to delete policy' });
  }
});

