app.post('/api/v1/policies/approvals/:entryId/resolve', requireServiceOrUserAuth(), (req, res) => {
  // F13: agents (agent_id / actor_type / agent_ops / attach lease / qmcp) never decide approvals.
  if (deriveActorType(req) === 'agent') {
    return res.status(403).json({ error: 'Agents cannot resolve HITL approvals (HARD INVARIANT #1); file a proposal for a human instead' });
  }
  if (!voltDb) return res.status(503).json({ error: 'Policy history not available' });
  const { outcome, reason } = req.body || {};
  if (!['approved', 'rejected'].includes(outcome)) {
    return res.status(400).json({ error: "outcome must be 'approved' or 'rejected'" });
  }
  // QUOXON-STEPUP: a human JWT proves a login, not a person. Approving a policy change needs a live step-up
  // token (minted by auth after a PIN verify). Rejecting is de-escalation and stays open. The service-key
  // path (req.service) is left as is: it is not a human and cannot supply a user identity.
  if (outcome === 'approved' && req.user && req.service !== true) {
    if (!require('./utils/stepUp.js').requireStepUp(req, res)) return;
  }
  const approver = req.user?.id || req.user?.email || req.body?.approved_by;
  if (!approver) return res.status(400).json({ error: 'approved_by required (no auth context)' });
  try {
    const entry = getPolicyHistoryEntry(voltDb, req.params.entryId);
    if (!entry) return res.status(404).json({ error: 'history entry not found' });

    // Second-approver rule: the approver must NOT be the requester.
    if (entry.actor_id && entry.actor_id !== 'unknown' && entry.actor_id === approver) {
      return res.status(403).json({ error: 'Second-approver rule: you cannot approve your own change.' });
    }
    // Cross-org guard
    if (req.user?.org_id && entry.org_id !== req.user.org_id) {
      return res.status(404).json({ error: 'history entry not found' });
    }

    const result = resolvePolicyApproval(voltDb, req.params.entryId, { outcome, approved_by: approver, reason });

    // On approval, re-apply the change with enforce_4eyes=false so it lands.
    if (outcome === 'approved') {
      const diff = entry.diff_json || {};
      const applyCtx = {
        actor_id: approver,
        actor_label: approver,
        actor_source: 'approval_workflow',
        reason: `Approved via ${req.params.entryId}`,
        enforce_4eyes: false,
      };
      try {
        if (diff._deleted?.after === true) {
          deletePolicyRecord(voltDb, entry.policy_id, applyCtx);
          emitPolicyChangedEnvelope({ id: entry.policy_id, org_id: entry.org_id }, 'deleted', applyCtx);
        } else {
          const updates = {};
          for (const [field, { after }] of Object.entries(diff)) {
            updates[field] = after;
          }
          const applied = updatePolicyRecord(voltDb, entry.policy_id, updates, applyCtx);
          emitPolicyChangedEnvelope(applied, 'updated', applyCtx);
        }
      } catch (applyErr) {
        console.error('[POL-HIST] apply-after-approval failed:', applyErr);
        return res.status(500).json({ error: 'Approval recorded but apply failed: ' + applyErr.message });
      }
    }

    res.json({ ok: true, outcome, entry: result.sibling });
  } catch (err) {
    if (err.message?.includes('already resolved')) return res.status(409).json({ error: err.message });
    if (err.message?.includes('not found')) return res.status(404).json({ error: err.message });
    console.error('[POL-HIST] resolve approval error:', err);
    res.status(500).json({ error: 'Failed to resolve approval' });
  }
});

