// ============================================================
// MON-GOV: Governance Incidents API
// ============================================================
//
// Incidents persist in voltDb alongside governance policies. All routes
// are dual-auth (user JWT or internal service key). Reads and writes are
// always scoped to the caller's resolved org. Manual severity
// escalation to "critical" requires role=admin for user callers;
// internal services can escalate freely (they carry their own audit
// trail via INTERNAL_SERVICE_KEY usage).

function resolveIncidentOrgId(req) {
  if (req.user && req.user.org_id) return req.user.org_id;
  if (req.service) {
    return req.body?.org_id || req.query?.org_id || '__default__';
  }
  return null;
}

function isAdminCaller(req) {
  return isAdminUser(req);
}

// POST /governance/incidents — Manual incident creation (rare; usually auto-created from envelopes)
app.post('/governance/incidents', requireServiceOrUserAuth(), (req, res) => {
  if (!voltDb) return res.status(503).json({ error: 'Incident storage not available' });
  const orgId = resolveIncidentOrgId(req);
  if (!orgId) return res.status(401).json({ error: 'org_id could not be resolved from auth context' });
  try {
    const body = req.body || {};
    if (body.severity === 'critical' && !isAdminCaller(req)) {
      return res.status(403).json({ error: 'admin role required to open critical-severity incidents' });
    }
    const incident = createGovernanceIncident(voltDb, {
      ...body,
      org_id: orgId,
      incident_type: body.incident_type || 'manual',
    });
    res.status(201).json({ incident });
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

// GET /governance/incidents — Paginated, filtered list for the caller's org
app.get('/governance/incidents', requireServiceOrUserAuth(), (req, res) => {
  if (!voltDb) return res.status(503).json({ error: 'Incident storage not available' });
  const orgId = resolveIncidentOrgId(req);
  if (!orgId) return res.status(401).json({ error: 'org_id could not be resolved from auth context' });
  try {
    const {
      severity, status, incident_type, agent_id, corr,
      since, until, limit, offset,
    } = req.query;
    if (severity && !INCIDENT_SEVERITIES.includes(severity)) {
      return res.status(400).json({ error: `severity must be one of: ${INCIDENT_SEVERITIES.join(', ')}` });
    }
    if (status && !INCIDENT_STATUSES.includes(status)) {
      return res.status(400).json({ error: `status must be one of: ${INCIDENT_STATUSES.join(', ')}` });
    }
    const result = listGovernanceIncidents(voltDb, {
      org_id: orgId,
      severity: severity || undefined,
      status: status || undefined,
      incident_type: incident_type || undefined,
      agent_id: agent_id || undefined,
      corr: corr || undefined,
      since: since || undefined,
      until: until || undefined,
      limit: limit ? Math.min(parseInt(limit, 10) || 100, 500) : 100,
      offset: offset ? parseInt(offset, 10) || 0 : 0,
    });
    res.json(result);
  } catch (err) {
    console.error('[MON-GOV] List incidents error:', err);
    res.status(500).json({ error: 'Failed to list incidents' });
  }
});

// GET /governance/incidents/:id — Detail + linked AEE envelopes (resolved by corr)
app.get('/governance/incidents/:id', requireServiceOrUserAuth(), (req, res) => {
  if (!voltDb) return res.status(503).json({ error: 'Incident storage not available' });
  const orgId = resolveIncidentOrgId(req);
  if (!orgId) return res.status(401).json({ error: 'org_id could not be resolved from auth context' });
  try {
    const incident = getGovernanceIncident(voltDb, req.params.id);
    if (!incident) return res.status(404).json({ error: 'Incident not found' });
    if (incident.org_id !== orgId) return res.status(404).json({ error: 'Incident not found' });

    // Lazily resolve linked envelopes by corr from aeeDb. Failures are
    // non-fatal — the incident detail still renders.
    let envelopes = [];
    if (aeeDb && incident.corr) {
      try {
        const rows = aeeDb
          .prepare('SELECT id, ts, type, "from", "to", intent FROM envelopes WHERE corr = ? ORDER BY ts ASC LIMIT 200')
          .all(incident.corr);
        envelopes = rows;
      } catch (envErr) {
        console.warn('[MON-GOV] envelope lookup failed:', envErr.message);
      }
    }
    res.json({ incident, envelopes });
  } catch (err) {
    console.error('[MON-GOV] Get incident error:', err);
    res.status(500).json({ error: 'Failed to get incident' });
  }
});

// PATCH /governance/incidents/:id — Update status / resolution / assignment / severity
app.patch('/governance/incidents/:id', requireServiceOrUserAuth(), (req, res) => {
  if (!voltDb) return res.status(503).json({ error: 'Incident storage not available' });
  const orgId = resolveIncidentOrgId(req);
  if (!orgId) return res.status(401).json({ error: 'org_id could not be resolved from auth context' });
  try {
    const existing = getGovernanceIncident(voltDb, req.params.id);
    if (!existing) return res.status(404).json({ error: 'Incident not found' });
    if (existing.org_id !== orgId) return res.status(404).json({ error: 'Incident not found' });

    const patch = req.body || {};
    if (patch.severity === 'critical' && existing.severity !== 'critical' && !isAdminCaller(req)) {
      return res.status(403).json({ error: 'admin role required to escalate to critical severity' });
    }
    const updated = updateGovernanceIncident(voltDb, req.params.id, patch);
    // MON-GOV-3: refire SIEM dispatch so status/resolution changes propagate.
    Promise.resolve(dispatchGovernanceIncident(voltDb, updated))
      .catch((err) => console.warn('[MON-GOV] webhook dispatch (patch) failed:', err?.message || err));
    res.json({ incident: updated });
  } catch (err) {
    if (err.message && err.message.toLowerCase().includes('not found')) {
      return res.status(404).json({ error: err.message });
    }
    res.status(400).json({ error: err.message });
  }
});

// POST /governance/incidents/:id/witness — Emit witness envelope, WARD stamps receipt
app.post('/governance/incidents/:id/witness', requireServiceOrUserAuth(), (req, res) => {
  if (!voltDb) return res.status(503).json({ error: 'Incident storage not available' });
  const orgId = resolveIncidentOrgId(req);
  if (!orgId) return res.status(401).json({ error: 'org_id could not be resolved from auth context' });
  try {
    const incident = getGovernanceIncident(voltDb, req.params.id);
    if (!incident) return res.status(404).json({ error: 'Incident not found' });
    if (incident.org_id !== orgId) return res.status(404).json({ error: 'Incident not found' });

    // Emit the witness envelope through the standard AEE pipeline so WARD
    // hooks it automatically (wardHookAOCL) and EventStreamHub broadcasts.
    let receipt = null;
    try {
      storeAuditEnvelope({
        type: 'event',
        from: 'system.governance',
        to: 'system.ward',
        intent: 'governance.incident.witnessed',
        corr: incident.corr,
        payload: {
          incident_id: incident.id,
          org_id: incident.org_id,
          severity: incident.severity,
          policy_id: incident.policy_id,
          framework_mapping: incident.framework_mapping,
        },
      });
      receipt = `aee:witnessed:${incident.corr}`;
    } catch (envErr) {
      console.warn('[MON-GOV] witness envelope emit failed:', envErr.message);
    }

    const updated = updateGovernanceIncident(voltDb, req.params.id, {
      witnessed_by_ward: true,
      witness_receipt: receipt,
    });
    // MON-GOV-3: fan witnessed event out to SIEMs too.
    Promise.resolve(dispatchGovernanceIncident(voltDb, updated))
      .catch((err) => console.warn('[MON-GOV] webhook dispatch (witness) failed:', err?.message || err));
    res.json({ incident: updated });
  } catch (err) {
    console.error('[MON-GOV] Witness error:', err);
    res.status(500).json({ error: 'Failed to witness incident' });
  }
});

// ============================================================
// MON-GOV-3: Governance webhook configuration API
// ============================================================
//
// SIEM delivery targets. All routes require admin role for user callers
// (webhooks are infra config, not user-tenant data); internal services
// can manage webhooks via INTERNAL_SERVICE_KEY. Secrets are encrypted
// at rest (AES-256-GCM via fieldEncryption) and never returned in
// responses — only `has_auth_secret` is surfaced.

function requireWebhookAdmin(req, res) {
  if (isAdminUser(req)) return true;
  if (!req.user) {
    res.status(401).json({ error: 'authentication_required' });
    return false;
  }
  res.status(403).json({ error: 'admin role required for webhook administration' });
  return false;
}

// fleet #370: the "Claude is not connected" auth-required message told
// every caller to "Open the Terminal" and visit dashboard Settings, even a
// CLI caller who IS in a terminal and has no browser session to open. The
// CLI sets X-Quox-Client: cli on every request (cli/lib/core/client.js) so
// this message can actually match where the caller is.
function isCliRequest(req) {
  return req.headers['x-quox-client'] === 'cli';
}

const NO_PROVIDER_MESSAGE = 'No AI is connected yet. Pick one: /connect openai (recommended), /connect anthropic, /connect ollama <host>, or /connect for the list. In the dashboard: Settings → Core Integrations.';

const CLAUDE_NOT_CONNECTED_MESSAGE = {
  dashboard: 'Claude is not connected. Open the Terminal to sign in with your Claude subscription. An API key in Settings → Core Integrations also works if you prefer.',
  dashboardHint: 'Open the Terminal to sign in with your Claude subscription, or add an API key in Settings → Core Integrations.',
  cli: 'No LLM provider configured. Run: quox vault create --type anthropic\nOr configure in the dashboard at Settings → Core Integrations.',
};

function resolveWebhookOrgId(req) {
  // Routes are nested under :orgId. For user callers the path orgId
  // must match req.user.org_id; admins across orgs can override via
  // INTERNAL_SERVICE_KEY.
  const pathOrg = req.params.orgId;
  if (req.user && req.user.org_id && pathOrg !== req.user.org_id) return null;
  return pathOrg;
}

