// ============================================================
// BLAST-RADIUS-P0: agent reach resolver
// ============================================================
// GET /orgs/:orgId/agents/:agentId/reach — an agent's static reachability
// closure computed from existing governed registries (tools, vault
// credential assignments, bastion fleet hosts, the per-org QLarity egress
// allowlist, and the canDelegateTo delegation graph). See
// lib/reach/reachResolver.js for the source-by-source contract and the
// honesty rules (a source failure is never reported as an empty array).
// Same org-scope pattern as /orgs/:orgId/governance-webhooks above:
// requireServiceOrUserAuth() (service-key OR JWT), path orgId must match
// the caller's JWT org for a user caller, service callers pass through.
// BLAST-RADIUS-P2: consumes the shared runtime (lib/reach/runtime.js) set
// up once above, rather than building its own resolver instance — same
// resolveStaticReach every trigger uses, and every evaluation is witnessed
// via auditReachEvaluation (trigger 'api').
const { getReachRuntime, getCachedStaticReach, auditReachEvaluation: auditReachEvaluationApi } = require('./lib/reach/runtime.js');

function resolveReachOrgId(req) {
  const pathOrg = req.params.orgId;
  if (req.user && req.user.org_id && pathOrg !== req.user.org_id) return null;
  return pathOrg;
}

app.get('/orgs/:orgId/agents/:agentId/reach', requireServiceOrUserAuth(), async (req, res) => {
  const orgId = resolveReachOrgId(req);
  if (!orgId) return res.status(403).json({ error: 'org scope mismatch' });
  try {
    const { resolveStaticReach } = getReachRuntime();
    const result = await resolveStaticReach(req.params.agentId, orgId);
    auditReachEvaluationApi({ trigger: 'api', orgId, agentId: req.params.agentId, result });
    res.json(result);
  } catch (err) {
    console.error('[BLAST-RADIUS] reach resolve error:', err.message);
    res.status(500).json({ error: 'Failed to resolve agent reach' });
  }
});

// ============================================================
// BLAST-RADIUS-P4: predicted-vs-actual least-privilege reporting.
// ============================================================
// Wires lib/reach/leastPrivilege.js's computeLeastPrivilege() to three real
// sources: the shared reach runtime's cached static resolver (same P0
// closure the approval gate and the GET /reach route use), the AEE
// envelope statement layer (aeeStatements.queryOrgScoped — no hand-rolled
// SQL in the lib itself), and the auth service's internal per-agent
// credential-usage route (Deliverable 2), reached the same
// AUTH_SERVICE_URL + X-Service-Key pattern every other internal auth call
// in this file uses (see resolveCredentials in reachResolver.js).
const { computeLeastPrivilege } = require('./lib/reach/leastPrivilege.js');

function queryEnvelopesForLeastPrivilege(filter) {
  if (!aeeStatements) {
    // Loud, not silent: an uninitialised statement layer must surface as a
    // source error (unknown coverage), never as an empty "nothing was used".
    throw new Error('AEE statement layer not initialised');
  }
  // Payloads are stored ENCRYPTED (encryptEnvelopeFields at ingest); raw rows
  // parse to nothing and every tool_name reads null — which rendered a live
  // agent as "0/24 used" on 2026-09-20. Decrypt exactly like /aee/query does.
  // #923: the generic queryOrgScoped shape walked the org's whole history for one agent; this read is
  // always one agent since a window start, so it uses the pinned ("from", ts) statement.
  if (filter.from && filter.after) {
    return aeeStatements.queryAgentEnvelopesSince.all({
      from: filter.from,
      after: filter.after,
      orgId: filter.orgId,
      limit: filter.limit ?? 5000,
    }).map((r) => decryptEnvelopeRow(r)).filter(Boolean);
  }
  return aeeStatements.queryOrgScoped.all({
    type: null,
    intent: null,
    from: filter.from ?? null,
    to: null,
    after: filter.after ?? null,
    before: null,
    corr: null,
    orgId: filter.orgId,
    limit: filter.limit ?? 5000,
  }).map((r) => decryptEnvelopeRow(r)).filter(Boolean);
}

async function fetchAgentCredentialUsageForLeastPrivilege(agentId, orgId, windowDays) {
  const authBase = process.env.AUTH_SERVICE_URL || 'http://auth:3101';
  const serviceKey = process.env.INTERNAL_SERVICE_KEY;
  const url = `${authBase}/internal/orgs/${encodeURIComponent(orgId)}/agents/${encodeURIComponent(agentId)}/credential-usage?days=${encodeURIComponent(windowDays)}`;
  const headers = serviceKey ? { 'X-Service-Key': serviceKey } : {};
  const resp = await fetch(url, {
    headers,
    signal: typeof AbortSignal !== 'undefined' && AbortSignal.timeout ? AbortSignal.timeout(5000) : undefined,
  });
  if (!resp || !resp.ok) {
    throw new Error(`credential-usage fetch failed: HTTP ${resp ? resp.status : 'no-response'}`);
  }
  return resp.json();
}

app.get('/orgs/:orgId/agents/:agentId/reach/least-privilege', requireServiceOrUserAuth(), async (req, res) => {
  const orgId = resolveReachOrgId(req);
  if (!orgId) return res.status(403).json({ error: 'org scope mismatch' });
  const parsedDays = parseInt(req.query.days, 10);
  const windowDays = Number.isFinite(parsedDays) ? Math.max(1, Math.min(365, parsedDays)) : 30;
  try {
    const result = await computeLeastPrivilege(
      { agentId: req.params.agentId, orgId, windowDays },
      {
        getCachedStaticReach,
        queryEnvelopes: queryEnvelopesForLeastPrivilege,
        fetchCredentialUsage: fetchAgentCredentialUsageForLeastPrivilege,
      },
    );
    auditReachEvaluationApi({ trigger: 'least_privilege', orgId, agentId: req.params.agentId, result });
    res.json(result);
  } catch (err) {
    console.error('[BLAST-RADIUS-P4] least-privilege compute error:', err.message);
    res.status(500).json({ error: 'Failed to compute least-privilege report' });
  }
});

// ── OPGOV quox#573: org agent inventory — the org-wide rollup of the SAME
// grant graph reach evaluates per-agent. Enumeration is shared (deps below
// hand the resolver getCachedStaticReach and computeLeastPrivilege), never
// forked; UNKNOWN stays first-class at registry, agent and layer level.
const { resolveOrgInventory } = require('./lib/reach/inventory.js');
const inventoryAssistantLoader = require('./lib/entityAssistantLoader.js');

async function computeInventoryForOrg(orgId, { includeUnused = false, windowDays = 30 } = {}) {
  return resolveOrgInventory(
      // The org-wide unused pass is 61 agents x an AEE-window query each and
      // measured 6+ minutes inline — that is phase 3's offline snapshot job.
      // Opt-in only; per-agent depth is `quox reach unused <agent>` today.
      { orgId, includeUnused, unusedWindowDays: windowDays, concurrency: 10 },
      {
        listCoreAssistants: () => inventoryAssistantLoader.listAssistants()
          .map((id) => inventoryAssistantLoader.getAssistant(id))
          .filter(Boolean),
        fetchOrgAgents: async (org) => {
          try {
            const base = process.env.AUTH_SERVICE_URL || 'http://quox-auth:3101';
            const resp = await fetch(`${base}/internal/agents?org_id=${encodeURIComponent(org)}`, {
              headers: { 'x-service-key': process.env.INTERNAL_SERVICE_KEY || '' },
              signal: AbortSignal.timeout(5000),
            });
            if (!resp.ok) return { ok: false, error: `auth ${resp.status}` };
            const data = await resp.json();
            return {
              ok: true,
              items: (data.agents || []).map((a) => ({
                id: a.agentId,
                name: a.name,
                model: (a.llm && a.llm.model) || null,
                provider: (a.llm && a.llm.provider) || null,
              })),
            };
          } catch (err) {
            return { ok: false, error: err.message };
          }
        },
        // A CMDB read tolerates 10 minutes of reach staleness (generated_at
        // is stamped; drift detection is phase 3's job). This is what makes a
        // re-run interactive: the first cold rollup pays ~2-4 min of resolver
        // fetches across the org, the next reads the warm cache.
        getReach: (agentId, org) => getCachedStaticReach(agentId, org, { ttlMs: 10 * 60 * 1000 }),
        // Strict honesty: an unused count is only a number when BOTH the
        // tools and credentials layers resolved with attributable coverage;
        // a partial count would understate risk with confidence.
        getUnused: async (agentId, org, days) => {
          const lp = await computeLeastPrivilege(
            { agentId, orgId: org, windowDays: days },
            {
              getCachedStaticReach,
              queryEnvelopes: queryEnvelopesForLeastPrivilege,
              fetchCredentialUsage: fetchAgentCredentialUsageForLeastPrivilege,
            },
          );
          const tools = lp && lp.layers && lp.layers.tools;
          const creds = lp && lp.layers && lp.layers.credentials;
          if (!Array.isArray(tools && tools.unused_list) || !Array.isArray(creds && creds.unused_list)) return {};
          return { unused_count: tools.unused_list.length + creds.unused_list.length };
        },
      },
  );
}

function emitInventoryAudit(intent, orgId, payload) {
  try {
    getReachRuntime().audit({
      type: 'event',
      from: 'collector.reach',
      to: 'audit.system',
      intent,
      corr: `REACH_INV_${Date.now()}`,
      org_id: orgId,
      payload,
    });
  } catch (auditErr) {
    console.warn('[Inventory] audit envelope emit failed (non-fatal):', auditErr.message);
  }
}

app.get('/orgs/:orgId/inventory', requireServiceOrUserAuth(), async (req, res) => {
  const orgId = resolveReachOrgId(req);
  if (!orgId) return res.status(403).json({ error: 'org scope mismatch' });
  const parsedDays = parseInt(req.query.days, 10);
  const windowDays = Number.isFinite(parsedDays) ? Math.max(1, Math.min(365, parsedDays)) : 30;
  try {
    const result = await computeInventoryForOrg(orgId, { includeUnused: req.query.unused === 'true', windowDays });
    emitInventoryAudit('quox.reach.inventory', orgId, {
      trigger: 'api',
      totals: result.totals,
      registry_unknowns: result.unknowns.length,
      duration_ms: result.duration_ms,
    });
    res.json(result);
  } catch (err) {
    console.error('[OPGOV-INVENTORY] compute error:', err.message);
    res.status(500).json({ error: 'Failed to compute org inventory' });
  }
});

// OPGOV quox#573 phase 3: witnessed drift. Diffs a fresh rollup against the
// last stored snapshot (aeeDb inventory_snapshots, newest 30 kept per org),
// stores the fresh one as the new baseline, and witnesses the delta.
const { runDrift: runInventoryDrift } = require('./lib/reach/inventoryDrift.js');
app.get('/orgs/:orgId/inventory/drift', requireServiceOrUserAuth(), async (req, res) => {
  const orgId = resolveReachOrgId(req);
  if (!orgId) return res.status(403).json({ error: 'org scope mismatch' });
  if (!aeeDb) return res.status(503).json({ error: 'snapshot store unavailable' });
  try {
    const inventory = await computeInventoryForOrg(orgId);
    const result = runInventoryDrift({ db: aeeDb, orgId, inventory });
    emitInventoryAudit('quox.reach.inventory_drift', orgId, {
      trigger: 'api',
      baseline: result.baseline,
      snapshot_id: result.snapshot_id,
      prev_taken_at: result.prev_taken_at,
      changed: result.drift ? result.drift.changed : false,
      agents_added: result.drift ? result.drift.agents_added.length : 0,
      agents_removed: result.drift ? result.drift.agents_removed.length : 0,
      model_changes: result.drift ? result.drift.model_changes.length : 0,
      reach_changes: result.drift ? result.drift.reach_changes.length : 0,
      visibility_changes: result.drift ? result.drift.visibility_changes.length : 0,
    });
    res.json(result);
  } catch (err) {
    console.error('[OPGOV-INVENTORY] drift error:', err.message);
    res.status(500).json({ error: 'Failed to compute inventory drift' });
  }
});

// ── OPGOV quox#582 phase 2: the governance compiler's draft-review-arm flow.
// A plain-language rule compiles DETERMINISTICALLY (lib/governance/
// ruleCompiler.js) to a quox-policy.v1 draft, stored inert; arming requires
// a HUMAN identity (a policy nobody read is not governance). Enforcement is
// phase 3 and waits on IMPACT #491's approval-binds-dispatch primitive:
// nothing here is consulted by any execution path yet, and no surface may
// claim otherwise.
const { compileRule } = require('./lib/governance/ruleCompiler.js');
const policyStore = require('./lib/governance/policyStore.js');

app.post('/orgs/:orgId/governance/policies/compile', requireServiceOrUserAuth(), (req, res) => {
  const orgId = resolveReachOrgId(req);
  if (!orgId) return res.status(403).json({ error: 'org scope mismatch' });
  if (!aeeDb) return res.status(503).json({ error: 'policy store unavailable' });
  const rule = (req.body && req.body.rule) || '';
  const compiled = compileRule(rule);
  if (!compiled.ok) {
    emitInventoryAudit('quox.governance.policy_compile', orgId, { compiled: false, reason: compiled.reason });
    return res.status(422).json(compiled);
  }
  try {
    const record = policyStore.saveDraft(aeeDb, {
      orgId,
      policy: compiled.policy,
      createdBy: (req.user && req.user.id) || 'service',
    });
    emitInventoryAudit('quox.governance.policy_compile', orgId, {
      compiled: true, policy_id: record.id, effect: record.policy.effect, state: record.state,
    });
    res.status(201).json({ ok: true, record });
  } catch (err) {
    console.error('[OPGOV-POLICY] compile store error:', err.message);
    res.status(500).json({ error: 'Failed to store compiled policy' });
  }
});

app.get('/orgs/:orgId/governance/policies', requireServiceOrUserAuth(), (req, res) => {
  const orgId = resolveReachOrgId(req);
  if (!orgId) return res.status(403).json({ error: 'org scope mismatch' });
  if (!aeeDb) return res.status(503).json({ error: 'policy store unavailable' });
  const state = ['draft', 'armed', 'retired'].includes(req.query.state) ? req.query.state : undefined;
  res.json({ policies: policyStore.listPolicies(aeeDb, orgId, { state }) });
});

app.post('/orgs/:orgId/governance/policies/:id/arm', requireServiceOrUserAuth(), (req, res) => {
  const orgId = resolveReachOrgId(req);
  if (!orgId) return res.status(403).json({ error: 'org scope mismatch' });
  if (!aeeDb) return res.status(503).json({ error: 'policy store unavailable' });
  // Review-before-arm is load-bearing: a bare service key has no human who
  // read the compiled policy, so it may compile and list but never arm.
  const approver = req.user && req.user.id;
  if (!approver) {
    return res.status(403).json({ error: 'human_approval_required', message: 'Arming a policy requires a logged-in human approver, not a service key.' });
  }
  const result = policyStore.armPolicy(aeeDb, { orgId, id: req.params.id, approvedBy: `human.${approver}` });
  if (!result.ok) {
    const status = result.error === 'not_found' ? 404 : 409;
    return res.status(result.error === 'human_approval_required' ? 403 : status).json({ error: result.error });
  }
  emitInventoryAudit('quox.governance.policy_arm', orgId, {
    policy_id: req.params.id, approved_by: `human.${approver}`, effect: result.policy.policy.effect,
  });
  res.json({ ok: true, record: result.policy });
});

