// CRP-BE-5: Periodic job runner — checks for due jobs every 60 seconds
// Runs server-side, no browser required
let complianceJobRunner = null;
function startComplianceJobRunner() {
  if (complianceJobRunner || !complianceStatements || !aeeStatements) return;

  complianceJobRunner = setInterval(async () => {
    try {
      const jobs = complianceStatements.getActiveJobs.all();
      const now = new Date().toISOString();

      for (const job of jobs) {
        if (!job.next_run || job.next_run > now) continue;

        console.log(`[Compliance] Running scheduled job ${job.id} (${job.format}, ${job.schedule_interval})`);
        try {
          // Calculate period
          const end = new Date();
          const start = new Date();
          switch (job.schedule_interval) {
            case 'daily': start.setDate(start.getDate() - 1); break;
            case 'weekly': start.setDate(start.getDate() - 7); break;
            case 'monthly': start.setMonth(start.getMonth() - 1); break;
          }

          // Gather AEE data from server-side SQLite (not IndexedDB!)
          const envelopes = aeeStatements.query.all(
            null, null, null, null, null, null, null, null,
            start.toISOString(), start.toISOString(),
            end.toISOString(), end.toISOString(),
            10000
          ).map(row => decryptEnvelopeRow(row)).filter(e => e !== null);

          const stats = aeeStatements.stats.get();
          const periodDays = Math.ceil((end - start) / (1000 * 60 * 60 * 24));

          // Build minimal report summary for server-side storage
          const summary = {
            totalTraces: envelopes.length,
            totalConversations: stats.conversations || 0,
            totalLayerEvents: envelopes.filter(e => e.intent?.startsWith('aocl.')).length,
            uniqueAgents: [...new Set(envelopes.map(e => e.to).filter(Boolean))].length
          };

          // Store report
          const reportId = `RPT_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`;
          // GOV-TRUTH tail: compliance_jobs now carries the creating caller's
          // org_id (migrations/volt/005-compliance-jobs-org-id-column.sql,
          // captured at POST /compliance/jobs) — propagate it onto the report
          // this run generates. Jobs created before this migration, or with
          // no resolvable org at creation time, still have org_id=null here,
          // which remains the honest value (never fabricated).
          complianceStatements.insertReport.run(
            reportId, job.id, job.format,
            start.toISOString(), end.toISOString(), periodDays,
            JSON.stringify(summary),
            JSON.stringify({ format: job.format, period: { start: start.toISOString(), end: end.toISOString(), days: periodDays }, summary }),
            job.org_id || null
          );

          // Update job
          const nextRun = calculateComplianceNextRun(job.schedule_interval, job.schedule_day_of_week, job.schedule_day_of_month);
          complianceStatements.updateJob.run(now, nextRun, null, job.id);
          console.log(`[Compliance] Job ${job.id} completed — report ${reportId}, next run ${nextRun}`);
        } catch (err) {
          console.error(`[Compliance] Job ${job.id} failed:`, err.message);
          const nextRun = calculateComplianceNextRun(job.schedule_interval, job.schedule_day_of_week, job.schedule_day_of_month);
          complianceStatements.updateJob.run(now, nextRun, err.message, job.id);
        }
      }
    } catch (err) {
      console.error('[Compliance] Job runner error:', err.message);
    }
  }, 60000); // Check every 60 seconds

  complianceJobRunner.unref?.();
  console.log('[Compliance] Server-side job runner started (60s interval)');
}

// Start the job runner after DB init
if (complianceStatements) {
  startComplianceJobRunner();
}

// ============================================================
// MON-GOV-4: Governance behaviour baseline runner
// ============================================================
//
// Its own cron — the complianceJobRunner is single-purpose (reports).
// Recomputes baselines every 24 h and runs anomaly detection every
// minute against the current hour. On boot we do an immediate baseline
// pass so a restart after an overnight outage catches up without
// waiting a full day.

let governanceBaselineRunner = null;
let governanceAnomalyRunner = null;
function startGovernanceBaselineRunner() {
  if (!voltDb) return;
  if (governanceBaselineRunner && governanceAnomalyRunner) return;

  // Catch-up pass: delayed (not at boot) and chunked/yielding so a restart never
  // freezes the event loop (was ~26 s synchronous at boot, 2026-10-11).
  // The daily run takes the same yielding path: the sync version froze the loop once
  // a day too (WORKER7 2026-10-15). baselineRunning keeps a slow run from overlapping.
  let baselineRunning = false;
  const runBaseline = async (label) => {
    if (baselineRunning) return;
    baselineRunning = true;
    try {
      // Deferred (bounded) while the host is saturated; every deploy re-fires the catch-up.
      const wait = await require('./lib/bootYield.js').waitForQuietHost();
      const t0 = Date.now();
      const rows = await computeAgentBaselinesAsync(voltDb);
      if (rows.length) console.log(`[MON-GOV] ${label}: ${rows.length} summaries computed (${Date.now() - t0}ms${wait.waitedMs ? `, after waiting ${Math.round(wait.waitedMs / 60000)}m for load${wait.quiet ? '' : ' (still loaded)'}` : ''})`);
    } catch (err) {
      console.warn(`[MON-GOV] ${label} failed:`, err.message);
    } finally {
      baselineRunning = false;
    }
  };
  const baselineCatchupTimer = setTimeout(() => runBaseline('baseline catch-up'), 180000);
  baselineCatchupTimer.unref?.();

  governanceBaselineRunner = setInterval(async () => {
    await runBaseline('daily baseline');
  }, 24 * 60 * 60 * 1000);
  governanceBaselineRunner.unref?.();

  governanceAnomalyRunner = setInterval(() => {
    try {
      const fired = detectAgentAnomalies(voltDb);
      if (fired.length) {
        // Anomaly incidents are created via createIncident() inside the
        // detector — but the detector does NOT emit governance.incident.created,
        // since it bypasses the AOCL emitter wrap. Fan them out here so WARD
        // witnesses + SIEMs + the UI stream all see them — but only on
        // first-insert. `_inserted` flag on the returned row tells us this
        // so the 60s scheduler doesn't flood downstream sinks for a
        // sustained spike.
        const freshFires = fired.filter((f) => f._inserted);
        if (freshFires.length) {
          console.log(`[MON-GOV] anomaly detector fired ${freshFires.length} new incident(s)`);
        }
        for (const f of freshFires) {
          const inc = getGovernanceIncident(voltDb, f.incident_id);
          if (!inc) continue;
          try {
            storeAuditEnvelope({
              type: 'event',
              from: 'system.governance',
              to: 'system.aee',
              intent: 'governance.incident.created',
              corr: inc.corr,
              payload: {
                incident_id: inc.id,
                org_id: inc.org_id,
                incident_type: inc.incident_type,
                severity: inc.severity,
                layer: inc.layer,
                agent_id: inc.agent_id,
                framework_mapping: inc.framework_mapping,
                sigma: f.sigma,
                metric: f.metric,
              },
            });
          } catch (selfErr) {
            console.warn('[MON-GOV] anomaly self-envelope failed:', selfErr.message);
          }
          Promise.resolve(dispatchGovernanceIncident(voltDb, inc))
            .catch((err) => console.warn('[MON-GOV] anomaly webhook dispatch failed:', err?.message || err));
        }
      }
    } catch (err) {
      console.warn('[MON-GOV] anomaly detector failed:', err.message);
    }
  }, 60 * 1000);
  governanceAnomalyRunner.unref?.();

  console.log('[MON-GOV] baseline runner started (daily recompute, 60s anomaly check)');
}

if (voltDb) {
  startGovernanceBaselineRunner();
}

