/**
 * Request RFC 3161 timestamp from a public TSA.
 * Builds DER-encoded TimeStampReq, POSTs to FreeTSA.org, returns timestamp record.
 * Non-fatal: returns null on failure.
 */
async function requestRFC3161Timestamp(hexHash) {
  const TSA_URL = process.env.VOLT_TSA_URL || 'https://freetsa.org/tsr';
  const SHA256_OID = [0x60, 0x86, 0x48, 0x01, 0x65, 0x03, 0x04, 0x02, 0x01];

  function derLength(len) {
    if (len < 0x80) return [len];
    if (len < 0x100) return [0x81, len];
    return [0x82, (len >> 8) & 0xff, len & 0xff];
  }
  function derSeq(items) {
    const body = Buffer.concat(items.map(i => Buffer.from(i)));
    return Buffer.from([0x30, ...derLength(body.length), ...body]);
  }

  const hashBytes = Buffer.from(hexHash, 'hex');
  const algId = derSeq([Buffer.from([0x06, SHA256_OID.length, ...SHA256_OID])]);
  const msgImprint = derSeq([algId, Buffer.from([0x04, ...derLength(hashBytes.length), ...hashBytes])]);
  const version = Buffer.from([0x02, 0x01, 0x01]);
  const certReq = Buffer.from([0x01, 0x01, 0xff]);
  const tsReq = derSeq([version, msgImprint, certReq]);

  const resp = await fetch(TSA_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/timestamp-query' },
    body: tsReq,
    signal: AbortSignal.timeout(10000),
  });

  if (!resp.ok) throw new Error(`TSA HTTP ${resp.status}`);

  const tsrBuffer = await resp.arrayBuffer();
  const tsr_base64 = Buffer.from(tsrBuffer).toString('base64');

  return {
    ts_version: '0.1',
    tsa_url: TSA_URL,
    requested_at: new Date().toISOString(),
    hash_alg: 'sha256',
    hash: hexHash,
    tsr_base64
  };
}

/**
 * Sign a bundle manifest. Thin wrapper around lib/bundleSigner.js that
 * injects the WARD keypair accessor. Extracted 2026-04-12 so the real
 * function can be unit-tested directly.
 */
const { signBundleManifest: _signBundleManifestLib } = require('./lib/bundleSigner.js');
async function signBundleManifest(manifest) {
  return _signBundleManifestLib(manifest, { getHookKeypair });
}

/**
 * AUDIT-REAL #2: real Ed25519 signature detection + verification for VOLT
 * certification. Reads BOTH the real singular `bundle.signature` shape
 * (what bundleSigner.js/voltContentStore.js actually persist) and the
 * legacy/spec plural `bundle.signatures` array, and cryptographically
 * verifies each signature before counting it as signed.
 */
const { evaluateBundleSignatures, verifyTimestamps } = require('./lib/volt-certifier.js');

/**
 * Inline certification engine for CJS collector context.
 * Mirrors the logic from volt-certifier.js (ESM).
 */
async function runCertification(input, events, bundle) {
  const crypto = require('crypto');
  const GENESIS_HASH = '0'.repeat(64);
  const TIER_NAMES = { bronze: 'VOLT-Compatible', silver: 'VOLT-Verified', gold: 'VOLT-Attested', platinum: 'VOLT-Enterprise' };
  const TIER_ORDER = ['bronze', 'silver', 'gold', 'platinum'];

  const REQUIRED_EVENT_FIELDS = ['volt_version', 'event_id', 'run_id', 'seq', 'ts', 'event_type', 'actor', 'context', 'prev_hash', 'hash'];
  const AEE_EVENT_TYPES = ['aee.envelope.received', 'aee.envelope.sent', 'aee.message.parsed', 'aee.message.rejected'];

  function canonicalize(val) {
    if (val === null || val === undefined) return JSON.stringify(val);
    if (typeof val !== 'object') return JSON.stringify(val);
    if (Array.isArray(val)) return '[' + val.map(v => canonicalize(v)).join(',') + ']';
    const sorted = Object.keys(val).filter(k => val[k] !== undefined).sort();
    return '{' + sorted.map(k => JSON.stringify(k) + ':' + canonicalize(val[k])).join(',') + '}';
  }
  function sha256(data) {
    return crypto.createHash('sha256').update(data).digest('hex');
  }

  const checks = [];

  // BRONZE
  if (events.length === 0) {
    checks.push({ code: 'NO_EVENTS', passed: false, message: 'No events found', tier: 'bronze' });
    return buildCertResult(events, bundle, checks, TIER_ORDER, TIER_NAMES);
  }
  checks.push({ code: 'NO_EVENTS', passed: true, message: `${events.length} events found`, tier: 'bronze' });

  const aeeEvts = events.filter(e => AEE_EVENT_TYPES.includes(e.event_type));
  const hasAeeCtx = events.some(e => e.context?.aee_envelope_id);
  const aeeOk = aeeEvts.length > 0 || hasAeeCtx;
  checks.push({ code: 'MISSING_AEE_ENVELOPES', passed: aeeOk, message: aeeOk ? `AEE integration confirmed (${aeeEvts.length} AEE events)` : 'No AEE integration found', tier: 'bronze' });

  let schemaErrors = 0;
  const missing = new Set();
  for (const evt of events) {
    for (const f of REQUIRED_EVENT_FIELDS) {
      if (evt[f] === undefined || evt[f] === null) { schemaErrors++; missing.add(f); }
    }
  }
  checks.push({ code: 'INVALID_EVENT_SCHEMA', passed: schemaErrors === 0, message: schemaErrors === 0 ? `All ${events.length} events valid schema` : `${schemaErrors} schema violations (${[...missing].join(', ')})`, tier: 'bronze' });

  let actorErr = 0;
  for (const e of events) { if (!e.actor || !e.actor.actor_type || !e.actor.actor_id) actorErr++; }
  checks.push({ code: 'MISSING_ACTOR', passed: actorErr === 0, message: actorErr === 0 ? 'All events have valid actor' : `${actorErr} actor violations`, tier: 'bronze' });

  const ctxMiss = events.filter(e => !e.context).length;
  checks.push({ code: 'MISSING_CONTEXT', passed: ctxMiss === 0, message: ctxMiss === 0 ? 'All events have context' : `${ctxMiss} missing context`, tier: 'bronze' });

  const started = events.some(e => e.event_type === 'run.started');
  const ended = events.some(e => e.event_type === 'run.completed' || e.event_type === 'run.failed');
  checks.push({ code: 'MISSING_RUN_LIFECYCLE', passed: started && ended, message: started && ended ? 'Run lifecycle complete' : 'Missing lifecycle events', tier: 'bronze' });

  // SILVER
  let chainValid = true, seqValid = true, genesisValid = true, validCount = 0, firstFail = null;
  const gen = events[0];
  if (gen.seq !== 1) { genesisValid = false; seqValid = false; }
  if (gen.prev_hash !== GENESIS_HASH) { genesisValid = false; chainValid = false; }
  if (gen.event_type !== 'run.started') genesisValid = false;

  let expPrev = GENESIS_HASH;
  for (let i = 0; i < events.length; i++) {
    const e = events[i];
    let ok = true;
    if (e.seq !== i + 1) { ok = false; seqValid = false; }
    if (e.prev_hash !== expPrev) { ok = false; chainValid = false; }
    const { hash: _h, ...rest } = e;
    const comp = sha256(canonicalize(rest));
    if (comp !== e.hash) { ok = false; chainValid = false; if (!firstFail) firstFail = { seq: i + 1, detail: 'Hash mismatch' }; }
    if (ok) validCount++;
    expPrev = e.hash;
  }

  checks.push({ code: 'CHAIN_INTEGRITY_FAILED', passed: chainValid, message: chainValid ? `Hash chain intact (${validCount}/${events.length})` : `Chain broken at seq ${firstFail?.seq || '?'}`, tier: 'silver' });
  checks.push({ code: 'SEQUENCE_GAPS', passed: seqValid, message: seqValid ? `Sequence monotonic (1-${events.length})` : 'Sequence gaps', tier: 'silver' });
  checks.push({ code: 'GENESIS_VALID', passed: genesisValid, message: genesisValid ? 'Genesis valid' : 'Genesis invalid', tier: 'silver' });

  // GOLD
  const manifest = bundle?.manifest;
  // AUDIT-REAL #3: real RFC 3161 cryptographic verification (parses,
  // message imprint, CMS signature, CA chain) rather than presence-only —
  // distinguishes "no timestamp" from "timestamp present but invalid" so
  // a tampered/forged receipt cannot pass Gold certification.
  const tsResult = await verifyTimestamps(manifest);
  if (!tsResult.present) {
    checks.push({ code: 'NO_TIMESTAMP', passed: false, message: 'No external timestamp', tier: 'gold' });
  } else if (!tsResult.any_valid) {
    const firstError = tsResult.results.find(r => r.errors?.length)?.errors?.[0];
    checks.push({ code: 'TIMESTAMP_INVALID', passed: false, message: `${tsResult.results.length} RFC 3161 timestamp(s) present but failed verification${firstError ? `: ${firstError}` : ''}`, tier: 'gold' });
  } else {
    const validCount = tsResult.results.filter(r => r.valid).length;
    checks.push({ code: 'NO_TIMESTAMP', passed: true, message: `${validCount}/${tsResult.results.length} RFC 3161 timestamp(s) cryptographically verified`, tier: 'gold' });
  }

  // VOLT-CERT-BIND: bind the signature to this bundle's manifest AND verify
  // against the collector's PINNED signing key (getHookKeypair). A transplanted
  // or attacker-keyed signature no longer certifies as valid.
  const sigEval = evaluateBundleSignatures(bundle, { pinnedPublicKey: getHookKeypair()?.publicKey || null });
  // QUOXTRUST T8/D6 (FND_..SC..) — GOLD requires an IDENTITY-verified signature: one
  // that verified against the collector's PINNED key (signature_trust === 'pinned'), not
  // merely a self-consistent bundle-EMBEDDED key (self-signed → signer identity NOT
  // verified). The old gate used has_signatures/any_valid and messaged "Ed25519-verified
  // valid", so a self-signed bundle earned the same GOLD badge as a pinned-identity one.
  // Fail-closed: if no pinned key is available (WARD down), nothing earns GOLD signature.
  const _sigPinned = sigEval.signature_trust === 'pinned';
  checks.push({
    code: 'NO_SIGNATURE',
    passed: _sigPinned,
    message: sigEval.signatures.length > 0
      ? (_sigPinned
          ? `${sigEval.signatures.length} signature(s) found, pinned Ed25519 identity-verified valid`
          : sigEval.any_valid
            ? `${sigEval.signatures.length} signature(s) found but self-signed (embedded key); signer identity NOT verified against the pinned collector key`
            : `${sigEval.signatures.length} signature(s) found but none verified valid`)
      : 'No bundle signature',
    tier: 'gold'
  });

  const rd = input.retentionInfo?.retention_days;
  if (rd !== undefined) {
    checks.push({ code: 'RETENTION_TOO_SHORT', passed: rd >= 30, message: rd >= 30 ? `Retention: ${rd} days` : `Retention: ${rd} days (need 30)`, tier: 'gold' });
  } else if (manifest?.started_at) {
    const age = Math.floor((Date.now() - new Date(manifest.started_at).getTime()) / 86400000);
    checks.push({ code: 'RETENTION_TOO_SHORT', passed: age >= 30, message: age >= 30 ? `Retained ${age} days` : `${age} day(s) old (need 30)`, tier: 'gold' });
  } else {
    checks.push({ code: 'RETENTION_TOO_SHORT', passed: false, message: 'No retention info', tier: 'gold' });
  }

  // PLATINUM
  const ai = input.auditInfo;
  checks.push({ code: 'NO_THIRD_PARTY_AUDIT', passed: !!(ai?.auditor && ai?.audit_date), message: ai?.auditor ? `Audit by ${ai.auditor}` : 'No third-party audit', tier: 'platinum' });

  const ci = input.complianceInfo;
  checks.push({ code: 'NO_COMPLIANCE_BUNDLE', passed: !!(ci?.frameworks?.length), message: ci?.frameworks?.length ? `Compliance: ${ci.frameworks.join(', ')}` : 'No compliance evidence', tier: 'platinum' });

  const ec = ci?.evidence_count || 0;
  checks.push({ code: 'INSUFFICIENT_EVIDENCE', passed: ec >= 10, message: ec >= 10 ? `${ec} evidence items` : `${ec} items (need 10)`, tier: 'platinum' });

  return buildCertResult(events, bundle, checks, TIER_ORDER, TIER_NAMES);
}

function buildCertResult(events, bundle, checks, TIER_ORDER, TIER_NAMES) {
  const crypto = require('crypto');
  const tiers = {};
  for (const tier of TIER_ORDER) {
    const tierChecks = checks.filter(c => c.tier === tier);
    const idx = TIER_ORDER.indexOf(tier);
    const lowerPass = TIER_ORDER.slice(0, idx).every(t => tiers[t]);
    tiers[tier] = lowerPass && tierChecks.every(c => c.passed);
  }

  let highest = null;
  for (const t of TIER_ORDER) { if (tiers[t]) highest = t; }

  const now = new Date();
  const expires = new Date(now.getTime() + 90 * 86400000);
  const certId = 'CERT_' + now.getTime().toString(36).toUpperCase() + crypto.randomBytes(8).toString('hex').toUpperCase().slice(0, 10);

  return {
    cert_id: certId,
    run_id: events.length > 0 ? events[0].run_id : bundle?.manifest?.run_id || null,
    bundle_id: bundle?.manifest?.bundle_id || null,
    tier: highest,
    tier_name: highest ? TIER_NAMES[highest] : 'None',
    tiers,
    checks,
    certified_at: now.toISOString(),
    expires_at: expires.toISOString(),
    summary: {
      total_checks: checks.length,
      passed: checks.filter(c => c.passed).length,
      failed: checks.filter(c => !c.passed).length,
      event_count: events.length,
      has_bundle: !!bundle,
      has_signatures: evaluateBundleSignatures(bundle, { pinnedPublicKey: getHookKeypair()?.publicKey || null }).has_signatures,
      has_timestamps: !!(bundle?.manifest?.timestamps?.length)
    }
  };
}

/**
 * Inline SVG badge generator for collector (CJS).
 */
function generateCertBadgeSVG(tier, certId, expiresAt, tierName) {
  const COLORS = {
    bronze:   { bg: '#432818', border: '#CD7F32', text: '#CD7F32' },
    silver:   { bg: '#2a2a30', border: '#C0C0C0', text: '#C0C0C0' },
    gold:     { bg: '#3a3010', border: '#FFD700', text: '#FFD700' },
    platinum: { bg: '#2e2e32', border: '#E5E4E2', text: '#E5E4E2' }
  };
  const c = COLORS[tier] || { bg: '#1a1a1e', border: 'rgba(255,255,255,0.15)', text: 'rgba(255,255,255,0.3)' };
  const shortId = certId ? certId.slice(0, 15) : '';
  const expiry = expiresAt ? expiresAt.split('T')[0] : '';
  const label = (tierName || tier || 'None').toUpperCase();

  return `<svg xmlns="http://www.w3.org/2000/svg" width="240" height="80" viewBox="0 0 240 80">
  <rect x="1" y="1" width="238" height="78" rx="8" ry="8" fill="${c.bg}" stroke="${c.border}" stroke-width="1.5"/>
  <g transform="translate(16, 40)">
    <path d="M0,-16 L12,-10 L12,4 C12,12 0,18 0,18 C0,18 -12,12 -12,4 L-12,-10 Z" fill="none" stroke="${c.text}" stroke-width="1.5"/>
    <path d="M-4,1 L-1,4 L5,-2" fill="none" stroke="${c.text}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
  </g>
  <text x="38" y="22" font-family="system-ui,sans-serif" font-size="11" font-weight="700" fill="${c.text}" letter-spacing="0.5">VOLT ${label}</text>
  <text x="38" y="37" font-family="system-ui,sans-serif" font-size="10" fill="${c.text}" opacity="0.8">${tierName || ''}</text>
  <text x="38" y="54" font-family="monospace" font-size="8" fill="${c.text}" opacity="0.5">${shortId}</text>
  ${expiry ? `<text x="38" y="67" font-family="system-ui,sans-serif" font-size="8" fill="${c.text}" opacity="0.4">Expires ${expiry}</text>` : ''}
</svg>`;
}

// ============================================================================
// GDPR User Data Deletion (Security Issue #57)
// ============================================================================

/**
 * DELETE /api/v1/users/:userId/data
 * Delete all data associated with a user (GDPR Art. 17 - Right to Erasure)
 * Called by the auth service during account deletion
 */
// FND_01M4HZQ5P004YSXH0BWY04YSXH follow-up: retry failed erasure legs every
// 5 minutes (backoff, failure accounting and loud retirement live in the outbox).
const gdprErasureOutbox = require('./lib/gdprErasureOutbox.js');
setInterval(() => {
  if (!aeeDb) return;
  try { gdprErasureOutbox.ensureTable(aeeDb); } catch (e) { console.error(`[GDPR] erasure outbox unavailable: ${e.message}`); return; }
  gdprErasureOutbox.drainTick(aeeDb, { runCascade: require('./lib/gdprErasureCascade.js').runErasureCascade })
    .then((r) => { if (r.due) console.log(`[GDPR] erasure retry tick: ${JSON.stringify(r)}`); })
    .catch((e) => console.error(`[GDPR] erasure retry tick failed: ${e.message}`));
}, 5 * 60_000).unref();

app.delete('/api/v1/users/:userId/data', async (req, res) => {
  const { userId } = req.params;
  const { email, reason } = req.body || {};

  // SEC-GDPR-SPOOF: the old gate checked req.headers['x-internal-service'] ===
  // 'auth-service' with no secret — a client-supplied header any caller could
  // set, letting anyone bulk-delete another org's data. Now requires the
  // same timing-safe X-Service-Key compare used elsewhere in this file
  // (requireInstanceServiceKey, tool-definitions/install|uninstall). Fails
  // closed if INTERNAL_SERVICE_KEY is unset.
  if (!verifyInternalServiceKey(req)) {
    console.warn(`[GDPR] Unauthorized data deletion attempt for user ${userId} (missing/invalid X-Service-Key)`);
    return res.status(401).json({ error: 'service_key_required' });
  }

  if (!userId) {
    return res.status(400).json({ error: 'Missing userId' });
  }

  console.log(`[GDPR] Data deletion request for user ${userId} (reason: ${reason || 'not specified'})`);

  // quox#706: erase the user's server-side chat session turns too.
  try {
    const turnsDeleted = require('./lib/chatSessionHistory.js').purgeUser(userId);
    console.log(`[GDPR] Deleted ${turnsDeleted} chat session turn(s) for user ${userId}`);
  } catch (turnErr) {
    console.warn(`[GDPR] chat session turn purge failed: ${turnErr.message}`);
  }

  const userIdPattern = `%${escapeLike(userId)}%`;
  const emailPattern = email ? `%${escapeLike(email)}%` : `%${escapeLike(userId)}%`;

  // FND_01M4HZQ5P004YSXH0BWY04YSXH: erase the user's QuoxMemory rows and Brain2
  // notes too. The brain copies of their conversations are keyed by envelope
  // corr, so collect those BEFORE the envelopes are purged below.
  const gdprCascade = require('./lib/gdprErasureCascade.js');
  let convRows = [];
  try {
    if (aeeDb) convRows = aeeDb.prepare(`SELECT DISTINCT org_id, corr FROM envelopes
      WHERE ("from" LIKE ? ESCAPE '\\' OR "from" LIKE ? ESCAPE '\\') AND corr IS NOT NULL AND org_id IS NOT NULL`).all(userIdPattern, emailPattern);
  } catch (convErr) {
    console.warn(`[GDPR] conversation lookup for brain erasure failed: ${convErr.message}`);
  }
  const cascade = await gdprCascade.runErasureCascade(userId, { conversations: gdprCascade.conversationsFromRows(convRows) });
  if (!cascade.complete) console.error(`[GDPR] erasure cascade INCOMPLETE for user ${userId}: memory=${cascade.memory.ok ? 'ok' : cascade.memory.error} brain=${cascade.brain.ok ? 'ok' : cascade.brain.error} tasks=${cascade.tasks.ok ? 'ok' : cascade.tasks.error}`);
  const cascadeOut = { complete: cascade.complete, memory: cascade.memory, brain: cascade.brain, tasks: cascade.tasks };
  // A failed leg is retried durably (gdprErasureOutbox), with the conversation
  // relPaths stored now because the envelopes are purged just below.
  if (!cascade.complete && aeeDb) {
    try {
      gdprErasureOutbox.ensureTable(aeeDb);
      gdprErasureOutbox.enqueue(aeeDb, userId, gdprCascade.conversationsFromRows(convRows), `memory=${cascade.memory.ok ? 'ok' : cascade.memory.error} brain=${cascade.brain.ok ? 'ok' : cascade.brain.error} tasks=${cascade.tasks.ok ? 'ok' : cascade.tasks.error}`);
      cascadeOut.retryQueued = true;
    } catch (qErr) {
      console.error(`[GDPR] could not queue erasure retry for user ${userId}: ${qErr.message}`);
      cascadeOut.retryQueued = false;
    }
  }

  if (!aeeDb) {
    return res.status(cascade.complete ? 200 : 502).json({
      deleted: cascade.complete,
      message: 'No AEE storage configured',
      user_id: userId,
      cascade: cascadeOut,
    });
  }

  try {
    // Find all envelopes where user is the actor (from field contains user email or id)
    // Note: This is a best-effort deletion since envelope "from" field may contain various formats
    // Issue 1.11: Added ESCAPE clause and escapeLike() for LIKE injection prevention
    const deleteByUserId = aeeDb.prepare(`
      DELETE FROM envelopes
      WHERE "from" LIKE ? ESCAPE '\\' OR "from" LIKE ? ESCAPE '\\'
    `);

    const result = deleteByUserId.run(userIdPattern, emailPattern);

    console.log(`[GDPR] Deleted ${result.changes} envelopes for user ${userId}`);

    // Audit the deletion itself (stored AFTER deletion so this envelope survives)
    storeAuditEnvelope({
      type: 'event',
      from: 'system.gdpr',
      to: 'system.aee',
      intent: 'gdpr.data.purged',
      corr: `GDPR_${userId}`,
      payload: {
        user_id: userId,
        reason: reason || 'gdpr_erasure_request',
        envelopes_deleted: result.changes,
        cascade_complete: cascade.complete,
      }
    });

    // A partial erasure is reported as such (502), never as done.
    res.status(cascade.complete ? 200 : 502).json({
      deleted: cascade.complete,
      cascade: cascadeOut,
      envelopes_deleted: result.changes,
      user_id: userId,
      reason: reason || 'gdpr_erasure_request',
      deleted_at: new Date().toISOString()
    });
  } catch (err) {
    console.error('[GDPR] Data deletion error:', err);
    res.status(500).json({ error: 'Failed to delete user data' });
  }
});

/**
 * GET /api/v1/users/:userId/data
 * Get all data associated with a user for GDPR data export
 * Called by the auth service during data export
 */
app.get('/api/v1/users/:userId/data', (req, res) => {
  const { userId } = req.params;

  // SEC-GDPR-SPOOF: see the DELETE handler above for why this is now a
  // timing-safe X-Service-Key compare instead of a spoofable bare header.
  if (!verifyInternalServiceKey(req)) {
    console.warn(`[GDPR] Unauthorized data export attempt for user ${userId} (missing/invalid X-Service-Key)`);
    return res.status(401).json({ error: 'service_key_required' });
  }

  if (!userId) {
    return res.status(400).json({ error: 'Missing userId' });
  }

  if (!aeeDb) {
    return res.json({
      user_id: userId,
      conversations: [],
      envelope_count: 0
    });
  }

  try {
    // Find all conversations involving this user
    // Issue 1.11: Added ESCAPE clause and escapeLike() for LIKE injection prevention
    const userConversations = aeeDb.prepare(`
      SELECT DISTINCT corr
      FROM envelopes
      WHERE "from" LIKE ? ESCAPE '\\' OR "to" LIKE ? ESCAPE '\\'
    `).all(`%${escapeLike(userId)}%`, `%${escapeLike(userId)}%`);

    // Get envelope count
    const envelopeCount = aeeDb.prepare(`
      SELECT COUNT(*) as count
      FROM envelopes
      WHERE "from" LIKE ? ESCAPE '\\' OR "to" LIKE ? ESCAPE '\\'
    `).get(`%${escapeLike(userId)}%`, `%${escapeLike(userId)}%`);

    res.json({
      user_id: userId,
      conversations: userConversations.map(c => c.corr),
      envelope_count: envelopeCount?.count || 0
    });
  } catch (err) {
    console.error('[GDPR] Data export error:', err);
    res.status(500).json({ error: 'Failed to export user data' });
  }
});

// ============================================================================
// Voice Endpoints (native)
// ============================================================================

const multer = require('multer');
const upload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 25 * 1024 * 1024 } });
const { handleSpeak, handleSpeakStream, handleTranscribe } = require('./lib/voiceHandlers');

/**
 * GET /voice/status - Check if voice API keys are configured
 * Returns: { stt: bool, tts: bool }
 */
app.get('/voice/status', async (req, res) => {
  try {
    const { getVoiceKeyStatus } = require('./lib/voiceHandlers');
    const status = await getVoiceKeyStatus();
    res.json(status);
  } catch (err) {
    res.json({ stt: false, tts: false, error: err.message });
  }
});

/**
 * POST /voice/speak - Text-to-Speech via ElevenLabs
 * Body: { text, voice_mode?, voice_id?, model_id? }
 * Returns: audio/mpeg binary
 */
app.post('/voice/speak', async (req, res) => {
  const start = Date.now();
  // AEE-CORE-3.2: capture TTS attempts in the audit trail with model, duration,
  // text length, and outcome. Uses resolveCorrelationId so the envelope inherits
  // the triggering chat's corr when the dashboard supplies session_id.
  const voiceCorr = resolveCorrelationId(req, req.body || {});
  const textLen = (req.body?.text || '').length;
  try {
    await handleSpeak(req, res);
    storeAuditEnvelope({
      type: 'event',
      from: `agent.${req.body?.voice_mode || 'quox'}`,
      to: 'audit.system',
      intent: 'quox.voice.speak',
      corr: voiceCorr,
      payload: {
        model: req.body?.model_id || 'elevenlabs',
        voice_mode: req.body?.voice_mode,
        voice_id: req.body?.voice_id,
        text_length: textLen,
        duration_ms: Date.now() - start,
        success: res.statusCode < 400,
        status_code: res.statusCode,
      }
    });
  } catch (err) {
    console.error('[Voice] Speak error:', err);
    storeAuditEnvelope({
      type: 'error',
      from: 'system.voice',
      to: 'audit.system',
      intent: 'quox.voice.speak.failed',
      corr: voiceCorr,
      payload: { text_length: textLen, duration_ms: Date.now() - start, error: (err.message || '').slice(0, 200) }
    });
    if (!res.headersSent) {
      res.status(500).json({ error: 'Internal voice error' });
    }
  }
});

/**
 * POST /voice/speak/stream - streaming TTS via ElevenLabs (QUOX-VOICE P2)
 * Body: { text, voice_mode?, voice_id?, model_id? }
 * Returns: audio/mpeg, chunk-streamed as synthesis proceeds.
 * Same governed vault key path as /voice/speak; the witness envelope lands
 * once the response finishes (or on client abort), since duration and
 * success are only known then. Audio bytes are streamed by handleSpeakStream
 * itself, so this wrapper must NOT touch res beyond the audit emit.
 */
app.post('/voice/speak/stream', async (req, res) => {
  const start = Date.now();
  const voiceCorr = resolveCorrelationId(req, req.body || {});
  const textLen = (req.body?.text || '').length;
  res.on('close', () => {
    storeAuditEnvelope({
      type: 'event',
      from: `agent.${req.body?.voice_mode || 'quox'}`,
      to: 'audit.system',
      intent: 'quox.voice.speak_stream',
      corr: voiceCorr,
      payload: {
        model: req.body?.model_id || 'eleven_flash_v2_5',
        voice_mode: req.body?.voice_mode,
        voice_id: req.body?.voice_id,
        text_length: textLen,
        duration_ms: Date.now() - start,
        success: res.statusCode < 400,
        status_code: res.statusCode,
        streamed: true,
      },
    });
  });
  try {
    await handleSpeakStream(req, res);
  } catch (err) {
    console.error('[Voice] Speak stream error:', err);
    if (!res.headersSent) res.status(500).json({ error: 'Internal voice error' });
  }
});

/**
 * POST /voice/transcribe - Speech-to-Text via OpenAI Whisper
 * Body: FormData with 'audio' file
 * Returns: { text, success }
 */
app.post('/voice/transcribe', upload.single('audio'), async (req, res) => {
  const start = Date.now();
  // AEE-CORE-3.2: capture STT attempts. Audio text itself is omitted from the
  // payload (privacy); we log length + outcome only.
  const voiceCorr = resolveCorrelationId(req, req.body || {});
  const fileBytes = req.file?.buffer?.length || 0;
  try {
    await handleTranscribe(req, res);
    storeAuditEnvelope({
      type: 'event',
      from: `human.${req.user?.id || 'unknown'}`,
      to: 'audit.system',
      intent: 'quox.voice.transcribe',
      corr: voiceCorr,
      payload: {
        model: 'whisper-1',
        provider: 'openai',
        audio_bytes: fileBytes,
        mime_type: req.file?.mimetype,
        duration_ms: Date.now() - start,
        success: res.statusCode < 400,
        status_code: res.statusCode,
      }
    });
  } catch (err) {
    console.error('[Voice] Transcribe error:', err);
    storeAuditEnvelope({
      type: 'error',
      from: 'system.voice',
      to: 'audit.system',
      intent: 'quox.voice.transcribe.failed',
      corr: voiceCorr,
      payload: { audio_bytes: fileBytes, duration_ms: Date.now() - start, error: (err.message || '').slice(0, 200) }
    });
    if (!res.headersSent) {
      res.status(500).json({ error: 'Internal voice error', text: '' });
    }
  }
});

