// ── RepoBrain private repos — git credential broker (owner 2026-10-05) ────
// The RepoBrain engine calls this, service-key authenticated, right before it
// clones/fetches a target marked auth:'org_github'. Returns ONLY that org's own
// mapped GitHub credential (never the shared '_global' fallback or the
// instance GITHUB_TOKEN), only for https://github.com/<owner>/<repo>. The token
// is never logged; the audit record carries org + repo + outcome only.
app.post('/api/internal/nucleus/git-credential', async (req, res) => {
  const { hasInternalServiceKey } = require('./lib/toolsListForAgent.js');
  if (!hasInternalServiceKey(req)) return res.status(401).json({ error: 'service key required' });
  const { org_id: orgId, repo_url: repoUrl } = req.body || {};
  const { brokerGitCredential } = require('./lib/repobrainGitCredential.js');
  const { getGitHubToken } = require('./routes/github-proxy.js');
  const r = await brokerGitCredential({ orgId, repoUrl }, { resolveOrgToken: getGitHubToken });
  try {
    auditOp('ops.nucleus.git_credential', { org_id: orgId || null, repo: String(repoUrl || '').slice(0, 200), granted: r.ok, code: r.ok ? null : r.code });
  } catch (_e) { /* audit is best-effort */ }
  if (!r.ok) return res.status(r.code === 'no_org_github_credential' ? 404 : 400).json({ error: r.code });
  res.set('Cache-Control', 'no-store');
  return res.json({ username: r.username, password: r.password });
});

// ── CORECOMMS-LOOP — internal channel-reply endpoint ────────────────────────
// The auth service calls this after a human responds to an inbox item that
// carries channel origin metadata (payload.source + chat_id/slack_user_id,
// minted by telegramWebhook.js/slackWebhook.js createInboxItem for an
// unknown sender). Service-key guarded, mirrors the qluster/tool-approval
// resume endpoints immediately above. Fire-and-forget: responds 202 fast,
// dispatches the reply through the channel driver registry
// (notificationService -> lib/channels/registry.js -> drivers/telegram.js
// or drivers/slack.js) async so a slow/unreachable channel API never blocks
// the auth-side inbox response.
app.post(
  '/api/internal/channels/reply',
  createChannelReplyEndpoint({
    sendNotification: require('./lib/notificationService.js').sendNotification,
    getConversation: require('./lib/channelConversationStore.js').getConversation,
    serviceKey: process.env.INTERNAL_SERVICE_KEY,
  })
);

// ── QLUSTER-LOOP-B Phase 5 — signed retrieval endpoint ──────────────────────
// The external controller polls its delegation result by corr. Self-authenticates
// via requireQlusterScope('agent.delegate') — a scoped bearer + an Ed25519-signed
// envelope (operational scope). corr is semi-guessable, so cross-controller reads
// are blocked by ORG-SCOPE (allowed_orgs), NOT by corr secrecy.
//
// Phase 3A — self-healing retrieval (split-brain recovery). Wires the SAME
// qlusterResume executor used by the auth-push resume path, so a lost
// auth→collector push (collector down at the exact moment a human approves)
// self-heals on the next poll instead of leaving the row pending_hitl forever.
app.get(
  '/api/v1/qluster/delegate/:corr',
  requireQlusterScope('agent.delegate', { getDb: qlusterDb }),
  createDelegateResultHandler({
    store: qlusterDelegationStore,
    runResume: qlusterResume,
    authBaseUrl: process.env.AUTH_SERVICE_URL || 'http://quox-auth:3101',
    serviceKey: process.env.INTERNAL_SERVICE_KEY,
  })
);

// AOCL-CUTOVER-2b: exposes current stack mode + shadow-mode parity metrics.
// Read-only; no auth requirement since it returns no PII or secrets.
// AOCL-DISPATCH-0: renamed from /chat/status (duplicate of the chat-readiness
// route at ~11480 which Express resolves first, making this unreachable).
app.get('/chat/aocl-status', (req, res) => {
  try {
    const { getStackMode } = require('./lib/aoclStackMode.js');
    const { getShadowMetrics } = require('./lib/shadowRunner.js');
    res.json({
      mode: getStackMode(),
      shadow: getShadowMetrics(),
    });
  } catch (err) {
    res.status(500).json({ error: 'chat_status_failed', message: err.message });
  }
});

app.post('/chat/policy-cache/invalidate', adaptiveChatLimiter, async (req, res) => {
  try {
    const orgId = req.body?.org_id || null;
    invalidatePolicyCache(orgId);
    res.json({ ok: true, org_id: orgId });
  } catch (error) {
    console.error('[PolicyCache] Invalidate error:', error);
    res.status(500).json({ error: 'Failed to invalidate policy cache' });
  }
});
// VAULT-ADVERSARIAL-VERIFICATION fix: this route resolves org-scoped vault
// credential labels (resolveCredentialById) and org LLM routing policy — an
// existence + label oracle if left open. Gated exactly like its /chat and
// /chat/claude siblings (requireServiceOrUserAuth) so an unauthenticated
// caller can no longer reach it. Org is resolved via resolveRequestOrgId(req)
// (the same helper /internal/embed uses post-gate) rather than trusting
// req.body.org_id directly — a service-key caller may still name an org
// explicitly via body (resolveRequestOrgId's explicit-org branch), which
// keeps the internal caller path (posting org_id with X-Service-Key) working.
app.post('/chat/resolve-plan', adaptiveChatLimiter, requireServiceOrUserAuth(), async (req, res) => {
  try {
    const resolvedOrgId = resolveRequestOrgId(req);
    // AOCL-FULL-2: L1 identity + L3 policy pre-check before the GOV-5 execution
    // policy evaluation. Previously /chat/resolve-plan only ran a post-check;
    // now it goes through the same gate as every other chat entry point.
    // QUOXTRUST FND_..S9XR (T2) — the pre-LLM gate now FAILS CLOSED on a throw (was
    // fail-open here, unlike its /chat/stream + unified-provider siblings). Routed
    // through lib/preLLMGate.js so the fail-closed behaviour is one testable unit.
    {
      const { setupPipelinePhase, SOURCES } = require('./lib/pipelineSetup.js');
      const { runPreLLMPipeline } = require('./lib/aoclPipeline.js');
      const { preLLMGate } = require('./lib/preLLMGate.js');
      const gate = await preLLMGate({
        voltDb, req, source: SOURCES.RESOLVE_PLAN,
        deps: { setupPipelinePhase, runPreLLMPipeline },
      });
      if (!gate.proceed) return res.status(gate.refusal.status).json(gate.refusal.body);
      if (gate.aoclCtx) req._aoclCtx = gate.aoclCtx;
    }

    // GOV-5: Check execution policies from the governance store before resolving
    if (voltDb) {
      const { getExecutionConstraints } = require('./lib/executionPolicyEvaluator.js');
      const execCtx = {
        'agent.id': req.body?.selected_agent || 'quox',
        capability: req.body?.capability_override || 'general_assistant',
        'org.id': resolvedOrgId || '',
      };
      const constraints = getExecutionConstraints(voltDb, resolvedOrgId || '__default__', execCtx);
      if (constraints.denied) {
        // MON-GOV-1c: Emit aocl.policy.reject so this denial flows through the
        // same incident pipe as AOCL layer rejections. Fire-and-forget.
        try {
          const corr = req.body?.conversation_id || req.body?.corr || `RESOLVE_${Date.now()}`;
          storeAuditEnvelope({
            type: 'error',
            from: 'system.aocl',
            to: 'system.aee',
            intent: 'aocl.policy.reject',
            corr,
            payload: {
              agent: execCtx['agent.id'],
              orgId: resolvedOrgId || '__default__',
              capability: execCtx.capability,
              reason: constraints.denyReason,
              matchedPolicies: constraints.matchedPolicies,
            },
          });
        } catch (envErr) {
          console.warn('[MON-GOV] resolve-plan denial envelope failed:', envErr.message);
        }
        return res.status(403).json({
          error: constraints.denyReason,
          deniedByPolicy: true,
          matchedPolicies: constraints.matchedPolicies,
        });
      }
      // Attach warnings to response later
      if (constraints.warnings.length > 0) {
        req._govWarnings = constraints.warnings;
        req._govMatchedPolicies = constraints.matchedPolicies;
      }
    }

    const cookies = parseCookieHeader(req.headers.cookie);
    const userAccessToken = cookies.access_token || '';
    const requestedCredentialId = req.body?.credential_id || null;
    // VAULT-P6.D: org_id threaded (same source this handler already uses for
    // providerKeys/claudeKeys/policy plan below) so resolve-by-id can reject
    // a credential_id belonging to a different org (P6-F1).
    const vaultCredential = requestedCredentialId ? await resolveCredentialById(requestedCredentialId, resolvedOrgId) : null;
    const providerKeys = await getProviderKeys(resolvedOrgId);
    const claudeKeys = await getClaudeKeys(resolvedOrgId);
    const localSource = (req.body?.local_source_id || req.body?.source_id)
      // SEC-LOCAL-INF-ORG-CHAT (quox#599): org-scoped, same resolvedOrgId
      // source this handler already uses above.
      ? resolveLocalSource(req.body?.local_source_id || req.body?.source_id, req.body, resolvedOrgId)
      : null;
    const { plan, policyPayload, policyContext } = await resolveCollectorPolicyPlan({
      orgId: resolvedOrgId,
      userAccessToken,
      selectedAgent: req.body?.selected_agent || 'quox',
      capabilityOverride: req.body?.capability_override || null,
      requestedProvider: req.body?.provider,
      requestedModel: req.body?.model,
      requestedCredentialId,
      credentialMeta: vaultCredential ? {
        id: requestedCredentialId,
        provider: vaultCredential.provider,
        label: vaultCredential.label,
      } : null,
      policyOverride: req.body?.policy_override || null,
      personalPreferenceOverride: req.body?.personal_preference_override || null,
      anthropicApiKey: claudeKeys.anthropic_api_key || process.env.ANTHROPIC_API_KEY || '',
      cliOAuthToken: claudeKeys.claude_oauth_token || '',
      providerKeys,
      localSource,
    });

    res.json({
      source: policyPayload.source,
      policy: policyPayload.record,
      policyContext,
      executionPlan: plan,
      ...(req._govWarnings?.length ? { govWarnings: req._govWarnings, govMatchedPolicies: req._govMatchedPolicies } : {}),
    });
  } catch (error) {
    console.error('[ResolvePlan] Error:', error);
    if (error.validationErrors?.length) {
      return res.status(400).json({
        error: error.message || 'Invalid execution policy override',
        validation_errors: error.validationErrors,
      });
    }
    res.status(500).json({ error: 'Failed to resolve execution plan' });
  }
});

// ============================================================================
// Decision Evidence — system prompt injection + response parsing
// ============================================================================

/**
 * Build system prompt instructions for decision evidence capture.
 * @param {string} level - 'minimal' | 'standard' | 'full'
 * @returns {string} System prompt fragment
 */
function buildDecisionEvidenceInstructions(level) {
  const base = `\n\n## Decision Evidence (Required)
When responding, include a JSON block at the end of your response within <decision_evidence> tags containing structured evidence of your decision process.`;

  const fields = {
    minimal: `Include: "decision" (what you decided), "reason_summary" (why, 1-2 sentences).`,
    standard: `Include: "inputs_used" (array of input names/refs), "tools_used" (array of tool names called), "decision" (what you decided), "reason_summary" (why, 1-2 sentences), "action_taken" (what you did), "confidence" (0-1).`,
    full: `Include: "inputs_used" (array of input names/refs), "context_refs" (array of source IDs/locators), "tools_used" (array of tool names called), "decision" (what you decided), "reason_summary" (why, 1-2 sentences), "action_taken" (what you did), "confidence" (0-1).`
  };

  return base + '\n' + (fields[level] || fields.standard) + `
Keep it compact. Use references (IDs, names) not full content.
Example:
<decision_evidence>
{"decision":"deploy_hotfix","reason_summary":"Error rate exceeded 5% threshold on docker01 nginx.","action_taken":"Executed rolling restart via ssh_exec","tools_used":["ssh_exec","get_host_health"],"inputs_used":["error_log:nginx","alert:uptime_kuma_443"],"confidence":0.91}
</decision_evidence>`;
}

/**
 * Extract <decision_evidence> JSON block from Claude's response text.
 * @param {string} responseText - The full response from Claude
 * @returns {object|null} Parsed decision evidence or null
 */
function extractDecisionEvidence(responseText) {
  if (!responseText) return null;
  const match = responseText.match(/<decision_evidence>\s*([\s\S]*?)\s*<\/decision_evidence>/);
  if (!match) return null;
  try {
    return JSON.parse(match[1]);
  } catch {
    return null;
  }
}

// ============================================================================
// PATH 1: Anthropic Messages API with native tool_use
// Used when ANTHROPIC_API_KEY is available
// ============================================================================
async function handleMessagesApi(req, res, opts) {
  // AOCL-DISPATCH Phase 1: thin wrapper — logic lives in
  // lib/claudeMessagesDispatcher.js as a req/res-free L7 dispatcher.
  const { dispatchClaudeMessages } = require('./lib/claudeMessagesDispatcher.js');

  // P10.7.3 — register the chat session so wb_emit's capture aligns with the
  // pull below. Same pattern as handleClaudeCliWithTools (P10.7.2). The
  // earlier fixes only patched the CLI path; this is the API path that the
  // /chat/claude endpoint actually uses for WEAVER (per collector log:
  // "[MCP] CLI call" routes through here, NOT handleClaudeCliWithTools).
  const chatSessionForCapture =
    opts.effectiveSessionId
    || opts.session_id
    || `chat-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
  console.log(`[handleMessagesApi] chat session for canvas capture: ${chatSessionForCapture} (effectiveSessionId=${opts.effectiveSessionId || 'none'}, session_id=${opts.session_id || 'none'})`);
  try {
    const { setActiveChatSession } = require('./lib/canvasActionCapture');
    setActiveChatSession(chatSessionForCapture);
  } catch { /* never block */ }

  const result = await dispatchClaudeMessages(
    {
      ...opts,
      userId: req.body?.user_id,
      orgId: req.body?.org_id,
      delegationDepth: req.body?._delegation_depth,
      voiceMode: req.body?.voice_mode,
    },
    {
      fetchFn: fetch,
      executeTool,
      voltEmitter,
      voltDb,
      voltStatements,
      persistVoltContent,
      storeAuditEnvelope,
      emitAgentSession,
      emitAgentEvent,
      imageStore,
      getCollectorMirrorCompact,
      memorySystemPrompt,
      actionSystemPrompt,
      buildDecisionEvidenceInstructions,
      extractVoiceSummary,
      extractDecisionEvidence,
      generateEnvelopeId,
      bastionHost: process.env.BASTION_HOST || '',
    },
  );

  if (result.outcome === 'auth_failed') {
    return res.json({
      success: false,
      result: result.authHint || result.text,
      voice_summary: result.voiceSummary,
      error: 'auth_required',
      hint: result.authHint || result.text,
      settings_path: '/settings',
      agent_used: opts.selected_agent,
      can_continue: false,
    });
  }

  if (result.outcome === 'tool_limit') {
    return res.json({
      success: true,
      result: result.text,
      voice_summary: result.voiceSummary,
      session_id: opts.effectiveSessionId,
      agent_used: opts.selected_agent,
      tools_used: result.toolsUsed,
      ...(Array.isArray(result.toolOutcomes)&&result.toolOutcomes.length?{tool_outcomes:result.toolOutcomes}:{}), // #889
      can_continue: true,
    });
  }

  // outcome === 'success'
  // TOOLSMITH-UX-4: Extract proposed_patch envelope when agent is toolsmith.
  let messagesApiProposedPatch = null;
  let messagesApiResultText = result.text;
  if (opts.selected_agent === 'toolsmith') {
    try {
      const { extractProposedPatch } = require('./lib/proposedPatchExtractor');
      const extracted = extractProposedPatch(messagesApiResultText);
      messagesApiResultText = extracted.strippedText;
      messagesApiProposedPatch = extracted.proposedPatch;
    } catch (patchErr) {
      console.warn('[handleMessagesApi] proposedPatchExtractor failed (non-fatal):', patchErr.message);
    }
  }
  // QUOXHAT MISSION D2 — surface the SAME structured needs_approval signal on the
  // Messages API path as on the Claude-CLI path (handleClaudeCliWithTools). Both
  // /chat and /chat/claude route through handleCollectorChat, which picks PATH 1
  // (this function) when an Anthropic API key is present and PATH 2 (CLI/OAuth)
  // otherwise. The voice bridge reads bare /chat, so the signal MUST be
  // path-independent — a gated tool call on either path returns the same
  // {approval_id, inbox_item_id, tool, summary, risk} for the bridge to detect
  // and resolve. Mirrors FND-2's lesson: a signal on one path only is not universal.
  let needsApproval = null;
  try {
    const { extractPendingApproval } = require('./lib/voiceApproval');
    needsApproval = extractPendingApproval(result.toolExecutions);
    if (!needsApproval) {
      // Fallback for the CLI/MCP path (toolExecutions result:null) and delegated
      // sub-turns — the turn-scoped registry keyed by this turn's session.
      const { peekPendingApproval } = require('./lib/pendingApprovalRegistry');
      needsApproval = peekPendingApproval(opts.effectiveSessionId);
    }
  } catch (e) {
    console.warn('[handleMessagesApi] needs_approval resolution failed (non-fatal):', e.message);
  }
  const responsePayload = {
    success: true,
    result: messagesApiResultText,
    proposed_patch: messagesApiProposedPatch,
    voice_summary: result.voiceSummary,
    session_id: opts.effectiveSessionId,
    cost_usd: 0,
    model: opts.requestedModel || catalogDefaultModel(),
    provider: opts.requestedProvider || 'anthropic',
    agent_used: opts.selected_agent,
    tools_used: result.toolsUsed,
    ...(Array.isArray(result.toolOutcomes)&&result.toolOutcomes.length?{tool_outcomes:result.toolOutcomes}:{}), // #889
    can_continue: true,
    needs_approval: needsApproval,
    decision_evidence_level: opts.decisionEvidenceLevel && opts.decisionEvidenceLevel !== 'none' ? opts.decisionEvidenceLevel : undefined,
    decision_evidence: result.decisionEvidence || undefined,
  };
  if (result.images && result.images.length > 0) {
    responsePayload.images = result.images;
  }
  if (result.richContent) {
    responsePayload.richContent = result.richContent;
  }
  // wb_emit: pull any canvas actions captured during tool execution and attach to response.
  // P10.7.3 — pull keyed by the SAME fallback chat session we used at the top
  // of this function, so capture/pull always meet on the same key.
  try {
    const { pullCanvasActions, clearActiveChatSession } = require('./lib/canvasActionCapture');
    const canvasActions = pullCanvasActions(chatSessionForCapture);
    clearActiveChatSession();
    console.log(`[handleMessagesApi] pulled ${canvasActions.length} canvas actions for session=${chatSessionForCapture}`);
    if (canvasActions.length > 0) {
      responsePayload.canvas_actions = canvasActions;
    }
  } catch { /* never block response */ }
  return res.json(responsePayload);
}

// ============================================================================
// PATH 2: Claude CLI with tool pre-execution
// Used when only OAuth subscription token is available
// Tools are executed BEFORE calling Claude, results injected as context
// ============================================================================
async function handleClaudeCliWithTools(req, res, opts) {
  // AOCL-DISPATCH Phase 2: thin wrapper — logic lives in
  // lib/claudeCliDispatcher.js as a req/res-free L7 dispatcher.
  const { spawn } = require('child_process');
  const fs = require('fs');
  const { dispatchClaudeCli } = require('./lib/claudeCliDispatcher.js');

  // P10.7.2 — register the chat session so wb_emit can fall back to it when
  // quoxmcp passes its own session ID instead of ours. Critical: when both
  // opts values are missing (new chat), GENERATE a fallback so capture has a
  // non-empty key to live under. The same fallback is used for the pull
  // below so capture/pull stay aligned.
  const chatSessionForCapture =
    opts.effectiveSessionId
    || opts.session_id
    || `chat-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
  console.log(`[handleClaudeCliWithTools] chat session for canvas capture: ${chatSessionForCapture} (effectiveSessionId=${opts.effectiveSessionId || 'none'}, session_id=${opts.session_id || 'none'})`);
  try {
    const { setActiveChatSession } = require('./lib/canvasActionCapture');
    setActiveChatSession(chatSessionForCapture);
  } catch { /* never block */ }

  // QUOXON-LATENCY: delegated specialist hops (and any /chat/claude turn) run stream-json with a
  // no-op listener so they can use a warm spare keyed by agent. QUOX_CLI_WARM_DELEGATE=0 = old path.
  const warmDelegate = process.env.QUOX_CLI_WARM_DELEGATE !== '0' && typeof opts.onStreamEvent !== 'function';
  const result = await dispatchClaudeCli(
    {
      ...opts,
      ...(warmDelegate ? { onStreamEvent: () => {}, warmKind: 'delegate' } : {}),
      userId: req.body?.user_id,
      orgId: req.body?.org_id,
      noToolsRequested: req.body?.no_tools === true || req.body?.no_tools === 'true',
      maxDurationMs: typeof req.body?._max_duration_ms === 'number' ? req.body._max_duration_ms : null,
      // quox#1090 ruling (b): a delegated sub-turn never holds the bearer past its parent's hold.
      bearerHoldUntil: req._delegatedHop === true ? (Number(req.body._bearer_hold_until) || null) : null,
      clientDisconnected: () => !!(req._clientDisconnected && req._clientDisconnected()),
    },
    {
      spawnFn: spawn,
      ...(warmDelegate ? { cliWarmPool } : {}),
      fetchFn: fetch,
      fsWriteFile: fs.writeFileSync.bind(fs),
      fsUnlink: (p) => { try { fs.unlinkSync(p); } catch {} },
      getClaudeCliHealth,
      resolveFollowUp,
      detectAndExecuteTools,
      executeTool,
      getTrackedTools,
      getTrackedToolOutcomes, // #889: the delegation path (a specialist turn) is this one
      clearTrackedTools,
      getToolCache,
      setToolCache,
      isValidUUID,
      sanitizeErrorForUser,
      voltEmitter,
      persistVoltContent,
      storeAuditEnvelope,
      emitAgentSession,
      emitAgentEvent,
      getCollectorMirrorCompact,
      memorySystemPrompt,
      actionSystemPrompt,
      extractVoiceSummary,
      generateEnvelopeId,
      runtimeHomeDir: RUNTIME_HOME_DIR,
      runtimeUser: RUNTIME_USER,
      bastionHost: process.env.BASTION_HOST || '',
      collectorPort: process.env.COLLECTOR_PORT || 9848,
      internalServiceKey: process.env.INTERNAL_SERVICE_KEY || '',
      tasksServiceUrl: process.env.TASKS_SERVICE_URL || 'http://tasks:3104',
      mcpEnabled: process.env.MCP_TOOLS_ENABLED === 'true',
    },
  );
  // D2: tag the CLI session file with its org + user (GDPR purge, TTL prune).
  require('./lib/chatSessionHistory.js').recordCliSessionFile({ orgId: opts.jwtOrgId || req.body?.org_id, userId: opts.jwtUserId || req.body?.user_id, cliSessionId: result && result.cliSessionId });

  const selectedAgent = opts.selected_agent;

  if (result.outcome === 'cli_unavailable') {
    return res.json({
      success: false,
      result: result.text,
      voice_summary: result.voiceSummary,
      error: 'cli_unavailable',
      hint: result.hint,
      settings_path: '/settings',
      agent_used: selectedAgent,
      can_continue: false,
    });
  }

  if (result.outcome === 'cli_error') {
    const body = {
      success: false,
      result: result.text,
      voice_summary: result.voiceSummary,
      error: result.errorCode || result.text,
      agent_used: selectedAgent,
      can_continue: false,
    };
    // MCP path additionally sets hint + settings_path
    if (result.path === 'mcp') {
      body.hint = result.hint || 'Claude CLI returned an error. Check API keys in Settings → Core Integrations.';
      body.settings_path = '/settings';
    }
    return res.json(body);
  }

  // outcome === 'success'
  // wb_emit: pull any canvas actions captured during tool execution.
  // P10.7.2 — pull keyed by the SAME fallback chat session ID we used for
  // setActiveChatSession above, so capture/pull always meet on the same key.
  let cliCanvasActions = [];
  try {
    const { pullCanvasActions, clearActiveChatSession } = require('./lib/canvasActionCapture');
    cliCanvasActions = pullCanvasActions(chatSessionForCapture);
    clearActiveChatSession();
    console.log(`[handleClaudeCliWithTools] pulled ${cliCanvasActions.length} canvas actions for session=${chatSessionForCapture}`);
  } catch { /* never block response */ }

  // TOOLSMITH-UX-4: Extract proposed_patch envelope when agent is toolsmith.
  let cliProposedPatch = null;
  let cliResultText = result.text;
  if (selectedAgent === 'toolsmith') {
    try {
      const { extractProposedPatch } = require('./lib/proposedPatchExtractor');
      const extracted = extractProposedPatch(cliResultText);
      cliResultText = extracted.strippedText;
      cliProposedPatch = extracted.proposedPatch;
    } catch (patchErr) {
      console.warn('[handleClaudeCliWithTools] proposedPatchExtractor failed (non-fatal):', patchErr.message);
    }
  }

  // QUOXHAT MISSION D2 — surface a structured needs_approval signal so a caller
  // (notably the voice bridge) can resolve a pending approval on the fly instead
  // of being told to click the dashboard. Additive + nullable; existing callers
  // ignore it. A gated tool call does not pause the turn, so this reads the
  // pending state out of the turn's tool results.
  let needsApproval = null;
  try {
    const { extractPendingApproval } = require('./lib/voiceApproval');
    needsApproval = extractPendingApproval(result.toolExecutions);
    if (!needsApproval) {
      // Fallback: CLI toolExecutions carry result:null, so extraction misses the
      // pending shape — read the turn-scoped registry keyed by this turn's session
      // (covers both direct CLI gating and delegated specialist sub-turns).
      const { peekPendingApproval } = require('./lib/pendingApprovalRegistry');
      needsApproval = peekPendingApproval(opts.effectiveSessionId);
    }
  } catch (e) {
    console.warn('[handleClaudeCliWithTools] needs_approval resolution failed (non-fatal):', e.message);
  }

  if (result.path === 'mcp') {
    const mcpResponse = {
      success: true,
      result: cliResultText,
      proposed_patch: cliProposedPatch,
      voice_summary: result.voiceSummary,
      // GAP-2: return the CLI's own UUID session id (resumable via `-r`),
      // not the collector's internal SESSION_-prefixed id — the latter is
      // never a valid UUID, so returning it here silently broke every
      // multi-turn `--resume` on the next request.
      session_id: result.cliSessionId || opts.effectiveSessionId,
      cost_usd: result.cost_usd,
      model: catalogDefaultModel(),
      provider: 'anthropic',
      agent_used: selectedAgent,
      tools_used: result.toolsUsed,
      ...(Array.isArray(result.toolOutcomes)&&result.toolOutcomes.length?{tool_outcomes:result.toolOutcomes}:{}), // #889
      tools_used_count: result.toolsUsed.length,
      tool_outcomes: result.toolOutcomes || undefined, // #889
      can_continue: true,
      needs_approval: needsApproval,
    };
    if (result.richContent) mcpResponse.richContent = result.richContent;
    if (cliCanvasActions.length > 0) mcpResponse.canvas_actions = cliCanvasActions;
    return res.json(mcpResponse);
  }

  // path === 'cli' (legacy)
  const cliResponse = {
    success: true,
    result: cliResultText,
    proposed_patch: cliProposedPatch,
    voice_summary: result.voiceSummary,
    session_id: result.cliSessionId || opts.session_id || 'cli-' + Date.now(),
    cost_usd: result.cost_usd,
    agent_used: selectedAgent,
    tools_used: result.toolsUsed,
    tool_outcomes: result.toolOutcomes || undefined, // #889
    can_continue: true,
    needs_approval: needsApproval,
  };
  if (cliCanvasActions.length > 0) cliResponse.canvas_actions = cliCanvasActions;
  return res.json(cliResponse);
}

// ============================================================================
// Tool results cache: per-session storage for follow-up continuity
// When a follow-up like "yes" matches no tools, re-inject previous results
// ============================================================================
const _toolResultsCache = new Map(); // session_id → { results, timestamp }
const TOOL_CACHE_TTL = 5 * 60 * 1000; // 5 minutes

function setToolCache(sessionId, results) {
  if (!sessionId || !results?.length) return;
  _toolResultsCache.set(sessionId, { results, timestamp: Date.now() });
  // Evict old entries
  if (_toolResultsCache.size > 100) {
    const now = Date.now();
    for (const [key, val] of _toolResultsCache) {
      if (now - val.timestamp > TOOL_CACHE_TTL) _toolResultsCache.delete(key);
    }
  }
}

function getToolCache(sessionId) {
  if (!sessionId) return null;
  const entry = _toolResultsCache.get(sessionId);
  if (!entry) return null;
  if (Date.now() - entry.timestamp > TOOL_CACHE_TTL) {
    _toolResultsCache.delete(sessionId);
    return null;
  }
  return entry.results;
}

// ============================================================================
// Session tool tracker: records which tools MCP called per session
// Used by MCP path to populate tools_used (since Claude CLI drives tool selection
// and the collector only sees individual /api/v1/tools/execute callbacks)
// ============================================================================
const _sessionToolTracker = new Map(); // session_id → { tools: string[], timestamp }

// MCP-AUDIT-1: Per-session MCP activity tracker for GET /api/v1/mcp/status.
// Keyed by session_id. Trimmed to 7-day TTL on every upsert write.
// Keys: session_id, agent_id, org_id, user_id, last_seen_at, host, total_calls_24h, recent_tools
const MCP_SESSION_TTL_MS = 7 * 24 * 60 * 60 * 1000; // 7 days
const MCP_RECENT_TOOLS_LIMIT = 10;
const _mcpSessionMap = new Map(); // session_id → McpSessionEntry

function _upsertMcpSession({ session_id, agent_id, org_id, user_id, host, tool_name, token_id }) {
  if (!session_id) return;
  const now = Date.now();
  const entry = _mcpSessionMap.get(session_id) || {
    session_id,
    agent_id: agent_id || 'quox',
    org_id: org_id || '',
    user_id: user_id || '',
    last_seen_at: new Date(now).toISOString(),
    host: host || '',
    total_calls_24h: 0,
    recent_tools: [],
    _calls: [], // ISO timestamps for 24h window calculation
    token_id: null,
  };

  entry.last_seen_at = new Date(now).toISOString();
  if (agent_id) entry.agent_id = agent_id;
  if (org_id) entry.org_id = org_id;
  if (user_id) entry.user_id = user_id;
  if (host) entry.host = host;
  // MCPB-HARDEN-3D: persist token_id on first call only (first-seen-token wins)
  if (token_id && !entry.token_id) entry.token_id = token_id;

  // Track call timestamps for 24h window
  entry._calls.push(now);
  const windowStart = now - 24 * 60 * 60 * 1000;
  entry._calls = entry._calls.filter(t => t >= windowStart);
  entry.total_calls_24h = entry._calls.length;

  // Bounded recent tools list (newest first)
  if (tool_name) {
    entry.recent_tools.unshift(tool_name);
    if (entry.recent_tools.length > MCP_RECENT_TOOLS_LIMIT) {
      entry.recent_tools = entry.recent_tools.slice(0, MCP_RECENT_TOOLS_LIMIT);
    }
  }

  _mcpSessionMap.set(session_id, entry);

  // Trim stale sessions (>7 days since last_seen)
  const cutoff = now - MCP_SESSION_TTL_MS;
  for (const [sid, e] of _mcpSessionMap) {
    if (new Date(e.last_seen_at).getTime() < cutoff) {
      _mcpSessionMap.delete(sid);
    }
  }
}

function trackToolExecution(sessionId, toolName, status) {
  if (!sessionId || !toolName) return;
  const entry = _sessionToolTracker.get(sessionId) || { tools: [], outcomes: [], timestamp: Date.now() };
  entry.tools.push(toolName);
  // #889: keep each call's outcome too, so a delegated specialist's tool calls can be reported
  // (with ok / failed / denied) instead of collapsing to a bare count in the parent turn.
  if (!entry.outcomes) entry.outcomes = [];
  entry.outcomes.push({ tool: toolName, status: status || 'unknown' });
  entry.timestamp = Date.now();
  _sessionToolTracker.set(sessionId, entry);
  // Evict stale entries
  if (_sessionToolTracker.size > 200) {
    const now = Date.now();
    for (const [key, val] of _sessionToolTracker) {
      if (now - val.timestamp > TOOL_CACHE_TTL) _sessionToolTracker.delete(key);
    }
  }
}

function getTrackedTools(sessionId) {
  if (!sessionId) return [];
  const entry = _sessionToolTracker.get(sessionId);
  if (!entry) return [];
  if (Date.now() - entry.timestamp > TOOL_CACHE_TTL) {
    _sessionToolTracker.delete(sessionId);
    return [];
  }
  return entry.tools;
}

function getTrackedToolOutcomes(sessionId) {
  if (!sessionId) return [];
  const entry = _sessionToolTracker.get(sessionId);
  if (!entry || Date.now() - entry.timestamp > TOOL_CACHE_TTL) return [];
  return entry.outcomes || [];
}

function clearTrackedTools(sessionId) {
  if (sessionId) _sessionToolTracker.delete(sessionId);
}

// ============================================================================
// Follow-up resolver: short prompts ("yes", "do it", "go ahead") are resolved
// using conversation history to determine the actual intent
// ============================================================================

// approvals-glitch: a short human yes ("do that") is read with the agent's last message (lib/quoxCli/directIntent.js confirmedAsk).
function directAskWithContext(message, orgId, userId, sessionId) {
  try {
    const { isAffirmation, confirmedAsk } = require('./lib/quoxCli/directIntent.js');
    if (!isAffirmation(message)) return message;
    const hist = require('./lib/chatSessionHistory.js').hydrateHistory({ orgId, userId, sessionId, clientHistory: [], includeActivity: false }).history || [];
    const last = [...hist].reverse().find((m) => m && m.role === 'assistant' && typeof m.content === 'string');
    return confirmedAsk(message, last ? last.content : '');
  } catch { return message; }
}

function resolveFollowUp(prompt, conversationHistory) {
  const trimmed = prompt.trim();

  // Only resolve short follow-ups (allow slightly longer compound phrases)
  if (trimmed.length > 60) return prompt;

  // Token-based follow-up detection: check if EVERY word is a known follow-up token
  // This handles compounds like "yes, do that", "ok go ahead", "try again", "another one"
  const followUpTokens = new Set(['yes','yeah','yep','yup','sure','ok','okay','please','go','ahead','do',
    'it','that','this','for','absolutely','affirmative','proceed','continue','carry','on','drill','down',
    'show','me','tell','more','details','detail','expand','elaborate','deeper','dig','in','sounds','good',
    'make','so','lets','let','100','right','away','now','definitely','perfect','great','fine',
    'try','again','retry','redo','another','one','different','version','same','repeat']);
  const words = trimmed.toLowerCase().replace(/[,.!?;:'"]/g, '').split(/\s+/).filter(Boolean);
  const isFollowUp = words.length > 0 && words.length <= 8 && words.every(w => followUpTokens.has(w));
  if (!isFollowUp) return prompt;

  // Look at the last assistant message for actionable context
  if (!Array.isArray(conversationHistory) || conversationHistory.length === 0) return prompt;

  const lastAssistant = [...conversationHistory].reverse().find(t => t.role === 'assistant');
  if (!lastAssistant?.content) return prompt;

  const assistantText = lastAssistant.content.toLowerCase();

  // Extract the intent from what the assistant offered to do
  // Order: specific domain patterns first, generic fallbacks last
  const offerPatterns = [
    { regex: /\b(docker|container)\b/i, resolved: 'docker status on all hosts' },
    { regex: /\b(proxmox|pve|vm|virtual machine)\b/i, resolved: 'proxmox cluster status' },
    { regex: /\b(security|audit|vulnerabilit)\b/i, resolved: 'security audit' },
    { regex: /\b(network|ping|connectivity|reachable)\b/i, resolved: 'network check all hosts' },
    { regex: /\b(cert|ssl|tls|expir)\b/i, resolved: 'ssl certificate check' },
    { regex: /\b(disk|storage|space)\b/i, resolved: 'disk usage check' },
    { regex: /\b(memory|ram|swap)\b/i, resolved: 'memory usage check' },
    { regex: /\b(log|journal|error)\b/i, resolved: 'system logs check' },
    { regex: /\b(metric|prometheus|alert)\b/i, resolved: 'metrics query' },
    { regex: /\b(generate|image|picture|photo|illustration|draw|paint|render|visuali[sz]e|nanobanana|nano banana)\b/i, resolved: null }, // handled by last-user-query replay below
    { regex: /\b(drill down|diagnostic|investigate|anomal|unhealthy|warning|critical)\b/i, resolved: 'fleet status detailed health check' },
    { regex: /\b(fleet|host|agent|status|online|offline|scan)\b/i, resolved: 'fleet status' },
  ];

  for (const { regex, resolved } of offerPatterns) {
    if (regex.test(assistantText)) {
      // For creative/generative patterns (images, etc.), replay the last user query
      // instead of a hardcoded string — preserves the original prompt, aspect_ratio, style, etc.
      if (resolved === null) {
        const lastUser = [...conversationHistory].reverse().find(t => t.role === 'user');
        if (lastUser?.content && lastUser.content.length > 5) {
          console.log(`[Tools] Follow-up resolved: "${trimmed}" → replaying last user query (creative context: "${assistantText.substring(0, 60)}...")`);
          return lastUser.content;
        }
      }
      console.log(`[Tools] Follow-up resolved: "${trimmed}" → "${resolved}" (from assistant context: "${assistantText.substring(0, 80)}...")`);
      return resolved;
    }
  }

  // Generic fallback: replay the last user message (works for any domain)
  const lastUser = [...conversationHistory].reverse().find(t => t.role === 'user');
  if (lastUser?.content && lastUser.content.length > 5) {
    console.log(`[Tools] Follow-up resolved: "${trimmed}" → re-using last user query for tool matching`);
    return lastUser.content;
  }

  return prompt;
}

// ============================================================================
// Tool pre-execution: detect which tools to run based on the query
// Used by the CLI path (OAuth) to execute tools before calling Claude
// ============================================================================
async function detectAndExecuteTools(prompt, agentId) {
  const results = [];
  const lower = prompt.toLowerCase();

  // Pattern → tool mapping with parameter extraction
  const patterns = [
    {
      test: () => /\b(docker|container)s?\b/i.test(lower) && /\b(status|list|show|running|ps|check)\b/i.test(lower),
      tool: 'docker_status',
      params: () => {
        const hostMatch = prompt.match(/(?:on|at|for|@)\s+(\w+\d+)/i);
        return { host: hostMatch?.[1] || 'docker01', all: /\ball\b/i.test(lower) };
      }
    },
    {
      test: () => /\b(docker)\b/i.test(lower) && /\b(logs?|stats?|inspect)\b/i.test(lower),
      tool: 'docker_extended',
      params: () => {
        const hostMatch = prompt.match(/(?:on|at|for|@)\s+(\w+\d+)/i);
        const containerMatch = prompt.match(/(?:logs?\s+(?:for|of|from)\s+)(\S+)/i) || prompt.match(/(?:container|service)\s+(\S+)/i);
        const op = /\blogs?\b/i.test(lower) ? 'logs' : /\bstats?\b/i.test(lower) ? 'stats' : 'inspect';
        return { host: hostMatch?.[1] || 'docker01', operation: op, container: containerMatch?.[1] };
      }
    },
    {
      test: () => /\b(fleet|agents?)\b/i.test(lower) && /\b(status|list|show|health|overview|check)\b/i.test(lower),
      tool: 'fleet_status',
      params: () => ({})
    },
    {
      // Broader host/infrastructure queries → also trigger fleet_status
      // Matches: "look at all hosts", "what's online/offline", "check which servers are up", etc.
      test: () => (
        (/\b(hosts?|servers?|machines?|infrastructure|infra)\b/i.test(lower) && /\b(status|online|offline|up|down|running|check|look|see|show|list|alive|reachable|available|overview)\b/i.test(lower)) ||
        (/\bwhat(?:'s|s| is| are)\b/i.test(lower) && /\b(online|offline|up|down|running|alive|reachable)\b/i.test(lower)) ||
        (/\bwhich\b/i.test(lower) && /\b(hosts?|servers?|machines?)\b/i.test(lower))
      ),
      tool: 'fleet_status',
      params: () => ({})
    },
    {
      test: () => /\bping\b/i.test(lower),
      tool: 'network_check',
      params: () => {
        const targetMatch = prompt.match(/ping\s+(\S+)/i);
        return { target: targetMatch?.[1] || 'localhost', type: 'ping', count: 4 };
      }
    },
    {
      test: () => /\btraceroute\b/i.test(lower),
      tool: 'network_check',
      params: () => {
        const targetMatch = prompt.match(/traceroute\s+(\S+)/i);
        return { target: targetMatch?.[1] || 'localhost', type: 'traceroute' };
      }
    },
    {
      test: () => /\b(dns\s+lookup|nslookup|resolve\s+\S+)\b/i.test(lower) || (/\bdig\b/i.test(lower) && /\b(record|domain|lookup|@)\b/i.test(lower)),
      tool: 'network_check',
      params: () => {
        const targetMatch = prompt.match(/(?:dns|dig|nslookup|resolve)\s+(\S+)/i);
        return { target: targetMatch?.[1] || 'quox.ai', type: 'dns' };
      }
    },
    {
      test: () => /\bport\s*scan\b/i.test(lower) || (/\bports?\b/i.test(lower) && /\b(check|scan|open)\b/i.test(lower)),
      tool: 'network_check',
      params: () => {
        const targetMatch = prompt.match(/(?:scan|check|on)\s+(\S+)/i);
        return { target: targetMatch?.[1] || 'localhost', type: 'ports', ports: [22, 80, 443, 8080, 9848] };
      }
    },
    {
      test: () => /\b(uptime|load)\b/i.test(lower) && !/\buptime.kuma\b/i.test(lower),
      tool: 'system_admin',
      params: () => {
        const hostMatch = prompt.match(/(?:on|at|for|@)\s+(\w+\d+)/i);
        return { host: hostMatch?.[1] || 'localhost', operation: 'uptime' };
      }
    },
    {
      test: () => /\b(service|systemctl|daemon)\b/i.test(lower),
      tool: 'system_admin',
      params: () => {
        const hostMatch = prompt.match(/(?:on|at|for|@)\s+(\w+\d+)/i);
        const filter = /\bfailed\b/i.test(lower) ? 'failed' : /\brunning\b/i.test(lower) ? 'running' : 'all';
        return { host: hostMatch?.[1] || 'localhost', operation: 'services', filter };
      }
    },
    {
      test: () => /\b(process|top|ps aux|cpu.hog|memory.hog)\b/i.test(lower),
      tool: 'system_admin',
      params: () => {
        const hostMatch = prompt.match(/(?:on|at|for|@)\s+(\w+\d+)/i);
        const sortBy = /\bmem/i.test(lower) ? 'memory' : 'cpu';
        return { host: hostMatch?.[1] || 'localhost', operation: 'processes', sort_by: sortBy, limit: 20 };
      }
    },
    {
      test: () => /\b(disk|df|storage|space)\b/i.test(lower) && !/\bproxmox\b/i.test(lower),
      tool: 'system_admin',
      params: () => {
        const hostMatch = prompt.match(/(?:on|at|for|@)\s+(\w+\d+)/i);
        return { host: hostMatch?.[1] || 'localhost', operation: 'disk' };
      }
    },
    {
      test: () => /\b(memory|ram|free|swap)\b/i.test(lower) && !/\bquox.?memory\b/i.test(lower),
      tool: 'system_admin',
      params: () => {
        const hostMatch = prompt.match(/(?:on|at|for|@)\s+(\w+\d+)/i);
        return { host: hostMatch?.[1] || 'localhost', operation: 'memory' };
      }
    },
    {
      test: () => /\b(logs?|journal|syslog)\b/i.test(lower) && /\b(show|check|view|tail|recent|last)\b/i.test(lower),
      tool: 'system_admin',
      params: () => {
        const hostMatch = prompt.match(/(?:on|at|for|@)\s+(\w+\d+)/i);
        const unitMatch = prompt.match(/(?:for|of|from)\s+(\w[\w.-]+)/i);
        return { host: hostMatch?.[1] || 'localhost', operation: 'logs', filter: unitMatch?.[1], since: '1h' };
      }
    },
    {
      test: () => /\b(vm|virtual.machine|qemu)\b/i.test(lower) && /\b(list|show|status|running)\b/i.test(lower),
      tool: 'proxmox_vms',
      params: () => {
        const nodeMatch = prompt.match(/(?:on|at)\s+(pve\d+)/i);
        return { node: nodeMatch?.[1] };
      }
    },
    {
      test: () => /\b(proxmox|pve)\b/i.test(lower) && /\b(cluster|status|health|overview)\b/i.test(lower),
      tool: 'proxmox_cluster_status',
      params: () => ({})
    },
    {
      test: () => /\b(proxmox|pve)\b/i.test(lower) && /\b(storage|disk|space)\b/i.test(lower),
      tool: 'proxmox_storage',
      params: () => {
        const nodeMatch = prompt.match(/(pve\d+)/i);
        return { node: nodeMatch?.[1] };
      }
    },
    {
      test: () => /\b(lxc|container)\b/i.test(lower) && /\b(proxmox|pve)\b/i.test(lower),
      tool: 'proxmox_containers',
      params: () => {
        const nodeMatch = prompt.match(/(pve\d+)/i);
        return { node: nodeMatch?.[1] };
      }
    },
    {
      test: () => /\b(audit|security.event|auth.log)\b/i.test(lower),
      tool: 'security_audit',
      params: () => ({
        hours: parseInt(prompt.match(/(\d+)\s*h/i)?.[1]) || 6,
        status: /\bfail/i.test(lower) ? 'failure' : 'all'
      })
    },
    {
      test: () => /\b(ssl|cert|certificate|tls)\b/i.test(lower) && /\b(check|expir|status|valid)\b/i.test(lower),
      tool: 'ssl_certificates',
      params: () => {
        const domainMatch = prompt.match(/(?:for|check|on)\s+(\S+\.\S+)/i);
        return { domain: domainMatch?.[1] };
      }
    },
    {
      test: () => /\b(prom|metric|promql)\b/i.test(lower) && /\b(query|check|show|get)\b/i.test(lower),
      tool: 'metrics_query',
      params: () => {
        const queryMatch = prompt.match(/query\s+['"]?([^'"]+)['"]?/i);
        return { query: queryMatch?.[1] || 'up' };
      }
    },
    {
      test: () => /\b(alert)s?\b/i.test(lower) && /\b(list|show|active|check|silence)\b/i.test(lower),
      tool: 'alerts_manage',
      params: () => ({ action: /\bsilence\b/i.test(lower) ? 'silence' : 'list' })
    },

    // Memory tools
    {
      test: () => /\b(remember|save|note|record|store)\b/i.test(lower) && /\b(that|this|fact|preference|decision)\b/i.test(lower),
      tool: 'memory_save',
      params: () => {
        const type = /\bprefer/i.test(lower) ? 'preference' : /\bdecisi/i.test(lower) ? 'decision' : /\bconstraint/i.test(lower) ? 'constraint' : 'fact';
        // Extract the content after "remember that" or "note that"
        const contentMatch = prompt.match(/(?:remember|note|record|save)\s+(?:that\s+)?(.+)/i);
        return { type, content: contentMatch?.[1] || prompt };
      }
    },
    {
      test: () => /\b(recall|what do you (?:know|remember)|search.*memor|do you remember)\b/i.test(lower),
      tool: 'memory_search',
      params: () => {
        const queryMatch = prompt.match(/(?:about|regarding|for)\s+(.+)/i);
        return { query: queryMatch?.[1] || prompt, limit: 5 };
      }
    },

    // QSKL-CHAT-BRIDGE.2: single skill view by name
    // NOTE: skill_manage (create) is intentionally NOT added here — write-side stays opt-in via tool_use API-key path only.
    {
      test: () => /\b(?:show|view|describe|explain|read)\s+(?:me\s+)?(?:the\s+)?([a-z][a-z0-9-]+)\s+skill\b/i.test(lower),
      tool: 'skill_view',
      params: () => {
        const viewMatch = prompt.match(/\b(?:show|view|describe|explain|read)\s+(?:me\s+)?(?:the\s+)?([a-z][a-z0-9-]+)\s+skill\b/i);
        return { name: viewMatch?.[1] };
      }
    },

    // QSKL-CHAT-BRIDGE.1: skills catalog discovery
    {
      test: () => /\b(?:list|show|what(?:'s| are| can)?|which)\s+(?:are\s+)?(?:my\s+|the\s+|all\s+|available\s+)?skills?\b/i.test(lower),
      tool: 'skills_list',
      params: () => {
        const catMatch = prompt.match(/\b(security|compliance|infra(?:structure)?|data|github|workflow|communication|ops[\-\s\/]?health)\b/i);
        const agentMatch = prompt.match(/\b(?:for|tagged(?:\s+for)?|used\s+by|assigned\s+to)\s+([a-z][a-z0-9-]*)\b/i);
        const category = catMatch ? catMatch[1].toLowerCase().replace(/[\-\s]+/, '/') : undefined;
        const agentId = agentMatch ? agentMatch[1].toLowerCase() : undefined;
        return { ...(category ? { category } : {}), ...(agentId ? { agentId } : {}) };
      }
    }
  ];

  // Check each pattern and execute matching tools (max 3 per query)
  const agentToolNames = new Set((require('./lib/agentTools.js').AGENT_TOOLS[agentId.toLowerCase()] || []));
  let executed = 0;

  for (const pattern of patterns) {
    if (executed >= 3) break;
    if (pattern.test() && agentToolNames.has(pattern.tool)) {
      try {
        const params = pattern.params();
        console.log(`[Tools] Pre-executing ${pattern.tool}:`, JSON.stringify(params).substring(0, 100));
        const result = await executeTool(pattern.tool, params, { agentId: agentId });
        if (result.success === false) {
          console.warn(`[Tools] Pre-execution failed for ${pattern.tool}: ${result.error}`);
          results.push({ tool: pattern.tool, result, error: true });
        } else {
          results.push({ tool: pattern.tool, result });
        }
        executed++;
      } catch (err) {
        console.error(`[Tools] Pre-execution error for ${pattern.tool}:`, err.message);
        results.push({ tool: pattern.tool, result: { success: false, error: err.message }, error: true });
        executed++;
      }
    }
  }

  // Also check for direct SSH commands: "run X on host" / "ssh host X"
  if (executed === 0 && agentToolNames.has('ssh_exec')) {
    const sshPatterns = [
      /(?:run|execute|exec)\s+[`"']?(.+?)[`"']?\s+on\s+(\w+\d+)/i,
      /(?:ssh|connect)\s+(\w+\d+)\s+(?:and\s+)?(?:run\s+)?[`"']?(.+?)[`"']?$/i,
      /on\s+(\w+\d+)\s+(?:run|execute)\s+[`"']?(.+?)[`"']?$/i
    ];
    for (const re of sshPatterns) {
      const match = prompt.match(re);
      if (match) {
        const [, cmdOrHost, hostOrCmd] = match;
        // Determine which capture is host and which is command
        const isFirstHost = /^\w+\d+$/.test(cmdOrHost) && cmdOrHost.length < 20;
        const host = isFirstHost ? cmdOrHost : hostOrCmd;
        const command = isFirstHost ? hostOrCmd : cmdOrHost;
        try {
          console.log(`[Tools] Pre-executing ssh_exec on ${host}: ${command.substring(0, 60)}`);
          const result = await executeTool('ssh_exec', { host, command });
          results.push({ tool: 'ssh_exec', result });
        } catch (err) {
          console.error(`[Tools] SSH pre-execution error:`, err.message);
        }
        break;
      }
    }
  }

  // Infrastructure fallback: if NO tools matched and query seems infra-related, run fleet_status
  // This prevents Claude from saying "I can't see your hosts" when patterns miss a phrasing
  if (results.length === 0 && agentToolNames.has('fleet_status')) {
    const infraSignals = /\b(hosts?|servers?|machines?|nodes?|vms?|clusters?|infra|online|offline|up|down|running|status|health|check|look|scan|sweep)\b/i;
    const matchCount = (lower.match(infraSignals) || []).length;
    if (matchCount >= 2) {
      try {
        console.log(`[Tools] Infrastructure fallback — running fleet_status (${matchCount} infra signals detected)`);
        const result = await executeTool('fleet_status', {}, { agentId: agentId });
        if (result.success !== false) {
          results.push({ tool: 'fleet_status', result });
        }
      } catch (err) {
        console.error(`[Tools] Fleet status fallback error:`, err.message);
      }
    }
  }

  return results;
}

/**
 * Extract a voice-friendly summary from response content
 */
function extractVoiceSummary(content) {
  if (!content) return '';

  // Try to parse JSON format (legacy)
  try {
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      if (parsed.voice) return parsed.voice;
    }
  } catch (_) {}

  // Extract first meaningful line
  const lines = content.split('\n').filter(l => l.trim() && !l.startsWith('#') && !l.startsWith('|') && !l.startsWith('```'));
  const firstLine = (lines[0] || '').replace(/[*#|`\[\]]/g, '').replace(/\n/g, ' ').trim();
  return firstLine.length > 150 ? firstLine.substring(0, 147) + '...' : firstLine;
}

/**
 * /chat/complete — Non-streaming completion endpoint (Stream UX-6)
 *
 * Lightweight JSON-in/JSON-out completion for UI-assist features (e.g. AI-powered form filling).
 * Uses Anthropic Messages API directly. No tools, no MCP, no streaming.
 * Requires auth: OAuth cookie/JWT (UI path) OR service key (QuoxDream P3
 * WP3 — server-side workers call this with X-Service-Key, no req.user).
 */
app.post('/chat/complete', chatLimiter, requireServiceOrUserAuth(), async (req, res) => {
  const { prompt, system_prompt, max_tokens = 500 } = req.body;
  if (!prompt || typeof prompt !== 'string') {
    return res.status(400).json({ error: 'prompt is required' });
  }

  // LLM-CHOICE Phase 2.2: resolve org-scoped credentials + the collector
  // policy plan instead of reading process.env.ANTHROPIC_API_KEY directly —
  // mirrors the agents/invoke fast path (server.js ~4875), reusing its
  // attemptAnthropicApiInvoke / attemptAnthropicCliInvoke / attemptOpenAiInvoke
  // helpers rather than a third reimplementation of single-shot dispatch.
  // BRAIN2-W11: a trusted service-key caller (Dream, rerank) names its org via X-Org-Id.
  const orgId = req.user?.org_id || req.user?.orgId || (req.service && req.headers['x-org-id']) || undefined;
  const cookies = parseCookieHeader(req.headers.cookie);
  const authHeader = req.headers.authorization;
  const userAccessToken = (authHeader && authHeader.startsWith('Bearer ') ? authHeader.slice(7) : '') || cookies.access_token || '';

  const claudeKeys = await getClaudeKeys(orgId);
  const providerKeys = await getProviderKeys(orgId);
  const anthropicApiKey = claudeKeys.anthropic_api_key || process.env.ANTHROPIC_API_KEY || '';
  let cliOAuthToken = resolveCliOAuthToken(claudeKeys);

  const requestedProviderRaw = typeof req.body.provider === 'string' && req.body.provider.trim() ? req.body.provider.trim() : null;
  const requestedModelRaw = typeof req.body.model === 'string' && req.body.model.trim() ? req.body.model.trim() : null;

  let candidates;
  let failoverPlan = null;
  try {
    const resolved = await resolveCollectorPolicyPlan({
      orgId,
      userAccessToken,
      requestedProvider: requestedProviderRaw,
      requestedModel: requestedModelRaw,
      anthropicApiKey,
      cliOAuthToken,
      providerKeys,
    });
    failoverPlan = resolved.plan;
    candidates = buildCandidateChain({ plan: resolved.plan, policyContext: resolved.policyContext });
  } catch (planErr) {
    console.warn(`[chat/complete] Policy resolution failed, defaulting to anthropic: ${planErr.message}`);
    // BRAIN2 P4a: claude-sonnet-4-20250514 is retired (CLI 404s on it, proven
    // live 2026-08-25); fall back to the current Sonnet alias instead.
    // VAULT-INTEG P17: was a bare process.env read — now resolved via
    // configResolver.getSetting(orgId, ...) (platformCapabilities.js
    // ANTHROPIC_MODEL), called fresh on every request that falls into this
    // catch branch.
    const anthropicModelDefault = configResolver.getSetting(orgId || null, 'ANTHROPIC_MODEL').value || 'claude-sonnet-5';
    candidates = [{ provider: 'anthropic', model: requestedModelRaw || anthropicModelDefault, source: 'default' }];
  }

  // LLM-CHOICE Phase 1 parity: a lane with allow_oauth=false must never fall
  // back to the CLI/OAuth path even when a token is present.
  const allowOAuth = failoverPlan?.credentialConstraints?.allowOAuth !== false;
  if (!allowOAuth) {
    cliOAuthToken = '';
  }

  // This endpoint only knows how to speak anthropic/openai directly (same
  // constraint as the fast path); other resolved providers are dropped from
  // the chain rather than faked.
  const supportedCandidates = candidates.filter((c) => c.provider === 'anthropic' || c.provider === 'openai');

  if (supportedCandidates.length === 0) {
    return res.status(503).json({ error: 'No AI provider configured for completions' });
  }

  const maxTokensClamped = Math.min(Number(max_tokens) || 500, 2000);

  const attemptCandidate = async (candidate) => {
    if (candidate.provider === 'anthropic') {
      if (anthropicApiKey) {
        return await attemptAnthropicApiInvoke({ candidate, agentId: 'chat-complete', context: system_prompt, task: prompt, apiKey: anthropicApiKey, maxTokens: maxTokensClamped });
      }
      if (allowOAuth && cliOAuthToken) {
        return await attemptAnthropicCliInvoke({ candidate, agentId: 'chat-complete', context: system_prompt, task: prompt, cliOAuthToken });
      }
      const authErr = new Error('anthropic_auth_unavailable');
      authErr.status = 401;
      throw authErr;
    }

    // openai
    const openaiKey = providerKeys?.openai_api_key || process.env.OPENAI_API_KEY;
    if (!openaiKey) {
      const authErr = new Error('openai_auth_unavailable');
      authErr.status = 401;
      throw authErr;
    }
    return await attemptOpenAiInvoke({ candidate, agentId: 'chat-complete', context: system_prompt, task: prompt, apiKey: openaiKey, req });
  };

  const completeCorrId = `COMPLETE_${Date.now()}`;
  const onFailoverHop = (hop, next) => {
    try {
      storeAuditEnvelope({
        type: 'event',
        from: 'system.llm-router',
        to: 'audit.system',
        intent: 'quox.llm.failover',
        corr: completeCorrId,
        payload: {
          path: 'complete',
          from_provider: hop.provider,
          from_model: hop.model,
          to_provider: next?.provider || null,
          to_model: next?.model || null,
          error: hop.error,
          status: hop.status,
        },
      });
    } catch { /* audit must never break failover */ }
  };

  try {
    const { result, candidate, hops } = await executeWithFailover({
      candidates: supportedCandidates,
      attempt: attemptCandidate,
      onHop: onFailoverHop,
    });

    // CRP-AU-5: Add audit envelope for /chat/complete (was zero evidence)
    storeAuditEnvelope({
      type: 'event',
      from: 'system.collector',
      to: 'audit.system',
      intent: 'quox.chat.complete',
      corr: completeCorrId,
      payload: { path: 'complete', provider: candidate.provider, model: result.usage?.model || candidate.model, input_tokens: result.usage?.input_tokens, output_tokens: result.usage?.output_tokens, response_length: result.result.length, hops: hops.length }
    });

    res.json({ success: true, text: result.result, usage: result.usage, provider: candidate.provider });
  } catch (err) {
    console.error(`[chat/complete] Error: ${err.message}`);
    const hopCount = Array.isArray(err.hops) ? err.hops.length : 0;
    console.warn(`[chat/complete] All providers failed (${hopCount} hops): ${err.message}`);
    res.status(502).json({ error: 'Completion request failed' });
  }
});

