const { handleTelegramWebhook, getWebhookConfig, clearConfigCache } = require('./lib/telegramWebhook');
const { registerWebhook: registerTelegramWebhook, setCommands: setTelegramCommands, getWebhookInfo: getTelegramWebhookInfo, getBotInfo: getTelegramBotInfo } = require('./utils/telegramSetup');

