/**
 * GET /api/v1/actions
 * Proxy to auth service for scoped action items
 */
app.get('/api/v1/actions', requireAuth(), async (req, res) => {
  // AEE-ORG-1 (tenant isolation): req.auth is NEVER assigned in this codebase,
  // so the old `req.auth?.orgId` read fell straight through to the client-supplied
  // x-org-id header — a JWT user could proxy to another org by setting it. Lock
  // to the verified JWT org; the header is honored only for trusted service callers.
  const orgId = req.user?.org_id || (req.service ? req.headers['x-org-id'] : null);
  if (!orgId) return res.json({ success: true, items: [], pagination: { total: 0 } });

  try {
    const token = req.headers.authorization?.split(' ')[1] || '';
    const queryStr = new URLSearchParams(req.query).toString();
    const authRes = await fetch(
      `${AUTH_SERVICE_URL}/api/orgs/${orgId}/actions${queryStr ? '?' + queryStr : ''}`,
      { headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' } }
    );
    const data = await authRes.json();
    res.status(authRes.status).json(data);
  } catch (err) {
    console.error('[Actions] Failed to get actions:', err);
    res.status(500).json({ success: false, error: err.message });
  }
});

