// ============================================================================
// CODEBASE MIRROR API
// ============================================================================

const { scanProject, generateSummary, generateMultiSummary } = require('./lib/codebaseScanner');
const { initCodebaseDb, storeScan, storeChanges, getLatestScan, listProjects, queryElements, getPreviousScan, getChanges } = require('./lib/codebaseStore');
const { diffScans } = require('./lib/codebaseDiff');

// Initialize codebase DB lazily on first use
let codebaseDbReady = false;
function ensureCodebaseDb() {
  if (!codebaseDbReady) {
    initCodebaseDb();
    codebaseDbReady = true;
  }
}

/**
 * POST /api/v1/codebase/scan
 * Trigger a codebase scan for a project path.
 * Body: { path: string, projectName?: string, orgId?: string }
 */
app.post('/api/v1/codebase/scan', scanLimiter, requireServiceOrUserAuth(), async (req, res) => {
  const { path: rawPath, projectName, orgId = 'default' } = req.body;
  if (!rawPath) {
    return res.status(400).json({ success: false, error: 'path is required' });
  }
  // #1021: the dashboard sends '~/<repo>' (it cannot know the host's home); expand it here.
  const projectPath = /^~(\/|$)/.test(String(rawPath)) ? hostPath(String(rawPath).replace(/^~\/?/, '')) : rawPath;

  try {
    ensureCodebaseDb();
    const scanResult = await scanProject(projectPath, { projectName });
    const scanId = storeScan(scanResult, orgId);

    // Run diff against previous scan
    const prevScan = getPreviousScan(scanId);
    let changes = [];
    if (prevScan) {
      changes = diffScans(prevScan.scan_data, scanResult);
      if (changes.length > 0) {
        storeChanges(scanId, changes);
      }
    }

    res.json({
      success: true,
      scanId,
      project: {
        id: scanResult.projectId,
        name: scanResult.projectName,
        type: scanResult.projectType,
      },
      metrics: scanResult.metrics,
      invariantChecks: scanResult.invariantChecks,
      changeCount: changes.length,
    });
  } catch (err) {
    console.error('[Codebase] Scan failed:', err);
    res.status(500).json({ success: false, error: err.message });
  }
});

/**
 * GET /api/v1/codebase/projects
 * List all scanned projects.
 */
app.get('/api/v1/codebase/projects', requireServiceOrUserAuth(), (req, res) => {
  try {
    ensureCodebaseDb();
    const orgId = req.user?.org_id || (req.service ? (req.query.orgId || 'default') : null) || null;
    const projects = listProjects(orgId);
    res.json({ success: true, projects });
  } catch (err) {
    console.error('[Codebase] List failed:', err);
    res.status(500).json({ success: false, error: err.message });
  }
});

/**
 * GET /api/v1/codebase/:projectId
 * Get latest scan for a project (by path or name).
 */
app.get('/api/v1/codebase/:projectId', requireServiceOrUserAuth(), (req, res) => {
  try {
    ensureCodebaseDb();
    const orgId = req.user?.org_id || (req.service ? (req.query.orgId || 'default') : null) || null;
    const scan = getLatestScan(decodeURIComponent(req.params.projectId), orgId);
    if (!scan) {
      return res.status(404).json({ success: false, error: 'Project not found' });
    }
    res.json({ success: true, scan: scan.scan_data, metrics: scan.metrics, invariantStatus: scan.invariant_status });
  } catch (err) {
    console.error('[Codebase] Get failed:', err);
    res.status(500).json({ success: false, error: err.message });
  }
});

/**
 * GET /api/v1/codebase/:projectId/query
 * Query elements within a project scan.
 * Query params: type (route|plugin|service|agent|schema|registry), filter JSON
 */
app.get('/api/v1/codebase/:projectId/query', requireServiceOrUserAuth(), (req, res) => {
  try {
    ensureCodebaseDb();
    const orgId = req.user?.org_id || (req.service ? (req.query.orgId || 'default') : null) || null;
    const elementType = req.query.type;
    if (!elementType) {
      return res.status(400).json({ success: false, error: 'type query param is required' });
    }
    let filter = {};
    if (req.query.filter) {
      try { filter = JSON.parse(req.query.filter); } catch { /* ignore */ }
    }
    if (req.query.name) filter.name = req.query.name;
    if (req.query.protected !== undefined) filter.protected = req.query.protected === 'true';
    if (req.query.minRole) filter.minRole = req.query.minRole;

    const elements = queryElements(decodeURIComponent(req.params.projectId), elementType, filter, orgId);
    res.json({ success: true, type: elementType, count: elements.length, elements });
  } catch (err) {
    console.error('[Codebase] Query failed:', err);
    res.status(500).json({ success: false, error: err.message });
  }
});

