function generateMarkdown(scan) {
  const lines = [];
  lines.push(`<!-- Last verified: ${new Date().toISOString().split('T')[0]} by Codebase Mirror API -->`);
  lines.push('');
  lines.push(`# ${scan.projectName} — Codebase Map`);
  lines.push('');

  // Metrics
  lines.push('## Metrics');
  lines.push('| Metric | Count |');
  lines.push('|--------|-------|');
  for (const [key, val] of Object.entries(scan.metrics)) {
    if (val > 0) lines.push(`| ${key} | ${val} |`);
  }
  lines.push('');

  // Registries
  if (scan.registries.length > 0) {
    lines.push('## Registries');
    for (const reg of scan.registries) {
      lines.push(`### ${reg.name} (${reg.entryCount} entries)`);
      lines.push(`Source: \`${reg.file}\``);
      lines.push('');
      if (reg.entries.length <= 30) {
        lines.push('| ID | Name |');
        lines.push('|----|------|');
        for (const entry of reg.entries) {
          lines.push(`| ${entry.id} | ${entry.name} |`);
        }
      } else {
        lines.push(`*${reg.entries.length} entries — too many to list*`);
      }
      lines.push('');
    }
  }

  // Routes
  if (scan.routes.length > 0) {
    lines.push('## Routes');
    lines.push('| Path | Protected | Min Role |');
    lines.push('|------|-----------|----------|');
    for (const route of scan.routes) {
      lines.push(`| \`${route.path}\` | ${route.protected ? 'Yes' : 'No'} | ${route.minRole || '—'} |`);
    }
    lines.push('');
  }

  // Services
  if (scan.services.length > 0) {
    lines.push('## Services');
    lines.push('| Name | Port |');
    lines.push('|------|------|');
    for (const svc of scan.services) {
      lines.push(`| ${svc.name} | ${svc.port || '—'} |`);
    }
    lines.push('');
  }

  // Invariants
  if (scan.invariantChecks.length > 0) {
    lines.push('## Invariant Checks');
    lines.push('| Check | Status | Details |');
    lines.push('|-------|--------|---------|');
    for (const check of scan.invariantChecks) {
      const icon = check.status === 'pass' ? '✓' : check.status === 'warn' ? '⚠' : '✗';
      lines.push(`| ${check.name} | ${icon} ${check.status} | ${check.message} |`);
    }
    lines.push('');
  }

  return lines.join('\n');
}

