function generateId() {
  return `${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 10)}`;
}

// Submit feedback (public, rate limited)
app.post('/feedback', feedbackLimiter, (req, res) => {
  if (!feedbackDb || !fbStatements) {
    return res.status(503).json({ error: 'Feedback storage not available' });
  }

  const { type, message, name, email, website } = req.body;

  // Honeypot — silently accept but discard
  if (website) {
    return res.json({ success: true, id: 'ok' });
  }

  if (!message || message.trim().length < 5 || message.length > 5000) {
    return res.status(400).json({ error: 'Message must be 5-5000 characters' });
  }

  const validTypes = ['feedback', 'bug', 'feature', 'integration_request'];
  const feedbackType = validTypes.includes(type) ? type : 'feedback';

  // Basic email validation if provided
  if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    return res.status(400).json({ error: 'Invalid email format' });
  }

  try {
    const id = generateId();
    const ip = req.ip || req.connection?.remoteAddress || '';
    const ua = (req.headers['user-agent'] || '').substring(0, 500);

    fbStatements.insertFeedback.run(
      id,
      feedbackType,
      name ? String(name).trim().substring(0, 255) : null,
      email ? String(email).trim().substring(0, 255) : null,
      String(message).trim().substring(0, 5000),
      ip,
      ua
    );

    console.log(`[Feedback] New ${feedbackType} submitted (${id})`);

    // Forward to quox.ai website API so it appears in /admin/feedback
    try {
      const websiteApiUrl = process.env.WEBSITE_API_URL || 'https://api.quox.ai';
      fetch(`${websiteApiUrl}/api/feedback`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type: feedbackType, message: String(message).trim().substring(0, 5000), name: name ? String(name).trim().substring(0, 255) : undefined, email: email ? String(email).trim().substring(0, 255) : undefined }),
      }).then(r => {
        if (!r.ok) console.warn(`[Feedback] Website forward failed: ${r.status}`);
        else console.log(`[Feedback] Forwarded to website API`);
      }).catch(e => console.warn(`[Feedback] Website forward error: ${e.message}`));
    } catch (fwdErr) {
      console.warn(`[Feedback] Forward setup error: ${fwdErr.message}`);
    }

    res.json({ success: true, id });
  } catch (err) {
    console.error('[Feedback] Store error:', err);
    res.status(500).json({ error: 'Failed to store feedback' });
  }
});

