// List feedback (admin)
app.get('/feedback', requireAuth(), (req, res) => {
  if (!feedbackDb || !fbStatements) {
    return res.json({ items: [], total: 0, page: 1, pages: 1 });
  }

  const page = Math.max(1, parseInt(req.query.page, 10) || 1);
  const limit = Math.min(100, Math.max(1, parseInt(req.query.limit, 10) || 50));
  const offset = (page - 1) * limit;
  const { status, type } = req.query;

  try {
    let where = [];
    let params = [];

    if (status && status !== 'all') {
      where.push('status = ?');
      params.push(status);
    }
    if (type && type !== 'all') {
      where.push('type = ?');
      params.push(type);
    }

    const whereClause = where.length > 0 ? `WHERE ${where.join(' AND ')}` : '';

    const countRow = feedbackDb.prepare(`SELECT COUNT(*) as total FROM feedback ${whereClause}`).get(...params);
    const total = countRow?.total || 0;
    const pages = Math.max(1, Math.ceil(total / limit));

    const items = feedbackDb.prepare(
      `SELECT id, type, name, email, message, status, created_at, read_at FROM feedback ${whereClause} ORDER BY created_at DESC LIMIT ? OFFSET ?`
    ).all(...params, limit, offset);

    res.json({ items, total, page, pages });
  } catch (err) {
    console.error('[Feedback] List error:', err);
    res.status(500).json({ error: 'Failed to fetch feedback' });
  }
});

