// ============================================================================
// Grafana Proxy API — Eliminates CORS, keeps API key server-side
// ============================================================================

const { grafanaFetch: _grafanaFetch, grafanaPost: _grafanaPost, getGrafanaUrl, setGrafanaUrl } = require('./lib/toolExecutors/grafana');

/**
 * GET /api/v1/grafana/config
 * Returns the Grafana base URL for iframe embedding (no API key exposed).
 */
// FND_...TX95 (WORKER2 2026-10-19): the monitoring/grafana config WRITE routes persist an INSTANCE-GLOBAL file, so a
// single tenant could repoint Prometheus/Grafana for every org (proven: a second-org non-admin PUT wrote it). Writes
// are INSTANCE-ADMIN only. requireAuth({required:true}) first (401 if unauthenticated), then this (403 if not instance admin).
async function requireInstanceAdminMw(req, res, next) {
  try {
    const verdict = await require('./lib/pluginBackendAdmin.js').checkInstanceAdmin(req, { isHumanAdmin });
    if (verdict === 'yes') return next();
    if (verdict === 'unavailable') return res.status(503).json({ success: false, error: 'instance-admin check unavailable' });
    return res.status(403).json({ success: false, error: 'instance admin required' });
  } catch { return res.status(403).json({ success: false, error: 'instance admin required' }); }
}
app.get('/api/v1/grafana/config', requireServiceOrUserAuth(), (req, res) => {
  res.json({ success: true, url: getGrafanaUrl() });
});

/**
 * PUT /api/v1/grafana/config
 * Save a new Grafana URL. Persisted to disk so it survives container restarts.
 */
app.put('/api/v1/grafana/config', requireAuth({ required: true }), requireInstanceAdminMw, (req, res) => {
  const { url } = req.body;
  if (!url || typeof url !== 'string') return res.status(400).json({ success: false, error: 'url is required' });
  // Basic URL validation
  try { new URL(url) } catch { return res.status(400).json({ success: false, error: 'Invalid URL format' }) }
  setGrafanaUrl(url);
  auditOp('ops.grafana.config.updated', { url: req.body.url });
  res.json({ success: true, url: getGrafanaUrl() });
});

/**
 * POST /api/v1/grafana/test
 * Test connectivity to an arbitrary Grafana URL without saving it.
 */
app.post('/api/v1/grafana/test', requireServiceOrUserAuth(), async (req, res) => {
  const { url } = req.body;
  if (!url || typeof url !== 'string') return res.status(400).json({ success: false, error: 'url is required' });
  try {
    new URL(url);
    const resp = await fetch(`${url.replace(/\/+$/, '')}/api/health`, {
      headers: { 'Accept': 'application/json' },
      signal: AbortSignal.timeout(8000),
    });
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const health = await resp.json();
    res.json({ success: true, ...health, url });
  } catch (err) {
    res.json({ success: false, error: err.message, url });
  }
});

/**
 * GET /api/v1/bastion/config
 * SECURITY FIX C3: this used to return the raw BASTION_API_TOKEN to the
 * browser, giving every authenticated frontend session a fleet-admin
 * bastion credential. The token now never leaves the server — the
 * frontend must call bastion through the proxy below, which injects the
 * token server-side and authorizes by dashboard role.
 */
// LL-7 D3: bastion-fleet entitlement gate — this route and the proxy below
// were auth+role only, so any authenticated org reached the bastion data
// plane while the client page gate looked authoritative. Same middleware
// contract as the lens/discord-pro/github mounts (402 LICENSE_REQUIRED,
// pure INTERNAL_SERVICE_KEY calls bypass, fail closed).
app.get('/api/v1/bastion/config', requireServiceOrUserAuth(), requireFleetAllowance('bastion-fleet'), (req, res) => {
  const configured = !!process.env.BASTION_API_TOKEN;
  if (!configured) {
    return res.json({ success: false, error: 'BASTION_API_TOKEN not configured on server' });
  }
  res.json({ success: true, proxied: true, baseUrl: '/collector/api/v1/bastion/proxy' });
});

// ============================================================================
// SECURITY FIX C3 — Bastion proxy
// The browser must never hold BASTION_API_TOKEN. All fleet-admin bastion
// calls go through this collector-side proxy: it injects the token
// server-side and authorizes the call by the caller's dashboard role.
// ============================================================================

/**
 * Map a dashboard role to the bastion scopes it is authorized for.
 *   admin/owner            -> read, exec, keys, admin (everything)
 *   operator                -> read, exec
 *   member/viewer/unknown   -> read only
 * `req.service` (INTERNAL_SERVICE_KEY) callers are treated as admin, matching
 * the existing isAdminCaller()/requireWebhookAdmin() convention elsewhere in
 * this file (internal callers are inside the trust boundary already).
 */
function bastionScopesForRole(role) {
  if (role === 'admin' || role === 'owner') return new Set(['read', 'exec', 'keys', 'admin']);
  if (role === 'operator') return new Set(['read', 'exec']);
  return new Set(['read']);
}

/**
 * Determine the bastion scope required for a given method + subpath.
 * Any write route not explicitly enumerated defaults to 'admin' (default-deny).
 *
 * NOTE (GAP-2): POST /tools/run is a single generic endpoint whose actual
 * privilege depends on the `tool_id` in the request body — see
 * bastionToolScope() below, which the proxy handler consults instead of the
 * flat 'exec' this function would otherwise return for /tools/run.
 */
function bastionScopeForRequest(method, subpath) {
  const m = (method || '').toUpperCase();
  if (m === 'GET' || m === 'HEAD') return 'read';
  if (m === 'POST' && (subpath === '/exec' || subpath === '/exec/stream' || subpath === '/tools/run')) return 'exec';
  if ((m === 'POST' || m === 'DELETE') && subpath.startsWith('/keys')) return 'keys';
  if (m === 'POST' && subpath === '/sudo/setup') return 'admin';
  if ((m === 'POST' || m === 'PUT' || m === 'DELETE') && subpath.startsWith('/hosts')) return 'admin';
  if (m === 'POST' && subpath === '/registry/import') return 'admin';
  // Anything else that isn't a plain read (e.g. POST /groups) — default-deny.
  return 'admin';
}

/**
 * GAP-2 (CRITICAL) — collector-side per-tool scope enforcement for
 * POST /tools/run.
 *
 * The collector proxies every bastion call with the single `*`
 * BASTION_API_TOKEN, so the bastion's own per-tool scope check cannot by
 * itself restrict what a given dashboard USER is allowed to trigger through
 * it — from the bastion's perspective every proxied call looks like the
 * same fleet-admin credential. bastionScopeForRequest() maps POST
 * /tools/run to a flat 'exec' scope, but /tools/run's body (`tool_id`) can
 * invoke tools that are far more privileged than plain exec — e.g.
 * sudo-setup (grants passwordless sudo) or ssh-key-deploy (installs SSH
 * keys). The collector MUST look inside the body and require the tool's
 * real scope before forwarding.
 *
 * Keep this map in sync with the bastion-side tool→scope map (see
 * internal/tools/builtins/*.go in QuoxBastion — sudo_setup.go,
 * ssh_key_deploy.go, install_*.go, cert_check.go, health_check.go,
 * motd_set.go for the current tool_id constants).
 */
function bastionToolScope(toolId) {
  const id = String(toolId || '');
  if (id === 'sudo-setup') return 'admin';
  if (id === 'ssh-key-deploy') return 'keys';
  if (id.startsWith('install-')) return 'exec';
  if (id === 'cert-check' || id === 'health-check') return 'read';
  if (id === 'motd-set') return 'exec';
  // Unknown/unrecognized tool_id — fail-safe to the most restrictive scope
  // rather than defaulting to 'exec'.
  return 'admin';
}

const BASTION_PROXY_PREFIX = '/api/v1/bastion/proxy';

// LL-7 D3: entitlement-gated (see /api/v1/bastion/config note above).
app.all(`${BASTION_PROXY_PREFIX}/*`, requireServiceOrUserAuth(), requireFleetAllowance('bastion-fleet'), async (req, res) => {
  const bastionUrl = process.env.BASTION_URL;
  const bastionToken = process.env.BASTION_API_TOKEN;
  if (!bastionUrl || !bastionToken) {
    return res.status(503).json({ error: 'Bastion is not configured on this installation.' });
  }

  // req.path is the full matched path (not route-relative) — strip the proxy
  // prefix to get the bastion subpath. Query string is taken from
  // originalUrl since req.path never includes it.
  const subpath = req.path.slice(BASTION_PROXY_PREFIX.length) || '/';
  const qIdx = req.originalUrl.indexOf('?');
  const rawQuery = qIdx === -1 ? '' : req.originalUrl.slice(qIdx);

  if (subpath.includes('..') || !/^\/[a-zA-Z0-9_\-/]*$/.test(subpath)) {
    return res.status(400).json({ error: 'invalid bastion proxy subpath' });
  }

  let requiredScope = bastionScopeForRequest(req.method, subpath);
  // GAP-2: /tools/run's real privilege depends on which tool is being
  // invoked, not just the route — enforce the tool's actual scope.
  if (req.method === 'POST' && subpath === '/tools/run') {
    requiredScope = bastionToolScope(req.body?.tool_id);
  }
  const role = req.service ? 'admin' : (req.user?.dashboardRole || null);
  const allowedScopes = bastionScopesForRole(role);
  if (!allowedScopes.has(requiredScope)) {
    return res.status(403).json({ error: `insufficient role for bastion ${requiredScope}` });
  }

  const targetUrl = `${bastionUrl.replace(/\/+$/, '')}/api/v1${subpath}${rawQuery}`;
  const actor = req.user?.email || req.user?.id || req.serviceAgent || 'service';
  const isGetLike = req.method === 'GET' || req.method === 'HEAD';
  const isStream = subpath === '/exec/stream';

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 60_000);

  try {
    const fetchOpts = {
      method: req.method,
      headers: {
        'Authorization': `Bearer ${bastionToken}`,
        'X-Actor': String(actor),
        'Content-Type': 'application/json',
      },
      signal: controller.signal,
    };
    if (!isGetLike) {
      fetchOpts.body = JSON.stringify(req.body || {});
    }

    const bastionRes = await fetch(targetUrl, fetchOpts);
    clearTimeout(timeout);

    if (isStream && bastionRes.body) {
      // SSE: pipe the bastion stream straight through to the client.
      res.status(bastionRes.status);
      res.setHeader('Content-Type', bastionRes.headers.get('content-type') || 'text/event-stream');
      const { Readable } = require('stream');
      Readable.fromWeb(bastionRes.body).pipe(res);
      return;
    }

    const contentType = bastionRes.headers.get('content-type') || '';
    if (contentType.includes('application/json')) {
      const data = await bastionRes.json().catch(() => null);
      return res.status(bastionRes.status).json(data ?? {});
    }
    const text = await bastionRes.text();
    res.status(bastionRes.status).send(text);
  } catch (err) {
    clearTimeout(timeout);
    if (err.name === 'AbortError') {
      return res.status(504).json({ error: 'bastion request timed out' });
    }
    console.error('[BastionProxy] forward error:', err.message);
    if (!res.headersSent) {
      res.status(502).json({ error: 'bastion_unreachable', detail: err.message });
    }
  }
});

// ============================================================
// Unified Monitoring Config & Discovery
// ============================================================

const MONITORING_CONFIG_PATH = require('path').join(
  process.env.AEE_DB_PATH ? require('path').dirname(process.env.AEE_DB_PATH) : '/var/lib/quox',
  'monitoring-config.json'
);

function loadMonitoringConfig() {
  try {
    if (require('fs').existsSync(MONITORING_CONFIG_PATH)) {
      return JSON.parse(require('fs').readFileSync(MONITORING_CONFIG_PATH, 'utf8'));
    }
  } catch { /* ignore */ }
  return {};
}

function saveMonitoringConfig(config) {
  try {
    require('fs').writeFileSync(MONITORING_CONFIG_PATH, JSON.stringify(config, null, 2));
  } catch (err) {
    console.error('[Monitoring] Failed to save config:', err.message);
  }
}

// Known service defaults — where to look if not configured
const MONITORING_DEFAULTS = {
  prometheus: { url: process.env.PROMETHEUS_URL || '', healthPath: '/api/v1/status/buildinfo' },
  'uptime-kuma': { url: process.env.UPTIME_KUMA_URL || '', healthPath: '/api/entry-page' },
  proxmox: { url: process.env.PROXMOX_URL || '', healthPath: '/api2/json/version', token: process.env.PROXMOX_API_TOKEN || '' },
};

// VAULT-INTEG P3: the 'proxmox' entry above is env-only. resolveProxmoxCredentialDefaults()
// resolves the org's 'proxmox' vault credential first (for the 'atlas' agent — HYPERION,
// the Proxmox specialist, mirroring wazuhCredentials.js's 'argus' pattern), falling back
// to the static env-derived defaults above only when the vault has nothing (or the
// resolver throws, e.g. a lease-blocked credential — never silently swallow a lease block).
async function resolveProxmoxCredentialDefaults(orgId) {
  try {
    const resolved = await resolveCredentialForAgent(orgId, 'atlas', 'proxmox');
    const { url, token, tlsFingerprint } = resolveProxmoxConnection(resolved);
    return { url: url || MONITORING_DEFAULTS.proxmox.url, token: token || MONITORING_DEFAULTS.proxmox.token, tlsFingerprint };
  } catch (err) {
    console.warn('[Monitoring] Proxmox vault credential resolution failed, using env fallback:', err.message);
    return { url: MONITORING_DEFAULTS.proxmox.url, token: MONITORING_DEFAULTS.proxmox.token };
  }
}

/**
 * GET /api/v1/monitoring/config
 * Returns saved monitoring service URLs for all services.
 */
app.get('/api/v1/monitoring/config', requireAuth({ required: false }), (req, res) => {
  const saved = loadMonitoringConfig();
  const config = {};
  for (const [svc, defaults] of Object.entries(MONITORING_DEFAULTS)) {
    config[svc] = { url: saved[svc]?.url || defaults.url, configured: !!saved[svc]?.url };
    // Multi-page support: return statusPages array (backwards-compat with single statusPageSlug)
    if (saved[svc]?.statusPages?.length) {
      config[svc].statusPages = saved[svc].statusPages;
      config[svc].statusPageSlug = saved[svc].statusPages[0].slug; // compat
    } else if (saved[svc]?.statusPageSlug) {
      config[svc].statusPages = [{ slug: saved[svc].statusPageSlug, label: saved[svc].statusPageSlug }];
      config[svc].statusPageSlug = saved[svc].statusPageSlug;
    }
  }
  // Include Grafana (managed by its own config)
  config.grafana = { url: getGrafanaUrl(), configured: true };
  res.json({ success: true, services: config });
});

/**
 * PUT /api/v1/monitoring/config/:service
 * Save a monitoring service URL. Persisted to disk.
 */
app.put('/api/v1/monitoring/config/:service', requireAuth({ required: true }), requireInstanceAdminMw, (req, res) => {
  const { service } = req.params;
  const { url } = req.body;
  if (!url || typeof url !== 'string') return res.status(400).json({ success: false, error: 'url is required' });
  try { new URL(url); } catch { return res.status(400).json({ success: false, error: 'Invalid URL format' }); }

  if (service === 'grafana') {
    setGrafanaUrl(url);
    return res.json({ success: true, service: 'grafana', url: getGrafanaUrl() });
  }

  const config = loadMonitoringConfig();
  const existing = config[service] || {};
  config[service] = { ...existing, url, updatedAt: new Date().toISOString() };
  // Store API token if provided (Proxmox)
  if (req.body.token) config[service].token = req.body.token;
  // Store status page(s) for Uptime Kuma
  if (req.body.statusPageSlug) {
    const slug = req.body.statusPageSlug;
    const label = req.body.statusPageLabel || slug;
    const pages = config[service].statusPages || [];
    // Migrate old single slug if present
    if (!pages.length && config[service].statusPageSlug && config[service].statusPageSlug !== slug) {
      pages.push({ slug: config[service].statusPageSlug, label: config[service].statusPageSlug });
    }
    // Add if not already present
    if (!pages.find(p => p.slug === slug)) {
      pages.push({ slug, label });
    }
    config[service].statusPages = pages;
    config[service].statusPageSlug = pages[0]?.slug; // compat
  }
  saveMonitoringConfig(config);
  auditOp('ops.monitoring.config.updated', { service: req.params.service });
  res.json({ success: true, service, url });
});

/**
 * DELETE /api/v1/monitoring/config/:service/status-page/:slug
 * Remove a status page from the Uptime Kuma config.
 */
app.delete('/api/v1/monitoring/config/:service/status-page/:slug', requireAuth({ required: true }), requireInstanceAdminMw, (req, res) => {
  const { service, slug } = req.params;
  const config = loadMonitoringConfig();
  if (!config[service]?.statusPages) return res.status(404).json({ success: false, error: 'No status pages configured' });
  config[service].statusPages = config[service].statusPages.filter(p => p.slug !== slug);
  config[service].statusPageSlug = config[service].statusPages[0]?.slug || null;
  saveMonitoringConfig(config);
  res.json({ success: true, remaining: config[service].statusPages });
});

/**
 * POST /api/v1/monitoring/discover
 * Probe known monitoring service URLs and return which are reachable.
 */
app.post('/api/v1/monitoring/discover', requireAuth({ required: false }), async (req, res) => {
  const saved = loadMonitoringConfig();
  const results = {};

  // Probe each service
  const discoverOrgId = (req.user && req.user.org_id) || 'system';
  for (const [svc, staticDefaults] of Object.entries(MONITORING_DEFAULTS)) {
    // VAULT-INTEG P3: proxmox resolves its url/token vault-first per request
    // (org-scoped credential), env fallback — see resolveProxmoxCredentialDefaults().
    const defaults = svc === 'proxmox' ? await resolveProxmoxCredentialDefaults(discoverOrgId) : staticDefaults;
    const url = saved[svc]?.url || defaults.url;
    const healthUrl = url.replace(/\/+$/, '') + (staticDefaults.healthPath);
    try {
      // Use https.request for self-signed certs (Proxmox)
      if (healthUrl.startsWith('https:')) {
        const apiToken = saved[svc]?.token || defaults.token || '';
        const httpsOpts = { rejectUnauthorized: false, timeout: 5000 };
        // DEVFLEET-A2: proxmox shares the pinned agent with the REST read client.
        if (svc === 'proxmox') httpsOpts.agent = require('./lib/proxmoxApi.js').getPveAgent(defaults.tlsFingerprint);
        if (apiToken) httpsOpts.headers = { Authorization: `PVEAPIToken=${apiToken}` };
        const data = await new Promise((resolve, reject) => {
          const req = https.get(healthUrl, httpsOpts, (resp) => {
            let body = '';
            resp.on('data', c => body += c);
            resp.on('end', () => {
              // 401 = reachable but needs auth
              if (resp.statusCode === 401) return resolve({ _needsAuth: true });
              if (resp.statusCode >= 400) return reject(new Error(`HTTP ${resp.statusCode}`));
              try { resolve(JSON.parse(body)); } catch { resolve(null); }
            });
          });
          req.on('error', reject);
          req.on('timeout', () => { req.destroy(); reject(new Error('Connection timed out')); });
        });
        if (data?._needsAuth) {
          results[svc] = { url, reachable: true, needsAuth: true, configured: !!saved[svc]?.url };
        } else {
          results[svc] = { url, reachable: true, configured: !!saved[svc]?.url, data };
        }
      } else {
        const resp = await fetch(healthUrl, { signal: AbortSignal.timeout(5000) });
        results[svc] = { url, reachable: resp.ok, status: resp.status, configured: !!saved[svc]?.url };
        if (resp.ok) {
          try { results[svc].data = await resp.json(); } catch { /* not JSON */ }
        }
        // Include saved status page slug for Uptime Kuma
        if (svc === 'uptime-kuma' && saved[svc]?.statusPageSlug) {
          results[svc].statusPageSlug = saved[svc].statusPageSlug;
        }
      }
    } catch (err) {
      results[svc] = { url, reachable: false, error: err.message, configured: !!saved[svc]?.url };
    }
  }

  // Grafana (uses its own config)
  try {
    const grafanaUrl = getGrafanaUrl();
    const resp = await fetch(`${grafanaUrl}/api/health`, { signal: AbortSignal.timeout(5000) });
    const data = resp.ok ? await resp.json() : null;
    results.grafana = { url: grafanaUrl, reachable: resp.ok, status: resp.status, configured: true, data };
  } catch (err) {
    results.grafana = { url: getGrafanaUrl(), reachable: false, error: err.message, configured: true };
  }

  res.json({ success: true, services: results });
});

/**
 * POST /api/v1/monitoring/test
 * Test connectivity to an arbitrary URL for a specific service type.
 */
app.post('/api/v1/monitoring/test', requireAuth({ required: false }), async (req, res) => {
  const { url, service } = req.body;
  if (!url) return res.status(400).json({ success: false, error: 'url is required' });

  const healthPaths = {
    grafana: '/api/health',
    prometheus: '/api/v1/status/buildinfo',
    'uptime-kuma': '/api/entry-page',
    proxmox: '/api2/json/version',
  };

  // If a statusPageSlug is provided, test that specific status page
  const statusPageSlug = req.body.statusPageSlug;
  let healthPath;
  if (statusPageSlug && service === 'uptime-kuma') {
    healthPath = `/api/status-page/${statusPageSlug}`;
  } else {
    healthPath = healthPaths[service] || '/health';
  }
  const targetUrl = `${url.replace(/\/+$/, '')}${healthPath}`;
  try {
    // Use https.request for self-signed certs (Proxmox, etc.)
    const fetchOpts = { signal: AbortSignal.timeout(8000) };
    if (targetUrl.startsWith('https:')) {
      // Use node https.get for self-signed cert support
      // Include API token if provided (Proxmox auth verification)
      const httpsOpts = { rejectUnauthorized: false, timeout: 8000 };
      const apiToken = req.body.token;
      if (apiToken && service === 'proxmox') {
        httpsOpts.headers = { Authorization: `PVEAPIToken=${apiToken}` };
      }
      const result = await new Promise((resolve, reject) => {
        const req = https.get(targetUrl, httpsOpts, (resp) => {
          let body = '';
          resp.on('data', c => body += c);
          resp.on('end', () => {
            let data = null;
            try { data = JSON.parse(body); } catch { /* not JSON */ }
            // 401 = reachable but needs auth (e.g. Proxmox API token required)
            if (resp.statusCode === 401) {
              return resolve({ success: true, needsAuth: true, url, data });
            }
            if (resp.statusCode >= 400) return reject(new Error(`HTTP ${resp.statusCode}`));
            resolve({ success: true, url, data });
          });
        });
        req.on('error', reject);
        req.on('timeout', () => { req.destroy(); reject(new Error('Connection timed out')); });
      });
      return res.json(result);
    }
    const resp = await fetch(targetUrl, fetchOpts);
    // 401 = reachable but needs auth
    if (resp.status === 401) {
      return res.json({ success: true, needsAuth: true, url });
    }
    if (!resp.ok) return res.json({ success: false, error: `HTTP ${resp.status}`, url });
    const data = await resp.json().catch(() => null);
    res.json({ success: true, url, data });
  } catch (err) {
    res.json({ success: false, error: err.message, url });
  }
});

/**
 * GET /api/v1/monitoring/proxy/:service/*
 * Generic proxy for monitoring services. Routes requests through the collector
 * to avoid CORS issues and keep service URLs server-side.
 */
app.all('/api/v1/monitoring/proxy/:service/*', requireServiceOrUserAuth(), async (req, res) => {
  const { service } = req.params;
  // PVE-PROXY: this proxy injects a privileged PVEAPIToken for the 'proxmox'
  // service and forwards req.method verbatim to the upstream. It must stay
  // read-only — reject any write method before the privileged token is ever
  // attached or forwarded.
  if (service === 'proxmox' && req.method !== 'GET' && req.method !== 'HEAD') {
    return res.status(405).json({ success: false, error: 'method_not_allowed', detail: 'proxmox monitoring proxy is read-only' });
  }
  const saved = loadMonitoringConfig();
  // VAULT-INTEG P3: proxmox resolves its url/token vault-first (org-scoped
  // credential), env fallback — see resolveProxmoxCredentialDefaults().
  const proxyOrgId = (req.user && req.user.org_id) || 'system';
  const defaults = service === 'proxmox' ? await resolveProxmoxCredentialDefaults(proxyOrgId) : MONITORING_DEFAULTS[service];
  const serviceUrl = saved[service]?.url || defaults?.url;
  if (!serviceUrl) return res.status(404).json({ success: false, error: `Unknown service: ${service}` });

  // Build target URL: strip the proxy prefix, keep the rest
  const proxyPrefix = `/api/v1/monitoring/proxy/${service}`;
  const targetPath = req.originalUrl.replace(proxyPrefix, '').replace(/^\/collector/, '');
  const targetUrl = `${serviceUrl.replace(/\/+$/, '')}${targetPath}`;

  try {
    // Use https.request for self-signed certs
    if (targetUrl.startsWith('https:')) {
      const apiToken = saved[service]?.token || defaults?.token || '';
      const data = await new Promise((resolve, reject) => {
        const opts = require('url').parse(targetUrl);
        opts.rejectUnauthorized = false;
        if (service === 'proxmox') opts.agent = require('./lib/proxmoxApi.js').getPveAgent(defaults?.tlsFingerprint);
        opts.timeout = 15000;
        opts.method = req.method;
        opts.headers = { Accept: 'application/json' };
        if (apiToken) opts.headers.Authorization = `PVEAPIToken=${apiToken}`;
        const proxyReq = https.request(opts, (proxyRes) => {
          let body = '';
          proxyRes.on('data', c => body += c);
          proxyRes.on('end', () => {
            res.status(proxyRes.statusCode);
            try { res.json(JSON.parse(body)); } catch { res.send(body); }
          });
        });
        proxyReq.on('error', reject);
        proxyReq.on('timeout', () => { proxyReq.destroy(); reject(new Error('Connection timed out')); });
        proxyReq.end();
      });
      return;
    }

    // HTTP services — use fetch
    const resp = await fetch(targetUrl, {
      method: req.method,
      headers: { Accept: 'application/json' },
      signal: AbortSignal.timeout(15000),
    });
    const contentType = resp.headers.get('content-type') || '';
    if (contentType.includes('json')) {
      const data = await resp.json();
      res.status(resp.status).json(data);
    } else {
      const text = await resp.text();
      res.status(resp.status).send(text);
    }
  } catch (err) {
    res.status(502).json({ success: false, error: err.message });
  }
});

/**
 * GET /api/v1/proxmox/resolve?name=<vm name>   (DEVFLEET-A2)
 * Name -> {vmid,node,type,status} from the live /cluster/resources, over the
 * Proxmox REST API with the caller's org vault credential. Authed (default-deny
 * gate + requireAuth); org always comes from the verified caller, never from
 * the query. Errors are errors: not configured 503, upstream failure 502,
 * unknown name 404, ambiguous 409 with candidates.
 */
app.get('/api/v1/proxmox/resolve', requireAuth(), async (req, res) => {
  const name = typeof req.query.name === 'string' ? req.query.name.trim() : '';
  if (!name) return res.status(400).json({ success: false, error: 'missing_name' });
  const orgId = req.user && req.user.org_id;
  if (!orgId) return res.status(403).json({ success: false, error: 'org_required' });
  try {
    const { pveGet } = require('./lib/proxmoxApi.js');
    const { resolveVmFromResources } = require('./lib/toolExecutors/proxmox.js');
    const resources = await pveGet('/cluster/resources', { type: 'vm' }, { orgId });
    const out = resolveVmFromResources(resources, name);
    if (out.success) return res.json(out);
    return res.status(out.error === 'ambiguous' ? 409 : 404).json(out);
  } catch (err) {
    const code = err && err.code;
    if (code === 'not_configured') return res.status(503).json({ success: false, error: 'proxmox_not_configured' });
    if (code === 'lease_blocked') return res.status(403).json({ success: false, error: 'lease_blocked' });
    return res.status(502).json({ success: false, error: code || 'proxmox_error', detail: err && err.message });
  }
});

// ============================================================
// Third-Party Plugin Gateway (Phase 1)
// ============================================================

/**
 * GET /api/public/spatial/w/:code — Unauthenticated public VOX share lookup.
 *
 * This is the ONLY public surface for the spatial plugin. It drives the public
 * /w/:code share page (a delivery driver, an external recipient — no Quox
 * account). It proxies the backend's public read, which returns SOLELY
 * 'public'-tier fields; an 'account'-tier code yields 403 account_required
 * (the page prompts sign-in) and a 'private'/absent code yields 404. The
 * spatial backend stays loopback-bound — no org context, no gateway secret,
 * and no account/private data can ever cross this route. Per-IP rate-limited.
 */
app.get('/api/public/spatial/w/:code', spatialPublicLimiter, async (req, res) => {
  const backend = getPluginBackend('spatial');
  if (!backend) return res.status(503).json({ error: 'spatial_unavailable' });
  const code = String(req.params.code || '');
  // VOX display form is base36 symbols + optional dashes; reject early (the
  // backend re-validates the check symbol — this is just defense in depth).
  if (!/^[0-9A-Za-z-]{1,64}$/.test(code)) {
    return res.status(400).json({ error: 'invalid_code' });
  }
  try {
    const upstream = await fetch(`${backend.url}/w/${encodeURIComponent(code)}`, {
      method: 'GET',
      headers: { Accept: 'application/json' },
      signal: AbortSignal.timeout(10_000),
    });
    const body = await upstream.text();
    res.status(upstream.status);
    res.setHeader('content-type', upstream.headers.get('content-type') || 'application/json');
    return res.send(body);
  } catch (e) {
    return res.status(502).json({ error: 'spatial_backend_unreachable' });
  }
});

/**
 * ALL /api/v1/plugins/:pluginId/* — Proxy to plugin backend container
 * Plugin backends register via admin endpoint and join quox-network.
 *
 * LICENSE-ENFORCE LE-3f: server-enforced entitlement gate. Only user-
 * originated requests (req.user present, from the JWT/qmcp_* branches of
 * requireServiceOrUserAuth()) are gated on org entitlement — a pure
 * INTERNAL_SERVICE_KEY call (req.service, no req.user/org context) is an
 * internal-to-internal call already inside the trust boundary and bypasses
 * this check, same as auth's LICENSE_GOVERNED_PLUGINS already makes
 * ungoverned/custom-upload plugins pass with no universe knowledge needed
 * here.
 */
app.all('/api/v1/plugins/:pluginId/*', requireServiceOrUserAuth(), async (req, res) => {
  const { pluginId } = req.params;
  const backend = getPluginBackend(pluginId);
  if (!backend) return res.status(404).json({ error: `Plugin backend not registered: ${pluginId}` });

  // LE-AUDIT HIGH: a user-originated request MUST be licensed. Previously a
  // user token with org_id=null (a signed-up user not joined to any org)
  // skipped the check entirely and reached the backend ungated. Only pure
  // service-key internal calls (no req.user) bypass; any req.user without an
  // org_id is denied, not waved through.
  if (req.user) {
    if (!req.user.org_id) {
      return res.status(402).json({ error: 'LICENSE_REQUIRED', plugin: pluginId, reason: 'no_org_context' });
    }
    const licensed = await isPluginLicensedForOrg(req.user.org_id, pluginId);
    if (!licensed) {
      return res.status(402).json({ error: 'LICENSE_REQUIRED', plugin: pluginId });
    }
  }

  await proxyToPlugin(req, res, pluginId);
});

// FND_01M4SZ7NNV4NZ57ZM6J34NZ57Z: these three routes touch INSTANCE-WIDE state
// (process-wide PLUGIN_BACKENDS, global tool maps, containers). register/delete
// require an instance admin; ensure derives image/port/healthPath from the
// caller's own org install and ignores the request body. See lib/pluginBackendAdmin.js.
const _pluginBackendHandlers = createPluginBackendHandlers({
  isHumanAdmin,
  requireAdminRole,
  getPluginBackend,
  registerPluginBackend,
  unregisterPluginBackend,
  unregisterPluginTools: (pluginId) => unregisterPluginTools(pluginId, TOOL_DEFS, AGENT_TOOLS),
  registerPluginTools: (pluginId, tools) => registerPluginTools(pluginId, tools, TOOL_DEFS, AGENT_TOOLS),
  lifecycle: pluginBackendLifecycle,
  auditOp,
  // SPATIAL-W4: tool registrations live in memory and die with the collector;
  // ensure fires on every activation, so it is the re-registration point.
  // Absence of /tools.json is a backend without tools, never an ensure failure.
  loadTools: async (pluginId, url) => {
    let toolsRegistered = 0;
    try {
      const toolsRes = await fetch(`${url}/tools.json`, { signal: AbortSignal.timeout(5000) });
      if (toolsRes.ok) {
        const toolsBody = await toolsRes.json().catch(() => null);
        if (toolsBody && Array.isArray(toolsBody.tools) && toolsBody.tools.length) {
          const reg = registerPluginTools(pluginId, toolsBody.tools, TOOL_DEFS, AGENT_TOOLS);
          toolsRegistered = reg.registered || 0;
          auditOp('ops.plugin.tools.registered', { plugin_id: pluginId, tool_count: toolsRegistered, via: 'ensure' });
        }
      }
    } catch (toolErr) {
      console.log(`[PluginGateway] ${pluginId} exposes no tools.json (${toolErr.message}), skipping tool registration`);
    }
    return toolsRegistered;
  },
  // QN-C: RepoBrain index notifications (non-blocking, non-fatal)
  onRegistered: (pluginId) => {
    if (!process.env.REPOBRAIN_URL) return;
    fetch(`${process.env.REPOBRAIN_URL}/api/targets`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        target_id: `plugin-${pluginId}`,
        source_type: 'local_path',
        source_config: { path: '/source/quox-dashboard' },
        description: `Plugin: ${pluginId}`,
      }),
    }).then(() => console.log(`[Nucleus] Indexed plugin ${pluginId}`))
      .catch(e => console.log(`[Nucleus] Could not index plugin ${pluginId}:`, e.message));
  },
  onUnregistered: (pluginId) => {
    if (!process.env.REPOBRAIN_URL) return;
    fetch(`${process.env.REPOBRAIN_URL}/api/targets/plugin-${pluginId}`, { method: 'DELETE' })
      .then(() => console.log(`[Nucleus] Removed plugin ${pluginId} from index`))
      .catch(e => console.log(`[Nucleus] Could not remove plugin ${pluginId}:`, e.message));
  },
});

