/**
 * POST /api/v1/ward/witness — anchor an EXTERNAL payload hash into a WARD
 * chain (SPATIAL-W5). The generic evidence door: plugin backends keep their
 * own hash chains and an org-authed caller anchors chain tips here, making
 * external event logs tamper-evident without sharing service keys.
 * Body: { chainId, sourceId, payloadHash, sourceTs?, tags? }.
 */
app.post('/api/v1/ward/witness', toolLimiter, requireServiceOrUserAuth(), async (req, res) => {
  const { chainId, sourceId, payloadHash, sourceTs, tags } = req.body || {};
  // AUDIT CRITICAL: chainId was caller-chosen — an org-A user could witness
  // forged entries into org-B's chain or the CORE audit chain
  // (ward:org/quox/env/production). Confine external witnesses to the plugin
  // namespace AND the caller's own org segment, derived from the verified JWT:
  //   ward:plugin/<plugin>/org/<callerOrg>[/...]
  // This blocks the core `ward:org/...` audit chains entirely and prevents
  // cross-org anchoring.
  const callerOrg = req.user?.org_id;
  if (!callerOrg) {
    return res.status(403).json({ error: 'org_context_required' });
  }
  const scopeOk = typeof chainId === 'string'
    && /^ward:plugin\/[a-z0-9-]{1,64}\/org\//.test(chainId)
    && chainId.split('/org/')[1]?.split('/')[0] === callerOrg;
  if (!scopeOk) {
    return res.status(403).json({
      error: 'chain_scope_denied',
      detail: `chainId must match ward:plugin/<plugin>/org/${callerOrg}`,
    });
  }
  if (!chainId || typeof chainId !== 'string' || chainId.length > 200) {
    return res.status(400).json({ error: 'chainId required' });
  }
  if (!sourceId || typeof sourceId !== 'string' || sourceId.length > 200) {
    return res.status(400).json({ error: 'sourceId required' });
  }
  if (!/^[0-9a-f]{64}$/.test(payloadHash || '')) {
    return res.status(400).json({ error: 'payloadHash must be sha256 hex' });
  }
  try {
    const ward = await wardApiModule.getWardService?.() || (await import('../ward/index.js'));
    const entry = ward.witness({
      chainId,
      sourceKind: 'EXTERNAL',            // never caller-controlled
      sourceId,
      payloadHash,
      sourceTs: sourceTs || new Date().toISOString(),
      tags: Array.isArray(tags) ? tags.slice(0, 8).map(String) : [],
      scope: `external witness via api (org=${req.user?.org_id || 'unknown'})`,
    });
    if (!entry) return res.json({ success: true, duplicate: true });
    auditOp('ops.ward.external.witnessed', { chain_id: chainId, source_id: sourceId, org_id: req.user?.org_id });
    res.json({ success: true, entryId: entry.id, chainId });
  } catch (err) {
    res.status(500).json({ error: 'witness_failed', detail: err.message });
  }
});

