// ============================================================
// Monitoring Data Cache (server-side persistence)
// ============================================================

const MONITORING_CACHE_PATH = require('path').join(
  process.env.AEE_DB_PATH ? require('path').dirname(process.env.AEE_DB_PATH) : '/var/lib/quox',
  'monitoring-cache.json'
);

function loadMonitoringCache() {
  try {
    if (require('fs').existsSync(MONITORING_CACHE_PATH)) {
      return JSON.parse(require('fs').readFileSync(MONITORING_CACHE_PATH, 'utf8'));
    }
  } catch { /* ignore */ }
  return {};
}

function saveMonitoringCache(cache) {
  try {
    require('fs').writeFileSync(MONITORING_CACHE_PATH, JSON.stringify(cache, null, 2));
  } catch (err) {
    console.error('[Monitoring] Failed to save cache:', err.message);
  }
}

/**
 * GET /api/v1/monitoring/cache/:service
 * Returns the last cached scan data for a monitoring service.
 * Used by frontends to show data instantly before live refresh completes.
 */
app.get('/api/v1/monitoring/cache/:service', requireServiceOrUserAuth(), (req, res) => {
  const { service } = req.params;
  const cache = loadMonitoringCache();
  const cached = cache[service];
  if (cached) {
    res.json({ success: true, cached: true, ...cached });
  } else {
    res.json({ success: false, cached: false, error: 'No cached data' });
  }
});

/**
 * PUT /api/v1/monitoring/cache/:service
 * Store scan results for a monitoring service.
 * Frontend pushes scan results here after each successful refresh.
 */
app.put('/api/v1/monitoring/cache/:service', requireServiceOrUserAuth(), (req, res) => {
  const { service } = req.params;
  const { data } = req.body;
  if (!data) return res.status(400).json({ success: false, error: 'data is required' });

  const cache = loadMonitoringCache();
  cache[service] = {
    data,
    scannedAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
  saveMonitoringCache(cache);
  res.json({ success: true, service, scannedAt: cache[service].scannedAt });
});

// ============================================================
// Uptime Kuma — Server-side fetch + cache per slug
// ============================================================

/**
 * Fetch Kuma status page + heartbeat server-side, cache result.
 * @param {string} slug - Status page slug
 * @returns {Promise<object>} Combined status data
 */
async function fetchKumaStatus(slug) {
  const saved = loadMonitoringConfig();
  const defaults = MONITORING_DEFAULTS['uptime-kuma'];
  const baseUrl = (saved['uptime-kuma']?.url || defaults?.url || '').replace(/\/+$/, '');
  if (!baseUrl) return { success: false, error: 'Uptime Kuma not configured' };

  const [pageResp, heartbeatResp] = await Promise.all([
    fetch(`${baseUrl}/api/status-page/${slug}`, { signal: AbortSignal.timeout(10000) }),
    fetch(`${baseUrl}/api/status-page/heartbeat/${slug}`, { signal: AbortSignal.timeout(10000) }),
  ]);

  if (!pageResp.ok) throw new Error(`Status page ${slug}: HTTP ${pageResp.status}`);
  if (!heartbeatResp.ok) throw new Error(`Heartbeat ${slug}: HTTP ${heartbeatResp.status}`);

  const pageData = await pageResp.json();
  const heartbeatData = await heartbeatResp.json();

  // Build monitor list from heartbeat
  const heartbeatList = heartbeatData.heartbeatList || {};
  const uptimeList = heartbeatData.uptimeList || {};
  const monitors = Object.entries(heartbeatList).map(([monitorId, heartbeats]) => {
    const latest = heartbeats[heartbeats.length - 1] || {};
    return {
      id: parseInt(monitorId),
      status: latest.status,
      ping: latest.ping,
      message: latest.msg,
      time: latest.time,
      uptime24h: ((uptimeList[monitorId]?.['24'] || 0) * 100).toFixed(2),
      uptime30d: ((uptimeList[monitorId]?.['720'] || 0) * 100).toFixed(2),
    };
  });

  // Enrich with names from status page groups
  const publicGroupList = pageData.publicGroupList || [];
  const nameMap = new Map();
  publicGroupList.forEach(group => {
    (group.monitorList || []).forEach(m => {
      nameMap.set(m.id, { name: m.name, type: m.type, group: group.name });
    });
  });
  const enriched = monitors.map(m => ({ ...m, ...(nameMap.get(m.id) || {}) }));

  const up = enriched.filter(m => m.status === 1);
  const down = enriched.filter(m => m.status === 0);
  const pending = enriched.filter(m => m.status === 2);
  const maintenance = enriched.filter(m => m.status === 3);

  return {
    success: true,
    slug,
    title: pageData.config?.title || 'Uptime Kuma',
    description: pageData.config?.description || '',
    monitors: enriched,
    groups: publicGroupList,
    summary: {
      total: enriched.length,
      up: up.length,
      down: down.length,
      pending: pending.length,
      maintenance: maintenance.length,
    },
  };
}

/**
 * GET /api/v1/monitoring/uptime-kuma/status/:slug
 * Returns cached status data for a Kuma status page.
 * Query params:
 *   ?refresh=true  — fetch fresh data, update cache, return new data
 *   (default)      — return cached data if available, else fetch fresh
 */
app.get('/api/v1/monitoring/uptime-kuma/status/:slug', requireServiceOrUserAuth(), async (req, res) => {
  const { slug } = req.params;
  const wantRefresh = req.query.refresh === 'true';
  const cacheKey = `uptime-kuma:${slug}`;
  const cache = loadMonitoringCache();
  const cached = cache[cacheKey];

  // If we have cached data and no refresh requested, return it
  if (cached && !wantRefresh) {
    return res.json({ success: true, cached: true, scannedAt: cached.scannedAt, ...cached.data });
  }

  // Fetch fresh data
  try {
    const data = await fetchKumaStatus(slug);
    const now = new Date().toISOString();
    cache[cacheKey] = { data, scannedAt: now, updatedAt: now };
    saveMonitoringCache(cache);
    res.json({ success: true, cached: false, scannedAt: now, ...data });
  } catch (err) {
    // On error, return stale cache if available
    if (cached) {
      return res.json({ success: true, cached: true, stale: true, scannedAt: cached.scannedAt, error: err.message, ...cached.data });
    }
    res.json({ success: false, error: err.message });
  }
});

/**
 * POST /api/v1/monitoring/uptime-kuma/refresh
 * Refresh all configured status pages in the background.
 * Returns immediately with acknowledgement.
 */
app.post('/api/v1/monitoring/uptime-kuma/refresh', requireServiceOrUserAuth(), async (req, res) => {
  const config = loadMonitoringConfig();
  const kumaConfig = config['uptime-kuma'];
  const pages = kumaConfig?.statusPages || [];
  if (kumaConfig?.statusPageSlug && !pages.length) {
    pages.push({ slug: kumaConfig.statusPageSlug, label: kumaConfig.statusPageSlug });
  }

  res.json({ success: true, refreshing: pages.map(p => p.slug) });

  // Refresh in background
  const cache = loadMonitoringCache();
  for (const page of pages) {
    try {
      const data = await fetchKumaStatus(page.slug);
      const now = new Date().toISOString();
      cache[`uptime-kuma:${page.slug}`] = { data, scannedAt: now, updatedAt: now };
    } catch (err) {
      console.warn(`[UptimeKuma] Background refresh failed for ${page.slug}:`, err.message);
    }
  }
  saveMonitoringCache(cache);
});

