/**
 * GET /api/v1/grafana/alerts
 * Proxy alert rules with state categorisation.
 */
app.get('/api/v1/grafana/alerts', requireServiceOrUserAuth(), async (req, res) => {
  try {
    let rules = [];
    try {
      rules = await _grafanaFetch('/api/v1/provisioning/alert-rules');
    } catch {
      try {
        const legacy = await _grafanaFetch('/api/alerts');
        rules = legacy.map(a => ({ title: a.name, state: a.state, dashboardUid: a.dashboardUid, panelId: a.panelId }));
      } catch {
        return res.json({ success: false, error: 'No alerting API available', rules: [], summary: { firing: 0, pending: 0, normal: 0 } });
      }
    }
    const summary = { firing: 0, pending: 0, normal: 0 };
    for (const r of rules) {
      const state = (r.state || r.execErrState || 'normal').toLowerCase();
      if (state === 'firing' || state === 'alerting') summary.firing++;
      else if (state === 'pending') summary.pending++;
      else summary.normal++;
    }
    res.json({
      success: true,
      rules: rules.slice(0, 30).map(r => ({ title: r.title || r.name, state: r.state, folder: r.folderTitle || r.folder })),
      summary,
      count: rules.length,
    });
  } catch (err) {
    res.json({ success: false, error: err.message, rules: [], summary: { firing: 0, pending: 0, normal: 0 } });
  }
});

