/**
 * POST /connectors/:connectorId/tools/:toolName/execute
 * Execute a specific connector tool.
 */
app.post('/connectors/:connectorId/tools/:toolName/execute', toolLimiter, requireServiceOrUserAuth(), async (req, res) => {
  try {
    // Org comes from the verified JWT. requireServiceOrUserAuth sets req.user
    // (org_id/orgId), never req.auth — the old `req.auth?.orgId` read ALWAYS
    // fell through, so every browser call resolved org 'default' and failed
    // credential resolution (found 2026-09-12 driving XView). Body orgId is
    // honoured only for service-key callers; honouring it for a user JWT
    // would be a cross-org credential vector.
    const orgId = req.user?.org_id || req.user?.orgId
      || (req.service ? req.body.orgId : null) || 'default';
    const { connectorId, toolName } = req.params;
    const input = req.body.input || {};
    const context = {
      agentId: req.body.agentId || req.user?.agent_id,
      userId: req.user?.id,
      orgId,
      corr: req.body.corr,
    };

    const result = await executeConnectorTool(orgId, connectorId, toolName, input, context);
    res.json(result);
  } catch (err) {
    console.error('[Connectors] Tool execution failed:', err);
    res.status(500).json({ success: false, error: err.message });
  }
});

// ── Tailscale Webhook Receiver ──
const { verifyWebhookSignature, handleWebhookEvents } = require('./lib/tailscaleWebhook');

app.post('/webhooks/tailscale', express.raw({ type: 'application/json' }), async (req, res) => {
  try {
    const signature = req.headers['tailscale-webhook-signature'];
    const bodyStr = typeof req.body === 'string' ? req.body : req.body.toString('utf8');

    // Parse events first to extract tailnet for org lookup
    let events;
    try {
      events = JSON.parse(bodyStr);
      if (!Array.isArray(events)) events = [events];
    } catch {
      return res.status(400).json({ error: 'Invalid JSON payload' });
    }

    // Resolve orgId from webhook secret lookup — NOT from query param (prevents cross-tenant injection).
    // The webhook secret is stored per-org in the vault alongside the Tailscale API key.
    // For now, use the org from the tailnet field in the event payload matched against configured orgs.
    // If no signature or no matching secret, reject the request.
    const webhookSecret = process.env.TAILSCALE_WEBHOOK_SECRET || '';
    if (!webhookSecret) {
      console.warn('[Tailscale] Webhook received but TAILSCALE_WEBHOOK_SECRET not configured — rejecting');
      return res.status(401).json({ error: 'Webhook secret not configured' });
    }

    if (!verifyWebhookSignature(bodyStr, signature, webhookSecret)) {
      console.warn('[Tailscale] Webhook signature verification failed — rejecting');
      return res.status(401).json({ error: 'Invalid webhook signature' });
    }

    // OrgId derived from env config (not user-controllable query param)
    const orgId = process.env.TAILSCALE_WEBHOOK_ORG_ID || 'default';

    // Process events asynchronously (return 200 immediately)
    res.status(200).json({ received: true, count: events.length });

    // Fire-and-forget event processing
    handleWebhookEvents(events, orgId).catch(err => {
      console.error('[Tailscale] Webhook event processing failed:', err.message);
    });
  } catch (err) {
    console.error('[Tailscale] Webhook handler error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

