// ============================================================================
// STUDY-REV P6.C — QuoxFlow evidence + observations proxy
//
// Bridges the dashboard to quoxflow's /api/evidence and /api/observations
// endpoints so the frontend has a single canonical URL regardless of whether
// quoxflow is internal-network-only.
//
// Dashboard calls:
//   GET /collector/quoxflow/evidence?correlationId=:corr&...
//   GET /collector/quoxflow/observations?correlationId=:corr&...
//
// These endpoints forward to quoxflow with X-Service-Key and return the
// upstream JSON as-is (pass-through proxy).
// ============================================================================

const QUOXFLOW_BASE_URL = process.env.QUOXFLOW_URL || 'http://quoxflow:3200';
const _QF_SERVICE_KEY = process.env.INTERNAL_SERVICE_KEY || '';

/**
 * Build headers for collector → quoxflow service-to-service calls.
 */
function quoxflowServiceHeaders() {
  const h = { 'Content-Type': 'application/json' };
  if (_QF_SERVICE_KEY) h['X-Service-Key'] = _QF_SERVICE_KEY;
  return h;
}

/**
 * Forward a GET request to quoxflow, preserving query params.
 * Returns 502 if the upstream is unreachable or returns a non-JSON response.
 */
async function proxyQuoxflowGet(upstreamPath, queryParams, res, extraHeaders = null) {
  const qs = new URLSearchParams(queryParams).toString();
  const url = `${QUOXFLOW_BASE_URL}${upstreamPath}${qs ? '?' + qs : ''}`;

  // When forwarding a user bearer, send ONLY it — quoxflow's auth middleware
  // checks X-Service-Key BEFORE the JWT, and the service key's synthetic user
  // has no org_id, so sending both silently discards the user's org context.
  const headers = (extraHeaders && extraHeaders.Authorization)
    ? { 'Content-Type': 'application/json', ...extraHeaders }
    : { ...quoxflowServiceHeaders(), ...(extraHeaders || {}) };

  let upstreamRes;
  try {
    upstreamRes = await fetch(url, {
      method: 'GET',
      headers,
      signal: AbortSignal.timeout(10000),
    });
  } catch (err) {
    console.warn(`[QF-Proxy] Upstream unreachable at ${url}: ${err.message}`);
    return res.status(502).json({
      error: 'upstream_unreachable',
      message: `QuoxFlow upstream unreachable: ${err.message}`,
    });
  }

  // Forward upstream status + body
  const contentType = upstreamRes.headers.get('content-type') || '';
  if (!contentType.includes('application/json')) {
    const text = await upstreamRes.text();
    console.warn(`[QF-Proxy] Non-JSON response from ${url}: ${text.slice(0, 120)}`);
    return res.status(502).json({
      error: 'upstream_bad_response',
      message: 'QuoxFlow returned non-JSON response',
    });
  }

  const body = await upstreamRes.json();
  return res.status(upstreamRes.status).json(body);
}

// GET /collector/quoxflow/evidence
// Proxies to quoxflow GET /api/evidence with all query params forwarded.
app.get('/quoxflow/evidence', requireServiceOrUserAuth(), async (req, res) => {
  const allowed = ['corr', 'correlationId', 'envelopeId', 'workflowId', 'executionId', 'type', 'limit', 'offset'];
  const params = {};
  for (const key of allowed) {
    if (req.query[key] != null) params[key] = req.query[key];
  }
  // 2026-08-19: quoxflow runs with QUOXFLOW_ORG_ENFORCEMENT=enforced, and
  // /api/evidence is deliberately NOT on its system-scope allowlist (evidence
  // is tenant data). This proxy sent the service key with no X-Org-Id, so
  // quoxflow refused every call with "X-Org-Id required — service-key callers
  // must supply X-Org-Id on this route".
  //
  // Net effect: `quox governance evidence` returned 403 for a normal logged-in
  // user, with an error blaming service-key callers. The evidence query is the
  // product's headline capability, and it was unreachable from the CLI.
  //
  // quoxflow's own note says to flip enforcement only AFTER the collector
  // callers ship; this caller was missed.
  const scoped = quoxflowScopedHeaders(req);
  if (!scoped) {
    return res.status(400).json({
      error: 'org_context_required',
      message: 'Evidence is tenant-scoped: no organisation context on this request.',
    });
  }
  return proxyQuoxflowGet('/api/evidence', params, res, scoped);
});

// GET /collector/quoxflow/observations
// Proxies to quoxflow GET /api/observations with all query params forwarded.
app.get('/quoxflow/observations', requireServiceOrUserAuth(), async (req, res) => {
  const allowed = ['taskId', 'correlationId', 'workflowId', 'orgId'];
  const params = {};
  for (const key of allowed) {
    if (req.query[key] != null) params[key] = req.query[key];
  }
  // Same defect as /quoxflow/evidence above: observations are tenant data and
  // quoxflow refuses an unscoped service-key read under enforced org scoping.
  const scopedObs = quoxflowScopedHeaders(req);
  if (!scopedObs) {
    return res.status(400).json({
      error: 'org_context_required',
      message: 'Observations are tenant-scoped: no organisation context on this request.',
    });
  }
  return proxyQuoxflowGet('/api/observations', params, res, scopedObs);
});

// ============================================================================
// CLI-COCKPIT — QuoxFlow skill-library (QSKL) read-only proxy
//
// Bridges the CLI/dashboard to quoxflow's /api/quox-skills endpoints (the
// procedural-knowledge Skills/Crystals primitive — see quoxflow
// src/store/quox-skills-store.js + src/api/routes/quox-skills.js).
//
// Dashboard/CLI calls:
//   GET /collector/quoxflow/skills?category=&edition=&agentId=&tag=&limit=&orderBy=&order=&orgId=
//   GET /collector/quoxflow/skills/:id?orgId=
//
// Read-only. Skill WRITES (create, patch, revert, run-tests, archive,
// review-queue approve/reject, promote-draft, rollback) are NOT proxied
// here — those go through quoxflow's governed firewall/promotion path
// directly and are out of scope for this proxy.
// ============================================================================

// quoxflow verifies the SAME JWTs (shared JWT_SECRET) and its quox-skills
// routes take org_id from the JWT, not query params. The collector's service
// key alone carries no org — forward the calling user's bearer so quoxflow
// sees real org context. (Same limitation exists for pure service-key
// callers; they get the service-key behavior unchanged.)
function quoxflowUserAuthHeader(req) {
  const auth = req.headers.authorization;
  if (auth && /^Bearer /i.test(auth)) return { Authorization: auth };
  const cookies = parseCookieHeader(req.headers.cookie);
  if (cookies.access_token) return { Authorization: `Bearer ${cookies.access_token}` };
  return null;
}

/**
 * Org-scoped headers for a quoxflow proxy call, for BOTH caller shapes.
 *
 * quoxflow runs with QUOXFLOW_ORG_ENFORCEMENT=enforced. Tenant-data routes
 * (evidence, observations, approvals, budgets, policies) are deliberately NOT
 * on its system-scope allowlist, so a service-key call with no X-Org-Id is
 * refused with "X-Org-Id required — service-key callers must supply X-Org-Id".
 *
 * A user bearer carries the org already, so forwarding it is enough and is
 * what most routes here do. A SERVICE-KEY caller has no org in its synthetic
 * user, so it must state the org explicitly or quoxflow cannot scope the read.
 * quoxflowUserAuthHeader alone returns null in that case and the call falls
 * back to unscoped service headers, which is exactly the 403.
 *
 * Returns null when there is no way to scope the call, so the route can refuse
 * with a clear reason rather than emit an unscoped read.
 */
function quoxflowScopedHeaders(req) {
  const bearer = quoxflowUserAuthHeader(req);
  if (bearer) return bearer;
  const orgId = resolveLicenceOrgId(req);
  return orgId ? { 'X-Org-Id': orgId } : null;
}

