// POST /collector/quoxflow/triggers/webhooks/fire
// Test-fire a registered webhook by path. Sends an empty POST to /webhooks/:path.
app.post('/quoxflow/triggers/webhooks/fire', requireServiceOrUserAuth(), async (req, res) => {
  const { path } = req.body || {};
  if (!path) {
    return res.status(400).json({ error: 'missing_path', message: 'path is required in request body' });
  }
  const url = `${QUOXFLOW_BASE_URL}/webhooks/${path.replace(/^\//, '')}`;
  let upstreamRes;
  try {
    upstreamRes = await fetch(url, {
      method: 'POST',
      headers: { ...quoxflowServiceHeaders(), 'Content-Type': 'application/json' },
      body: JSON.stringify({ _testFire: true }),
      signal: AbortSignal.timeout(10000),
    });
  } catch (err) {
    console.warn(`[QF-Proxy] Upstream unreachable at ${url}: ${err.message}`);
    return res.status(502).json({
      error: 'upstream_unreachable',
      message: `QuoxFlow upstream unreachable: ${err.message}`,
    });
  }
  const contentType = upstreamRes.headers.get('content-type') || '';
  if (!contentType.includes('application/json')) {
    const text = await upstreamRes.text();
    console.warn(`[QF-Proxy] Non-JSON response from ${url}: ${text.slice(0, 120)}`);
    return res.status(502).json({ error: 'upstream_bad_response', message: 'QuoxFlow returned non-JSON response' });
  }
  const body = await upstreamRes.json();
  return res.status(upstreamRes.status).json(body);
});

// ============================================================================
// Budget CRUD + usage ingestion proxy — P8.B.2
//
// Dashboard calls:
//   GET    /collector/quoxflow/budgets?org_id=…              → list
//   POST   /collector/quoxflow/budgets                       → create
//   GET    /collector/quoxflow/budgets/:id?org_id=…          → fetch
//   PATCH  /collector/quoxflow/budgets/:id                   → update
//   DELETE /collector/quoxflow/budgets/:id                   → delete
//   GET    /collector/quoxflow/budgets/:id/usage?org_id=…    → usage history
//   POST   /collector/quoxflow/budget/usage                  → ingestion (fire-and-forget)
//
// These forward to quoxflow /api/budgets/* and /api/v1/budget/* with X-Service-Key.
// ============================================================================

/**
 * Forward a mutating request (POST/PATCH/DELETE) to quoxflow, preserving body.
 * When extraHeaders carries a user Authorization bearer (see quoxflowUserAuthHeader
 * above), send ONLY that — same rationale as proxyQuoxflowGet: quoxflow's auth
 * middleware checks X-Service-Key before the JWT, and the service key's synthetic
 * user has no org_id, so sending both silently discards the user's org context.
 */
async function proxyQuoxflowMutate(method, upstreamPath, body, res, extraHeaders = null) {
  const url = `${QUOXFLOW_BASE_URL}${upstreamPath}`;
  const headers = (extraHeaders && extraHeaders.Authorization)
    ? { 'Content-Type': 'application/json', ...extraHeaders }
    : { ...quoxflowServiceHeaders(), 'Content-Type': 'application/json', ...(extraHeaders || {}) };
  let upstreamRes;
  try {
    upstreamRes = await fetch(url, {
      method,
      headers,
      body: body != null ? JSON.stringify(body) : undefined,
      signal: AbortSignal.timeout(10000),
    });
  } catch (err) {
    console.warn(`[QF-Proxy] Upstream unreachable at ${url}: ${err.message}`);
    return res.status(502).json({ error: 'upstream_unreachable', message: `QuoxFlow upstream unreachable: ${err.message}` });
  }
  const contentType = upstreamRes.headers.get('content-type') || '';
  if (!contentType.includes('application/json')) {
    const text = await upstreamRes.text();
    console.warn(`[QF-Proxy] Non-JSON response from ${url}: ${text.slice(0, 120)}`);
    return res.status(502).json({ error: 'upstream_bad_response', message: 'QuoxFlow returned non-JSON response' });
  }
  const responseBody = await upstreamRes.json();
  return res.status(upstreamRes.status).json(responseBody);
}

